INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fbe81f4a-ba95-4a4d-b2e4-95719c261ea8', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why should we avoid repeatedly washing raw rice and pulses with large amounts of water before cooking?', 'Frequent vigorous washing leaches out water-soluble micronutrients like thiamine, niacin, and essential minerals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bcbe7a0-f3e2-49e1-b8e3-d2b592e8a2be', 'It dissolves water-soluble vitamins (like Vitamin B complex and C) and minerals, washing them away', true, 'fbe81f4a-ba95-4a4d-b2e4-95719c261ea8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6f0ecbf-28dd-445f-9eed-2f32c495de0b', 'It converts carbohydrates into harmful toxins', false, 'fbe81f4a-ba95-4a4d-b2e4-95719c261ea8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fd25f1d-3c18-4958-a075-a7bf8bb8a001', 'It increases fat content', false, 'fbe81f4a-ba95-4a4d-b2e4-95719c261ea8');
