INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7aa13da-0047-40d7-a998-6b2d61c5399f', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'What physical symptoms are exhibited by a child suffering from Kwashiorkor (protein deficiency)?', 'Severe protein malnutrition leads to hypoalbuminemia causing abdominal edema (pot belly) and depigmented hair.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a795a79b-649c-429a-b3f1-e2ad8170bbea', 'Swollen swollen belly (pot belly), discoloured hair, stunted growth, and skin diseases', true, 'f7aa13da-0047-40d7-a998-6b2d61c5399f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e012087e-2dd8-45e1-b167-985be01e102c', 'Extremely soft bones bending into bow legs', false, 'f7aa13da-0047-40d7-a998-6b2d61c5399f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ebba93e-8d31-4344-8d39-f2733394eaa5', 'Bleeding gums and loose teeth', false, 'f7aa13da-0047-40d7-a998-6b2d61c5399f');
