INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6486038-e208-4f87-ac2a-4cd79f1cc8bd', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'A diet containing excessive fat-rich fried foods, samosas, and sweets over long periods can lead to a condition called:', 'Unburned surplus dietary calories from saturated fats get stored as adipose tissue, resulting in clinical obesity.', NOW()) ON CONFLICT DO NOTHING;
