INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7d7112f-83a7-416c-b39c-0937c9b718c7', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why does our body need roughage (dietary fibre) even though it provides zero energy and no nutrients?', 'Cellulose fibres stimulate intestinal peristaltic contractions, facilitating efficient transit of fecal bolus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3227d5e-beb1-4ef8-93a2-993c72bf10e0', 'It adds bulk to the food, aids normal peristalsis, and helps our body expel undigested waste smoothly', true, 'b7d7112f-83a7-416c-b39c-0937c9b718c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ea896a4-553f-4bb8-a168-3c3aef21e107', 'It fights bacterial infections directly', false, 'b7d7112f-83a7-416c-b39c-0937c9b718c7');
