INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d0675b7-2ee1-407e-9126-25822b776cdc', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Which mineral works in synergy with Vitamin D to maintain mineralized bone density and strong enamel on teeth?', 'Hydroxyapatite crystals of bones and teeth are composed primarily of calcium phosphate complexes.', NOW()) ON CONFLICT DO NOTHING;
