INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5855719-503e-4e3b-9218-5736ad0a052b', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why is drinking 2 to 3 litres of clean water every day essential for human physiological health?', 'Water serves as the biological universal solvent, regulating thermoregulation and renal clearance of toxins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1043ac25-52ce-4d32-8c92-54d1de1f88cb', 'Water absorbs nutrients from food into the bloodstream and helps excrete metabolic wastes as urine and sweat', true, 'b5855719-503e-4e3b-9218-5736ad0a052b');
