INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07d0f948-5acd-42bb-b913-b586c979c28d', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Which symptom specifically characterizes Rickets in growing children?', 'Lack of Vitamin D impairs calcium absorption, leading to defective osteoid mineralization that deforms weight-bearing leg bones.', NOW()) ON CONFLICT DO NOTHING;
