INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cd91926-f8e8-436a-a61a-156a438943f4', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why do athletes and physical labourers require higher amounts of carbohydrate-rich foods compared to sedentary desk workers?', 'Glycolysis of carbohydrate substrates provides the fastest fuel pathway for high-output skeletal muscle work.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0750e029-6bc1-4d3b-a978-bd818101893c', 'Carbohydrates are rapidly broken down into glucose, providing immediate ATP energy for strenuous muscular contractions', true, '3cd91926-f8e8-436a-a61a-156a438943f4');
