INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82804fb7-7a00-4ae6-a8a7-8971bcaeb6ff', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Which pair of food items is predominantly rich in starch?', 'Tubers (potatoes) and cereal grains (rice) store excess photosynthetic energy primarily in the form of amylose/amylopectin starch granules.', NOW()) ON CONFLICT DO NOTHING;
