INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56034959-f951-48cb-8461-79f359633525', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'What is a ''Balanced Diet''?', 'A balanced diet supplies macro and micronutrients in physiological proportions to sustain metabolic requirements without deficits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('163ed6c8-eba6-453c-8435-76af0ea3470c', 'A diet providing all essential nutrients in proper proportions, along with adequate roughage and water for optimal health', true, '56034959-f951-48cb-8461-79f359633525');
