INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1706263-bb16-47c7-bc32-819e8d795a20', 'A diet containing equal weights of butter and sugar', false, '56034959-f951-48cb-8461-79f359633525');
