INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fce8c20e-0a4a-4f39-9c60-b99501866df7', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why does the government mandate the iodization of common edible table salt (NaCl)?', 'Universal salt iodization with potassium iodate is an effective public health intervention preventing iodine deficiency disorders (IDD).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da868847-3012-4dd2-a84c-f895909c7c62', 'To ensure regular microscopic intake of iodine across all populations to prevent goitre and mental impairment in children', true, 'fce8c20e-0a4a-4f39-9c60-b99501866df7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e251437a-5a07-4ed7-81d6-8d3b6d5e06ef', 'To make table salt white in color', false, 'fce8c20e-0a4a-4f39-9c60-b99501866df7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c696434a-18f7-45d0-bd4c-6cf629725660', 'To prevent table salt from absorbing moisture', false, 'fce8c20e-0a4a-4f39-9c60-b99501866df7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('926a648d-f2c1-41c2-980c-51806be82766', 'To improve salt sweetness', false, 'fce8c20e-0a4a-4f39-9c60-b99501866df7');
