INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9304687-3af9-49da-9ea6-95c90e13ff32', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why is deep-frying vegetables at high temperatures considered nutritionally detrimental?', 'Prolonged thermal stress degrades heat-sensitive vitamins (C, B-complex) and generates free fatty acid radicals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('872bb149-8f6d-46b0-81a2-c4cc197bad46', 'High heat oxidizes and destroys delicate vitamins while loading the food with unhealthy oxidized fats', true, 'b9304687-3af9-49da-9ea6-95c90e13ff32');
