INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b5207ba-83fc-4dc7-aa92-9ee4a64e5045', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Hard', 'Why do sailors on ancient long-distance wooden ships historically suffer from loose teeth, joint pain, and bleeding skin lesions after months at sea?', 'Non-perishable ship rations (hardtack, salted meat) lacked fresh produce, inducing severe scorbutic collagen breakdown (James Lind''s trials).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('903c1134-3257-410b-a78e-10eeb0c09a4a', 'Absence of fresh fruits and green vegetables on long voyages resulted in severe nutritional Scurvy (Vitamin C depletion)', true, '0b5207ba-83fc-4dc7-aa92-9ee4a64e5045');
