INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98ef84ee-3b89-4b99-a12b-cf0fb332e381', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Hard', 'A student adds 2 drops of Copper Sulphate and 10 drops of Caustic Soda to a test tube containing crushed soybean powder mixed with water. What sequence of physical observations confirms protein presence?', 'Biuret test: Cu2+ ions coordinate with unprotonated peptide nitrogen atoms in alkaline conditions, forming a violet chelate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d124690a-9920-48bb-bdef-cb1ad940165c', 'The white suspension turns distinct violet/purple after shaking and standing for a few minutes', true, '98ef84ee-3b89-4b99-a12b-cf0fb332e381');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6920883-7ee1-4c30-9039-2a3b5575507d', 'The solution immediately turns deep blue-black', false, '98ef84ee-3b89-4b99-a12b-cf0fb332e381');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1496894-c9b5-483b-a15f-6aa931b1f8d1', 'The test tube gets freezing cold with gas bubbles', false, '98ef84ee-3b89-4b99-a12b-cf0fb332e381');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10cbd6c2-c36a-4487-a662-546f5d15348e', 'A yellow precipitate settles down', false, '98ef84ee-3b89-4b99-a12b-cf0fb332e381');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbbbb671-1516-44cc-ba1f-e685e0e57bb7', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Hard', 'Why are sprouted seeds (like sprouted moong and chana) significantly more nutritious than raw dry seeds?', 'Germination activates endogenous hydrolytic enzymes, deactivating anti-nutrients (phytates) and bio-synthesizing vitamins and bioactive peptides.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a362b1b2-45c3-40d7-9bdd-5546f48b02f6', 'Sprouting triggers enzymatic synthesis of vitamins (especially Vitamin C and B-complex) and converts complex starches into easily digestible nutrients', true, 'bbbbb671-1516-44cc-ba1f-e685e0e57bb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04658a98-4000-4073-b341-93d467456306', 'Sprouting multiplies fat percentage by 100 times', false, 'bbbbb671-1516-44cc-ba1f-e685e0e57bb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8251aec5-c4b3-4d60-b327-70884c57145e', 'Sprouting removes all water content', false, 'bbbbb671-1516-44cc-ba1f-e685e0e57bb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69164d78-8ed2-44fc-b1a2-7c534622306c', 'Sprouted seeds become mineral stones', false, 'bbbbb671-1516-44cc-ba1f-e685e0e57bb7');
