INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('874ab741-6b9f-45d1-884b-36d2760a2d9c', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Easy', 'What is the greatest 4-digit number using the digits 7, 3, 9, and 1 without repetition?', 'Arranging digits in descending order (9 > 7 > 3 > 1) yields the largest possible numeral: 9731.', NOW()) ON CONFLICT DO NOTHING;
