INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56d77ad7-71fe-4747-9427-e7ad38d93c41', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Easy', 'What is the smallest 4-digit number using the digits 5, 0, 8, and 2 without repetition?', 'A 4-digit number cannot start with 0; hence place the smallest non-zero digit (2) first, followed by 0, 5, 8 giving 2058.', NOW()) ON CONFLICT DO NOTHING;
