INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4e70eee-dc82-4081-a9f3-56f1b926d61c', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Easy', 'What is the Roman numeral for 50?', 'In standard Roman numeration: I=1, V=5, X=10, L=50, C=100, D=500, M=1000.', NOW()) ON CONFLICT DO NOTHING;
