INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1b8f931-4d38-4327-a4db-3dfa415cf7df', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Easy', 'How many milligrams (mg) are there in 1 kilogram (kg)?', '1 kg = 1,000 grams; 1 gram = 1,000 mg; therefore 1 kg = 1,000 × 1,000 = 1,000,000 milligrams.', NOW()) ON CONFLICT DO NOTHING;
