INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69389b54-f649-4445-8a66-b0498ba323d0', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Easy', 'How many millilitres (mL) make 1 Litre?', 'The metric prefix ''milli'' denotes one-thousandth (1/1000); hence 1 L = 1000 mL.', NOW()) ON CONFLICT DO NOTHING;
