INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57f9c57d-cdee-4325-b9b0-f9878c2f1605', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'A machine on an average manufactures 2,825 screws a day. How many screws did it produce in the month of January 2024?', 'January has 31 days. Total screws = 2,825 × 31 = 87,575 screws.', NOW()) ON CONFLICT DO NOTHING;
