INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('464b85da-518d-43c5-9d89-2d2e577a3dd4', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'A vessel has 4 litres and 500 mL of curd. In how many glasses, each of 25 mL capacity, can it be filled?', 'Total capacity = 4,500 mL. Number of glasses = 4,500 ÷ 25 = 180 glasses.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cbd07f5-d714-400a-a11c-8ae0514d93e6', '180 glasses', true, '464b85da-518d-43c5-9d89-2d2e577a3dd4');
