INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19bc8401-8fec-4cfb-a1b4-6e063d8ebb99', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'Estimate the product 578 × 161 by rounding off each factor to its greatest place:', '578 rounds to 600 (hundreds place); 161 rounds to 200 (hundreds place). Estimated product = 600 × 200 = 1,20,000.', NOW()) ON CONFLICT DO NOTHING;
