INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3539b072-21e4-4709-be2c-e11916bde3fe', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'To stitch a shirt, 2 m 15 cm cloth is needed. Out of 40 m cloth, how many shirts can be stitched and how much cloth will remain?', 'Cloth per shirt = 215 cm. Total cloth = 4,000 cm. 4000 ÷ 215 = 18 shirts with remainder 130 cm = 1 m 30 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55b5cfae-ba23-4b74-a075-d1d3ffc4bf6f', '18 shirts, 1 m 30 cm remaining', true, '3539b072-21e4-4709-be2c-e11916bde3fe');
