INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0057563c-473d-4d8d-b0f6-b3798619a33b', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'What is the Hindu-Arabic numeral value of the Roman expression LXXIX + XLIV?', 'LXXIX = 70 + 9 = 79. XLIV = 40 + 4 = 44. Sum = 79 + 44 = 123 (CXXIII).', NOW()) ON CONFLICT DO NOTHING;
