INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fa37927-e3f2-4ff5-ae19-087507b9f0cb', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'In the numeral 7,89,34,521, what is the place value and face value of the digit 8?', 'The digit 8 occupies the Ten Lakhs place; its place value is 8 × 10,00,000 = 80,00,000 while its face value is the digit itself (8).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfea98bc-d7fb-4cac-a739-aa95f5d5ef58', 'Place value = 80,00,000 (Eighty Lakhs); Face value = 8', true, '6fa37927-e3f2-4ff5-ae19-087507b9f0cb');
