INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35bd9e47-4bbd-4cb6-9b93-b952330eb207', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'Estimate the sum 5,290 + 17,986 by rounding off to the nearest thousands:', '5,290 rounds to 5,000; 17,986 rounds to 18,000. Sum = 5,000 + 18,000 = 23,000.', NOW()) ON CONFLICT DO NOTHING;
