INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e4eec5b-5b4e-4d1a-9125-a041ccad7b00', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'Write 7,452 in expanded form:', 'Expanded form represents the sum of the products of each digit with its corresponding place value.', NOW()) ON CONFLICT DO NOTHING;
