INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2731d87f-454f-4f5e-b05f-59d6c82b35c4', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'A medicine box contains 2,00,000 tablets each weighing 20 mg. What is the total weight of all tablets in grams and in kilograms?', 'Total weight = 200,000 × 20 mg = 4,000,000 mg = 4,000,000 ÷ 1,000 g = 4,000 g = 4 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ed06bfc-24e2-4f1d-93fc-513308b1777b', '4,000 grams = 4 kg', true, '2731d87f-454f-4f5e-b05f-59d6c82b35c4');
