INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22cdf463-bc00-41bf-a832-8ac4d74632e1', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'How is the number 85,420,109 read in the International Number System?', 'International periods group into Millions (85), Thousands (420), and Units (109).', NOW()) ON CONFLICT DO NOTHING;
