INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68a0b91f-72bd-476e-bbd6-bd5f12daab10', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'What is the Roman numeral for 69?', '69 = 60 + 9 = (50 + 10) + (10 - 1) = LX + IX = LXIX.', NOW()) ON CONFLICT DO NOTHING;
