INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1467a38a-78fe-4a52-b0ab-d13d80949b11', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'Find the difference between the place values of two 7s in the number 57,34,725:', 'First 7 is at Ten Lakhs place (7,00,000); second 7 is at Hundreds place (700). Difference = 7,00,000 - 700 = 6,99,300.', NOW()) ON CONFLICT DO NOTHING;
