INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28687938-2009-4e4a-a789-227a3bc68859', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Hard', 'A student multiplied 7,236 by 65 instead of multiplying by 56. By how much was his answer greater than the correct answer?', 'Difference = 7,236 × (65 - 56) = 7,236 × 9 = 65,124.', NOW()) ON CONFLICT DO NOTHING;
