INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ea0b821-ab33-44b9-a310-58a370cdea1b', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Hard', 'How many total 7-digit numbers exist in all of mathematics?', 'Largest 7-digit number = 99,99,999; Smallest 7-digit number = 10,00,000. Total = (99,99,999 - 10,00,000) + 1 = 90,00,000.', NOW()) ON CONFLICT DO NOTHING;
