INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f21d9e12-92d7-47af-ab48-edf80b97e06c', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Hard', 'A carton holds 24 boxes, and each box contains 15 packets of biscuits. If each biscuit packet costs ₹ 12, what is the total cost of biscuits in 10 such cartons?', 'Packets per carton = 24 × 15 = 360 packets. Total in 10 cartons = 3,600 packets. Cost = 3,600 × 12 = ₹ 43,200.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('712b3848-b8b1-4ddd-9fb7-1f486c169543', '₹ 43,200', true, 'f21d9e12-92d7-47af-ab48-edf80b97e06c');
