INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d035fe9-2b45-40b9-9264-6ed26f04e287', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Hard', 'What is the Roman numeral for 495?', '495 = 400 + 90 + 5 = CD + XC + V = CDXCV.', NOW()) ON CONFLICT DO NOTHING;
