INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db3c3572-a4fd-492e-b5da-8159baa56308', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Easy', 'What is the rhyming scheme and poet of the poem ''A House, A Home'' in Chapter 1?', 'The poem ''A House, A Home'' contrasting physical building materials with loving family life is composed by Lorraine M. Halli.', NOW()) ON CONFLICT DO NOTHING;
