INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0bc620b-21cb-40e1-bb49-57625de6f235', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'Why did the little elf constantly squeak and demand Patrick''s help in Mathematics?', 'The elf exclaimed that elves never needed times tables, addition, or division, forcing Patrick to sit beside him and guide every step.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b4bd62c-69f7-4e0d-ab62-ff5f26c9adb3', 'Elves knew nothing of human timetables, addition, subtraction, fractions, and division', true, 'b0bc620b-21cb-40e1-bb49-57625de6f235');
