INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d340d49-859e-41eb-bab1-d26443a28a71', 'The elf wanted to play video games', false, 'b0bc620b-21cb-40e1-bb49-57625de6f235');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a88e2b6-2c1d-4498-80fb-8d856e2dffd0', 'The math book was written in secret code', false, 'b0bc620b-21cb-40e1-bb49-57625de6f235');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4dc4491-c48e-4b6d-bc12-9ae2775f8a89', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'How did the elf behave when it came to reading Human History?', 'To the elf, human history was an utter mystery, so he ordered Patrick to go to the library and read books aloud to him.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dea70d5e-f241-4251-9eb6-05967170dccf', 'He considered human history ''a mystery'' and shrieked for Patrick to fetch more books from the library and read them aloud', true, 'c4dc4491-c48e-4b6d-bc12-9ae2775f8a89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ac7d410-3928-43d7-a3a3-ee15a3aa1a13', 'He knew everything and finished it in one minute', false, 'c4dc4491-c48e-4b6d-bc12-9ae2775f8a89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19e74053-e96f-42ec-8d78-b377326c3f5d', 'He tore up the history textbook', false, 'c4dc4491-c48e-4b6d-bc12-9ae2775f8a89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc538734-f0ab-4cca-a556-e588e69da8de', 'He fell asleep immediately', false, 'c4dc4491-c48e-4b6d-bc12-9ae2775f8a89');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a13f7a7a-7a7f-43c5-8019-ef5ee42a5fd6', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What real transformation took place in Patrick''s daily habits and attitude by the end of the semester?', 'Patrick developed self-discipline: cleaning his room, doing daily chores, staying cheerful, and developing a completely new positive attitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d60c0bce-044e-4277-ae39-4745d725bf66', 'He became a model kid who cleaned his room, did his chores, stayed cheerful, and never lost his temper', true, 'a13f7a7a-7a7f-43c5-8019-ef5ee42a5fd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6e37b66-ab0b-4ef1-aed0-16cb5daf227d', 'He became lazy and hired more elves', false, 'a13f7a7a-7a7f-43c5-8019-ef5ee42a5fd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bda98f77-5823-4b9e-a2c9-07e91c48431b', 'He dropped out of school to play sports', false, 'a13f7a7a-7a7f-43c5-8019-ef5ee42a5fd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfbc2d0e-50f6-4ddc-ad94-ff348b656858', 'He stopped talking to his teachers', false, 'a13f7a7a-7a7f-43c5-8019-ef5ee42a5fd6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2510979-ad5b-491e-888f-8600f8a0ec37', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What is the fundamental difference between a ''House'' and a ''Home'' as described in the poem ''A House, A Home''?', 'Poet Lorraine M. Halli distinguishes physical inanimate construction (house) from the emotional bond of loving family (home).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58979e32-4b28-41db-9541-7f3a990cecfd', 'A house is made of lifeless brick, stone, and wood; a home is made of loving family members caring selflessly for one another', true, 'b2510979-ad5b-491e-888f-8600f8a0ec37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5356e43-169b-4d26-a211-22e01d1aa421', 'A house has two floors; a home has only one room', false, 'b2510979-ad5b-491e-888f-8600f8a0ec37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9deddaa6-fdaf-4b44-af2c-842de732782e', 'A home has expensive furniture; a house is empty', false, 'b2510979-ad5b-491e-888f-8600f8a0ec37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87db5b91-63e0-41ed-90ca-d4722d145211', 'There is no difference between them', false, 'b2510979-ad5b-491e-888f-8600f8a0ec37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e858697d-3794-4ab7-a1b4-34c3537c45f5', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'Why did the elf slip out quietly through the back door on the last day of the semester?', 'On the 35th day, the semester ended with zero remaining homework; free from his pledge, the elf slipped away quietly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('054dfdfd-d989-491a-aa00-4f312dc2d542', 'There was no more homework left to do, and his contracted promise was fulfilled', true, 'e858697d-3794-4ab7-a1b4-34c3537c45f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10910f60-ac7f-47dc-aef6-d22b865eb277', 'He was terrified of Patrick''s parents', false, 'e858697d-3794-4ab7-a1b4-34c3537c45f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d76d6049-ddff-4ae5-b136-05f4d2ad159f', 'The cat attacked him again', false, 'e858697d-3794-4ab7-a1b4-34c3537c45f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a76ce854-ad96-40aa-ad83-3f6e96ff7483', 'He stole Patrick''s Nintendo console', false, 'e858697d-3794-4ab7-a1b4-34c3537c45f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31d253b6-ae9d-413f-bbf3-fda3f38b0a48', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'Choose the correct synonym for the phrase ''a nagging person'' as depicted by the elf in the story:', 'A ''nag'' is one who persistently annoys, complains, or urges someone to do continuous work.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e9a2ed1-ce7f-49a3-9fc4-d6680d846343', 'A nag', true, '31d253b6-ae9d-413f-bbf3-fda3f38b0a48');
