INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('daf0d0de-6e26-4584-982b-fc96bbe40577', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What figure of speech / literary device is used in the line: ''His face wrinkled like a dishcloth thrown in the hamper''?', 'The explicit comparison using ''like'' between the elf''s wrinkled face and a dishcloth is a Simile.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0887e1be-784e-473d-b2d2-2509f9c3d4c8', 'Simile', true, 'daf0d0de-6e26-4584-982b-fc96bbe40577');
