INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('931630d6-7970-4cb9-b526-69e25589b20f', 'Personification', false, 'daf0d0de-6e26-4584-982b-fc96bbe40577');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbcdcb8e-1666-4164-817f-cfc98158e01f', 'Alliteration', false, 'daf0d0de-6e26-4584-982b-fc96bbe40577');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ecdaec9-fd20-4615-81d5-308b49b365dc', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What moral lesson does the story ''Who Did Patrick''s Homework?'' impart to young learners?', 'The narrative illustrates that self-reliance, diligent effort, and intrinsic motivation create true personal excellence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aef8667e-f710-4088-b539-374dc2a6af94', 'Self-help and persistent hard work are the true secrets to academic success, not magical shortcuts', true, '1ecdaec9-fd20-4615-81d5-308b49b365dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdc7bd09-3f53-4520-ada8-4b3a63d9dd1a', 'Elves are dangerous creatures to keep as pets', false, '1ecdaec9-fd20-4615-81d5-308b49b365dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a06e10f3-5136-496f-a6ad-1b534d83b64a', 'Homework should be banned in schools', false, '1ecdaec9-fd20-4615-81d5-308b49b365dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f1437dd-ae57-447a-86fc-203561e9518e', 'Video games are better than studies', false, '1ecdaec9-fd20-4615-81d5-308b49b365dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ccf7a32-98e2-4f2a-81dd-2284f93d9468', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'In the supplementary reader tale ''A Tale of Two Birds'', why did the two young birds behave so completely differently?', '''One is known by the company one keeps.'' Environmental conditioning and peer company shaped their distinct characters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e72b8557-73e4-4bcd-aedf-48881751dc73', 'One lived with robbers and learned abusive language; the other lived near a Rishi''s ashram and learned courteous hospitality', true, '2ccf7a32-98e2-4f2a-81dd-2284f93d9468');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('747b5d0c-0df6-4730-8649-32d9adbe92b9', 'They belonged to different biological species', false, '2ccf7a32-98e2-4f2a-81dd-2284f93d9468');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2559b6f-27d9-4632-be4c-c3c019b892f5', 'One was blind and the other was deaf', false, '2ccf7a32-98e2-4f2a-81dd-2284f93d9468');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('020218a3-1340-4a48-a0a7-74aa28626798', 'One was fed meat and the other ate grains', false, '2ccf7a32-98e2-4f2a-81dd-2284f93d9468');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68ce438d-4989-47c8-a88d-f9d8622f25fd', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What phrase did the King utter upon hearing the ashram bird welcome him so gently?', 'The King was amazed by how two identical sibling birds displayed opposite behavioral temperaments due to their company.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59d421be-5406-4a10-8f30-852e18321501', '"This bird looks just like the other outside the cave, but how different their talk is!"', true, '68ce438d-4989-47c8-a88d-f9d8622f25fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77971cae-809d-49dc-801f-c5be6f9e225c', '"I will shoot this bird for dinner."', false, '68ce438d-4989-47c8-a88d-f9d8622f25fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95044f4d-f83e-4a12-811a-b0b2ead4d627', '"This bird is an imposter."', false, '68ce438d-4989-47c8-a88d-f9d8622f25fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebf4e84f-8a5d-4364-bbb0-7c48a6d64bf7', '"Take me to the robbers'' den."', false, '68ce438d-4989-47c8-a88d-f9d8622f25fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c98e6222-07b8-466d-8dc4-eeab6d49968c', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What is the meaning of the word ''Britches'' in the description of the elf?', '''Britches'' (or breeches) are old-fashioned short trousers fitting snugly just below the knee.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e448c9d-4997-46bd-9c18-7b9264fe3245', 'Short trousers / breeches', true, 'c98e6222-07b8-466d-8dc4-eeab6d49968c');
