INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baef99d8-dcbf-451d-a7bb-82e18d988c7b', 'A magical cape', false, 'c98e6222-07b8-466d-8dc4-eeab6d49968c');
