INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e239902-983e-43c4-bd70-34bcfb32655c', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'Fill in the blank: ''Patrick stayed up nights, feeling ______ and tired, yet went to school with his eyes puffed and bleary.''', '''Weary'' expresses extreme physical and mental fatigue resulting from late-night studying.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4e348c4-6b8d-42f8-98e9-2987fc71c2f0', 'weary', true, '4e239902-983e-43c4-bd70-34bcfb32655c');
