INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e2a75ab-021c-4f72-820f-2447b39b5771', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What did Patrick''s teachers do when he started scoring top grades?', 'His teachers were genuinely pleased, admiring his transformed dedication and academic turnaround.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5dfa774-97f7-4dd6-86d9-eed949d7e9ea', 'They smiled, praised him, and were full of sincere appreciation', true, '7e2a75ab-021c-4f72-820f-2447b39b5771');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('577aeb94-1fbd-427a-abf1-5a3e1a8ce13e', 'They accused him of cheating with an elf', false, '7e2a75ab-021c-4f72-820f-2447b39b5771');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d4c7cf3-cebc-46ff-9866-86759f2c6cc3', 'They gave him twice as much homework', false, '7e2a75ab-021c-4f72-820f-2447b39b5771');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0bf9677-9e17-4b84-9e15-080d1c6773bf', 'They called his parents to complain', false, '7e2a75ab-021c-4f72-820f-2447b39b5771');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32435e37-3367-49c3-9a49-ce6722da0f41', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'Which of the following describes Patrick''s eyes on the morning after studying all night?', 'Working late hours with the elf left Patrick''s eyes visibly swollen (''puffed'') and exhausted (''bleary'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('784684f7-8a39-4077-a415-572ffec3b953', 'Puffed and bleary', true, '32435e37-3367-49c3-9a49-ce6722da0f41');
