INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a955ee02-4b70-41ed-8793-8cd167522e2c', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What is the meaning of ''Glitch'' in the context of the elf''s homework trouble?', 'A glitch refers to a sudden malfunction, hindrance, or flaw that stops progress.', NOW()) ON CONFLICT DO NOTHING;
