INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27a7974e-181c-4b1f-b913-0e31084ec12f', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What did Patrick think his cat was playing with before discovering it was an elf?', 'Patrick mistook the minuscule man for a child''s toy doll when grabbing it from the cat.', NOW()) ON CONFLICT DO NOTHING;
