INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db4964a4-6d28-40e2-85cb-f4e93baaef67', 'Chimney', false, 'b1fc48f1-467f-4a79-948a-b2978477d50a');
