INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a4a2b2f-87c5-44af-bcbe-cf6c9f46c9fa', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'What profound psychological technique did the elf unwittingly use on Patrick to make him study?', 'By constantly claiming ignorance, the elf compelled Patrick into active reading, calculation, and self-directed study.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5790e9bf-daf0-4a3d-9433-2e7e8363ceb2', 'Reverse scaffolding / forced active learning (acting helpless so Patrick took full ownership of the problem-solving)', true, '5a4a2b2f-87c5-44af-bcbe-cf6c9f46c9fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5c06dcb-b3cb-4e86-a63d-e564364a1234', 'Hypnotic mind control', false, '5a4a2b2f-87c5-44af-bcbe-cf6c9f46c9fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b55c7cb-f768-4076-9942-06e58d433fbb', 'Threat of physical punishment', false, '5a4a2b2f-87c5-44af-bcbe-cf6c9f46c9fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8edd027-8fd0-40b5-b409-95cadf2f1ffb', 'Bribery with magical coins', false, '5a4a2b2f-87c5-44af-bcbe-cf6c9f46c9fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f19be9fc-70b7-40f3-af5e-1d47f4722ead', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'In ''A Tale of Two Birds'', the Rishi summarized the ultimate lesson of the story as:', 'The sage explains that association and environment define social temperament and speech habits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27d4fb02-020b-4cee-9dea-3ea657ea5ec2', '"One is known by the company one keeps. That bird repeated the robbers'' talk, but this one repeats what he hears at the ashram."', true, 'f19be9fc-70b7-40f3-af5e-1d47f4722ead');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcb83d32-46a9-4665-86a9-b3dece99d073', '"Never trust a wild bird in a storm."', false, 'f19be9fc-70b7-40f3-af5e-1d47f4722ead');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11c2f745-9317-4b55-8b3f-b08c65a058aa', '"Kings must always hunt in thick forests."', false, 'f19be9fc-70b7-40f3-af5e-1d47f4722ead');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fef381da-359c-471a-87c1-7c95f7612b9b', '"All birds in a forest possess evil minds."', false, 'f19be9fc-70b7-40f3-af5e-1d47f4722ead');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2a83bb8-7a2c-4f15-aa44-4128e326893e', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'Match the words from the story with their exact contextual meanings:
(a) Slyly      -> (i) Shrieked high-pitched
(b) Bleary     -> (ii) Secretly / cunningly
(c) Squeaked   -> (iii) Dim / dull from tiredness
(d) Semester   -> (iv) School academic term', 'Slyly = Secretly; Bleary = Dull from exhaustion; Squeaked = High-pitched cry; Semester = Academic period.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc8fd940-cf31-4863-a217-3293e0447834', 'a-(ii), b-(iii), c-(i), d-(iv)', true, 'e2a83bb8-7a2c-4f15-aa44-4128e326893e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c39cb27-0284-483b-9167-a2e26fab42b6', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'e2a83bb8-7a2c-4f15-aa44-4128e326893e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a88a7e6-213e-471d-b6c3-dfba36a8c4f1', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'e2a83bb8-7a2c-4f15-aa44-4128e326893e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73faea43-d38c-4389-bc51-191e718dfb50', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'e2a83bb8-7a2c-4f15-aa44-4128e326893e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7868e76-677d-4f53-8280-362cda0ff3b0', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'Read the statements from ''A House, A Home'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63c6fbf5-a794-420e-8c01-0f3b0c9b331e', 'Statements 1 and 2 only', true, 'b7868e76-677d-4f53-8280-362cda0ff3b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('154f8fb0-bcca-4c93-bef3-d094b31717a5', 'Statements 2 and 3 only', false, 'b7868e76-677d-4f53-8280-362cda0ff3b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88424dcd-d2ed-4b38-8931-43e6fada970a', 'Statements 1 and 3 only', false, 'b7868e76-677d-4f53-8280-362cda0ff3b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38285d02-e033-4561-a0ca-bd87ae2cef27', 'All Statements 1, 2, and 3', false, 'b7868e76-677d-4f53-8280-362cda0ff3b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2d6bcb6-0f02-4982-9b12-79aec6f5ea4c', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'Consider the elf''s physical reaction: ''He kicked his legs and doubled his fists and he grimaced and scowled and pursed his lips.'' What emotion is depicted?', 'The vivid bodily gestures (grimacing, scowling, kicking) express violent displeasure and resentment toward doing homework.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0636eca0-d40a-4418-892c-dbe83573ccb4', 'Intense frustration and reluctance at being trapped into doing school homework', true, 'd2d6bcb6-0f02-4982-9b12-79aec6f5ea4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d42cd025-7843-4dff-ac41-0d6ba820ddd6', 'Joyful excitement at solving puzzles', false, 'd2d6bcb6-0f02-4982-9b12-79aec6f5ea4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1af6f2d0-1962-4c42-b63c-68cb9fecf518', 'Deep peaceful sleep', false, 'd2d6bcb6-0f02-4982-9b12-79aec6f5ea4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb28d146-c6ff-4327-83ae-14644615df8f', 'Fear of the dark', false, 'd2d6bcb6-0f02-4982-9b12-79aec6f5ea4c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03c11bc0-6ce3-422d-a01f-6ef89c65ac00', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'Why did Patrick keep the truth a ''secret'' between himself and the reader at the end of the story?', 'Author Carol Moore writes: ''You think Patrick''s elf did his homework; but I''ll share a secret between you and me: Patrick had done it himself!''', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c97c1c4b-96a0-40a4-8fe8-96caec96af87', 'Patrick still believed in his own heart that the tiny elf had performed the miracle', true, '03c11bc0-6ce3-422d-a01f-6ef89c65ac00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08fdbcce-c9a1-48f3-ad1c-b08498b2d6b8', 'He was ashamed of his ''A'' grade', false, '03c11bc0-6ce3-422d-a01f-6ef89c65ac00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcc904be-69f4-42ba-b9fa-d0329443a009', 'His parents forbid him from talking', false, '03c11bc0-6ce3-422d-a01f-6ef89c65ac00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f90570d0-665c-4a3a-9bd4-5720d345cd68', 'The teachers threatened him', false, '03c11bc0-6ce3-422d-a01f-6ef89c65ac00');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5f9e6c4-da3c-4aaf-8c03-3aa98d647781', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'In ''A Tale of Two Birds'', how did the strong thunderstorm initially separate the mother bird and her two fledglings?', 'The storm''s violent winds blew the fledglings away, landing one near a robber''s cave and the other beside a peaceful hermitage.', NOW()) ON CONFLICT DO NOTHING;
