INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eefcbfc8-d421-4b2a-b7c4-9c826bba97bf', 'Jupiter', false, 'e8ee94f3-e90a-447d-a910-3260d71f8c6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd078272-d011-4892-8e4b-494715e0a6f1', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'What is the unique spherical shape of planet Earth (slightly flattened at the poles and bulged at the equator) called?', '''Geoid'' literally means ''Earth-shaped'', describing an oblate spheroid flattened at poles due to axial rotation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6ed7963-526a-4d1a-bf33-7efb4b7f7256', 'Geoid (Earth-like shape)', true, 'fd078272-d011-4892-8e4b-494715e0a6f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ed9b7f2-24b5-4fb1-ab0d-311d1aa8a7b7', 'Perfect Sphere', false, 'fd078272-d011-4892-8e4b-494715e0a6f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b8b1e2b-c0c9-4654-bca0-250481b4be9b', 'Cube', false, 'fd078272-d011-4892-8e4b-494715e0a6f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d662b2b-f31e-42dc-ae3f-d93942cf64ef', 'Oval', false, 'fd078272-d011-4892-8e4b-494715e0a6f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e251836-9838-4164-924e-923f5a33efd1', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'Why is planet Earth uniquely known as the ''Blue Planet'' when viewed from outer space?', 'Rayleigh scattering off expansive oceanic hydrosphere gives Earth its brilliant azure appearance from space.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1502465e-7fdb-4206-bf1a-96822817cda5', 'Two-thirds (around 71%) of its surface is covered by liquid water in oceans and seas', true, '1e251836-9838-4164-924e-923f5a33efd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ebfccd3-a2a4-4f1e-a6cb-346e5986d5cd', 'Its atmosphere is made of blue smoke', false, '1e251836-9838-4164-924e-923f5a33efd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03055489-69b5-4f64-a84f-13ef44b4bbf2', 'Earth is covered with blue soil', false, '1e251836-9838-4164-924e-923f5a33efd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9a15585-49a6-4b94-9300-fbf05f1356e0', 'Sunlight reflects blue from mountains', false, '1e251836-9838-4164-924e-923f5a33efd1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3c48980-9f2b-45b7-9528-c7b9c7480a7b', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'How long does the Moon take to complete one revolution around the Earth?', 'Synchronous tidal locking causes the Moon''s orbital period (~27.3 days) to match its axial rotation period.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a16ad4f-0d85-4d72-b6d8-e65ddf69e5ce', 'About 27 days (and takes exactly the same time to complete one rotation on its axis)', true, 'f3c48980-9f2b-45b7-9528-c7b9c7480a7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3b07130-07f9-4caa-be5d-e6aa5ccd0de1', '365 days', false, 'f3c48980-9f2b-45b7-9528-c7b9c7480a7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('565eaa0a-221e-438c-ab36-ac88b6e3aed3', '24 hours', false, 'f3c48980-9f2b-45b7-9528-c7b9c7480a7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80bd24e6-bd89-4d9a-980e-a10f428c1fb0', '30 days', false, 'f3c48980-9f2b-45b7-9528-c7b9c7480a7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10253f7c-61d1-4983-a020-6d1abd9e5f50', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'The tiny rocky celestial objects that revolve around the Sun primarily between the orbits of Mars and Jupiter are called:', 'The Main Asteroid Belt is a circumstellar disc located between the orbital paths of terrestrial Mars and gas giant Jupiter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01d2687a-7fef-4063-ada0-7f4cd7b8f671', 'Asteroids', true, '10253f7c-61d1-4983-a020-6d1abd9e5f50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8310b8f5-2acc-4edd-8f6a-e69faa2fc17b', 'Meteoroids', false, '10253f7c-61d1-4983-a020-6d1abd9e5f50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb9e0a67-5d22-4805-9ffb-802ec2a7b8b5', 'Comets', false, '10253f7c-61d1-4983-a020-6d1abd9e5f50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a61f8cc-357b-49ef-a3cf-e475d42d3108', 'Dwarf Stars', false, '10253f7c-61d1-4983-a020-6d1abd9e5f50');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7534b9ec-69f4-4009-8814-df99641d0d91', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'Small chunks of rock and metallic debris that travel around the Sun and sometimes enter Earth''s atmosphere causing a streak of light are:', 'Frictional atmospheric compression heats falling meteoroids, creating incandescent trails (meteors / shooting stars).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8f0adf7-d93d-4153-a032-ef1ef8ad316d', 'Meteoroids (Shooting stars)', true, '7534b9ec-69f4-4009-8814-df99641d0d91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55f12fd3-a632-41c9-b4b1-edf48410be9f', 'Asteroids', false, '7534b9ec-69f4-4009-8814-df99641d0d91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f17f9e99-656a-4955-93c4-1f3bd04b5f8b', 'Satellites', false, '7534b9ec-69f4-4009-8814-df99641d0d91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('762d322d-8cce-47d1-b2a4-8499c0850246', 'Constellations', false, '7534b9ec-69f4-4009-8814-df99641d0d91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8197158e-7f4e-48e0-bff3-92122e831688', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'What is our home spiral galaxy called, which appears as a faint glowing band of stars across the clear night sky?', 'Our solar system resides inside the Orion Arm of the Milky Way barred spiral galaxy, traditionally called Akash Ganga.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4eab9568-45c6-4e4d-aecc-05e3a4a45300', 'Milky Way Galaxy (Akash Ganga)', true, '8197158e-7f4e-48e0-bff3-92122e831688');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('957c8ab9-cd00-44c8-87af-cc42cd6765fb', 'Andromeda Galaxy', false, '8197158e-7f4e-48e0-bff3-92122e831688');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ebf85d2-02af-4317-8627-fec0ca26fe5b', 'Triangulum', false, '8197158e-7f4e-48e0-bff3-92122e831688');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68fd4ca0-e770-4b47-af5d-8d0fbb668fd0', 'Whirlpool Galaxy', false, '8197158e-7f4e-48e0-bff3-92122e831688');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84d53940-7ab8-4348-b722-07e35a800a29', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Why do we always see only ONE side of the Moon from the Earth?', 'Gravitational tidal lock equalizes orbital revolution and axial spin, keeping the lunar near-side permanently facing Earth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b1b9cf-b135-40be-a950-dfb79076365d', 'Because the Moon takes exactly the same time (~27 days) to complete one rotation on its axis as it takes to revolve once around the Earth (Synchronous Rotation)', true, '84d53940-7ab8-4348-b722-07e35a800a29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4adbaefb-42c9-469b-9a0e-e94e896e5e99', 'The other side of the Moon is pitch dark without light', false, '84d53940-7ab8-4348-b722-07e35a800a29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c4340bd-0b64-4b36-9b14-32178cc6bed1', 'The Moon does not rotate at all', false, '84d53940-7ab8-4348-b722-07e35a800a29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8636dc2-d74a-46e6-aed6-b25d9ddc46a9', 'Clouds block the other side', false, '84d53940-7ab8-4348-b722-07e35a800a29');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('808467f4-673f-4fba-8882-709ba7bd7e48', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Why is Earth considered the only unique planet in the Solar System capable of supporting biological life?', 'Earth sits squarely inside the circumstellar Goldilocks Habitable Zone, sustaining liquid water and breathable N2-O2 atmosphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29dc1d35-cf2d-489d-899a-9c31d5135c06', 'It has moderate temperature conditions, life-supporting oxygen gas in atmosphere, and abundant liquid water in hydrological cycles', true, '808467f4-673f-4fba-8882-709ba7bd7e48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6712c0ed-7918-4fea-99b8-20f05f7b6d82', 'It has zero gravity', false, '808467f4-673f-4fba-8882-709ba7bd7e48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e180412c-6ea2-4a7c-9770-b390f3137267', 'It is the closest planet to the Sun', false, '808467f4-673f-4fba-8882-709ba7bd7e48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e25c6cab-e50a-4dec-9ecb-7ce0516282cf', 'It is made entirely of gold and diamonds', false, '808467f4-673f-4fba-8882-709ba7bd7e48');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3145cad9-a6a7-476c-b82b-c4bc78f222e4', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'How long does light from the Sun take to reach the surface of planet Earth?', 'At light speed c = 300,000 km/s across 150,000,000 km distance: time t = 150,000,000 ÷ 300,000 = 500 seconds = 8 min 20 sec.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2c38051-bc6e-447f-8c29-84974349a56f', 'About 8 minutes and 20 seconds', true, '3145cad9-a6a7-476c-b82b-c4bc78f222e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dce45f2-4256-4b66-b825-469f10e120f7', '1 minute', false, '3145cad9-a6a7-476c-b82b-c4bc78f222e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04e49bcd-849d-4a35-ade6-728a22411087', '24 hours', false, '3145cad9-a6a7-476c-b82b-c4bc78f222e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68630dfd-0bfb-401c-af2f-73cbdca1de33', 'Instantaneously in 1 second', false, '3145cad9-a6a7-476c-b82b-c4bc78f222e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('516375dc-8549-4d15-8e17-4c6183161bac', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Who was the first human astronaut to step onto the surface of the Moon on 20 July 1969?', 'American Apollo 11 astronaut Neil Armstrong made historic first contact on the lunar Mare Tranquillitatis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc9621f6-0e58-4ff7-9378-b28100606588', 'Neil Armstrong', true, '516375dc-8549-4d15-8e17-4c6183161bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfe6db1d-a39f-4021-b73d-4859f53ec05e', 'Yuri Gagarin', false, '516375dc-8549-4d15-8e17-4c6183161bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86871015-7fc9-4204-8575-ed58e7c12561', 'Rakesh Sharma', false, '516375dc-8549-4d15-8e17-4c6183161bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5c0f5b6-aed1-4596-9440-cdf951ad1dc6', 'Buzz Aldrin', false, '516375dc-8549-4d15-8e17-4c6183161bac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14f96b52-1fce-44e8-99b5-df430f3dee7b', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What is a ''Human-made (Artificial) Satellite''?', 'Spacecraft like INSAT, IRS, and EDUSAT are engineered payloads injected into orbit for communications and remote sensing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f0b1b67-df7d-4366-892a-a34ae381b3e7', 'An artificial body designed by scientists to gather information about the universe or for telecommunication, placed in Earth''s orbit by rockets', true, '14f96b52-1fce-44e8-99b5-df430f3dee7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6021b40-67c1-413c-9b3b-9270992e7fd8', 'A natural rock orbiting Mars', false, '14f96b52-1fce-44e8-99b5-df430f3dee7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('889f483a-b390-40cf-ad41-3e7e92543f0e', 'A telescope on a mountain', false, '14f96b52-1fce-44e8-99b5-df430f3dee7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9facced-3582-43b2-8dc0-d4cbb915eae6', 'An aeroplane flying in clouds', false, '14f96b52-1fce-44e8-99b5-df430f3dee7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42837cd9-3c0e-4a0a-b63c-f80d6147d15e', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Why was Pluto reclassified from a major planet to a ''Dwarf Planet'' by the International Astronomical Union (IAU) in August 2006?', 'IAU planetary criteria require a planet to: orbit the Sun, attain hydrostatic equilibrium, and have cleared its orbital neighborhood.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eec852dd-57c1-46f3-8264-12b8b2c65b8a', 'Pluto failed to clear its orbital neighborhood of other icy trans-Neptunian Kuiper belt debris', true, '42837cd9-3c0e-4a0a-b63c-f80d6147d15e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86ac18c3-191c-4ebd-b90b-d6bdbc6af1ba', 'Pluto melted into water', false, '42837cd9-3c0e-4a0a-b63c-f80d6147d15e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6eaf615-54ec-4aae-82f6-ab6c0360d7be', 'Pluto collided with the Sun', false, '42837cd9-3c0e-4a0a-b63c-f80d6147d15e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4efc951-f7ff-42f2-b9bb-ea3a89bbd5b0', 'Pluto stopped revolving', false, '42837cd9-3c0e-4a0a-b63c-f80d6147d15e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff14187b-fc4b-4de6-a2c5-a96f6706d032', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What are the four ''Inner Planets'' of the Solar System?', 'Inner planets are dense, rocky silicates situated inside the main asteroid belt, unlike outer gas/ice giants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73a6dff6-182a-4c9c-a453-fecb4f12a365', 'Mercury, Venus, Earth, and Mars (terrestrial rocky planets close to the Sun)', true, 'ff14187b-fc4b-4de6-a2c5-a96f6706d032');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09b7b780-69bf-46a5-add4-2cc2196175b8', 'Jupiter, Saturn, Uranus, and Neptune', false, 'ff14187b-fc4b-4de6-a2c5-a96f6706d032');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8830d706-5d91-48d1-9db7-5960491263b6', 'Earth, Moon, Sun, and Mars', false, 'ff14187b-fc4b-4de6-a2c5-a96f6706d032');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b06ca1d6-9304-4e58-aac0-bd1301da14aa', 'Pluto, Ceres, Eris, and Haumea', false, 'ff14187b-fc4b-4de6-a2c5-a96f6706d032');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('697e1d8a-fa2a-4496-82bc-b49b5064ef98', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Which outer planet in the Solar System possesses the most spectacular and prominent system of rings composed of ice and dust chunks?', 'Saturn''s extensive ring system spans up to 282,000 km, composed of reflective water-ice particles and rocky debris.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('481c6342-3425-4189-bc71-de60a7e29a8d', 'Saturn', true, '697e1d8a-fa2a-4496-82bc-b49b5064ef98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('197585ee-a532-4fea-880c-907d3900f0fa', 'Jupiter', false, '697e1d8a-fa2a-4496-82bc-b49b5064ef98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c0f9a39-15d6-444d-abae-37791583a228', 'Neptune', false, '697e1d8a-fa2a-4496-82bc-b49b5064ef98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7001b9c-33bc-4a19-b217-c60e270be965', 'Mars', false, '697e1d8a-fa2a-4496-82bc-b49b5064ef98');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('573a3985-ecdd-47e6-a803-cc6d8f2c8206', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What is the famous seven-star constellation known as ''Saptarishi'' in Indian astronomy?', 'The Saptarishi asterism (Big Dipper) forms the prominent tail and body of the constellation Ursa Major.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1040a4dc-cf08-4883-b058-7307518b3bf2', 'A group of seven prominent stars that forms part of the Ursa Major (Great Bear) constellation', true, '573a3985-ecdd-47e6-a803-cc6d8f2c8206');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e7fc09f-02de-4a0a-8335-643d43bc4feb', 'A cluster of seven planets', false, '573a3985-ecdd-47e6-a803-cc6d8f2c8206');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db49661d-988a-48b3-9058-5404279d5921', 'The seven moons of Jupiter', false, '573a3985-ecdd-47e6-a803-cc6d8f2c8206');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4467fdb-6505-4a30-ae97-7fa907bff300', 'The Orion Hunter belt', false, '573a3985-ecdd-47e6-a803-cc6d8f2c8206');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57a714b9-5e33-40a3-9a55-9b25092a353b', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'How can one locate the position of the North Pole Star in the night sky using the Saptarishi constellation?', 'Extending the line connecting pointer stars Merak and Dubhe northward leads directly to Polaris.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da332df7-bcda-4b9e-b6f5-0bb5ce3ac664', 'By drawing an imaginary straight pointer line through the two forward pointer stars of Saptarishi and extending it northward', true, '57a714b9-5e33-40a3-9a55-9b25092a353b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1855cdf-4a09-44c8-8de8-982e787035ac', 'By looking directly behind the Moon', false, '57a714b9-5e33-40a3-9a55-9b25092a353b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52ea2583-717e-4905-9922-6e8e6fa00c85', 'By pointing toward the southern horizon', false, '57a714b9-5e33-40a3-9a55-9b25092a353b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f671dc29-a941-4585-8e22-864bc2e059f2', 'By tracking the movement of Mars', false, '57a714b9-5e33-40a3-9a55-9b25092a353b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6324aaff-5cbb-48aa-be83-f459782d1d92', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What happens when a large meteoroid does not burn up completely in Earth''s atmosphere and crashes onto the Earth''s surface?', 'Surviving solid fragments that strike planetary crust are termed meteorites, forming impact structures (e.g., Lonar Crater).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2219a211-5420-4461-83a1-54eae2bcf136', 'It is called a Meteorite and creates a hollow impact crater in the ground', true, '6324aaff-5cbb-48aa-be83-f459782d1d92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15308011-6269-4527-8703-86fd36bb181e', 'It turns into a new planet', false, '6324aaff-5cbb-48aa-be83-f459782d1d92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('233f1461-b20b-4a52-9fb5-e94fc71607f1', 'It bounces back to outer space', false, '6324aaff-5cbb-48aa-be83-f459782d1d92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed8c0f63-99ee-4c84-ba42-ba6f608ca470', 'It dissolves into rain clouds', false, '6324aaff-5cbb-48aa-be83-f459782d1d92');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1367b37d-5d76-402d-82d2-2ac4a9267784', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Which is the fastest planet to complete one revolution around the Sun (taking only 88 days)?', 'By Kepler''s Third Law, Mercury''s closest orbital proximity (57.9 million km) results in a brief 88-day sidereal year.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d598839a-fee8-4254-a71d-8c2f07016787', 'Mercury', true, '1367b37d-5d76-402d-82d2-2ac4a9267784');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('292ed720-0991-4453-a6d3-a50cbaaa3483', 'Venus', false, '1367b37d-5d76-402d-82d2-2ac4a9267784');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bfb5562-be99-40f5-8bac-0b802408c5f7', 'Earth', false, '1367b37d-5d76-402d-82d2-2ac4a9267784');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ef0803e-0de8-40ec-96fb-b5f3e1ec819e', 'Mars', false, '1367b37d-5d76-402d-82d2-2ac4a9267784');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d39f9f80-6743-4ad9-9864-478faf62e3c8', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What is the primary source of all heat and light energy throughout our Solar System?', 'Thermonuclear fusion of hydrogen into helium in the Sun''s core generates the solar irradiance powering the entire system.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2d37c98-56bb-4c48-97b1-ea5f01a8891a', 'The Sun', true, 'd39f9f80-6743-4ad9-9864-478faf62e3c8');
