INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ab25df6-66e0-4289-9cbb-6363f5083aff', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Which of the following Indian artificial satellites was launched for educational tele-broadcasting?', 'Launched in 2004 by ISRO, EDUSAT was India''s dedicated satellite for distance educational curriculum delivery.', NOW()) ON CONFLICT DO NOTHING;
