INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('decb3388-d317-4e5b-98c5-51684ad9e386', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What is a ''New Moon'' night known as in the Indian calendar?', 'During Amavasya (New Moon), the Moon sits between Earth and Sun, presenting its unilluminated shadowed face toward Earth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13508f3c-c1b4-4d9c-9792-65db65211f42', 'Amavasya (when the Moon is not visible at all)', true, 'decb3388-d317-4e5b-98c5-51684ad9e386');
