INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ac83284-c4c4-4ad8-8c44-24c5adfc8bf8', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What is a ''Full Moon'' night known as in the Indian calendar?', 'Poornima occurs when Earth lies between Sun and Moon, allowing the full hemisphere of lunar reflection to be viewed.', NOW()) ON CONFLICT DO NOTHING;
