INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('063b568b-7b75-4d40-b832-c5f8c9580abc', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Arrange the planets in order of their increasing distance from the Sun:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6b7d47e-f45b-40f5-b186-d76f43320eef', '2 -> 4 -> 3 -> 1 (Mercury -> Venus -> Earth -> Mars)', true, '063b568b-7b75-4d40-b832-c5f8c9580abc');
