INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e139e75-aaae-4f66-9839-503700145352', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'af53b25f-e9cd-4503-89b7-9b24f6115152');
