INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5960177c-f6eb-4a02-b187-73ecea4616f9', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'What is the fundamental scientific difference between a Planet and a Star?', 'Self-luminous stars undergo stellar nucleosynthesis, whereas non-luminous planets shine solely via reflected starlight.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86cb2113-f0ce-40ec-b250-88f34f689a98', 'Stars generate their own heat and light through nuclear fusion; planets have no internal fusion and only reflect light from stars', true, '5960177c-f6eb-4a02-b187-73ecea4616f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da97f109-2eb9-4d34-b2b5-64e8ea3270fb', 'Planets are always bigger than stars', false, '5960177c-f6eb-4a02-b187-73ecea4616f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fbc9ec1-ea6e-49c9-8eca-4fa9032f4a59', 'Stars revolve around planets', false, '5960177c-f6eb-4a02-b187-73ecea4616f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47aeafad-7a25-4676-92af-f8b177c17905', 'Stars are made of liquid water', false, '5960177c-f6eb-4a02-b187-73ecea4616f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eeed1fdd-c1ad-4dfd-b665-5998c8f90c66', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Read the statements regarding the Solar System:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6b130c2-ee58-4d0b-8e40-abd8d4fc1f7f', 'Statements 1 and 3 only', true, 'eeed1fdd-c1ad-4dfd-b665-5998c8f90c66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abe6ece8-6929-4c15-b0f3-2472ad0613df', 'Statements 1 and 2 only', false, 'eeed1fdd-c1ad-4dfd-b665-5998c8f90c66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ae2b80d-3cf1-45ee-9004-c747097bea6b', 'Statements 2 and 3 only', false, 'eeed1fdd-c1ad-4dfd-b665-5998c8f90c66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0e659c5-e697-44a2-8fe3-41af45c8d02c', 'All Statements 1, 2, and 3', false, 'eeed1fdd-c1ad-4dfd-b665-5998c8f90c66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54db38cf-1755-448a-a113-8dcc0ca094cb', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Match the celestial bodies with their distinctive characteristics:
(a) Venus     -> (i) Red Planet (iron oxide dust)
(b) Mars      -> (ii) Earth''s Twin
(c) Jupiter   -> (iii) Ringed Gas Giant
(d) Saturn    -> (iv) Largest planet in solar system', 'Venus = Earth''s Twin; Mars = Red planet; Jupiter = Largest planet; Saturn = Prominent ring system.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5065ca44-4757-4820-8ce4-cfef012b8cd7', 'a-(ii), b-(i), c-(iv), d-(iii)', true, '54db38cf-1755-448a-a113-8dcc0ca094cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d5aeed3-57eb-4e23-a596-2099644d3193', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '54db38cf-1755-448a-a113-8dcc0ca094cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f7f80ae-7faf-4605-a491-bd99a9aa7bd2', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '54db38cf-1755-448a-a113-8dcc0ca094cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08d03025-f9a5-4418-9442-f1b0620198e3', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '54db38cf-1755-448a-a113-8dcc0ca094cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7880b36b-b7fb-45c9-8eaf-ce166d6ed4dc', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Why does the Moon have extreme surface temperatures (100°C+ during lunar day and -170°C at lunar night) with zero liquid water?', 'Lunar vacuum exosphere offers zero greenhouse buffering, subjecting the regolith to brutal unshielded solar irradiance and radiative cooling.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b79efb6c-44d3-426a-95c5-f7aa045997b3', 'The Moon lacks a protective blanket of atmosphere to trap or shield solar radiation and regulate heat', true, '7880b36b-b7fb-45c9-8eaf-ce166d6ed4dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('512ca713-b75a-4f62-a7dd-0a7a80a3afb1', 'The Moon is made of radioactive fire', false, '7880b36b-b7fb-45c9-8eaf-ce166d6ed4dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eba4007a-5e5f-4ef9-8107-17b3dea676dc', 'The Moon is too close to the Sun', false, '7880b36b-b7fb-45c9-8eaf-ce166d6ed4dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2250d5e3-a83d-47a2-b38b-ab4f0b93ea97', 'The Moon is surrounded by ice clouds', false, '7880b36b-b7fb-45c9-8eaf-ce166d6ed4dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63e4a2f5-0bd6-4886-adaa-c3d3213e1f75', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Why is the word ''Planet'' derived from the ancient Greek word ''Planetai''?', 'Ancient astronomers tracked planets drifting apparent retrograde loops relative to background stellar coordinates, naming them wanderers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('244b4078-5bba-4a2d-9667-df06e4d73feb', 'Because ''Planetai'' means ''Wanderers'', describing how planets appeared to wander across fixed stellar constellations', true, '63e4a2f5-0bd6-4886-adaa-c3d3213e1f75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d4866e6-eaa4-49b7-842d-61c7affb5671', 'Because it means ''Giant Stone''', false, '63e4a2f5-0bd6-4886-adaa-c3d3213e1f75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92c8c05d-be3f-49eb-af6e-ad42d128f764', 'Because it means ''Water Carrier''', false, '63e4a2f5-0bd6-4886-adaa-c3d3213e1f75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6e566fc-d8ba-48be-a197-2ce5d0746b96', 'Because it means ''King of Sky''', false, '63e4a2f5-0bd6-4886-adaa-c3d3213e1f75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfd066a0-d402-4b44-a826-d11ddb502f3a', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Consider four celestial objects:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f9f244b-5961-478b-9ac4-2d0bff49eaa3', '1 only (Sirius)', true, 'cfd066a0-d402-4b44-a826-d11ddb502f3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f9e3b75-f8f6-45cb-9777-f72cb89c2e6e', '2 and 3 only', false, 'cfd066a0-d402-4b44-a826-d11ddb502f3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('893a798c-93c2-407b-947c-cf303a164adc', '1 and 4 only', false, 'cfd066a0-d402-4b44-a826-d11ddb502f3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecfdea41-ac2d-4061-85c1-d3a8014f553e', 'All 1, 2, 3, and 4', false, 'cfd066a0-d402-4b44-a826-d11ddb502f3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba856ffd-a543-4e51-8f71-c6390882d785', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'What is the speed of light in vacuum, and how is it used to define astronomical distances (Light Years)?', 'Light speed c = 3 × 10⁸ m/s in vacuum; 1 light year = c × 31,557,600 s ≈ 9.46 × 10¹² km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66076aae-e3f1-40b9-8a8c-c165dcf58e0e', '300,000 km per second (3 × 10⁸ m/s); a light year is the total distance light travels in one full year (~9.46 trillion km)', true, 'ba856ffd-a543-4e51-8f71-c6390882d785');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cd05af7-df96-4ebd-a8ac-f7dd466bf000', '1,000 km per hour', false, 'ba856ffd-a543-4e51-8f71-c6390882d785');
