INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50f42843-5519-4ff5-82da-e9da11850226', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Why do astronauts floating in the International Space Station or standing on the Moon see the outer space sky as pitch BLACK even in broad daylight?', 'Without air molecules to scatter blue optical wavelengths, the vacuum of space appears pitch black even when the Sun blazes brightly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4e28c8f-c69a-4fd1-8d83-6ddbfa11f2ec', 'There is no atmospheric medium in space to scatter incoming sunlight (Rayleigh scattering does not occur in vacuum)', true, '50f42843-5519-4ff5-82da-e9da11850226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('699b5643-e6d5-4ede-9e15-dce967f30829', 'The Sun is turned off in space', false, '50f42843-5519-4ff5-82da-e9da11850226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a24fc0db-f85e-4255-bedb-f585d24bb202', 'Space helmets have black glass', false, '50f42843-5519-4ff5-82da-e9da11850226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29858dd1-b83c-465d-aca0-c50191848e0c', 'Earth blocks all light', false, '50f42843-5519-4ff5-82da-e9da11850226');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c771602-e342-4411-9400-442fa2d2052e', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'मनुष्य अपने भावों और विचारों को बोलकर या लिखकर दूसरों तक पहुँचाने के साधन को क्या कहते हैं?', 'भाषा वह सक्षम माध्यम है जिसके द्वारा मनुष्य अपने मनोभावों एवं विचारों का पारस्परिक आदान-प्रदान करता है।', NOW()) ON CONFLICT DO NOTHING;
