INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61ef9ffd-4ce2-45a0-9795-b8b451637168', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'वह शास्त्र जो हमें भाषा को शुद्ध रूप से बोलना, पढ़ना और लिखना सिखाता है, उसे क्या कहते हैं?', 'व्याकरण भाषा के नियमों का वह शास्त्र है जो भाषा के शुद्ध, मानक एवं त्रुटिहीन प्रयोग का ज्ञान कराता है।', NOW()) ON CONFLICT DO NOTHING;
