INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3dcf898-5aa6-4ed5-a7ca-eb122a7feb8d', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'बच्चा अपने परिवार तथा माता-पिता से जो भाषा सर्वप्रथम सहज रूप से सीखता है, उसे क्या कहते हैं?', 'मातृभाषा वह स्वाभाविक भाषा है जिसे बालक अपने शैशवकाल में माता-पिता एवं घरेलू परिवेश से ग्रहण करता है।', NOW()) ON CONFLICT DO NOTHING;
