INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5f153d6-7472-450f-bf80-316a5ccf5223', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के मुख्य रूप से कितने अंग / विभाग होते हैं?', 'व्याकरण के तीन मूलभूत अंग होते हैं: वर्ण-विचार (Phonology), शब्द-विचार (Morphology) तथा वाक्य-विचार (Syntax)।', NOW()) ON CONFLICT DO NOTHING;
