INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3004fc1-bb57-4204-893a-feba20981965', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'भारतीय संविधान की आठवीं अनुसूची (8th Schedule) में कुल कितनी भाषाओं को आधिकारिक रूप से मान्यता प्राप्त है?', 'संविधान की 8वीं अनुसूची में असमिया, बांग्ला, हिंदी, तमिल, तेलुगु, संस्कृत, उर्दू सहित कुल 22 भाषाएँ सम्मिलित हैं।', NOW()) ON CONFLICT DO NOTHING;
