INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27a58b29-a60b-44dd-9f91-7af3d955796b', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'किसी भाषा के ज्ञान के संचित एवं व्यवस्थित कोष को क्या कहा जाता है?', 'युगों-युगों से संचित ज्ञान, उत्कृष्ट विचारों तथा अनुभूतियों के लिखित संग्रह को ''साहित्य'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
