INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ba79d23-a6e3-44e3-97be-05e6e6187103', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'देश के अधिकांश नागरिकों द्वारा बोली और समझी जाने वाली सर्वमान्य भाषा को क्या कहते हैं?', 'राष्ट्रभाषा संपूर्ण राष्ट्र में जनसंपर्क तथा भावनात्मक एकता स्थापित करने वाली बहुसंख्यक प्रयुक्त भाषा होती है।', NOW()) ON CONFLICT DO NOTHING;
