INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e6cd2ed-3cd5-43aa-b5dd-77e75daf7514', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'सरकारी कार्यालयों तथा प्रशासनिक राजकाज के कार्यों में प्रयुक्त होने वाली भाषा क्या कहलाती है?', 'राजभाषा वह संवैधानिक भाषा है जिसमें देश के शासकीय एवं कानूनी कार्य संपन्न किए जाते हैं।', NOW()) ON CONFLICT DO NOTHING;
