INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0adf01a6-ec20-4897-a4c5-fcbcb76075d0', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'निम्नलिखित में से कौन-सा वाक्य व्याकरण की दृष्टि से पूर्णतः शुद्ध है?', 'सर्वनाम संबंधी अशुद्धि ''मेरे को'' के स्थान पर मानक रूप ''मुझे घर जाना है'' व्याकरणसम्मत शुद्ध प्रयोग है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2488f703-5c32-4c1c-923d-2957f6dfc64d', 'मेरे को घर जाना है। -> अशुद्ध; ''मुझे घर जाना है।'' -> शुद्ध', true, '0adf01a6-ec20-4897-a4c5-fcbcb76075d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b8634e8-fae1-412a-916f-f5a84dddef54', 'हमारा देश में अनेक नदियाँ हैं।', false, '0adf01a6-ec20-4897-a4c5-fcbcb76075d0');
