INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('747323ed-a6df-4a84-9da3-8509596e59cb', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'गद्य साहित्य के अंतर्गत कौन-सी रचना विधा आती है?', 'साधारण बोलचाल की वाक्य संरचना में विचार प्रस्तुत करने वाली विधाएँ (कहानी, निबंध, उपन्यास) गद्य कहलाती हैं।', NOW()) ON CONFLICT DO NOTHING;
