INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00900558-1af7-42ea-8740-075b1bfc3b8e', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'पद्य साहित्य के अंतर्गत निम्नलिखित में से कौन-सी विधा आती है?', 'लय, तुक, छंद तथा गेयता से युक्त भावात्मक रचनाएँ पद्य साहित्य कहलाती हैं।', NOW()) ON CONFLICT DO NOTHING;
