INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f55927f1-b232-4178-8e00-b778636c3daf', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'मराठी भाषा किस लिपि में लिखी जाती है?', 'मराठी तथा कोंकणी भाषाएँ देवनागरी लिपि के ''मोडी/बालबोध'' स्वरूप में लिखी जाती हैं।', NOW()) ON CONFLICT DO NOTHING;
