INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('472c6fd6-cb1b-469f-b143-24f3221163f1', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'ट्रैफ़िक पुलिस का सिपाही हाथ के इशारे से वाहनों को रुकने का संकेत देता है। यह किसका उदाहरण है?', 'संकेतों द्वारा भाव व्यक्त करना सांकेतिक संप्रेषण है; निश्चित नियम न होने से व्याकरण में इसका अध्ययन नहीं होता।', NOW()) ON CONFLICT DO NOTHING;
