INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10443488-ed4c-4cb4-a0d5-8b98c046df49', 'लिखित भाषा', false, '472c6fd6-cb1b-469f-b143-24f3221163f1');
