INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41c57223-3303-4311-8481-69a20d49a372', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग में वर्णों के आकार, उच्चारण, भेद तथा उनके मेल की संधि का अध्ययन किया जाता है?', 'वर्ण-विचार में स्वर, व्यंजन, उनके उच्चारण स्थान, मात्रा तथा वर्ण-संयोजन का विधिवत विवेचन होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc30c242-140d-4bdc-8ea0-8241f238f4d8', 'वर्ण-विचार (Orthography)', true, '41c57223-3303-4311-8481-69a20d49a372');
