INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6075bfb5-a2fd-4a61-869c-268a814c2614', 'पद-विचार', false, '41c57223-3303-4311-8481-69a20d49a372');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e3fb00d-d7cf-4ba0-be11-ca11b5cbbe82', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग में संज्ञा, सर्वनाम, विशेषण, क्रिया तथा शब्द रचना (उपसर्ग, प्रत्यय, समास) का अध्ययन किया जाता है?', 'शब्द-विचार में शब्दों के भेद, व्युत्पत्ति, रूपांतरण तथा अर्थ का विश्लेषणात्मक अध्ययन होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ac4161b-6aec-4faf-aca9-9526bbddd3a4', 'शब्द-विचार (Morphology)', true, '9e3fb00d-d7cf-4ba0-be11-ca11b5cbbe82');
