INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbdf94ac-5e4d-46c2-83a3-b6e64140cb84', 'छंद-विचार', false, '9e3fb00d-d7cf-4ba0-be11-ca11b5cbbe82');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11bbebdf-9e80-4d06-9e4f-36a3e9a013df', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग में वाक्य की रचना, वाक्य के अंग (उद्देश्य और विधेय) तथा विराम-चिह्नों का अध्ययन किया जाता है?', 'वाक्य-विचार के अंतर्गत वाक्य के भेद, पदक्रम, अन्वय, रूपांतरण तथा विराम चिह्नों का अध्ययन किया जाता है।', NOW()) ON CONFLICT DO NOTHING;
