INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d610aff-2298-4623-8818-f9cd6d9f3d32', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cec1345-37a5-429f-93ec-dea6aa5d2b54', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '9d610aff-2298-4623-8818-f9cd6d9f3d32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b038ca76-b111-4ec0-9510-622e18e733f5', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '9d610aff-2298-4623-8818-f9cd6d9f3d32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6193e5b-e206-4ac1-9b24-ace4bff38dd9', '(A) सही है, परन्तु (R) गलत है।', false, '9d610aff-2298-4623-8818-f9cd6d9f3d32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('192f8f3c-9930-4759-b324-8cb98c3768ed', '(A) गलत है, परन्तु (R) सही है।', false, '9d610aff-2298-4623-8818-f9cd6d9f3d32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1237a7fb-51c8-4579-9fbc-b95e5e6fc0ab', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'भाषा और लिपि के संबंध में बेमेल / असंगत (IMPOSTER) युग्म को पहचानिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06fe4ef1-2eef-4b29-ba69-52f4f077b88a', 'हिंदी - देवनागरी', false, '1237a7fb-51c8-4579-9fbc-b95e5e6fc0ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a2414eb-8d84-4f1d-a782-e1dbb2284319', 'अंग्रेज़ी - रोमन', false, '1237a7fb-51c8-4579-9fbc-b95e5e6fc0ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83689511-a0e7-4f0d-a29f-031d4828bd00', 'पंजाबी - गुरुमुखी', false, '1237a7fb-51c8-4579-9fbc-b95e5e6fc0ab');
