INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6c9fd3b-d3f8-403b-a398-ff505427a2e2', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'The shiny appearance or gleam on the freshly cut surface of metals is called:', 'Lustre refers to the metallic sheen produced by the specular reflection of light from free electrons on metal surfaces.', NOW()) ON CONFLICT DO NOTHING;
