INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f7f34dd-3156-4052-8622-845cfbc80520', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Which of the following substances is completely INSOLUBLE in water?', 'Insoluble wood sawdust does not dissolve and remains suspended or floats on the surface of water.', NOW()) ON CONFLICT DO NOTHING;
