INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c16434b-94c8-44e4-b228-ab712af547d8', 'Dry wooden stick', false, '8c8f9822-d076-4cfe-a6fc-4e03830b72b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf76a08b-73e4-4d62-abf1-4efec7bbdeb7', 'Feather', false, '8c8f9822-d076-4cfe-a6fc-4e03830b72b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14131004-4c02-4c54-aff0-935d40f4e517', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Why are cooking utensils (pans, kettles) made of metals while their handles are made of plastic or wood?', 'Metals efficiently conduct thermal energy for cooking; plastic/wood handles insulate hands from heat.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('806abc74-298c-45ef-85e9-6a8ae3ce4f54', 'Metals are good conductors of heat, while plastic and wood are insulators that do not burn our hands', true, '14131004-4c02-4c54-aff0-935d40f4e517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5280781-75c6-4619-b4d8-981bc8476435', 'Metals are transparent', false, '14131004-4c02-4c54-aff0-935d40f4e517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6588b663-91e3-45c9-995f-a07a5e328539', 'Wood melts faster than metal', false, '14131004-4c02-4c54-aff0-935d40f4e517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b2606a5-957c-4f8a-af2b-4250ae5c2a69', 'Plastic conducts heat faster', false, '14131004-4c02-4c54-aff0-935d40f4e517');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68bf0435-16f7-4d07-b9ba-b9069884b424', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Which of the following is a natural, organic material?', 'Cotton is a natural plant cellulose fiber harvested from the seed bolls of the Gossypium plant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e07a5bc9-48ba-41d6-94c0-1e1d63366927', 'Cotton', true, '68bf0435-16f7-4d07-b9ba-b9069884b424');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3138613-f812-4ccd-a9bc-c709b0e32169', 'Nylon', false, '68bf0435-16f7-4d07-b9ba-b9069884b424');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37ff8925-a38d-4430-b90f-013df11a1f74', 'Polyester', false, '68bf0435-16f7-4d07-b9ba-b9069884b424');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54c1e129-99d8-4a9a-ac8a-24fabcf5127e', 'Plastic', false, '68bf0435-16f7-4d07-b9ba-b9069884b424');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('582b65b3-e7af-4509-aede-d8afe332056f', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Which liquid completely mixes (is miscible) with water?', 'Vinegar (aqueous acetic acid) is polar and forms a single homogenous miscible phase with water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e51d7ec7-cee1-44bf-931f-ec1759dbe131', 'Vinegar and Lemon juice', true, '582b65b3-e7af-4509-aede-d8afe332056f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baaff5b5-7eea-4395-bb5b-d62c8a9c1032', 'Kerosene oil', false, '582b65b3-e7af-4509-aede-d8afe332056f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c583b4a-fe3a-41e7-9f8a-dad984223c1c', 'Mustard oil', false, '582b65b3-e7af-4509-aede-d8afe332056f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1eb64d06-5c1a-41cd-b93c-b647410abca1', 'Coconut oil', false, '582b65b3-e7af-4509-aede-d8afe332056f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b795bade-828a-4d03-9983-4ba8457a08e3', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Why do shopkeepers usually prefer to keep sweets, biscuits, and toffees in transparent glass or plastic jars?', 'Optical transparency enables effortless visual inspection and attractive merchandising without opening containers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb98ccad-5891-4434-8cf5-dd6c6edd05cc', 'So that buyers can easily see and identify the items without opening the containers', true, 'b795bade-828a-4d03-9983-4ba8457a08e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ca0f082-c52f-4bf7-a747-88106eca0df6', 'To protect items from getting heavy', false, 'b795bade-828a-4d03-9983-4ba8457a08e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b629ebb1-1613-49b2-b121-488bd13e00a5', 'Because glass is the cheapest material', false, 'b795bade-828a-4d03-9983-4ba8457a08e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfd8b9fd-1f16-4a2d-85a1-fe1cfa6bbe49', 'Because glass absorbs all sugar', false, 'b795bade-828a-4d03-9983-4ba8457a08e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50727177-62e5-4c6f-b24c-a666091060fb', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Why do shiny iron rods or copper vessels lose their metallic lustre and appear dull and tarnished over time?', 'Surface oxidation and corrosion from ambient humidity and air form dull passivation films, masking intrinsic lustre.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cf05110-18b8-4973-a078-98bb8998cd89', 'They react chemically with moisture and atmospheric gases (oxygen) to form a thin surface oxide layer', true, '50727177-62e5-4c6f-b24c-a666091060fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12ea33f2-1a5f-4c88-afdb-1d0bbda0ff92', 'Light stops shining on old metals', false, '50727177-62e5-4c6f-b24c-a666091060fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8cc7022-a6cf-4c1f-aec3-ecac98e66507', 'The atoms inside metals disappear', false, '50727177-62e5-4c6f-b24c-a666091060fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('719dd0c7-4c07-4e1b-bc7c-aca4480302b2', 'Metals turn into wood', false, '50727177-62e5-4c6f-b24c-a666091060fb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7c1d550-d9dc-4706-a01f-f6e6c5b888c3', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'What happens when mustard oil or cooking oil is vigorously stirred into a glass of water?', 'Non-polar lipids are hydrophobic (immiscible) and have lower density (~0.92 g/cm³), floating atop water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4376150-ba56-4437-83d4-d41597c621fd', 'It forms a separate upper layer because oil is immiscible in water and less dense than water', true, 'f7c1d550-d9dc-4706-a01f-f6e6c5b888c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d05a9070-8a35-4a12-8a65-28d9aa68be43', 'It dissolves completely to form a transparent solution', false, 'f7c1d550-d9dc-4706-a01f-f6e6c5b888c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('925e70c9-a660-4c18-9ba9-51e6a8f93471', 'It turns into hard plastic', false, 'f7c1d550-d9dc-4706-a01f-f6e6c5b888c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd47878a-ab91-446b-998e-583b45a0cda3', 'It sinks to the bottom as heavy mud', false, 'f7c1d550-d9dc-4706-a01f-f6e6c5b888c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67912132-d3d5-429a-80a9-cd2aefb93376', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Why is a tumbler / drinking cup NEVER made out of a piece of cloth?', 'Woven textiles possess microscopic permeable pores between yarn threads through which liquids immediately leak.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40e26dda-3cc8-4f11-9bd2-51098e66649b', 'Cloth is porous with spaces between interwoven threads and cannot hold or retain liquid water', true, '67912132-d3d5-429a-80a9-cd2aefb93376');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc19483d-d266-41f2-9ef2-3e063e6f433d', 'Cloth is too heavy to lift', false, '67912132-d3d5-429a-80a9-cd2aefb93376');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96fe7502-c0bc-4a67-8ea3-b15e9aafb716', 'Cloth turns water into acid', false, '67912132-d3d5-429a-80a9-cd2aefb93376');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63a8a6cf-b2b4-4e8a-ad02-a8cc179d503b', 'Cloth is transparent', false, '67912132-d3d5-429a-80a9-cd2aefb93376');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4e274ed-a174-46d5-af3b-59b0f2402bf3', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Why is sorting materials into groups (Classification) scientifically useful in everyday life?', 'Taxonomic categorization organizes entities by shared physical/chemical traits, optimizing identification and retrieval.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34bfb55f-2e84-4d3f-9ac6-50b3b870f110', 'It allows systematic study of material properties, saves time in locating objects, and aids structured analysis', true, 'f4e274ed-a174-46d5-af3b-59b0f2402bf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f0c572e-e292-4ebf-af78-5200c36d8a88', 'It makes all objects colorful', false, 'f4e274ed-a174-46d5-af3b-59b0f2402bf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e265df2e-3091-4af6-bd3b-98101a9ab48e', 'It eliminates the need for cleaning', false, 'f4e274ed-a174-46d5-af3b-59b0f2402bf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ecc330b-830c-48d4-a93b-2f57aebe83a4', 'It prevents objects from breaking', false, 'f4e274ed-a174-46d5-af3b-59b0f2402bf3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d589f577-a69e-4e5d-bcd3-0fe65f2151bb', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Which of the following gases is dissolved in natural water bodies, enabling aquatic animals and fish to breathe?', 'Oxygen partially dissolves in water (~7-10 mg/L), which fish extract across gill membranes for aerobic respiration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3194b971-d294-4aea-81e1-d035f022162a', 'Dissolved Oxygen (O₂)', true, 'd589f577-a69e-4e5d-bcd3-0fe65f2151bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcd2fda3-a25c-4c68-9032-90afcaadbe43', 'Nitrogen gas', false, 'd589f577-a69e-4e5d-bcd3-0fe65f2151bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('854d34de-cce2-4bc2-aae7-d63880dd42b4', 'Hydrogen gas', false, 'd589f577-a69e-4e5d-bcd3-0fe65f2151bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25601c2b-61e3-49c1-a889-4f151d1c4f7a', 'Methane gas', false, 'd589f577-a69e-4e5d-bcd3-0fe65f2151bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fbc77d5-c270-4bad-b29f-5d493a6eb7a6', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'A material which can be easily compressed, scratched, or bent with fingers is classified as:', 'Materials with low structural indentation resistance and deformability are defined as soft materials.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d76a6962-6415-4356-bc2f-f3dd135296dd', 'Soft material (e.g., sponge, cotton)', true, '9fbc77d5-c270-4bad-b29f-5d493a6eb7a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab9ddcc0-0389-4ddd-8114-6416e5db5d90', 'Hard material', false, '9fbc77d5-c270-4bad-b29f-5d493a6eb7a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('512ccd31-f534-4950-9a39-60cff7418d40', 'Lustrous metal', false, '9fbc77d5-c270-4bad-b29f-5d493a6eb7a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e7ac3b5-61e7-46ba-8945-2ee3620af6b7', 'Opaque metal', false, '9fbc77d5-c270-4bad-b29f-5d493a6eb7a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f4018cb-e6e0-4eff-b188-cf74d767529e', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'A material which is difficult to compress, scratch, or deform is classified as:', 'Hardness is the measure of resistance to localized surface plastic deformation, scratching, or abrasion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b58f889-7dc9-4d6a-aa0f-bc1c3d99dade', 'Hard material (e.g., iron, stone, diamond)', true, '0f4018cb-e6e0-4eff-b188-cf74d767529e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f09baefc-469f-4ad2-a789-b320115794f8', 'Soft material', false, '0f4018cb-e6e0-4eff-b188-cf74d767529e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a19f1ad9-9d1b-4df2-afab-4a2d07a4dc55', 'Translucent material', false, '0f4018cb-e6e0-4eff-b188-cf74d767529e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab7edba7-e376-47f3-8e1e-c781881bedad', 'Soluble material', false, '0f4018cb-e6e0-4eff-b188-cf74d767529e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a543d6da-35ef-4e51-ad03-c56395340737', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Which pair of materials can be used to make a single everyday object like a chair?', 'The same functional object (chair) can be manufactured from various solid structural materials (timber, polymer, metal).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6494721-f7c9-4494-9208-1247f0103051', 'Wood, Plastic, or Iron', true, 'a543d6da-35ef-4e51-ad03-c56395340737');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6698ed0f-2a97-4de9-8217-bbf96d11fb0e', 'Water and Milk', false, 'a543d6da-35ef-4e51-ad03-c56395340737');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b7565c-f8aa-4869-a54e-b855a7b8ca62', 'Air and Kerosene', false, 'a543d6da-35ef-4e51-ad03-c56395340737');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8ec2cf9-e33d-4606-8159-08fc721670be', 'Oxygen and Sand', false, 'a543d6da-35ef-4e51-ad03-c56395340737');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35a8da91-094e-410f-8e72-3d71ec49f36c', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'What happens when a drop of oil falls on a clean sheet of white writing paper?', 'Oil fills the air voids between cellulose fibers, matching refractive indices and rendering the paper translucent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b20bedf6-3544-4d1a-aa34-ed4db4404b64', 'The paper becomes translucent at that spot, allowing light to pass through diffusely', true, '35a8da91-094e-410f-8e72-3d71ec49f36c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2667c479-6633-406d-a2dd-8c1dcac4e110', 'The paper catches fire instantly', false, '35a8da91-094e-410f-8e72-3d71ec49f36c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f49c47ea-3cc4-4518-b67b-da2f0998f9bd', 'The paper becomes 100% transparent like clear glass', false, '35a8da91-094e-410f-8e72-3d71ec49f36c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2313b992-f6e9-4a5e-945a-5f27f35bb04a', 'The paper dissolves into water', false, '35a8da91-094e-410f-8e72-3d71ec49f36c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8938559-ba3c-40ec-bea8-089778a12da1', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Which of the following pairs contains only LUSTROUS materials when freshly cut?', 'Metals like aluminium and gold exhibit shiny metallic reflectivity (lustre) on freshly exposed surfaces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c44f947-4d88-43f3-bd65-629a320a9e0d', 'Aluminium wire and Gold ring', true, 'd8938559-ba3c-40ec-bea8-089778a12da1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45476287-550b-44df-90f9-d972fe67ec08', 'Cardboard and Wooden block', false, 'd8938559-ba3c-40ec-bea8-089778a12da1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8204d28e-d801-42cc-95ec-83d99a806533', 'Chalk stick and Plastic toy', false, 'd8938559-ba3c-40ec-bea8-089778a12da1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5828f467-cb76-4cc4-bdfd-6e0b2a630225', 'Rubber eraser and Sandpaper', false, 'd8938559-ba3c-40ec-bea8-089778a12da1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1ec3865-26cf-47e1-babd-e256d09508b5', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Why do coins and iron nails sink in water whereas a large wooden log of greater mass floats?', 'Flotation depends on relative density (mass per unit volume), not on total absolute mass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a2cbdec-e4ec-4e81-8e3e-173061dd12d2', 'Density of iron is greater than water, while overall density of wood is lower than that of water', true, 'a1ec3865-26cf-47e1-babd-e256d09508b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c006f7c6-1b10-4b73-9a19-29fc51880bba', 'Iron is magnetic and pulled by Earth', false, 'a1ec3865-26cf-47e1-babd-e256d09508b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa3076b1-0613-4532-8d37-e1ce8504c1fa', 'Wood contains air balloons inside', false, 'a1ec3865-26cf-47e1-babd-e256d09508b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f12deb6-e287-40c8-a28d-6ca78ff0829b', 'Water rejects metal', false, 'a1ec3865-26cf-47e1-babd-e256d09508b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9cb05fb9-a15e-4799-b773-5d83ebb72fa1', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Which of the following is a man-made (synthetic) material?', 'Polyethylene is a synthetic petrochemical polymer produced via artificial chemical polymerization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d98a2ba-c674-48ac-a11b-1b9548021772', 'Polythene bag', true, '9cb05fb9-a15e-4799-b773-5d83ebb72fa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e14b1c4b-d759-477b-ab77-ee520e500b17', 'Silk saree', false, '9cb05fb9-a15e-4799-b773-5d83ebb72fa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c9ed87d-e78a-44a1-a0e0-cecebe7f77f6', 'Jute rope', false, '9cb05fb9-a15e-4799-b773-5d83ebb72fa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91a5a768-54df-41df-9c7f-137262588a8f', 'Leather belt', false, '9cb05fb9-a15e-4799-b773-5d83ebb72fa1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7adc4d87-614b-456b-90e3-d20778ee2faf', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Which of the following liquids is IMMISCIBLE with water?', 'Lipids (coconut oil) do not mix with polar water molecules and form a separate distinct meniscus layer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37b3d355-38b0-4b85-8aee-e170b6bd69d0', 'Coconut oil', true, '7adc4d87-614b-456b-90e3-d20778ee2faf');
