INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6160c524-f5a2-4128-bffe-6c650aecc252', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Hard', 'Why does a hollow plastic toy boat weighing 500 grams float on water, while a solid lead pellet weighing only 5 grams sinks immediately?', 'Archimedes'' principle: hollow geometry displaces volume with low mean density (mass/volume < 1 g/cm³), enabling flotation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('245963cc-4666-4e10-87ab-598621108d22', 'The boat encloses a large volume of air, making its overall average density much less than water, while dense lead has higher density than water', true, '6160c524-f5a2-4128-bffe-6c650aecc252');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58156da4-7997-4066-b3c0-1b9747f34150', 'Lead is poisonous to water', false, '6160c524-f5a2-4128-bffe-6c650aecc252');
