INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81052f0c-7622-40f6-afc0-2182f69e0598', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Hard', 'Why is sorting waste into Biodegradable (green bin) and Non-Biodegradable (blue bin) materials recommended at municipal levels?', 'Source segregation isolates organic matter for aerobic composting while diverting recyclable synthetic polymers and metals from landfills.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56f13154-2ec4-403c-ae55-f322cd568c30', 'It allows organic waste to be composted into soil manure and non-biodegradable plastics/metals to be recycled efficiently', true, '81052f0c-7622-40f6-afc0-2182f69e0598');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56e174a4-eafa-496a-9bb6-f50bade92f8e', 'To make waste colorful', false, '81052f0c-7622-40f6-afc0-2182f69e0598');
