INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c384181f-9c53-44e9-ade7-d3ca8c2db871', 'To hide garbage from sunlight', false, '81052f0c-7622-40f6-afc0-2182f69e0598');
