INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('895eef69-ac57-4b10-82bf-598c7fd01532', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Easy', 'What is the smallest natural number?', 'Natural numbers (counting numbers) start from 1, 2, 3, 4... Hence, 1 is the smallest natural number.', NOW()) ON CONFLICT DO NOTHING;
