INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fcf49b59-698d-4e2f-9b30-20b603f14f69', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'A vendor supplies 32 litres of milk to a hotel in the morning and 68 litres of milk in the evening. If the milk costs ₹ 45 per litre, how much money is due to the vendor per day?', 'Total cost = 45 × (32 + 68) = 45 × 100 = ₹ 4,500.', NOW()) ON CONFLICT DO NOTHING;
