INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15303641-58fa-401d-b4f2-8fbf9d74e2e0', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Which of the following operations is NOT closed for whole numbers?', 'Subtracting 5 - 8 = -3 (not a whole number) and dividing 5 ÷ 2 = 2.5 (not a whole number); hence not closed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef36bed4-2c91-4c64-bf3d-80b0e8e7596c', 'Subtraction and Division', true, '15303641-58fa-401d-b4f2-8fbf9d74e2e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c265421-126b-4130-857a-3b9a9181cc30', 'Addition and Multiplication', false, '15303641-58fa-401d-b4f2-8fbf9d74e2e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('055bcc75-f3a6-4a42-8b2f-286b1c1588bc', 'Addition only', false, '15303641-58fa-401d-b4f2-8fbf9d74e2e0');
