INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2059c08a-8e09-4bb0-87d4-cbb335bbbb33', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Which property is demonstrated by: (a × b) × c = a × (b × c)?', 'Regrouping factors does not change the final product (Associative Property).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4a4faf2-f12c-4d68-9c18-b9f0b40b4be0', 'Associative property of multiplication', true, '2059c08a-8e09-4bb0-87d4-cbb335bbbb33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4507dda7-d920-4417-8ad7-a7ab0f097bc6', 'Commutative property', false, '2059c08a-8e09-4bb0-87d4-cbb335bbbb33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('384214f5-17b1-41f1-906e-d97995e8df63', 'Distributive property', false, '2059c08a-8e09-4bb0-87d4-cbb335bbbb33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95ffbeb4-d606-4d8e-9963-ed9644000333', 'Closure property', false, '2059c08a-8e09-4bb0-87d4-cbb335bbbb33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c24c571-91ce-4061-82d7-ea451889db5d', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Study the pattern: 1 × 8 + 1 = 9; 12 × 8 + 2 = 98; 123 × 8 + 3 = 987. What is the value of 12345 × 8 + 5?', 'Following the arithmetic pattern, the resulting digits descend from 9 down to 5: 98765.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4eea766-4dee-4713-9036-086dc3793661', '98765', true, '0c24c571-91ce-4061-82d7-ea451889db5d');
