INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dccb3fbe-13cf-49ac-a638-b0ef951c955a', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Which of the following whole numbers can be arranged as a square pattern using dots?', 'Square numbers n² (2²=4, 3²=9, 4²=16, 5²=25) form symmetrical square dot lattices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ee854ec-a755-4007-80c1-766644b2d45b', '4, 9, 16, 25', true, 'dccb3fbe-13cf-49ac-a638-b0ef951c955a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a301ce5e-122c-4df8-801b-3406cbaaeb1a', '2, 3, 5, 7', false, 'dccb3fbe-13cf-49ac-a638-b0ef951c955a');
