INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99bbfbd8-3588-4fca-bd70-641bd5bc2535', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Which of the following whole numbers can be arranged as a triangular pattern using dots?', 'Triangular numbers T_n = n(n+1)/2 (T₂=3, T₃=6, T₄=10, T₅=15) form equilateral triangular dot grids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45754df8-4594-45bd-b1ad-c67d72a59d42', '3, 6, 10, 15', true, '99bbfbd8-3588-4fca-bd70-641bd5bc2535');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b40c1f3-e46f-4058-9861-e44ca643592c', '4, 9, 16, 25', false, '99bbfbd8-3588-4fca-bd70-641bd5bc2535');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a9cc4cd-11ed-4f66-85e1-0768bb8b7d4f', '2, 4, 8, 16', false, '99bbfbd8-3588-4fca-bd70-641bd5bc2535');
