INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d709fda3-7f6c-4a1b-b6c1-4645c6fec9b0', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Find the product: 4 × 166 × 25', '(4 × 25) × 166 = 100 × 166 = 16,600.', NOW()) ON CONFLICT DO NOTHING;
