INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc86efbe-339b-431d-a611-521bb1d53408', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Solve using suitable properties: 854 × 102', '854 × (100 + 2) = 85,400 + 1,708 = 87,108.', NOW()) ON CONFLICT DO NOTHING;
