INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7df93da2-055c-435a-89cc-8a5fbaaae210', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'If the product of two whole numbers is zero, what can we definitively conclude?', 'By the Zero Product Property: if a × b = 0, then a = 0, or b = 0, or a = b = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0299aca2-20ae-4ab0-8158-e88edb0695b8', 'At least one of the numbers (or both) must be zero', true, '7df93da2-055c-435a-89cc-8a5fbaaae210');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42740846-1971-45b4-8a40-0233d9cd5e80', 'Both numbers must be equal to 1', false, '7df93da2-055c-435a-89cc-8a5fbaaae210');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63d8fbaa-a6d3-4055-b4b5-2b414956ea77', 'Both numbers must be greater than 10', false, '7df93da2-055c-435a-89cc-8a5fbaaae210');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51928e08-5d8e-4dd0-b67e-3a19ff347d2c', 'Neither number can be zero', false, '7df93da2-055c-435a-89cc-8a5fbaaae210');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89b71b0d-3911-4066-9148-acad00b59460', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'If the product of two whole numbers is 1, what can we conclude?', 'In whole numbers, the only factors of 1 are 1 × 1 = 1; hence both numbers must be 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba5837e5-734d-4762-90e6-975cbfe0b37d', 'Both numbers must be equal to 1', true, '89b71b0d-3911-4066-9148-acad00b59460');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4808f6d-0770-4b52-b75f-30e722ff3711', 'One number is 0 and the other is 1', false, '89b71b0d-3911-4066-9148-acad00b59460');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b70eb9c6-27bb-4351-b227-69b4d928a65d', 'Both numbers can be any prime number', false, '89b71b0d-3911-4066-9148-acad00b59460');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bfe3984-d0e0-4dc3-96e4-e070b244747e', 'Their sum is 1', false, '89b71b0d-3911-4066-9148-acad00b59460');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8e18153-9b9c-4e90-bca8-365698b5b4e7', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ca5863a-eb73-4687-b283-d4c667330b36', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'a8e18153-9b9c-4e90-bca8-365698b5b4e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d94314b-bcaa-491b-a3c1-0b68f368aa06', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'a8e18153-9b9c-4e90-bca8-365698b5b4e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aafe503a-b95e-4397-ab10-25d3bea8579e', '(A) is true, but (R) is false.', false, 'a8e18153-9b9c-4e90-bca8-365698b5b4e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afec0939-7ca3-426b-a994-bd4698200554', '(A) is false, but (R) is true.', false, 'a8e18153-9b9c-4e90-bca8-365698b5b4e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31af233b-7765-4906-8375-eb91c970b12f', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Spot the IMPOSTER in the following mathematical properties of whole numbers:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70f2a35f-e051-41dd-9412-6b6728cc0018', 'Closure under Addition', false, '31af233b-7765-4906-8375-eb91c970b12f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c15630e-be7b-4b0d-92cb-9a7d74fc97d8', 'Commutativity of Multiplication', false, '31af233b-7765-4906-8375-eb91c970b12f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21188719-e764-44a3-8784-e0de8eab824c', 'Associativity of Addition', false, '31af233b-7765-4906-8375-eb91c970b12f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec20edc5-0f06-4ede-9b6e-2c4e32a0a08a', 'Commutativity of Subtraction', true, '31af233b-7765-4906-8375-eb91c970b12f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aad071d1-99d2-4c86-a602-bb1509cb14f7', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Find the value of: 125 × 40 × 8 × 25 using optimal grouping:', 'Group (125 × 8) × (40 × 25) = 1,000 × 1,000 = 1,000,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da4349df-c84a-41f6-a702-b8c3edfb8f7b', '10,00,000 (1 Million)', true, 'aad071d1-99d2-4c86-a602-bb1509cb14f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ddbf6a4-5510-4732-b0a2-05307883112d', '1,00,000', false, 'aad071d1-99d2-4c86-a602-bb1509cb14f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('380832e3-9766-447f-af9f-7c4d0ff28c38', '5,00,000', false, 'aad071d1-99d2-4c86-a602-bb1509cb14f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66a5c2ac-fb16-40c0-b36a-d68707c43a52', '10,000', false, 'aad071d1-99d2-4c86-a602-bb1509cb14f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd28c40e-082b-4184-8107-7b089cfbb8a8', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'If a = 5, b = 3, c = 2, verify the Distributive Property of multiplication over subtraction: a × (b - c) = ?', 'Distributive property holds over subtraction: a(b - c) = ab - ac.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d232bd2c-0ee3-4173-8307-3c0a0abe68c7', 'a × b - a × c = 5 × 3 - 5 × 2 = 15 - 10 = 5', true, 'dd28c40e-082b-4184-8107-7b089cfbb8a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28f9f265-6f83-4279-b0d3-f1aeea48cacc', 'a × b + a × c = 25', false, 'dd28c40e-082b-4184-8107-7b089cfbb8a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d880cec-5436-4964-89a8-18d7a30bb6c3', 'a × (b + c) = 25', false, 'dd28c40e-082b-4184-8107-7b089cfbb8a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16396b60-55e9-4ffe-8bba-3a930f3a3181', '10', false, 'dd28c40e-082b-4184-8107-7b089cfbb8a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37a02b32-01c3-414a-b198-10a7c4952835', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Match the following operations with their properties:
(a) 425 × 136 = 425 × (6 + 30 + 100) -> (i) Commutativity under multiplication
(b) 2 × 49 × 50 = 2 × 50 × 49          -> (ii) Commutativity under addition
(c) 80 + 2005 + 20 = 80 + 20 + 2005      -> (iii) Distributivity of multiplication over addition', 'a is Distributive property; b is Commutativity of multiplication; c is Commutativity of addition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c120e8e3-4bb4-4346-ac0c-12f4734713b3', 'a-(iii), b-(i), c-(ii)', true, '37a02b32-01c3-414a-b198-10a7c4952835');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abdd5d7e-e672-46b1-a3bf-8c40392ab571', 'a-(i), b-(ii), c-(iii)', false, '37a02b32-01c3-414a-b198-10a7c4952835');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edd7d40f-a504-4037-bedd-8ded45d3a0fc', 'a-(ii), b-(iii), c-(i)', false, '37a02b32-01c3-414a-b198-10a7c4952835');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48b48162-de3c-4ba6-8913-22fe8b272c9f', 'a-(iii), b-(ii), c-(i)', false, '37a02b32-01c3-414a-b198-10a7c4952835');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a795e036-f3fa-4010-a5c0-0caac4994e2d', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c193ded5-4230-442a-885b-e323918da615', 'Statements 1 and 3 only', true, 'a795e036-f3fa-4010-a5c0-0caac4994e2d');
