INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aef486f9-b819-4491-84ab-9e84582185c8', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Solve using pattern: 111 × 111 = 12,321. What is the value of 11,111 × 11,111?', 'Product of n ones with n ones ascends from 1 to n then descends back to 1: for n=5 -> 123454321.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6476e163-2e90-4a67-ae48-34331d94a470', '123,454,321', true, 'aef486f9-b819-4491-84ab-9e84582185c8');
