INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a94224ae-68d3-41ea-b98b-44001982e654', '12,345,432', false, 'aef486f9-b819-4491-84ab-9e84582185c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24ad9447-654a-4214-a126-ec78cd725e0b', '111,111,111', false, 'aef486f9-b819-4491-84ab-9e84582185c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a5cd86c-61b4-4ac6-bc05-c4e463eacb66', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'What is the sum of the first 10 odd natural numbers (1 + 3 + 5 + ... + 19)?', 'The sum of the first n odd natural numbers is always equal to n²; for n = 10, sum = 10² = 100.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c1557c9-94dd-461c-ada4-1debcac79a4f', '100 (= 10²)', true, '9a5cd86c-61b4-4ac6-bc05-c4e463eacb66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0043921-9151-4310-98aa-720c36067054', '90', false, '9a5cd86c-61b4-4ac6-bc05-c4e463eacb66');
