INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df4d141a-43c9-418a-92c4-be070d4f7215', '81', false, '9a5cd86c-61b4-4ac6-bc05-c4e463eacb66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9476f3d-c8f8-484d-a811-f256fd55d726', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'A school canteen charges ₹ 25 for lunch and ₹ 6 for milk each day. How much money does a student spend in 5 days on these items?', 'Total spent = 5 × (25 + 6) = 5 × 31 = ₹ 155.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fe67423-4f9b-4ae5-a20f-6fd562ec5892', '₹ 155', true, 'f9476f3d-c8f8-484d-a811-f256fd55d726');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb02ac45-e42f-4ea7-a218-2c3d06cabbbe', '₹ 150', false, 'f9476f3d-c8f8-484d-a811-f256fd55d726');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c975baa-fb41-4349-8df4-53adf71df617', '₹ 160', false, 'f9476f3d-c8f8-484d-a811-f256fd55d726');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6005eaac-f94d-4fa3-91bb-d0a02b00745b', '₹ 145', false, 'f9476f3d-c8f8-484d-a811-f256fd55d726');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ded23bc-988a-475f-9089-8688ea49bb2c', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Which of the following numbers can be represented as BOTH a line, a rectangle, a square, AND a triangle in dot geometry?', '36 is a square number (6²=36) and a triangular number T₈ = 8×9/2 = 36, and can form rectangles (4×9, 3×12, etc.) and a line (1×36).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93f96be8-603f-4f0a-b1b6-b8d522f0cf8b', '36', true, '4ded23bc-988a-475f-9089-8688ea49bb2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91cc4f96-7043-401a-8366-ba142275ccd3', '16', false, '4ded23bc-988a-475f-9089-8688ea49bb2c');
