INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50bc466f-49f5-4d1c-b865-6ce3b20c194c', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Find the value of (3845 × 5 × 782) + (769 × 25 × 218):', 'Notice 769 × 25 = 769 × 5 × 5 = 3845 × 5 = 19,225. Expression = 19,225 × (782 + 218) = 19,225 × 1,000 = 1,92,25,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08c7a50a-e7b5-4311-a231-ed84a482d7e8', '1,92,25,000', true, '50bc466f-49f5-4d1c-b865-6ce3b20c194c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95c442b9-187f-407c-b33f-91b26a15dbfe', '1,92,00,000', false, '50bc466f-49f5-4d1c-b865-6ce3b20c194c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78103e5f-314c-4b57-ac98-456ce844f67f', '1,85,25,000', false, '50bc466f-49f5-4d1c-b865-6ce3b20c194c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52d1db73-51c7-468b-acd5-bc7e46d47f55', '2,00,00,000', false, '50bc466f-49f5-4d1c-b865-6ce3b20c194c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cbe47a0a-57e0-417c-b64a-9a297f8b5fbd', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'If x is any whole number, which of the following expressions is ALWAYS equal to x?', '1 is the multiplicative identity: x × 1 = x for every whole number x.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ee24f54-f6b8-4523-88e9-3a661374283c', 'x × 1', true, 'cbe47a0a-57e0-417c-b64a-9a297f8b5fbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f05dfd0-c063-422b-905c-dbd78b6047ff', 'x ÷ 0', false, 'cbe47a0a-57e0-417c-b64a-9a297f8b5fbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('095bf91a-0b38-4e57-acfb-9305eba598c9', 'x - 1', false, 'cbe47a0a-57e0-417c-b64a-9a297f8b5fbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7c7b9d3-0ad8-4402-81c9-faaca9348b18', 'x + 1', false, 'cbe47a0a-57e0-417c-b64a-9a297f8b5fbd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('258bb128-cd78-420f-aaff-cba56c06d3fa', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Long ago, how did dogs live before deciding to find a master?', 'Dogs once lived as wild beasts in full freedom, being their own masters until one dog grew tired of hunting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c96d1500-b18c-49ff-bd5e-fb1718108cf0', 'They lived in freedom, like wolves, being their own masters', true, '258bb128-cd78-420f-aaff-cba56c06d3fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b800be52-d179-4b2d-9104-e5f0e8b9cdc8', 'They lived in zoos', false, '258bb128-cd78-420f-aaff-cba56c06d3fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b1bbff8-5437-4d5e-a6d2-4511d8b9f502', 'They were kept as farm cattle', false, '258bb128-cd78-420f-aaff-cba56c06d3fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25a99540-9217-411b-8dd6-ea580e9e2388', 'They lived only in cold caves', false, '258bb128-cd78-420f-aaff-cba56c06d3fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7768f60f-340b-430b-b0b4-325906eb1d2f', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Why was the dog sick and tired of his free, wild way of life?', 'The dog was tired of hunting alone and living in constant fear of more powerful predators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('365ab376-334e-486c-b829-7e62a959cfd3', 'He was tired of wandering about alone looking for food and being frightened of stronger animals', true, '7768f60f-340b-430b-b0b4-325906eb1d2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fbf5416-54b7-4659-8f46-8b85985d3dbb', 'He wanted to sleep in a warm house', false, '7768f60f-340b-430b-b0b4-325906eb1d2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a1d39ee-5227-4bee-b8dd-5ec815dec6df', 'He hated running in forests', false, '7768f60f-340b-430b-b0b4-325906eb1d2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78f41acf-927e-408f-b224-07991e60d354', 'He wanted to eat cooked meat only', false, '7768f60f-340b-430b-b0b4-325906eb1d2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08024f4a-42fd-4ee2-b31c-190c335d1119', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'What decision did the dog make to solve his problem?', 'He decided to seek service under the absolute strongest being on Earth to secure safety and food.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b2d7381-d39b-49b3-bc54-0d76f9adcaa6', 'To become the loyal servant of someone who was stronger than anyone on Earth', true, '08024f4a-42fd-4ee2-b31c-190c335d1119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('243f5caa-5e7e-4df1-8c88-ea484b54e33b', 'To hide underground forever', false, '08024f4a-42fd-4ee2-b31c-190c335d1119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8a1dab4-04d3-441a-a4ca-376aa7e8dea6', 'To become a vegetarian', false, '08024f4a-42fd-4ee2-b31c-190c335d1119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7decb5da-c492-4c5a-89fb-48df66dffe41', 'To fly in the sky like birds', false, '08024f4a-42fd-4ee2-b31c-190c335d1119');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ffd7641-9dbb-42aa-8fb4-04d8705aa5f7', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Who was the FIRST creature the dog chose as his master?', 'The dog first met a big, fierce wolf and agreed to serve him as master.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe3ea1a4-2812-4557-b5b0-ccc2655a50b3', 'A big, fierce Wolf (his kinsman)', true, '5ffd7641-9dbb-42aa-8fb4-04d8705aa5f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('174427b6-426d-4738-9f42-6260dc4097d0', 'A Bear', false, '5ffd7641-9dbb-42aa-8fb4-04d8705aa5f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28332080-3f9c-4f57-8f7a-30310304023b', 'A Lion', false, '5ffd7641-9dbb-42aa-8fb4-04d8705aa5f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3aa077c-09a6-45ec-b3f8-89b724b15da5', 'A Man', false, '5ffd7641-9dbb-42aa-8fb4-04d8705aa5f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cef574e-998d-4682-bf66-39edbb843a3d', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Why did the dog leave the Wolf?', 'Seeing the wolf terrified of the bear, the dog realized the wolf was not the strongest and left him.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1ba5bd9-28d1-40a2-b34c-4a14db2de88c', 'Because the Wolf was afraid of the Bear, who could eat them both', true, '4cef574e-998d-4682-bf66-39edbb843a3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85e12e32-f297-4bbc-99e0-c7023880d82d', 'The Wolf refused to share food', false, '4cef574e-998d-4682-bf66-39edbb843a3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21582da1-39b4-4b69-9cc0-e70b61697ddb', 'The Wolf bit the dog', false, '4cef574e-998d-4682-bf66-39edbb843a3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0e4e3d3-6ba1-4261-a480-cdc843377424', 'The Wolf ran away to another country', false, '4cef574e-998d-4682-bf66-39edbb843a3d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f720e7d7-539f-440d-9ef5-049437d07ff2', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Who was the SECOND master chosen by the dog?', 'After leaving the wolf, the dog offered his service to the Bear.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('119b5df6-14de-4332-a1cc-2f15ad9f1ac0', 'The Bear', true, 'f720e7d7-539f-440d-9ef5-049437d07ff2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc5ef9b9-75a1-4a88-a73f-e647d07725cf', 'The Wolf', false, 'f720e7d7-539f-440d-9ef5-049437d07ff2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8b88c05-57c3-4cc1-b32f-5b5608626781', 'The Lion', false, 'f720e7d7-539f-440d-9ef5-049437d07ff2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4749054f-5bb9-4f90-943b-894358a37454', 'The Elephant', false, 'f720e7d7-539f-440d-9ef5-049437d07ff2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed5bcb83-9d6b-4bb7-b6fa-f374a9e33144', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Why did the Bear run away into the deep forest while hunting a herd of cows?', 'The bear panicked upon hearing a lion, confessing that the Lion is the strongest beast in the forest.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b02f4aa-500f-4b69-b299-d1bb9a83f1b1', 'He heard the loud, terrifying roar of a Lion', true, 'ed5bcb83-9d6b-4bb7-b6fa-f374a9e33144');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f92913f-ddb0-497f-88bf-27b43212a7c5', 'A thunderstorm started', false, 'ed5bcb83-9d6b-4bb7-b6fa-f374a9e33144');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bca13922-398c-47a5-9d3a-bdf10bf0697a', 'The cows attacked the bear', false, 'ed5bcb83-9d6b-4bb7-b6fa-f374a9e33144');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d6709c1-a2af-4227-8c4b-db302f6affdc', 'He smelled fire in the woods', false, 'ed5bcb83-9d6b-4bb7-b6fa-f374a9e33144');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d269bd9-3d4f-4c50-aab3-09b2a0b09c42', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Who was the THIRD master chosen by the dog?', 'The dog left the bear and stayed with the Lion for a very long, comfortable time.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14b4c8f3-7498-4749-9a96-8a0650ee21d2', 'The Lion', true, '7d269bd9-3d4f-4c50-aab3-09b2a0b09c42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3412edc-683c-4f73-8f6d-db7015902289', 'The Bear', false, '7d269bd9-3d4f-4c50-aab3-09b2a0b09c42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6add6a2-40a4-4b14-90a6-d68ff13ca721', 'The Wolf', false, '7d269bd9-3d4f-4c50-aab3-09b2a0b09c42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55c1f3ed-a8dc-4d56-bfc3-3593a26154c7', 'The Tiger', false, '7d269bd9-3d4f-4c50-aab3-09b2a0b09c42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bad05a3a-f97a-40e4-8b0c-d9d88870f68a', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Why did the Lion suddenly stop, give a great roar, and strike the ground angrily while walking near a cliff?', 'The lion caught the scent of human presence and warned the dog that they must flee or face trouble.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cae54ec-48cf-4118-9f23-d47405cd6992', 'He smelled the scent of a Man approaching and warned the dog to run away', true, 'bad05a3a-f97a-40e4-8b0c-d9d88870f68a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff56c771-465f-4b54-99d5-c11b3db88ba9', 'He stepped on a sharp thorn', false, 'bad05a3a-f97a-40e4-8b0c-d9d88870f68a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1d28212-0f33-48c5-bb15-2d56d34ecd74', 'He saw an elephant coming', false, 'bad05a3a-f97a-40e4-8b0c-d9d88870f68a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dfbf54a-bcbb-46e3-af51-15b795423078', 'He was hungry', false, 'bad05a3a-f97a-40e4-8b0c-d9d88870f68a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3318999-4642-4bf7-ac0f-126aad310343', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Who did the dog finally choose as his ULTIMATE and permanent master?', 'Realizing that Man is stronger than all wild beasts, the dog chose Man as his ultimate master.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df8510ca-04fc-44f2-b825-73716202d090', 'Man (Human)', true, 'b3318999-4642-4bf7-ac0f-126aad310343');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('444a2940-029b-49cb-9657-10c7fc92efb3', 'The Lion', false, 'b3318999-4642-4bf7-ac0f-126aad310343');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5959501e-28af-4c3d-96aa-d9e2e1711e2d', 'The Tiger', false, 'b3318999-4642-4bf7-ac0f-126aad310343');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('396f6240-5c47-4131-9baf-adf6315fc4a0', 'The Elephant', false, 'b3318999-4642-4bf7-ac0f-126aad310343');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0129970b-e1e7-438d-a2ad-4acfe4ca51ba', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'In the poem ''The Kite'' by Harry Behn, how does a new kite look in the blue sky?', 'Poet Harry Behn opens: ''How bright on the blue is a kite when it''s new! With a dive and a dip it snaps its tail...''', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c402a290-a690-4b0f-9aeb-bb44484e75bf', 'Bright and beautiful as it dives and dips', true, '0129970b-e1e7-438d-a2ad-4acfe4ca51ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12051d3e-fdb9-4554-b2d2-c3b1515d2094', 'Dark and dusty', false, '0129970b-e1e7-438d-a2ad-4acfe4ca51ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('519697e3-8cb0-4d39-8763-d93d8d10b4b2', 'Heavy and clumsy', false, '0129970b-e1e7-438d-a2ad-4acfe4ca51ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfaa9fc9-0767-49ee-beec-221231b3aed1', 'Faded and torn', false, '0129970b-e1e7-438d-a2ad-4acfe4ca51ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef1c541f-72b3-481f-84ff-b653d59cea04', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'In the supplementary story ''The Friendly Mongoose'', why did the farmer bring a baby mongoose home?', 'The farmer wished to provide his infant son with a loyal companion as the child grew up.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fba6ab27-74f5-4900-a13e-e006727e9b10', 'To be a companion and protective pet for their infant son', true, 'ef1c541f-72b3-481f-84ff-b653d59cea04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc298265-3f08-4670-8aa0-9fcb180f1900', 'To sell it in the market', false, 'ef1c541f-72b3-481f-84ff-b653d59cea04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9a9dd88-4175-4986-b75c-9b2936f0f349', 'To guard the crops from thieves', false, 'ef1c541f-72b3-481f-84ff-b653d59cea04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c073df7-f1ed-4007-8289-b6b015fb70f1', 'To hunt birds in the garden', false, 'ef1c541f-72b3-481f-84ff-b653d59cea04');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43cf55df-a7f8-49da-b6d4-761b182b963d', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What is the chronological sequence of masters tested by the dog in his quest for the strongest leader?', 'The dog successively evaluated and transitioned from Wolf to Bear, then Lion, and finally Man.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91d9cf9c-caff-491a-9251-384814734ab8', 'Wolf -> Bear -> Lion -> Man', true, '43cf55df-a7f8-49da-b6d4-761b182b963d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3dcf6e5-7967-4ba0-8229-9d65a2e77d26', 'Bear -> Wolf -> Lion -> Man', false, '43cf55df-a7f8-49da-b6d4-761b182b963d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35434577-b37a-416a-a584-418e00aba447', 'Lion -> Bear -> Wolf -> Man', false, '43cf55df-a7f8-49da-b6d4-761b182b963d');
