INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4726f81-33db-45e6-8124-f6b182382f8e', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What figure of speech / simile is used in the poem ''The Kite'' to describe the flight of a kite soaring on a gust of wind?', 'The poet compares the effortless aerodynamic riding of the kite to a ship gliding over ocean waves with a single sail.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a362d705-a626-4387-a09e-b21184d118da', '"Then soars like a ship with only a sail"', true, 'c4726f81-33db-45e6-8124-f6b182382f8e');
