INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a26a8f4f-3129-48eb-bdcd-4205869ab245', '"Shines like a diamond"', false, 'c4726f81-33db-45e6-8124-f6b182382f8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9149c1c-4e0f-4928-9c51-73e5975a0c4b', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What makes a soaring kite become a ''raggedy thing'' according to Harry Behn''s poem?', 'The poem laments the pathetic sight of a trapped kite fluttering and tearing apart upon tree branches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('439f0139-8359-4295-a7e9-93611cd1806d', 'When its string gets tangled in the branches of a tree, flapping helplessly until torn', true, 'f9149c1c-4e0f-4928-9c51-73e5975a0c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87e0a89f-7879-4646-a360-a49593d61534', 'When it gets wet in rain', false, 'f9149c1c-4e0f-4928-9c51-73e5975a0c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2de34ce8-9a73-44ab-b8e9-f93e274115c5', 'When the sun sets', false, 'f9149c1c-4e0f-4928-9c51-73e5975a0c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91bd26d4-3e7f-4f52-8556-eceadeb04ddc', 'When children cut the tail', false, 'f9149c1c-4e0f-4928-9c51-73e5975a0c4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b07c7076-8912-46af-b274-3e5094948a00', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'In ''The Friendly Mongoose'', why did the farmer''s wife kill the loyal mongoose with a heavy water pot?', 'She jumped to a hasty, tragic conclusion without inspecting the cradle inside the room.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40192328-ad4e-41ee-b44c-556022388cde', 'She acted in hasty blind rage, seeing blood on the mongoose''s mouth and assuming it had harmed her sleeping baby', true, 'b07c7076-8912-46af-b274-3e5094948a00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57a0b6b8-3e62-4828-b22f-154a7579d2b6', 'The mongoose bit her leg', false, 'b07c7076-8912-46af-b274-3e5094948a00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09dac17b-0b88-483d-a141-8a7dd634adc7', 'The mongoose stole her food', false, 'b07c7076-8912-46af-b274-3e5094948a00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60108bf8-73bd-4b2e-97d2-e93bd1121592', 'She wanted a dog instead', false, 'b07c7076-8912-46af-b274-3e5094948a00');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f22f97ec-70e3-45d5-a007-f6ccb0dca181', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What did the farmer''s wife find inside the room AFTER she struck down the mongoose?', 'The brave mongoose had fought and killed the venomous snake to defend the sleeping infant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e612a15e-cfd7-4a82-a6b8-c8f624983a5e', 'Her baby sleeping peacefully in the cradle, and a black venomous cobra lying torn and bleeding dead on the floor', true, 'f22f97ec-70e3-45d5-a007-f6ccb0dca181');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('424e112c-33dd-41a4-9daa-7f4778b6f615', 'The baby was missing', false, 'f22f97ec-70e3-45d5-a007-f6ccb0dca181');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d37d9d8e-fe86-4681-8de8-00d8d9977d08', 'The cradle was on fire', false, 'f22f97ec-70e3-45d5-a007-f6ccb0dca181');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10bb66e1-055b-4f7f-adf7-1a3859cfda2c', 'Another snake inside the bed', false, 'f22f97ec-70e3-45d5-a007-f6ccb0dca181');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f31aa15-cbe6-4fb5-9772-38845fab3a76', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What profound moral lesson is taught by the Panchatantra tale ''The Friendly Mongoose''?', 'Hasty, unthinking emotional action leads to irreversible tragedy and lifelong remorse.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41ea1354-354e-4ceb-9339-a6d28d8a2a0a', 'Never act in hasty anger or make irreversible decisions without verifying facts first (''Look before you leap'')', true, '0f31aa15-cbe6-4fb5-9772-38845fab3a76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5896ebb-da93-4d70-8d6f-f6f7361a7f16', 'Never keep any animals as pets', false, '0f31aa15-cbe6-4fb5-9772-38845fab3a76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a21f4601-20a4-4a1d-9dd8-e2189ff6582f', 'Mongoose and snakes are best friends', false, '0f31aa15-cbe6-4fb5-9772-38845fab3a76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('448bda69-7d1a-4e61-9a69-8006c0033121', 'Women should never fetch water', false, '0f31aa15-cbe6-4fb5-9772-38845fab3a76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5ad3c5d-a7dc-4ccb-8349-7f0bc8d1e60f', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'Choose the correct meaning of the collective noun ''a herd'' as used in the chapter:', '''Herd'' denotes a collective assemblage of herbivorous domestic or wild ungulates (cows, deer, elephants).', NOW()) ON CONFLICT DO NOTHING;
