INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6880ac17-8587-4a5f-8d1c-ad4682f40bd9', 'A pack of wolves', false, 'c5ad3c5d-a7dc-4ccb-8349-7f0bc8d1e60f');
