INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45fb4aa5-24c0-4a5a-b2d9-13a7dd5a8024', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What is the collective noun used for a group of Wolves in English grammar?', 'In standard grammatical nomenclature, wolves hunt and travel socially in ''a pack''.', NOW()) ON CONFLICT DO NOTHING;
