INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fead1b4-04e3-4856-9530-6a865401f6f1', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What does the word ''Fierce'' mean in the context of the Wolf''s description?', '''Fierce'' describes an intimidating, menacing, and ferocious disposition.', NOW()) ON CONFLICT DO NOTHING;
