INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1542deec-ff63-4961-a2c0-a7724ed34d2e', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What does ''sniff the air'' mean as done by the Bear and the Lion in the forest?', 'Olfactory tracking enables wild animals to detect chemical pheromones and potential threats.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8523629b-0f2c-4781-af4c-24ac0103df99', 'To draw in air through the nose to detect the scent of other animals or danger', true, '1542deec-ff63-4961-a2c0-a7724ed34d2e');
