INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c929528c-38e1-4556-ab82-cf7ffd59c83f', 'To become someone''s loyal servant or employee', true, 'db88183d-6ecd-45af-936e-cba85ab62204');
