INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29a88b13-4a7d-45e1-b10e-5e8cbce9b5c2', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'How long did the dog serve the Lion before deciding to leave him?', 'The dog enjoyed a long, tranquil life with the Lion because no other beast dared offend the King of the forest.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7a5d0c6-f44e-4c9b-9389-da45691f79f1', 'For a long, long time with great peace and satisfaction, until a man passed by', true, '29a88b13-4a7d-45e1-b10e-5e8cbce9b5c2');
