INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ea7c2e7-5987-4853-8532-622880a5a879', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What does ''cliff'' mean in the line: ''They walked on until the lion stopped near a bare cliff''?', 'A cliff is an exposed vertical or near-vertical rocky precipice.', NOW()) ON CONFLICT DO NOTHING;
