INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22a73aed-a631-48a6-b013-9621a6b4f303', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'In ''The Kite'', when the wind falls, what happens to the kite''s string?', 'As aerodynamic lift drops, the tethering line loses tension, requiring the flier to wind the spool.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4938c617-1a89-4772-a84c-72226c93df2c', 'The string goes slack, and the child winds it back on the reel', true, '22a73aed-a631-48a6-b013-9621a6b4f303');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3def514-86d1-4d62-aa60-11aab9a6f426', 'The kite snaps into space', false, '22a73aed-a631-48a6-b013-9621a6b4f303');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6177a40f-335f-4891-ac49-ec583dd720c2', 'The kite turns into a bird', false, '22a73aed-a631-48a6-b013-9621a6b4f303');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3687e6a5-e3b1-44bb-867a-ef38f30075d9', 'The string catches fire', false, '22a73aed-a631-48a6-b013-9621a6b4f303');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('179d9e8f-ee6e-463c-85fc-6ba4c1db1016', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What is the relationship between dogs and humans since the events of the folk legend?', 'The tale concludes that canine domestication established an enduring bond of unparalleled fidelity to humanity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dca571b4-ba9e-4bf8-9202-02b12757260b', 'The dog serves Man faithfully and knows no other master to this day', true, '179d9e8f-ee6e-463c-85fc-6ba4c1db1016');
