INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8baf214-3b4a-41c5-b02a-9e3222a2982a', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '01fbee44-256b-417f-8e1d-9170f2caefd1');
