INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e294a677-65a3-46a1-9794-060cc102f890', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'Spot the IMPOSTER in the following list of collective nouns paired with animal groups:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abfd06aa-a482-4325-b2cd-7856a387464c', 'A pride of lions', false, 'e294a677-65a3-46a1-9794-060cc102f890');
