INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06729b30-98f6-4563-a529-f71c42a3c477', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'Match the following actions from the story with the emotions they express:
(a) Lion strikes ground and roars -> (i) Frantic panic & self-preservation
(b) Bear runs hastily into forest  -> (ii) Alarm at detecting human threat
(c) Dog wags tail before man       -> (iii) Submission & lifelong loyalty
(d) Wolf hides behind bushes      -> (iv) Fear of a larger predator (Bear)', 'Accurately maps behavioral physical cues of wild predators to their internal psychological motivations in the text.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15bca989-46b3-491f-864d-a255f2549179', 'a-(ii), b-(i), c-(iii), d-(iv)', true, '06729b30-98f6-4563-a529-f71c42a3c477');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('376242d1-41a2-4931-86ed-2dc88106fd62', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '06729b30-98f6-4563-a529-f71c42a3c477');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6b94097-461a-4b28-a2cf-9dbb5093ffc7', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '06729b30-98f6-4563-a529-f71c42a3c477');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd82e351-7374-49a6-8983-df0e594e2bd7', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '06729b30-98f6-4563-a529-f71c42a3c477');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb8f0f91-4972-4b7d-81a0-816b9806e48f', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'In the poem ''The Kite'', what is the poetic significance of comparing a kite''s flight to a ship riding the ''crest of a gust''?', 'Harry Behn evokes fluid dynamics: airflow lift beneath the paper sail mimics buoyant hydrodynamic waves beneath a schooner.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35c83783-2414-47b2-97f3-f3aeb6df90f2', 'It captures the majestic, buoyant rhythm of soaring high over atmospheric thermal currents, mimicking a nautical vessel riding ocean swells', true, 'eb8f0f91-4972-4b7d-81a0-816b9806e48f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81ca7474-b4d0-4758-b229-3acc1b02db02', 'It shows that kites can float on ocean water', false, 'eb8f0f91-4972-4b7d-81a0-816b9806e48f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8af3a24f-c7d1-4024-96e1-58d8d1e065ce', 'It means kites are made of heavy ship timber', false, 'eb8f0f91-4972-4b7d-81a0-816b9806e48f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('328a6031-1161-4d2b-95aa-73ec022f2d85', 'It proves kites are used as anchors', false, 'eb8f0f91-4972-4b7d-81a0-816b9806e48f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6ba5e96-e239-4f61-ade2-faf34249c958', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'Read the statements from ''The Friendly Mongoose'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d16493cd-68a5-496a-aeaf-0d59082e014d', 'Statements 1 and 2 only', true, 'c6ba5e96-e239-4f61-ade2-faf34249c958');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a85dba5e-01e1-43aa-a5b6-349adf084d16', 'Statements 2 and 3 only', false, 'c6ba5e96-e239-4f61-ade2-faf34249c958');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63b71ac5-fe6a-4f70-b48d-96f34af6ab81', 'Statements 1 and 3 only', false, 'c6ba5e96-e239-4f61-ade2-faf34249c958');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46ebb749-8cf7-4c9a-9b44-3cada8a55113', 'All Statements 1, 2, and 3', false, 'c6ba5e96-e239-4f61-ade2-faf34249c958');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa33daf9-c8c7-4229-8b05-231a516f78e4', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'Which of the following proverbs encapsulates the core theme of the folk tale ''How the Dog Found Himself a New Master!''?', 'The dog exercises pragmatic social intelligence to secure lifelong survival and protection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18dee1f2-1fae-41aa-8b45-81ab47be224d', '"Wisdom and survival lie in choosing the right alliances."', true, 'fa33daf9-c8c7-4229-8b05-231a516f78e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3943a952-549c-4c30-b668-9a9f5fbe83f2', '"A bird in hand is worth two in the bush."', false, 'fa33daf9-c8c7-4229-8b05-231a516f78e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('733ee68d-11a7-4eb7-90bf-f8587c91896e', '"Too many cooks spoil the broth."', false, 'fa33daf9-c8c7-4229-8b05-231a516f78e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa4a75c3-0b74-4817-ba6c-0e6fe82b443f', '"All that glitters is not gold."', false, 'fa33daf9-c8c7-4229-8b05-231a516f78e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5bbeef22-3fcb-40af-a169-7c8bf35a2be7', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'In grammar, what type of sentence is: ''Would you like to be my master, Wolf?''', 'A sentence that poses a direct question and ends with a question mark is an Interrogative sentence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b0bd913-62ff-4be4-9459-91c025ae36f4', 'Interrogative sentence', true, '5bbeef22-3fcb-40af-a169-7c8bf35a2be7');
