INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d010d64d-f09a-4167-8fe5-8e13e85c7722', 'Imperative sentence', false, '5bbeef22-3fcb-40af-a169-7c8bf35a2be7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5297e986-091d-4d01-9ffd-e0c6e0ab7bbc', 'Exclamatory sentence', false, '5bbeef22-3fcb-40af-a169-7c8bf35a2be7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('edb242c7-8af1-4616-a155-1a4d784e62df', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'What is the antonym of the word ''Fierce'' as used in describing gentle domestic animals?', 'The opposite of fierce/ferocious is tame, mild, docile, or gentle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0baee362-fb00-4f7a-8d6c-5bbbc39ac681', 'Tame / Gentle', true, 'edb242c7-8af1-4616-a155-1a4d784e62df');
