INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b7ffb8b-dbb7-45c4-849d-b1912645476c', 'Cruel', false, 'edb242c7-8af1-4616-a155-1a4d784e62df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10e1f9c9-7d7a-4339-851b-c1bf3587228f', 'Ferocious', false, 'edb242c7-8af1-4616-a155-1a4d784e62df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9558ed5f-51af-44b1-817f-14c5da9557fa', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'Why did the Lion express genuine fear of Man, despite being the crowned King of Beasts?', 'Human technology, fire, and strategic cooperative hunting historically subdued even the fiercest megafauna.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34311755-8225-45bc-9659-6674eabaef9f', 'Man''s superior intellect, tools, fire, and hunting weapons made humans the apex threat to all wild predators', true, '9558ed5f-51af-44b1-817f-14c5da9557fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d13c6120-14ac-4aaf-acca-b957e993346a', 'Humans are physically three times larger than lions', false, '9558ed5f-51af-44b1-817f-14c5da9557fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce7105ca-1297-406c-bf66-6c16998469d8', 'Humans have sharp claws', false, '9558ed5f-51af-44b1-817f-14c5da9557fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6ed132c-5fd9-4fad-ab1c-cd24a027946f', 'Humans can run faster than cheetahs', false, '9558ed5f-51af-44b1-817f-14c5da9557fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f49d206-b9f0-4cd5-a0ac-1c29c6c04466', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'What literary device is present in the line: ''With a dive and a dip it snaps its tail''?', 'The rhythmic repetition of the initial consonant sound /d/ in ''dive and dip'' is classical Alliteration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adb06848-4d40-41c0-8795-12f503f0bc92', 'Alliteration (repetition of ''d'' consonant sound)', true, '1f49d206-b9f0-4cd5-a0ac-1c29c6c04466');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa5e6c66-2d17-4c48-9f77-d5131af1b271', 'Hyperbole', false, '1f49d206-b9f0-4cd5-a0ac-1c29c6c04466');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9273e520-1ea7-4659-b65a-3871d0015b30', 'Personification', false, '1f49d206-b9f0-4cd5-a0ac-1c29c6c04466');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e2487b8-d492-4e75-a5ac-d4158b27303c', 'Irony', false, '1f49d206-b9f0-4cd5-a0ac-1c29c6c04466');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ff43fc9-4d40-4af7-b7be-5b3a63196e56', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'In ''The Friendly Mongoose'', what psychological bias caused the mother to believe the blood on the pet''s paws was her son''s?', 'Her pre-existing anxiety that ''a wild beast cannot be trusted'' made her instinctively assume guilt upon seeing blood.', NOW()) ON CONFLICT DO NOTHING;
