INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7634fac6-5300-4fb5-ae6f-a7df02cc367a', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'Complete the analogical relationship: Wolf is to Pack as Lion is to ______', 'Wolves associate in a pack; lions live and hunt collectively in a social family group called a ''pride''.', NOW()) ON CONFLICT DO NOTHING;
