INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00597aa4-a4dd-4e5c-bc0f-e68588afea16', 'The distance remains constant everywhere', false, '35663964-7ee1-4fbe-9893-273b659e499b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b18de05d-4333-4714-9c3d-e181fbb78626', 'It doubles at 45° latitude', false, '35663964-7ee1-4fbe-9893-273b659e499b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43d8e8c3-460d-42ec-b814-184d16a283ec', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'As the Earth rotates 360° on its axis in 24 hours, how many degrees of longitude does it rotate in ONE hour?', 'Earth rotates 360° in 24 hours = 15° longitude per 60 minutes = 1° longitude every 4 minutes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e2bac5e-03e3-4342-953f-d098e14f4489', '15° per hour (360° ÷ 24 = 15°)', true, '43d8e8c3-460d-42ec-b814-184d16a283ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e39d81e-5dd3-488b-8ab0-ef8e1fb2e7bf', '10° per hour', false, '43d8e8c3-460d-42ec-b814-184d16a283ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6768e96e-be1e-4fdb-b0a8-92a09d9376c9', '20° per hour', false, '43d8e8c3-460d-42ec-b814-184d16a283ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97e4ba17-ae52-45ad-aac8-e687ff6d7d31', '1° per hour', false, '43d8e8c3-460d-42ec-b814-184d16a283ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d85a795a-5275-4c81-a82e-dc5dc42b46e5', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'How much time difference corresponds to a difference of 1° of longitude?', '60 minutes ÷ 15° = 4 minutes per 1° change in terrestrial longitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('232d38aa-6dab-4c8c-b9ad-6aeb04da025e', '4 minutes', true, 'd85a795a-5275-4c81-a82e-dc5dc42b46e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27d11108-c1f4-4bec-93ac-1fd8a42b5f3e', '15 minutes', false, 'd85a795a-5275-4c81-a82e-dc5dc42b46e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39f77ce8-25bb-4815-812a-77954a3e19b6', '1 hour', false, 'd85a795a-5275-4c81-a82e-dc5dc42b46e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03225cf1-2c9c-4a0e-97ce-bbd9e1df72ac', '1 minute', false, 'd85a795a-5275-4c81-a82e-dc5dc42b46e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0dcbfc83-b6bb-4874-9686-4e85ef2d2165', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'What is the official Standard Meridian of India chosen to fix the Indian Standard Time (IST)?', '82°30'' E passing through Mirzapur/Prayagraj is the official Standard Meridian of India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e71570b-4dd2-4a11-9bd5-3dd4fd40251e', '82° 30'' E (82½° East passing through Mirzapur, UP)', true, '0dcbfc83-b6bb-4874-9686-4e85ef2d2165');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86ad3f97-6e17-401b-8133-80c4bed8d018', '80° E', false, '0dcbfc83-b6bb-4874-9686-4e85ef2d2165');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f78d5736-c327-4c14-b90f-286393835b14', '75° E', false, '0dcbfc83-b6bb-4874-9686-4e85ef2d2165');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b92832a9-82ec-4c9f-a0d7-a26e96f503e9', '90° E', false, '0dcbfc83-b6bb-4874-9686-4e85ef2d2165');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2934aa33-21bc-4377-af2d-50dd729a98d4', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'How much is Indian Standard Time (IST) ahead of Greenwich Mean Time (GMT)?', '82.5° × 4 minutes = 330 minutes = +5 hours 30 minutes ahead of Greenwich (0°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9337561e-d1da-44b4-ac8b-e910a8790a5d', '5 hours and 30 minutes ahead (+5:30)', true, '2934aa33-21bc-4377-af2d-50dd729a98d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5df9886-ed5c-45e6-965f-1e36fb69210d', '5 hours behind', false, '2934aa33-21bc-4377-af2d-50dd729a98d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f73e79a-c1e1-41c0-a8b7-64eefbb24bb5', '6 hours ahead', false, '2934aa33-21bc-4377-af2d-50dd729a98d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5a3ad29-c5af-4bf7-b4c3-126e043047b2', '4 hours and 30 minutes ahead', false, '2934aa33-21bc-4377-af2d-50dd729a98d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b308a25a-474c-4f35-936f-4dc23a4873d7', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'What is the approximate local time difference between Dwarka in Gujarat (western tip) and Dibrugarh in Assam (eastern tip) of India?', 'India spans ~30° longitude (68°7'' E to 97°25'' E); 30° × 4 min = 120 min ≈ 1 hr 45 min local solar time difference.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0af9592-54d6-4916-a34e-6726e0c7e143', 'About 1 hour and 45 minutes', true, 'b308a25a-474c-4f35-936f-4dc23a4873d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('742c3de1-d9c2-4236-bcda-c0b947482485', '30 minutes', false, 'b308a25a-474c-4f35-936f-4dc23a4873d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5fd4977-3029-46fe-98c9-df93eef2d269', '3 hours', false, 'b308a25a-474c-4f35-936f-4dc23a4873d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf529fbf-8c66-434b-8be0-253ba212ee75', 'Zero minutes', false, 'b308a25a-474c-4f35-936f-4dc23a4873d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b1009d8-6513-4a8e-a99e-8ba5d5774121', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'Why do places situated to the EAST of Greenwich gain time and are ahead of GMT?', 'Prograde west-to-east axial spin brings eastern longitudes into solar view ahead of western coordinates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('640f23a7-08c9-4a6a-aa14-c8b2cbdabb4f', 'Because Earth rotates on its axis from West to East, so eastern places experience sunrise earlier', true, '8b1009d8-6513-4a8e-a99e-8ba5d5774121');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c90380e1-f917-43fe-95c0-e1ecfd1e7a76', 'Because the Sun rotates from East to West', false, '8b1009d8-6513-4a8e-a99e-8ba5d5774121');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb341037-a5e1-4c34-85ed-728876099a55', 'Because Greenwich is at the highest mountain', false, '8b1009d8-6513-4a8e-a99e-8ba5d5774121');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78663078-4e20-421b-bc7d-67b72ebca51e', 'Because clocks run faster in the east', false, '8b1009d8-6513-4a8e-a99e-8ba5d5774121');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c17b8986-dfb9-4a57-8f48-e6036178ec72', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'Which of the following thermal zones lies between the Tropic of Cancer (23½° N) and the Arctic Circle (66½° N)?', 'The Temperate Zones experience moderate temperatures with neither extreme tropical heat nor polar freezing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b3c9c50-0add-4e68-b94b-60fda02fe6e2', 'North Temperate Zone (moderate climate)', true, 'c17b8986-dfb9-4a57-8f48-e6036178ec72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e112f590-d2d0-4d8b-91e4-991ba3047977', 'Torrid Zone', false, 'c17b8986-dfb9-4a57-8f48-e6036178ec72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('893d2b26-2835-48e0-ad72-64b27d6246ce', 'North Frigid Zone', false, 'c17b8986-dfb9-4a57-8f48-e6036178ec72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0933acd-1145-4227-93e9-3f28ec357bfd', 'South Temperate Zone', false, 'c17b8986-dfb9-4a57-8f48-e6036178ec72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91552d80-e584-47dc-8e9c-e3bf96155e1e', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'What happens to the size / circumference of the parallels of latitude as we move from the Equator towards the poles?', 'Parallels are small circles of radius R·cos(θ); circumference shrinks to zero at θ = 90° (poles).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a005cf08-b12f-4af7-ab3e-0035a13c93b5', 'The length of the parallel circles decreases progressively until they become mere points at the poles', true, '91552d80-e584-47dc-8e9c-e3bf96155e1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0654c07-4155-4813-a6b8-75a31e269a8c', 'They become larger', false, '91552d80-e584-47dc-8e9c-e3bf96155e1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0ce083f-c168-4575-a07c-e489b60a2881', 'They stay the exact same size', false, '91552d80-e584-47dc-8e9c-e3bf96155e1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32e10aa0-5af3-4607-bf3b-ac6da0915b98', 'They become straight lines', false, '91552d80-e584-47dc-8e9c-e3bf96155e1e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eba6f273-1ecb-4b5c-83e5-b9c47af74870', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'If it is 12:00 Noon at Greenwich (0°), what will be the local solar time at 15° East longitude?', '15° East is ahead by 15 × 4 min = 60 min (1 hour); 12:00 Noon + 1 hour = 1:00 PM.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9284d4d-0921-402c-b4fc-2f714b0e0802', '1:00 PM (13:00 hours)', true, 'eba6f273-1ecb-4b5c-83e5-b9c47af74870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dbb2ec4-1743-4a63-9708-4f5dee1204c9', '11:00 AM', false, 'eba6f273-1ecb-4b5c-83e5-b9c47af74870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4c64736-c2dd-4aa7-aa61-3f99e86adfe9', '2:00 PM', false, 'eba6f273-1ecb-4b5c-83e5-b9c47af74870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('213b4778-9ef2-4e11-bdf2-3dacf1015f9e', '12:15 PM', false, 'eba6f273-1ecb-4b5c-83e5-b9c47af74870');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0582fd70-3a0f-48ea-a271-1c7b0d0af4a9', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'If it is 12:00 Noon at Greenwich (0°), what will be the local solar time at 15° West longitude?', '15° West is behind by 15 × 4 min = 60 min (1 hour); 12:00 Noon - 1 hour = 11:00 AM.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5431e8a1-a2a6-4784-8bfc-d8d025c5c1b8', '11:00 AM', true, '0582fd70-3a0f-48ea-a271-1c7b0d0af4a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f004b37-705b-4431-abd7-02dbd96257f6', '1:00 PM', false, '0582fd70-3a0f-48ea-a271-1c7b0d0af4a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22dc69a7-b39c-4390-ac98-7570c6694aa6', '10:00 AM', false, '0582fd70-3a0f-48ea-a271-1c7b0d0af4a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d789233a-7e56-48b9-8d27-e6a86567b2e5', '12:15 PM', false, '0582fd70-3a0f-48ea-a271-1c7b0d0af4a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f689552a-eeab-4b6c-85b3-c491e4dbe995', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'How many standard time zones has the world been divided into, each spanning 15° of longitude?', 'The planet is divided into 24 standard 1-hour time zones of 15° longitudinal width each (24 × 15° = 360°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c30cfe40-cb5b-4370-854a-7ab38598ac38', '24 standard time zones', true, 'f689552a-eeab-4b6c-85b3-c491e4dbe995');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('153607ce-db1e-4eeb-80dc-bd36db101a8c', '12 time zones', false, 'f689552a-eeab-4b6c-85b3-c491e4dbe995');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4388280-fca6-4e90-84ac-508c8f0a4ee9', '36 time zones', false, 'f689552a-eeab-4b6c-85b3-c491e4dbe995');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a252378d-ffc4-4712-b4f8-ff9c888c2a28', '10 time zones', false, 'f689552a-eeab-4b6c-85b3-c491e4dbe995');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4681ab8-2460-40cf-ad78-ad01adc2f818', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'Which country has the maximum number of standard time zones (11 time zones) due to its vast longitudinal extent?', 'Spanning over 160° of longitude across Eurasia, Russia is divided into 11 official standard time zones.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b211dc3f-9003-4583-bf2d-0d3e017f01c3', 'Russia', true, 'c4681ab8-2460-40cf-ad78-ad01adc2f818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5cf25db-0e40-4b3d-88b2-9d8809e47617', 'India', false, 'c4681ab8-2460-40cf-ad78-ad01adc2f818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('498dee7c-9bb2-40d9-b618-6c450cc1d6c2', 'China', false, 'c4681ab8-2460-40cf-ad78-ad01adc2f818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e08f8af3-6553-433a-b0a2-2d1d7068a94c', 'Australia', false, 'c4681ab8-2460-40cf-ad78-ad01adc2f818');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85db9436-b56a-4240-a1fa-ec92ad92fce5', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'What is the angle of tilt of the Earth''s rotational axis from its orbital plane vertical?', 'Earth''s rotational axis maintains a fixed 23.5° obliquity tilt from the perpendicular to its ecliptic orbital plane.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('478560b0-40fd-4a6f-b301-524272859714', '23½° (making an angle of 66½° with its orbital plane)', true, '85db9436-b56a-4240-a1fa-ec92ad92fce5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e972ccb-d148-4e5a-8bf7-d5f46d8f3d8b', '45°', false, '85db9436-b56a-4240-a1fa-ec92ad92fce5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('189f3f1f-377e-4445-9413-310749dd1299', '0°', false, '85db9436-b56a-4240-a1fa-ec92ad92fce5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8dbd521-6874-42f6-a8af-67b35987f2ae', '90°', false, '85db9436-b56a-4240-a1fa-ec92ad92fce5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c723aab3-6cab-47c6-af8f-246f50b8aaa2', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'If a cricket match starts in London at 2:00 PM GMT, at what time will Indian viewers watch it live on TV (IST = GMT + 5:30)?', '2:00 PM + 5 hours 30 minutes = 7:30 PM IST in the evening.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbd2013-f67e-4998-9334-9ca8f0a9fcbd', '7:30 PM IST', true, 'c723aab3-6cab-47c6-af8f-246f50b8aaa2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4c04de7-662d-401e-987b-a49a1ad408a5', '5:30 PM IST', false, 'c723aab3-6cab-47c6-af8f-246f50b8aaa2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a39ecc00-270d-4a04-ba6d-2279a8aeb809', '8:00 PM IST', false, 'c723aab3-6cab-47c6-af8f-246f50b8aaa2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0818433-b39b-4348-ab8c-0c13b758b6a0', '12:30 PM IST', false, 'c723aab3-6cab-47c6-af8f-246f50b8aaa2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7f5b32f-0c9c-49fe-b80c-067bf102767b', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65df1436-a635-459d-a479-64efe6275dcc', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'f7f5b32f-0c9c-49fe-b80c-067bf102767b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04648ade-12e4-43ad-91a3-95c0d20d83e1', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'f7f5b32f-0c9c-49fe-b80c-067bf102767b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7af3b492-5ab7-48a5-a474-d568cac762f8', '(A) is true, but (R) is false.', false, 'f7f5b32f-0c9c-49fe-b80c-067bf102767b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81e12936-f4a7-4868-8791-b76ee3d67a1e', '(A) is false, but (R) is true.', false, 'f7f5b32f-0c9c-49fe-b80c-067bf102767b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d8aa5cb-ed6c-4beb-b428-bd51ab5bf320', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Spot the IMPOSTER in the following list of important parallels of latitude and their values:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c28b204a-4f68-4fda-8383-9854e27db020', 'Tropic of Cancer - 23½° N', false, '2d8aa5cb-ed6c-4beb-b428-bd51ab5bf320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00b93129-fc6b-4ea0-9715-b581f36c932f', 'Tropic of Capricorn - 23½° S', false, '2d8aa5cb-ed6c-4beb-b428-bd51ab5bf320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75cd9db3-5320-4a4d-8da0-81ebecb97434', 'Arctic Circle - 66½° N', false, '2d8aa5cb-ed6c-4beb-b428-bd51ab5bf320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2f906d8-9c7c-461b-97d8-31c21faf588d', 'Antarctic Circle - 66½° N', true, '2d8aa5cb-ed6c-4beb-b428-bd51ab5bf320');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6299991-54eb-40fa-9860-09b8e7ce204c', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'A ship captain reports his position as 0° Latitude and 0° Longitude. Where is this vessel located on Earth?', 'The intersection of the Equator (0° Lat) and the Prime Meridian (0° Long) is located in the Gulf of Guinea (Null Island) in the Atlantic Ocean.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7bf5949-e9fb-45b6-8523-f1d9edc14535', 'In the Atlantic Ocean off the coast of West Africa (Gulf of Guinea)', true, 'c6299991-54eb-40fa-9860-09b8e7ce204c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0061ce3-4d64-4137-8b40-1feae835a0fe', 'In the middle of the Indian Ocean', false, 'c6299991-54eb-40fa-9860-09b8e7ce204c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af3127d8-7bbd-498c-9461-47554cbefa58', 'On the top of Mount Everest', false, 'c6299991-54eb-40fa-9860-09b8e7ce204c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b78e581-c94e-4881-ad93-cc9ccfa52537', 'In the Pacific Ocean', false, 'c6299991-54eb-40fa-9860-09b8e7ce204c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b4c50e6-3461-4418-b54c-0a0579e0a3da', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Why does the mid-day sun NEVER shine directly overhead on any latitude beyond the Tropic of Cancer and Tropic of Capricorn?', 'Declination of the Sun is limited by Earth''s 23.5° axial obliquity; hence zenith sun is impossible at latitudes > 23.5°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad68a7bf-8408-48e1-9d74-775259bbf1c3', 'Because the maximum axial tilt of the Earth is 23½°, so subsolar point oscillations are bounded strictly between 23½° N and 23½° S', true, '2b4c50e6-3461-4418-b54c-0a0579e0a3da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8bcfa3a-4af6-4fb0-ae7c-07a18234c951', 'Because poles are too cold for sunlight', false, '2b4c50e6-3461-4418-b54c-0a0579e0a3da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('687c50d5-5b20-4bc8-a6b4-e1a60bc6ea25', 'Because Earth is flat at the edges', false, '2b4c50e6-3461-4418-b54c-0a0579e0a3da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2daed67e-6d53-4b8b-88ea-f934a28c545d', 'Because the Sun shrinks in winter', false, '2b4c50e6-3461-4418-b54c-0a0579e0a3da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5fe53dc-0370-4857-9f89-3aa4fd050bde', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Match Column I (Locations) with Column II (Coordinates):
(a) Equator          -> (i) 90° S
(b) South Pole       -> (ii) 0° Longitude
(c) Prime Meridian   -> (iii) 0° Latitude
(d) 180° Meridian    -> (iv) International Date Line line of longitude', 'Equator = 0° Lat; South Pole = 90° S; Prime Meridian = 0° Long; 180° Meridian = Antimeridian/Date Line.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('217316a3-0662-4489-b788-2f5d7f9c3596', 'a-(iii), b-(i), c-(ii), d-(iv)', true, 'b5fe53dc-0370-4857-9f89-3aa4fd050bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46dd13da-9e6e-45f9-b54e-bdf03178d100', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'b5fe53dc-0370-4857-9f89-3aa4fd050bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23f9ada4-a5d5-43f3-a47f-61e617be2229', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b5fe53dc-0370-4857-9f89-3aa4fd050bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be538011-36fa-45b9-8c6d-1231218cf942', 'a-(ii), b-(iv), c-(i), d-(iii)', false, 'b5fe53dc-0370-4857-9f89-3aa4fd050bde');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad4b198c-02fa-496d-9fb8-edff2859abf2', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e2fefd9-f655-425e-bbc9-d0739c78c544', 'Statements 1 and 2 only', true, 'ad4b198c-02fa-496d-9fb8-edff2859abf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cbff9d5-ed4d-47d4-ad3c-1eefc833e08c', 'Statements 2 and 3 only', false, 'ad4b198c-02fa-496d-9fb8-edff2859abf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66c958e9-e8fc-4ee3-9a75-bb17c36f2920', 'Statements 1 and 3 only', false, 'ad4b198c-02fa-496d-9fb8-edff2859abf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d2d8685-d508-4b79-b92a-4b1353dfca48', 'All Statements 1, 2, and 3', false, 'ad4b198c-02fa-496d-9fb8-edff2859abf2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1cf7968-effe-4e87-8188-99bc72ceaf9d', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Town X is located at 30° East longitude and Town Y is located at 60° West longitude. What is the total time difference between Town X and Town Y?', 'Longitudinal separation = 30° + 60° = 90°. Time difference = 90 × 4 min = 360 minutes = 6 hours.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('033b8307-8913-49fc-a02c-a411816e787b', '6 hours (90° total difference × 4 min = 360 min)', true, 'c1cf7968-effe-4e87-8188-99bc72ceaf9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab60a1d6-d2f2-4422-9437-9b8dc15e4472', '2 hours', false, 'c1cf7968-effe-4e87-8188-99bc72ceaf9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('660a6cbe-e243-495d-8127-dfddd124b06b', '4 hours', false, 'c1cf7968-effe-4e87-8188-99bc72ceaf9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b178c073-2e5e-422e-9a30-acdc6d69b95e', '8 hours', false, 'c1cf7968-effe-4e87-8188-99bc72ceaf9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0aa49ae-8557-49e6-a927-50e74f387e5a', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Why did India adopt ONE single Standard Time (IST) across the entire country instead of multiple local time zones?', 'A uniform national reference meridian (82.5° E) harmonizes logistical schedules across transport, administration, and commerce.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88646c4f-bafb-44d1-8573-b5e931f5f5bd', 'To avoid immense confusion in nationwide railway timetables, flights, banking, and television broadcasts', true, 'b0aa49ae-8557-49e6-a927-50e74f387e5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b27d2aa3-7e7b-4278-ae82-44e4665519f9', 'Because India is only 1 km wide', false, 'b0aa49ae-8557-49e6-a927-50e74f387e5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba57c541-ac8f-49cf-82ad-9a220acee33c', 'Because clocks cannot be changed', false, 'b0aa49ae-8557-49e6-a927-50e74f387e5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f0bc295-33d6-406f-97fe-641a09c92f14', 'Because the Sun rises at the same minute across India', false, 'b0aa49ae-8557-49e6-a927-50e74f387e5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1b5c9e0-e548-4942-9ee9-63b5df77f1cd', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Both Tonga Islands (in Pacific Ocean) and Mauritius Islands (in Indian Ocean) are situated on 20° S latitude. How do navigators distinguish their exact positions?', 'A 2D coordinate fix requires BOTH latitude (Y-axis parallel) AND longitude (X-axis meridian) coordinates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b89e889-a245-4937-89e0-926daaabb666', 'By referencing their specific longitudes (East or West of the Prime Meridian)', true, 'b1b5c9e0-e548-4942-9ee9-63b5df77f1cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c34164a2-c67d-4ed3-a732-7c1234366363', 'By looking at ocean waves', false, 'b1b5c9e0-e548-4942-9ee9-63b5df77f1cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2b059e3-a51d-4372-b100-ee57d817289b', 'By measuring air temperature only', false, 'b1b5c9e0-e548-4942-9ee9-63b5df77f1cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23f040db-8eab-4713-bad0-445ffa20e759', 'They cannot be distinguished', false, 'b1b5c9e0-e548-4942-9ee9-63b5df77f1cd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6d4c1b3-d97b-4fb6-b0b4-78da2a99ad30', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'What is the key difference between the Torrid Zone and the Frigid Zone regarding insolation?', 'Lambert''s cosine law: vertical rays deliver concentrated flux per unit area, while acute slanting rays dilute radiative heating.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab5bd573-fc9d-4f4c-a907-a86120ae2f71', 'Torrid Zone receives direct vertical solar rays with high energy density; Frigid Zone receives oblique slanting rays spread over vast areas with severe reflection', true, 'd6d4c1b3-d97b-4fb6-b0b4-78da2a99ad30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e5d88dc-8b9a-47be-a9da-5ca814d32e14', 'Torrid Zone has no night', false, 'd6d4c1b3-d97b-4fb6-b0b4-78da2a99ad30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9aca5774-8d6a-4f81-b95d-4bd196f1222e', 'Frigid Zone is closer to the Sun', false, 'd6d4c1b3-d97b-4fb6-b0b4-78da2a99ad30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43da553f-09a4-4ffc-b355-80545be6877e', 'Torrid Zone is in outer space', false, 'd6d4c1b3-d97b-4fb6-b0b4-78da2a99ad30');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db170889-1d1a-4a6d-b7b0-477e69c0d222', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Which of the following continents does the Equator, Tropic of Cancer, AND Tropic of Capricorn ALL pass through?', 'Africa is the only continent on Earth traversed by all three primary latitude lines: Cancer (N), Equator, and Capricorn (S).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c528671f-9308-420b-883c-1928632c3173', 'Africa', true, 'db170889-1d1a-4a6d-b7b0-477e69c0d222');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f496c9b5-7073-4721-8e03-440ba94f6bc9', 'Asia', false, 'db170889-1d1a-4a6d-b7b0-477e69c0d222');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('242d42de-63fa-4e40-987b-1939e6bcb0d3', 'South America', false, 'db170889-1d1a-4a6d-b7b0-477e69c0d222');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('259d9453-8ef8-4002-bf87-88134de6611e', 'Australia', false, 'db170889-1d1a-4a6d-b7b0-477e69c0d222');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6f1025b-37c7-4ccf-b235-b765d9fd50d1', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'If a traveler crosses the 180° International Date Line traveling from West to East (e.g. from Japan to USA), what calendar adjustment must they make?', 'Crossing eastward into the Western Hemisphere steps back across the antimeridian, repeating that calendar date.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f0a0dbc-f1ca-43de-bbce-822d23ef3c83', 'They repeat one calendar day (gain a day / subtract 24 hours from date)', true, 'f6f1025b-37c7-4ccf-b235-b765d9fd50d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d69210a-d62c-4b9d-8f24-e0b87859c3c5', 'They lose one calendar day (add 24 hours)', false, 'f6f1025b-37c7-4ccf-b235-b765d9fd50d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd03118b-517e-493a-9430-800829f3f5d5', 'Clocks stop working', false, 'f6f1025b-37c7-4ccf-b235-b765d9fd50d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d5ee788-09ba-4303-8eaa-2495553319b3', 'They travel 100 years into the future', false, 'f6f1025b-37c7-4ccf-b235-b765d9fd50d1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c78173e0-f22d-4914-89f8-d7cfe560bbb2', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'भाषा की वह सबसे छोटी मूल ध्वनि जिसके और टुकड़े (खंड) नहीं किए जा सकते, उसे क्या कहते हैं?', 'वर्ण (जैसे अ, आ, क, ख) भाषा की अविभाज्य लघुतम इकाई है जिसके खंड नहीं किए जा सकते।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86a74b37-71b9-4680-b1e2-ab393d58c911', 'वर्ण या अक्षर (Letter / Phoneme)', true, 'c78173e0-f22d-4914-89f8-d7cfe560bbb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab28417b-dd0d-45ce-a1f2-7b72ee23e8c6', 'शब्द', false, 'c78173e0-f22d-4914-89f8-d7cfe560bbb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee7de177-39ae-4d79-a382-d05a42deea2f', 'वाक्य', false, 'c78173e0-f22d-4914-89f8-d7cfe560bbb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adeaf02b-d161-4860-9fb0-e3bc58d42067', 'पद', false, 'c78173e0-f22d-4914-89f8-d7cfe560bbb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9570e53b-a88e-4359-a803-69edc7dab803', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'वर्णों के व्यवस्थित और क्रमबद्ध समूह को क्या कहते हैं?', 'वर्णों का मानक क्रमबद्ध एवं व्यवस्थित समूह ''वर्णमाला'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42675117-8ccc-438d-a0f4-75fb12f9653a', 'वर्णमाला (Alphabet)', true, '9570e53b-a88e-4359-a803-69edc7dab803');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('934d0595-07a7-4b0e-935b-e3654753b230', 'शब्दकोश', false, '9570e53b-a88e-4359-a803-69edc7dab803');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad69020f-7b8b-48c3-af97-10842cc3183b', 'वाक्य', false, '9570e53b-a88e-4359-a803-69edc7dab803');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('342b8ead-34fa-4610-8e5b-984721708b88', 'व्याकरण', false, '9570e53b-a88e-4359-a803-69edc7dab803');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e578e0bf-f2c2-4943-a21b-4b0f2163c672', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'हिंदी वर्णमाला में वर्णों को मुख्य रूप से कितने भागों (भेदों) में बाँटा गया है?', 'हिंदी वर्णमाला के मुख्य दो भेद हैं: 1. स्वर (Vowels) तथा 2. व्यंजन (Consonants)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebfe4dc1-92e1-409e-9a54-aa889b4c03e7', 'दो भागों में (स्वर और व्यंजन)', true, 'e578e0bf-f2c2-4943-a21b-4b0f2163c672');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b79df4e9-fdae-42a0-b9ae-35e44c09301c', 'तीन भागों में', false, 'e578e0bf-f2c2-4943-a21b-4b0f2163c672');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57ae85e3-e25a-409a-97dc-a0a343930414', 'चार भागों में', false, 'e578e0bf-f2c2-4943-a21b-4b0f2163c672');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fae2a6b0-9006-4f3f-85c1-c8c60b09b9ce', 'पाँच भागों में', false, 'e578e0bf-f2c2-4943-a21b-4b0f2163c672');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41a991b7-7a2f-4de1-b63b-305e4a93a101', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'जिन वर्णों का उच्चारण स्वतंत्र रूप से बिना किसी अन्य वर्ण की सहायता से होता है, उन्हें क्या कहते हैं?', 'स्वर निर्बाध एवं स्वतंत्र रूप से उच्चरित होने वाली ध्वनियाँ हैं (अ, आ, इ, ई, उ, ऊ, ऋ, ए, ऐ, ओ, औ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d52861c-82c8-4c2a-93e0-3dd5c4247437', 'स्वर (Vowels)', true, '41a991b7-7a2f-4de1-b63b-305e4a93a101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c3d9948-51fd-4fad-9ff2-808287c6d22f', 'व्यंजन', false, '41a991b7-7a2f-4de1-b63b-305e4a93a101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47c1e0a7-d9cf-49ae-8345-1ce8125f3776', 'संयुक्त व्यंजन', false, '41a991b7-7a2f-4de1-b63b-305e4a93a101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4262a5b-eac9-4f9e-9710-88b372c6d93e', 'अयोगवाह', false, '41a991b7-7a2f-4de1-b63b-305e4a93a101');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a86213fd-a0fe-4d80-9b31-8c434f220157', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'मानक हिंदी वर्णमाला में कुल कितने मूल स्वर (Vowels) होते हैं?', 'हिंदी वर्णमाला में 11 स्वर होते हैं: अ, आ, इ, ई, उ, ऊ, ऋ, ए, ऐ, ओ, औ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f71ca5c5-aa32-4ab8-a43b-9924f4c00668', '11 स्वर', true, 'a86213fd-a0fe-4d80-9b31-8c434f220157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e87fff4b-5bf5-4d75-af9b-0834ba98154c', '13 स्वर', false, 'a86213fd-a0fe-4d80-9b31-8c434f220157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cad5e0f9-677c-415b-9d2a-a9641339186a', '10 स्वर', false, 'a86213fd-a0fe-4d80-9b31-8c434f220157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af7be482-5e40-4750-b8d6-094b80bbfe20', '12 स्वर', false, 'a86213fd-a0fe-4d80-9b31-8c434f220157');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09218fd2-0107-49b7-bf9d-f33de3e32d24', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'जिन वर्णों का उच्चारण स्वरों की सहायता से किया जाता है, उन्हें क्या कहते हैं?', 'व्यंजनों के पूर्ण उच्चारण हेतु स्वर (मुख्यतः ''अ'') का संयोग अनिवार्य होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03b35a28-d041-4582-bca8-7726d88dd8ed', 'व्यंजन (Consonants)', true, '09218fd2-0107-49b7-bf9d-f33de3e32d24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b01b3ae3-24c5-4910-8d1e-d22031352c7b', 'स्वर', false, '09218fd2-0107-49b7-bf9d-f33de3e32d24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('190140f7-b724-4265-a69a-1d3ca197906a', 'मात्रा', false, '09218fd2-0107-49b7-bf9d-f33de3e32d24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b48d86cc-dff9-462e-bf75-2ea2e3374427', 'अनुस्वार', false, '09218fd2-0107-49b7-bf9d-f33de3e32d24');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8cb60c1c-8f37-4f26-baf0-9c5157ddc704', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'उच्चारण में लगने वाले समय (मात्रा) के आधार पर स्वर के कितने भेद होते हैं?', 'मात्रा काल के आधार पर स्वर तीन प्रकार के होते हैं: ह्रस्व (1 मात्रा), दीर्घ (2 मात्रा), तथा प्लुत (3 मात्रा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('233a1ded-92e1-4480-9ba8-06afcc45661f', 'तीन भेद (ह्रस्व स्वर, दीर्घ स्वर, प्लुत स्वर)', true, '8cb60c1c-8f37-4f26-baf0-9c5157ddc704');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69a41214-705a-4ce4-95fd-8d85463cb2a5', 'दो भेद', false, '8cb60c1c-8f37-4f26-baf0-9c5157ddc704');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d169765f-977a-413c-86ce-db13e069b917', 'चार भेद', false, '8cb60c1c-8f37-4f26-baf0-9c5157ddc704');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f65455e0-65ea-4abe-9ce9-3cadc821ae10', 'पाँच भेद', false, '8cb60c1c-8f37-4f26-baf0-9c5157ddc704');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0cb47a5-7a2a-4b52-8b01-c6d77b4cca84', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'हिंदी वर्णमाला में ह्रस्व स्वर (Short Vowels) कुल कितने हैं?', 'ह्रस्व स्वर (मूल स्वर) जिनके उच्चारण में न्यूनतम एक मात्रा का समय लगता है, संख्या में 4 हैं: अ, इ, उ, ऋ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f505c02c-bc58-4ec2-ae9d-d93bd40ff5df', 'चार (अ, इ, उ, ऋ)', true, 'c0cb47a5-7a2a-4b52-8b01-c6d77b4cca84');
