INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('922e2c49-5de1-4c3a-a299-726c7e5ff8b0', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'हिंदी वर्णमाला में दीर्घ स्वर (Long Vowels) कुल कितने हैं?', 'दीर्घ स्वर जिनके उच्चारण में ह्रस्व से दोगुना समय लगता है, संख्या में 7 हैं: आ, ई, ऊ, ए, ऐ, ओ, औ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e026c83d-09c7-48ca-91e2-4536c08db1d9', 'सात (आ, ई, ऊ, ए, ऐ, ओ, औ)', true, '922e2c49-5de1-4c3a-a299-726c7e5ff8b0');
