INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f127bc98-4afd-4cdc-a582-7e301cc7a938', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'अं (ं) और अः (ः) को हिंदी व्याकरण में क्या कहा जाता है?', 'अं (अनुस्वार) और अः (विसर्ग) न तो पूर्ण स्वर हैं और न पूर्ण व्यंजन; अतः इन्हें ''अयोगवाह'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eea41c86-23f7-40a0-8ef1-d17ac2f77326', 'अयोगवाह (अनुस्वार और विसर्ग)', true, 'f127bc98-4afd-4cdc-a582-7e301cc7a938');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85551bb7-1d64-436a-8446-3a2c3526853f', 'मूल स्वर', false, 'f127bc98-4afd-4cdc-a582-7e301cc7a938');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0a94884-642d-4ced-a6c8-7e87c25a0074', 'स्पर्श व्यंजन', false, 'f127bc98-4afd-4cdc-a582-7e301cc7a938');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7f27d86-ce80-4bc1-9b6a-ce7778c923f1', 'अन्तःस्थ व्यंजन', false, 'f127bc98-4afd-4cdc-a582-7e301cc7a938');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4dd72c6-b99e-42f6-a29f-7d4b1b63d263', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'हिंदी में संयुक्त व्यंजन (क्ष, त्र, ज्ञ, श्र) की कुल संख्या कितनी है?', 'दो भिन्न व्यंजनों के परस्पर मेल से बनने वाले 4 संयुक्त व्यंजन हैं: क्ष (क्+ष), त्र (त्+र), ज्ञ (ज्+ञ), श्र (श्+र)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ebcf195-e1f6-4d95-ba91-60f14c897959', 'चार (4 संयुक्त व्यंजन)', true, 'f4dd72c6-b99e-42f6-a29f-7d4b1b63d263');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26a0f786-1d70-461c-ae98-5e0125a8e59c', 'तीन', false, 'f4dd72c6-b99e-42f6-a29f-7d4b1b63d263');
