INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58452662-d228-421b-ad35-7fd500bc8ee1', 'दो', false, 'f4dd72c6-b99e-42f6-a29f-7d4b1b63d263');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e4476ff-9f80-42d8-ab3b-2fa21247fab4', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'स्वरों के जो निश्चित चिह्न व्यंजनों के साथ जोड़े जाते हैं, उन्हें क्या कहते हैं?', 'व्यंजनों के साथ प्रयुक्त होने वाले स्वरों के प्रतीकात्मक लिखित चिह्नों को ''मात्रा'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89f0ef43-3b51-475b-ad87-d60cebe04690', 'मात्रा (Matra)', true, '1e4476ff-9f80-42d8-ab3b-2fa21247fab4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16a3f0ae-351d-4f10-8f7e-ae8a80c4683a', 'वर्ण', false, '1e4476ff-9f80-42d8-ab3b-2fa21247fab4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4b992b0-c9f1-4b9f-b26f-81f85a9803ab', 'ध्वनि', false, '1e4476ff-9f80-42d8-ab3b-2fa21247fab4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2422ed65-4cbd-4845-946a-ac3653d88757', 'हलंत', false, '1e4476ff-9f80-42d8-ab3b-2fa21247fab4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e767d94-7c27-40b6-8a36-92086740dec4', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'संयुक्त व्यंजन ''क्ष'' किन दो वर्णों के संयोग से बनता है?', 'क् + ष् = क्ष (जैसे: कक्षा, क्षत्रिय, रक्षा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('971be0f7-1b45-4fb0-aa1e-1a3563414e9d', 'क् + ष् + अ', true, '1e767d94-7c27-40b6-8a36-92086740dec4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acb3bb3e-2470-4f5d-8bad-5d8ffc0a216e', 'क् + छ् + अ', false, '1e767d94-7c27-40b6-8a36-92086740dec4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd33260f-094d-41b9-a82a-2246303595bb', 'क् + स् + अ', false, '1e767d94-7c27-40b6-8a36-92086740dec4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a708ce41-fa52-4db3-a3a8-39c8122f65cd', 'ख् + श् + अ', false, '1e767d94-7c27-40b6-8a36-92086740dec4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dca453e9-8835-45a1-b65c-3f1b85ac577a', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'संयुक्त व्यंजन ''ज्ञ'' किन दो वर्णों के संयोग से बनता है?', 'ज् + ञ् = ज्ञ (जैसे: ज्ञान, ज्ञानी, अज्ञात)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a461342-8830-427d-bb2d-a4e7b363e9d9', 'ज् + ञ् + अ', true, 'dca453e9-8835-45a1-b65c-3f1b85ac577a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cff24895-6af1-4aa0-920e-a86fd80a3944', 'ग् + य् + अ', false, 'dca453e9-8835-45a1-b65c-3f1b85ac577a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe9f2be1-5903-4ed6-ac5f-27913b7004e6', 'ग् + न् + अ', false, 'dca453e9-8835-45a1-b65c-3f1b85ac577a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19bf3c2f-404c-4ba0-bcf3-9d9eec87084c', 'द् + य् + अ', false, 'dca453e9-8835-45a1-b65c-3f1b85ac577a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54db1f6d-662d-4345-9c35-344c7af25807', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'संयुक्त व्यंजन ''त्र'' और ''श्र'' क्रमशः किन वर्णों के संयोग से बनते हैं?', 'त् + र् = त्र (छात्र, पत्र) तथा श् + र् = श्र (श्रम, विश्राम)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56664d8a-6a68-406a-8f16-9632624c5bb8', 'त्र = त् + र् + अ ; श्र = श् + र् + अ', true, '54db1f6d-662d-4345-9c35-344c7af25807');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('868dbc31-0206-4dab-aeb2-c3926c73feff', 'त्र = ट् + र् ; श्र = स् + र्', false, '54db1f6d-662d-4345-9c35-344c7af25807');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('756d296a-ca8d-44c8-a587-84a0213c00da', 'त्र = थ् + र् ; श्र = ष् + र्', false, '54db1f6d-662d-4345-9c35-344c7af25807');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a540d17-ace2-4f98-b453-16cb14195a67', 'त्र = त् + ऋ ; श्र = श् + ऋ', false, '54db1f6d-662d-4345-9c35-344c7af25807');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21b4449c-0b18-442a-b125-4eba41ddd252', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'स्पर्श व्यंजन (क से म तक) कुल कितने होते हैं और इन्हें कितने वर्गों में बाँटा गया है?', 'क-वर्ग से प-वर्ग तक 5×5 = 25 स्पर्श व्यंजन होते हैं जिनका उच्चारण जिह्वा के मुख-स्थान स्पर्श से होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('562febae-00d4-44f9-bb23-b49e9e90a917', '25 स्पर्श व्यंजन, 5 वर्गों में (क-वर्ग, च-वर्ग, ट-वर्ग, त-वर्ग, प-वर्ग)', true, '21b4449c-0b18-442a-b125-4eba41ddd252');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c6e6c6a-ce82-461b-ab24-de05a55cfb86', '20 स्पर्श व्यंजन, 4 वर्गों में', false, '21b4449c-0b18-442a-b125-4eba41ddd252');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12b94b24-0ab4-4eb3-91e3-bfa58f5c7f48', '33 स्पर्श व्यंजन, 6 वर्गों में', false, '21b4449c-0b18-442a-b125-4eba41ddd252');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('165a8432-53bc-4b09-906c-9ab82801bae2', '15 स्पर्श व्यंजन, 3 वर्गों में', false, '21b4449c-0b18-442a-b125-4eba41ddd252');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13f7b099-070e-4175-ad58-8a88460d6a79', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'अन्तःस्थ व्यंजन (Semivowels) कौन-से चार वर्ण होते हैं?', 'य, र, ल, व का उच्चारण स्वर और व्यंजन के मध्यवर्ती (अन्तःस्थ) रूप में होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b436fcf6-0065-423e-9431-18ef56a884a8', 'य, र, ल, व', true, '13f7b099-070e-4175-ad58-8a88460d6a79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('207b82bf-2c9a-437c-81be-5974e80595ed', 'श, ष, स, ह', false, '13f7b099-070e-4175-ad58-8a88460d6a79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83d44504-6701-44f3-8d0b-dead78ca377c', 'क, ख, ग, घ', false, '13f7b099-070e-4175-ad58-8a88460d6a79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d09557c-6846-4e5c-8c87-4ba5656b4c28', 'क्ष, त्र, ज्ञ, श्र', false, '13f7b099-070e-4175-ad58-8a88460d6a79');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49ece9e0-c99a-4a3a-93a5-50b714938e6a', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'ऊष्म व्यंजन (Sibilants) कौन-से चार वर्ण होते हैं जिनके उच्चारण में मुख से ऊष्मा (गर्म हवा) निकलती है?', 'श (तालव्य), ष (मूर्धन्य), स (दंत्य), ह (कंठ्य/काकल्य) के घर्षण जनित उच्चारण से वायु ऊष्मित होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad2a778e-dac1-420b-b76a-adf087dda58b', 'श, ष, स, ह', true, '49ece9e0-c99a-4a3a-93a5-50b714938e6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5403fbeb-c73e-4d7b-9eef-dab67eede5af', 'य, र, ल, व', false, '49ece9e0-c99a-4a3a-93a5-50b714938e6a');
