INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0303e75d-7336-4aec-8fbe-18cabf8e5aa2', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'जब एक ही व्यंजन ध्वनि अपने ही समान व्यंजन ध्वनि से संयुक्त होती है (जैसे: पक्का, बिल्ली, दिल्ली), तो उसे क्या कहते हैं?', 'समान व्यंजनों का परस्पर युग्मन ''द्वित्व व्यंजन'' कहलाता है (क्+क = क्क, ल्+ल = ल्ल)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58d2d4d3-eb31-43c5-b994-08d07d68a34c', 'द्वित्व व्यंजन (Geminate Consonants)', true, '0303e75d-7336-4aec-8fbe-18cabf8e5aa2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66b50e9b-1192-45ac-a451-7eb149c33f70', 'संयुक्त व्यंजन', false, '0303e75d-7336-4aec-8fbe-18cabf8e5aa2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7075f2a6-9686-4041-bbc8-0390bac911ce', 'संयुक्ताक्षर', false, '0303e75d-7336-4aec-8fbe-18cabf8e5aa2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1123ed2f-d8b5-4c37-9554-813354969789', 'अन्तःस्थ व्यंजन', false, '0303e75d-7336-4aec-8fbe-18cabf8e5aa2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1de9f8b4-c73a-4be6-9d0b-532c1fb03525', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'जब दो अलग-अलग व्यंजन परस्पर जुड़ते हैं (जैसे: विद्या, स्थान, पुस्तक), तो उन्हें क्या कहते हैं?', 'दो भिन्न व्यंजनों का स्वर-रहित मेल ''संयुक्ताक्षर'' कहलाता है (स्+थ = स्थ, स्+त = स्त)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df048224-5ecc-4382-b986-34b773e478db', 'संयुक्ताक्षर (Conjunct Consonants)', true, '1de9f8b4-c73a-4be6-9d0b-532c1fb03525');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44bd1383-3a28-4c15-8ba8-2d0f9edbf154', 'द्वित्व व्यंजन', false, '1de9f8b4-c73a-4be6-9d0b-532c1fb03525');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ca3575e-5659-4e6e-bdc8-26bd93778621', 'ह्रस्व स्वर', false, '1de9f8b4-c73a-4be6-9d0b-532c1fb03525');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8f2af9d-c80c-4ab2-907c-1579964af5d2', 'विसर्ग', false, '1de9f8b4-c73a-4be6-9d0b-532c1fb03525');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a071213-b38f-4f79-bbf7-6dec223c4359', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'हिंदी वर्णमाला में किस स्वर की अपनी कोई लिखित मात्रा नहीं होती?', '''अ'' स्वर प्रत्येक अ-कारान्त व्यंजन में अंतर्निहित होता है; इसका कोई अलग मात्रा चिह्न नहीं होता।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a83d998-9373-45f6-8155-6ddde7dab910', '''अ'' स्वर', true, '2a071213-b38f-4f79-bbf7-6dec223c4359');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('087f3197-ffd5-48da-ad77-9ab9e1da733d', '''आ'' स्वर', false, '2a071213-b38f-4f79-bbf7-6dec223c4359');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('148ed949-0183-498f-9e36-48f8f96be35e', '''इ'' स्वर', false, '2a071213-b38f-4f79-bbf7-6dec223c4359');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('171ab6f6-0c12-4b03-90bd-733a9c3ef9ec', '''ऋ'' स्वर', false, '2a071213-b38f-4f79-bbf7-6dec223c4359');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9b0cc16-9693-485b-a364-4bcf444b25d0', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'अनुनासिक (ँ - चंद्रबिंदु) का उच्चारण मुख और नाक में किस प्रकार होता है?', 'अनुनासिक स्वरों की वायु उच्चारण के समय मुख और नासिका दोनों से एक साथ निःसृत होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4392702-8bb3-431b-a233-960f8dfe209f', 'इसका उच्चारण मुख और नासिका दोनों की सहायता से एक साथ होता है (जैसे: आँख, चाँद, गाँव)', true, 'd9b0cc16-9693-485b-a364-4bcf444b25d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03e586f5-a3cb-4217-ad5e-fae333bae249', 'केवल नाक से होता है', false, 'd9b0cc16-9693-485b-a364-4bcf444b25d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6aa195d-ac7a-4a1a-9b5b-5295fdf7786f', 'केवल गले से होता है', false, 'd9b0cc16-9693-485b-a364-4bcf444b25d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbc5c367-1981-48f1-9c7a-47e629dc5c6e', 'केवल होंठों से होता है', false, 'd9b0cc16-9693-485b-a364-4bcf444b25d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96b7b0f5-e868-455b-9afc-a731bf3c81e6', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'अनुस्वार (ं - बिंदु) का उच्चारण किसकी सहायता से होता है?', 'अनुस्वार नासिक्य व्यंजन ध्वनि है जो पंचमाक्षरों (पंत, गंगा, चंचल) के स्थानापन्न प्रयुक्त होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97c56d7e-a8b3-4357-8407-c08c7cbd0253', 'इसका उच्चारण केवल नासिका (नाक) से होता है और यह प्रत्येक वर्ग के पंचम वर्ण (ङ, ञ, ण, न, म) के स्थान पर आता है', true, '96b7b0f5-e868-455b-9afc-a731bf3c81e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e987abfd-28f7-453a-9c59-8826c03c62f4', 'केवल होंठों से', false, '96b7b0f5-e868-455b-9afc-a731bf3c81e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27558401-4c0d-454e-bebe-682e2ed83006', 'केवल दाँतों से', false, '96b7b0f5-e868-455b-9afc-a731bf3c81e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43d2b2ac-9d27-486e-b41b-98acaa51062d', 'केवल जीभ से', false, '96b7b0f5-e868-455b-9afc-a731bf3c81e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d5b3c5c-0ef8-4b58-a331-8bee3e6e642c', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'विसर्ग (ः) का उच्चारण किस ध्वनि के समान हल्का और फुसफुसाहट भरा होता है?', 'संस्कृत मूल के विसर्ग (ः) का उच्चारण अघोष काकल्य ध्वनि /h/ (ह्) के सदृश होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85590381-789a-4cef-b155-bc5e979e3c80', '''ह्'' ध्वनि के समान (जैसे: प्रातः, अतः, नमः)', true, '1d5b3c5c-0ef8-4b58-a331-8bee3e6e642c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fe7bf42-b0a9-44b3-b9bf-cf558b9a1e4b', '''म्'' ध्वनि के समान', false, '1d5b3c5c-0ef8-4b58-a331-8bee3e6e642c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54a48b81-887e-4008-a047-ac9a664d9b3a', '''न्'' ध्वनि के समान', false, '1d5b3c5c-0ef8-4b58-a331-8bee3e6e642c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8887a6fb-cf74-495c-ab60-f77cacf7e822', '''स्'' ध्वनि के समान', false, '1d5b3c5c-0ef8-4b58-a331-8bee3e6e642c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0aa07d8b-1e30-46de-bb29-79b71816d0ab', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'क-वर्ग (क, ख, ग, घ, ङ) का उच्चारण स्थान मुख का कौन-सा भाग है?', 'क-वर्ग के वर्ण कंठ्य (Throat/Velar) ध्वनियाँ कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2162445a-2b76-4167-ad37-86bd36cd9268', 'कंठ (गला / Velar)', true, '0aa07d8b-1e30-46de-bb29-79b71816d0ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06c65f53-5321-4147-86cf-861fdff341a2', 'तालु', false, '0aa07d8b-1e30-46de-bb29-79b71816d0ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a00a67c2-22d5-4c2c-adb7-87747478192d', 'मूर्धा', false, '0aa07d8b-1e30-46de-bb29-79b71816d0ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f970af44-cce8-4af6-a2bf-a6a52a8a0c3f', 'दाँत', false, '0aa07d8b-1e30-46de-bb29-79b71816d0ab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('847842b6-06c9-4a55-b3db-8abe0ad7dee5', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'च-वर्ग (च, छ, ज, झ, ञ) तथा इ, ई, य, श का उच्चारण स्थान क्या है?', 'जिह्वा तालु के कठोर भाग को स्पर्श करती है, अतः ये ''तालव्य'' वर्ण कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c81771de-16f6-4421-a380-d0d3bee53d72', 'तालु (तालव्य / Palatal)', true, '847842b6-06c9-4a55-b3db-8abe0ad7dee5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42beba2d-1885-410d-be40-13ea7898ea42', 'ओष्ठ', false, '847842b6-06c9-4a55-b3db-8abe0ad7dee5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0c6c9bd-4744-40af-8a11-cf7779d0f7a8', 'दंत', false, '847842b6-06c9-4a55-b3db-8abe0ad7dee5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dab55b60-029a-4f6a-9bf8-098f9907f706', 'मूर्धा', false, '847842b6-06c9-4a55-b3db-8abe0ad7dee5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04c23dfd-51b5-4ad4-93b7-4ef7d21aacb2', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'प-वर्ग (प, फ, ब, भ, म) तथा उ, ऊ का उच्चारण स्थान क्या है?', 'दोनों होंठों के परस्पर मिलन से उच्चरित होने के कारण इन्हें ''ओष्ठ्य'' वर्ण कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a43429-ef94-43b3-894b-4d89de81192f', 'ओष्ठ (ओष्ठ्य / Labial - दोनों होंठ)', true, '04c23dfd-51b5-4ad4-93b7-4ef7d21aacb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7424db04-4ef6-46d4-946e-3fce63f68ae4', 'कंठ', false, '04c23dfd-51b5-4ad4-93b7-4ef7d21aacb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b7c693e-5926-4d91-80e2-00e72403561c', 'तालु', false, '04c23dfd-51b5-4ad4-93b7-4ef7d21aacb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f45205f-375b-4e88-9cc6-523377d3f635', 'दंत', false, '04c23dfd-51b5-4ad4-93b7-4ef7d21aacb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f3341e6-f1ef-47fc-9378-54ec5c9c727d', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'ड़ और ढ़ को हिंदी में कौन-से व्यंजन कहा जाता है?', 'ड़ और ढ़ उत्क्षिप्त (ताड़नजात) वर्ण हैं, जिनका उच्चारण जिह्वा को झटके से नीचे गिराकर किया जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('749938ee-cceb-4a3f-993b-31c128c8633f', 'उत्क्षिप्त या विकसित अतिरिक्त व्यंजन (Flap Consonants)', true, '9f3341e6-f1ef-47fc-9378-54ec5c9c727d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa5482b5-8935-4c1e-8421-04c9576f6e41', 'मूल स्वर', false, '9f3341e6-f1ef-47fc-9378-54ec5c9c727d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d6c5711-82a9-45ec-bb3b-8efa564c6bc8', 'ऊष्म व्यंजन', false, '9f3341e6-f1ef-47fc-9378-54ec5c9c727d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d22aa50e-c832-416c-ba04-1cb4d4001947', 'संयुक्त व्यंजन', false, '9f3341e6-f1ef-47fc-9378-54ec5c9c727d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('862c662e-aea9-4d74-ac32-6330d799829a', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f70c3805-d445-4e94-95ba-4a863046baab', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '862c662e-aea9-4d74-ac32-6330d799829a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43c86e31-3f42-41ee-bb31-c0f015a918d0', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '862c662e-aea9-4d74-ac32-6330d799829a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d480682-3440-4665-80c5-71ff2fb27e44', '(A) सही है, परन्तु (R) गलत है।', false, '862c662e-aea9-4d74-ac32-6330d799829a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6efc10a8-a834-4b99-a5da-bdcf91d2eb3e', '(A) गलत है, परन्तु (R) सही है।', false, '862c662e-aea9-4d74-ac32-6330d799829a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b8418c0-acd3-4289-a8de-7777c5ac2c26', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'वर्ण-विच्छेद (Phonetic Decomposition) की दृष्टि से ''विद्यार्थी'' शब्द का सही विच्छेद कौन-सा है?', 'वि-द्या-र्-थी = (व्+इ) + (द्+य्+आ) + (र्+थ्+ई)। रेफ (र्) थ से पूर्व उच्चरित होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('895ed100-24a9-4558-adbb-e9dce7774887', 'व् + इ + द् + य् + आ + र् + थ् + ई', true, '7b8418c0-acd3-4289-a8de-7777c5ac2c26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaa6a8c5-b653-4bc4-b1a9-66e8ae81c5cf', 'व् + ई + द् + य् + आ + थ् + ई + र्', false, '7b8418c0-acd3-4289-a8de-7777c5ac2c26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51971a65-d62d-4823-8d29-5f8afd978ce7', 'व् + इ + द् + य् + आ + र् + थ् + इ', false, '7b8418c0-acd3-4289-a8de-7777c5ac2c26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4589f4ca-13e1-4ba3-b262-3a93708d8949', 'व् + इ + द्या + र्थी', false, '7b8418c0-acd3-4289-a8de-7777c5ac2c26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92f2ddff-61a1-4a68-b0ed-15255d81f761', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'Spot the IMPOSTER in the following group of वर्ण based on their उच्चारण स्थान:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffc6c1d9-5051-4b27-aaef-fb96aaf6c0f2', 'क', false, '92f2ddff-61a1-4a68-b0ed-15255d81f761');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ece6914-3d05-4e7c-8e63-840541834814', 'ख', false, '92f2ddff-61a1-4a68-b0ed-15255d81f761');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('296bc481-6970-4fed-8e05-c4fec5d01986', 'ग', false, '92f2ddff-61a1-4a68-b0ed-15255d81f761');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f5f1cee-c16c-474e-a3f0-800b294e89ed', 'च', true, '92f2ddff-61a1-4a68-b0ed-15255d81f761');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27d14913-1aad-430c-a2ff-6f34e68111b5', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'सुमेलित कीजिए (Match the Columns):
(क) क-वर्ग (क, ख, ग, घ) -> (i) मूर्धन्य
(ख) च-वर्ग (च, छ, ज, झ) -> (ii) ओष्ठ्य
(ग) ट-वर्ग (ट, ठ, ड, ढ) -> (iii) कंठ्य
(घ) प-वर्ग (प, फ, ब, भ) -> (iv) तालव्य', 'क-वर्ग = कंठ्य; च-वर्ग = तालव्य; ट-वर्ग = मूर्धन्य; प-वर्ग = ओष्ठ्य।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a454e4d-0dab-48a2-a6b5-b14ef8897d17', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', true, '27d14913-1aad-430c-a2ff-6f34e68111b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9bb476d-1495-48de-9d31-4647444ffb59', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '27d14913-1aad-430c-a2ff-6f34e68111b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4903aafe-72c6-4f2d-a85b-b450565208a7', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '27d14913-1aad-430c-a2ff-6f34e68111b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('311d3e8a-a736-47f8-9c17-f6517f06ab2d', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '27d14913-1aad-430c-a2ff-6f34e68111b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('040f8447-1971-462e-8cdf-0e9a12353b6a', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', '''र'' के विभिन्न रूपों के संबंध में सही कथन चुनिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa12bbeb-ba8e-4d7c-ac27-f30c1961db76', 'सभी कथन 1, 2 और 3 सत्य हैं', true, '040f8447-1971-462e-8cdf-0e9a12353b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1140823a-a3ba-4461-9667-1fe3d6046f32', 'कथन 1 और 2 केवल', false, '040f8447-1971-462e-8cdf-0e9a12353b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a975341b-dcb1-45f8-bb27-afab90d4b15d', 'कथन 2 और 3 केवल', false, '040f8447-1971-462e-8cdf-0e9a12353b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('658da045-b2c1-4e56-bfb2-9972dc4a2a51', 'कथन 1 और 3 केवल', false, '040f8447-1971-462e-8cdf-0e9a12353b6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fa5b180-b286-4373-a80f-42f1026a4f40', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'शब्द ''श्रृंगार'' अथवा ''कृष्ण'' में ''ऋ'' की मात्रा का सही वर्ण-विच्छेद क्या है?', '''कृ'' में व्यंजन ''क्'' के साथ ''ऋ'' स्वर जुड़ा है: क् + ऋ + ष् + ण् + अ = कृष्ण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a445c9e-b853-4225-bbc6-f8dceff75957', 'कृष्ण = क् + ऋ + ष् + ण् + अ', true, '6fa5b180-b286-4373-a80f-42f1026a4f40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f2a8014-82d1-408c-9377-a3404e379a17', 'कृष्ण = क् + र् + इ + ष् + ण् + अ', false, '6fa5b180-b286-4373-a80f-42f1026a4f40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f8a18a7-0d67-48fd-ab71-f1ec8b0d2999', 'कृष्ण = क् + ऋ + ष् + ण्', false, '6fa5b180-b286-4373-a80f-42f1026a4f40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfb38afd-521e-4a2b-ac8d-44c9609327cd', 'कृष्ण = क + ऋ + ष + ण', false, '6fa5b180-b286-4373-a80f-42f1026a4f40');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5dbe2139-eaca-4748-9122-ed99ff3bee12', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'आगत ध्वनि ''ऑ'' (जैसे: डॉक्टर, कॉलेज, बॉल, कॉफी) किस विदेशी भाषा से हिंदी में समाहित हुई है?', 'अंग्रेज़ी के ''o'' स्वर के शुद्ध उच्चारण (Doctor, College) हेतु अर्ध-चंद्र ''ऑ'' आगत स्वर स्वीकृत किया गया है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbadcde9-ca10-4003-b5a5-4789eedcd778', 'अंग्रेज़ी भाषा (English)', true, '5dbe2139-eaca-4748-9122-ed99ff3bee12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c9437fd-769e-46cd-9598-068d69acad26', 'फारसी', false, '5dbe2139-eaca-4748-9122-ed99ff3bee12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8eed019-cc2b-46c2-a4b6-fdee5275e0ec', 'पुर्तगाली', false, '5dbe2139-eaca-4748-9122-ed99ff3bee12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27c6d58d-f037-4084-9eea-779c3ce03744', 'तुर्की', false, '5dbe2139-eaca-4748-9122-ed99ff3bee12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84791bc6-2aa5-4718-bb0f-612ec30ac255', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'नुक्ता (़) लगे आगत व्यंजन ''फ़'' और ''ज़'' (जैसे: फ़र्क, ज़माना) मुख्यतः किस भाषा से हिंदी में आए हैं?', 'अरबी-फारसी की ध्वनियों के शुद्ध उच्चारण हेतु वर्ण के नीचे अधोबिंदु (नुक्ता) लगाया जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0be66fe6-d34e-4bd5-9b51-37394ceede21', 'अरबी और फारसी (Arabic & Persian)', true, '84791bc6-2aa5-4718-bb0f-612ec30ac255');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e0ad315-02c7-453f-902d-f90fc41e6f06', 'अंग्रेज़ी', false, '84791bc6-2aa5-4718-bb0f-612ec30ac255');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1861be6-8ccb-48ba-9748-9bffdfb2f1a2', 'संस्कृत', false, '84791bc6-2aa5-4718-bb0f-612ec30ac255');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26903ea9-cf71-4453-87cc-775530768fad', 'फ्रेंच', false, '84791bc6-2aa5-4718-bb0f-612ec30ac255');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b9921ee-7522-413a-9e2f-6643fd8a388c', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'अल्पप्राण और महाप्राण के वर्गीकरण में ''महाप्राण'' ध्वनियों की क्या विशेषता होती है?', 'महाप्राण (ख, घ, छ, झ, ठ, ढ, थ, ध, फ, भ + श, ष, स, ह) के उच्चारण में तीव्र उच्छ्वास प्राणवायु निकलती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ede6141c-9b42-43b2-b93f-1fb9d323004d', 'इनके उच्चारण में अधिक श्वास वायु बाहर निकलती है और ''ह'' जैसी ध्वनि सुनाई देती है (प्रत्येक वर्ग का दूसरा और चौथा वर्ण तथा ऊष्म व्यंजन)', true, '5b9921ee-7522-413a-9e2f-6643fd8a388c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c89528f7-7299-4387-94c4-11f9e200a8f9', 'इनमें बहुत कम हवा निकलती है', false, '5b9921ee-7522-413a-9e2f-6643fd8a388c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bdb2d09-6410-4af8-acc0-962f8d407cd8', 'इनमें कोई आवाज़ नहीं होती', false, '5b9921ee-7522-413a-9e2f-6643fd8a388c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da71c3a9-44c3-40e4-8ed5-9587ed5c33ce', 'ये केवल रात में बोले जाते हैं', false, '5b9921ee-7522-413a-9e2f-6643fd8a388c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9f26351-a8a7-46e2-96ae-10b5f03fbce2', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'अल्पप्राण (Non-aspirated) ध्वनियों के अंतर्गत कौन-से वर्ण आते हैं?', 'अल्पप्राण (क, ग, ङ, च, ज, ञ...) के उच्चारण में सीमित एवं सामान्य प्राणवायु प्रयुक्त होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf88aca3-7f49-4039-95e1-85d06cdd9bd4', 'प्रत्येक वर्ग का पहला, तीसरा, पाँचवाँ वर्ण (1, 3, 5) तथा अन्तःस्थ व्यंजन (य, र, ल, व) एवं सभी स्वर', true, 'a9f26351-a8a7-46e2-96ae-10b5f03fbce2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('523eec0a-cd6e-4468-9870-8feb08406af9', 'दूसरा और चौथा वर्ण', false, 'a9f26351-a8a7-46e2-96ae-10b5f03fbce2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('021d2314-84b3-44f0-80c3-43912b23f130', 'केवल ऊष्म व्यंजन', false, 'a9f26351-a8a7-46e2-96ae-10b5f03fbce2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad162cb5-eeec-4de2-8d19-b70cb1b889bb', 'केवल संयुक्त व्यंजन', false, 'a9f26351-a8a7-46e2-96ae-10b5f03fbce2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('874b0eb6-4a05-4872-ade4-2de7807f16f1', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'प्लुत स्वर (जैसे: ''ओ३म्'' या किसी को दूर से पुकारने में) के उच्चारण में ह्रस्व स्वर की तुलना में कितना समय लगता है?', 'प्लुत स्वर त्रैमात्रिक होते हैं (३ चिह्न द्वारा दर्शाए जाते हैं), जो दीर्घ से भी अधिक समय तक उच्चरित होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b3df82d-dc3d-4cba-8b99-1e4c7ab7c004', 'तीन गुना समय (तीन मात्राओं का काल)', true, '874b0eb6-4a05-4872-ade4-2de7807f16f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeb204b3-cd4a-4981-910d-3fdd71356919', 'दोगुना समय', false, '874b0eb6-4a05-4872-ade4-2de7807f16f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fa6b7bb-91f8-4629-8f99-5b382ab248c1', 'बराबर समय', false, '874b0eb6-4a05-4872-ade4-2de7807f16f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0288797e-eee1-497b-945c-711b093e0ff7', 'आधा समय', false, '874b0eb6-4a05-4872-ade4-2de7807f16f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62202730-7e00-4028-8198-a4c40982b555', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'निम्नलिखित में से मानक वर्तनी के अनुसार पंचमाक्षर के स्थान पर अनुस्वार का शुद्ध प्रयोग कौन-सा है?', 'केंद्रीय हिंदी निदेशालय के मानक वर्तनी नियमों के अनुसार पंचमाक्षरों के स्थान पर शिरोरेखा के ऊपर अनुस्वार (ं) का प्रयोग मानक है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49184b5e-dad9-4900-bfcf-69f628ca2341', 'गङ्गा -> गंगा ; चञ्चल -> चंचल ; कण्ठ -> कंठ ; सम्बन्ध -> संबंध', true, '62202730-7e00-4028-8198-a4c40982b555');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fee94355-13ba-490d-8db3-4a156227b613', 'सभी अशुद्ध हैं', false, '62202730-7e00-4028-8198-a4c40982b555');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5357eb0-d214-4e84-b07a-30aa806be046', 'केवल गङ्गा शुद्ध है', false, '62202730-7e00-4028-8198-a4c40982b555');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d562831-4301-4cbb-bfe3-bf072acd1550', 'केवल चञ्चल शुद्ध है', false, '62202730-7e00-4028-8198-a4c40982b555');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('443a2047-0a75-4471-85e2-6141ed484dfb', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'The method of separating slightly larger sized impurities like pieces of dirt, stones, and husk from wheat, rice, or pulses using hands is called:', 'Handpicking is used when impurities differ in size, color, or shape and are present in small quantities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32a1cc2d-ab69-403b-bcd6-dffe643166bc', 'Handpicking', true, '443a2047-0a75-4471-85e2-6141ed484dfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bea3975-9f37-4e35-8a8b-3eb43218be28', 'Threshing', false, '443a2047-0a75-4471-85e2-6141ed484dfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a7569f9-8e21-4044-b64f-dda87a273b55', 'Winnowing', false, '443a2047-0a75-4471-85e2-6141ed484dfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1c4a50d-58a4-4f62-bb1c-5bad5992fe7c', 'Sieving', false, '443a2047-0a75-4471-85e2-6141ed484dfb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a95ac3bb-6cd7-4c18-96cc-8a64133d8f4c', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'The process of beating harvested stalks on a hard stone surface to free the edible grains is called:', 'Threshing separates grain seeds from the dry stalks using mechanical beating, bullocks, or motorized threshers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a37d8f7-7adf-4c0b-8517-5d1d91e4504b', 'Threshing', true, 'a95ac3bb-6cd7-4c18-96cc-8a64133d8f4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9995aaef-3120-48d1-b000-04d5f4a2ba79', 'Winnowing', false, 'a95ac3bb-6cd7-4c18-96cc-8a64133d8f4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6aae0341-821a-4362-9778-0f3cc0acf330', 'Sieving', false, 'a95ac3bb-6cd7-4c18-96cc-8a64133d8f4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3312ce88-9b13-4ab9-b930-112aab7a9052', 'Filtration', false, 'a95ac3bb-6cd7-4c18-96cc-8a64133d8f4c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d8175b8-2d6b-4eff-bedd-b1c9e711c7bf', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'The method of separating heavier grain seeds from lighter husk particles using blowing wind or air currents is called:', 'Winnowing relies on the density difference where wind blows away lighter husk while heavier grains fall vertically.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a24f6ed-4f18-491e-9656-66890519ac8c', 'Winnowing', true, '8d8175b8-2d6b-4eff-bedd-b1c9e711c7bf');
