INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9447341d-b343-41e2-bcc9-587a706568b9', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'A solution in which no more quantity of a given solute can be dissolved at that specific temperature is called a:', 'A saturated solution has reached thermodynamic chemical equilibrium between dissolved and undissolved solute.', NOW()) ON CONFLICT DO NOTHING;
