INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a7aafdd-8bb6-4e69-88e0-e8d60fa56a4d', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'Which of the following implements is used in kitchens to separate used tea leaves from brewed liquid tea?', 'A tea strainer acts as a sieve/filter, retaining insoluble boiled tea leaves while letting the aromatic beverage flow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('128c3608-6597-472f-bd27-c584d7bb5dfb', 'A fine wire strainer (Filter)', true, '0a7aafdd-8bb6-4e69-88e0-e8d60fa56a4d');
