INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3313cfa-396b-4335-b523-a5e6f69bc0bd', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'What happens to the solubility of solid sugar or salt in water when the temperature of the water is increased by heating?', 'Thermal energy expands intermolecular spaces between water molecules and supplies endothermic dissolution energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73bbf617-2e5b-4b11-8525-700bf865b7ec', 'Its solubility increases, allowing more solid to dissolve', true, 'e3313cfa-396b-4335-b523-a5e6f69bc0bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d20af13-de8b-4cd5-898f-102bd9755bd1', 'Its solubility decreases', false, 'e3313cfa-396b-4335-b523-a5e6f69bc0bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fae8b186-ca3b-4520-b7f7-0c03822a1d60', 'The dissolved sugar turns into gas', false, 'e3313cfa-396b-4335-b523-a5e6f69bc0bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb771bea-8efd-44e8-bd85-9cff62efd495', 'The solubility remains unchanged', false, 'e3313cfa-396b-4335-b523-a5e6f69bc0bd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed34141c-76dd-433b-95f6-f0a4ed9b632c', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Why can a mixture of wheat flour and iron fillings be easily separated using a magnet?', 'Magnetic separation exploits the ferromagnetic property of iron to selectively extract filings without touching the flour.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b957f6d3-27ed-45f2-b307-b37a06411d21', 'Iron is a magnetic material attracted by magnets, whereas wheat flour is non-magnetic', true, 'ed34141c-76dd-433b-95f6-f0a4ed9b632c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('758e1207-d2b3-4383-8af9-7e28c65c6288', 'Iron melts near magnets', false, 'ed34141c-76dd-433b-95f6-f0a4ed9b632c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26f9ad9c-df2e-4093-a0c6-a2cb2feca4ce', 'Wheat flour is poisonous to magnets', false, 'ed34141c-76dd-433b-95f6-f0a4ed9b632c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5b2c805-a8c9-43d9-be72-aaea59928ce8', 'Magnets blow air like wind', false, 'ed34141c-76dd-433b-95f6-f0a4ed9b632c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('698d3077-2019-4345-95e0-9fd1f06b2370', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Why is water commonly referred to as a ''Universal Solvent'' in chemistry?', 'Water''s high dielectric constant and polar dipole moments readily hydrate and break ionic lattices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00ae24b8-cc22-42b8-a620-20a92b06419f', 'Because its polar molecular structure can dissolve a wider variety of solutes than any other known liquid', true, '698d3077-2019-4345-95e0-9fd1f06b2370');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6121640a-ade3-44bf-b342-d84cd0421c12', 'Because it exists in all galaxies', false, '698d3077-2019-4345-95e0-9fd1f06b2370');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06e02d8c-4256-43f9-8af2-001d1aff0714', 'Because it has zero boiling point', false, '698d3077-2019-4345-95e0-9fd1f06b2370');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e089302e-96ab-4997-bdfc-057aaa916639', 'Because it never turns into ice', false, '698d3077-2019-4345-95e0-9fd1f06b2370');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5e336e4-4f75-49ad-9572-f8a9fa1edeb2', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Which combined sequence of separation techniques is used to separate a mixture of Sand and Salt completely?', 'Salt dissolves in water while sand remains insoluble; filtering removes sand residue, and evaporating the filtrate yields dry salt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa9947aa-d2e2-475f-a41f-524861a17f79', 'Dissolution in water -> Sedimentation & Filtration (separates sand) -> Evaporation / Condensation (recovers salt & water)', true, 'a5e336e4-4f75-49ad-9572-f8a9fa1edeb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8bfba6b-be1e-44f7-a67c-9c39285b175b', 'Threshing followed by Winnowing', false, 'a5e336e4-4f75-49ad-9572-f8a9fa1edeb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('040317cd-7f47-4b06-b020-5588d151b83b', 'Handpicking followed by Sieving', false, 'a5e336e4-4f75-49ad-9572-f8a9fa1edeb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd7ce3f3-5a73-44f7-b7cc-55b227f8edce', 'Direct Sieving through cloth', false, 'a5e336e4-4f75-49ad-9572-f8a9fa1edeb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('009b2f97-9b75-4b2c-bdc8-cabaf80527dd', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Why is churning (centrifugation) of whole milk or curd practiced in Indian households?', 'Mechanical churning agitates emulsified fat globules, causing them to coalesce and float as lighter butter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4bc6795-2ba6-42cf-a125-a9211e4a9a1a', 'To separate less dense butter (fats) which float to the top from denser liquid buttermilk', true, '009b2f97-9b75-4b2c-bdc8-cabaf80527dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('319e241b-bd7e-44c9-9871-8e5efe954c49', 'To change the color of milk to red', false, '009b2f97-9b75-4b2c-bdc8-cabaf80527dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd4defc2-1e29-4aaf-a90c-ed439f604d56', 'To evaporate all liquid', false, '009b2f97-9b75-4b2c-bdc8-cabaf80527dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6270e88d-2aea-491f-9a38-62c5bbc3ca60', 'To dissolve sugar', false, '009b2f97-9b75-4b2c-bdc8-cabaf80527dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1dbd1f2c-58c3-4b93-95e6-7ab118bda3d5', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'What is the solid material retained on the filter paper after filtration called?', 'The trapped insoluble solid retained on the filter is the Residue, while the clear collected liquid is the Filtrate.', NOW()) ON CONFLICT DO NOTHING;
