INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d13f3a8-eb1e-407f-9afb-9cdb402ef68f', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'What is the clear liquid that passes through the filter paper and collects in the beaker called?', 'The liquid that successfully passes through the microscopic pores of the filtration filter is called the Filtrate.', NOW()) ON CONFLICT DO NOTHING;
