INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d3d2b8f-326b-4d21-a786-cbd3114d26a7', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'How can muddy river water be rapidly cleared of fine suspended colloidal clay particles in village households?', 'Alum releases trivalent Al³⁺ ions that neutralize negative surface charges on colloidal clay, causing rapid flocculation (loading).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eaf97e5b-ced7-4fce-96c4-e78364ce6c9c', 'By swirling a piece of Alum (Phitkari) in the water to cause coagulation (Loading)', true, '2d3d2b8f-326b-4d21-a786-cbd3114d26a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('309216f7-6fd3-49c2-9bf7-130a17efdf63', 'By adding salt', false, '2d3d2b8f-326b-4d21-a786-cbd3114d26a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d429978-ddcf-4e0f-a767-e494bcf0ca7b', 'By blowing air', false, '2d3d2b8f-326b-4d21-a786-cbd3114d26a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f22abfbb-83ff-4646-8efd-bc5a39ee9ef5', 'By freezing into ice', false, '2d3d2b8f-326b-4d21-a786-cbd3114d26a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9656345d-6a4c-4ece-b57b-74b4d7a22cd1', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Why can''t a mixture of sugar dissolved in water be separated by using filter paper?', 'Dissolved solute particles in a true solution have molecular dimensions (< 1 nm) and pass through filter pores unimpeded.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40e2bed6-8942-41fc-8fd5-301ee107f1c3', 'Sugar dissolves into individual molecules/ions that are much smaller than the microscopic pores of the filter paper', true, '9656345d-6a4c-4ece-b57b-74b4d7a22cd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7834077-f1d5-47e7-852f-e082e3ba9bf9', 'Sugar tears the filter paper', false, '9656345d-6a4c-4ece-b57b-74b4d7a22cd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce6cc2e9-94e2-4298-bdf0-901331adc5af', 'Sugar turns into water vapor', false, '9656345d-6a4c-4ece-b57b-74b4d7a22cd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edc800b7-b0ae-4349-8f6b-6d3bf54d3d6b', 'Filter paper dissolves sugar', false, '9656345d-6a4c-4ece-b57b-74b4d7a22cd1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b9128da-b7ce-4126-a21e-4ece33e81ec5', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Which of the following mixtures CANNOT be separated by winnowing?', 'Both iron pins and sand grains are dense solids that fall straight down; winnowing requires a light, wind-blowable fraction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1178f935-b76e-43a9-bf01-99f0c0d524af', 'Iron pins mixed with sand', true, '9b9128da-b7ce-4126-a21e-4ece33e81ec5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('358a2772-bdd2-4d4c-a19f-2af632527a21', 'Wheat grains mixed with dry husk', false, '9b9128da-b7ce-4126-a21e-4ece33e81ec5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c02d86c9-55a2-4a27-a347-e458be141cf4', 'Paddy grains mixed with dry chaff', false, '9b9128da-b7ce-4126-a21e-4ece33e81ec5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49c6ab4d-1189-4407-9215-e260910cbb3d', 'Groundnut seeds mixed with dry leaves', false, '9b9128da-b7ce-4126-a21e-4ece33e81ec5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aad91d56-9193-41c5-8567-f26cf44d1a83', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'What is the primary scientific reason for separating substances from a mixture?', 'Separation isolates useful components (e.g. butter from milk) and purges harmful or unwanted contaminants (e.g. stones from grains).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33a75ee5-22f4-4f44-a563-90d1afd48e1d', 'To remove harmful or undesirable impurities and to recover valuable pure components for use', true, 'aad91d56-9193-41c5-8567-f26cf44d1a83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55902fd9-ff3e-48e4-9332-e1eaa88e782a', 'To make food taste bitter', false, 'aad91d56-9193-41c5-8567-f26cf44d1a83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54a38ba5-1715-4e03-97fa-18b6e84d5423', 'To destroy the chemical elements', false, 'aad91d56-9193-41c5-8567-f26cf44d1a83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27cf1344-8b22-47b2-867f-6f213f5a2020', 'To increase the weight of the mixture', false, 'aad91d56-9193-41c5-8567-f26cf44d1a83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('998fe9eb-d84e-4bbd-84d3-c2e9967292ef', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'In construction sites, why do builders pass sand through large inclined wire mesh sieves?', 'Sieving isolates particle sizes, filtering out oversized aggregate stones to ensure smooth plastering cement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c8f4ce-227d-49f2-8341-86d8f7e88c5a', 'To separate coarse gravel and pebbles from fine sand needed for masonry mortar', true, '998fe9eb-d84e-4bbd-84d3-c2e9967292ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8106785e-8dc9-4d0b-b790-77d2b57219c5', 'To dry the sand', false, '998fe9eb-d84e-4bbd-84d3-c2e9967292ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b1e6c95-d328-4a0f-af73-567fd72f573e', 'To change the color of sand', false, '998fe9eb-d84e-4bbd-84d3-c2e9967292ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5248f24b-8920-47d0-8f96-b6f6ddd2dcfb', 'To cool the sand', false, '998fe9eb-d84e-4bbd-84d3-c2e9967292ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1bbc18e-7d5c-4114-abfc-77a1c8531578', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'How can one prepare a saturated solution of salt in a glass of water at room temperature?', 'Dynamic saturation is reached when the dissolution rate equals crystallization rate, leaving visible solid solute.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('262e2cd7-b5da-4c24-abdb-738700da3023', 'Keep adding salt spoon by spoon with continuous stirring until no more salt dissolves and excess crystals settle at the bottom', true, 'b1bbc18e-7d5c-4114-abfc-77a1c8531578');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f5d81f5-e3a1-4cba-ac43-4f4c50f133c5', 'Add 1 gram of salt and boil for 2 hours', false, 'b1bbc18e-7d5c-4114-abfc-77a1c8531578');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10158ed5-0858-4b70-b89a-da850d2b51f5', 'Add ice to water', false, 'b1bbc18e-7d5c-4114-abfc-77a1c8531578');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7176c320-a9bb-4e40-9e77-63528fb991d7', 'Keep the water in the dark', false, 'b1bbc18e-7d5c-4114-abfc-77a1c8531578');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('098d73aa-723e-4043-b368-978ebdb6a762', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'What is the role of the condensation process in the water cycle of nature?', 'Adiabatic cooling of rising warm moist air condenses vapor onto cloud condensation nuclei, generating precipitation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e061a127-a31f-4557-8acf-2a9630f00503', 'It converts rising atmospheric water vapor into liquid water droplets, forming clouds and bringing rain', true, '098d73aa-723e-4043-b368-978ebdb6a762');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78501fde-07b5-4583-9d37-13b94836ffbb', 'It absorbs sunlight', false, '098d73aa-723e-4043-b368-978ebdb6a762');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7051625-104f-412b-b136-007e5bd13c50', 'It turns rain into dry air', false, '098d73aa-723e-4043-b368-978ebdb6a762');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35e4c247-01cc-4975-b289-6b8e254a75e5', 'It creates ocean salt', false, '098d73aa-723e-4043-b368-978ebdb6a762');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33101b96-f762-4cfe-a57f-44cafa733f31', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'If a saturated solution of salt is cooled down from 60°C to 10°C, what observation will be made?', 'Lowering temperature reduces solute saturation capacity, forcing excess solute out of solution as recrystallized solids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07bb2b3b-bfd3-4612-9f6a-24fbad6bb7fd', 'Excess dissolved salt will precipitate out and crystallize at the bottom of the beaker', true, '33101b96-f762-4cfe-a57f-44cafa733f31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3605a4a-85ee-4448-8832-71622a3d2c03', 'The water will turn into gas', false, '33101b96-f762-4cfe-a57f-44cafa733f31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ac3c915-deb3-4033-ad8b-0fa50c158fdd', 'The salt will disappear permanently', false, '33101b96-f762-4cfe-a57f-44cafa733f31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85cdeb94-9b64-40b8-ae35-efc25b561da4', 'The solution will become unsaturated', false, '33101b96-f762-4cfe-a57f-44cafa733f31');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2525650-068c-4584-88ce-735ee76efbd0', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Which of the following processes involves BOTH evaporation and condensation working consecutively?', 'Distillation vaporizes the volatile solvent (evaporation) and then cools the pure vapor through a condenser (condensation).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bb4473f-444e-4966-bce0-bc3f498c739d', 'Distillation (producing pure distilled water)', true, 'd2525650-068c-4584-88ce-735ee76efbd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e34399e9-fe8e-41fb-bf05-bcb8f25aee1c', 'Handpicking', false, 'd2525650-068c-4584-88ce-735ee76efbd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d320c2d9-9619-4819-ad19-bec51b3808d6', 'Sieving', false, 'd2525650-068c-4584-88ce-735ee76efbd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f637a208-1149-4510-a541-158b1a22d88f', 'Threshing', false, 'd2525650-068c-4584-88ce-735ee76efbd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2a09b8a-6eef-4576-bfd8-8397b8b01cf7', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Read the statements:
