INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83d5ef26-9009-4af3-a2fd-4daf3db967b9', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Spot the IMPOSTER in the following group of separation techniques based on the physical state of the mixtures they separate:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c34becb-d1bc-480f-ad87-a090f93c20e6', 'Handpicking', false, '83d5ef26-9009-4af3-a2fd-4daf3db967b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c552a3e0-c3c5-4c21-bc19-ecfe634328f2', 'Threshing', false, '83d5ef26-9009-4af3-a2fd-4daf3db967b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cffaf900-f41a-46b4-bbbf-f080bfb65670', 'Winnowing', false, '83d5ef26-9009-4af3-a2fd-4daf3db967b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc25250e-c6f8-4504-83e6-2757c78f2c37', 'Decantation', true, '83d5ef26-9009-4af3-a2fd-4daf3db967b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bbc269a-8daa-426e-a1fe-db329b147d65', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'A student accidentally mixes Sand, Salt, and Iron filings in a beaker. What is the scientifically correct step-by-step procedure to recover all three components pure and dry?', 'Magnetic extraction isolates iron; aqueous dissolution exploits differential solubility; filtration isolates sand; evaporation yields salt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3fe696f-5b9d-4ffc-8c00-a131adeca1cd', '1. Use a Magnet to extract iron filings -> 2. Add water to dissolve salt -> 3. Filter to separate sand residue -> 4. Evaporate filtrate to recover dry salt crystals', true, '8bbc269a-8daa-426e-a1fe-db329b147d65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa5c29f3-01a3-4a22-a9ce-091b471e4ca8', '1. Evaporate first -> 2. Filter -> 3. Handpick', false, '8bbc269a-8daa-426e-a1fe-db329b147d65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8043b43-6ec2-435b-9fd1-bf8a2e700636', '1. Winnow the mixture -> 2. Sieve through wire mesh', false, '8bbc269a-8daa-426e-a1fe-db329b147d65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2848a530-2f3c-489d-a643-dfcca94c9a4f', '1. Thresh the beaker -> 2. Add acid', false, '8bbc269a-8daa-426e-a1fe-db329b147d65');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2677b18d-f2d3-44ee-bd8b-90281db527d8', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'In an experiment, water containing steam is held beneath a cold metal plate holding ice cubes. Drops of liquid water form and drip into a beaker. What two physical processes are operating?', 'Thermal vaporization generates steam (evaporation), which gives up its latent heat of condensation upon contact with the chilled ice plate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1a3d367-d0b5-48c9-8991-f79c8be20524', 'Evaporation (from the hot liquid) and Condensation (on the cold metal plate)', true, '2677b18d-f2d3-44ee-bd8b-90281db527d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('702390e0-d79a-47ae-b905-4edc46330a28', 'Sedimentation and Decantation', false, '2677b18d-f2d3-44ee-bd8b-90281db527d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('525685c7-b49f-4a4f-b16e-ae0361e26806', 'Sieving and Threshing', false, '2677b18d-f2d3-44ee-bd8b-90281db527d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a86af630-f691-4095-911a-497cf9ace1cc', 'Sublimation and Freezing', false, '2677b18d-f2d3-44ee-bd8b-90281db527d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fb90460-ff89-4ebf-a511-0760f38ac853', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Match the following mixtures with their optimal method of separation:
(a) Grain seeds from stalks       -> (i) Filtration
(b) Husk from grain seeds        -> (ii) Threshing
(c) Fine clay from muddy water   -> (iii) Evaporation
(d) Salt from sea water          -> (iv) Winnowing', 'Grain from stalks = Threshing; Husk from grain = Winnowing; Fine clay = Filtration; Salt from seawater = Evaporation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd85a085-2745-4aff-bd82-4da36ead192a', 'a-(ii), b-(iv), c-(i), d-(iii)', true, '1fb90460-ff89-4ebf-a511-0760f38ac853');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0270eb79-91de-447f-b270-892119092528', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '1fb90460-ff89-4ebf-a511-0760f38ac853');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c93b7770-418e-47b7-a626-9b54d8a49608', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '1fb90460-ff89-4ebf-a511-0760f38ac853');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8d84be2-2387-446d-b560-2cce32e15130', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '1fb90460-ff89-4ebf-a511-0760f38ac853');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4df51cf-615f-401f-95a8-15baa8214315', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Read the statements:
