INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c41276e8-3ef7-48f6-b4da-b55786a19757', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Why does the rate of evaporation of water increase significantly on a hot, windy, and dry sunny afternoon?', 'Evaporation rate is directly proportional to temperature, surface area, and wind speed, and inversely proportional to relative humidity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fab4a7f-1e37-4c8e-aa93-1a756332439a', 'Higher temperature increases thermal kinetic energy, wind swiftly removes saturated vapor boundary layers, and low humidity enhances vapor gradient', true, 'c41276e8-3ef7-48f6-b4da-b55786a19757');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('515f3601-55ff-469e-a185-3416ff3f0c39', 'Wind blows the water molecules into outer space', false, 'c41276e8-3ef7-48f6-b4da-b55786a19757');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc624607-df23-4734-b31e-1f208113ff86', 'Sunlight freezes water molecules', false, 'c41276e8-3ef7-48f6-b4da-b55786a19757');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba8e2841-d1a2-4fe6-aa01-f34c4ace94d0', 'Atmospheric air turns into pure salt', false, 'c41276e8-3ef7-48f6-b4da-b55786a19757');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24a254fb-82a4-405f-ab44-bea635418fb9', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Consider four mixtures:
