INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57c54cce-e89f-4e2a-af90-677d6f129026', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad0cc3d4-8086-40be-a457-9120c2b19764', 'Statements 1 and 2 only', true, '57c54cce-e89f-4e2a-af90-677d6f129026');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf5bbe0f-9d45-40d8-a59e-888fe961df76', 'Statements 2 and 3 only', false, '57c54cce-e89f-4e2a-af90-677d6f129026');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a075f5a1-776c-4f27-8783-166473455444', 'Statements 1 and 3 only', false, '57c54cce-e89f-4e2a-af90-677d6f129026');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8df28cf3-773f-4f4f-9dec-fd6a8f5eb286', 'All Statements 1, 2, and 3', false, '57c54cce-e89f-4e2a-af90-677d6f129026');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16e8278f-d318-4b37-bbfa-8db2201bf794', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Why is folded cone-shaped filter paper moistened with a few drops of water before placing it in the glass funnel?', 'Capillary wetting seals the paper against the glass conical wall, creating continuous hydrostatic suction and preventing bypass channels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2610fbb-137d-4b1f-8e0e-0a06a6e91431', 'To ensure the filter paper adheres tightly to the glass funnel walls without air pockets, preventing unfiltered liquid from bypassing the filter', true, '16e8278f-d318-4b37-bbfa-8db2201bf794');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('676e6dde-2f5e-43f4-a154-f7307aebf4ee', 'To make the paper change color', false, '16e8278f-d318-4b37-bbfa-8db2201bf794');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0312b80a-589f-439c-8da9-20921026db57', 'To burn impurities', false, '16e8278f-d318-4b37-bbfa-8db2201bf794');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e053706e-ada4-40ac-b83b-0ad098610895', 'To block water from passing', false, '16e8278f-d318-4b37-bbfa-8db2201bf794');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a6f230b-8adb-4add-b630-8b6a72051e95', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'A beaker contains 100 mL of water saturated with salt at 25°C (containing 36 g salt). What happens if another 10 g of salt is stirred in at 25°C?', 'At 25°C, water''s solubility limit for NaCl is ~36 g/100 mL; any additional solute remains in dynamic equilibrium as undissolved precipitate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8b64b3a-0e39-4c62-a0a1-9a242672cb76', 'The extra 10 g of salt will remain completely undissolved at the bottom of the beaker', true, '8a6f230b-8adb-4add-b630-8b6a72051e95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3585694a-2fda-47f6-985d-0f02e0d1ca5b', 'The water will freeze instantly', false, '8a6f230b-8adb-4add-b630-8b6a72051e95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('007cf1e2-dbe2-47b7-95c3-79bbbe760b54', 'The extra salt will dissolve and make the solution cold', false, '8a6f230b-8adb-4add-b630-8b6a72051e95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7571e9fc-5025-4af4-afae-a8b6bb3453d5', 'The solution will evaporate completely', false, '8a6f230b-8adb-4add-b630-8b6a72051e95');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4658df92-b74b-4815-9dc5-e362f9e4722c', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Which of the following describes the physicochemical principle underlying ''Loading'' using Alum in water treatment?', 'Coagulation/loading collapses the electrical double layer of colloidal clay particulates, enabling rapid gravity sedimentation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae78dd59-eb93-4aa5-9c88-c5fa6d00d000', 'Alum hydrolyzes to provide multivalent positive aluminium ions that neutralize negative zeta potentials on suspended clay particles, causing rapid aggregation and precipitation', true, '4658df92-b74b-4815-9dc5-e362f9e4722c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd80f411-ca77-4fca-a698-ef95851a6898', 'Alum boils the water', false, '4658df92-b74b-4815-9dc5-e362f9e4722c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('589e2bc0-7a49-4cd9-b595-3f97115f2274', 'Alum turns dirt into oxygen gas', false, '4658df92-b74b-4815-9dc5-e362f9e4722c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8acc57e4-7ff7-4f02-92c8-8b452c729047', 'Alum magnifies light rays', false, '4658df92-b74b-4815-9dc5-e362f9e4722c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1381c3a4-4d3c-4875-84fd-86e69435e7ad', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'A number which has only two distinct factors, 1 and the number itself, is called a:', 'Prime numbers (2, 3, 5, 7, 11...) have exactly two positive factors: 1 and the number itself.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('798c4670-4ede-4882-8df0-6d7474c24fff', 'Prime Number', true, '1381c3a4-4d3c-4875-84fd-86e69435e7ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c56d42a5-c929-408b-9775-a68743dd4f3f', 'Composite Number', false, '1381c3a4-4d3c-4875-84fd-86e69435e7ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aed9bd61-d255-467c-9d50-5d62a82def79', 'Even Number', false, '1381c3a4-4d3c-4875-84fd-86e69435e7ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4fea070-7679-49f6-a961-eee75c8ddbb1', 'Odd Number', false, '1381c3a4-4d3c-4875-84fd-86e69435e7ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7d12858-1f88-470c-af6d-87e0aa4de69e', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'Numbers having more than two factors are called:', 'Composite numbers (4, 6, 8, 9, 10...) can be divided evenly by numbers other than 1 and themselves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('779d0a5d-29a3-4065-af4c-dcdf4694f9c0', 'Composite Numbers', true, 'd7d12858-1f88-470c-af6d-87e0aa4de69e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84b935e5-4a72-4fe8-91cc-13c809001f9e', 'Prime Numbers', false, 'd7d12858-1f88-470c-af6d-87e0aa4de69e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90df471d-3514-432d-b062-7fe8ca5dfef2', 'Odd Numbers', false, 'd7d12858-1f88-470c-af6d-87e0aa4de69e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02fc5718-8c05-449f-87c0-379a31e39e3f', 'Twin Primes', false, 'd7d12858-1f88-470c-af6d-87e0aa4de69e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecf4ce31-8076-4262-a52c-7e85bbef8863', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'Which unique number is NEITHER a prime number NOR a composite number?', 'The number 1 has only one single factor (1); hence it is neither prime (2 factors) nor composite (> 2 factors).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcf1409b-e10e-41ba-bcfa-7951f7757740', '1', true, 'ecf4ce31-8076-4262-a52c-7e85bbef8863');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d32d7292-8587-4448-b6f1-0a0e2c5c7867', '0', false, 'ecf4ce31-8076-4262-a52c-7e85bbef8863');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb768fd2-8a8a-45b9-a861-ed30f6288278', '2', false, 'ecf4ce31-8076-4262-a52c-7e85bbef8863');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc4e89aa-949e-48ff-99fa-3f71f025937e', '3', false, 'ecf4ce31-8076-4262-a52c-7e85bbef8863');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d285d8fc-4f72-44c6-8f9d-6f65cfb8e431', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'What is the smallest and ONLY EVEN prime number?', '2 is the smallest prime number and the only even prime, as all other even numbers are divisible by 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96698b51-149d-4019-bc88-8d25170164cb', '2', true, 'd285d8fc-4f72-44c6-8f9d-6f65cfb8e431');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('102699ac-f73a-4cd0-9330-c72a9ad03bc9', '4', false, 'd285d8fc-4f72-44c6-8f9d-6f65cfb8e431');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a67797-1e53-4d32-9fc9-c064a6182ea8', '0', false, 'd285d8fc-4f72-44c6-8f9d-6f65cfb8e431');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc65207f-46f9-4b8a-a053-acd8a67ae0e0', '1', false, 'd285d8fc-4f72-44c6-8f9d-6f65cfb8e431');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2205cd65-2af2-4933-938e-06da582d0684', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'Two prime numbers whose difference is exactly 2 (such as 3 and 5, or 5 and 7) are called:', 'Twin primes are pairs of prime numbers differing by 2: (3, 5), (5, 7), (11, 13), (17, 19).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d0f3f54-d589-4609-b1cd-0980fa2e33ef', 'Twin Primes', true, '2205cd65-2af2-4933-938e-06da582d0684');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c6bb6e5-9ce1-4150-a525-fa6c1f3607ea', 'Co-primes', false, '2205cd65-2af2-4933-938e-06da582d0684');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6453693c-f880-4bea-adb9-dc396f120e58', 'Perfect Numbers', false, '2205cd65-2af2-4933-938e-06da582d0684');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dc63e03-8674-44b8-9ff0-2a27cb63cc9c', 'Composite Numbers', false, '2205cd65-2af2-4933-938e-06da582d0684');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e23a253-41fb-4bae-b864-466dcaa9196b', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'Two numbers having only 1 as their common factor (such as 4 and 15) are called:', 'Two integers a and b are co-prime if their Highest Common Factor HCF(a, b) = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b2d727a-9be7-49dc-88cf-58d533311c6c', 'Co-prime Numbers (Relatively Prime)', true, '9e23a253-41fb-4bae-b864-466dcaa9196b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3ff261d-5656-4db0-ba22-b7fe078a0388', 'Twin Primes', false, '9e23a253-41fb-4bae-b864-466dcaa9196b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('634ba70c-df11-4bc5-93a9-801acb0157f9', 'Composite Numbers', false, '9e23a253-41fb-4bae-b864-466dcaa9196b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc2d69c4-2b23-46bf-a8a2-a76818bf89b7', 'Even Numbers', false, '9e23a253-41fb-4bae-b864-466dcaa9196b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e62748d-7ce4-4465-9021-2f3752918457', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'What is a number for which the sum of all its factors is equal to twice the number called?', 'For 6: factors are 1, 2, 3, 6; sum = 1+2+3+6 = 12 = 2 × 6; hence 6 is a perfect number.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4f49c81-328f-4e5a-8b75-d9ee7483a9b8', 'A Perfect Number (e.g., 6 and 28)', true, '5e62748d-7ce4-4465-9021-2f3752918457');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9691b43-24cb-41da-9648-07ea13fa5b9b', 'A Prime Number', false, '5e62748d-7ce4-4465-9021-2f3752918457');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('386ade63-ef73-4be6-8774-67523eff5427', 'A Composite Number', false, '5e62748d-7ce4-4465-9021-2f3752918457');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2df449e7-fc6e-471a-bb2c-c3e63c705def', 'A Twin Prime', false, '5e62748d-7ce4-4465-9021-2f3752918457');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a5dc6ba-6972-4ac6-92f8-bafca8954c8c', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'A number is divisible by 2 if its units digit is:', 'Divisibility by 2 requires the last digit to be an even number (0, 2, 4, 6, 8).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59894b3d-9e05-4021-8049-cb722a2bf009', '0, 2, 4, 6, or 8 (Even digit)', true, '9a5dc6ba-6972-4ac6-92f8-bafca8954c8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ab20621-759b-4076-b29c-1146f735587d', '1, 3, 5, 7, 9', false, '9a5dc6ba-6972-4ac6-92f8-bafca8954c8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b25ccf79-fa64-492b-9f99-0fada7f7f4d5', '0 or 5 only', false, '9a5dc6ba-6972-4ac6-92f8-bafca8954c8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25996794-c63a-4f17-a7ee-fd7f7dfcd5ce', 'Divisible by 3', false, '9a5dc6ba-6972-4ac6-92f8-bafca8954c8c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45202207-8725-4d66-ab4e-ef08b3d31b31', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'A number is divisible by 3 if:', 'In base-10, since 10 ≡ 1 (mod 3), a number is divisible by 3 if and only if the sum of its digits is divisible by 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba849733-3dd2-4b53-bc85-7a1ef653c93c', 'The sum of all its digits is a multiple of 3 (divisible by 3)', true, '45202207-8725-4d66-ab4e-ef08b3d31b31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d58f7c8-3b8c-414d-a7a7-df090b258f7a', 'Its last digit is 3', false, '45202207-8725-4d66-ab4e-ef08b3d31b31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c2f703f-6c8f-43f6-9999-b273006f622d', 'Its last two digits are divisible by 3', false, '45202207-8725-4d66-ab4e-ef08b3d31b31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e424493a-faa7-4435-b255-c2afb837086c', 'It is an odd number', false, '45202207-8725-4d66-ab4e-ef08b3d31b31');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e775f52-bc27-474a-9b6e-2da5d4c46fda', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'A number is divisible by 5 if its units digit is:', 'Multiples of 5 always terminate in either 0 or 5 in the standard decimal numeral system.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2e6beb4-2f07-43f7-b631-fd50ea221dbf', '0 or 5', true, '8e775f52-bc27-474a-9b6e-2da5d4c46fda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41267efc-f429-49a5-a805-06032215166f', '0, 2, 4, 6, 8', false, '8e775f52-bc27-474a-9b6e-2da5d4c46fda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('205084e9-f0dc-4212-89fc-c8510b9f00ea', '5 only', false, '8e775f52-bc27-474a-9b6e-2da5d4c46fda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d115f17-a582-4284-a21c-e2f9e06aeb09', 'Any odd digit', false, '8e775f52-bc27-474a-9b6e-2da5d4c46fda');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4b1f599-dbf8-4821-b0ab-a6950661e58f', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'What is the Highest Common Factor (HCF) of two consecutive numbers (like 8 and 9)?', 'Any two consecutive integers are always co-prime; therefore their HCF is strictly 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66c7cb4b-a1bf-4a9c-92f4-deae975e5e0b', '1', true, 'a4b1f599-dbf8-4821-b0ab-a6950661e58f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dde0d10b-1744-47c3-86c7-3a4b21c20cb8', '2', false, 'a4b1f599-dbf8-4821-b0ab-a6950661e58f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6f1a534-71a4-48a3-a154-f2a02856fb3b', 'Their product', false, 'a4b1f599-dbf8-4821-b0ab-a6950661e58f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6827baa-13fa-4f05-b2dd-559610c08602', '0', false, 'a4b1f599-dbf8-4821-b0ab-a6950661e58f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0345ce59-386f-456c-a5ea-58b960f0f149', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'What is the Lowest Common Multiple (LCM) of two co-prime numbers a and b?', 'Since HCF(a, b) = 1 and HCF × LCM = a × b, the LCM of co-prime numbers is their product a × b.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b52277c-1dfc-4f94-9beb-da4d3de48c1d', 'a × b (Their product)', true, '0345ce59-386f-456c-a5ea-58b960f0f149');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6258928-2243-4638-85d0-6cac85c3d4ea', '1', false, '0345ce59-386f-456c-a5ea-58b960f0f149');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('206d8a70-12ad-484b-bf2a-334bc62cb99b', 'a + b', false, '0345ce59-386f-456c-a5ea-58b960f0f149');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e3a26d9-ecb0-470c-8bb4-37748155f735', 'a - b', false, '0345ce59-386f-456c-a5ea-58b960f0f149');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('867f120f-34f5-4410-9671-dc48ac7b6797', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'A number is divisible by 6 if it satisfies which condition?', 'Since 6 = 2 × 3 and 2, 3 are co-prime, divisibility by 6 requires the number to be even and have a digit sum divisible by 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c87954bc-fd61-44db-99b8-cc2998aa3d05', 'It is divisible by BOTH 2 and 3 simultaneously', true, '867f120f-34f5-4410-9671-dc48ac7b6797');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52beb6f7-e950-4f7b-aa45-eda84163c25e', 'It is divisible by 2 only', false, '867f120f-34f5-4410-9671-dc48ac7b6797');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c505cb7-6202-44ae-8227-d583bb04bbdb', 'It is divisible by 3 only', false, '867f120f-34f5-4410-9671-dc48ac7b6797');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c8b6689-0302-47a3-9e1a-dc41f692facd', 'Its last digit is 6', false, '867f120f-34f5-4410-9671-dc48ac7b6797');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66c445f1-7684-49a5-a37c-d24d13689f5f', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'A number with 3 or more digits is divisible by 4 if:', 'Since 100 is divisible by 4, only the last two digits determine divisibility by 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c519dc28-7eb1-4eea-b149-cab8dbe69f25', 'The number formed by its last two digits (tens and units) is divisible by 4', true, '66c445f1-7684-49a5-a37c-d24d13689f5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b9d4976-a80c-4828-b3a0-3468d0d4d9da', 'Its units digit is 4', false, '66c445f1-7684-49a5-a37c-d24d13689f5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84b87239-3718-43e7-ae90-0472c959fa12', 'The sum of its digits is divisible by 4', false, '66c445f1-7684-49a5-a37c-d24d13689f5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc34ab81-fd0f-4b7b-8680-d24a6f6444c3', 'It ends in an odd number', false, '66c445f1-7684-49a5-a37c-d24d13689f5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('faa02f8e-c2b3-4699-bc54-33a44e6f29b7', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'A number with 4 or more digits is divisible by 8 if:', 'Since 1000 is divisible by 8, divisibility depends entirely on the last 3 digits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4083f41e-111e-4bdf-81f2-7ac6e2bd169c', 'The number formed by its last three digits (hundreds, tens, and units) is divisible by 8', true, 'faa02f8e-c2b3-4699-bc54-33a44e6f29b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9bec38d-001b-448d-9e10-3e7217a62949', 'Its last digit is 8', false, 'faa02f8e-c2b3-4699-bc54-33a44e6f29b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('429f241e-e6f9-4e08-9aee-f1d61dd9b39e', 'The sum of its digits is 8', false, 'faa02f8e-c2b3-4699-bc54-33a44e6f29b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2aabaa07-3a2b-4986-8e57-69c5542c64c5', 'It is divisible by 4 only', false, 'faa02f8e-c2b3-4699-bc54-33a44e6f29b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('788eccc7-1c61-4848-b6c5-83254bb2fd7d', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'A number is divisible by 9 if:', 'Since 10 ≡ 1 (mod 9), a number n is divisible by 9 if the sum of its decimal digits is a multiple of 9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fd357e2-222f-4455-8ffa-4515185f97fd', 'The sum of all its digits is divisible by 9', true, '788eccc7-1c61-4848-b6c5-83254bb2fd7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93fa9a6b-f304-4646-a9b6-58a7a3dd84ce', 'Its last digit is 9', false, '788eccc7-1c61-4848-b6c5-83254bb2fd7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7947e076-3c6b-4941-9e86-fdb2169fd7a3', 'Its last two digits are 99', false, '788eccc7-1c61-4848-b6c5-83254bb2fd7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80915006-f02f-4f1f-a0ff-d57993db7d41', 'It is an odd number', false, '788eccc7-1c61-4848-b6c5-83254bb2fd7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3db2342f-385d-4348-9fb1-270cfe9ad159', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'What is the divisibility test for 11?', 'Alternating sum of digits modulo 11 determines divisibility because 10 ≡ -1 (mod 11).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('022fb05a-889a-4b36-b58f-33665f58b72f', 'The difference between the sum of the digits at odd places (from right) and the sum of digits at even places is either 0 or divisible by 11', true, '3db2342f-385d-4348-9fb1-270cfe9ad159');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c80ba84e-c553-4592-b274-81c28e5be67c', 'The sum of all digits is 11', false, '3db2342f-385d-4348-9fb1-270cfe9ad159');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2d1b409-2739-4bfb-a030-3e2a9c357f9d', 'The last two digits are identical', false, '3db2342f-385d-4348-9fb1-270cfe9ad159');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45f25235-07a6-40e1-855c-0d6f6a741f69', 'The units digit is 1', false, '3db2342f-385d-4348-9fb1-270cfe9ad159');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ddda31b-1074-413f-94d4-d4466693e8cb', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Find the Prime Factorisation of the number 980:', '980 ÷ 2 = 490; 490 ÷ 2 = 245; 245 ÷ 5 = 49; 49 ÷ 7 = 7; 7 ÷ 7 = 1 -> 2² × 5 × 7².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e995cebe-f314-44e4-81d6-600f1623dfbd', '2 × 2 × 5 × 7 × 7 (2² × 5 × 7²)', true, '2ddda31b-1074-413f-94d4-d4466693e8cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2445716-356d-4e2d-8867-212a3b81ea2d', '2 × 5 × 7 × 14', false, '2ddda31b-1074-413f-94d4-d4466693e8cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d09c460-52bd-4b76-93b5-e2b896807cb8', '4 × 5 × 49', false, '2ddda31b-1074-413f-94d4-d4466693e8cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23900798-8244-4014-8cdc-6bbca46b3d86', '2 × 2 × 2 × 5 × 7', false, '2ddda31b-1074-413f-94d4-d4466693e8cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d2460c3-6e8b-48af-9f55-b4fef52855c9', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Find the HCF of 18, 54, and 81:', '18 = 2 × 3²; 54 = 2 × 3³; 81 = 3⁴. Common prime factors with lowest powers = 3² = 9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec08b662-4ceb-4f41-8ab2-7ca0050854aa', '9', true, '1d2460c3-6e8b-48af-9f55-b4fef52855c9');
