INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('822cf65e-d657-4aae-b871-f788f959d9d7', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Find the LCM of 12, 16, and 24:', '12 = 2² × 3; 16 = 2⁴; 24 = 2³ × 3. LCM = highest powers of primes = 2⁴ × 3 = 16 × 3 = 48.', NOW()) ON CONFLICT DO NOTHING;
