INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e2ff24c-5940-4057-ae0e-d2492ab43900', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'What is the HCF of two consecutive EVEN numbers (like 6 and 8, or 10 and 12)?', 'Consecutive even numbers are 2k and 2k + 2 = 2(k + 1). Since k and k + 1 are co-prime, HCF = 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c87b34df-b470-4588-897c-97a2f670b9f0', '2', true, '3e2ff24c-5940-4057-ae0e-d2492ab43900');
