INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e480ac7-9959-4407-8a94-ac03183f7c99', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Which of the following numbers is divisible by 11: 61809 or 1331?', 'For 1331: (1+3)-(3+1)=0 (div by 11). For 61809: (9+8+6)-(0+1)=23-1=22 (div by 11). Both are divisible.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75e02773-3cc2-4cdf-b8cb-eee7848f5c63', 'Both 61809 and 1331', true, '3e480ac7-9959-4407-8a94-ac03183f7c99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47404b75-8620-4a70-82e9-ba25bf4fa5aa', '1331 only', false, '3e480ac7-9959-4407-8a94-ac03183f7c99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f514e4fb-945f-49d6-b3c2-15782bf914f6', '61809 only', false, '3e480ac7-9959-4407-8a94-ac03183f7c99');
