INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dced7594-9a57-4a61-a7b3-7aa77d320042', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Two tankers contain 850 litres and 680 litres of kerosene oil respectively. Find the maximum capacity of a container which can measure the kerosene of both tankers when used an exact number of times:', '850 = 170 × 5; 680 = 170 × 4. HCF(850, 680) = 170 litres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eb8f06b-ae7a-4c70-9971-afd3f1686e88', '170 litres (HCF of 850 and 680)', true, 'dced7594-9a57-4a61-a7b3-7aa77d320042');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dfbf7ab-a84c-457e-a441-6526bb63e8a2', '85 litres', false, 'dced7594-9a57-4a61-a7b3-7aa77d320042');
