INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7e548be-8eaf-4a6d-b6ff-e60986c5e7a0', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Three boys step off together from the same spot. Their steps measure 63 cm, 70 cm, and 77 cm respectively. What is the minimum distance each should cover so that all can cover the distance in complete steps?', 'Minimum distance = LCM(63, 70, 77) = 7 × 9 × 10 × 11 = 6,930 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb632f08-3a67-4dbf-9e93-6cea8f33371d', '6,930 cm (= 69 m 30 cm)', true, 'a7e548be-8eaf-4a6d-b6ff-e60986c5e7a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa5b0677-fff3-4a95-ba65-fcdf3ac4fb9d', '6,300 cm', false, 'a7e548be-8eaf-4a6d-b6ff-e60986c5e7a0');
