INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8e7bcab-66c6-4851-b99d-27483742c419', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'What is the smallest 3-digit number which is exactly divisible by 6, 8, and 12?', 'LCM(6, 8, 12) = 24. Smallest 3-digit multiple of 24 = 24 × 5 = 120.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71b84b75-03c7-4e44-b3b8-9478350baf55', '120', true, 'd8e7bcab-66c6-4851-b99d-27483742c419');
