INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ae4276f-dc82-47c6-8743-3df78c9fc15d', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Find the least number which when divided by 6, 15, and 18 leaves a remainder of 5 in each case:', 'LCM(6, 15, 18) = 90. Required number = LCM + remainder = 90 + 5 = 95.', NOW()) ON CONFLICT DO NOTHING;
