INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e587849-e055-48d4-a9b7-e86ac9032435', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Which of the following pairs of numbers are Co-prime?', 'HCF(18, 35) = 1; HCF(15, 37) = 1; HCF(81, 16) = 1. All three pairs share no common factor other than 1.', NOW()) ON CONFLICT DO NOTHING;
