INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9d42dd8-37fa-4193-8ac0-6761a8623168', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'The traffic lights at three different road crossings change after every 48 seconds, 72 seconds, and 108 seconds respectively. If they change simultaneously at 7:00 AM, at what time will they change simultaneously again?', 'LCM(48, 72, 108) = 432 seconds = 7 minutes 12 seconds. Time = 7:07:12 AM.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bc99d45-9034-431c-ba85-4546c20906a5', '7:07:12 AM (7 hours 7 minutes 12 seconds AM)', true, 'd9d42dd8-37fa-4193-8ac0-6761a8623168');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0f36b00-a265-4c66-b135-c584ab7ec0b8', '7:12:00 AM', false, 'd9d42dd8-37fa-4193-8ac0-6761a8623168');
