INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ff70a6f-9708-4ddf-90d8-3335f1a6b7ff', '7:05:00 AM', false, 'd9d42dd8-37fa-4193-8ac0-6761a8623168');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1422a70a-5b51-40b7-81ad-96d60463fd15', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'Determine the greatest 3-digit number which is exactly divisible by 8, 10, and 12:', 'LCM(8, 10, 12) = 120. Largest 3-digit number 999 ÷ 120 = 8 with remainder 39. Greatest multiple = 999 - 39 = 960.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01877790-dd2c-4b14-9371-faf448b49844', '960', true, '1422a70a-5b51-40b7-81ad-96d60463fd15');
