INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d719f087-d8dc-4b56-89da-b5037bdd2eb6', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'Match the numbers in Column I with their properties in Column II:
(a) 35 -> (i) Multiple of 8
(b) 15 -> (ii) Factor of 30
(c) 16 -> (iii) Multiple of 7
(d) 20 -> (iv) Factor of 20', '35 = multiple of 7 (7×5); 15 = factor of 30 (30÷15=2); 16 = multiple of 8 (8×2); 20 = factor of 20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c65d7222-4bdc-42a0-89a7-6187a10c3543', 'a-(iii), b-(ii), c-(i), d-(iv)', true, 'd719f087-d8dc-4b56-89da-b5037bdd2eb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('488d7fad-4075-4b94-8970-62465ea63c85', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'd719f087-d8dc-4b56-89da-b5037bdd2eb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7768c296-6870-4946-b04c-59a88a09546c', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'd719f087-d8dc-4b56-89da-b5037bdd2eb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd07f687-6b26-4df9-8dc0-520bab394b77', 'a-(ii), b-(iv), c-(i), d-(iii)', false, 'd719f087-d8dc-4b56-89da-b5037bdd2eb6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('829e66d6-7596-42c5-b8f5-87903773e4db', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'In the 6-digit number 92_389, replace the blank (_) with the smallest digit so that the number becomes divisible by 11:', 'Odd place sum = 9 + 3 + 2 = 14. Even place sum = 8 + _ + 9 = 17 + _. (17 + _) - 14 = 3 + _ must equal 11 -> _ = 8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03a2aaca-53b1-4bbc-9bfd-322875bcfbe2', '8', true, '829e66d6-7596-42c5-b8f5-87903773e4db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3865a85-7552-4bc3-8caf-0979281156ef', '0', false, '829e66d6-7596-42c5-b8f5-87903773e4db');
