INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18abdaf9-6ef1-4b47-9867-03b534f4a443', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'What is the Prime Factorisation of the smallest 5-digit number (10,000)?', '10,000 = 10⁴ = (2 × 5)⁴ = 2⁴ × 5⁴ = 16 × 625 = 10,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caf80ed5-5edc-44c4-b98e-956248a2a047', '2⁴ × 5⁴ (2 × 2 × 2 × 2 × 5 × 5 × 5 × 5)', true, '18abdaf9-6ef1-4b47-9867-03b534f4a443');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85a7f56b-5512-4a49-aa38-7094bd7f37c5', '2⁵ × 5⁵', false, '18abdaf9-6ef1-4b47-9867-03b534f4a443');
