INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48d99258-b630-4149-9d5f-54a88a4f36db', '10⁴', false, '18abdaf9-6ef1-4b47-9867-03b534f4a443');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c36901ad-6259-4244-a9b7-e7c51d88c73e', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'The HCF and LCM of two numbers are 12 and 240 respectively. If one of the numbers is 48, what is the other number?', 'Product of two numbers = HCF × LCM -> 48 × y = 12 × 240 = 2,880 -> y = 2,880 ÷ 48 = 60.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('865c8901-66dd-45d1-a0b4-5d46d5792e3d', '60', true, 'c36901ad-6259-4244-a9b7-e7c51d88c73e');
