INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a9ff800-2058-49b0-abeb-07d4a9da985c', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'Express the number 44 as the sum of two odd primes:', 'Goldbach''s partition: 3 and 41 are both odd prime numbers and 3 + 41 = 44.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57cadd7c-c741-4796-b811-4f32c451f8d6', '3 + 41 (or 7 + 37, 13 + 31)', true, '4a9ff800-2058-49b0-abeb-07d4a9da985c');
