INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d0c8fda-528e-4ed5-8613-ae16f3f76520', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What profession did young Taro pursue for a living?', 'Taro was a young Japanese woodcutter who chopped wood on the hillside all day long.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61bdb127-3991-476f-858d-6305bda7288a', 'A woodcutter', true, '9d0c8fda-528e-4ed5-8613-ae16f3f76520');
