INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c05e8ba1-c16f-485c-bccb-08a089fb7c11', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'Where did Taro live with his elderly parents?', 'Taro lived with his old mother and father in a small wooden hut on a lonely mountainside.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad638398-19f7-427d-bf47-97fa3afa14d8', 'On a lonely hillside in Japan', true, 'c05e8ba1-c16f-485c-bccb-08a089fb7c11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0ecaa7c-14a0-4b7b-9356-08835625fca4', 'In a bustling port city', false, 'c05e8ba1-c16f-485c-bccb-08a089fb7c11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b924dc6a-fd04-41d9-8d5d-7f12ac10ae84', 'Near the emperor''s palace', false, 'c05e8ba1-c16f-485c-bccb-08a089fb7c11');
