INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd9ba192-a8a1-4d40-b0b9-1bf1b9438138', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What did Taro''s old father wish for on a very cold, windy evening?', 'Feeling the icy wind through the cracks of the hut, Taro''s shivering father wished for a cup of nourishing sake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e64704de-7950-4679-ac84-7bed2e8ec129', 'A cup of sake (a warm, expensive Japanese drink) to warm his heart', true, 'fd9ba192-a8a1-4d40-b0b9-1bf1b9438138');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('416dbca7-5451-447e-8165-64b18daf1804', 'A bowl of hot noodle soup', false, 'fd9ba192-a8a1-4d40-b0b9-1bf1b9438138');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b1e382f-006b-452f-98af-a11a403005b9', 'A woollen blanket', false, 'fd9ba192-a8a1-4d40-b0b9-1bf1b9438138');
