INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2db409e7-efec-4e51-ac72-b34d3a6c8cad', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'Why was Taro deeply saddened by his father''s wish for sake?', 'Taro was heartbroken because his meager earnings could not afford the costly traditional beverage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96bf5b59-084a-48a7-842a-0e3edd881e71', 'Because sake was very expensive, and Taro earned very little money from chopping wood', true, '2db409e7-efec-4e51-ac72-b34d3a6c8cad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ca85d62-8a18-4f15-be26-cd07ac0e9f1b', 'Because sake was forbidden in the village', false, '2db409e7-efec-4e51-ac72-b34d3a6c8cad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32f37c32-70a6-4939-996a-552219378a84', 'Because the shops were closed', false, '2db409e7-efec-4e51-ac72-b34d3a6c8cad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('879ae1ed-a86f-4e8a-9f9c-bad8ca3ae5ef', 'Because Taro disliked his father', false, '2db409e7-efec-4e51-ac72-b34d3a6c8cad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a848a1bf-4e9b-4f27-9478-627a56ec8fd1', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What did Taro do the next morning to earn more money for the sake?', 'Motivated by filial love, Taro ventured into the deep forest at dawn to chop and split extra logs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('759cd193-ca5e-4cd0-b769-57025e91b10e', 'He woke up earlier than usual and hurried to the forest to chop extra wood', true, 'a848a1bf-4e9b-4f27-9478-627a56ec8fd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('732d3b6d-16c6-4093-89b1-0c515375b52f', 'He went to borrow money from a neighbor', false, 'a848a1bf-4e9b-4f27-9478-627a56ec8fd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ae0b1a9-1e33-4d57-b174-c74ec5597fa0', 'He went to the Emperor''s court', false, 'a848a1bf-4e9b-4f27-9478-627a56ec8fd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5ae18f0-83bd-4ed2-8af5-19c3d7f839c3', 'He caught fish in the river', false, 'a848a1bf-4e9b-4f27-9478-627a56ec8fd1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f7e9d1d-8d9b-4a0c-bb67-bb1f568e1333', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What unexpected sound surprised Taro while he was chopping wood in the forest?', 'Thirsty from his hard labor, Taro heard the sound of rushing water where no stream had previously existed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43d37835-be30-48fc-9e3f-577f5b16dc03', 'The sound of rushing, splashing water from a hidden waterfall', true, '2f7e9d1d-8d9b-4a0c-bb67-bb1f568e1333');
