INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72187982-d8ec-4f11-b839-fbdbd8081ab7', 'Thunderstorm lightning', false, '2f7e9d1d-8d9b-4a0c-bb67-bb1f568e1333');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39dcc730-5fb7-4751-88b9-a19a0a7f17fb', 'A singing bird', false, '2f7e9d1d-8d9b-4a0c-bb67-bb1f568e1333');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61fdbfd4-4e1c-4fb5-9c43-8de04352b1de', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'When Taro cupped a little of the waterfall liquid in his hands and tasted it, what was it?', 'To Taro''s utter delight, the magical waterfall tasted like rich, warm, delicious sake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7ad581a-1ab2-4a3b-a941-cb8b4c7ea3a2', 'Delicious sake instead of cold water', true, '61fdbfd4-4e1c-4fb5-9c43-8de04352b1de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f856519-6c51-4135-b3d2-4449eff0411e', 'Sweet fruit juice', false, '61fdbfd4-4e1c-4fb5-9c43-8de04352b1de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45a140cd-2968-49ba-8818-311c9d3f3121', 'Bitter medicine', false, '61fdbfd4-4e1c-4fb5-9c43-8de04352b1de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd7071f0-5a26-4d24-8496-c4978260ca4a', 'Hot tea', false, '61fdbfd4-4e1c-4fb5-9c43-8de04352b1de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76cd7e44-b09c-4990-b20e-c573ffad7008', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What container did Taro fill with the magical sake to carry home to his father?', 'Taro hurriedly filled his personal wooden pitcher and ran home joyfully to his father.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daca892a-784e-4e25-983a-168dd85091a5', 'His pitcher / gourd', true, '76cd7e44-b09c-4990-b20e-c573ffad7008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d144490-3b64-4fe5-89d9-4bc238cf8851', 'A wooden bucket', false, '76cd7e44-b09c-4990-b20e-c573ffad7008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a67c14f-cb86-4487-9f49-baf998441f47', 'A clay bowl', false, '76cd7e44-b09c-4990-b20e-c573ffad7008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a098dfb-569d-4780-b84f-5e01d2b2cd2d', 'A metal bottle', false, '76cd7e44-b09c-4990-b20e-c573ffad7008');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ccdf21b4-7b42-4391-8ed8-5ae983ced5b0', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What physical effect did the sake have on Taro''s elderly father?', 'The nourishing warmth invigorated the old man so much that he happily danced on the floor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c78b363-a029-47ad-9891-a91eb6d18815', 'He stopped shivering immediately and did a joyful little dance in the middle of the floor', true, 'ccdf21b4-7b42-4391-8ed8-5ae983ced5b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8399634d-eacf-4e13-aeb5-18d47a49a997', 'He fell into a deep sleep for two days', false, 'ccdf21b4-7b42-4391-8ed8-5ae983ced5b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30e9de30-5bce-444a-9ee5-f6ce8655c309', 'He became young again', false, 'ccdf21b4-7b42-4391-8ed8-5ae983ced5b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63bed5b9-2d68-4ec1-9126-3dae278563b2', 'He grew taller', false, 'ccdf21b4-7b42-4391-8ed8-5ae983ced5b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98663892-7637-45a4-8d70-e6d782987775', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'How did the entire village learn about the magical sake waterfall by evening?', 'The neighbor lady hastily spread the gossip across the entire hamlet before nightfall.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5353b49d-4e18-4e7a-887a-1c8d9ef77130', 'A visiting neighbor lady drank a cup, heard the whole story from the father, and spread the news from house to house', true, '98663892-7637-45a4-8d70-e6d782987775');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2293d76-2a94-4758-b3b3-d12607e3b12e', 'Taro put up a notice in the marketplace', false, '98663892-7637-45a4-8d70-e6d782987775');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1cb9fed-d4ff-4582-92ff-9253cb988a83', 'The Emperor sent messengers', false, '98663892-7637-45a4-8d70-e6d782987775');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('178275d5-d8ed-4229-a52a-e36da4d7d27f', 'A bird announced it', false, '98663892-7637-45a4-8d70-e6d782987775');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13389706-6605-409c-a701-45ea368a4315', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'How did the Emperor of Japan honor and reward Taro for his profound devotion and kindness?', 'The Emperor rewarded Taro with 20 gold coins and named the grandest imperial fountain after him to inspire all children to honor parents.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f56f0c1f-cb35-4843-a05d-63ef7a901f1b', 'He rewarded him with twenty pieces of gold and named the most beautiful fountain in the city after Taro', true, '13389706-6605-409c-a701-45ea368a4315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57711a50-9b80-49dd-9207-151475d2ade2', 'He made Taro the commander of the army', false, '13389706-6605-409c-a701-45ea368a4315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3d71b37-15e2-4754-a26f-7be6f68d6eff', 'He gave Taro a palace made of glass', false, '13389706-6605-409c-a701-45ea368a4315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45924cdf-d11c-45c1-b719-8e486624e3ee', 'He gave him a flying horse', false, '13389706-6605-409c-a701-45ea368a4315');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1696dfca-a6be-4064-a0fa-59460331e63a', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'In the supplementary tale ''The Shepherd''s Treasure'', where did the wise shepherd live?', 'The humble, uneducated yet deeply wise shepherd lived in a poor village in ancient Iran.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ac743a9-3cd9-43d6-8c1f-fdd68512abb7', 'In a village in Iran (Persia)', true, '1696dfca-a6be-4064-a0fa-59460331e63a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b7d240f-5b06-41ee-a254-2c0d479c76f0', 'In the mountains of Japan', false, '1696dfca-a6be-4064-a0fa-59460331e63a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f98cec19-9c57-407b-a056-f55d25432fe1', 'In an Indian forest', false, '1696dfca-a6be-4064-a0fa-59460331e63a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('370e79fc-bcae-41b8-9ada-1570ea1ead8e', 'In a palace in Egypt', false, '1696dfca-a6be-4064-a0fa-59460331e63a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3eb9fca0-cd39-44ee-b4de-c541a7892896', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What happened when the greedy villagers rushed with pitchers and buckets to the waterfall the next morning?', 'The magic waterfall gave delicious sake only to thoughtful, devoted Taro, but gave only cold water to greedy villagers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d540bf4-9220-4b6f-9bc6-e4f7beb5ca69', 'The waterfall yielded only plain, ice-cold water to everyone else because of their selfish greed', true, '3eb9fca0-cd39-44ee-b4de-c541a7892896');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f94186d1-d91a-4493-9521-bf922b2cf5ef', 'The waterfall dried up instantly', false, '3eb9fca0-cd39-44ee-b4de-c541a7892896');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aafdffb-80d2-49f7-9288-8d55c53102cc', 'The waterfall gave boiling hot soup', false, '3eb9fca0-cd39-44ee-b4de-c541a7892896');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db0623d6-f552-4494-b090-c9a6b7b3377a', 'The waterfall turned into poison', false, '3eb9fca0-cd39-44ee-b4de-c541a7892896');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7f842df-0ffb-427a-b29a-3ab071ac9e66', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'Why were the villagers furious with Taro at the waterfall, muttering ''We have been tricked!''?', 'Expecting fine free sake, the villagers tasted only cold water and angrily threatened to drown Taro in the pool.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79a6e334-5b53-4d1a-b8b1-57b3cb500a1c', 'They tasted the water repeatedly and found it was ordinary cold water, suspecting Taro had fooled them', true, 'a7f842df-0ffb-427a-b29a-3ab071ac9e66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c1ce464-6b79-4d4d-8b15-9509b263d502', 'Taro stole their buckets', false, 'a7f842df-0ffb-427a-b29a-3ab071ac9e66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c18795ca-5820-48dd-8a54-56a1ca576aff', 'The waterfall wet their clothes', false, 'a7f842df-0ffb-427a-b29a-3ab071ac9e66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f5b4267-44bf-4d4f-bb0f-c2cabc898d67', 'The forest was too dark', false, 'a7f842df-0ffb-427a-b29a-3ab071ac9e66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f3af8e1-da02-4678-a160-5cf88629a542', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'In ''The Shepherd''s Treasure'', what made the King of Iran disguise himself as a shepherd riding on a mule?', 'Fascinated by reports of the poor shepherd''s extraordinary wisdom, the King went disguised to assess his character.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1572220c-064b-45cb-b55e-55a7a0ca6abf', 'To personally visit and test the famous wisdom, humility, and hospitality of the poor shepherd', true, '9f3af8e1-da02-4678-a160-5cf88629a542');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97e60986-abb9-4bdd-bb9e-f4d000800f1a', 'To escape from enemy soldiers', false, '9f3af8e1-da02-4678-a160-5cf88629a542');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a71234-365f-4d1c-b648-b685556c25bc', 'To hunt wild deer in the mountains', false, '9f3af8e1-da02-4678-a160-5cf88629a542');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c48a26f-126e-4ef3-8944-ec5edc95deef', 'To look for hidden gold', false, '9f3af8e1-da02-4678-a160-5cf88629a542');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5aa40473-08a0-49f1-9a00-6fa0ad87383d', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'How did the poor shepherd treat the disguised King who arrived at his cave door exhausted?', 'The shepherd welcomed the stranger warmly, offering fresh water and half of his modest meal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6cb07ff-6b8d-4625-9449-05a39f06ca06', 'With warm hospitality: sharing his own meager supper of food, fresh spring water, and shelter for the night', true, '5aa40473-08a0-49f1-9a00-6fa0ad87383d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f293d1a-b12f-4f14-86d1-e4cd4b15f664', 'He asked for payment before opening the door', false, '5aa40473-08a0-49f1-9a00-6fa0ad87383d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c54073f9-e21c-47a3-9820-05f46c6e2d76', 'He told the traveler to sleep in the cold', false, '5aa40473-08a0-49f1-9a00-6fa0ad87383d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78f8e77f-f621-4561-91cb-be89f6112491', 'He reported him to the police', false, '5aa40473-08a0-49f1-9a00-6fa0ad87383d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd5d5ce2-0c87-4fa3-bc7d-ddeff7766a87', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What position did the impressed King bestow upon the wise shepherd?', 'Deeply impressed by his natural wisdom, justice, and kindness, the King appointed him Governor of a district.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8fc61bf-13bb-4d96-8462-f8c9cb5b0335', 'Governor of a small district', true, 'fd5d5ce2-0c87-4fa3-bc7d-ddeff7766a87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62530f2c-f4bd-4e56-8258-cef82782f7eb', 'Chief General of the army', false, 'fd5d5ce2-0c87-4fa3-bc7d-ddeff7766a87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b02ad581-9c74-4089-9126-15ed863fa7b0', 'Imperial Treasurer', false, 'fd5d5ce2-0c87-4fa3-bc7d-ddeff7766a87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90e82b97-b747-4465-9bf1-6a80651e897d', 'Royal Cook', false, 'fd5d5ce2-0c87-4fa3-bc7d-ddeff7766a87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e182eeef-6eef-4054-9588-30675dee04d3', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'Why did other jealous governors in neighboring provinces plot against the new shepherd-governor?', 'His incorruptible justice and widespread public adoration provoked bitter jealousy among the corrupt aristocrats.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b550e4fb-f122-4a27-b615-3ab6daad4097', 'They were intensely envious of his soaring popularity, wisdom, and the King''s immense trust in him', true, 'e182eeef-6eef-4054-9588-30675dee04d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4853df8-249c-402a-a350-9bc0029dc757', 'He stole money from their provinces', false, 'e182eeef-6eef-4054-9588-30675dee04d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfd942cd-a2ff-4dc8-9ee0-0b773bb2d103', 'He refused to wear fine clothes', false, 'e182eeef-6eef-4054-9588-30675dee04d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d54c2e11-9626-491e-a10d-a6013fbfb2c4', 'He closed all markets', false, 'e182eeef-6eef-4054-9588-30675dee04d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb23fb7c-f6ef-4a14-a5c8-4fc3e894fa35', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What false accusation did the jealous governors bring against the shepherd-governor before the King?', 'They falsely alleged that the iron box he always carried contained embezzled tax revenues.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9187f586-05b9-4ba7-beb9-2b8c4d250da6', 'They claimed he was dishonest and secretly carried stolen tax gold in an iron chest strapped to his camel''s back', true, 'bb23fb7c-f6ef-4a14-a5c8-4fc3e894fa35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65ca337f-41b0-457f-9046-3120ea3bfda7', 'They claimed he was an enemy spy', false, 'bb23fb7c-f6ef-4a14-a5c8-4fc3e894fa35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a4f4884-6a67-4f47-8f78-c0033ad71157', 'They said he murdered a merchant', false, 'bb23fb7c-f6ef-4a14-a5c8-4fc3e894fa35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54f5b595-ae04-4f3f-919b-acfa948092a9', 'They said he refused to pay respect to the King', false, 'bb23fb7c-f6ef-4a14-a5c8-4fc3e894fa35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ccc9707-42ea-4fee-aad8-c7ffd59305c1', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'When the King ordered the iron chest to be opened in the royal court, what was discovered inside?', 'The chest contained only his humble old woollen blanket, which he kept as a reminder of his true self.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fcecdeb-3fd7-48be-9689-b7bebd550ff2', 'No gold, jewels, or silver — only an old, worn-out woollen blanket', true, '8ccc9707-42ea-4fee-aad8-c7ffd59305c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb6ea906-5471-4be9-a6dd-6a5f9a64c630', 'A hoard of glittering diamonds and gold coins', false, '8ccc9707-42ea-4fee-aad8-c7ffd59305c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('890d9cfc-cd1f-4c7d-8d89-934362a7ee90', 'A bundle of secret enemy maps', false, '8ccc9707-42ea-4fee-aad8-c7ffd59305c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e88d7673-b920-48b6-8736-a1f8e9e80347', 'The box was completely empty', false, '8ccc9707-42ea-4fee-aad8-c7ffd59305c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8a7f3ba-a477-4868-8045-47de244e9777', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'Why did the shepherd-governor always carry his old blanket everywhere with him?', 'The blanket symbolized true humility; if fortune and titles vanished, his honest blanket would remain his steadfast shield.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2327b7f-8ba8-4a50-b0bc-da6bdb546a65', 'Because it was his oldest friend that would still protect him from cold even if the King stripped him of all titles and royal cloaks', true, 'e8a7f3ba-a477-4868-8045-47de244e9777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b222ff35-8045-4791-a980-d5b0a167bc81', 'Because it had magical flying powers', false, 'e8a7f3ba-a477-4868-8045-47de244e9777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ec69134-5098-4b3e-ba02-b70450ccfce3', 'Because it was given by a wizard', false, 'e8a7f3ba-a477-4868-8045-47de244e9777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('663b5714-0918-49e4-b2f4-bc6542e4b55e', 'Because it was very heavy', false, 'e8a7f3ba-a477-4868-8045-47de244e9777');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29679afe-2098-4926-a518-cf5c976bd689', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What did the King do after witnessing the shepherd''s supreme humility, honesty, and wisdom?', 'Vindicated and moved by his sterling character, the King promoted the shepherd to govern a much larger province.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('086227bc-a93a-411d-b06b-393b5c75def7', 'He made him the governor of a much bigger district and publicly shamed the jealous accusers', true, '29679afe-2098-4926-a518-cf5c976bd689');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('186a849a-6388-4509-84b2-8826927c7797', 'He dismissed him from service', false, '29679afe-2098-4926-a518-cf5c976bd689');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab55ed40-d7ed-4df2-a863-e45c3ffb4808', 'He confiscated his blanket', false, '29679afe-2098-4926-a518-cf5c976bd689');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('453c2080-62f0-4377-a2b4-6dcc74ee5999', 'He sent him back to his cave', false, '29679afe-2098-4926-a518-cf5c976bd689');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77f51518-ba4d-45cc-86a8-7365e8307f17', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What does the word ''Whistled through'' mean in: ''A cold wind whistled through the cracks of the hut''?', 'Describing the high-velocity freezing gale producing a sharp aerodynamic whistling noise through timber crevices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9163eb91-f5e3-44f9-8b42-4d808890e95d', 'Passed through making a shrill whistling sound', true, '77f51518-ba4d-45cc-86a8-7365e8307f17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15094944-c25c-4da9-903b-ee771bfffa39', 'Blew the hut away completely', false, '77f51518-ba4d-45cc-86a8-7365e8307f17');
