INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41d5566d-f3f8-4e0a-8b78-47d8497ebcfa', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What is the meaning of the word ''Pitted'' or ''Pitcher'' in the story of Taro?', 'A pitcher is a container (often with a handle and lip) designed to carry and dispense potable liquids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31dc17d9-b965-40d6-a1a2-dd2ff02bb176', 'A pot / vessel made of earthenware or wood for holding liquids', true, '41d5566d-f3f8-4e0a-8b78-47d8497ebcfa');
