INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8c4c9c4-2076-4942-9e86-494b558b22ef', 'A sharp axe', false, '41d5566d-f3f8-4e0a-8b78-47d8497ebcfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c883093f-1ebd-43f9-9195-2f7ed49b7eb9', 'A wooden cart', false, '41d5566d-f3f8-4e0a-8b78-47d8497ebcfa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bb0d7ce-2c74-403d-94b9-7e6f652a49de', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What does the phrase ''to chop and hew'' mean in describing Taro''s labor?', '''Hew'' means to hack, shape, or fell timber using sharp heavy cutting tools.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('896647e7-58d2-405b-b8d3-bd1ad46cf100', 'To cut down trees and strike wood with repeated heavy blows of an axe', true, '8bb0d7ce-2c74-403d-94b9-7e6f652a49de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb9d141c-8ea5-436e-8f2b-08fbde4b4c34', 'To paint timber', false, '8bb0d7ce-2c74-403d-94b9-7e6f652a49de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7577d00c-09f6-4170-b498-6f9e2cc156fa', 'To plant new saplings', false, '8bb0d7ce-2c74-403d-94b9-7e6f652a49de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a52a02ca-b1fc-4560-bdb2-bf5e33b9f5c2', 'To climb trees', false, '8bb0d7ce-2c74-403d-94b9-7e6f652a49de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4112cd2d-1d0a-4e94-8c07-2cfabdd36908', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'Why did Taro hide behind a rock when the villagers arrived at the waterfall?', 'Prudent Taro concealed himself until the shouting, disappointed mob departed back to the village.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('071d9e37-9fd2-4ef6-8e9e-3c43c4216558', 'He saw their wild fury and did not want to face their violent anger when they found only water', true, '4112cd2d-1d0a-4e94-8c07-2cfabdd36908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5e4ca63-3176-419e-ba8d-41ca5380b89e', 'He wanted to scare them', false, '4112cd2d-1d0a-4e94-8c07-2cfabdd36908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e259a67e-6e8a-44df-be15-69046547ca35', 'He fell asleep behind the rock', false, '4112cd2d-1d0a-4e94-8c07-2cfabdd36908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('027bec12-87b1-40d7-a0c8-3a94ca2e1e75', 'He was waiting for the Emperor', false, '4112cd2d-1d0a-4e94-8c07-2cfabdd36908');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62ee9c3e-ee7d-4f63-9ffb-74d96ffee4c1', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What is the primary moral message of ''Taro''s Reward'' for young children?', 'The tale exemplifies the virtues of filial piety, selfless love, and honest industrious labor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdd1cafb-fb21-4f61-9ad4-67847c422576', 'Diligence, thoughtful care, and profound devotion to one''s parents earn the highest divine and human rewards', true, '62ee9c3e-ee7d-4f63-9ffb-74d96ffee4c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('195cf730-dfba-4840-8593-dd0443c110be', 'Magic waterfalls exist in every mountain', false, '62ee9c3e-ee7d-4f63-9ffb-74d96ffee4c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abda9c03-f040-4fa8-8916-0bee7345121c', 'Greed always brings wealth', false, '62ee9c3e-ee7d-4f63-9ffb-74d96ffee4c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a36d0923-77e1-486b-b83c-2bd18ffab097', 'Woodcutting is the best job', false, '62ee9c3e-ee7d-4f63-9ffb-74d96ffee4c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('238ec983-7a3e-4914-b4d0-1022a1839a53', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'In ''The Shepherd''s Treasure'', how is true nobility of character demonstrated?', 'Inner virtue, incorruptibility, and humility outshine all artificial titles, wealth, and ancestral pedigree.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5fced50-ecca-44ee-83ef-331d0ce822e7', 'Through steadfast humility, unwavering honesty, and wisdom, regardless of one''s humble birth or elevated royal station', true, '238ec983-7a3e-4914-b4d0-1022a1839a53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d209195e-0f5f-45c3-86dd-e3716d3c07c9', 'Through wearing expensive gold ornaments', false, '238ec983-7a3e-4914-b4d0-1022a1839a53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17e98bac-8628-4a4d-b60d-0e0375da462d', 'Through defeating enemies in battle', false, '238ec983-7a3e-4914-b4d0-1022a1839a53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11785ad2-2d2b-452e-97de-9a19fa883412', 'Through collecting high taxes', false, '238ec983-7a3e-4914-b4d0-1022a1839a53');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc51c754-31aa-4fb0-b6c2-568bf15edde5', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0168212-3a11-4f97-a681-d9ef368645d2', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'fc51c754-31aa-4fb0-b6c2-568bf15edde5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a959ee6-fcf0-44ae-b0c2-32476969a372', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'fc51c754-31aa-4fb0-b6c2-568bf15edde5');
