INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1f21fa5-7c48-4220-8925-3cafdde7214f', '(A) is false, but (R) is true.', false, 'fc51c754-31aa-4fb0-b6c2-568bf15edde5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('055693d5-93d3-4b44-a3e0-1d3fc8984f42', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Spot the IMPOSTER in the following group of vocabulary words from Chapter 3 paired with their meanings:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fee35ca7-19b7-470d-a11b-63be2aeb9914', 'Kneel - bend on knees', false, '055693d5-93d3-4b44-a3e0-1d3fc8984f42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1e949ae-f424-406e-8cce-e038176da458', 'Gourd - a fleshy fruit/pitcher', false, '055693d5-93d3-4b44-a3e0-1d3fc8984f42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('065d2a96-09a2-4251-be64-ec0ee35e3301', 'Chieftain - a leader/ruler', false, '055693d5-93d3-4b44-a3e0-1d3fc8984f42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa1469ab-93a9-4872-88e8-b9d59d77d0df', 'Delighted - intensely angry', true, '055693d5-93d3-4b44-a3e0-1d3fc8984f42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d06e3f40-0e97-4f00-b8ce-f8af408b54c1', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'What profound psychological contrast is portrayed between Taro and the village community?', 'Taro toiled selflessly for his family, whereas the envious neighbors rushed en masse with pots purely for selfish indulgence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e87ae41-1977-46b8-8949-9f5708b2451a', 'Taro was driven by selfless love and extra toil to comfort his parents, while the villagers were driven by opportunistic greed to exploit free luxury', true, 'd06e3f40-0e97-4f00-b8ce-f8af408b54c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9707f05-5551-4ea7-a6df-f06a59dbab7d', 'Taro was lazy while the villagers worked hard', false, 'd06e3f40-0e97-4f00-b8ce-f8af408b54c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3ae5b18-4d9a-43ac-bf95-3778c157e8c4', 'Taro was greedy for gold', false, 'd06e3f40-0e97-4f00-b8ce-f8af408b54c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4be47303-db61-4df3-aa6a-c6ec0128669b', 'The villagers wanted to help Taro''s father', false, 'd06e3f40-0e97-4f00-b8ce-f8af408b54c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f038d09-1630-4fa3-9b36-f59c52f6d32d', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'In ''The Shepherd''s Treasure'', what symbolic meaning did the old woollen blanket hold for the wise governor?', 'The blanket preserved his philosophical humility, ensuring he never succumbed to arrogance or the vanity of royal office.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97dcabe3-314a-4929-9d58-6fe3f6e08d4f', 'It was a grounding talisman of his humble origins, reminding him that worldly power is fleeting and moral integrity is eternal', true, '2f038d09-1630-4fa3-9b36-f59c52f6d32d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1c412f1-7972-4faa-979f-8dfb316e65a6', 'It contained a hidden treasure map sewn in the seam', false, '2f038d09-1630-4fa3-9b36-f59c52f6d32d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e081e9d-dab7-43d1-90a3-77e00353350b', 'It was worth millions of gold dinars', false, '2f038d09-1630-4fa3-9b36-f59c52f6d32d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d17d936e-483c-472b-b08d-7d59b289d77b', 'It was a royal gift from his grandfather', false, '2f038d09-1630-4fa3-9b36-f59c52f6d32d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47b478ce-fe24-46a3-8770-fa41a7d53028', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Match the following characters with their distinctive traits:
(a) Taro             -> (i) Wise, humble, and incorruptible
(b) Iranian Shepherd -> (ii) Inquisitive, just, and appreciative of true virtue
(c) The Persian King -> (iii) Selfless, hardworking, and devoted son
(d) Jealous Governors-> (iv) Malicious, corrupt, and envious', 'Taro = devoted son; Shepherd = wise & humble; King = just & appreciative; Governors = corrupt & envious.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ad49279-4ffb-4a7a-8c84-9b2fe8c8062f', 'a-(iii), b-(i), c-(ii), d-(iv)', true, '47b478ce-fe24-46a3-8770-fa41a7d53028');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8580d494-1423-4d2c-ab72-1f57d7652467', 'a-(i), b-(iii), c-(ii), d-(iv)', false, '47b478ce-fe24-46a3-8770-fa41a7d53028');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69760d62-513d-467a-8269-839d103b7ba3', 'a-(iv), b-(ii), c-(i), d-(iii)', false, '47b478ce-fe24-46a3-8770-fa41a7d53028');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d3f41ad-39cd-4b79-b00b-6661db9b8ca6', 'a-(ii), b-(iv), c-(iii), d-(i)', false, '47b478ce-fe24-46a3-8770-fa41a7d53028');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a7aed02-1b30-4d2c-82aa-4f09023dcf72', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Read the statements from the story:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3cf74c0-e2fa-4786-ac4b-751b58004678', 'Statements 1 and 3 only', true, '7a7aed02-1b30-4d2c-82aa-4f09023dcf72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('434cb757-8737-440e-b1c4-adf222287c75', 'Statements 1 and 2 only', false, '7a7aed02-1b30-4d2c-82aa-4f09023dcf72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6a72c9b-e549-4569-8a5a-ec762fd58309', 'Statements 2 and 3 only', false, '7a7aed02-1b30-4d2c-82aa-4f09023dcf72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd48925e-585b-437c-8ca1-fd2dba9c2267', 'All Statements 1, 2, and 3', false, '7a7aed02-1b30-4d2c-82aa-4f09023dcf72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5f3b83a-560d-4f68-b733-3315c16071be', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Identify the part of speech of the underlined word in the sentence: ''Taro worked *harder* than ever to earn money.''', '''Harder'' modifies the verb ''worked'' in the comparative degree, functioning as an Adverb.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('828c0197-0fe3-40cc-ac1b-b836d1a33f50', 'Adverb (Comparative degree)', true, 'c5f3b83a-560d-4f68-b733-3315c16071be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ba634ed-bce0-4d10-afb5-2833c41b739b', 'Adjective', false, 'c5f3b83a-560d-4f68-b733-3315c16071be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('583076f5-4a8e-4932-a918-77684898cbbb', 'Noun', false, 'c5f3b83a-560d-4f68-b733-3315c16071be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22336740-d9d7-4516-bacc-984413a1e70c', 'Preposition', false, 'c5f3b83a-560d-4f68-b733-3315c16071be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7d00ac6-81d3-4cea-8ae3-f1855baf3031', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'What is the meaning of the idiomatic phrase ''to have one''s heart warmed'' in literature?', 'Metaphorical idiom expressing profound internal emotional comfort, solace, and gratitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dabf9587-3f0a-49a6-ba7d-751632d28d7d', 'To feel deep emotional joy, satisfaction, affection, or gratitude', true, 'c7d00ac6-81d3-4cea-8ae3-f1855baf3031');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5668f1a0-e2bc-43d1-a6f1-6b19e63ec34e', 'To suffer from physical fever', false, 'c7d00ac6-81d3-4cea-8ae3-f1855baf3031');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d1afbf6-fd16-47f9-b79a-87d79fa0bdfd', 'To sit too close to a fireplace', false, 'c7d00ac6-81d3-4cea-8ae3-f1855baf3031');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f426ee4-e48e-4c78-810e-dde2abc483bb', 'To drink hot water', false, 'c7d00ac6-81d3-4cea-8ae3-f1855baf3031');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40ff515d-7783-48b8-9a0a-80e4d6c4cbbc', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'In ''The Shepherd''s Treasure'', why was the King delighted when the shepherd gave his famous answer about the blanket?', 'The shepherd''s humble reply vindicated the King''s original trust and utterly demolished the slanders of the jealous governors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3a161f2-d910-49bd-8a05-91b180f67843', 'Because the shepherd proved beyond all doubt that he was truly the wisest, most honest, and uncorrupted man in the entire kingdom', true, '40ff515d-7783-48b8-9a0a-80e4d6c4cbbc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb9ce4ef-08c0-46f5-bce0-cd2c5de40fcd', 'Because the King wanted to borrow the blanket', false, '40ff515d-7783-48b8-9a0a-80e4d6c4cbbc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cd14b39-3ad1-42bc-ba06-3e7ebe60a47f', 'Because the King found gold under the carpet', false, '40ff515d-7783-48b8-9a0a-80e4d6c4cbbc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('071802a0-71a6-4691-8951-b05c58789998', 'Because the court cheered for war', false, '40ff515d-7783-48b8-9a0a-80e4d6c4cbbc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48d42eb3-cd66-4e51-a541-d3c04cd1211b', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Choose the correct sentence showcasing the proper use of the conjunction ''although'':', 'Concessive conjunction ''Although'' introduces a subordinate clause of contrast without combining with ''but''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f7bae28-267f-42b1-8bc3-26669f5d8e3a', 'Although Taro was poor, he never hesitated to work tirelessly for his parents'' comfort.', true, '48d42eb3-cd66-4e51-a541-d3c04cd1211b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b347881a-37b0-421e-b521-cc1fb9e15f22', 'Although Taro was rich but he worked hard.', false, '48d42eb3-cd66-4e51-a541-d3c04cd1211b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('166071d5-6a29-42a6-9200-baddb547d7b2', 'Taro although poor so he slept all day.', false, '48d42eb3-cd66-4e51-a541-d3c04cd1211b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('445cc314-9e8c-4cc7-b944-b7e7b0835a2a', 'Although he worked but he earned gold.', false, '48d42eb3-cd66-4e51-a541-d3c04cd1211b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b6eb36e-9656-4041-8fe6-f25fd3893e53', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'What narrative structure is common to both ''Taro''s Reward'' and ''The Shepherd''s Treasure''?', 'Both classic didactic fables utilize a moral test where an underdog of supreme virtue is elevated by wise royal authority.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ed64917-90cf-47fd-a668-d8a6a6e652d3', 'Both feature an undercover/mystical test of virtue where true moral integrity is rewarded by a sovereign ruler while shallow jealousy/greed is exposed', true, '9b6eb36e-9656-4041-8fe6-f25fd3893e53');
