INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ec30efd-ea7c-4708-af0b-16b3705ba850', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'What causes the cycle of changing SEASONS (Summer, Winter, Spring, Autumn) on Earth?', 'Seasonal changes result from cyclical variations in solar insolation caused by Earth''s orbital revolution and persistent 23.5° axial tilt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48b6f06b-ca21-497e-9430-52521e961b35', 'The Revolution of the Earth around the Sun combined with the fixed inclination of Earth''s axis (23½° tilt)', true, '4ec30efd-ea7c-4708-af0b-16b3705ba850');
