INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f017d694-f1e8-4cf0-b2e3-7f7e1fe21886', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'The imaginary circle that divides the day from night on the globe is called the:', 'The Circle of Illumination is the great circle boundary dividing the sunlit day hemisphere from the darkened night hemisphere.', NOW()) ON CONFLICT DO NOTHING;
