INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b99a4ef-dcca-4c82-98e4-ca68f1224008', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'How much time does the Earth take to complete one full rotation on its axis (known as an ''Earthday'')?', 'Earth rotates 360° relative to the Sun in precisely 24 hours, defining our standard daily civil time.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('562e4e2a-b77b-42f9-bc2d-a95b3aafc6d6', '24 hours (1 solar day)', true, '9b99a4ef-dcca-4c82-98e4-ca68f1224008');
