INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75776b34-7134-4f2a-9ef8-84fef3874aa9', '12 hours', false, '9b99a4ef-dcca-4c82-98e4-ca68f1224008');
