INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ceac696-0594-4bdd-adce-3706eaf57fb9', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'How long does the Earth take to complete one full orbital revolution around the Sun?', 'One sidereal/tropical orbital revolution takes ~365.242 days (365 days and ~6 hours).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25dce278-607e-4e4f-9743-b8d744745e0c', '365 days and 6 hours (365¼ days)', true, '7ceac696-0594-4bdd-adce-3706eaf57fb9');
