INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5fff91c-6813-4dff-bb5f-a0d4752a6d3a', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'How many days are there in a ''Leap Year'', and which month has 29 days instead of 28?', 'The surplus 6 hours (¼ day) accumulated over 4 consecutive years equals 24 hours (1 full day), added to February every leap year.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d5c7fb6-f117-49e4-8ed4-32da69f75903', '366 days, with February having 29 days', true, 'b5fff91c-6813-4dff-bb5f-a0d4752a6d3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55fc09c8-b6fc-4b82-b870-7fb2467e55bf', '365 days, with February having 29 days', false, 'b5fff91c-6813-4dff-bb5f-a0d4752a6d3a');
