INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c418de6e-5a98-453c-993d-bb3785974925', '368 days', false, 'b5fff91c-6813-4dff-bb5f-a0d4752a6d3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf4596d5-c64b-470b-bbfa-dd08ded4a757', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'On which date does the Northern Hemisphere experience the ''Summer Solstice'' with the longest day and shortest night?', 'On 21 June, the Tropic of Cancer receives direct perpendicular solar rays; the North Pole tilts towards the Sun.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eec1da57-b1f9-4dd4-a308-f8593728ca10', '21st June', true, 'bf4596d5-c64b-470b-bbfa-dd08ded4a757');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2749dd0-e3c4-428f-b7c2-b25338c437d9', '22nd December', false, 'bf4596d5-c64b-470b-bbfa-dd08ded4a757');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1be3bda-3b11-4fdf-bd4c-3fe176364ec6', '21st March', false, 'bf4596d5-c64b-470b-bbfa-dd08ded4a757');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1303edcf-aab1-4b54-85c3-e22a34c80766', '23rd September', false, 'bf4596d5-c64b-470b-bbfa-dd08ded4a757');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2823c042-afe7-4ed7-86e4-c8cba4e8025b', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'On which date does the Southern Hemisphere experience the ''Summer Solstice'' (longest day in Southern Hemisphere / Winter Solstice in Northern Hemisphere)?', 'On 22 December, the Sun shines directly over the Tropic of Capricorn (23½° S), bringing midsummer to the Southern Hemisphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f18e404e-855c-45fa-b292-6513f86a4256', '22nd December', true, '2823c042-afe7-4ed7-86e4-c8cba4e8025b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('615addf4-52ea-4773-9970-11fea249016c', '21st June', false, '2823c042-afe7-4ed7-86e4-c8cba4e8025b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe857f5c-6a81-42e2-b0b8-8ce7d52b5778', '23rd September', false, '2823c042-afe7-4ed7-86e4-c8cba4e8025b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e71f32b3-a5b4-47b8-be4b-9ec545ce1749', '21st March', false, '2823c042-afe7-4ed7-86e4-c8cba4e8025b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6e53254-397c-40fd-8202-57ee529008d6', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'On which two dates does the Earth experience an ''Equinox'' when direct rays of the Sun fall on the Equator and day and night are of equal duration all over the world?', 'During Equinoxes (21 March Vernal & 23 September Autumnal), neither pole tilts toward the Sun, resulting in equal 12-hour day and night.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9bede61-5d35-4292-84d0-32f30a9ee546', '21st March and 23rd September', true, 'a6e53254-397c-40fd-8202-57ee529008d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11107973-f72a-4ea5-a925-7e73ba224dc0', '21st June and 22nd December', false, 'a6e53254-397c-40fd-8202-57ee529008d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e274db3-884e-450a-b58a-cfb5a224ea73', '1st January and 1st July', false, 'a6e53254-397c-40fd-8202-57ee529008d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acc33ce7-9c7f-4166-bfa7-8dd7253d7214', '15th August and 26th January', false, 'a6e53254-397c-40fd-8202-57ee529008d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6741004d-312a-4359-ada9-d44becf40514', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'In which country is Christmas famously celebrated in the middle of summer?', 'Christmas falls on 25 December during peak summer in the Southern Hemisphere (Australia, New Zealand, South Africa).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d848e5b-64ef-48e8-92d3-2d7939697063', 'Australia (Southern Hemisphere)', true, '6741004d-312a-4359-ada9-d44becf40514');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02433652-0a11-42ef-845f-ddab6a997b62', 'United Kingdom', false, '6741004d-312a-4359-ada9-d44becf40514');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19e53f4a-af0a-4c1c-9a24-e7c1c898aba1', 'Canada', false, '6741004d-312a-4359-ada9-d44becf40514');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58d2dc72-95aa-44c4-8f7c-68581dd28317', 'Norway', false, '6741004d-312a-4359-ada9-d44becf40514');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51012a3f-0ff9-463e-a981-48ac4c4b5c6d', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What would happen if the Earth stopped rotating on its axis entirely?', 'Cessation of spin would create a tidally locked thermal catastrophe: an unlivable subsolar oven on one side and an absolute cryogenic desert on the other.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e97b914-10eb-4f2e-86f4-45a17257946a', 'The hemisphere facing the Sun would be in permanent scorching daylight and extreme heat, while the other hemisphere would remain in perpetual freezing darkness, making life impossible', true, '51012a3f-0ff9-463e-a981-48ac4c4b5c6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2784ffbe-c25b-42c8-8814-a5fcb5646a22', 'All humans would fly into space', false, '51012a3f-0ff9-463e-a981-48ac4c4b5c6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42c3f016-8b63-4d0f-837a-db15bc329bcc', 'The Sun would turn into ice', false, '51012a3f-0ff9-463e-a981-48ac4c4b5c6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d10b878-2975-4fdf-b23c-636540a39696', 'Seasons would change every 2 hours', false, '51012a3f-0ff9-463e-a981-48ac4c4b5c6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('842b7224-902e-4639-a0d3-aeb673a701e0', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Does the Circle of Illumination coincide with the Earth''s rotational axis?', 'The Circle of Illumination is perpendicular to solar rays, while Earth''s tilted axis maintains a fixed 66.5° angle to the orbital plane.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6259df1-0945-4203-9a9e-a34f3793b8cf', 'No, because the Earth''s rotational axis is tilted at an angle of 23½° from the perpendicular (66½° with the orbital plane)', true, '842b7224-902e-4639-a0d3-aeb673a701e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('273bfa79-e79a-40c7-b43d-a07593883620', 'Yes, they are the exact same line', false, '842b7224-902e-4639-a0d3-aeb673a701e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48aec9c9-57d1-4633-a018-f9d283128ec3', 'Yes, only on Mondays', false, '842b7224-902e-4639-a0d3-aeb673a701e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0f679a2-2419-4727-b823-8b10220ad0d7', 'Only during midnight', false, '842b7224-902e-4639-a0d3-aeb673a701e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2328954f-11a8-483e-a622-81db35121590', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Why do places beyond the Arctic Circle (66½° N) experience continuous daylight (the ''Midnight Sun'') for about 6 months around June?', 'Axial tilt positions the circumpolar region entirely within the sunlit hemisphere throughout the daily 360° spin.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10f68e77-ea64-48ea-ace5-1269653f37a2', 'The North Pole remains tilted towards the Sun continuously as Earth rotates, so the Arctic region stays inside the Circle of Illumination for 24 hours a day', true, '2328954f-11a8-483e-a622-81db35121590');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b536779-6e32-4528-a98f-820ad0dda4f5', 'The Moon turns into a small sun', false, '2328954f-11a8-483e-a622-81db35121590');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51e2c73e-4420-434b-bfe8-d76927037858', 'Snow reflects light like a mirror', false, '2328954f-11a8-483e-a622-81db35121590');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('891b8345-8464-4471-bcc9-1946faacf940', 'The Sun stops setting in all galaxies', false, '2328954f-11a8-483e-a622-81db35121590');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e48fe96-edad-4d0e-aa01-f42fcfa95400', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Why do areas around the Poles receive minimum heat even during long daylight hours in summer?', 'Low solar elevation angle reduces radiant flux per unit surface area according to Lambert''s cosine law.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9573a70-3e3b-4cd2-9e97-1c243e20e9f0', 'The sun''s rays strike the polar surface at an extremely acute, slanting angle, spreading the heat energy over a very large area', true, '9e48fe96-edad-4d0e-aa01-f42fcfa95400');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea1590e8-ded8-421b-b89d-4446f0b827d3', 'Poles have no air', false, '9e48fe96-edad-4d0e-aa01-f42fcfa95400');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('601704c5-9ae4-4afb-96bd-c05f60b1cf32', 'The Sun is millions of miles farther from the poles', false, '9e48fe96-edad-4d0e-aa01-f42fcfa95400');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f92f110-ba9e-4363-a6d6-6857c62a49db', 'Ice pushes the Sun away', false, '9e48fe96-edad-4d0e-aa01-f42fcfa95400');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed641d6c-93f7-4395-93b5-b41b279049f5', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What is the shape of the Earth''s orbit around the Sun?', 'Kepler''s First Law: All planets orbit the Sun in an elliptical path with the Sun situated at one of the two focal points.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7cd4437-d440-45e2-a1dd-a22a1cedbe27', 'An Elliptical orbit (an elongated, oval circle)', true, 'ed641d6c-93f7-4395-93b5-b41b279049f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6792bd6b-54e3-457a-a4e9-156c82438a88', 'A perfect circle', false, 'ed641d6c-93f7-4395-93b5-b41b279049f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22fb1194-befa-4166-8986-0a9056266284', 'A straight line', false, 'ed641d6c-93f7-4395-93b5-b41b279049f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7edd831-5d0b-4cba-93c0-7cec66c1d672', 'A square path', false, 'ed641d6c-93f7-4395-93b5-b41b279049f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75def6b5-534a-4adb-9e30-6ee775fc27e5', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'On 23rd September, what season is experienced in the Northern Hemisphere and Southern Hemisphere respectively?', 'The 23 September Equinox brings Autumn to the Northern Hemisphere and Spring to the Southern Hemisphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61d1bb7e-3382-42ff-b534-19a93856bb78', 'Northern Hemisphere: Autumn (Fall); Southern Hemisphere: Spring', true, '75def6b5-534a-4adb-9e30-6ee775fc27e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f9b893f-44da-4186-8c2a-766cc1403580', 'Northern Hemisphere: Spring; Southern Hemisphere: Autumn', false, '75def6b5-534a-4adb-9e30-6ee775fc27e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a319e1f-9c72-4c78-9baf-4bfeca7f8aa4', 'Northern Hemisphere: Summer; Southern Hemisphere: Winter', false, '75def6b5-534a-4adb-9e30-6ee775fc27e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5de6370-e6bf-4861-9ffc-e69deef902f6', 'Both experience Winter', false, '75def6b5-534a-4adb-9e30-6ee775fc27e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed3aae0a-e980-491b-8f55-96d16832f2bb', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'On 21st March, what season is experienced in the Northern Hemisphere and Southern Hemisphere respectively?', 'The 21 March Equinox marks the beginning of Spring (Vernal Equinox) in the north and Autumn in the south.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a6877d7-0985-4340-a1c4-718ce7db3ce8', 'Northern Hemisphere: Spring (Vernal); Southern Hemisphere: Autumn', true, 'ed3aae0a-e980-491b-8f55-96d16832f2bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a991e1e-4cbe-4900-b8b6-c31f23452c6e', 'Northern Hemisphere: Autumn; Southern Hemisphere: Spring', false, 'ed3aae0a-e980-491b-8f55-96d16832f2bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('741635a4-472d-4356-b2a1-cb4a889f2bb9', 'Northern Hemisphere: Winter; Southern Hemisphere: Summer', false, 'ed3aae0a-e980-491b-8f55-96d16832f2bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f828527b-8aa4-4559-ae2c-4a665bd22bff', 'Both experience Summer', false, 'ed3aae0a-e980-491b-8f55-96d16832f2bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c1c1628-b2a3-452c-9fa4-ecdc9c2d5ba0', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What is the orbital plane of the Earth?', 'The orbital plane (ecliptic plane) is the geometric plane containing the Earth''s revolution path around the Sun.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c0ba6a5-a1c3-4062-8a17-5e7b5f48d98c', 'The plane formed by the Earth''s orbit around the Sun', true, '0c1c1628-b2a3-452c-9fa4-ecdc9c2d5ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('501dbec3-8a7e-46eb-ba68-1823fc821daf', 'The plane passing through the equator', false, '0c1c1628-b2a3-452c-9fa4-ecdc9c2d5ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e46b2aa-e6b1-4867-af4d-bd4bc028af88', 'The plane passing through the prime meridian', false, '0c1c1628-b2a3-452c-9fa4-ecdc9c2d5ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee39f9f5-d69b-4a4d-bbd8-31e8d1c3c30b', 'The surface of the ocean', false, '0c1c1628-b2a3-452c-9fa4-ecdc9c2d5ba0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7afdc3eb-701c-41dc-abda-03c953330fa5', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What angle does the Earth''s axis make with its orbital plane?', 'Earth''s rotational axis tilts 23½° from the perpendicular, making an angle of 90° - 23½° = 66½° with its orbital plane.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f742e4fc-5f32-45de-8f39-07e1a13c1e6d', '66½°', true, '7afdc3eb-701c-41dc-abda-03c953330fa5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10b91e6e-5c93-4f9b-9fd5-9d0a72fcb2a3', '23½°', false, '7afdc3eb-701c-41dc-abda-03c953330fa5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50229988-f8e6-4047-be5b-1f1b064e6d59', '90°', false, '7afdc3eb-701c-41dc-abda-03c953330fa5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c15d231-7d3e-4ab0-bce0-a26239326640', '45°', false, '7afdc3eb-701c-41dc-abda-03c953330fa5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b62c60bf-e35d-4798-bd55-4fb0027f2cd5', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Why do days become longer in summer and nights become shorter in winter in the Northern Hemisphere?', 'The northern tilt causes northern latitude parallels to spend more than 50% of their diurnal rotational arc inside the Circle of Illumination.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9e46fd5-4a9b-4520-af9f-0ae72e44a6be', 'The Northern Hemisphere is tilted towards the Sun in summer, so a larger portion of the northern latitude circles lies within the sunlit day hemisphere', true, 'b62c60bf-e35d-4798-bd55-4fb0027f2cd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d3645f9-fb9b-44a5-b840-4b506a0d53d4', 'The Earth rotates slower in summer and faster in winter', false, 'b62c60bf-e35d-4798-bd55-4fb0027f2cd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9a93181-888b-45d6-a791-286dfff1615d', 'The Sun grows bigger in summer', false, 'b62c60bf-e35d-4798-bd55-4fb0027f2cd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f11e87af-40cd-4cba-a17b-b586be07db1d', 'Clouds hide the night in summer', false, 'b62c60bf-e35d-4798-bd55-4fb0027f2cd5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3d5b232-772e-47f1-90a0-181ebb0ca25d', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Which term describes the point in the Earth''s elliptical orbit when it is CLOSEST to the Sun (about 147 million km around 3 January)?', 'Perihelion (from Greek peri = near, helios = sun) is the orbital periapsis where Earth is closest to the Sun.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fb33097-e861-49bd-8ee9-225d0147e8ad', 'Perihelion', true, 'a3d5b232-772e-47f1-90a0-181ebb0ca25d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3593b66-6d8d-4b45-a2cd-fa4002b39467', 'Aphelion', false, 'a3d5b232-772e-47f1-90a0-181ebb0ca25d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dc781ec-ffcf-45b9-a37e-ff5646b9dc85', 'Solstice', false, 'a3d5b232-772e-47f1-90a0-181ebb0ca25d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b642b8e-a339-4d54-8e8a-3b94a7e62618', 'Equinox', false, 'a3d5b232-772e-47f1-90a0-181ebb0ca25d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0be0c00-2f1d-4bd8-bf8e-73656e8eb2f5', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Which term describes the point in the Earth''s orbit when it is FARTHEST from the Sun (about 152 million km around 4 July)?', 'Aphelion (apo = away, helios = sun) is the orbital apoapsis where Earth reaches maximum solar distance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d4d24a4-3db8-464e-ab92-0e028085e8e5', 'Aphelion', true, 'c0be0c00-2f1d-4bd8-bf8e-73656e8eb2f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be99b166-dd4d-4b17-8d83-7f33856a0995', 'Perihelion', false, 'c0be0c00-2f1d-4bd8-bf8e-73656e8eb2f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2461c46-c7b9-435a-89d3-5943127eedb7', 'Equinox', false, 'c0be0c00-2f1d-4bd8-bf8e-73656e8eb2f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47fdba90-2b17-4da0-bf2e-94a024ec519c', 'Zenith', false, 'c0be0c00-2f1d-4bd8-bf8e-73656e8eb2f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d54e356-8e2d-439e-8254-23d74ae3e351', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What is the phenomenon called when the Sun is visible at local midnight during summer months in northern Norway, Sweden, and Finland?', 'At latitudes north of the Arctic Circle, the Sun remains above the horizon 24 hours a day during summer solstice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df48a5c9-18a7-4725-95e4-47f4d06305e3', 'The Midnight Sun', true, '4d54e356-8e2d-439e-8254-23d74ae3e351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('639eb07f-f665-4133-a6d9-893c01fe0b24', 'Solar Eclipse', false, '4d54e356-8e2d-439e-8254-23d74ae3e351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('005c4ada-e057-46dd-b1b6-481db55bb7f8', 'Aurora Borealis', false, '4d54e356-8e2d-439e-8254-23d74ae3e351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71047ac7-f21d-4b9b-86ac-d5c7920da41e', 'Polar Vortex', false, '4d54e356-8e2d-439e-8254-23d74ae3e351');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d15f6cca-0ec8-4097-b1b4-a4077c945e3b', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Why is an extra day added to the calendar every fourth year in February?', 'Without leap days, the 0.242-day annual discrepancy would cause calendar seasons to drift by ~24 days every century.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc7725c7-2972-44b9-b729-bc84b20706b1', 'To synchronize the civil calendar year (365 days) with the astronomical solar year (365.25 days) and prevent calendar seasonal drift', true, 'd15f6cca-0ec8-4097-b1b4-a4077c945e3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9e8c7b4-31ef-4b53-a6a9-5da15bc46d48', 'Because February was feeling too short', false, 'd15f6cca-0ec8-4097-b1b4-a4077c945e3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99215f96-e925-415f-a10f-4a4506e96ea5', 'To celebrate the King''s birthday', false, 'd15f6cca-0ec8-4097-b1b4-a4077c945e3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a143223a-6598-48b0-b774-b89f3c3c33c3', 'Because Earth takes a vacation every 4 years', false, 'd15f6cca-0ec8-4097-b1b4-a4077c945e3b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('428b7fe4-c0cc-4fba-9d0f-bb5c2291dc59', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What is the daily rotation of the Earth around its axis also termed in geography?', 'Diurnal motion refers to the daily 24-hour apparent rotation of celestial objects caused by Earth''s axial rotation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e216aad-3417-42a7-a11a-da7edb560ecb', 'Diurnal Motion', true, '428b7fe4-c0cc-4fba-9d0f-bb5c2291dc59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c14ca3b-88d3-4a6d-b288-4600f64e3378', 'Annual Motion', false, '428b7fe4-c0cc-4fba-9d0f-bb5c2291dc59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15b476ef-be2a-4c28-82f6-f3c3b7312f47', 'Secular Motion', false, '428b7fe4-c0cc-4fba-9d0f-bb5c2291dc59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('141e4e64-ec2f-4bd4-a278-7123d1a410ff', 'Orbital Motion', false, '428b7fe4-c0cc-4fba-9d0f-bb5c2291dc59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7964a656-6ae6-4acf-b191-de541d9d556b', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Why does the Equator experience virtually equal 12-hour days and 12-hour nights throughout the entire year?', 'The Equator is a Great Circle, and any plane passing through the Earth''s center (like the Circle of Illumination) bisects all Great Circles equally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ab46a00-25a2-40a0-b45b-ac98cae1e851', 'Because the Circle of Illumination always bisects the Equator into two exact equal halves in all orbital positions', true, '7964a656-6ae6-4acf-b191-de541d9d556b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98d9d954-184e-4c4b-939a-225f130d542c', 'Because the Sun never moves away from the Equator', false, '7964a656-6ae6-4acf-b191-de541d9d556b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c90d137-d80c-4b71-8ffd-40f0037a1aa1', 'Because Earth does not rotate at the Equator', false, '7964a656-6ae6-4acf-b191-de541d9d556b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23c7959e-5a1e-42a6-adda-21128d6397ad', 'Because the Equator is flat', false, '7964a656-6ae6-4acf-b191-de541d9d556b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e879541-77a5-4ad2-bc25-8a663aa5b864', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6894362-784b-4aae-a9b7-9f7a1651662a', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '7e879541-77a5-4ad2-bc25-8a663aa5b864');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d6dfd3d-7573-4a0f-b9f6-c17e31ad565f', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '7e879541-77a5-4ad2-bc25-8a663aa5b864');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('812e42dd-09bb-4390-b791-5524e826e548', '(A) is true, but (R) is false.', false, '7e879541-77a5-4ad2-bc25-8a663aa5b864');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d97dc932-dc9a-40d4-94da-f2a729f93f81', '(A) is false, but (R) is true.', false, '7e879541-77a5-4ad2-bc25-8a663aa5b864');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7a76f4b-d7c7-4695-b4cf-aaef535b2641', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Spot the IMPOSTER in the following list of astronomical dates and their northern seasonal designations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('768304ad-0f63-4223-aa0a-bfdde1e27cd2', '21 June - Summer Solstice', false, 'a7a76f4b-d7c7-4695-b4cf-aaef535b2641');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a3a67d9-ae5f-46f8-b5e5-0e89c6139fa3', '22 December - Winter Solstice', false, 'a7a76f4b-d7c7-4695-b4cf-aaef535b2641');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6896586f-e8a1-4ab5-81c7-9d6469c92e7a', '21 March - Vernal Equinox', false, 'a7a76f4b-d7c7-4695-b4cf-aaef535b2641');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e16f941f-d275-46bf-9036-b49f4b9d7c75', '23 September - Winter Solstice', true, 'a7a76f4b-d7c7-4695-b4cf-aaef535b2641');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32cd95f3-a5ec-44c0-b64d-cd6a73107704', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Consider a person standing at the South Pole on 21st June. What will they experience for the entire 24-hour period?', 'On 21 June, the South Pole tilts away from the Sun, remaining fully submerged in the dark night hemisphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('885ade9a-6608-464c-adac-1a369c6cf938', 'Continuous, complete 24-hour darkness (Polar Night), with the Sun never rising above the horizon', true, '32cd95f3-a5ec-44c0-b64d-cd6a73107704');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42099375-5b09-4f4a-9464-2d4905a098ae', 'Continuous 24-hour bright daylight', false, '32cd95f3-a5ec-44c0-b64d-cd6a73107704');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb6586c-ed4c-40fa-9bb3-5d617b25d595', 'Equal 12-hour day and 12-hour night', false, '32cd95f3-a5ec-44c0-b64d-cd6a73107704');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0115491-8767-4966-8a06-d95cff1d9087', 'A solar eclipse every 2 hours', false, '32cd95f3-a5ec-44c0-b64d-cd6a73107704');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ea4d699-d195-4460-b58b-e5f9cb8c20f7', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Match Column I (Dates) with Column II (Solar Positions & Events):
(a) 21st June       -> (i) Direct rays on Tropic of Capricorn
(b) 22nd December   -> (ii) Direct rays on Tropic of Cancer
(c) 21st March      -> (iii) Direct rays on Equator (Spring Equinox in North)
(d) 23rd September  -> (iv) Direct rays on Equator (Autumn Equinox in North)', '21 June = Sun on Cancer; 22 Dec = Sun on Capricorn; 21 March = Spring Equinox; 23 Sept = Autumn Equinox.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85ae9a45-c3f9-46e3-a29b-6b0d9145ef9e', 'a-(ii), b-(i), c-(iii), d-(iv)', true, '1ea4d699-d195-4460-b58b-e5f9cb8c20f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28d414ea-945f-4daf-b191-75e47c260a52', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '1ea4d699-d195-4460-b58b-e5f9cb8c20f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('142a3d12-698f-4b29-8785-ae48559f1bb8', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '1ea4d699-d195-4460-b58b-e5f9cb8c20f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62711913-df13-470d-8afe-a25505a1ca40', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '1ea4d699-d195-4460-b58b-e5f9cb8c20f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fdbef7db-35c5-4848-9580-1e5a59d7517a', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5479aa88-3947-4737-819e-116cba4e37ba', 'All Statements 1, 2, and 3', true, 'fdbef7db-35c5-4848-9580-1e5a59d7517a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9380e11-6257-46b2-af70-8700a35b397b', 'Statements 1 and 2 only', false, 'fdbef7db-35c5-4848-9580-1e5a59d7517a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4042cfb-9af5-441a-b93a-eef4ff7ac140', 'Statements 2 and 3 only', false, 'fdbef7db-35c5-4848-9580-1e5a59d7517a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0257b873-7ce0-47f7-826a-676cb5c2ed63', 'Statements 1 and 3 only', false, 'fdbef7db-35c5-4848-9580-1e5a59d7517a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f517760c-f4ac-4b45-910e-e5416403e5e4', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Why are solar days slightly longer than sidereal days (the true rotation period relative to distant stars being 23h 56m 4s)?', 'Orbital progression (~1° per day) requires Earth to spin an extra ~1° (360°/365 ≈ 4 minutes) for the Sun to return to the meridian.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd76bdc9-b2ec-4535-b81a-d326d0448595', 'Because while rotating, Earth also moves forward in its orbit around the Sun, requiring an extra ~4 minutes of rotation to align with the Sun again', true, 'f517760c-f4ac-4b45-910e-e5416403e5e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2559055e-f17d-48be-998d-dd43a93436a6', 'Because stars move backwards', false, 'f517760c-f4ac-4b45-910e-e5416403e5e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c4d709d-5ca5-47b2-80c5-743623437e56', 'Because the Sun rotates in the opposite direction', false, 'f517760c-f4ac-4b45-910e-e5416403e5e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9daadbda-b80c-400d-8e93-1127b24e01d5', 'Because gravity slows down at night', false, 'f517760c-f4ac-4b45-910e-e5416403e5e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fc79893-f891-4ec2-a5a3-3fea0122f12e', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'What is the mathematical condition for a century year (like 1900, 2000, 2100) to be designated a Leap Year in the Gregorian calendar?', 'Century years must be multiples of 400 to account for the precise fractional solar year (365.2422 days).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4fb8c95-ba1f-454a-bb3a-d9f3e386f78a', 'It must be divisible by 400 (e.g. 2000 was a leap year, but 1900 and 2100 are NOT leap years)', true, '0fc79893-f891-4ec2-a5a3-3fea0122f12e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db0518a0-d605-44e9-b261-634c24e018b3', 'It must be divisible by 4 only', false, '0fc79893-f891-4ec2-a5a3-3fea0122f12e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0939f8b4-3875-43b3-ac48-42f8b5b4deb3', 'It must be divisible by 100 only', false, '0fc79893-f891-4ec2-a5a3-3fea0122f12e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c3360ff-23eb-4ba1-bb8a-da7bcf99f513', 'All century years are leap years', false, '0fc79893-f891-4ec2-a5a3-3fea0122f12e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d39df76-a64d-4672-9b30-f7ceb13b7d86', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Why do direct solar rays at noon produce significantly more heating than slanting rays in the early morning and late evening?', 'Vertical rays minimize atmospheric optical path attenuation (air mass = 1) and maximize insolation flux per square meter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2442cfde-6fb5-428e-b565-4c746c496999', 'Direct vertical rays travel through a thinner slice of the atmosphere and concentrate high radiant energy on a small surface patch', true, '8d39df76-a64d-4672-9b30-f7ceb13b7d86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97de2250-5562-4a02-8782-144781d57245', 'The Sun is hotter at noon', false, '8d39df76-a64d-4672-9b30-f7ceb13b7d86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6340d62-738c-491f-a59d-fb2ef6f82ec3', 'Air disappears at noon', false, '8d39df76-a64d-4672-9b30-f7ceb13b7d86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c50606-4b21-4af8-858d-b0c05a297c66', 'Clouds only exist in the morning', false, '8d39df76-a64d-4672-9b30-f7ceb13b7d86');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d52cab7-7e81-49bb-9999-141347f6c776', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Why does the Southern Hemisphere experience peak winter when the Northern Hemisphere is experiencing peak summer?', 'Axial orientation creates inverse subsolar exposure between opposite hemispheres during Earth''s orbital journey.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f684515-31b0-404e-9ee3-8607542fe5c5', 'Due to Earth''s fixed axial tilt, when the Northern Hemisphere points towards the Sun, the Southern Hemisphere is tilted away from the Sun', true, '6d52cab7-7e81-49bb-9999-141347f6c776');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('984f8c56-c45a-4351-9fb8-e52ddf1ea0df', 'Because the Southern Hemisphere is made of water', false, '6d52cab7-7e81-49bb-9999-141347f6c776');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a957b989-df63-4b04-b077-5644ac685ceb', 'Because the Sun only shines on the north', false, '6d52cab7-7e81-49bb-9999-141347f6c776');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b5971c5-cfab-4b92-abde-fe5a82bc8fbc', 'Because Antarctica is too high', false, '6d52cab7-7e81-49bb-9999-141347f6c776');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('932181d4-5c28-4869-a8d2-f8a8706991e9', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Consider four points on Earth on 21st June:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5053f29-2962-43f0-ab6b-3af249870489', '1 -> 2 -> 3 -> 4 (North Pole: 24h -> Equator: 12h -> Tropic of Capricorn: ~10.5h -> South Pole: 0h)', true, '932181d4-5c28-4869-a8d2-f8a8706991e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b6eb558-bde6-492a-8bb0-da482cb2a1e7', '4 -> 3 -> 2 -> 1', false, '932181d4-5c28-4869-a8d2-f8a8706991e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed1747e2-5e47-4e06-8d32-c09866221645', '2 -> 1 -> 3 -> 4', false, '932181d4-5c28-4869-a8d2-f8a8706991e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bd1f012-886a-4be6-98f0-28b90b04876f', '1 -> 3 -> 2 -> 4', false, '932181d4-5c28-4869-a8d2-f8a8706991e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a8e10d8-f372-4b85-b24f-214c88655bf7', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'What is the velocity of Earth''s rotational spin at the Equator compared to that at the Poles?', 'Linear velocity v = ω·R·cos(θ); at θ = 0° (Equator), v ≈ 40,075 km / 24 h ≈ 1,670 km/h; at θ = 90° (Poles), v = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('667d74e6-daed-4de6-9398-6ba95a8acf72', 'Maximum at the Equator (~1,670 km/h) and zero at the Poles', true, '7a8e10d8-f372-4b85-b24f-214c88655bf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ffed695-b2e3-412c-8264-4c926479ed18', 'Zero at the Equator and maximum at the Poles', false, '7a8e10d8-f372-4b85-b24f-214c88655bf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b6bc9c9-ed2a-41ba-a053-2c2d9fd5482a', 'Equal at all latitudes', false, '7a8e10d8-f372-4b85-b24f-214c88655bf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03f24a43-1b7b-4339-929d-a1487da277ec', '100 km/h everywhere', false, '7a8e10d8-f372-4b85-b24f-214c88655bf7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fe30b28-b353-4c63-b6ea-de1dae78187c', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Which of the following would be an immediate consequence if the Earth revolved around the Sun at TWICE its current orbital speed while maintaining its current rotation rate?', 'Doubling orbital velocity halves the annual revolution period (365/2 ≈ 182.5 days), while diurnal spin remains unchanged at 24 hours.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d06b1754-d19e-4296-923e-34b934aad2b2', 'A year would last only ~182.5 days (seasons would change twice as fast), but each day would still last 24 hours', true, '9fe30b28-b353-4c63-b6ea-de1dae78187c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('397d33f8-43b6-4450-94a4-22edadda4626', 'A day would become 12 hours', false, '9fe30b28-b353-4c63-b6ea-de1dae78187c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b239d37-ee8c-4ba4-8e17-7f1c06cc43cb', 'Gravity would double', false, '9fe30b28-b353-4c63-b6ea-de1dae78187c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2392376a-a839-4038-8303-9595327919f7', 'The Moon would crash into Earth', false, '9fe30b28-b353-4c63-b6ea-de1dae78187c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b28733e-a509-400d-8b81-538e92b3de87', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'दो या दो से अधिक वर्णों के सार्थक (अर्थपूर्ण) मेल को क्या कहते हैं?', 'वर्णों का वह स्वतंत्र एवं सार्थक समूह जिसका कोई निश्चित अर्थ निकलता हो, ''शब्द'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfeb4c50-d5a4-46aa-a796-046fa2bc827a', 'शब्द (Word)', true, '8b28733e-a509-400d-8b81-538e92b3de87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3a0bf07-c23d-4ce6-9f54-c22e63eeb660', 'वर्णमाला', false, '8b28733e-a509-400d-8b81-538e92b3de87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18b4f5cb-e54f-42d5-a103-eaa94fa4cd89', 'वाक्य', false, '8b28733e-a509-400d-8b81-538e92b3de87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd279756-d5c4-48e5-bf21-6d7cdb103753', 'लिपि', false, '8b28733e-a509-400d-8b81-538e92b3de87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7962e596-7914-43b8-9650-49c0c10f1665', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'जब कोई सार्थक शब्द किसी वाक्य में व्याकरण के नियमों के अनुसार प्रयुक्त होता है, तो उसे क्या कहते हैं?', 'वाक्य में प्रयुक्त होकर व्याकरणिक संबंध (कारक, वचन, लिंग) ग्रहण करने पर शब्द ''पद'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5ba9917-b110-47b6-b84d-0ae7716b9897', 'पद (Word in a sentence / Form)', true, '7962e596-7914-43b8-9650-49c0c10f1665');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('599fd13f-ca56-4932-80bc-73c8971bd773', 'ध्वनि', false, '7962e596-7914-43b8-9650-49c0c10f1665');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5d8eade-8217-49e1-9500-df1fe3f5c0c2', 'वर्ण', false, '7962e596-7914-43b8-9650-49c0c10f1665');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1273bc70-9b8c-46f8-80ce-fcb21360a79f', 'उपसर्ग', false, '7962e596-7914-43b8-9650-49c0c10f1665');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98933e8a-e23d-4205-a968-ae1dce25df40', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'अर्थ के आधार पर शब्दों को मुख्य रूप से कितने भागों में बाँटा जाता है?', 'अर्थ के आधार पर दो भेद होते हैं: 1. सार्थक शब्द (जिनका निश्चित अर्थ हो) तथा 2. निरर्थक शब्द (जिनका कोई अर्थ न हो, जैसे ''वाय-शाय'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('878918b3-45e5-4031-b5e4-6516035e746d', 'दो भागों में (सार्थक शब्द और निरर्थक शब्द)', true, '98933e8a-e23d-4205-a968-ae1dce25df40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c06c2d11-27d7-446d-8f24-d09ba77c6f14', 'चार भागों में', false, '98933e8a-e23d-4205-a968-ae1dce25df40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5802cd88-250c-4706-9896-b8e2d8cf7690', 'तीन भागों में', false, '98933e8a-e23d-4205-a968-ae1dce25df40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efd7ca7e-9b1d-41f4-b551-71ee17296e6a', 'पाँच भागों में', false, '98933e8a-e23d-4205-a968-ae1dce25df40');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d1478fe-91e1-4c3a-adfd-52c77f552959', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'उत्पत्ति या स्रोत (Origin) के आधार पर शब्दों के कितने भेद होते हैं?', 'उत्पत्ति के आधार पर चार मुख्य वर्ग हैं: तत्सम (संस्कृत मूल), तद्भव (परिवर्तित), देशज (स्थानीय), तथा विदेशी (आगत)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f104b489-ae3e-40ed-90dc-e469e112253a', 'चार मुख्य भेद (तत्सम, तद्भव, देशज, विदेशी)', true, '6d1478fe-91e1-4c3a-adfd-52c77f552959');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fced84df-5f28-4e07-968e-167da2baf6c0', 'दो भेद', false, '6d1478fe-91e1-4c3a-adfd-52c77f552959');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46784d45-c291-4e9b-a4cc-0d4dbfa77ea3', 'छह भेद', false, '6d1478fe-91e1-4c3a-adfd-52c77f552959');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17f4d483-34c8-4793-beb2-181faf4eef7f', 'तीन भेद', false, '6d1478fe-91e1-4c3a-adfd-52c77f552959');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a65e939-de1c-458c-b3d1-d9f76c214e4a', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'संस्कृत भाषा के वे शब्द जो बिना किसी परिवर्तन के अपने मूल रूप में हिंदी में प्रयुक्त होते हैं, उन्हें क्या कहते हैं?', '''तत्'' (उसके/संस्कृत) + ''सम'' (समान) = जो शब्द संस्कृत से ज्यों-के-त्यों हिंदी में आए हैं, तत्सम कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff9cf26f-b845-4b5a-9459-5379a87bb53f', 'तत्सम शब्द (Tatsam - जैसे: अग्नि, सूर्य, दुग्ध, रात्रि)', true, '9a65e939-de1c-458c-b3d1-d9f76c214e4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27915272-d078-41f0-bf28-f70617ca3979', 'तद्भव शब्द', false, '9a65e939-de1c-458c-b3d1-d9f76c214e4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd2a6966-aab0-4dc6-8219-b6c5c2ce43e0', 'देशज शब्द', false, '9a65e939-de1c-458c-b3d1-d9f76c214e4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5c99962-24c6-4b90-903d-b130029ccd52', 'विदेशी शब्द', false, '9a65e939-de1c-458c-b3d1-d9f76c214e4a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('855efaf6-0259-4c72-b3c6-a07dd945f3f2', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'संस्कृत के वे शब्द जो समय के साथ रूप बदलकर (सरल होकर) हिंदी में प्रयुक्त होते हैं, उन्हें क्या कहते हैं?', '''तत्'' + ''भव'' (उससे उत्पन्न/विकसित) = संस्कृत से प्राकृत/अपभ्रंश होते हुए हिंदी में रूप बदलने वाले शब्द तद्भव कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5a379e2-352d-41c2-9f29-98be431f53a1', 'तद्भव शब्द (Tadbhav - जैसे: आग, सूरज, दूध, रात)', true, '855efaf6-0259-4c72-b3c6-a07dd945f3f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d34d39a-000d-408c-8a28-4fdbbd0685c8', 'तत्सम शब्द', false, '855efaf6-0259-4c72-b3c6-a07dd945f3f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d36340bd-ad5a-46f1-9631-4c31ce2d5351', 'रूढ़ शब्द', false, '855efaf6-0259-4c72-b3c6-a07dd945f3f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61f19833-06ec-4e2d-87d3-527c9a81f639', 'योगरूढ़ शब्द', false, '855efaf6-0259-4c72-b3c6-a07dd945f3f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7bce359c-306c-44ae-bc25-0a1fd3887e42', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'वे शब्द जो स्थानीय बोलियों या क्षेत्रीय प्रभाव से आवश्यकतानुसार हिंदी में आ गए हैं, उन्हें क्या कहते हैं?', 'देश में ही क्षेत्रीय बोलियों और लोक-व्यवहार से निर्मित शब्द ''देशज'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('393f76d1-569c-405b-b394-0f8940c61449', 'देशज शब्द (Deshaj - जैसे: लोटा, पगड़ी, खिड़की, डिबिया)', true, '7bce359c-306c-44ae-bc25-0a1fd3887e42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a34cdda3-9a7f-4cbb-960d-da44696ac17d', 'तत्सम शब्द', false, '7bce359c-306c-44ae-bc25-0a1fd3887e42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25f4b941-f8f5-413d-9392-cc87829cd3ae', 'विदेशी शब्द', false, '7bce359c-306c-44ae-bc25-0a1fd3887e42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c564e9d-91af-4809-881d-57613cab5c61', 'यौगिक शब्द', false, '7bce359c-306c-44ae-bc25-0a1fd3887e42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d4dab00-ae1d-4ba1-9b3c-6b79ec6891e2', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'विदेशी भाषाओं (अंग्रेज़ी, अरबी, फारसी, पुर्तगाली आदि) से हिंदी में आए शब्दों को क्या कहते हैं?', 'विदेशी संपर्कों और शासनकालों के कारण हिंदी में गृहीत शब्द ''विदेशी/आगत शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcdbd540-7dde-4b8d-a83a-2a4f4b87c0f1', 'विदेशी या आगत शब्द (जैसे: स्कूल, डॉक्टर, किताब, तोप, चाय)', true, '8d4dab00-ae1d-4ba1-9b3c-6b79ec6891e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('980c73b9-e567-4ab5-af42-24a001bd81f6', 'तत्सम शब्द', false, '8d4dab00-ae1d-4ba1-9b3c-6b79ec6891e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74d791f6-9b39-4a3f-8d69-65127bff28af', 'तद्भव शब्द', false, '8d4dab00-ae1d-4ba1-9b3c-6b79ec6891e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aea250bd-0a81-4799-bffb-0f43c077dbd3', 'रूढ़ शब्द', false, '8d4dab00-ae1d-4ba1-9b3c-6b79ec6891e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cca38cdf-7308-4803-b7c5-446f7d21a7c5', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'रचना या बनावट (Structure) के आधार पर शब्दों के कितने भेद होते हैं?', 'बनावट के आधार पर तीन भेद हैं: 1. रूढ़ (अविभाज्य मूल), 2. यौगिक (मेल से बने), 3. योगरूढ़ (विशेष अर्थ देने वाले)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a494b44d-dd78-40ab-addf-a853b7c528c2', 'तीन भेद (रूढ़ शब्द, यौगिक शब्द, योगरूढ़ शब्द)', true, 'cca38cdf-7308-4803-b7c5-446f7d21a7c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53aeeb51-fe6d-4cae-bc7d-ae83bc5dcfbf', 'दो भेद', false, 'cca38cdf-7308-4803-b7c5-446f7d21a7c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de951514-a128-492c-9a63-87f2cc6f9de6', 'चार भेद', false, 'cca38cdf-7308-4803-b7c5-446f7d21a7c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7b3a83e-73ff-4044-9aac-55846b173862', 'पाँच भेद', false, 'cca38cdf-7308-4803-b7c5-446f7d21a7c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c25eba66-42ab-4b44-a867-e12e61075858', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'वे शब्द जिनके सार्थक खंड (टुकड़े) नहीं किए जा सकते और जो किसी विशेष अर्थ के लिए परंपरा से प्रसिद्ध हैं, उन्हें क्या कहते हैं?', 'रूढ़ शब्दों के टुकड़े करने पर कोई स्वतंत्र अर्थ नहीं निकलता (जैसे ''घ + र'' का कोई अर्थ नहीं)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29b3424f-81aa-4b9b-b6e2-25cbd4403247', 'रूढ़ शब्द (जैसे: घर, जल, पुस्तक, पेड़)', true, 'c25eba66-42ab-4b44-a867-e12e61075858');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8524c30-ae71-4240-9df4-14ab92695a1c', 'यौगिक शब्द', false, 'c25eba66-42ab-4b44-a867-e12e61075858');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23e8a9f0-3457-4916-97ba-d79bdfd069ae', 'योगरूढ़ शब्द', false, 'c25eba66-42ab-4b44-a867-e12e61075858');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4122669-8e6a-4ad8-af83-a0a61e404a6c', 'तद्भव शब्द', false, 'c25eba66-42ab-4b44-a867-e12e61075858');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38e1b6ae-a94c-4a18-99dc-ba17b894b106', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'दो या दो से अधिक सार्थक शब्दों या शब्दांशों के मेल से बनने वाले शब्दों को क्या कहते हैं?', 'यौगिक शब्दों के प्रत्येक खंड का अपना स्वतंत्र सार्थक अर्थ होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0780d42c-efec-45f7-b858-a2df666cd1b9', 'यौगिक शब्द (जैसे: पाठ + शाला = पाठशाला, विद्या + आलय = विद्यालय)', true, '38e1b6ae-a94c-4a18-99dc-ba17b894b106');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f61860a-a52f-4d22-aa85-cb3cde502883', 'रूढ़ शब्द', false, '38e1b6ae-a94c-4a18-99dc-ba17b894b106');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62171afe-f843-428e-9353-da1e6a04434d', 'योगरूढ़ शब्द', false, '38e1b6ae-a94c-4a18-99dc-ba17b894b106');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afff3dfb-0bed-455d-a266-f704ae7f3673', 'निरर्थक शब्द', false, '38e1b6ae-a94c-4a18-99dc-ba17b894b106');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3102f3c9-2f48-4ff0-99ee-c6f06e920048', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'वे शब्द जो दो या दो से अधिक शब्दों के मेल से बनते हैं, परन्तु किसी विशेष/रूढ़ अर्थ को प्रकट करते हैं, उन्हें क्या कहते हैं?', 'योगरूढ़ शब्द यौगिक होते हुए भी सामान्य अर्थ को छोड़कर किसी तीसरे विशिष्ट अर्थ के लिए रूढ़ हो जाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c55db259-8a44-4e62-8a31-052dbd273fae', 'योगरूढ़ शब्द (जैसे: जलज = कमल, लंबोदर = गणेश, दशानन = रावण)', true, '3102f3c9-2f48-4ff0-99ee-c6f06e920048');
