INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3b6148c-a9f1-417a-aedd-0737c621f6b6', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'प्रयोग या विकार (Grammatical Variation) के आधार पर शब्दों के दो प्रमुख भेद कौन-से हैं?', 'विकार के आधार पर: विकारी (संज्ञा, सर्वनाम, विशेषण, क्रिया) तथा अविकारी (क्रियाविशेषण, संबंधबोधक, समुच्चयबोधक, विस्मयादिबोधक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a25401ff-ca4d-47ea-8c01-c5f98d295116', 'विकारी शब्द (जिनमें परिवर्तन होता है) और अविकारी शब्द (जिनमें कभी परिवर्तन नहीं होता)', true, 'f3b6148c-a9f1-417a-aedd-0737c621f6b6');
