INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b41e4347-42a6-4729-b77f-7f784924796b', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'विकारी शब्द कौन-से चार होते हैं जिनमें लिंग, वचन और कारक के अनुसार रूप बदल जाता है?', 'संज्ञा (लड़का/लड़के), सर्वनाम (वह/वे), विशेषण (अच्छा/अच्छी), तथा क्रिया (जाता/जाती) में विकार (बदलाव) आता है।', NOW()) ON CONFLICT DO NOTHING;
