INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62472c9d-fa00-4bd0-9c82-6559f386c748', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'अविकारी शब्द (अव्यय) कौन-से होते हैं जिनका रूप किसी भी परिस्थिति में कभी नहीं बदलता?', 'अव्यय/अविकारी शब्दों में लिंग, वचन, कारक या काल के कारण कोई विकार या रूपांतरण नहीं होता।', NOW()) ON CONFLICT DO NOTHING;
