INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4d04ddb-2293-4661-9566-6c764c602ca4', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'शब्द ''जलज'' (जल + ज = जल में जन्म लेने वाला) का रूढ़ विशेष अर्थ क्या है, जिसके कारण यह ''योगरूढ़'' कहलाता है?', 'यद्यपि जल में अनेक जीव जन्म लेते हैं, परन्तु ''जलज'' शब्द केवल ''कमल'' के विशिष्ट अर्थ में योगरूढ़ है।', NOW()) ON CONFLICT DO NOTHING;
