INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cdb946b2-5721-4a37-a0f1-5dea76af934c', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'शब्द ''दशानन'' (दश + आनन = दस मुख वाला) किस विशिष्ट ऐतिहासिक पौराणिक पात्र के लिए योगरूढ़ है?', '''दशानन'' का रूढ़ विशेष अर्थ लंकापति ''रावण'' है।', NOW()) ON CONFLICT DO NOTHING;
