INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('afbf4867-1a1a-4b5d-ba97-394ea0581352', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'एक-दूसरे का विपरीत (उल्टा) अर्थ बताने वाले शब्दों को क्या कहते हैं?', 'परस्पर विरोधी अर्थ व्यक्त करने वाले शब्द युग्म विलोम/विपरीतार्थक शब्द कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
