INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06249ff1-9425-422c-987c-58e5936e5f9c', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'वे शब्द जो सुनने में समान लगते हैं परन्तु उनके अर्थ भिन्न होते हैं (जैसे: ''अनल'' = आग, ''अनिल'' = हवा), उन्हें क्या कहते हैं?', 'ध्वन्यात्मक साम्य रखने वाले परन्तु वर्तनी एवं अर्थ में भिन्न शब्द श्रुतिसमभिन्नार्थक कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
