INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86b2404e-f8e4-49f4-a7f1-93bce0434f02', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'एक से अधिक अर्थ प्रकट करने वाले शब्दों को क्या कहते हैं (जैसे: ''कर'' = हाथ, टैक्स, किरण)?', 'प्रसंग भेद के अनुसार अनेक अर्थ देने वाले स्वतंत्र शब्द अनेकार्थी कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
