INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9bc1607-365a-467b-864c-d880934de943', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''यौगिक शब्द'' का सही उदाहरण है?', '''राष्ट्रपति'' दो सार्थक शब्दों (राष्ट्र + पति) के योग से बना यौगिक शब्द है।', NOW()) ON CONFLICT DO NOTHING;
