INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30f998d7-77c1-4667-b507-d0d0df625f43', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '71500bec-9507-49ce-b402-5613483ca37a');
