INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70bdcf18-71d7-44ae-b310-da3a2b9e69ea', '(A) सही है, परन्तु (R) गलत है।', false, '71500bec-9507-49ce-b402-5613483ca37a');
