INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('799b46f6-a6c3-4b91-81ff-8b1e1c0c5b59', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'सुमेलित कीजिए (तत्सम और तद्भव युग्म):
(क) मयूर  -> (i) घी
(ख) ग्राम  -> (ii) मोर
(ग) घृत   -> (iii) खेत
(घ) क्षेत्र -> (iv) गाँव', 'मयूर = मोर; ग्राम = गाँव; घृत = घी; क्षेत्र = खेत।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b7cfae8-bbc8-424d-b0cd-0859a7b62b49', 'क-(ii), ख-(iv), ग-(i), घ-(iii)', true, '799b46f6-a6c3-4b91-81ff-8b1e1c0c5b59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('455ec8b7-4373-44d5-b65e-d6401e55a9fb', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '799b46f6-a6c3-4b91-81ff-8b1e1c0c5b59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55d622dc-99c5-4a75-abc6-4e160bfcfa22', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '799b46f6-a6c3-4b91-81ff-8b1e1c0c5b59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc0443bf-5bad-498c-b9bc-8f278aa0b767', 'क-(iii), ख-(i), ग-(iv), घ-(ii)', false, '799b46f6-a6c3-4b91-81ff-8b1e1c0c5b59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94c2f404-9399-4e21-8472-81f150c7be25', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'दो भिन्न भाषाओं के शब्दों के मेल से बने नवीन शब्द को हिंदी में क्या कहा जाता है (जैसे: रेल + गाड़ी = रेलगाड़ी, वर्ष + गाँठ = वर्षगाँठ)?', 'दो भिन्न भाषाई स्रोतों (जैसे अंग्रेज़ी + हिंदी) से निर्मित मिश्रित शब्द ''संकर शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c443e979-01e9-4acd-a020-72a700aeef70', 'संकर शब्द (Hybrid Words)', true, '94c2f404-9399-4e21-8472-81f150c7be25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8e50a86-1513-4d4c-9ca6-1bffea191850', 'तत्सम शब्द', false, '94c2f404-9399-4e21-8472-81f150c7be25');
