INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b28a345-0c61-4659-a97c-dc8290522827', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'निम्नलिखित कथनों पर विचार कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e0182f8-c3e6-41bf-b1df-728f43860a48', 'सभी कथन 1, 2 और 3 सत्य हैं', true, '0b28a345-0c61-4659-a97c-dc8290522827');
