INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84e20bce-a50d-4524-871e-e8ff81c46061', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'शब्द ''नीलकंठ'' (नील + कंठ) रचना की दृष्टि से किस वर्ग का शब्द है और क्यों?', '''नीलकंठ'' यौगिक संरचना होते हुए भी देवाधिदेव शिव के विशिष्ट तीसरे अर्थ में रूढ़ है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('935408cc-7157-4f48-a560-f6f056117dfe', 'योगरूढ़ शब्द; क्योंकि यह नीले कंठ वाले सामान्य पक्षी के बजाय भगवान शिव के विशिष्ट अर्थ में रूढ़ हो गया है', true, '84e20bce-a50d-4524-871e-e8ff81c46061');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90c9eb64-bf69-4b9c-ad8b-f5b1e98d3077', 'रूढ़ शब्द; क्योंकि इसके खंड नहीं हो सकते', false, '84e20bce-a50d-4524-871e-e8ff81c46061');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b97e96f2-7409-4a2f-be96-37bbd4b41c07', 'विदेशी शब्द', false, '84e20bce-a50d-4524-871e-e8ff81c46061');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b3cd349-7a7d-476b-87c0-b5f7e606788e', 'निरर्थक शब्द', false, '84e20bce-a50d-4524-871e-e8ff81c46061');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9628098a-0746-474b-84b4-62738dc6720f', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'श्रुतिसमभिन्नार्थक शब्द युग्म ''दिन'' और ''दीन'' के क्रमशः सही अर्थ क्या हैं?', 'ह्रस्व ''इ'' वाला ''दिन'' = दिवस/वार, तथा दीर्घ ''ई'' वाला ''दीन'' = दरिद्र/गरीब।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea91cb7a-fa87-43a9-87b4-7b2f9c19400a', 'दिन = दिवस (Day) ; दीन = गरीब / असहाय (Poor)', true, '9628098a-0746-474b-84b4-62738dc6720f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f1d85c6-0461-43d6-b39e-4bb228c162df', 'दिन = रात ; दीन = अमीर', false, '9628098a-0746-474b-84b4-62738dc6720f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddfc152c-78df-4edc-846d-3647ace2664e', 'दिन = सूरज ; दीन = चाँद', false, '9628098a-0746-474b-84b4-62738dc6720f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('598c806e-030d-4002-bfcb-e42811574996', 'दोनों का अर्थ समान है', false, '9628098a-0746-474b-84b4-62738dc6720f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ae36714-fdb4-4456-8940-62ab77dc8797', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'श्रुतिसमभिन्नार्थक शब्द युग्म ''गृह'' और ''ग्रह'' के क्रमशः सही अर्थ क्या हैं?', '''गृह'' (ऋ की मात्रा) = घर/आवास, तथा ''ग्रह'' (र पदेन) = सूर्य की परिक्रमा करने वाला खगोलीय पिंड।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12f8a6f4-cb7a-4325-8e86-c27665d29b59', 'गृह = घर (Mansion/House) ; ग्रह = आकाशीय पिंड (Planet)', true, '0ae36714-fdb4-4456-8940-62ab77dc8797');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57631465-8037-4bc0-91cd-2692453f4f16', 'गृह = नक्षत्र ; ग्रह = कमरा', false, '0ae36714-fdb4-4456-8940-62ab77dc8797');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('671a5fc9-a5e8-4158-99d8-7d3682e44c31', 'गृह = सूर्य ; ग्रह = मंदिर', false, '0ae36714-fdb4-4456-8940-62ab77dc8797');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5d9bb83-38e5-4a08-8728-40ac52b3fc38', 'दोनों का अर्थ घर है', false, '0ae36714-fdb4-4456-8940-62ab77dc8797');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a5f772d-8d7f-44b3-8186-a48303b1be52', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'अनेकार्थी शब्द ''अंबर'' के दो विभिन्न संदर्भगत अर्थ कौन-से हैं?', '''अंबर'' का एक अर्थ विस्तृत नभ/आकाश है (जैसे ''नीलांबर'') तथा दूसरा अर्थ परिधान/वस्त्र है (जैसे ''पीतांबर'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6dbf6a1-f908-4af8-8990-4a62f30d01d8', 'आकाश (Sky) और वस्त्र / कपड़ा (Cloth)', true, '3a5f772d-8d7f-44b3-8186-a48303b1be52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9412c053-4cce-48e7-bfa1-9504fc3282d8', 'पानी और हवा', false, '3a5f772d-8d7f-44b3-8186-a48303b1be52');
