INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1dec3e8-d873-4b00-88a0-1ba4a6deac3a', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'वाक्यांश के लिए एक शब्द: ''जो सब कुछ जानता हो'' तथा ''जिसका कोई शत्रु न जन्मा हो'' के लिए क्रमशः सही शब्द क्या हैं?', 'सब कुछ जानने वाला = सर्वज्ञ; जिसका कोई शत्रु न उत्पन्न हुआ हो = अजातशत्रु।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24e99d65-9d35-4432-952a-e04e107cd917', 'सर्वज्ञ (Omniscient) तथा अजातशत्रु (Ajatashatru)', true, 'd1dec3e8-d873-4b00-88a0-1ba4a6deac3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49d9aa49-551d-4d97-89c3-a508209ea9fc', 'अल्पज्ञ तथा विद्वान', false, 'd1dec3e8-d873-4b00-88a0-1ba4a6deac3a');
