INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a9aa7aa-1206-43e4-ba55-f774704e710c', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'फारसी भाषा से हिंदी में आए आगत शब्दों का सही समूह कौन-सा है?', 'कागज़, ज़मीन, बाज़ार, गुलाब, चश्मा फारसी मूल के मानक आगत शब्द हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('272fae40-a0f5-4fe4-bb9b-02114a3937af', 'कागज़, ज़मीन, बाज़ार, गुलाब, चश्मा', true, '4a9aa7aa-1206-43e4-ba55-f774704e710c');
