INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4f89937-c2c6-45a3-83af-240c1218cbac', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'अरबी भाषा से हिंदी में समाहित हुए शब्दों का सही समूह कौन-सा है?', 'अमीर, गरीब, कानून, फैसला, अदालत न्याय-प्रशासनिक अरबी मूल के आगत शब्द हैं।', NOW()) ON CONFLICT DO NOTHING;
