INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1ef3c49-935f-426d-a58e-3b388bf9906a', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Easy', 'Small plants with green, tender, and soft stems that usually do not have many branches are called:', 'Herbs are short, non-woody plants with tender green stems (e.g. mint, coriander, tomato).', NOW()) ON CONFLICT DO NOTHING;
