INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85a1474a-11b5-4259-bbf0-91158b54725b', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Easy', 'The broad, green, flat expanded part of a leaf is called the:', 'The lamina (blade) is the flattened photosynthetic surface containing vascular venation networks.', NOW()) ON CONFLICT DO NOTHING;
