INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ed324de-6343-44e9-8863-c9f0392471d9', 'Respiration', false, 'bf89f8f9-ff6d-43c1-8d77-90dbe122e500');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ec436e7-e77d-4436-a9b4-12e86f20f250', 'Germination', false, 'bf89f8f9-ff6d-43c1-8d77-90dbe122e500');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e930f27-9c5c-4d55-aaf0-3a987501704e', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Easy', 'The biochemical process by which green leaves synthesize glucose food in the presence of sunlight, chlorophyll, CO₂, and water is called:', 'Photosynthesis converts solar energy into chemical energy: 6CO₂ + 6H₂O -> C₆H₁₂O₆ + 6O₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa2a8d0c-f792-4dbc-b24a-dacd877ba221', 'Photosynthesis', true, '7e930f27-9c5c-4d55-aaf0-3a987501704e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a444123-3f99-4e35-ab49-e95c97acda92', 'Transpiration', false, '7e930f27-9c5c-4d55-aaf0-3a987501704e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de715770-2644-4cea-af61-c5d0829b5f2a', 'Respiration', false, '7e930f27-9c5c-4d55-aaf0-3a987501704e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44485d61-69b0-40a9-ae3d-eda50892e962', 'Fermentation', false, '7e930f27-9c5c-4d55-aaf0-3a987501704e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a619f6b7-4cab-4ffb-aa19-ab744d2ee69a', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Easy', 'What primary gas is released into the atmosphere by green leaves during daytime photosynthesis?', 'Photolysis of water molecules during light-dependent reactions yields diatomic oxygen (O₂) byproduct.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d9890ce-fe5c-4a9f-8ff5-98ac24d438ff', 'Oxygen gas (O₂)', true, 'a619f6b7-4cab-4ffb-aa19-ab744d2ee69a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f40a9ae-dfcf-4127-bf4c-f6147ab5dae9', 'Carbon dioxide gas', false, 'a619f6b7-4cab-4ffb-aa19-ab744d2ee69a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adfd1f8a-b75c-428c-a17b-6f8a19b777e0', 'Nitrogen gas', false, 'a619f6b7-4cab-4ffb-aa19-ab744d2ee69a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f5956ec-0d1a-491d-b3d5-a24d0df05ce0', 'Methane gas', false, 'a619f6b7-4cab-4ffb-aa19-ab744d2ee69a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29f345fd-8005-4128-ace8-3e9b961b7286', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What is the key difference between Reticulate Venation and Parallel Venation?', 'Dicot leaves exhibit branching anastomosing net patterns (reticulate), while monocots feature longitudinal parallel venation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79fb9de0-7cf6-43ec-b6da-76bacfaa0a30', 'Reticulate venation forms a net-like web of veins (e.g. Peepal, Mango), while Parallel venation runs in parallel lines (e.g. Grass, Wheat, Banana)', true, '29f345fd-8005-4128-ace8-3e9b961b7286');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f56d603a-bd28-4349-8490-aaaef1dd9a47', 'Parallel venation only occurs in trees', false, '29f345fd-8005-4128-ace8-3e9b961b7286');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22556e1b-8cbd-4148-96ac-a6f5bb358538', 'Reticulate venation has no midrib', false, '29f345fd-8005-4128-ace8-3e9b961b7286');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37ba7714-b250-4583-a54f-76ce521f085e', 'They are identical', false, '29f345fd-8005-4128-ace8-3e9b961b7286');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('233be0cc-f8e4-405c-9106-d425eb5b7673', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What correlation exists between a plant''s root system and its leaf venation type?', 'Dicotyledons typically pair reticulate leaf venation with taproots; monocotyledons pair parallel venation with fibrous root clusters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc1bd986-da6e-4090-b12f-8290ec1053a3', 'Plants with Reticulate venation have Taproots, while plants with Parallel venation have Fibrous roots', true, '233be0cc-f8e4-405c-9106-d425eb5b7673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb05f71d-14cd-4984-8d4b-ccfe2802b1ed', 'Plants with Reticulate venation have Fibrous roots', false, '233be0cc-f8e4-405c-9106-d425eb5b7673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3880c64a-46fe-4304-9e94-23690471b05d', 'Leaf venation has zero relation to root type', false, '233be0cc-f8e4-405c-9106-d425eb5b7673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b278f75-b420-4e01-a3cb-a44b33e3b706', 'All trees have fibrous roots', false, '233be0cc-f8e4-405c-9106-d425eb5b7673');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ba84725-02ea-46ac-b69d-536fceaa66a5', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the two primary physiological functions performed by plant ROOTS?', 'Roots provide mechanical soil anchorage and extract aqueous minerals across root hair membranes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5db5cd84-838c-4868-b21e-ef8162bbf4f6', 'Anchoring the plant firmly in the soil and absorbing water and dissolved mineral nutrients', true, '8ba84725-02ea-46ac-b69d-536fceaa66a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b34f6e8e-3055-483e-8d99-7b1bc6bdbca2', 'Producing flowers and seeds', false, '8ba84725-02ea-46ac-b69d-536fceaa66a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19e12348-cc33-4db5-b1ad-c57310041204', 'Synthesizing oxygen from sunlight', false, '8ba84725-02ea-46ac-b69d-536fceaa66a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2102ba1d-c266-4512-8d2b-28d77af8dbc4', 'Breathing air for animals', false, '8ba84725-02ea-46ac-b69d-536fceaa66a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('052c812a-1d24-4834-830c-fd4f337b9c2b', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the two primary physiological functions performed by the plant STEM?', 'Stems house xylem vascular conduits (upward sap transport) and phloem conduits (bidirectional photosynthate translocation).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c188337-4276-4de9-ab0c-100d92b8895d', 'Conducting water and minerals from roots upward to leaves, and transporting synthesized food from leaves to all plant parts', true, '052c812a-1d24-4834-830c-fd4f337b9c2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6b60763-304c-4645-a9d5-c0bc39f577f7', 'Producing pollen grains', false, '052c812a-1d24-4834-830c-fd4f337b9c2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67688bf0-c0fe-40d2-8776-1bba21e66fc8', 'Absorbing sunlight directly through bark', false, '052c812a-1d24-4834-830c-fd4f337b9c2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b2dbc01-5f50-4ed9-a1c8-9045450d5e44', 'Storing stones', false, '052c812a-1d24-4834-830c-fd4f337b9c2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73d61b51-de78-4127-897b-4e3d0bb334d5', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the four concentric whorls of a complete typical flower from outside to inside?', 'Floral organs arise in four sequential whorls: outer protective sepals, showy petals, male stamens, and central female pistil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28b8c743-41b5-46f1-a47f-624d60abf6c9', 'Sepals (Calyx) -> Petals (Corolla) -> Stamens (Androecium) -> Pistil/Carpel (Gynoecium)', true, '73d61b51-de78-4127-897b-4e3d0bb334d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fceb440-e845-4312-b1e1-7a84661c428e', 'Petals -> Sepals -> Pistil -> Stamens', false, '73d61b51-de78-4127-897b-4e3d0bb334d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24a700df-e222-4967-a362-0e52b45048d0', 'Pistil -> Stamens -> Petals -> Sepals', false, '73d61b51-de78-4127-897b-4e3d0bb334d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a001d213-566e-41ac-8712-76443611ce09', 'Root -> Stem -> Leaf -> Flower', false, '73d61b51-de78-4127-897b-4e3d0bb334d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56393265-59d9-4a0a-aa14-5ffb0941a47d', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the two main parts that make up a male reproductive organ (Stamen) of a flower?', 'The stamen consists of the microsporangiate anther supported by a slender filament.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ada5b264-7d8a-4db8-abee-9c32971cfef0', 'Anther (produces pollen grains) and Filament (stalk)', true, '56393265-59d9-4a0a-aa14-5ffb0941a47d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4e2847f-0714-4a56-b46c-57ffb291069a', 'Stigma and Style', false, '56393265-59d9-4a0a-aa14-5ffb0941a47d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33458731-2b00-4d48-a7bd-3b4cf2c05d3c', 'Ovary and Ovule', false, '56393265-59d9-4a0a-aa14-5ffb0941a47d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edab7348-3658-49e5-bff5-b27c565fbb73', 'Sepal and Petal', false, '56393265-59d9-4a0a-aa14-5ffb0941a47d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9b37ff7-10f9-4ed4-962e-cd015b92ebd0', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the three main morphological parts of the female reproductive organ (Pistil / Carpel)?', 'The pistil comprises the sticky receptive stigma, elongate neck style, and basal ovule-bearing ovary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2357fd6-f080-4aa9-b5c0-e7c61649aee1', 'Stigma (receptive top), Style (middle tube), and Ovary (swollen base)', true, 'b9b37ff7-10f9-4ed4-962e-cd015b92ebd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('112f4111-763b-4021-b675-245c29538459', 'Anther, Filament, Pollen', false, 'b9b37ff7-10f9-4ed4-962e-cd015b92ebd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('082deba4-d32a-4adc-b938-96863ecb1737', 'Sepal, Petal, Node', false, 'b9b37ff7-10f9-4ed4-962e-cd015b92ebd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5b0b7cd-6b28-44aa-803d-58d1b8517d40', 'Root, Stem, Leaf', false, 'b9b37ff7-10f9-4ed4-962e-cd015b92ebd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa81d5e0-d518-472e-b8fe-9cfe16e1ea12', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the small bead-like structures found attached inside the cut ovary of a flower called?', 'Ovules are the female megasporangia housed on ovarian placentas that ripen into seeds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4899f25-88e5-4fcf-9af5-d2a838b26581', 'Ovules (which develop into seeds after fertilization)', true, 'aa81d5e0-d518-472e-b8fe-9cfe16e1ea12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fda812c3-2979-4889-8129-e1841fa40aa1', 'Pollen grains', false, 'aa81d5e0-d518-472e-b8fe-9cfe16e1ea12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('481b772d-325f-48c2-be9b-10b8f7da7e56', 'Sepals', false, 'aa81d5e0-d518-472e-b8fe-9cfe16e1ea12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bb24710-834d-47bc-bc36-bc2b880aba28', 'Stomata', false, 'aa81d5e0-d518-472e-b8fe-9cfe16e1ea12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ba9414b-ae29-4401-be6b-d52db50e6784', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'After successful pollination and fertilization, what does the flower''s Ovary ripen into?', 'Post-fertilization hormonal signaling swells ovarian pericarp tissues into botanical fruit surrounding the mature seeds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('facaa646-0de7-4c74-b684-93fa147353be', 'The Fruit (containing seeds inside)', true, '0ba9414b-ae29-4401-be6b-d52db50e6784');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06e3f964-6a88-491f-9e20-7e3217b35800', 'A new leaf', false, '0ba9414b-ae29-4401-be6b-d52db50e6784');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54c736b8-d90a-4e1c-b7ea-f8649f620e4e', 'A root', false, '0ba9414b-ae29-4401-be6b-d52db50e6784');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e9c1ab1-2fe5-4afb-923c-9c019323f804', 'A petal', false, '0ba9414b-ae29-4401-be6b-d52db50e6784');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48277e26-698d-4cf4-a3c7-f2e8f8e88676', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'In an experiment, a freshly cut leafy branch with white flowers is placed in water coloured with red ink. What happens after a few hours?', 'Demonstrates xylem vascular conduction: negative transpiration pull draws colored aqueous dye up through stem capillaries.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3b6d5ef-b3f0-40ce-b5f2-4a9839d99d5e', 'Red color ascends through narrow vascular tubes inside the stem, turning the flower petals and leaf veins reddish', true, '48277e26-698d-4cf4-a3c7-f2e8f8e88676');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1e80581-9aa2-4bb5-8d1c-777aa0955efb', 'The branch dissolves completely', false, '48277e26-698d-4cf4-a3c7-f2e8f8e88676');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('617ee7af-b425-41d7-97a6-9672d7391df2', 'The leaves turn black', false, '48277e26-698d-4cf4-a3c7-f2e8f8e88676');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('270b582f-6c7a-484d-92f9-fb5bd8621afe', 'The water evaporates instantly', false, '48277e26-698d-4cf4-a3c7-f2e8f8e88676');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ece93fc-3fde-4fa4-9a87-ec9997b6278d', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'Why are bright, colourful petals and sweet nectar present in many entomophilous flowers?', 'Pigmented floral visual displays and nectar rewards entice insect pollinators to transfer pollen between blossoms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eef32f5-4f80-47c4-a296-722a7b5de0c0', 'To attract honeybees, butterflies, and insects for cross-pollination', true, '0ece93fc-3fde-4fa4-9a87-ec9997b6278d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c339b3c-8d7b-43bb-80da-a9f98bb92f99', 'To keep the flower warm at night', false, '0ece93fc-3fde-4fa4-9a87-ec9997b6278d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('939776a0-3a96-4eac-823b-2b1ed4d7b3dd', 'To frighten grazing cattle', false, '0ece93fc-3fde-4fa4-9a87-ec9997b6278d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0476bebd-613d-4727-b1b6-20c885e51478', 'To absorb extra rain', false, '0ece93fc-3fde-4fa4-9a87-ec9997b6278d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1acee154-438f-4836-8a38-53a0795d931f', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'Which of the following root vegetables represents an enlarged, modified Taproot storing surplus food?', 'Carrot, radish, turnip, and beetroot are swollen biennial primary taproots storing accumulated carbohydrate reserves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e7bdd4c-0c5b-4d9e-9114-3ea6e23e09af', 'Carrot, Radish, and Beetroot', true, '1acee154-438f-4836-8a38-53a0795d931f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25fd2556-3d48-49dc-a093-a0877f1150e6', 'Potato and Ginger', false, '1acee154-438f-4836-8a38-53a0795d931f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('359356e1-7d55-4ab1-9ee5-f6c95bb45bb6', 'Onion and Garlic', false, '1acee154-438f-4836-8a38-53a0795d931f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91e53319-80f8-47ee-952f-bdcbf9e93c68', 'Tomato and Brinjal', false, '1acee154-438f-4836-8a38-53a0795d931f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('479c1e69-a95c-4ec5-b7bd-e99beaa39d87', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'Potato, ginger, and turmeric grow underground but are botanically classified as modified STEMS because:', 'Tubers and rhizomes exhibit cauline morphological features: nodes, internodal spacing, and vegetative eye buds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3f597fd-9547-4cac-b5ac-77c2246ae693', 'They possess nodes, internodes, scale leaves, and axillary buds (eyes)', true, '479c1e69-a95c-4ec5-b7bd-e99beaa39d87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cd11499-1db1-4528-b9c5-53ed8eb4dcd7', 'They absorb water from soil like roots', false, '479c1e69-a95c-4ec5-b7bd-e99beaa39d87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5960b445-8d94-4130-a75c-3ebf45fc2949', 'They have root caps', false, '479c1e69-a95c-4ec5-b7bd-e99beaa39d87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2b10fb0-9f46-4694-990c-413bc0409364', 'They have no cells', false, '479c1e69-a95c-4ec5-b7bd-e99beaa39d87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7175c295-a7d3-4448-a986-59ce95b64ff8', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What happens when a clear polythene bag is tied around a leafy green twig of a potted plant kept in bright sunlight?', 'Transpirational water vapor escaping from foliar stomata hits the cooler polyethylene film and condenses into liquid droplets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15405f3c-ef7d-4dc5-946c-6e87684db28d', 'Tiny droplets of water condense on the inner walls of the bag due to transpiration', true, '7175c295-a7d3-4448-a986-59ce95b64ff8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b922d30-52c2-41c7-a83d-439fac31af42', 'The bag fills with black smoke', false, '7175c295-a7d3-4448-a986-59ce95b64ff8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87d6f977-0b40-4542-a16c-151b2d049c1c', 'The leaves turn into wood', false, '7175c295-a7d3-4448-a986-59ce95b64ff8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06838baa-ad07-412e-8619-ef8f5898d42f', 'The bag catches fire', false, '7175c295-a7d3-4448-a986-59ce95b64ff8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06fbead6-a984-46f2-9f8c-1daca15a8536', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'Which test confirms that green leaves produce and store carbohydrate Starch during photosynthesis?', 'Ethanol extracts green chlorophyll; subsequent triiodide staining yields a deep blue-black amylose-iodine complex.', NOW()) ON CONFLICT DO NOTHING;
