INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b9d7dac-ca0b-4b87-a7cc-2b918bf9a086', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'Which of the following plants has leaves with PARALLEL venation and a FIBROUS root system?', 'Poaceae grasses and cereals (maize, wheat, rice) are monocots with linear parallel venation and adventitious fibrous roots.', NOW()) ON CONFLICT DO NOTHING;
