INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84f70098-5f3e-4e6b-9d9f-cd4051fd722a', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'A potted green plant kept inside a dark cupboard for 48 hours is tested with iodine solution for starch. The leaf does NOT turn blue-black. Why?', 'Without photons to drive light reactions, dark metabolism hydrolyzes stored amylose reserves to sustain basal cellular respiration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ebda30a-7f1e-4db6-8759-5b53a4ab8621', 'In the absence of sunlight, photosynthesis ceased, and the plant consumed all its stored starch through cellular respiration (Destarching)', true, '84f70098-5f3e-4e6b-9d9f-cd4051fd722a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e68f163-9199-4504-b427-8b93e62bc0ab', 'The iodine lost its chemical power', false, '84f70098-5f3e-4e6b-9d9f-cd4051fd722a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d41210ab-e5a0-4ea3-9d03-52f6d4d1f276', 'The leaves dissolved in the dark', false, '84f70098-5f3e-4e6b-9d9f-cd4051fd722a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa389f78-bd08-4aa0-9824-140c023e7d7b', 'Darkness creates excess starch', false, '84f70098-5f3e-4e6b-9d9f-cd4051fd722a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd8142d3-3a50-4d1b-8e45-cac8ce487070', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Match Column I (Flower Organs) with Column II (Functions):
(a) Sepals   -> (i) Protect flower during bud stage
(b) Petals   -> (ii) Attract insect pollinators
(c) Anther   -> (iii) Produce male pollen grains
(d) Stigma   -> (iv) Receive pollen grains during pollination', 'Sepals = bud protection; Petals = pollinator attraction; Anther = pollen genesis; Stigma = pollen reception.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94517d70-5f1b-4613-ab92-093954f54874', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'dd8142d3-3a50-4d1b-8e45-cac8ce487070');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a65e08d-f656-4bab-8d91-59a6e866e51d', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'dd8142d3-3a50-4d1b-8e45-cac8ce487070');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02cc6b53-822e-44de-92ed-2378b8082597', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'dd8142d3-3a50-4d1b-8e45-cac8ce487070');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cacfa3d0-bcc6-458c-8353-1aab169f3efa', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'dd8142d3-3a50-4d1b-8e45-cac8ce487070');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4744e50-c4db-4c2a-8aaa-6fa570592105', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Read the statements regarding plant physiology:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1e90e82-9d17-4c26-b930-081e1a6e4459', 'Statements 1 and 3 only', true, 'd4744e50-c4db-4c2a-8aaa-6fa570592105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f488a398-254b-4892-af82-4270f7cc2cdf', 'Statements 1 and 2 only', false, 'd4744e50-c4db-4c2a-8aaa-6fa570592105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a25abbf1-fb02-47ba-9f4b-76e2abe25dc0', 'Statements 2 and 3 only', false, 'd4744e50-c4db-4c2a-8aaa-6fa570592105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df6c1cb0-7dd0-42f7-ac75-b868817eb683', 'All Statements 1, 2, and 3', false, 'd4744e50-c4db-4c2a-8aaa-6fa570592105');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5b0a16a-f08e-40ab-a493-04ec82f3a392', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Why do desert xerophytic plants (like Opuntia cactus) have leaves modified into sharp spines and fleshy green stems?', 'Foliar reduction into sclerified spines minimizes surface area for transpiration, while the phylloclade stem handles photosynthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdf63ba2-3b14-45ec-ba4c-aa389e54cfb4', 'Spines drastically reduce water loss via transpiration, while the thick green stem carries out photosynthesis and stores succulent water', true, 'b5b0a16a-f08e-40ab-a493-04ec82f3a392');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dc4eadc-ffa8-48f7-a12c-efef152cdab3', 'Spines absorb water from air', false, 'b5b0a16a-f08e-40ab-a493-04ec82f3a392');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90615ccc-264c-47a8-8611-de07aba7c16c', 'To frighten wild animals only', false, 'b5b0a16a-f08e-40ab-a493-04ec82f3a392');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78df94aa-7f0c-458c-bd8a-4a96a88f37c2', 'Because desert soil has no minerals', false, 'b5b0a16a-f08e-40ab-a493-04ec82f3a392');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('746bbc17-cea8-47ef-a458-824e3e0dde7c', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'A student slices an ovary of a hibiscus flower horizontally (transverse cut) and another longitudinally (vertical cut). What do they observe under a magnifying lens?', 'Microscopic inspection reveals unfertilized megasporangiate ovules anchored to the central placenta within multi-locular carpels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d64f212c-a3a5-42ff-a899-85ecba1ac6ad', 'Small bead-like ovules arranged inside distinct ovarian chambers (locules)', true, '746bbc17-cea8-47ef-a458-824e3e0dde7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b05bb215-6411-49c8-b298-48a722d45066', 'Fully formed green seeds', false, '746bbc17-cea8-47ef-a458-824e3e0dde7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40a05ee6-4c0f-4b2d-b016-314de95cef03', 'Flowing red ink', false, '746bbc17-cea8-47ef-a458-824e3e0dde7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4dfa8b1-0da1-4cda-8dcc-6ab9c748f42b', 'Tiny pollen tubes only', false, '746bbc17-cea8-47ef-a458-824e3e0dde7c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4909054a-cea7-420c-9cb5-f627f7dca501', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Consider four plants:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6e5c783-e8b1-4a4e-a342-06431e3ee7d0', 'Plant 3 (Bamboo)', true, '4909054a-cea7-420c-9cb5-f627f7dca501');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddb6024d-7568-4a97-928a-428981df6e95', 'Plant 1 (Hibiscus)', false, '4909054a-cea7-420c-9cb5-f627f7dca501');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3bce599-78ea-4892-a0db-9cdb26cc8c87', 'Plant 2 (Mustard)', false, '4909054a-cea7-420c-9cb5-f627f7dca501');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5b22fa8-7eb4-4b4a-bb7a-0be8adad7a82', 'Plant 4 (Mango)', false, '4909054a-cea7-420c-9cb5-f627f7dca501');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c1098ba-0c4f-4971-98b5-6985466088d1', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Why must a leaf be boiled in alcohol / surgical spirit over a water bath (and NEVER directly over an open burner flame) during the starch test?', 'Ethanol''s low flash point (~13°C) demands indirect heating in a double-boiler water bath to safely extract chlorophyll.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56a216a7-2224-48ef-b35a-546e005cf397', 'Alcohol is highly flammable and volatile; heating directly over an open flame would ignite it and cause a severe fire hazard', true, '1c1098ba-0c4f-4971-98b5-6985466088d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe6eac62-f7bc-4b93-b2db-cc0a372c2067', 'Water bath makes the leaf sweet', false, '1c1098ba-0c4f-4971-98b5-6985466088d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3f74a3c-2407-4c89-844f-02f74ed2e4b5', 'Direct flame freezes alcohol', false, '1c1098ba-0c4f-4971-98b5-6985466088d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01f12d44-b365-4713-a124-d4e7ceb931e1', 'Alcohol turns into stone over flame', false, '1c1098ba-0c4f-4971-98b5-6985466088d1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad91ad0b-2a20-4974-bdea-e6ca9491810a', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'What is the primary role of the ''transpiration pull'' generated by leaves in tall hundred-meter giant redwood trees?', 'Cohesion-Tension theory: Meniscus evaporation in stomatal chambers generates negative xylem xylem sap tension (~-2 MPa) pulling water upwards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e81784f-eb02-4eb2-bcff-98ada1fe928c', 'It creates continuous negative hydrostatic suction tension that lifts water and dissolved mineral ions from deep root hair cells to top canopy leaves', true, 'ad91ad0b-2a20-4974-bdea-e6ca9491810a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e318f025-f0ea-4b9b-8d40-20b4a99377a2', 'It pushes the tree trunk into the ground', false, 'ad91ad0b-2a20-4974-bdea-e6ca9491810a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8170506f-eaa2-4ca3-8b2f-9252f3afa537', 'It stops the leaves from getting green', false, 'ad91ad0b-2a20-4974-bdea-e6ca9491810a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac1daf46-0c64-4ff0-8c4f-2caeb1304534', 'It keeps the tree warm in summer', false, 'ad91ad0b-2a20-4974-bdea-e6ca9491810a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89bd8076-d406-437c-a768-e52339046c47', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Which of the following flowers is ''Incomplete'' because it lacks either male stamens or female pistil in the same blossom (Unisexual flower)?', 'Papaya and cucumber are dioecious/monoecious species bearing unisexual staminate (male) or pistillate (female) flowers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('deca7be8-8cab-4d18-a5d8-a9a510dad019', 'Papaya and Cucumber flower', true, '89bd8076-d406-437c-a768-e52339046c47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61a0158c-b5e5-48ce-8901-915f94a00297', 'Mustard flower', false, '89bd8076-d406-437c-a768-e52339046c47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ef8833e-7f16-47c9-a803-4db5213af92a', 'China rose (Hibiscus)', false, '89bd8076-d406-437c-a768-e52339046c47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61a1ef64-324a-48e0-9598-101f286ecc40', 'Rose flower', false, '89bd8076-d406-437c-a768-e52339046c47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8825a02-23fb-460c-8961-8e5af03573e9', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'What anatomical pathway traces the path of a water molecule from soil entry to atmospheric release?', 'Unidirectional transpiration stream: soil water traverses root cortex into central vascular stele, ascends xylem pipes, and exits via leaf stomata.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38c7caa5-0d04-454e-958d-fc7f683eda08', 'Soil water -> Root hair -> Root xylem -> Stem xylem -> Leaf petiole & veins -> Stomatal pores -> Atmosphere (as vapor)', true, 'e8825a02-23fb-460c-8961-8e5af03573e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66f5b1a6-7dbb-4ed7-89fe-3d3739f5e655', 'Leaf -> Stem -> Root -> Soil', false, 'e8825a02-23fb-460c-8961-8e5af03573e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcabd2a1-90d7-41f2-b0dd-ae1b3f10ea50', 'Flower -> Stem -> Root -> Seed', false, 'e8825a02-23fb-460c-8961-8e5af03573e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f057ef9a-1650-4153-8044-3fbea0a9304a', 'Soil -> Stoma -> Root -> Stem', false, 'e8825a02-23fb-460c-8961-8e5af03573e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fefe45f-f844-441e-a038-fa92d4c08c8d', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Easy', 'A dimensionless location in space which has zero length, zero breadth, and zero thickness, denoted by a sharp dot, is a:', 'A point is a fundamental geometric primitive indicating an exact position in space, represented by a single capital letter (e.g. Point A).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0c160a8-5bbb-4d7e-a5a0-956590c1d175', 'Point', true, '7fefe45f-f844-441e-a038-fa92d4c08c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51fadfde-5673-4846-8b91-3c29e3e34ff1', 'Line', false, '7fefe45f-f844-441e-a038-fa92d4c08c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7da2044-0dae-445e-b52a-819a5453ff0c', 'Ray', false, '7fefe45f-f844-441e-a038-fa92d4c08c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0077121-2e5e-4a33-8c87-1ddd657f1795', 'Plane', false, '7fefe45f-f844-441e-a038-fa92d4c08c8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3840daa9-b09f-4721-9496-60c61d4a1a26', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Easy', 'A straight path connecting two fixed end points A and B, which has a definite measurable length, is called a:', 'A line segment AB is the shortest path bounded by two distinct end points A and B.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5badf98a-e359-48c5-b127-eac7f50f5289', 'Line Segment (denoted as AB)', true, '3840daa9-b09f-4721-9496-60c61d4a1a26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d02261fd-ef10-4240-8c51-c1d9c902b2df', 'Line', false, '3840daa9-b09f-4721-9496-60c61d4a1a26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2aae3258-e206-45da-83d4-0f27762281cb', 'Ray', false, '3840daa9-b09f-4721-9496-60c61d4a1a26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06289f24-97a4-416e-8d60-7f778972f192', 'Curve', false, '3840daa9-b09f-4721-9496-60c61d4a1a26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4878d59-79cf-4c97-821b-21257a5e82cb', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Easy', 'A straight path that extends infinitely without end in BOTH directions and has no fixed length is called a:', 'A line extends boundlessly in both opposite directions and has zero end points.', NOW()) ON CONFLICT DO NOTHING;
