INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('343c43bc-e08d-48f6-a56a-2dfe04ce0a86', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'Three or more lines in a plane that pass through the exact same single intersection point are called:', 'Lines intersecting at a single common point of concurrency are termed concurrent lines.', NOW()) ON CONFLICT DO NOTHING;
