INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('402b6db9-d8d1-4d85-b5d7-72121044fa1f', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'What is a ''Simple Closed Curve''?', 'A Jordan curve is simple if it does not self-intersect and closed if its start and end coordinates coincide.', NOW()) ON CONFLICT DO NOTHING;
