INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dc76c16-2e81-4d21-be9a-8c0bb8e02fff', 'A curve that crosses itself like a figure-8', false, '402b6db9-d8d1-4d85-b5d7-72121044fa1f');
