INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f565563d-38a5-451f-8020-426af6e55612', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'Into how many distinct regions does a simple closed curve divide the plane it lies on?', 'Jordan Curve Theorem: A simple closed planar curve partitions the plane into interior, boundary, and exterior.', NOW()) ON CONFLICT DO NOTHING;
