INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('441f5623-b01e-4176-9f0c-6054fedf72ff', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'What is a 4-sided polygon called in geometry?', 'A quadrilateral is a 4-gon consisting of 4 vertices, 4 edges, and 2 internal diagonals.', NOW()) ON CONFLICT DO NOTHING;
