INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30f54655-b2e5-4569-a07c-57f0891d9970', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'How many diagonals does a regular quadrilateral (4-sided polygon) possess?', 'Formula d = n(n-3)/2; for n = 4: d = 4(4-3)/2 = 2 diagonals.', NOW()) ON CONFLICT DO NOTHING;
