INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5eef8e0-7160-4780-bfe1-9a52196d9ad1', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'Match Column I (Geometric Terms) with Column II (Definitions):
(a) Ray       -> (i) Two endpoints with fixed length
(b) Line      -> (ii) One endpoint, extending infinitely in one direction
(c) Segment   -> (iii) Zero endpoints, extending infinitely both ways
(d) Point     -> (iv) Position in space with zero dimensions', 'Ray = 1 endpoint; Line = 0 endpoints (infinite both sides); Segment = 2 endpoints; Point = 0 dimensions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ec85568-644e-40fd-991b-311699b7e2bf', 'a-(ii), b-(iii), c-(i), d-(iv)', true, 'f5eef8e0-7160-4780-bfe1-9a52196d9ad1');
