INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3647dc18-3f89-426d-b230-aceaf7d6ceb3', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'How many lines can be drawn passing through any TWO points chosen out of FOUR collinear points?', 'Since all 4 points lie on the exact same single straight line, every pair defines that same unique collinear line.', NOW()) ON CONFLICT DO NOTHING;
