INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('714f3c6c-b505-453f-99da-436e00694b32', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'How many lines can be drawn passing through pairs of points chosen from FOUR points where NO THREE points are collinear?', 'Combinatorial formula n(n-1)/2: with 4 non-collinear points, total unique lines = 4 × 3 / 2 = 6 lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb39e8ae-7c19-49bc-82da-af3da6ef9851', '6 lines (4C2 = 4 × 3 / 2 = 6)', true, '714f3c6c-b505-453f-99da-436e00694b32');
