INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c44e8be8-7f6d-4796-bc56-d1cf5a99c47f', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'What is the difference between an ''Open Curve'' and a ''Closed Curve''?', 'Closed curves enclose a bounded interior domain because their endpoints join; open curves do not bound an interior.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c463d56c-dc19-42c1-8099-3e9047bcb8c4', 'In an open curve, the two starting and ending points do not meet, whereas in a closed curve, the path begins and ends at the exact same point', true, 'c44e8be8-7f6d-4796-bc56-d1cf5a99c47f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b0b03ee-5197-4fbe-904a-068912beb5ae', 'An open curve is made of metal', false, 'c44e8be8-7f6d-4796-bc56-d1cf5a99c47f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7be9a99-5275-403c-8503-f0b32ef45fd0', 'A closed curve is always a straight line', false, 'c44e8be8-7f6d-4796-bc56-d1cf5a99c47f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98b304e1-c45f-4404-abec-98878dc30c15', 'There is no difference', false, 'c44e8be8-7f6d-4796-bc56-d1cf5a99c47f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1012022d-8bed-407b-b0d6-dfeb49033f23', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'Consider a point P situated inside a circle of radius 5 cm. If the distance from the center O to point P is d(O, P) = 3.5 cm, where does point P lie?', 'Since d(O, P) = 3.5 cm < r = 5 cm, point P lies strictly within the circle''s interior.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beadfb5c-b299-427b-83ff-1f7044d6102a', 'In the Interior of the circle', true, '1012022d-8bed-407b-b0d6-dfeb49033f23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('feaaced3-b428-454d-876c-a2ceb28da700', 'On the boundary (circumference) of the circle', false, '1012022d-8bed-407b-b0d6-dfeb49033f23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ea22fb8-b62e-4394-98b0-1fc86a239121', 'In the Exterior of the circle', false, '1012022d-8bed-407b-b0d6-dfeb49033f23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6442f9ef-31b0-404a-be52-c19dd237879a', 'At infinity', false, '1012022d-8bed-407b-b0d6-dfeb49033f23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22c8a9a5-a44b-4385-a35b-eb399f7e6ebe', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'If ray OA and ray OB point in EXACTLY opposite directions forming a straight line, what angle is formed at vertex O?', 'Collinear opposite rays originating from vertex O define a straight angle measuring exactly 180°.', NOW()) ON CONFLICT DO NOTHING;
