INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b3e01fc-c8db-4325-8de3-ab9d73257ceb', 'A Complete Angle = 360°', false, '22c8a9a5-a44b-4385-a35b-eb399f7e6ebe');
