INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6c772c8-6f1d-4645-ac29-869a29dcf4ed', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What inspiring message did Kalpana Chawla send to students from aboard the Space Shuttle Columbia?', 'Her immortal transmission from Columbia inspired youth worldwide to boldly pursue their highest aspirations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e951cec2-c65e-4e0f-913d-073895f91fa6', '"The path from dreams to success does exist. May you have the vision to find it, the courage to get onto it, and the perseverance to follow it."', true, 'b6c772c8-6f1d-4645-ac29-869a29dcf4ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3dc9a18-aed5-4875-a3c3-b27dfa4294fc', '"Space is too dangerous for students."', false, 'b6c772c8-6f1d-4645-ac29-869a29dcf4ed');
