INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76b926dc-b910-4972-a705-0b115342a42a', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What other aircraft pilot licenses did Kalpana Chawla hold besides astronaut qualifications?', 'She was a multi-engine land and seaplane pilot, glider enthusiast, and FAA-certified flight instructor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6d33e40-40db-4020-9b1d-9059952fed4c', 'Commercial pilot licenses for single and multi-engine land planes, single-engine seaplanes, gliders, and certified flight instructor', true, '76b926dc-b910-4972-a705-0b115342a42a');
