INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10895830-fbea-4eb6-a17b-24943670ab48', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What scientific experiments did the Columbia crew conduct during their 16-day STS-107 flight?', 'The SPACEHAB payload conducted 80 microgravity biology, physical science, and fluid physics experiments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60acdb27-a0d6-4be1-a794-d5a342888152', '80 scientific experiments including plant microgravity pollination, materials crystal growth, and combustion behavior in space', true, '10895830-fbea-4eb6-a17b-24943670ab48');
