INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffe716b0-4aa6-41f9-9105-e3de86cc6f25', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'How did deaf shopkeeper Ray defuse a potential armed robbery at his clock shop on Christmas Eve?', 'Ray sensed their desperation, communicated through written notes, and extended compassionate financial help without judgment.', NOW()) ON CONFLICT DO NOTHING;
