INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b0b42b9-3ae4-478a-8df4-ddcbbcfeae0e', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'Why was Ray NOT a commercial moneylender / pawn-broker in the traditional sense?', 'Ray operated out of goodwill, providing bridge loans against used watches to aid destitute folks through hard times.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39504f5c-ca11-4221-9c42-14a4b6f80c31', 'He never charged exorbitant interest and always returned items to needy people whenever they could repay the exact loaned amount', true, '4b0b42b9-3ae4-478a-8df4-ddcbbcfeae0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84ccc16b-512e-4e5d-9022-b53f9707d174', 'He took items for free', false, '4b0b42b9-3ae4-478a-8df4-ddcbbcfeae0e');
