INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0bde48f8-1487-4e75-9d40-2c6edc29f3bf', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What musical chime filled the shop as the clock struck midnight at 12:00 on Christmas Eve?', 'The synchronized chiming of antique clocks resonated as a timeless Christmas benediction of peace and universal brotherhood.', NOW()) ON CONFLICT DO NOTHING;
