INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54f50fcd-34fb-4223-b3d7-6c88a13ada37', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What is a ''Space Shuttle''?', 'NASA Space Shuttles were winged, reusable orbital spacecraft designed to ferry crews and satellite cargo to low Earth orbit.', NOW()) ON CONFLICT DO NOTHING;
