INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00a61a0d-2ab7-4530-9615-0bf329860715', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What did journalists write about Kalpana Chawla''s extraordinary intellectual capability?', 'Her biographical tribute highlighted the multidisciplinary mastery of mathematics, biology, astronomy, and physics required of astronauts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b25640c-07ff-4599-9668-d58285606beb', '"She was a heroine; to become an astronaut, one needs enormous knowledge about everything from biology to astrophysics and aeronautical engineering"', true, '00a61a0d-2ab7-4530-9615-0bf329860715');
