INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b98a6f9-a3e1-4a21-a28c-6734e9822e91', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'In ''The Old-Clock Shop'', what was in the pocket of the younger man standing near the shop entrance?', 'Ray noticed the gun bulge in the visitor''s coat pocket, understanding their desperate criminal intent.', NOW()) ON CONFLICT DO NOTHING;
