INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4136fa5b-c2bf-400c-b217-eba41cec9bc0', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'How did the older visitor''s face change when Ray handed him a fifty-dollar bill for his ordinary watch?', 'Ray''s unexpected grace and generous loan diffused their criminal desperation, replacing tension with heartfelt gratitude.', NOW()) ON CONFLICT DO NOTHING;
