INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('470a7dea-7c58-468a-9d76-febbcf7759ac', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What poetic structure does E-Yeh-Shure use in the poem ''Beauty''?', 'The poem is organized into sensory visual beauty (Stanza 1), auditory beauty (Stanza 2), and moral beauty of the soul (Stanza 3).', NOW()) ON CONFLICT DO NOTHING;
