INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fb17034-0192-46c6-bc48-f62d57548455', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Hard', 'What philosophical philosophy of non-violence and restorative empathy did Ray exercise in ''The Old-Clock Shop''?', 'Ray transformed a volatile life-threatening armed robbery into an act of mutual respect, redemption, and holiday peace.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('060848bb-540e-49f3-82d4-d4a5e0b0c8ef', 'He weaponized empathy: defusing potential violence by acknowledging human dignity, offering economic relief, and neutralizing criminal desperation', true, '7fb17034-0192-46c6-bc48-f62d57548455');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33baf8d7-3bba-450f-8671-1704c36f2a7d', 'He feigned death to escape', false, '7fb17034-0192-46c6-bc48-f62d57548455');
