INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9793a74f-b445-45f0-b43b-1359a2ed7130', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Hard', 'In the poem ''Beauty'', how does the poet redefine beauty beyond superficial physical glamour?', 'E-Yeh-Shure elevates aesthetics from external visual perception to ethical purity and moral integrity of the human heart.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5c6bc02-409a-430a-ba20-537bead3c417', 'By asserting that the highest form of beauty is internal — residing in virtuous conduct, noble thoughts, and sincere selfless intentions', true, '9793a74f-b445-45f0-b43b-1359a2ed7130');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f54dc15e-12b9-4f64-bc07-38fcf9751951', 'By claiming beauty only exists in museums', false, '9793a74f-b445-45f0-b43b-1359a2ed7130');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1067b08e-4979-4b78-b70e-36e0d1ef5af7', 'By stating beauty can be bought with money', false, '9793a74f-b445-45f0-b43b-1359a2ed7130');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('684d7fc4-8654-485f-9949-62e9aae12859', 'By saying only poets can have beauty', false, '9793a74f-b445-45f0-b43b-1359a2ed7130');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('712e12bd-43cd-46c9-8fb8-81f031a98521', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Hard', 'Match the following historical events with their dates in Kalpana Chawla''s life:
(a) Selected by NASA as astronaut candidate -> (i) 1 February 2003
(b) First spaceflight launch (STS-87)         -> (ii) December 1994
(c) Tragic Columbia re-entry accident        -> (iii) 19 November 1997
(d) Birth in Karnal                          -> (iv) 17 March 1962 (official records)', 'NASA Selection = 1994; STS-87 launch = 1997; Columbia disaster = 1 Feb 2003; Birth = 1962.', NOW()) ON CONFLICT DO NOTHING;
