INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b267c53-dd7b-49a6-a16e-b2318dd93867', 'Kalpana said that she had never dreamed that she would cross the frontiers of space.', true, '289c5f5a-77ad-486c-b56f-7e1dfc69d066');
