INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06601625-dfd0-437c-8c4d-a553245c1c31', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Hard', 'What is the figurative meaning of the phrase ''to cross the frontiers of space''?', '''Frontiers of space'' symbolizes the outermost boundary of human technological reach and cosmic exploration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80cd2f2d-9e00-47cd-a574-f14b70174451', 'To transcend earthly physical and technological boundaries to explore the cosmos', true, '06601625-dfd0-437c-8c4d-a553245c1c31');
