INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64b374e1-6868-4822-bbe2-ad48b8c3c6f4', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Hard', 'In ''The Old-Clock Shop'', why did Ray write on the notepad: ''May I help you?'' instead of asking aloud?', 'Ray''s hearing impairment necessitated written communication via notepad and pencil.', NOW()) ON CONFLICT DO NOTHING;
