INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e604f92-ab04-495a-af2f-f3191bc49bf1', 'Class 6', 'GK', 'Chapter 4: Wildlife, Flora & National Parks of India', 'Hard', 'What is the crucial ecological difference between a ''National Park'' and a ''Wildlife Sanctuary'' in India under the Wildlife Protection Act 1972?', 'National Parks have a higher degree of statutory protection with complete prohibition on livestock grazing and resource extraction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf07ee30-2d02-49de-8f48-29dfa0e18184', 'In a National Park, human activities (grazing, timber harvesting, private land ownership) are strictly prohibited, whereas in a Wildlife Sanctuary, limited traditional human activities may be permitted', true, '0e604f92-ab04-495a-af2f-f3191bc49bf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d203ae1f-17ad-44bf-8741-79357bd5ee15', 'Sanctuaries only have birds while parks have lions', false, '0e604f92-ab04-495a-af2f-f3191bc49bf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('282abc93-6297-487a-b50e-73b8b9d2f2a1', 'National parks are owned by private companies', false, '0e604f92-ab04-495a-af2f-f3191bc49bf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('252cc050-4b08-4330-9443-6ac95c9b94c7', 'There is zero difference', false, '0e604f92-ab04-495a-af2f-f3191bc49bf1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddeacd82-5b65-4ea7-b7f1-5f1e1c6a6b74', 'Class 6', 'GK', 'Chapter 4: Wildlife, Flora & National Parks of India', 'Hard', 'Which marine national park in Gujarat was the FIRST Marine National Park established in India (in 1982 in the Gulf of Kutch)?', 'Encompassing 42 islands in the Gulf of Kutch, it protects vibrant coral reefs, sponges, sea anemones, and dugongs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bb73ea1-3e7f-48a3-bd35-96d37c862d22', 'Marine National Park, Gulf of Kutch', true, 'ddeacd82-5b65-4ea7-b7f1-5f1e1c6a6b74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac4f5deb-7a02-4b1b-93a7-067d009e6a92', 'Gulf of Mannar Marine National Park', false, 'ddeacd82-5b65-4ea7-b7f1-5f1e1c6a6b74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('628c20dd-5aad-4217-ba75-eff4683c29b2', 'Mahatma Gandhi Marine National Park (Andamans)', false, 'ddeacd82-5b65-4ea7-b7f1-5f1e1c6a6b74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('963e33ad-03c0-4d37-80c6-edb37c27893f', 'Malvan Marine Sanctuary', false, 'ddeacd82-5b65-4ea7-b7f1-5f1e1c6a6b74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2158989-1181-4361-ad8f-9ed4f1770853', 'Class 6', 'GK', 'Chapter 4: Wildlife, Flora & National Parks of India', 'Hard', 'What is the critically endangered state bird of Rajasthan that faces severe electrocution threats from overhead power transmission lines in the Thar desert?', 'With fewer than 150 individuals remaining in the wild, the massive terrestrial Godawan is India''s most endangered grassland bird.', NOW()) ON CONFLICT DO NOTHING;
