INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bab7d1f5-044f-4663-b0db-3bd48099d5d7', 'Class 6', 'GK', 'Chapter 4: Wildlife, Flora & National Parks of India', 'Hard', 'Which aromatic evergreen timber tree native to the dry deciduous forests of Karnataka and Tamil Nadu is renowned as ''White Gold'' (Chandan)?', 'Santalum album is a hemiparasitic fragrant tree celebrated worldwide for prized santalol essential oil and carvings.', NOW()) ON CONFLICT DO NOTHING;
