INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e572086-2cd5-4807-af79-68de1c92be07', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'A representation or a drawing of the Earth''s surface or a part of it drawn on a flat surface according to a scale is called a:', 'A map is a scaled, symbolic flat 2D graphic representation of terrestrial spatial features.', NOW()) ON CONFLICT DO NOTHING;
