INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28c52630-372d-46a8-9e29-c291b3e86d6f', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'Maps showing natural features of the Earth such as mountains, plateaus, plains, rivers, and oceans are called:', 'Physical maps depict natural topography, terrain elevation, and hydrographic drainage networks.', NOW()) ON CONFLICT DO NOTHING;
