INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d9ad937-2b10-4468-8f27-0a7ad735c8ae', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'Maps that focus on specific information, such as road networks, rainfall distribution, forests, or industries, are called:', 'Thematic maps illustrate specialized spatial themes (e.g. population density, annual rainfall, mineral deposits).', NOW()) ON CONFLICT DO NOTHING;
