INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f996c35-ea82-4af6-9460-48cda61b3e4d', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'What are the THREE essential components of any standard map?', 'Cartography rests on three foundational structural components: Scale (Distance), Orientation (Direction), and Legend (Symbols).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43ad89a8-d676-4b12-a204-5af772b594f2', 'Distance, Direction, and Symbols', true, '1f996c35-ea82-4af6-9460-48cda61b3e4d');
