INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('852bae89-2116-4d1a-bcdb-e3ea5a1cd8fa', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'The ratio between the actual ground distance on the Earth and the distance shown on the map paper is called the:', 'Map scale = (Distance on Map) / (Actual Ground Distance).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbf9ddb7-e5b6-4142-80fb-a9ab7d2c43b5', 'Scale of the map', true, '852bae89-2116-4d1a-bcdb-e3ea5a1cd8fa');
