INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96fe3a9a-f511-4e86-a0d6-dd962843ea5b', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'What are the FOUR major Cardinal Points / Directions on a map?', 'The four primary cardinal directions are North (N), South (S), East (E), and West (W).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('482d6899-1426-47bd-a82f-8facecd2acb6', 'North, South, East, and West', true, '96fe3a9a-f511-4e86-a0d6-dd962843ea5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c0f839d-ef5f-4636-9c14-d8022c810061', 'North-East, North-West, South-East, South-West', false, '96fe3a9a-f511-4e86-a0d6-dd962843ea5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2d27f70-85ff-4add-91c7-7d1fa09567c1', 'Up, Down, Left, Right', false, '96fe3a9a-f511-4e86-a0d6-dd962843ea5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5aa4e079-9ba8-46d1-8663-1a92c13a2544', 'Top, Bottom, Front, Back', false, '96fe3a9a-f511-4e86-a0d6-dd962843ea5b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2c1f10a-7a6f-4da4-8169-de1299cf2413', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'What are the four intermediate directions located between the cardinal points?', 'The four ordinal/intercardinal compass bearings are NE (45°), SE (135°), SW (225°), and NW (315°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa0f935f-2f4c-4eab-b1f2-3125f18a0f22', 'North-East (NE), South-East (SE), South-West (SW), and North-West (NW)', true, 'e2c1f10a-7a6f-4da4-8169-de1299cf2413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4ec04b8-4977-4a6a-939f-b6eeb9c7f80d', 'North-Up, South-Down, East-Left, West-Right', false, 'e2c1f10a-7a6f-4da4-8169-de1299cf2413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6ed1887-d0cc-4220-9951-b7c42c15b7d4', 'Zenith, Nadir, Horizon, Meridian', false, 'e2c1f10a-7a6f-4da4-8169-de1299cf2413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ddc5f21-4ba1-4c15-aac5-eec70cb28192', 'Central, Upper, Lower, Outer', false, 'e2c1f10a-7a6f-4da4-8169-de1299cf2413');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63851773-4790-4c1e-b288-378dde7ec350', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'An instrument used to find the main directions, featuring a magnetic needle that always points towards the North-South direction, is a:', 'A magnetic compass needle aligns itself with the geomagnetic dipole axis pointing towards magnetic North.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bf089b3-36ac-4d58-b09a-00d427bf8f25', 'Magnetic Compass', true, '63851773-4790-4c1e-b288-378dde7ec350');
