INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b77ae0c-70eb-4cdf-a1c4-f8af752e16e2', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'Symbols on a map that are internationally agreed upon and recognized across the world are called:', 'Conventional signs and symbols follow standardized international cartographic conventions (e.g. blue for water, green for forests).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('724216c9-2aa5-44a4-8af3-07502ac72794', 'Conventional Symbols', true, '8b77ae0c-70eb-4cdf-a1c4-f8af752e16e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3dedcc0-52b4-4f39-adbf-4d30b23e8e64', 'Decorative Symbols', false, '8b77ae0c-70eb-4cdf-a1c4-f8af752e16e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffc7ee06-62bc-40c2-9068-97abcb27b3d6', 'Local Symbols', false, '8b77ae0c-70eb-4cdf-a1c4-f8af752e16e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4f2d811-fa08-49e4-b2c2-40ed50bec860', 'Abstract Sketches', false, '8b77ae0c-70eb-4cdf-a1c4-f8af752e16e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3801deac-a983-4981-854f-9a6d79569bc6', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'On a standard physical map, what natural feature is universally represented using BLUE color?', 'In standard topographic symbology, cyan/blue shades denote water bodies, streams, and reservoirs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4aaac50e-b7a3-4fae-bd38-c35edea68886', 'Water bodies (Oceans, Seas, Rivers, Lakes)', true, '3801deac-a983-4981-854f-9a6d79569bc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11267fbb-0e40-4d1a-87a2-5758d80f76bb', 'Mountains', false, '3801deac-a983-4981-854f-9a6d79569bc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1af2684f-d7ec-4ee6-b408-be0dd1547393', 'Forests and vegetation', false, '3801deac-a983-4981-854f-9a6d79569bc6');
