INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21f9339e-06f3-47d1-bd9a-0c93b8112acf', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'A book or bound collection of various maps of the world, continents, and countries is called an:', 'An Atlas is a comprehensive bound volume of geographical, thematic, and political charts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b2a6be2-b697-49d8-bb4d-8db08bddf799', 'Atlas', true, '21f9339e-06f3-47d1-bd9a-0c93b8112acf');
