INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5dc3e164-0339-497d-8bf7-c5c77292c2bf', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is the key difference between a ''Small Scale Map'' and a ''Large Scale Map''?', 'Scale fraction 1/50,000,000 is small (macro coverage), while 1/5,000 is large (micro granular street detail).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00d051dd-3ad9-40c5-8a4a-204974907a3c', 'A Small Scale map shows large areas (continents/countries) with less detail (e.g. 1 cm = 500 km), while a Large Scale map shows small areas (villages/towns) with great detail (e.g. 1 cm = 50 m)', true, '5dc3e164-0339-497d-8bf7-c5c77292c2bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07bd3597-2f50-4e63-9f1b-1156a68ff213', 'A Small scale map is drawn on tiny paper', false, '5dc3e164-0339-497d-8bf7-c5c77292c2bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cc01d25-c574-408e-9e69-88ff35fecd15', 'A Large scale map shows only outer space', false, '5dc3e164-0339-497d-8bf7-c5c77292c2bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccfc204c-12c8-4efb-b0f8-e0b89ccd9569', 'There is no difference', false, '5dc3e164-0339-497d-8bf7-c5c77292c2bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22630966-a4dc-4aa8-9ac7-f8aecfb41031', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is a ''Sketch'' in cartography?', 'A sketch map is a rapid, non-instrumental mental drawing showing landmarks to guide directions without scale.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3638463-4f52-49b4-bd1f-adfbbdcf5dcc', 'A rough drawing mainly based on memory and spot observation without any scale', true, '22630966-a4dc-4aa8-9ac7-f8aecfb41031');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3216639d-9a17-4015-ae29-265e3b9a58ba', 'A mathematically accurate scaled blueprint', false, '22630966-a4dc-4aa8-9ac7-f8aecfb41031');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed2ae688-022e-4806-9922-9c999e522405', 'A satellite photograph', false, '22630966-a4dc-4aa8-9ac7-f8aecfb41031');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32fc4f6c-5860-4688-8fa3-282b9ece0323', 'A globe', false, '22630966-a4dc-4aa8-9ac7-f8aecfb41031');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7231dd7-dd49-4e0f-9d4e-4c07deccaa5c', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is a ''Plan'' in cartography and architecture?', 'A plan provides ultra-large-scale engineering dimensions for an individual architectural space or plot.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('869a7f72-c4f7-4eac-a2ac-40669d4c41fd', 'A drawing of a small area (like a single room or house) drawn on a very large scale showing minute measurements like length and breadth', true, 'a7231dd7-dd49-4e0f-9d4e-4c07deccaa5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00d5792f-8a23-4e1a-93bd-b23dd4d6c52c', 'A rough sketch of a continent', false, 'a7231dd7-dd49-4e0f-9d4e-4c07deccaa5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c73acd69-2bca-4a47-b008-19c3f7be0fc2', 'A world map', false, 'a7231dd7-dd49-4e0f-9d4e-4c07deccaa5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a754caeb-e139-4b61-b3e3-ed79769f8888', 'A weather forecast', false, 'a7231dd7-dd49-4e0f-9d4e-4c07deccaa5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32a05abd-e225-430d-ac6c-25ead5032f4d', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What does the letter ''N'' with an arrow at the upper right-hand corner of a map indicate?', 'The North Arrow indicates true geodetic or grid north, establishing map orientation for navigation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb82ffb8-e47a-4d8e-a1cd-74121dd618ea', 'The North Direction (North Line)', true, '32a05abd-e225-430d-ac6c-25ead5032f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3fb29ee-a315-4f39-883b-dac4a84e7b3c', 'National Highway', false, '32a05abd-e225-430d-ac6c-25ead5032f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3e062dd-aab7-45f1-88f6-927a27992746', 'New Town', false, '32a05abd-e225-430d-ac6c-25ead5032f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef1c7726-088b-4495-b621-0d67433b43f5', 'No Entry', false, '32a05abd-e225-430d-ac6c-25ead5032f4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b6690e6-058b-46b4-9f5c-e70fcdb70072', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'On a standard physical map, what colors are conventionally used for Mountains, Plateaus, and Plains respectively?', 'Hypsometric tinting: Brown indicates high mountain relief, Yellow denotes intermediate plateau tablelands, and Green indicates low plains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fd927af-cab1-417d-a15c-64fa6771e53b', 'Mountains: Brown ; Plateaus: Yellow ; Plains: Green', true, '1b6690e6-058b-46b4-9f5c-e70fcdb70072');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a70b937-7d38-4729-a4c1-cb1431fea4fc', 'Mountains: Green ; Plateaus: Red ; Plains: Blue', false, '1b6690e6-058b-46b4-9f5c-e70fcdb70072');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f79317d-b443-429b-b964-14bb2a4cb5f1', 'Mountains: Yellow ; Plateaus: Brown ; Plains: White', false, '1b6690e6-058b-46b4-9f5c-e70fcdb70072');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21351d68-6d23-401d-b2fd-831fd052d181', 'Mountains: White ; Plateaus: Green ; Plains: Black', false, '1b6690e6-058b-46b4-9f5c-e70fcdb70072');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c5765fe-61ee-425b-9680-a8d36b2b5f8c', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'Why are conventional symbols, letters, shades, and signs extensively used in maps?', 'Cartographic symbols compress complex multidimensional geographic features into concise, universally decodable visual tokens.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e65f9706-3086-48fb-882d-613921d1e0eb', 'They allow large amounts of spatial information (roads, bridges, trees, railways, temples) to be depicted clearly in a limited map space', true, '9c5765fe-61ee-425b-9680-a8d36b2b5f8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db59eb4a-0445-42d0-98d7-4c705b07c92a', 'To make maps look like paintings', false, '9c5765fe-61ee-425b-9680-a8d36b2b5f8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cddf30b2-9c7a-4d4c-9d01-43f1496a0e7f', 'To hide secrets from enemies', false, '9c5765fe-61ee-425b-9680-a8d36b2b5f8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e56eea0-c834-412d-8a32-5dedef5bf2b5', 'Because map makers cannot write words', false, '9c5765fe-61ee-425b-9680-a8d36b2b5f8c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d146a362-df73-4588-83dc-de1d2f67b3af', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'If a map uses a scale of ''1 cm = 5 km'', what is the actual ground distance between two railway stations that are 6 cm apart on the map?', 'Ground distance = Map distance × Scale factor = 6 cm × 5 km/cm = 30 kilometers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61f7b336-1e71-4e6a-8c87-7a805fb187e5', '30 km (6 cm × 5 km/cm)', true, 'd146a362-df73-4588-83dc-de1d2f67b3af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b9cecf3-d07c-478d-a807-5518521d6cec', '11 km', false, 'd146a362-df73-4588-83dc-de1d2f67b3af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72a48253-3dd0-4da9-b6b0-b338b5f0d7fb', '60 km', false, 'd146a362-df73-4588-83dc-de1d2f67b3af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d3bfcfd-cc1a-4bd7-9322-b1df4c3e3751', '5 km', false, 'd146a362-df73-4588-83dc-de1d2f67b3af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b06c7b3-ed48-411a-a929-e940f21996f1', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is the conventional cartographic symbol for a ''Broad Gauge Railway Line'' with a railway station?', 'Survey of India standards use a hatched black band with an attached ''RS'' box for broad gauge railway stations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad04c3b8-4c1e-41e8-a35d-4659178a461e', 'A black track with alternating cross-hatches and a rectangle marked ''RS''', true, '8b06c7b3-ed48-411a-a929-e940f21996f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc369fea-17e4-4e38-87cb-812fd5a65b18', 'A continuous red line', false, '8b06c7b3-ed48-411a-a929-e940f21996f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9d146c0-1412-4c85-94a9-9cde8a7a81a1', 'A blue wavy curve', false, '8b06c7b3-ed48-411a-a929-e940f21996f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20c64682-ab82-49bb-a412-776fecf04579', 'A green circle', false, '8b06c7b3-ed48-411a-a929-e940f21996f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f5e562e-e3b3-4f22-825f-1672df53cd06', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What conventional symbol is used to represent a ''Metalled Road'' versus an ''Unmetalled Road'' on Indian topographical maps?', 'Pucca metalled roads are depicted as continuous double red lines, while kuccha unmetalled tracks are dashed double lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('313f9a47-44ba-478e-9267-c0e6ab4fb77b', 'Metalled Road: Two parallel continuous red lines ; Unmetalled Road: Two parallel broken/dashed red lines', true, '2f5e562e-e3b3-4f22-825f-1672df53cd06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be04ab85-6c46-464f-82a0-0b22e326cd0a', 'Metalled: Solid blue line ; Unmetalled: Green line', false, '2f5e562e-e3b3-4f22-825f-1672df53cd06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1324d44b-f575-45d2-9618-9e8027bcc2d5', 'Metalled: Black dots ; Unmetalled: Solid square', false, '2f5e562e-e3b3-4f22-825f-1672df53cd06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70b47f79-bcde-4f48-8ded-ed05de7cc25d', 'Metalled: Star ; Unmetalled: Triangle', false, '2f5e562e-e3b3-4f22-825f-1672df53cd06');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe747f4d-c13d-4cda-b1e8-424a0939f680', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What abbreviation is conventionally used on Indian maps for ''Post Office'', ''Post and Telegraph Office'', and ''Police Station''?', 'Standard Survey of India abbreviations: PO = Post Office, PTO = Post & Telegraph Office, PS = Police Station.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8be08bc1-5a31-440a-b257-904eeab30dea', 'PO, PTO, and PS respectively', true, 'fe747f4d-c13d-4cda-b1e8-424a0939f680');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3d8a135-0d0b-46f0-901b-019620f93b62', 'PO, POST, POL', false, 'fe747f4d-c13d-4cda-b1e8-424a0939f680');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f44ed84-db8e-4219-bb7b-702ddb87deef', 'P, PT, PL', false, 'fe747f4d-c13d-4cda-b1e8-424a0939f680');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aacc9ee9-b1ed-4f66-95f2-c1a54bdfb9a8', 'OFF, TEL, COP', false, 'fe747f4d-c13d-4cda-b1e8-424a0939f680');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31b08d3a-5b10-46bb-844d-7c1dd7d98f8f', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is the main limitation of a flat 2D map when representing the entire spherical Earth?', 'Gauss''s Theorema Egregium: A sphere possesses positive Gaussian curvature and cannot be mapped onto a flat plane without metric distortion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a13522a1-238f-498f-a3e1-dd21747a1efd', 'A spherical surface (like an orange peel) cannot be flattened onto a flat plane without some geometric distortion of shape, area, or distance', true, '31b08d3a-5b10-46bb-844d-7c1dd7d98f8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7a577f8-4963-4c87-8ade-21827c45528e', 'Maps are too heavy to carry', false, '31b08d3a-5b10-46bb-844d-7c1dd7d98f8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a960da34-8991-418c-b17b-670fffeee58a', 'Maps cannot show colors', false, '31b08d3a-5b10-46bb-844d-7c1dd7d98f8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c406a83-721c-4837-9db0-9281a768b9a9', 'Maps erase the oceans', false, '31b08d3a-5b10-46bb-844d-7c1dd7d98f8f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44ebd474-135b-4b79-9db9-ec8db25a88a5', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'Why is a Globe more advantageous than a Map when studying the Earth as a planetary whole?', 'A globe preserves true conformal shapes, area ratios, and geodetic arcs without projection distortions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('754a8deb-5bb3-4290-996f-73ee75dcca46', 'A globe is a true, undistorted 3D three-dimensional model showing exact shapes, relative sizes, and spatial orientations of continents and oceans', true, '44ebd474-135b-4b79-9db9-ec8db25a88a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b377512f-5d2f-4194-b1b1-fe87df047cab', 'A globe can fit in a pocket easily', false, '44ebd474-135b-4b79-9db9-ec8db25a88a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d13e59d1-4ef3-4737-8810-2ebc67925b52', 'A globe shows every small street in a village', false, '44ebd474-135b-4b79-9db9-ec8db25a88a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45ff0c94-5a8d-4ed1-b672-617dc18e8999', 'A globe can be folded into a book', false, '44ebd474-135b-4b79-9db9-ec8db25a88a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('116ef35e-907c-4c44-92e2-5dda6ee9d1d0', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'If you are walking facing the rising Sun in the early morning, which directions are directly on your LEFT, RIGHT, and BACK?', 'Facing East (090° azimuth): Left is 90° counterclockwise (North), Right is 90° clockwise (South), and behind is West.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f35c9afe-5ff6-4b54-937c-0a2241628f6a', 'Left: North ; Right: South ; Back: West', true, '116ef35e-907c-4c44-92e2-5dda6ee9d1d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af1e9e33-909d-4863-b880-f6be0535b180', 'Left: South ; Right: North ; Back: West', false, '116ef35e-907c-4c44-92e2-5dda6ee9d1d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8515b136-c000-416e-97be-3c1291cd8f47', 'Left: West ; Right: North ; Back: South', false, '116ef35e-907c-4c44-92e2-5dda6ee9d1d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c66c1d83-0ced-4fc4-96ba-686795828866', 'Left: East ; Right: West ; Back: North', false, '116ef35e-907c-4c44-92e2-5dda6ee9d1d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9ab1344-35c7-4bff-9090-be8f01e4dbbb', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is the science and art of making and drawing maps called?', 'Cartography (from French carte = map, graphie = writing) is the discipline of map conception, design, and production.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('412b62d3-1abb-4ca7-a632-9db5fc4147f2', 'Cartography', true, 'f9ab1344-35c7-4bff-9090-be8f01e4dbbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d46b7eaa-7254-4ec2-ae1a-971397ec01f5', 'Calligraphy', false, 'f9ab1344-35c7-4bff-9090-be8f01e4dbbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f05b3c73-5262-42a2-9cb9-ed5a9afbf574', 'Topography', false, 'f9ab1344-35c7-4bff-9090-be8f01e4dbbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fea6a01d-421f-46c2-a1a2-32be9f291ca5', 'Geology', false, 'f9ab1344-35c7-4bff-9090-be8f01e4dbbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8708083-cd2c-41d0-a0a7-bf4d2c472bf0', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'Which type of map would a town planner or revenue officer use to show individual cadastral land ownership plots in a village?', 'Cadastral maps are very large-scale (e.g. 1:1,000 to 1:4,000) legal boundary surveys showing parcel ownership.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79c96ade-295b-4a5b-9cea-b04e9229a6be', 'A Cadastral / Large-Scale Village Plan Map', true, 'f8708083-cd2c-41d0-a0a7-bf4d2c472bf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d8d5b8a-917d-4e1d-a799-7d37508fec2c', 'A World Thematic Map', false, 'f8708083-cd2c-41d0-a0a7-bf4d2c472bf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('978c39af-5c8a-4f4e-9893-199d3f8a9133', 'A Global Physical Map', false, 'f8708083-cd2c-41d0-a0a7-bf4d2c472bf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b69ac445-0bcd-4a3a-9913-b9a598758f40', 'A Small-Scale Atlas Map', false, 'f8708083-cd2c-41d0-a0a7-bf4d2c472bf0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa4577c3-bf26-4740-b594-b874d3a3d2e7', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'How is an International Boundary conventionally depicted on standard maps?', 'International borders are designated by thick black alternating dash-dot-dash lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c76a168-5ef3-4a60-80c3-ddec520ea98b', 'A bold line of alternating dark thick dashes and dots', true, 'aa4577c3-bf26-4740-b594-b874d3a3d2e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84e92f85-4927-4a39-8fb4-3f1a97feacc8', 'A thin dotted line', false, 'aa4577c3-bf26-4740-b594-b874d3a3d2e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19e84930-da24-46f0-970c-5bbe062baa5e', 'A solid green double line', false, 'aa4577c3-bf26-4740-b594-b874d3a3d2e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03923bfd-f0db-4112-b36d-40b1f8147566', 'A wavy blue line', false, 'aa4577c3-bf26-4740-b594-b874d3a3d2e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e9d07f7-4807-47bd-8231-87f8de2e4a9d', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8334fe8-aeff-4929-8ca0-89c96e04060e', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '6e9d07f7-4807-47bd-8231-87f8de2e4a9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e7ee0d8-1dde-4236-9331-74457e6abf3a', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '6e9d07f7-4807-47bd-8231-87f8de2e4a9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('378bc399-c7b7-4174-befa-68c64d1ce0b1', '(A) is true, but (R) is false.', false, '6e9d07f7-4807-47bd-8231-87f8de2e4a9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('106396b4-6203-44b4-b0fb-daf6aa65c4ed', '(A) is false, but (R) is true.', false, '6e9d07f7-4807-47bd-8231-87f8de2e4a9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ca41215-1416-4bf3-bb5e-7ead15481705', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Spot the IMPOSTER in the following classification of maps:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6264ad10-715c-4861-8d43-2118baa6cc76', 'Physical Map', false, '6ca41215-1416-4bf3-bb5e-7ead15481705');
