INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6854e2b8-a0b9-45cf-a91e-901f1f99f175', 'Thematic Map', false, '6ca41215-1416-4bf3-bb5e-7ead15481705');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3776e14a-2f36-42ba-8bf2-190bebde446e', 'Thermometer', true, '6ca41215-1416-4bf3-bb5e-7ead15481705');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41b68a6b-be00-4fec-b1b3-592cecd79952', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'A hiker at a base camp wants to walk towards a scenic waterfall located exactly halfway between North and West. In which direction must the hiker set their compass bearing?', 'Halfway between North (000°/360°) and West (270°) is North-West (315°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a4450bd-0762-46bd-9d62-75d457a5e762', 'North-West (NW / 315° bearing)', true, '41b68a6b-be00-4fec-b1b3-592cecd79952');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b4240ca-6a4f-4da9-b45f-fd8fae8bf5c7', 'North-East (NE)', false, '41b68a6b-be00-4fec-b1b3-592cecd79952');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27f71013-7fd8-490a-93a9-f34530c6f359', 'South-West (SW)', false, '41b68a6b-be00-4fec-b1b3-592cecd79952');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('916f52e4-0b89-4d1e-9dce-70ced839c88d', 'South-East (SE)', false, '41b68a6b-be00-4fec-b1b3-592cecd79952');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb6ddd66-9c18-4d69-bf6e-897e16911bd5', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Match Column I (Map Components & Types) with Column II (Descriptions):
(a) Physical Map  -> (i) Shows distribution of rainfall or industries
(b) Political Map -> (ii) Shows relief, rivers, mountains, and plains
(c) Thematic Map  -> (iii) Shows national and state administrative boundaries
(d) Scale         -> (iv) Ratio of map distance to ground distance', 'Physical = relief/rivers; Political = boundaries; Thematic = rainfall/industries; Scale = distance ratio.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be2456d1-92c0-4a23-b752-3ab32e8a3144', 'a-(ii), b-(iii), c-(i), d-(iv)', true, 'cb6ddd66-9c18-4d69-bf6e-897e16911bd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dc658f9-8aa6-4465-a264-33f6b10e340e', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'cb6ddd66-9c18-4d69-bf6e-897e16911bd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('948716f8-94a4-4f39-9301-d3dc11c2e631', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'cb6ddd66-9c18-4d69-bf6e-897e16911bd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de0de27e-5823-4e6c-ae86-3eae01740594', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'cb6ddd66-9c18-4d69-bf6e-897e16911bd5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('835b073e-90a8-43a5-a859-184f1d4f7d75', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('775cbbe4-3dc7-4456-b1e8-bea677ab20c4', 'Statements 1 and 2 only', true, '835b073e-90a8-43a5-a859-184f1d4f7d75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14ad9850-1210-442e-b53d-2c4daaa3e202', 'Statements 2 and 3 only', false, '835b073e-90a8-43a5-a859-184f1d4f7d75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da02d346-7cb5-4d69-a8c4-02023b2bbf69', 'Statements 1 and 3 only', false, '835b073e-90a8-43a5-a859-184f1d4f7d75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be0ba09e-2e8f-4364-8b78-7f0afe8be135', 'All Statements 1, 2, and 3', false, '835b073e-90a8-43a5-a859-184f1d4f7d75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0d17185-adfd-4e67-8087-c428ad77161b', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'On a topographical sheet drawn on a scale of 1:50,000, two towns are separated by 8 cm on the map. What is the actual straight-line distance on the ground in kilometers?', '8 cm × 50,000 = 400,000 cm = 4,000 meters = 4.0 kilometers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc57a29f-ab70-4a91-83e5-bdf868edd898', '4 km (8 cm × 50,000 = 400,000 cm = 4,000 m = 4 km)', true, 'e0d17185-adfd-4e67-8087-c428ad77161b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b8aec3f-64f7-4040-8bb9-29bb9f986b00', '40 km', false, 'e0d17185-adfd-4e67-8087-c428ad77161b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7d00dd8-2645-4029-a02f-c03943fb4a75', '2 km', false, 'e0d17185-adfd-4e67-8087-c428ad77161b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b32905b-0950-45cb-b1a3-712201f3b5db', '8 km', false, 'e0d17185-adfd-4e67-8087-c428ad77161b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bab8cda5-202e-4745-9357-a5e387b6e877', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Why does the magnetic needle of a compass always align itself along the North-South direction anywhere on Earth''s surface?', 'Earth''s liquid outer core dynamo generates a global geomagnetic field that aligns magnetized dipoles with geomagnetic flux lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c5398eb-1d94-488e-9cdc-08fb7cb62341', 'The Earth itself acts as a gigantic magnet with geomagnetic poles near its geographic poles, exerting magnetic torque on the compass needle', true, 'bab8cda5-202e-4745-9357-a5e387b6e877');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5852a313-fe93-4dff-9652-a78dcc675f7f', 'Because the Sun attracts it', false, 'bab8cda5-202e-4745-9357-a5e387b6e877');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4a7f4dd-d27d-4533-abf1-d54144cf162b', 'Because wind blows from north to south', false, 'bab8cda5-202e-4745-9357-a5e387b6e877');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2a11335-b899-466f-8408-b4a429b27b65', 'Because the needle is heavy at one end', false, 'bab8cda5-202e-4745-9357-a5e387b6e877');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47437b6c-4146-4df4-986a-b9e5b70cdad9', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Which of the following represents the correct Representative Fraction (R.F.) for a map scale given as ''2 cm = 1 km''?', 'R.F. = Map Distance / Ground Distance = 2 cm / 100,000 cm = 1 : 50,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed7cf5f9-8b0c-456d-9b83-97b133655f60', '1 : 50,000 (since 1 km = 100,000 cm, so 2 / 100,000 = 1 / 50,000)', true, '47437b6c-4146-4df4-986a-b9e5b70cdad9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f7a90d2-753a-40a3-85f8-69f3ecde34a0', '1 : 100,000', false, '47437b6c-4146-4df4-986a-b9e5b70cdad9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('539468b1-16c6-4d6b-a93a-b92ce0ccaf9d', '1 : 25,000', false, '47437b6c-4146-4df4-986a-b9e5b70cdad9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d2d58b0-f413-4dcb-b7b5-b1b99c8cd625', '1 : 2,000', false, '47437b6c-4146-4df4-986a-b9e5b70cdad9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b50e8bda-1a7d-4b21-84fe-20bde33c3aab', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Consider four map scales:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aeb08ea-eaf3-4153-a48d-63f99f3d7ceb', 'Scale 1 (1 : 2,500)', true, 'b50e8bda-1a7d-4b21-84fe-20bde33c3aab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06443839-a41c-409f-91fc-b69f35846fe4', 'Scale 2', false, 'b50e8bda-1a7d-4b21-84fe-20bde33c3aab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6e81450-7b08-45cc-80cf-5c89918af71f', 'Scale 3', false, 'b50e8bda-1a7d-4b21-84fe-20bde33c3aab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c848082f-5705-46e6-98d2-ed4d8cc74cd0', 'Scale 4', false, 'b50e8bda-1a7d-4b21-84fe-20bde33c3aab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b286040-1fa4-40b1-a503-20a1f500b697', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Why is a Map generally more practical and convenient for daily travel navigation than a 3D Globe?', 'Portability, high-resolution thematic zoom, ease of plotting, and selective regional coverage make maps far superior for navigation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec26b7c3-c58e-4c51-9f95-57847471ddd7', 'Maps are portable, can be folded, can focus on a specific small locality (city/road), and provide high-density localized data on a flat surface', true, '1b286040-1fa4-40b1-a503-20a1f500b697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4dbc8c1-00ab-4a1a-900d-439dda72a7d2', 'Globes are always inaccurate', false, '1b286040-1fa4-40b1-a503-20a1f500b697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3a0e7c5-db75-4d4f-a827-cb8ff6af0e4a', 'Maps are made of gold', false, '1b286040-1fa4-40b1-a503-20a1f500b697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5d9be57-f42b-4856-a907-012f91733e67', 'Globes cannot show oceans', false, '1b286040-1fa4-40b1-a503-20a1f500b697');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed040f5c-b113-4b69-a7c6-be8b683fe5c3', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'What is the conventional color used on topographical maps to show agricultural cultivable farmland?', 'On Survey of India topographic sheets, yellow wash denotes cultivated agricultural land, while green denotes forest/woodland cover.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88ff90d2-5bb0-4f03-a1ce-466f67dbf555', 'Yellow color', true, 'ed040f5c-b113-4b69-a7c6-be8b683fe5c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8fca199-6d57-49d3-a977-2a1c5d153fd6', 'Green color', false, 'ed040f5c-b113-4b69-a7c6-be8b683fe5c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f28ffa36-2bd1-4062-9876-96d312f6eb78', 'Brown color', false, 'ed040f5c-b113-4b69-a7c6-be8b683fe5c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e12b119-a50e-4b23-a1f4-3827c90c92b7', 'Red color', false, 'ed040f5c-b113-4b69-a7c6-be8b683fe5c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db54f48b-af65-496f-abcf-3bcd1f8467ae', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'If a village church is located to the South-East (SE) of a school, in which direction is the school located relative to the church?', 'The diametrically opposite direction of South-East (135°) is North-West (315°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af2a058b-1e4d-476f-a28c-81b90f9ce228', 'North-West (NW)', true, 'db54f48b-af65-496f-abcf-3bcd1f8467ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50cc3582-3ff1-4d8c-9c38-81d66bb11bf6', 'North-East (NE)', false, 'db54f48b-af65-496f-abcf-3bcd1f8467ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f140d50-383d-43f1-a44e-7760d5c53c87', 'South-West (SW)', false, 'db54f48b-af65-496f-abcf-3bcd1f8467ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05e350f4-d3c8-49fb-ac74-aa42173d1ab6', 'South-East (SE)', false, 'db54f48b-af65-496f-abcf-3bcd1f8467ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e22689a-280c-48ba-b58a-cc73d8a15a85', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'किसी व्यक्ति, वस्तु, स्थान, प्राणी या भाव के नाम का बोध कराने वाले शब्द को क्या कहते हैं?', 'संसार के किसी भी नाम (व्यक्ति, वस्तु, स्थान, जाति अथवा भाव) को व्याकरण में ''संज्ञा'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c3a7b01-85c0-442e-9ee7-60c2a55bd5ff', 'संज्ञा (Noun)', true, '2e22689a-280c-48ba-b58a-cc73d8a15a85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecd75785-6b09-4f2d-b1f7-aa1667cc6a4a', 'सर्वनाम', false, '2e22689a-280c-48ba-b58a-cc73d8a15a85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b6d0ece-7fd1-46ce-aff6-6814e2be7430', 'विशेषण', false, '2e22689a-280c-48ba-b58a-cc73d8a15a85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72802906-1383-456b-9a72-7a6bfd638933', 'क्रिया', false, '2e22689a-280c-48ba-b58a-cc73d8a15a85');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc48a423-ee92-4038-84dc-e35fdd760a03', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'हिंदी व्याकरण में मुख्य रूप से संज्ञा के कितने भेद (प्रकार) माने जाते हैं?', 'संज्ञा के 3 मुख्य भेद हैं: व्यक्तिवाचक, जातिवाचक, तथा भाववाचक (जातिवाचक के अंतर्गत द्रव्यवाचक व समूहवाचक आते हैं)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5198847-33fe-4c25-beee-7450d816e49d', 'तीन मुख्य भेद (व्यक्तिवाचक, जातिवाचक, भाववाचक)', true, 'fc48a423-ee92-4038-84dc-e35fdd760a03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6840c874-5da4-4d97-b780-6a1c4b060c8b', 'दो भेद', false, 'fc48a423-ee92-4038-84dc-e35fdd760a03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2d8c50b-afef-4e8d-8df6-9bb6683c0dcc', 'चार भेद', false, 'fc48a423-ee92-4038-84dc-e35fdd760a03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c533e481-8a89-45ca-994d-e27dde8f9448', 'छह भेद', false, 'fc48a423-ee92-4038-84dc-e35fdd760a03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05a51f42-a765-4ccb-8804-ce0d22492111', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'जिस संज्ञा शब्द से किसी एक विशेष व्यक्ति, विशेष स्थान या विशेष वस्तु का बोध हो, उसे क्या कहते हैं?', 'विशिष्ट इकाई/नाम का बोध कराने वाले शब्द व्यक्तिवाचक संज्ञा कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bdb5a50-fb9f-4e33-aa95-89b25854af71', 'व्यक्तिवाचक संज्ञा (Proper Noun - जैसे: राम, दिल्ली, हिमालय, गंगा, ताजमहल)', true, '05a51f42-a765-4ccb-8804-ce0d22492111');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('032cb7f1-bf40-4379-98fa-00fa201e10c3', 'जातिवाचक संज्ञा', false, '05a51f42-a765-4ccb-8804-ce0d22492111');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33968131-84dd-4e31-91e5-ab8660c1e44b', 'भाववाचक संज्ञा', false, '05a51f42-a765-4ccb-8804-ce0d22492111');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b102c5d5-3623-4de8-98fa-a6180c93a0c3', 'द्रव्यवाचक संज्ञा', false, '05a51f42-a765-4ccb-8804-ce0d22492111');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d30dcef4-b701-4c40-80b5-4394d63ec85f', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'जिस संज्ञा शब्द से किसी संपूर्ण जाति, वर्ग या श्रेणी के सभी प्राणियों, वस्तुओं या स्थानों का बोध हो, उसे क्या कहते हैं?', 'संपूर्ण प्रजाति/वर्ग का सामान्य बोध कराने वाले शब्द जातिवाचक संज्ञा कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbb0487c-4f8c-49f0-84f7-aadbb00ceb02', 'जातिवाचक संज्ञा (Common Noun - जैसे: लड़का, नदी, पर्वत, नगर, पुस्तक)', true, 'd30dcef4-b701-4c40-80b5-4394d63ec85f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5459524e-256e-4f19-9536-107195d22561', 'व्यक्तिवाचक संज्ञा', false, 'd30dcef4-b701-4c40-80b5-4394d63ec85f');
