INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79dcc45a-097b-4a32-8762-6f372cb8e11c', 'समूहवाचक संज्ञा', false, 'd30dcef4-b701-4c40-80b5-4394d63ec85f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('791576f1-1395-4af0-a5e4-03b9672b2f17', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'जिन शब्दों से किसी व्यक्ति या वस्तु के गुण, दोष, दशा, अवस्था, मन के भाव या स्वभाव का बोध हो, उन्हें क्या कहते हैं?', 'अमूर्त भाव, गुण, दशा या अवस्था का बोध कराने वाले शब्द भाववाचक संज्ञा कहलाते हैं (इन्हें छुआ नहीं, केवल अनुभव किया जाता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('132bab75-13a3-406e-8cbd-997de07c8733', 'भाववाचक संज्ञा (Abstract Noun - जैसे: मिठास, बचपन, ईमानदारी, बुढ़ापा, क्रोध)', true, '791576f1-1395-4af0-a5e4-03b9672b2f17');
