INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('550df872-425e-4197-87db-ccf4ef411482', 'द्रव्यवाचक संज्ञा', false, '791576f1-1395-4af0-a5e4-03b9672b2f17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13587c56-6c5a-4bef-ad3d-761f8e88d680', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'वे संज्ञा शब्द जिनसे किसी धातु, तरल, ठोस या द्रव्य (पदार्थ) का बोध होता है जिसे नापा या तौला जा सके, उन्हें क्या कहते हैं?', 'मात्रात्मक एवं परिमाप्य पदार्थों का बोध कराने वाले शब्द द्रव्यवाचक संज्ञा कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ce513df-bd71-42a1-bc67-1e5d7eded492', 'द्रव्यवाचक संज्ञा (Material Noun - जैसे: सोना, चाँदी, दूध, पानी, गेहूँ, तेल)', true, '13587c56-6c5a-4bef-ad3d-761f8e88d680');
