INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12d0fd56-418d-4f2a-b408-b4f6f9ab367e', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'वे संज्ञा शब्द जिनसे किसी समूह, दल, सभा, भीड़ या समुदाय का बोध होता है, उन्हें क्या कहते हैं?', 'अनेक प्राणियों या वस्तुओं के समूह का संयुक्त बोध कराने वाले शब्द समूहवाचक संज्ञा कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b5a3e4b-aead-47e6-a725-2bdeee9e8a06', 'समूहवाचक या समुदायवाचक संज्ञा (Collective Noun - जैसे: सेना, कक्षा, भीड़, परिवार, गुच्छा)', true, '12d0fd56-418d-4f2a-b408-b4f6f9ab367e');
