INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c336316-6fdf-4428-9022-54236f494352', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'निम्नलिखित में से ''व्यक्तिवाचक संज्ञा'' का सही उदाहरण कौन-सा है?', 'भारत (देश विशेष), हिमालय (पर्वत विशेष), गांधी (व्यक्ति विशेष), रामायण (ग्रंथ विशेष) सभी व्यक्तिवाचक संज्ञाएँ हैं।', NOW()) ON CONFLICT DO NOTHING;
