INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a9782e0-fdbd-4f36-a012-a73567a5c478', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'निम्नलिखित में से ''जातिवाचक संज्ञा'' का सही उदाहरण कौन-सा है?', 'पक्षी, गाँव, बालक, फल अपनी पूरी जाति और श्रेणी का प्रतिनिधित्व करते हैं।', NOW()) ON CONFLICT DO NOTHING;
