INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aca40b6a-9567-481a-ac0c-92298d22573d', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'विशेषण शब्द ''मीठा'' से बनने वाली सही ''भाववाचक संज्ञा'' कौन-सी है?', '''मीठा'' गुणवाचक विशेषण में ''आस'' प्रत्यय जुड़ने से भाववाचक संज्ञा ''मिठास'' बनती है।', NOW()) ON CONFLICT DO NOTHING;
