INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('695a7700-cfbc-40c4-a89f-7100bc041801', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'जातिवाचक संज्ञा ''मानव'', ''मित्र'' और ''पशु'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'मानव + ता = मानवता; मित्र + ता = मित्रता; पशु + ता = पशुता (सभी शुद्ध भाववाचक संज्ञाएँ हैं)।', NOW()) ON CONFLICT DO NOTHING;
