INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b69e3b7c-fa3e-4c25-9901-9b61855f53f5', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'सर्वनाम शब्द ''अपना'', ''मम'' और ''निज'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'सर्वनामों में ''पन'', ''ता'', ''त्व'' प्रत्यय लगाने से भाववाचक संज्ञा बनती है: अपनापन, ममता/ममत्व, निजत्व।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f5b27bd-3a26-4f17-a5c1-ededd7642b5d', 'अपनापन (या अपनत्व), ममता (या ममत्व), निजत्व', true, 'b69e3b7c-fa3e-4c25-9901-9b61855f53f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f19445a7-7ef4-41ac-bd09-d1bb8de90665', 'अपने, मेरा, खुद', false, 'b69e3b7c-fa3e-4c25-9901-9b61855f53f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02b2719c-042c-4072-9207-f3d54c6ad65e', 'आपसी, व्यक्तिगत', false, 'b69e3b7c-fa3e-4c25-9901-9b61855f53f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f536a71-1a60-4033-8b4f-0443500a04ac', 'अपनाने, मेरापन', false, 'b69e3b7c-fa3e-4c25-9901-9b61855f53f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eebe9b3f-e6c0-4ab1-b17a-5c90c136b589', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'क्रिया शब्द ''पढ़ना'', ''हँसना'' और ''सजाना'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'क्रिया के धातु रूप में प्रत्यय लगने से भाववाचक संज्ञाएँ बनती हैं: पढ़ना -> पढ़ाई; हँसना -> हँसी; सजाना -> सजावट।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63082527-9c9f-492b-b680-e394cc29c359', 'पढ़ाई, हँसी, सजावट', true, 'eebe9b3f-e6c0-4ab1-b17a-5c90c136b589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b77ebea0-1749-4bd3-b808-052c53946d05', 'पढ़ाकू, हँसोड़, सजानेवाला', false, 'eebe9b3f-e6c0-4ab1-b17a-5c90c136b589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b649a87-483f-4c0c-a92e-d4109905c0c5', 'पठन, हँसमुख, साज', false, 'eebe9b3f-e6c0-4ab1-b17a-5c90c136b589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92d6b2b6-3227-4658-92fd-0dde422eaab0', 'पढ़कर, हँसकर, सजाकर', false, 'eebe9b3f-e6c0-4ab1-b17a-5c90c136b589');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b5423c7-b371-49bc-95a5-8e222537584f', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'विशेषण शब्द ''सुंदर'', ''वीर'' और ''सफल'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'सुंदर + ता = सुंदरता; वीर + ता = वीरता; सफल + ता = सफलता।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaca4225-eabb-46de-8c1c-1142adee35f3', 'सुंदरता (या सौंदर्य), वीरता, सफलता', true, '9b5423c7-b371-49bc-95a5-8e222537584f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2df53a9-7e04-4f6d-bed9-13ab384494e1', 'सुंदरी, वीरवर, सफलकारी', false, '9b5423c7-b371-49bc-95a5-8e222537584f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a6c1fc3-5a14-400b-8a59-ff1105694339', 'सुहावना, साहसी, फल', false, '9b5423c7-b371-49bc-95a5-8e222537584f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('917edeea-1d0a-44b3-b3b8-af34e2b76cd5', 'खूबसूरत, बहादुर, कामयाब', false, '9b5423c7-b371-49bc-95a5-8e222537584f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7c872eb-4138-49ed-971c-114fe3870e9b', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'अव्यय शब्द ''दूर'', ''समीप'' और ''मना'' से बनने वाली भाववाचक संज्ञाएँ कौन-सी हैं?', 'अव्यय से निर्मित भाववाचक संज्ञाएँ: दूर -> दूरी; समीप -> समीपता/सामीप्य; मना -> मनाही।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bb3b74c-e0f6-42f1-932d-7dd505b46511', 'दूरी, समीपता (सामीप्य), मनाही', true, 'd7c872eb-4138-49ed-971c-114fe3870e9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2c34006-ef46-4812-8068-da53e2eeeb5b', 'दूरबीन, समीपवर्ती, मनाना', false, 'd7c872eb-4138-49ed-971c-114fe3870e9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f125cf52-867e-45a1-8bd8-9c0bafcfae88', 'दूर-दूर, पास, ना', false, 'd7c872eb-4138-49ed-971c-114fe3870e9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c45c475e-52c9-4425-8025-1ee4600a6adf', 'दूरस्थ, निकटता, इनकार', false, 'd7c872eb-4138-49ed-971c-114fe3870e9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84e46fff-b3b6-4470-bb6a-c411ce3ef01f', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'जब कोई व्यक्तिवाचक संज्ञा किसी व्यक्ति विशेष के नाम के रूप में न आकर उसके विशेष गुणों के कारण पूरी जाति का बोध कराती है (जैसे: ''हमारे देश में जयचंदों की कमी नहीं है''), तो वह क्या बन जाती है?', 'व्यक्तिवाचक संज्ञा जब बहुवचन में प्रयुक्त होकर किसी लाक्षणिक वर्ग (गद्दारों/दानवीरों) को दर्शाए, तो वह जातिवाचक बन जाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ad1b91f-3e16-42c3-bc1b-e00486ae11e1', 'जातिवाचक संज्ञा (विश्वासघातियों की संपूर्ण श्रेणी)', true, '84e46fff-b3b6-4470-bb6a-c411ce3ef01f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73a9ed55-5c56-45fa-bba7-98cd7eda35b2', 'भाववाचक संज्ञा', false, '84e46fff-b3b6-4470-bb6a-c411ce3ef01f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32b15084-7604-4761-9a83-8a73f9c89ee4', 'द्रव्यवाचक संज्ञा', false, '84e46fff-b3b6-4470-bb6a-c411ce3ef01f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef0a0f77-690e-4050-bfef-5c47f03e74b9', 'समूहवाचक संज्ञा', false, '84e46fff-b3b6-4470-bb6a-c411ce3ef01f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13e68d0e-878a-43bc-9adc-03d3128f3abc', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'जब कोई जातिवाचक संज्ञा किसी विशेष रूढ़ व्यक्ति के लिए निश्चित हो जाती है (जैसे: ''पंडित जी भारत के प्रथम प्रधानमंत्री थे'' या ''नेता जी ने आज़ाद हिंद फ़ौज बनाई''), तो वह क्या बन जाती है?', 'जातिवाचक पद जब किसी सुप्रसिद्ध व्यक्ति विशेष के लिए रूढ़ होकर प्रयुक्त हो, तो वह व्यक्तिवाचक संज्ञा बन जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86665849-ae93-4cb8-8499-e6178b8e3929', 'व्यक्तिवाचक संज्ञा (पंडित जी = जवाहरलाल नेहरू ; नेता जी = सुभाष चंद्र बोस)', true, '13e68d0e-878a-43bc-9adc-03d3128f3abc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b741dc41-054f-4bcd-b0bd-d80134cb8d50', 'भाववाचक संज्ञा', false, '13e68d0e-878a-43bc-9adc-03d3128f3abc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edce8d3b-ac72-4b14-856f-816bdbe99536', 'समूहवाचक संज्ञा', false, '13e68d0e-878a-43bc-9adc-03d3128f3abc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38726972-58d6-46cf-a7a1-d7d6e8ef1f1b', 'द्रव्यवाचक संज्ञा', false, '13e68d0e-878a-43bc-9adc-03d3128f3abc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1077cb01-2938-4021-b251-b87b06a39d8a', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'भाववाचक संज्ञाओं का प्रयोग सामान्यतः किस वचन में होता है?', 'अमूर्त भाववाचक संज्ञाएँ सदा एकवचन में रहती हैं; बहुवचन बनते ही वे जातिवाचक संज्ञा में परिवर्तित हो जाती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e141cf99-aaba-483a-a22d-d031905ee52f', 'सदैव एकवचन में (जब भाववाचक संज्ञा बहुवचन में प्रयुक्त होती है, जैसे ''दूरियाँ, बुराइयाँ'', तो वह जातिवाचक बन जाती है)', true, '1077cb01-2938-4021-b251-b87b06a39d8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7266fd8e-1213-457b-8734-1ad7671ee2b8', 'सदैव बहुवचन में', false, '1077cb01-2938-4021-b251-b87b06a39d8a');
