INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('912eef09-0ca6-4e21-94c4-8a698bc58f7e', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''समूहवाचक संज्ञा'' का सही समूह है?', 'संसद, मेला, जुलूस, दल, झुंड सभी व्यक्तियों या जीवों के एकत्र समुदाय का बोध कराते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ce47dc0-75cc-4bf1-9cb7-e1363ac05020', 'संसद, मेला, जुलूस, दल, झुंड', true, '912eef09-0ca6-4e21-94c4-8a698bc58f7e');
