INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a340292-83b4-4544-ab36-01bd326ad28d', 'गंगा, हिमालय, दिल्ली', false, '912eef09-0ca6-4e21-94c4-8a698bc58f7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b17f23a-5f70-4936-8063-1ed952463435', 'बचपन, बुढ़ापा, जवानी', false, '912eef09-0ca6-4e21-94c4-8a698bc58f7e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79291549-28c7-44ca-a59c-16122f11f5e2', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''द्रव्यवाचक संज्ञा'' का सही समूह है?', 'ताँबा, पीतल, पेट्रोल, कोयला, घी सभी द्रव्यमान और रासायनिक धातु/तरल पदार्थ हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66c96292-2daf-4c3d-8b20-d9873f7f32b5', 'ताँबा, पीतल, पेट्रोल, कोयला, घी', true, '79291549-28c7-44ca-a59c-16122f11f5e2');
