INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4488672-4cb3-4412-97a3-610146a094ea', 'रामायण, ताजमहल, कुरान', false, '79291549-28c7-44ca-a59c-16122f11f5e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a391d4fa-1e68-43f6-951f-67bf3f7a8a8a', 'ईमानदारी, चालाकी, क्रोध', false, '79291549-28c7-44ca-a59c-16122f11f5e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe6e24f3-a715-4d80-a22e-527101f1bfec', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'जातिवाचक संज्ञा ''पंडित'' से बनने वाली सही भाववाचक संज्ञा कौन-सी है?', '''पंडित'' से ''पांडित्य'' (संस्कृत प्रत्यय य) तथा ''पंडिताई'' (आई प्रत्यय) दोनों मानक भाववाचक संज्ञाएँ बनती हैं।', NOW()) ON CONFLICT DO NOTHING;
