INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fcca29f-7bc0-443c-b0fe-a9a5759f5ea0', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'विशेषण शब्द ''गर्म'' और ''ठंडा'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'गर्म से ''गर्मी'' / ''गर्माहट'' तथा ठंडा से ''ठंडक'' / ''ठंड'' मानक भाववाचक संज्ञाएँ बनती हैं।', NOW()) ON CONFLICT DO NOTHING;
