INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9edb0d41-214d-44d1-8446-5e84d0677294', 'गर्माहट और शीत', false, '7fcca29f-7bc0-443c-b0fe-a9a5759f5ea0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb697f15-5038-4f80-88cb-8f19cb41a389', 'दोनों ''गर्मी और ठंडक'' सही हैं', true, '7fcca29f-7bc0-443c-b0fe-a9a5759f5ea0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3825c4b-f4d9-4e4b-ba8d-f65f0e1176bb', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62f9346a-7ee0-4a5b-8975-5c08dd1f438c', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'b3825c4b-f4d9-4e4b-ba8d-f65f0e1176bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('568eb93d-8fe2-462d-8f11-cb7173172034', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'b3825c4b-f4d9-4e4b-ba8d-f65f0e1176bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('302e6e24-8dbd-44a4-9990-f4cdaa5d3295', '(A) सही है, परन्तु (R) गलत है।', false, 'b3825c4b-f4d9-4e4b-ba8d-f65f0e1176bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b69df82d-1dcf-492c-ad18-13b0ee05d042', '(A) गलत है, परन्तु (R) सही है।', false, 'b3825c4b-f4d9-4e4b-ba8d-f65f0e1176bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98489dda-01a9-40fa-8b71-70dc9f1f83cb', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'Spot the IMPOSTER in the following group of भाववाचक संज्ञा शब्दों के आधार पर:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f4a8fb8-7f5c-43cd-8f6a-5855f7e2f728', 'मिठास', false, '98489dda-01a9-40fa-8b71-70dc9f1f83cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('085af89e-cd45-4954-887b-5d7ef66b2a1c', 'सुंदरता', false, '98489dda-01a9-40fa-8b71-70dc9f1f83cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3729c96-da90-45f4-96d5-0233f7648807', 'बचपन', false, '98489dda-01a9-40fa-8b71-70dc9f1f83cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('589e2f87-a58c-4634-a2e5-2524deb54d2f', 'हिमालय', true, '98489dda-01a9-40fa-8b71-70dc9f1f83cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4c9efd2-352a-48c1-9f10-139d90252aa6', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'सुमेलित कीजिए (शब्द और उनकी भाववाचक संज्ञा):
(क) बूढ़ा    -> (i) लड़कपन
(ख) लड़का   -> (ii) मोटापा
(ग) मोटा    -> (iii) बुढ़ापा
(घ) चढ़ना   -> (iv) चढ़ाई', 'बूढ़ा = बुढ़ापा; लड़का = लड़कपन; मोटा = मोटापा; चढ़ना = चढ़ाई।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d7cfac1-b250-44c7-87c2-bfe102cef740', 'क-(iii), ख-(i), ग-(ii), घ-(iv)', true, 'b4c9efd2-352a-48c1-9f10-139d90252aa6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68a58fa9-a609-4804-98b3-7adfff3cbdbf', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, 'b4c9efd2-352a-48c1-9f10-139d90252aa6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35e51e22-ca60-440f-9ad8-3b26a2ba22bc', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'b4c9efd2-352a-48c1-9f10-139d90252aa6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8b34df3-c80b-46b0-84f9-ceb39f054263', 'क-(ii), ख-(iv), ग-(i), घ-(iii)', false, 'b4c9efd2-352a-48c1-9f10-139d90252aa6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da11472f-4995-47f9-b5b4-128eccd24649', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'भाववाचक संज्ञाओं की रचना मुख्यतः कितने प्रकार के शब्दों से की जाती है?', 'व्याकरणिक नियमानुसार भाववाचक संज्ञा पाँच स्रोतों से व्युत्पन्न होती है: जातिवाचक संज्ञा, सर्वनाम, विशेषण, क्रिया, तथा अव्यय।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df797c03-4d82-4890-a577-4867ee3fba08', 'पाँच प्रकार के शब्दों से: 1. जातिवाचक संज्ञा से, 2. सर्वनाम से, 3. विशेषण से, 4. क्रिया से, 5. अव्यय से', true, 'da11472f-4995-47f9-b5b4-128eccd24649');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0d6b024-6f39-4083-9064-62fb999164d3', 'केवल दो प्रकार से', false, 'da11472f-4995-47f9-b5b4-128eccd24649');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('006c77f7-d1c0-486a-8b50-080cc054a53f', 'केवल तीन प्रकार से', false, 'da11472f-4995-47f9-b5b4-128eccd24649');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ad2306a-8d1b-4c1d-87f4-9cb7697e25cd', 'चार प्रकार से', false, 'da11472f-4995-47f9-b5b4-128eccd24649');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25e128bd-accc-4d0f-9ac3-9f14759f5491', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'निम्नलिखित वाक्यों पर विचार कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a74b1d1-5422-4aef-b1bd-b2a6401b290f', 'सभी वाक्य 1, 2 और 3 सत्य हैं', true, '25e128bd-accc-4d0f-9ac3-9f14759f5491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b21230f-99e2-486f-8912-84086666aa59', 'वाक्य 1 और 2 केवल', false, '25e128bd-accc-4d0f-9ac3-9f14759f5491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18eb6ee1-3998-4015-aae0-2e80e524130e', 'वाक्य 2 और 3 केवल', false, '25e128bd-accc-4d0f-9ac3-9f14759f5491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cabcb928-be9f-4262-bbe7-960e9c51aeb2', 'वाक्य 1 और 3 केवल', false, '25e128bd-accc-4d0f-9ac3-9f14759f5491');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b98d0e2-4c66-4ed4-b53d-d61acd25d8d5', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'वाक्य में प्रयुक्त पद ''शाबाशी'' और ''वाहवाही'' व्याकरण की दृष्टि से किस कोटि की संज्ञाएँ हैं?', 'विस्मयादिबोधक अव्यय ''शाबाश'' और ''वाह-वाह'' में ''ई'' प्रत्यय जुड़ने से अमूर्त भाववाचक संज्ञाएँ निर्मित होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('700b8c8d-4bd2-42b5-ad4b-b599ed4f2591', 'विस्मयादिबोधक अव्यय से बनी भाववाचक संज्ञाएँ (शाबाश -> शाबाशी ; वाह-वाह -> वाहवाही)', true, '4b98d0e2-4c66-4ed4-b53d-d61acd25d8d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2a20ff8-a4b7-4f14-9c3f-f928294bc5d4', 'द्रव्यवाचक संज्ञाएँ', false, '4b98d0e2-4c66-4ed4-b53d-d61acd25d8d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('715caf08-9b50-4dcc-a913-8246c8c50bff', 'व्यक्तिवाचक संज्ञाएँ', false, '4b98d0e2-4c66-4ed4-b53d-d61acd25d8d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65c89279-bc64-4cb3-9585-59e945354c6c', 'समूहवाचक संज्ञाएँ', false, '4b98d0e2-4c66-4ed4-b53d-d61acd25d8d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6d81f6a-0994-4f18-aaa0-f7ace763bb20', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'जातिवाचक संज्ञा ''चोर'', ''ठग'' और ''शिशु'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'चोर -> चोरी; ठग -> ठगी; शिशु -> शैशव/शिशुता मानक व्याकरणिक भाववाचक संज्ञाएँ हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1afd3daa-9df7-4b2f-8477-c6840779160a', 'चोरी, ठगी, शैशव (या शिशुता)', true, 'c6d81f6a-0994-4f18-aaa0-f7ace763bb20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('add9a099-420a-4dfd-b81c-c02e177d7477', 'चोरपन, ठगपन, शिशुपन', false, 'c6d81f6a-0994-4f18-aaa0-f7ace763bb20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aede7698-fb45-4dbc-804e-b12a811fcbce', 'चोरना, ठगना, छोटा', false, 'c6d81f6a-0994-4f18-aaa0-f7ace763bb20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56d9f7a3-3df6-4b3e-8ded-c9547671a00a', 'डकैती, बेईमानी, बालक', false, 'c6d81f6a-0994-4f18-aaa0-f7ace763bb20');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e38a7230-12e8-4730-a745-66605c641052', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'सर्वनाम ''सर्व'' और ''अहं'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', '''सर्व'' में ''स्व'' प्रत्यय से ''सर्वस्व'' तथा ''अहं'' (मैं) में ''कार'' प्रत्यय से ''अहंकार'' भाववाचक संज्ञा बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e4c6181-d749-47b6-a265-83c1c5b467e2', 'सर्वस्व और अहंकार', true, 'e38a7230-12e8-4730-a745-66605c641052');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8cdd7ac-0512-4479-83ed-ea0ef3b45de6', 'सबकुछ और घमंड', false, 'e38a7230-12e8-4730-a745-66605c641052');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a586d248-6221-492c-b68b-53aabc55202b', 'सभी और मैं', false, 'e38a7230-12e8-4730-a745-66605c641052');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('294782cc-ea9b-4acd-97b1-b40c7eca2c55', 'सर्वत्र और अभिमान', false, 'e38a7230-12e8-4730-a745-66605c641052');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2935e0e-b126-4d99-a80e-8f96b8b0322f', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'विशेषण ''चतुर'', ''आलसी'' और ''कायर'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'चतुर -> चतुराई/चतुरता; आलसी -> आलस्य; कायर -> कायरता।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('859e23fa-3c1e-4a44-a3c4-6c3525db10f6', 'चतुराई, आलस्य (या आलस), कायरता', true, 'e2935e0e-b126-4d99-a80e-8f96b8b0322f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d28a3f5c-72f5-4ea7-b1aa-e8567bb9d052', 'चालाक, सुस्त, डरपोक', false, 'e2935e0e-b126-4d99-a80e-8f96b8b0322f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbd0a497-771c-4242-a2ae-85acb805f194', 'चतुरपन, आलसीपन, कायरपन', false, 'e2935e0e-b126-4d99-a80e-8f96b8b0322f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ef5f0c4-1107-4c6d-8ef5-30c68183276b', 'चतुरता, नींद, भागना', false, 'e2935e0e-b126-4d99-a80e-8f96b8b0322f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('421e433c-3ad6-4d3d-9a2c-203e41e229a7', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'क्रिया ''घबराना'', ''थकना'' और ''बहाव'' (बहना) से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'घबराना + आहट = घबराहट; थकना + आवट = थकावट/थकान; बहना + आव = बहाव।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('625fb866-7682-4ce7-9040-25cb60c1c139', 'घबराहट, थकावट (थकान), बहाव', true, '421e433c-3ad6-4d3d-9a2c-203e41e229a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bc8e8b1-50c4-4910-a908-8e9c75f297fb', 'घबराया, थका, बहता', false, '421e433c-3ad6-4d3d-9a2c-203e41e229a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dbd8b12-d91f-4ef4-bf12-97de52d76d78', 'घबराहटपन, थकनी, बाढ़', false, '421e433c-3ad6-4d3d-9a2c-203e41e229a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed920c03-60fd-4d50-820b-05dff13f68f7', 'डर, सुस्ती, पानी', false, '421e433c-3ad6-4d3d-9a2c-203e41e229a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b58be36-7679-4246-b1c2-1d1a93eebb90', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'अंग्रेज़ी व्याकरण के प्रभाव से आधुनिक हिंदी में स्वीकृत ''द्रव्यवाचक'' और ''समूहवाचक'' संज्ञाओं को पारंपरिक रूप से किस मुख्य भेद का उपभेद माना जाता है?', 'पारंपरिक हिंदी व्याकरण में द्रव्यवाचक (Material) और समूहवाचक (Collective) दोनों को जातिवाचक संज्ञा का ही विस्तार माना जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9760c8e9-8399-4305-a2dc-a34a7052b262', 'जातिवाचक संज्ञा के अंतर्गत', true, '1b58be36-7679-4246-b1c2-1d1a93eebb90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48161e99-2e4b-4157-b77a-38259190c21c', 'व्यक्तिवाचक संज्ञा के अंतर्गत', false, '1b58be36-7679-4246-b1c2-1d1a93eebb90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b753fbc-6dfd-4652-9f4c-e494912ba6ca', 'भाववाचक संज्ञा के अंतर्गत', false, '1b58be36-7679-4246-b1c2-1d1a93eebb90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a43bec91-7408-4f31-98fa-bbc6c79176b2', 'सर्वनाम के अंतर्गत', false, '1b58be36-7679-4246-b1c2-1d1a93eebb90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96df2534-fede-4829-826d-11ba41da13e0', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'वाक्य में रेखांकित पदों के संज्ञा भेदों का सही क्रम चुनिए:
