INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ca3f1c0-6e0c-49c4-bf90-258e461bb1aa', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The hard, internal bony framework that supports, gives shape, and protects the internal organs of the human body is called the:', 'The human skeleton consists of 206 bones in adults, providing mechanical structure, protection, and levers for movement.', NOW()) ON CONFLICT DO NOTHING;
