INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0376d45-f820-4c9e-9b61-088add5c839e', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The anatomical place or point where two or more bones meet and join together is called a:', 'Joints are structural articulations between bones allowing varying degrees of flexibility and bodily movement.', NOW()) ON CONFLICT DO NOTHING;
