INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4eced924-1aca-409b-b20f-003636af88bf', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'Which type of movable joint allows complete rotational movement in ALL directions (360°), found at the shoulder and hip?', 'The spherical head of one bone fits into the cup-like cavity of another, enabling multi-axial 360° rotatory movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a9e61b0-5260-4c4c-8e89-15dd832a1015', 'Ball and Socket Joint', true, '4eced924-1aca-409b-b20f-003636af88bf');
