INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('649e2fa3-da7a-452f-bc47-e5f39de6dcff', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'Which type of joint allows movement in only ONE single plane (back and forth like a door hinge), found at the elbow and knee?', 'Hinge joints permit angular flexion and extension along a single transverse axis, resembling a door hinge.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('114f42bb-5f41-41c2-a1db-3e21345090d6', 'Hinge Joint', true, '649e2fa3-da7a-452f-bc47-e5f39de6dcff');
