INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8617e946-bb5f-4001-9d04-315024cf8ed8', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The joint where our neck joins the head, allowing us to bend our head forward/backward and turn it to the right/left, is a:', 'The atlanto-axial pivotal joint allows a cylindrical bone to rotate within a ring formed by bone and ligament.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97f3ffe3-197c-4fa9-a4fd-85a2c24213aa', 'Pivotal Joint (Pivot Joint)', true, '8617e946-bb5f-4001-9d04-315024cf8ed8');
