INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10dd5d71-0e65-4467-a232-de188235be3f', 'Fixed Joint', false, '8617e946-bb5f-4001-9d04-315024cf8ed8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cec1dfa5-e062-4e6b-9ed3-dc02fa0fccca', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The bones in our head (cranium/skull) that are fused together tightly and CANNOT move at all are examples of:', 'Cranial skull bones are united by fibrous immovable suture joints to shield the delicate brain from injury.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42aeaa06-f473-4cf8-9386-fca4c9326849', 'Fixed Joints (Immovable Joints / Sutures)', true, 'cec1dfa5-e062-4e6b-9ed3-dc02fa0fccca');
