INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d761cc48-f46f-43e5-a178-b96dd996167d', 'Gliding Joints', false, 'cec1dfa5-e062-4e6b-9ed3-dc02fa0fccca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('efed08a6-0da8-4521-9442-7a98b108a823', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'Which is the ONLY movable bone in the human skull, enabling us to chew food and speak?', 'The mandible articulates via the temporomandibular joint, making it the skull''s only dynamic movable bone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcfdfdf1-3551-497c-805b-18b3d3e52698', 'Lower Jaw bone (Mandible)', true, 'efed08a6-0da8-4521-9442-7a98b108a823');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18169a5d-c19e-4a94-816f-507a8b7dee59', 'Upper Jaw bone (Maxilla)', false, 'efed08a6-0da8-4521-9442-7a98b108a823');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c40fba16-781c-458d-88a0-6c53382e0ed3', 'Nasal bone', false, 'efed08a6-0da8-4521-9442-7a98b108a823');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('390f2ce5-d135-4c60-bc2c-0d38d610ba63', 'Forehead bone (Frontal)', false, 'efed08a6-0da8-4521-9442-7a98b108a823');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68bd7665-9a0f-4a44-92a7-59f8c2dab4b7', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The curved bones that join the chest bone (sternum) and the backbone together to form a protective cage around the heart and lungs are called:', '12 pairs of curved ribs form the thoracic cage, shielding the heart, lungs, and major blood vessels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdd59ba0-7c46-4397-b29c-73f98e15f58e', 'Ribs (forming the Rib Cage)', true, '68bd7665-9a0f-4a44-92a7-59f8c2dab4b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c20e471-e257-46d7-981d-03d16983e3d2', 'Vertebrae', false, '68bd7665-9a0f-4a44-92a7-59f8c2dab4b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('222f2abd-6a7d-4727-9877-f4aec74c1bcc', 'Pelvis', false, '68bd7665-9a0f-4a44-92a7-59f8c2dab4b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23d49ca1-20c9-4f10-8aa3-2e3ae0658090', 'Clavicles', false, '68bd7665-9a0f-4a44-92a7-59f8c2dab4b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('629c3ba2-11ad-4acf-9bd6-48be1dc0c55e', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'How many pairs of ribs are there in the normal human rib cage?', 'There are 12 bilateral pairs of ribs: 7 true ribs, 3 false ribs, and 2 floating rib pairs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e37c36f9-78fa-4c54-8c41-ec500ddf90e3', '12 pairs (24 ribs total)', true, '629c3ba2-11ad-4acf-9bd6-48be1dc0c55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79fbb2fe-b030-4325-8ba5-1c5e39aa2753', '10 pairs', false, '629c3ba2-11ad-4acf-9bd6-48be1dc0c55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5ef3447-c347-4933-b576-a6b8022a06d3', '14 pairs', false, '629c3ba2-11ad-4acf-9bd6-48be1dc0c55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce9b7d49-63ce-4d6f-a029-1d2a09cd21c0', '7 pairs', false, '629c3ba2-11ad-4acf-9bd6-48be1dc0c55e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c2ad9ab-4f71-4af9-b19f-9349057b9e23', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The long, flexible column running along our back made up of 33 small individual bones (vertebrae) is the:', 'The vertebral column consists of 33 stacked vertebrae that protect the spinal cord and allow torso bending.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e9ae842-3934-41e9-8c1a-c1299324057a', 'Backbone (Spine / Vertebral Column)', true, '7c2ad9ab-4f71-4af9-b19f-9349057b9e23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a868ed7-9af6-4c8b-ac9d-b268d7ccd7ca', 'Rib cage', false, '7c2ad9ab-4f71-4af9-b19f-9349057b9e23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f870d2e0-73e1-4bb5-a02e-139e11931770', 'Pelvic bone', false, '7c2ad9ab-4f71-4af9-b19f-9349057b9e23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4977a475-8f00-4f2f-8d46-52a114cdef1f', 'Femur', false, '7c2ad9ab-4f71-4af9-b19f-9349057b9e23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f761753-cee6-4450-997e-f461c1c9e84b', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The softer, flexible connective tissue that is not as hard as bone and can be bent, found in the upper ear lobe and tip of the nose, is:', 'Cartilage is an avascular, flexible cartilaginous matrix cushioning joints and structuring the external pinna.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('715e725e-d84b-49c3-b933-a1217237f7ea', 'Cartilage', true, '4f761753-cee6-4450-997e-f461c1c9e84b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43af3060-5717-4e01-a29d-5350c13bd9be', 'Ligament', false, '4f761753-cee6-4450-997e-f461c1c9e84b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5ea7395-73d4-4d1e-aa1a-31856c5b8c58', 'Tendon', false, '4f761753-cee6-4450-997e-f461c1c9e84b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efe04395-bec0-4dab-a9b5-18199f80607d', 'Muscle', false, '4f761753-cee6-4450-997e-f461c1c9e84b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e47ab6e-5361-4802-b820-27940c161854', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'What are the specialized contractile tissues that work in coordinated antagonistic pairs (contraction and relaxation) to pull bones and cause movement?', 'Muscles can only pull (contract) and cannot push; hence they operate in antagonistic pairs to flex and extend limbs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0986edef-af8b-4af7-a525-d89986e7a0b3', 'Muscles (e.g., Biceps and Triceps)', true, '4e47ab6e-5361-4802-b820-27940c161854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e2a772f-286c-4823-9d5f-acb7c1bf29e6', 'Cartilage', false, '4e47ab6e-5361-4802-b820-27940c161854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8bc93d2-1587-443d-bbc6-7d919d88e78c', 'Nerves', false, '4e47ab6e-5361-4802-b820-27940c161854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16d7e439-920a-49aa-8887-2bf12bab2c08', 'Blood vessels', false, '4e47ab6e-5361-4802-b820-27940c161854');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9d87f7e-94d5-4984-98f9-c2ecb2c56ec7', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'Why do muscles always operate in PAIRS to move a bone at a joint?', 'Muscle fiber sliding-filament contraction exerts unidirectional tensile pulling force; returning the limb requires an antagonistic counter-pull.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('925bb246-7c39-44e1-98e6-04648980ec8a', 'A muscle can only pull (contract) and cannot push; when one contracts to pull a bone, the other relaxes, and vice versa to return it', true, 'e9d87f7e-94d5-4984-98f9-c2ecb2c56ec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a98f2dc-4d92-4fad-9766-1d4ae933c10a', 'Because one muscle is always sleeping', false, 'e9d87f7e-94d5-4984-98f9-c2ecb2c56ec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12ffc137-501d-4412-a13a-a485bf1a9554', 'To make bones heavier', false, 'e9d87f7e-94d5-4984-98f9-c2ecb2c56ec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('824c6840-11d7-4706-87b5-de78d212ac2d', 'Because bones have two heads', false, 'e9d87f7e-94d5-4984-98f9-c2ecb2c56ec7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7acc6c1-0d74-4194-bea6-3c5b5d1b89e7', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'How does an Earthworm crawl forward on the ground without having any internal bones?', 'Peristaltic hydrostatic locomotion: circular and longitudinal muscle waves coordinate with anchoring chitinous setae.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1985547f-d402-4375-8971-04b4e6d7b1ab', 'By alternate cycles of muscular contraction and expansion of body segments, aided by tiny hair-like bristles (setae) that grip the soil', true, 'f7acc6c1-0d74-4194-bea6-3c5b5d1b89e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2f34d3a-6e98-47e2-8f7e-00888a5bdedf', 'By rolling like a ball', false, 'f7acc6c1-0d74-4194-bea6-3c5b5d1b89e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0cb5ff7-1a94-468e-a29d-4ed9d699c9f4', 'By using wings to glide', false, 'f7acc6c1-0d74-4194-bea6-3c5b5d1b89e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17507401-9fc5-44ab-8a5f-1471655dfc00', 'By jumping with legs', false, 'f7acc6c1-0d74-4194-bea6-3c5b5d1b89e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8dec8674-e1b5-4d3c-8657-55edf6221290', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What organ does a Snail use for locomotion, and what substance does it secrete to glide smoothly over sharp surfaces?', 'The ventral muscular foot produces retrograde pedal muscular waves over a protective friction-reducing mucus layer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e832d13-273b-495e-bfc6-8354ddcd8c3a', 'A strong muscular foot, secreting a slimy layer of lubricating mucus', true, '8dec8674-e1b5-4d3c-8657-55edf6221290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e736d21-b78e-4db4-a07a-9b6b15884f08', 'Jointed legs, secreting wax', false, '8dec8674-e1b5-4d3c-8657-55edf6221290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90d21da8-30c7-416d-b79a-f757a4309bdd', 'Wings, secreting water', false, '8dec8674-e1b5-4d3c-8657-55edf6221290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fdcb62d-616f-44b4-9469-c83bfe000123', 'A bony tail, secreting oil', false, '8dec8674-e1b5-4d3c-8657-55edf6221290');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10b88970-fee2-4f61-952f-0758e26cb409', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'How many pairs of walking legs and how many pairs of wings does a Cockroach have attached to its thorax?', 'Cockroach hexapod anatomy: three thoracic segments bear three pairs of jointed ambulatory legs and two pairs of wings.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c13fcd7-dd28-4bfe-81bb-9e33e5358630', '3 pairs of legs (6 legs) and 2 pairs of wings (4 wings)', true, '10b88970-fee2-4f61-952f-0758e26cb409');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca0aa236-e1e5-4df9-9e43-ba6b7e60eadd', '4 pairs of legs and 1 pair of wings', false, '10b88970-fee2-4f61-952f-0758e26cb409');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('251faedd-4ae5-433d-8f65-8ff57ed2475d', '2 pairs of legs and 2 pairs of wings', false, '10b88970-fee2-4f61-952f-0758e26cb409');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('397b1452-14a7-45f4-9e43-e67797954916', '5 pairs of legs and 0 wings', false, '10b88970-fee2-4f61-952f-0758e26cb409');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec0cf001-c939-4848-8891-658cbb3e517c', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What anatomical adaptations enable Birds to fly efficiently in the air?', 'Avian flight requires pneumatic skeletal weight reduction, aerodynamic wing camber, and hypertrophied supracoracoideus/pectoralis flight muscles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50590f98-083a-446b-ba8e-098da8458615', 'Hollow and light pneumatic bones, forelimbs modified into wings with flight feathers, and powerful pectoral breast muscles attached to a deep breastbone', true, 'ec0cf001-c939-4848-8891-658cbb3e517c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e734a34f-cf73-4457-8e35-866924f8cb5e', 'Heavy solid bones to resist wind', false, 'ec0cf001-c939-4848-8891-658cbb3e517c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80a1a8c4-8713-43ee-b8f2-2fa2b16f8e4c', 'Lack of heart and lungs', false, 'ec0cf001-c939-4848-8891-658cbb3e517c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2115b174-b1d5-4473-903a-0dbd00aecf66', 'A heavy tail made of steel', false, 'ec0cf001-c939-4848-8891-658cbb3e517c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4a36c1a-4cf5-4b72-a3ec-9d2a650e616b', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What is the characteristic ''streamlined'' body shape of a Fish, and how does it assist aquatic swimming?', 'Fusiform hydrodynamic streamlining reduces laminar drag, skin friction, and wake vortices during underwater propulsion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('631396d3-689f-4250-9ce9-adc603e3231f', 'The head and tail are narrower than the middle portion, minimizing fluid resistance and drag as it glides through water', true, 'c4a36c1a-4cf5-4b72-a3ec-9d2a650e616b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2914e095-1ee1-4aa9-8345-64c06ba31485', 'A square flat shape that traps water', false, 'c4a36c1a-4cf5-4b72-a3ec-9d2a650e616b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ddf11e1-5e01-4d09-a5de-a24fa521eb6d', 'A circular spherical shape', false, 'c4a36c1a-4cf5-4b72-a3ec-9d2a650e616b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb9a25d5-381c-4610-b1d1-e3af6159b877', 'A long straight line without curves', false, 'c4a36c1a-4cf5-4b72-a3ec-9d2a650e616b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b75602b2-c24f-4dad-b633-de390c794725', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'How does a Fish propel itself forward through water using its body and caudal (tail) fin?', 'Alternating lateral myotomal muscle contractions produce undulating waves along the spine, ending in a propulsive caudal thrust.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6c7ced8-203a-4742-8efd-ed695c3e82e0', 'By curving its flexible body into alternating side-to-side loops (undulations), where the tail fin pushes water in the opposite direction creating forward thrust', true, 'b75602b2-c24f-4dad-b633-de390c794725');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('723418a7-0b67-40f2-826c-200e5b8369aa', 'By sucking in water through its nose', false, 'b75602b2-c24f-4dad-b633-de390c794725');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37c650bc-bfd6-42c5-9404-fb04eb91c548', 'By walking on underwater sand', false, 'b75602b2-c24f-4dad-b633-de390c794725');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2599a76f-8541-4bf1-acf1-ffdf54aa612f', 'By floating motionless', false, 'b75602b2-c24f-4dad-b633-de390c794725');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52abc0f7-cb89-426a-895b-5d533944cb4e', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'How does a Snake move rapidly across ground without having any limbs or legs?', 'Serpentine lateral undulation: wave curves along hundreds of vertebrae and ribs exert posterior force against ground irregularities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9cb8e47-b036-46e7-9e5a-7d4bcb917953', 'By slithering in S-shaped sinusoidal loops; each loop presses against the ground to push the snake forward', true, '52abc0f7-cb89-426a-895b-5d533944cb4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16f704d1-a958-40f3-90cb-05a39688b472', 'By rolling like a wheel', false, '52abc0f7-cb89-426a-895b-5d533944cb4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('660fec8b-0e41-470c-8758-2efc139dbe0d', 'By jumping on its tail', false, '52abc0f7-cb89-426a-895b-5d533944cb4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4f03563-6503-46dc-9ad9-5213768121ba', 'By walking on tiny invisible legs', false, '52abc0f7-cb89-426a-895b-5d533944cb4e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa6978b8-ea0e-4764-95e8-ad51653aba1c', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'Why do snakes move in deep wave-like curves and NEVER in a perfectly straight line during rapid slithering?', 'Lateral undulation requires curved contact zones where body angles transfer vector thrust against friction points.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1675c81-9c23-4b65-a285-bae9cf7f8cd0', 'Each lateral loop of its long flexible body pushes against surface irregularities to generate forward momentum', true, 'fa6978b8-ea0e-4764-95e8-ad51653aba1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c36cbb7c-8c93-4dfe-bb8b-103dda714f96', 'Snakes have crooked eyes', false, 'fa6978b8-ea0e-4764-95e8-ad51653aba1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6190e9a4-e098-4b09-b259-644b528685a5', 'Straight paths make snakes dizzy', false, 'fa6978b8-ea0e-4764-95e8-ad51653aba1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('299017c7-2af4-4270-83f1-be08d7ab0e20', 'Snakes cannot bend their bones', false, 'fa6978b8-ea0e-4764-95e8-ad51653aba1c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fdf2204f-5c54-4a6e-a97c-59061cff7199', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What is an X-ray radiograph used for in medical diagnostic science?', 'High-density calcium in bones absorbs X-ray photons, casting sharp white silhouettes on radiographic film to reveal fractures.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d34e324a-e99e-41c6-9fa3-0aabac7c2207', 'To capture photographic shadow images of dense bones and detect fractures, dislocations, or skeletal injuries', true, 'fdf2204f-5c54-4a6e-a97c-59061cff7199');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('644dd11b-cc46-4ecc-bfc0-71fb7ee0cb76', 'To check blood color', false, 'fdf2204f-5c54-4a6e-a97c-59061cff7199');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1491a415-e905-4c8e-b47b-e3b130325b0a', 'To count hairs on the head', false, 'fdf2204f-5c54-4a6e-a97c-59061cff7199');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17a0edb5-831d-4ac9-98c9-136fd20ef9bd', 'To measure eye vision', false, 'fdf2204f-5c54-4a6e-a97c-59061cff7199');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55a1f42c-62ca-4669-82ba-77ce2a14c40b', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'Which anatomical joint in the human body is formed by the Pelvic bone joining the upper leg bone (Femur)?', 'The femoral head inserts into the pelvic acetabulum socket, forming a stable weight-bearing ball-and-socket joint.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b32a57ec-cdbd-46c7-96e3-6832890293ff', 'Hip Joint (Ball and Socket Joint)', true, '55a1f42c-62ca-4669-82ba-77ce2a14c40b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d4caa1a-add5-4444-96d7-ac5fcdd202ba', 'Knee Joint (Hinge Joint)', false, '55a1f42c-62ca-4669-82ba-77ce2a14c40b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79fda9c0-5b43-4bb4-bbd3-8e261b4db9f0', 'Ankle Joint', false, '55a1f42c-62ca-4669-82ba-77ce2a14c40b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fbddb95-3016-4970-95b7-d8c626d1a918', 'Pivot Joint', false, '55a1f42c-62ca-4669-82ba-77ce2a14c40b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bde7868f-eda9-4a1c-a4c4-6964b8f4451c', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What is the tough, fibrous connective tissue band that attaches a MUSCLE to a BONE called?', 'Tendons are collagenous bands transmitting contractile muscle forces to move skeletal bones.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('575dfe6b-125b-4758-911c-772460c1ad5f', 'Tendon', true, 'bde7868f-eda9-4a1c-a4c4-6964b8f4451c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cecc9d94-7ae4-47aa-a92b-9e0c444d8564', 'Ligament', false, 'bde7868f-eda9-4a1c-a4c4-6964b8f4451c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c66649ba-3acb-4b2b-8a20-cb369ddcfff0', 'Cartilage', false, 'bde7868f-eda9-4a1c-a4c4-6964b8f4451c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fd110b5-8db0-4992-8ed3-f339b9717192', 'Joint capsule', false, 'bde7868f-eda9-4a1c-a4c4-6964b8f4451c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3a81eff-d09a-4ccf-84ac-c6d5904f4a21', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What is the strong fibrous connective tissue band that connects a BONE to another BONE at a joint called?', 'Ligaments are strong elastomeric bands bridging bone-to-bone junctions to stabilize joint capsules.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('185e3efe-cb22-4707-a66d-a3c755ba48e9', 'Ligament', true, 'a3a81eff-d09a-4ccf-84ac-c6d5904f4a21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc58a658-9b2b-46e3-80bb-3b5f3695c25f', 'Tendon', false, 'a3a81eff-d09a-4ccf-84ac-c6d5904f4a21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b8f773e-8b59-4eb7-b9ed-8dba34b803e9', 'Cartilage', false, 'a3a81eff-d09a-4ccf-84ac-c6d5904f4a21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('281243fb-e2b6-4f20-9bf1-12c8b929a4e4', 'Myofibril', false, 'a3a81eff-d09a-4ccf-84ac-c6d5904f4a21');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f41acd8-10b7-4066-af7d-2c9f61c7d8b2', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'Why is the human backbone composed of 33 small vertebrae with intervertebral discs instead of one single, solid long bone?', 'Segmented multi-vertebral articulation provides multi-axis spinal flexibility, shock absorption, and bending.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61b25e32-3bdf-4e0d-a745-42676a34c42a', 'If it were a single continuous bone, we would never be able to bend forward, backward, or twist our torso sideways', true, '1f41acd8-10b7-4066-af7d-2c9f61c7d8b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e20c9d9-a631-44d1-96ab-ac04435562c9', 'To make the body heavier', false, '1f41acd8-10b7-4066-af7d-2c9f61c7d8b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('243fc65c-7e1d-4bb6-b9ce-1c4b66702709', 'Because one long bone would melt', false, '1f41acd8-10b7-4066-af7d-2c9f61c7d8b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d90d5286-fd99-4cd3-beea-5410a634115a', 'To store food inside', false, '1f41acd8-10b7-4066-af7d-2c9f61c7d8b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2de8732c-57c8-4fc2-a181-0b87a11dde65', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'Which of the following animals possesses a hard external skeleton (Exoskeleton) made of chitin that is periodically molted?', 'Arthropods (insects, crustaceans) possess a rigid cuticular chitinous exoskeleton encasing soft internal organs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6572ede-af01-4844-b4a4-6f73210c686d', 'Cockroach and Crab', true, '2de8732c-57c8-4fc2-a181-0b87a11dde65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80c926ef-aaa1-457e-9e24-ac52580583e5', 'Earthworm', false, '2de8732c-57c8-4fc2-a181-0b87a11dde65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cad313e-ee4e-4db0-9d3a-fb56cc1acce8', 'Fish', false, '2de8732c-57c8-4fc2-a181-0b87a11dde65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf350ba6-e172-4523-8441-a40d65b58b14', 'Snake', false, '2de8732c-57c8-4fc2-a181-0b87a11dde65');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1dc5be66-8909-4d60-a1f3-680f6d3b8a95', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What is the ancient philosophical Greek treatise ''Gait of Animals'' (De Motu Animalium) that first analyzed the mechanics of animal locomotion authored by?', 'Aristotle authored ''Progression of Animals'' and ''Movement of Animals'', pioneering the comparative biomechanics of locomotion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e323778-4c46-4914-917b-61ffa8363e71', 'Aristotle', true, '1dc5be66-8909-4d60-a1f3-680f6d3b8a95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e12111fc-d4b0-4829-a5e0-d44986c5d01e', 'Plato', false, '1dc5be66-8909-4d60-a1f3-680f6d3b8a95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9e5393b-440c-4c1e-a555-d9ba871c7b39', 'Archimedes', false, '1dc5be66-8909-4d60-a1f3-680f6d3b8a95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8494688f-190e-4f96-9179-4a624b993cfa', 'Socrates', false, '1dc5be66-8909-4d60-a1f3-680f6d3b8a95');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9bf2dac-7a28-498f-b2fe-5e8e5e0d5204', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a594152-f16d-4df6-83c2-bde813270616', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'c9bf2dac-7a28-498f-b2fe-5e8e5e0d5204');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40dbbf85-5004-4167-817e-6b63ec233bbb', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'c9bf2dac-7a28-498f-b2fe-5e8e5e0d5204');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b21e8d19-dc4f-4ebb-8b3f-979fad07d48b', '(A) is true, but (R) is false.', false, 'c9bf2dac-7a28-498f-b2fe-5e8e5e0d5204');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20d909ca-fed8-434c-b9ef-72953c3fae52', '(A) is false, but (R) is true.', false, 'c9bf2dac-7a28-498f-b2fe-5e8e5e0d5204');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20f34eb7-f25e-4662-a603-a52ab8bd9e8a', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Spot the IMPOSTER in the following group of anatomical joints paired with their locations in the human body:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('360a9103-ec4f-4d46-bd89-9e7d97825270', 'Shoulder Joint - Ball and Socket', false, '20f34eb7-f25e-4662-a603-a52ab8bd9e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ace55768-5456-402c-b905-d23a3cca2946', 'Elbow Joint - Hinge', false, '20f34eb7-f25e-4662-a603-a52ab8bd9e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('837bd05e-300b-423a-b23d-79d386889d61', 'Cranial Sutures - Fixed', false, '20f34eb7-f25e-4662-a603-a52ab8bd9e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7c4c56e-5467-4afe-b16e-9bb5ebca2d66', 'Knee Joint - Pivot', true, '20f34eb7-f25e-4662-a603-a52ab8bd9e8a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51ad249f-7d6e-4a8b-ae1c-2cac0fac8129', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'A biomechanist observes the flight mechanics of a pigeon. What anatomical structures execute the ''downstroke'' and ''upstroke'' of the wings during flight?', 'Avian triosseal canal pulley mechanism: Pectoralis major powers propulsive downstrokes, while supracoracoideus elevates wings for upstroke.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be16db10-9024-4466-9513-794356a8ad08', 'The massive Pectoralis major breast muscle contracts for the powerful downstroke, while the Pectoralis minor (Supracoracoideus) pulls a tendon over a pulley to lift the wing in upstroke', true, '51ad249f-7d6e-4a8b-ae1c-2cac0fac8129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7417434f-7d18-4f36-90f3-a3d1112d16c9', 'The legs kick backwards', false, '51ad249f-7d6e-4a8b-ae1c-2cac0fac8129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a713c3ca-470b-4249-bcd7-c709a187d016', 'The neck turns left and right', false, '51ad249f-7d6e-4a8b-ae1c-2cac0fac8129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bba73543-795e-4e82-aa9b-ac061ad2caf4', 'Air is blown out from the tail', false, '51ad249f-7d6e-4a8b-ae1c-2cac0fac8129');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf627a6c-f48d-4f70-bc25-7a3bbe5570af', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Match Column I (Organisms) with Column II (Locomotory Organs / Mechanics):
(a) Earthworm -> (i) Muscular foot with mucus trail
(b) Snail     -> (ii) Hydrostatic body segments with setae
(c) Cockroach -> (iii) Streamlined body with myotomes and fins
(d) Fish      -> (iv) Jointed thoracic legs and chitinous wings', 'Earthworm = setae & segments; Snail = muscular foot; Cockroach = 6 legs & wings; Fish = streamlined myotome fins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72d36cb8-56d4-44d4-939b-76114cc33498', 'a-(ii), b-(i), c-(iv), d-(iii)', true, 'bf627a6c-f48d-4f70-bc25-7a3bbe5570af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc2853b3-b0d0-4726-9023-befe7a7772e4', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'bf627a6c-f48d-4f70-bc25-7a3bbe5570af');
