INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7836fb2f-f62e-4eda-a61d-e336c48a8546', 'Statements 1 and 2 only', true, '3730768b-ca70-41f3-91d4-684dbe337fb1');
