INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fadea33-f6d9-47f1-b261-9a1d93edc51b', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Why do underwater divers wear long, flipper-shaped swim fins on their feet?', 'Flippers increase effective propulsive surface area, converting oscillating leg strokes into laminar hydrodynamic thrust.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9544825f-ece3-4784-8484-b4bfc6b976c9', 'To mimic the streamlined flat caudal fins of fish, maximizing water displacement thrust and swimming speed with minimal muscular effort', true, '7fadea33-f6d9-47f1-b261-9a1d93edc51b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a7e9956-b5d0-48b2-bda4-936af3aa0dc0', 'To keep their feet warm', false, '7fadea33-f6d9-47f1-b261-9a1d93edc51b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cea3c5a-1e4d-4eea-8750-c5e3d93d1a88', 'To walk on the ocean floor like a crab', false, '7fadea33-f6d9-47f1-b261-9a1d93edc51b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('825e774d-d1fc-4e75-a902-7700eff0c7dd', 'To float like a balloon', false, '7fadea33-f6d9-47f1-b261-9a1d93edc51b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d80a511f-b7f3-4ef0-9e92-33153a080a25', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'What happens when a person flexes (bends) their arm at the elbow to touch their shoulder with their hand?', 'Elbow flexion: agonist biceps brachii contracts concentrically while antagonist triceps brachii lengthens in eccentric relaxation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab137f61-f0a2-4107-bf47-ea8b153fa0c7', 'The Biceps muscle on the front of the upper arm contracts (shortens and bulges), while the Triceps muscle on the back relaxes', true, 'd80a511f-b7f3-4ef0-9e92-33153a080a25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f12ff245-6db0-4f8c-bf9c-c696ad5d9291', 'The Triceps contracts and biceps relaxes', false, 'd80a511f-b7f3-4ef0-9e92-33153a080a25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2cd4d93-07b7-4422-bc91-ae9747017c20', 'Both biceps and triceps contract simultaneously', false, 'd80a511f-b7f3-4ef0-9e92-33153a080a25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d60ee3d-fa7c-4130-a0da-734e646e9b62', 'Both muscles relax completely', false, 'd80a511f-b7f3-4ef0-9e92-33153a080a25');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b041031-fa60-4df5-90ef-35e1f0dd4815', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Consider four joints in the human body:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('311a2542-216f-45da-b3cc-a1182258ae4e', '1 (Ball & Socket - 360°) -> 4 (Gliding) -> 3 (Hinge - 180°) -> 2 (Fixed - 0°)', true, '3b041031-fa60-4df5-90ef-35e1f0dd4815');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcbe35a5-85be-4137-9716-05d748f3b69c', '2 -> 3 -> 4 -> 1', false, '3b041031-fa60-4df5-90ef-35e1f0dd4815');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3944f6b6-2a2b-456d-a32e-117cf09b2691', '3 -> 1 -> 4 -> 2', false, '3b041031-fa60-4df5-90ef-35e1f0dd4815');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6db106a6-a09a-443f-bfb3-1eb61d34553f', '1 -> 2 -> 3 -> 4', false, '3b041031-fa60-4df5-90ef-35e1f0dd4815');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee341e35-b849-4844-baee-39084449b3d1', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Why are the bones of the pelvic girdle much thicker, heavier, and more tightly fused than the bones of the shoulder pectoral girdle?', 'The ilium, ischium, and pubis fuse into a heavy rigid osseous ring to transfer axial torso loads into lower limb femurs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8048b7bd-5318-4cc6-a354-ec4040de64ff', 'The pelvic girdle bears the entire weight of the upper body during standing, walking, and running, and protects pelvic visceral organs', true, 'ee341e35-b849-4844-baee-39084449b3d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42962452-02d9-49bb-bb44-64a6a4e2bfaf', 'To store extra blood', false, 'ee341e35-b849-4844-baee-39084449b3d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b4b6c5e-43ac-4549-8f33-e18a5dbd87c2', 'Because legs are shorter than arms', false, 'ee341e35-b849-4844-baee-39084449b3d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd86f7e7-3049-4fb3-acb0-f54348d6413f', 'To help digest food', false, 'ee341e35-b849-4844-baee-39084449b3d1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86eea045-8fb6-4f2a-8681-2a63f42afb45', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'How does the swim bladder (air bladder) in bony fishes assist their buoyancy and vertical movement in water?', 'Hydrostatic swim bladders adjust gas partial pressure via the rete mirabile to equalize whole-body density with surrounding water density.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61e36652-4f0a-40db-80d9-c7e2669d593b', 'By regulating the volume of gas inside the bladder, allowing the fish to maintain neutral buoyancy and hover at any water depth without sinking or floating', true, '86eea045-8fb6-4f2a-8681-2a63f42afb45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d13359e-8e46-49e9-af9f-cd6d82287583', 'By heating the water around the fish', false, '86eea045-8fb6-4f2a-8681-2a63f42afb45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24cb83ee-5b1e-4ff6-8bce-489a9ae4430c', 'By digesting fish food', false, '86eea045-8fb6-4f2a-8681-2a63f42afb45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd93ec51-e903-41e3-aa89-5c4f341dbdbf', 'By glowing in the dark', false, '86eea045-8fb6-4f2a-8681-2a63f42afb45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdcecb42-cfc1-4aba-b408-6e721a12f429', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Which of the following describes the functional anatomy of the human Wrist Joint (Carpal bones)?', 'Intercarpal articulations are planar arthrodial gliding joints allowing smooth translational sliding motions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('020354c2-cd13-4d64-8145-5c07478b9713', 'Gliding Joint (Plane Joint) where small carpal bones slide gently over one another, providing subtle multidirectional hand flexion', true, 'bdcecb42-cfc1-4aba-b408-6e721a12f429');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3cdc386-2579-4ecf-aadb-1f899b6dc6d9', 'Ball and Socket Joint', false, 'bdcecb42-cfc1-4aba-b408-6e721a12f429');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a041758-6156-4f00-aadf-78ea4b89c947', 'Fixed Suture Joint', false, 'bdcecb42-cfc1-4aba-b408-6e721a12f429');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b98c6454-0fe3-4735-a3f5-6a680fe8f02a', 'Pivotal Joint', false, 'bdcecb42-cfc1-4aba-b408-6e721a12f429');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07520eaa-e87e-4419-a27c-738d9efa60d3', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'What physiological consequence occurs if articular cartilage at the ends of synovial joints wears away due to degenerative disease (osteoarthritis)?', 'Loss of hyaline articular cartilage eliminates hydrodynamic lubrication, leading to painful eburnation and bone spurs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c911b1f1-49d7-414d-98c3-5e8b1bb91839', 'Exposed bare bones rub directly against each other, causing severe friction, excruciating pain, inflammation, and stiffness during movement', true, '07520eaa-e87e-4419-a27c-738d9efa60d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0a9c5f9-e9c9-435a-9d80-1addb82ab82b', 'Bones turn into soft muscle', false, '07520eaa-e87e-4419-a27c-738d9efa60d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80edbffb-f529-4a75-9c78-8041bc966637', 'Joints become 10 times more flexible', false, '07520eaa-e87e-4419-a27c-738d9efa60d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a7cff7d-755c-495d-846e-71c342abd7af', 'Bones disappear completely', false, '07520eaa-e87e-4419-a27c-738d9efa60d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea8c5b94-e278-43ea-bc28-b8b7dab66aed', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Easy', 'An angle measuring exactly 90° (equal to one-fourth of a full revolution) is called a:', 'A right angle measures exactly 90° (¼ of a 360° full revolution).', NOW()) ON CONFLICT DO NOTHING;
