INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bcf437c2-f85f-40f4-acc9-849ffe9449b8', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Easy', 'A quadrilateral having all 4 sides equal and all 4 internal angles equal to 90° is a:', 'A square is a regular quadrilateral with 4 equal sides, 4 right angles, and perpendicular diagonals.', NOW()) ON CONFLICT DO NOTHING;
