INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16481dab-c855-47bf-99ad-3efd4b62a143', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Easy', 'How many faces (flat surfaces) does a 3D solid Cube or Cuboid have?', 'A standard hexahedral cube/cuboid has 6 quadrilateral faces, 12 straight edges, and 8 corner vertices.', NOW()) ON CONFLICT DO NOTHING;
