INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adcd964d-d5a1-4145-bc05-39a6fa8b6c4a', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What fraction of a clockwise revolution does the hour hand of a clock turn through when it goes from 3 to 9?', 'From 3 to 9 is 6 hour divisions: 6/12 = 1/2 revolution = 180°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05c5d8d7-f919-4ce1-a8da-50c1a15f3de9', '1/2 revolution (180° / 2 right angles)', true, 'adcd964d-d5a1-4145-bc05-39a6fa8b6c4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c6fdfff-1074-4a78-9860-363e8e0aafc0', '1/4 revolution', false, 'adcd964d-d5a1-4145-bc05-39a6fa8b6c4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24a0d71b-8820-46c6-86b2-1f88b0bd90d5', '3/4 revolution', false, 'adcd964d-d5a1-4145-bc05-39a6fa8b6c4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7181a90a-e1ad-4c6e-8008-045bc6d5acde', '1 full revolution', false, 'adcd964d-d5a1-4145-bc05-39a6fa8b6c4a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b9febea-d752-4c6d-a2f9-613c31b54f8a', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What fraction of a clockwise revolution does the hour hand of a clock turn through when it goes from 12 to 3?', 'From 12 to 3 is 3 hour divisions: 3/12 = 1/4 revolution = 90°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0148c62f-85bb-41b6-9af3-7832af1267b5', '1/4 revolution (90° / 1 right angle)', true, '9b9febea-d752-4c6d-a2f9-613c31b54f8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7641439d-1db9-4f5e-9dbb-2d2e82d00b42', '1/2 revolution', false, '9b9febea-d752-4c6d-a2f9-613c31b54f8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('285f5e3d-7f0f-4676-ae86-20f9aaad5fac', '3/4 revolution', false, '9b9febea-d752-4c6d-a2f9-613c31b54f8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be67678a-20e8-46f0-9ca1-c0fb4059813b', '1/3 revolution', false, '9b9febea-d752-4c6d-a2f9-613c31b54f8a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18aa3c27-13e6-49c3-a1cf-4c194cf4a00e', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'Where will the hand of a clock stop if it starts at 12 and makes 1/2 of a revolution clockwise?', '12 + (1/2 × 12) = 12 + 6 = 6 o''clock.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf0b23f4-ae53-49f1-a0f4-85728d14279f', 'At 6', true, '18aa3c27-13e6-49c3-a1cf-4c194cf4a00e');
