INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09182de0-fcab-421a-a5e3-3f8c809113a6', 'At 9', false, '18aa3c27-13e6-49c3-a1cf-4c194cf4a00e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18759094-195d-48e4-a1da-b7eac8782f1f', 'At 12', false, '18aa3c27-13e6-49c3-a1cf-4c194cf4a00e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9964ac5-120d-4a3b-b03f-162acf41193c', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'Where will the hand of a clock stop if it starts at 2 and makes 3/4 of a revolution clockwise?', '3/4 of 12 hours = 9 hours. 2 + 9 = 11 o''clock.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('888e1e92-1b65-44a8-9a64-5a75406883b5', 'At 11', true, 'd9964ac5-120d-4a3b-b03f-162acf41193c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14bbf074-73ca-4dd3-9951-2e170da15b7c', 'At 8', false, 'd9964ac5-120d-4a3b-b03f-162acf41193c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11be77b9-fd21-4bc0-ae14-b9991cd25126', 'At 5', false, 'd9964ac5-120d-4a3b-b03f-162acf41193c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95c7e40c-3ad9-4ea5-ac91-4fab181a5930', 'At 10', false, 'd9964ac5-120d-4a3b-b03f-162acf41193c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('752b7d4d-2e2b-482c-8c61-9a9b31dabb23', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'If you face North and turn clockwise to face East, what fraction of a revolution have you turned through?', 'From North (0°) clockwise to East (90°) is 90°/360° = 1/4 revolution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e145c700-6c73-4692-9556-b01a688cc80e', '1/4 revolution (90° right angle)', true, '752b7d4d-2e2b-482c-8c61-9a9b31dabb23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dbad646-58e7-4549-9b86-07d10f558d3a', '1/2 revolution', false, '752b7d4d-2e2b-482c-8c61-9a9b31dabb23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b85210a-41ad-4d48-b5db-795d33ea9f04', '3/4 revolution', false, '752b7d4d-2e2b-482c-8c61-9a9b31dabb23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1fbec22-2367-48fb-b1cc-642da3b462a9', '1 revolution', false, '752b7d4d-2e2b-482c-8c61-9a9b31dabb23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31aae60a-f2aa-48ec-8484-94436dedd0f2', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'If you face West and turn clockwise to face South, how many right angles have you turned through?', 'From West clockwise: West -> North (1) -> East (2) -> South (3) = 3 right angles (270°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bd9d8b3-c933-435a-bd74-153fae9c01e4', '3 right angles (270° / 3/4 revolution)', true, '31aae60a-f2aa-48ec-8484-94436dedd0f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fc68879-b1f8-4270-aacb-e24d28b55260', '1 right angle', false, '31aae60a-f2aa-48ec-8484-94436dedd0f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d36e4af-a86c-4a79-9ac8-bbbc6acdc7c8', '2 right angles', false, '31aae60a-f2aa-48ec-8484-94436dedd0f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b19a1ff-50e2-4243-af5a-5b5cab700d42', '4 right angles', false, '31aae60a-f2aa-48ec-8484-94436dedd0f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc1d7603-f3b3-4131-9d1f-161c63ee5a52', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What is a line called that is perpendicular to a given line segment and divides it into two exact equal halves?', 'A perpendicular bisector intersects a segment at its midpoint at a right angle (90°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92b0c322-6e02-42b3-acd8-e3d8b01cf0ef', 'Perpendicular Bisector', true, 'bc1d7603-f3b3-4131-9d1f-161c63ee5a52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ec2921f-bcad-4328-b80e-62141fbc24c5', 'Diagonal', false, 'bc1d7603-f3b3-4131-9d1f-161c63ee5a52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d417fd3-c688-4ea4-8e42-0c06da1ee43f', 'Altitude', false, 'bc1d7603-f3b3-4131-9d1f-161c63ee5a52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78a570ee-8944-40d2-9b7a-0436c71d202b', 'Tangent', false, 'bc1d7603-f3b3-4131-9d1f-161c63ee5a52');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f72dda69-daf3-429a-b28b-5d5b4a352358', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'A quadrilateral in which opposite sides are parallel and equal, but opposite angles are NOT necessarily 90°, is a:', 'A parallelogram has opposite parallel congruent sides and bisecting diagonals.', NOW()) ON CONFLICT DO NOTHING;
