INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('384c8aeb-590a-4dc9-8e71-3cddb66115ac', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'A quadrilateral having all 4 sides equal, opposite sides parallel, but whose angles are not 90° is a:', 'A rhombus is an equilateral parallelogram whose diagonals bisect each other perpendicularly at 90°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89e89649-e1f0-4a24-8c7b-a2bdf088964d', 'Rhombus', true, '384c8aeb-590a-4dc9-8e71-3cddb66115ac');
