INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fa8cf85-f220-4cec-be64-1228af30da06', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'A quadrilateral with exactly ONE pair of parallel opposite sides is called a:', 'A trapezium is a 4-sided polygon having strictly one pair of parallel opposing bases.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb5662ed-4894-44fd-9ddb-a689d1f6c51f', 'Trapezium (or Trapezoid)', true, '7fa8cf85-f220-4cec-be64-1228af30da06');
