INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9681369-170b-467f-8afa-4c709bed471b', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What is a 5-sided polygon and an 8-sided polygon called respectively in geometry?', '5 sides = Pentagon; 6 sides = Hexagon; 7 sides = Heptagon; 8 sides = Octagon.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e440e83e-22de-4c5c-9a5d-587b6d427c3b', 'Pentagon (5 sides) and Octagon (8 sides)', true, 'd9681369-170b-467f-8afa-4c709bed471b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c948958-12f7-4431-bab6-f1e05ab8004a', 'Hexagon and Heptagon', false, 'd9681369-170b-467f-8afa-4c709bed471b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ed1246d-aae6-4b29-ac84-d5414a923940', 'Decagon and Nonagon', false, 'd9681369-170b-467f-8afa-4c709bed471b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('467b430f-1cdf-4805-8b4a-83adbf5a0e35', 'Triangle and Quadrilateral', false, 'd9681369-170b-467f-8afa-4c709bed471b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20e85170-3061-4fa7-a226-2edf866142c7', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What are the numbers of Faces (F), Vertices (V), and Edges (E) in a triangular pyramid (Tetrahedron)?', 'A tetrahedron has 4 triangular faces, 4 corner vertices, and 6 connecting edges (Euler''s formula F+V-E = 4+4-6 = 2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69d74326-e2d5-49d2-8e64-13ca9fa3a88a', '4 Faces, 4 Vertices, 6 Edges', true, '20e85170-3061-4fa7-a226-2edf866142c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5dcdc1a-7f97-4e35-b7e4-c420ef9e6eb8', '5 Faces, 6 Vertices, 9 Edges', false, '20e85170-3061-4fa7-a226-2edf866142c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('465a5869-e264-486b-99a2-647215e459b4', '6 Faces, 8 Vertices, 12 Edges', false, '20e85170-3061-4fa7-a226-2edf866142c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('523f56e8-7d56-49fb-85cc-6f7e79a56821', '4 Faces, 6 Vertices, 4 Edges', false, '20e85170-3061-4fa7-a226-2edf866142c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4a2ae78-04aa-413e-bfd4-af35ecf8f4d5', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What are the numbers of Faces, Vertices, and Edges in a Triangular Prism?', 'A triangular prism has 5 faces (2 bases + 3 rectangular sides), 6 vertices, and 9 edges (5+6-9 = 2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7867959-5218-4b61-b77a-047df0332652', '5 Faces (2 triangular, 3 rectangular), 6 Vertices, 9 Edges', true, 'a4a2ae78-04aa-413e-bfd4-af35ecf8f4d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74fea9c8-4542-4458-b4b6-106c289d7351', '4 Faces, 4 Vertices, 6 Edges', false, 'a4a2ae78-04aa-413e-bfd4-af35ecf8f4d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04b75eea-c2bf-48cf-a602-69cfaf1a0dc7', '6 Faces, 8 Vertices, 12 Edges', false, 'a4a2ae78-04aa-413e-bfd4-af35ecf8f4d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3146e71-83e1-4aab-802b-1e91f876eb91', '5 Faces, 5 Vertices, 8 Edges', false, 'a4a2ae78-04aa-413e-bfd4-af35ecf8f4d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65fb9969-0b43-439f-b922-896fa7fc3ffe', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What are the numbers of Faces, Vertices, and Edges in a Square Pyramid (like the Egyptian Pyramids)?', 'A square pyramid has 5 faces, 5 vertices (1 apex + 4 base), and 8 edges (5+5-8 = 2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7c55292-e52e-469d-b1ff-c52c798cb1a3', '5 Faces (1 square base, 4 triangular sides), 5 Vertices, 8 Edges', true, '65fb9969-0b43-439f-b922-896fa7fc3ffe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fad0dd21-51ae-46b3-b14c-6c1301d1b8e2', '6 Faces, 8 Vertices, 12 Edges', false, '65fb9969-0b43-439f-b922-896fa7fc3ffe');
