INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a26f9a57-bf5d-4208-b3de-5917bfc9e082', '5 Faces, 6 Vertices, 9 Edges', false, '65fb9969-0b43-439f-b922-896fa7fc3ffe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecf244c7-6508-4be8-805e-cfb21e6a5f5f', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'Which of the following 3D solid shapes has NO flat face, NO straight edge, and NO vertex?', 'A sphere is a perfectly smooth continuous curved surface with zero vertices, zero edges, and zero planar faces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54bc285f-6e4e-4ca9-807a-abfec2725c3f', 'Sphere (e.g. a football)', true, 'ecf244c7-6508-4be8-805e-cfb21e6a5f5f');
