INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91f9b69c-bb17-4fde-8f84-09d3b28f536d', 'Cone', false, 'ecf244c7-6508-4be8-805e-cfb21e6a5f5f');
