INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b56d313-7b44-4cad-b191-867ca53b6194', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'How many circular flat faces and curved surfaces does a solid Cylinder have?', 'A cylinder possesses two congruent circular planar end-bases connected by a single lateral curved surface.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8b30a35-e6d9-4a17-9d44-16bc11bee816', '2 flat circular faces and 1 curved surface', true, '7b56d313-7b44-4cad-b191-867ca53b6194');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c36dac05-d6f6-4979-8026-58f16f13f463', '1 flat face and 2 curved surfaces', false, '7b56d313-7b44-4cad-b191-867ca53b6194');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3137c78-284e-46cd-b756-f0c60d89fe89', '3 flat faces', false, '7b56d313-7b44-4cad-b191-867ca53b6194');
