INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca9ed857-15ad-4520-b170-8da775d36360', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'What is the angle between the hands of a clock at 9:00 PM?', 'Hour hand at 9, minute hand at 12: separation = 3 hour marks = 3 × 30° = 90°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30010f92-adb3-46b3-b9fd-7f6be6543140', '90° (Right angle) or Reflex 270°', true, 'ca9ed857-15ad-4520-b170-8da775d36360');
