INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4049ffc-df8c-41d8-b93f-885e041ad818', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'Match Column I (Quadrilaterals) with Column II (Properties of Diagonals):
(a) Square        -> (i) Diagonals are equal and bisect each other perpendicularly at 90°
(b) Rectangle     -> (ii) Diagonals are equal and bisect each other (not at 90°)
(c) Rhombus       -> (iii) Diagonals are unequal and bisect each other perpendicularly at 90°
(d) Parallelogram -> (iv) Diagonals bisect each other but are neither equal nor perpendicular', 'Square = equal & perp; Rectangle = equal; Rhombus = unequal & perp; Parallelogram = bisect only.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34e2cbcc-ef9d-4544-a5f5-438610916c0f', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'e4049ffc-df8c-41d8-b93f-885e041ad818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95075d89-53d9-4f6a-b5d5-9f2d34f03e52', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'e4049ffc-df8c-41d8-b93f-885e041ad818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7e8bbd6-f66f-4928-a42e-0cc24ff503fe', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'e4049ffc-df8c-41d8-b93f-885e041ad818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('190867c9-e71a-4b14-8a30-8b07dfafe018', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'e4049ffc-df8c-41d8-b93f-885e041ad818');
