INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8e0842b-6824-4b9f-886c-893ef2b1dd56', 'Statement 3 only', true, '036ba57c-3b50-4fe5-b3ad-d93ef89aca8c');
