INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10d1d931-0e19-4b3c-8b23-515b1c40a292', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'What is the angle traced by the hour hand of a clock between 1:00 PM and 5:00 PM?', 'Each clock hour span = 360°/12 = 30°. Elapsed time = 4 hours -> 4 × 30° = 120° (Obtuse angle).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cab56bca-9171-485f-bdc4-8f545a3682f6', '120° (4 hours × 30°/hour = 4/12 × 360°)', true, '10d1d931-0e19-4b3c-8b23-515b1c40a292');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5103dee-e83e-4c29-816b-4e672793123c', '90°', false, '10d1d931-0e19-4b3c-8b23-515b1c40a292');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42f14a97-5ab6-4c87-aa3f-f5d697aacc26', '150°', false, '10d1d931-0e19-4b3c-8b23-515b1c40a292');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efdc0304-c682-46c1-ae87-fd0bf1eaf392', '180°', false, '10d1d931-0e19-4b3c-8b23-515b1c40a292');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f4a48b1-8ea3-4b62-91c3-cb40825982e3', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'A polygon is ''Regular'' if it satisfies which two conditions simultaneously?', 'A regular polygon (like an equilateral triangle or square) has equal edge lengths and congruent interior vertex angles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a81113e8-624a-434c-b1c4-422b75590e07', 'It is Equilateral (all sides equal) AND Equiangular (all internal angles equal)', true, '7f4a48b1-8ea3-4b62-91c3-cb40825982e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdd9e984-1ea1-498e-b27e-d02d34354ecf', 'It has only 4 sides', false, '7f4a48b1-8ea3-4b62-91c3-cb40825982e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f46c6f7-d3e7-471f-9811-b2accbbaa700', 'It has curved sides', false, '7f4a48b1-8ea3-4b62-91c3-cb40825982e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('808e43a6-7107-47f9-ab71-1d73201291f1', 'Its diagonals are parallel', false, '7f4a48b1-8ea3-4b62-91c3-cb40825982e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8296393-6b10-4e01-a699-612dc307a2d9', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'How many total faces, edges, and vertices does an Octahedron (8-faced regular polyhedron formed by joining two square pyramids base-to-base) possess?', 'An octahedron has 8 triangular faces, 6 vertices, and 12 edges (8 + 6 - 12 = 2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0cc1977-9dcb-48e0-826e-8cfb09b9f884', '8 Faces, 6 Vertices, 12 Edges', true, 'd8296393-6b10-4e01-a699-612dc307a2d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6094081c-cfdf-4224-b941-c14dbc38c9c4', '8 Faces, 8 Vertices, 16 Edges', false, 'd8296393-6b10-4e01-a699-612dc307a2d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f953e0e8-f7ba-4ebf-a455-370679576cae', '6 Faces, 8 Vertices, 12 Edges', false, 'd8296393-6b10-4e01-a699-612dc307a2d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd7c1794-f397-427b-9816-71dd078f8867', '8 Faces, 12 Vertices, 6 Edges', false, 'd8296393-6b10-4e01-a699-612dc307a2d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4cebe31-7e33-47d4-bf3e-aa9a7a1189fe', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'Which 3D solid shape is formed when a right-angled triangle is rotated 360° continuously about one of its perpendicular legs?', 'Revolving a right triangle about an altitude leg sweeps out the circular base and conical apex of a cone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0d8f4a7-c201-4b13-ad7b-c14306ed4855', 'Right Circular Cone', true, 'c4cebe31-7e33-47d4-bf3e-aa9a7a1189fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c69f38aa-4916-4b60-9290-51b336d1efb8', 'Cylinder', false, 'c4cebe31-7e33-47d4-bf3e-aa9a7a1189fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c6439ac-62a0-40a2-b11c-cd3631ae6964', 'Sphere', false, 'c4cebe31-7e33-47d4-bf3e-aa9a7a1189fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b09495af-2034-4b5b-9d55-8e70d681a23f', 'Prism', false, 'c4cebe31-7e33-47d4-bf3e-aa9a7a1189fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42041302-dd34-4f7b-9bc6-3c2b2fb4a940', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'Consider a clock at 6:30. What is the angle between the hour hand and the minute hand?', 'At 6:30, minute hand is at 6 (180°), and hour hand is at 6.5 (195°). Angle = 195° - 180° = 15°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b068cba6-5311-457e-8d8c-921229d738dc', '15° (at 6:30, hour hand is halfway between 6 and 7: 30° / 2 = 15°)', true, '42041302-dd34-4f7b-9bc6-3c2b2fb4a940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d17b80cc-8a51-4098-a814-515be490432f', '0°', false, '42041302-dd34-4f7b-9bc6-3c2b2fb4a940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d00d9b45-01a3-4f63-8f36-665022aae60a', '30°', false, '42041302-dd34-4f7b-9bc6-3c2b2fb4a940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc3e9936-f383-40b3-a91e-ccdeb56f0542', '45°', false, '42041302-dd34-4f7b-9bc6-3c2b2fb4a940');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff54f9fa-0a80-4fea-af53-26cfabb4b6b5', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'In which of the following quadrilaterals are the diagonals NOT necessarily equal in length?', 'In a rhombus and general parallelogram, one diagonal is longer (spanning obtuse angles) than the other.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1475271-8d8a-416a-8d4f-612fb9a2f314', 'Rhombus and Parallelogram', true, 'ff54f9fa-0a80-4fea-af53-26cfabb4b6b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5e7f891-fc49-41bd-92cf-29f21323bc8f', 'Square', false, 'ff54f9fa-0a80-4fea-af53-26cfabb4b6b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('147a96c8-4fd2-4e94-bbd8-f64b659dd660', 'Rectangle', false, 'ff54f9fa-0a80-4fea-af53-26cfabb4b6b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17305ac1-94a8-4740-aadf-cb78878067b5', 'Isosceles Trapezium', false, 'ff54f9fa-0a80-4fea-af53-26cfabb4b6b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce1ef1b4-517c-4fc0-8955-964d77c01cff', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'What is the sum of all internal angles in a 6-sided Hexagon?', 'Formula S = (n - 2) × 180°; for n = 6: S = 4 × 180° = 720°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4758c33-95e9-4d55-9d58-94f2b51dc6d5', '720° ((n - 2) × 180° = (6 - 2) × 180° = 4 × 180°)', true, 'ce1ef1b4-517c-4fc0-8955-964d77c01cff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f1aa523-771c-4e4d-ac6c-2191cec20b4c', '540°', false, 'ce1ef1b4-517c-4fc0-8955-964d77c01cff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('581ea8cd-1640-46e2-9c33-5801a146e85f', '360°', false, 'ce1ef1b4-517c-4fc0-8955-964d77c01cff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('572b1cc6-f031-49a6-9bfb-43b29bee1db4', '900°', false, 'ce1ef1b4-517c-4fc0-8955-964d77c01cff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('df5de923-23a9-4631-82b9-bc1049e5a67c', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'Who was the headmistress and founder of the innovative school visited by the author E.V. Lucas?', 'Miss Beam was a middle-aged, authoritative yet kind and understanding woman who ran the unique school.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27667c7d-50a2-443e-9e1c-331dbd168016', 'Miss Beam', true, 'df5de923-23a9-4631-82b9-bc1049e5a67c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af84146f-d061-453f-9656-df4892fe93d1', 'Miss Sullivan', false, 'df5de923-23a9-4631-82b9-bc1049e5a67c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9131050a-919b-4113-a107-d161ff336a1a', 'Miss Mary', false, 'df5de923-23a9-4631-82b9-bc1049e5a67c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed4bf032-e5b1-4143-9d8c-a387dd162dcf', 'Mrs. Smith', false, 'df5de923-23a9-4631-82b9-bc1049e5a67c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f386cbe0-7614-47c1-9a9b-56ca3df9b992', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'What was the real aim and core educational philosophy of Miss Beam''s school?', 'Miss Beam emphasized active empathy, compassion, and experiential understanding of others'' misfortunes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94cd0488-8b48-494d-a900-4c12765ba667', 'Not so much to teach thought, but thoughtfulness — kindness to others, empathy, and being responsible citizens', true, 'f386cbe0-7614-47c1-9a9b-56ca3df9b992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e616687-a3d2-4a93-a551-6ccc85856174', 'To produce top rankers in mathematics only', false, 'f386cbe0-7614-47c1-9a9b-56ca3df9b992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe146f75-da04-40f6-a3e7-c577d8aec075', 'To train professional athletes', false, 'f386cbe0-7614-47c1-9a9b-56ca3df9b992');
