INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ade24afa-10b6-40a2-8074-57d37af8b1f0', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'What special experiential system was organized in Miss Beam''s school to make children appreciate and understand misfortune?', 'Each child lived through simulated disabilities so they developed genuine compassion for the disabled.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a71c5e66-00aa-4dfc-a966-89e8f4b39a2c', 'Every child had one blind day, one lame day, one deaf day, one injured day, and one dumb day during each term', true, 'ade24afa-10b6-40a2-8074-57d37af8b1f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8140005b-72fe-44ea-afe6-e954d207313b', 'Students had to do all cleaning work', false, 'ade24afa-10b6-40a2-8074-57d37af8b1f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('defcb7c1-c848-48b9-8327-670c1113233b', 'Students were sent to live in a forest', false, 'ade24afa-10b6-40a2-8074-57d37af8b1f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6eaab5f-fd4c-4157-aeaa-d73557572774', 'Students were not allowed to eat food', false, 'ade24afa-10b6-40a2-8074-57d37af8b1f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1aa50c4c-53c3-4583-a943-682f4efa682d', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'What happened on a student''s ''Blind Day'' at Miss Beam''s school?', 'With bandaged eyes, the child experienced complete visual impairment, assisted by designated helpers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89634698-609a-430e-b609-a5a76446c125', 'Their eyes were bandaged absolutely, and they promised on honor not to peep; another child was assigned to guide them', true, '1aa50c4c-53c3-4583-a943-682f4efa682d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fe43b76-953a-476b-a043-69d86a88f06c', 'They had to wear dark sunglasses', false, '1aa50c4c-53c3-4583-a943-682f4efa682d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5eb0ce7b-daba-4355-8e4e-81a949986af0', 'They stayed locked in a dark room', false, '1aa50c4c-53c3-4583-a943-682f4efa682d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd4ead5c-8562-415a-9cb7-3b1e6b96b43d', 'They were not allowed to walk', false, '1aa50c4c-53c3-4583-a943-682f4efa682d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('697d3e7b-b0af-4baf-bf16-7d882d79f75d', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'Which day did the little girl confess to the author was by far the MOST DIFFICULT and awful day?', 'The Blind Day was the hardest because one feared bumping into things constantly and felt helpless in the dark.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14d6629e-9e5f-4b76-92b6-98c45a03ae6c', 'The Blind Day', true, '697d3e7b-b0af-4baf-bf16-7d882d79f75d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e940e666-8fd6-4a55-9f7c-53c7e95f5af9', 'The Lame Day', false, '697d3e7b-b0af-4baf-bf16-7d882d79f75d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ffd524b-cecd-4f31-a733-27929b8369e5', 'The Deaf Day', false, '697d3e7b-b0af-4baf-bf16-7d882d79f75d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b666c78-268e-41ce-b159-8d2ff1e3654b', 'The Dumb Day', false, '697d3e7b-b0af-4baf-bf16-7d882d79f75d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d26a6ea-21f5-4705-8f0b-260281ccd337', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'Why was the ''Dumb Day'' also extremely challenging for young children?', 'Without physical mouth bindings, maintaining total silence tested the child''s internal discipline.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b1fce67-c345-42d2-8501-3c8a18b0e0c8', 'Because the mouth could not be bandaged, so the child had to rely entirely on pure willpower and self-control to remain silent', true, '7d26a6ea-21f5-4705-8f0b-260281ccd337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6c39c41-486e-402b-812b-dca101a1b28a', 'Because they had to write 100 pages', false, '7d26a6ea-21f5-4705-8f0b-260281ccd337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4ec8164-1023-47d2-8e86-910e93ce11d0', 'Because they were not allowed to drink water', false, '7d26a6ea-21f5-4705-8f0b-260281ccd337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('125e3508-4bc8-4ef9-ba1b-379b506848f1', 'Because other children made jokes', false, '7d26a6ea-21f5-4705-8f0b-260281ccd337');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1875267b-f327-40e6-9820-16e1d74f82c1', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'In the supplementary story ''Tansen'', who was Tansen?', 'Tansen (originally Ramtanu Pandey) was India''s supreme classical musician in Akbar''s court.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29092d01-57d8-4b0d-85a6-abcdf4388f3b', 'The greatest and most famous musical maestro of India, one of the Navaratnas in Emperor Akbar''s court', true, '1875267b-f327-40e6-9820-16e1d74f82c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f50220f-1da2-4acb-a738-6b4dc38526ef', 'A famous king of Gwalior', false, '1875267b-f327-40e6-9820-16e1d74f82c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f1f815a-1016-44c4-a986-3165fd1e33cc', 'A royal commander of the army', false, '1875267b-f327-40e6-9820-16e1d74f82c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cd0f629-d72a-4fa7-85ae-adc597778d7e', 'A Persian painter', false, '1875267b-f327-40e6-9820-16e1d74f82c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b7026fb-005e-47f6-ae63-4f5b249f0e41', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'Where was Tansen born, as the only child of Mukandan Misra?', 'Tansen was born in Behat near Gwalior and studied music under the great master Swami Haridas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ced3a3a2-327b-4a1b-945e-a284372a2e76', 'Behat near Gwalior (Madhya Pradesh)', true, '2b7026fb-005e-47f6-ae63-4f5b249f0e41');
