INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce9ec015-572c-40b9-8142-e3aa472a827a', 'Varanasi', false, '2b7026fb-005e-47f6-ae63-4f5b249f0e41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23be44d5-42af-4142-b859-2ef954ed768a', 'Delhi', false, '2b7026fb-005e-47f6-ae63-4f5b249f0e41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5bb2fe98-6091-4148-b00f-df3e21374d82', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'What naughty animal trick did young Tansen play in the forest when he met Swami Haridas and his disciples?', 'Young Tansen had mastered mimicking bird and beast sounds, flawlessly roaring like a tiger.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80aeed9e-b042-453b-a64e-510f3e8b1ef1', 'He hid behind a tree and roared like a fierce tiger, frightening the whole traveling party', true, '5bb2fe98-6091-4148-b00f-df3e21374d82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a46fa97e-a7f2-4970-82a8-f705e65ec6f5', 'He threw stones at them', false, '5bb2fe98-6091-4148-b00f-df3e21374d82');
