INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3382b7e-5a03-462e-9081-e70f38e872a6', 'He sang like a monkey', false, '5bb2fe98-6091-4148-b00f-df3e21374d82');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('495689d7-5eb9-4f30-aeed-b305aa02bd13', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'For how many years did Tansen learn classical music under the tutelage of Swami Haridas?', 'Tansen spent eleven intensive years residing with Swami Haridas, mastering Hindustani classical ragas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc2511d5-ca5e-41cb-9e02-2b7ac90f0bab', '11 years', true, '495689d7-5eb9-4f30-aeed-b305aa02bd13');
