INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0501bd68-6029-4a2c-8636-06e4d9981c69', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'In which year did Tansen join the royal imperial court of Mughal Emperor Akbar?', 'Tansen entered Akbar''s court in 1556 and was elevated as one of the nine precious jewels (Navaratnas).', NOW()) ON CONFLICT DO NOTHING;
