INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb0d0127-e741-4a3e-b911-20621b334b77', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'In the poem ''Where Do All the Teachers Go?'' by Peter Dixon, what curious question does the child ponder?', 'The child''s innocent perspective wonders if authoritative teachers lead ordinary domestic lives at home.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22d539bb-f00e-4e12-93ea-e1f068eaf68c', 'Where teachers go at 4 o''clock, whether they live in ordinary houses, wear pyjamas, wash socks, and watch TV like normal people', true, 'fb0d0127-e741-4a3e-b911-20621b334b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7bbfb63-a953-42d0-9271-3f99d4205204', 'How teachers fly to space', false, 'fb0d0127-e741-4a3e-b911-20621b334b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fcba088-ebba-422c-8e3e-c5f0f0549cf1', 'Why teachers have no names', false, 'fb0d0127-e741-4a3e-b911-20621b334b77');
