INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52ce204b-443f-4d4a-a3ec-c0f5b9fed1c3', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What transformation did the author E.V. Lucas feel inside himself when he walked around Miss Beam''s school with the blindfolded girl?', 'Guiding the visually impaired girl heightened the author''s descriptive attentiveness and empathetic awareness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdcedb8d-e5b4-42a6-8db2-dda3553f47d9', 'He realized he had become ten times more thoughtful, observant, and sensitive to others than he ever thought possible', true, '52ce204b-443f-4d4a-a3ec-c0f5b9fed1c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('965ad953-0810-4794-8c96-8dc410238db7', 'He decided to become a headmaster', false, '52ce204b-443f-4d4a-a3ec-c0f5b9fed1c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9418a6a2-85be-4b4a-9eb4-55baa8eaf78f', 'He felt bored and wanted to leave', false, '52ce204b-443f-4d4a-a3ec-c0f5b9fed1c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0366f9ed-c6f8-44cc-8908-a408b0277432', 'He decided never to visit schools again', false, '52ce204b-443f-4d4a-a3ec-c0f5b9fed1c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b28e9ba7-1fdf-445d-99b4-bfe8f69af9c1', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Who was ''Millie'' whom the author and the blindfolded girl observed in the garden?', 'The author described the tall girl walking in the garden, whom his companion identified as Millie, the Head Girl.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6225bdc3-54e8-45fa-9d0d-5b0eae3b919f', 'The Head Girl of the school wearing a blue cotton skirt and pink blouse', true, 'b28e9ba7-1fdf-445d-99b4-bfe8f69af9c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd86c2a0-6414-4df1-a46d-a8374a7a3d56', 'A teacher', false, 'b28e9ba7-1fdf-445d-99b4-bfe8f69af9c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b295eefe-2c3f-40e7-88b8-44ace6b60cdd', 'The gardener', false, 'b28e9ba7-1fdf-445d-99b4-bfe8f69af9c1');
