INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f4b6596-3e71-46b3-adda-073eaee4129a', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Who was ''Peter'' in Miss Beam''s school garden?', 'Peter was the aged, devoted gardener seen by the author tying up flowering rose stems.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42c79d4b-57a5-4dfc-b3a4-b510cb0d95ed', 'The elderly gardener who was hundreds of years old (according to the girl) tying up roses', true, '0f4b6596-3e71-46b3-adda-073eaee4129a');
