INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3013b1b3-8867-40eb-ad13-caeb0ce407c9', 'A cook', false, '0f4b6596-3e71-46b3-adda-073eaee4129a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7d709e5-a51d-4f87-9ec8-68308989c277', 'A driver', false, '0f4b6596-3e71-46b3-adda-073eaee4129a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a574fce-b800-45df-b9ac-799a9a2c3cc1', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Why did jealous courtiers in Akbar''s court (led by Shaukat Mian) conspire to demand that Tansen sing ''Raga Deepak''?', 'The conspirators sought Tansen''s destruction, knowing pure Raga Deepak''s incandescent heat would incinerate the performer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ae363d9-7877-45f9-b9bf-2738750d87d8', 'If sung with absolute perfection, Raga Deepak creates such intense thermal heat that it lights lamps and burns the singer to ashes', true, '2a574fce-b800-45df-b9ac-799a9a2c3cc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef850ad0-46fe-4a8d-9135-63b5a92fdf3d', 'Because they wanted to dance', false, '2a574fce-b800-45df-b9ac-799a9a2c3cc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9918b73-3d83-4249-954e-507d9a50d50f', 'Because Raga Deepak makes everyone fall asleep', false, '2a574fce-b800-45df-b9ac-799a9a2c3cc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5f690af-183f-4272-9d46-d58920970e24', 'Because the Emperor was deaf', false, '2a574fce-b800-45df-b9ac-799a9a2c3cc1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1addeb5e-64f2-4ac0-8ac7-67ae6f19a31e', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'How did Tansen brilliantly counter the lethal heat of Raga Deepak and save his life?', 'Tansen coordinated Raga Megh (rain raga) to trigger atmospheric precipitation the moment Raga Deepak sparked flames.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9153d70-39ca-49b6-8363-928cdff0c3d8', 'He trained his daughter Saraswati and her friend Rupvati to sing ''Raga Megh'' simultaneously, bringing torrents of cooling rain the moment the air grew hot and lamps lit up', true, '1addeb5e-64f2-4ac0-8ac7-67ae6f19a31e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6c486c0-5722-4fa5-9761-fa920ef18fcb', 'He poured cold water over himself while singing', false, '1addeb5e-64f2-4ac0-8ac7-67ae6f19a31e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3edb6134-8bfa-43f6-8883-bf01ca9d4408', 'He refused to sing before Akbar', false, '1addeb5e-64f2-4ac0-8ac7-67ae6f19a31e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c053038f-095c-4e8b-a8ef-cf6b37a329ab', 'He fled to another country', false, '1addeb5e-64f2-4ac0-8ac7-67ae6f19a31e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fafe130-f593-4a50-bd01-9afd9131f53f', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What happened when Tansen began singing Raga Deepak in Akbar''s court on the appointed day?', 'His acoustic harmonics manifested physical thermal phenomena, lighting the palace oil lamps.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ed9fbac-ce18-40f5-8662-a8f9ce2622d8', 'The air grew intensely warm, audience perspired, leaves dried up on trees, birds fell dead, river boiled, and unlit lamps suddenly burst into flame', true, '6fafe130-f593-4a50-bd01-9afd9131f53f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a11ccacf-91a7-493d-9dfe-0ad73d8b24ec', 'Snow began falling in the hall', false, '6fafe130-f593-4a50-bd01-9afd9131f53f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1ee4c44-3cc6-4077-b8b5-b2d57e64cf3f', 'The Emperor fell unconscious', false, '6fafe130-f593-4a50-bd01-9afd9131f53f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79f1a526-cbb6-4ae7-8ecf-b71e6635de3c', 'The palace collapsed', false, '6fafe130-f593-4a50-bd01-9afd9131f53f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d23ce996-b0d5-4ddd-a2f1-cc84d09b6242', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What did Emperor Akbar do when he discovered the malicious plot of the jealous courtiers against Tansen?', 'Akbar rejoiced in Tansen''s recovery from illness, severely penalizing the conspirators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('821ee5d2-d2ad-4ec7-9ef3-03194722c8b1', 'He severely punished the wicked courtiers and rewarded Tansen with great honor and royal treasures', true, 'd23ce996-b0d5-4ddd-a2f1-cc84d09b6242');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e511f653-f4ec-4ead-a0c7-fec8d0387e0e', 'He banned music in India', false, 'd23ce996-b0d5-4ddd-a2f1-cc84d09b6242');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fc1a66c-700e-443d-bb9b-a1a4007e0d9e', 'He dismissed Tansen from court', false, 'd23ce996-b0d5-4ddd-a2f1-cc84d09b6242');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b287ab1b-3f31-405b-ad94-f072f202ed24', 'He gave his crown to Tansen', false, 'd23ce996-b0d5-4ddd-a2f1-cc84d09b6242');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dde4ef04-2cfc-40b1-a22a-765d4ee2302a', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Where is the historic tomb of Tansen situated, revered as a place of pilgrimage for musicians?', 'Tansen''s tomb in Gwalior is a celebrated pilgrimage monument where an annual national music festival is hosted.', NOW()) ON CONFLICT DO NOTHING;
