INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3230fb5-22fc-41b2-8680-f84e13fe7e42', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What is the meaning of the word ''Thoughtfulness'' as used by Miss Beam?', 'Thoughtfulness transcends academic intellect to signify active empathy, social responsibility, and human kindness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb9f1b12-79b9-494b-b8fa-449d52d77eae', 'Being considerate, empathetic, caring, and attentive to the needs and feelings of others', true, 'c3230fb5-22fc-41b2-8680-f84e13fe7e42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c8a5dc1-eb2a-4193-9973-6d31e22e422a', 'Thinking about examination marks', false, 'c3230fb5-22fc-41b2-8680-f84e13fe7e42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cec5f25d-0372-47ed-8bec-2bd39f8f5f3d', 'Sitting quietly in a room', false, 'c3230fb5-22fc-41b2-8680-f84e13fe7e42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a14a913-21ed-4f60-9300-66091711180f', 'Reading many books', false, 'c3230fb5-22fc-41b2-8680-f84e13fe7e42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('511c0a12-2fb9-44b0-9fed-3507949546a0', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What was the rule for the other children assigned as ''Helpers'' to a blind child for the day?', 'Helpers developed acute observational and communication skills while experiencing the vital importance of assisting others.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eb5162d-86e0-4cef-95dd-12c4d8f209e5', 'They had to guide them around everywhere and explain the world to them, learning as much about empathy as the blind child', true, '511c0a12-2fb9-44b0-9fed-3507949546a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a636f3d1-d383-4c0e-a6c8-5b72bdc50f2a', 'They had to carry the blind child on their shoulders', false, '511c0a12-2fb9-44b0-9fed-3507949546a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ce27c7a-2977-4118-833f-bd61332d746d', 'They had to do all their homework', false, '511c0a12-2fb9-44b0-9fed-3507949546a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa849aa8-ebfb-44a3-b6be-535fe3180941', 'They had to give them money', false, '511c0a12-2fb9-44b0-9fed-3507949546a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('536b9611-28ac-4599-b74b-021ddad223d8', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'In the poem ''Where Do All the Teachers Go?'', what childish misbehavior does the poet wonder if teachers also committed as kids?', 'The poem playfully deconstructs the infallibility of teachers by imagining them as mischievous children.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfc771bc-72ad-420d-bf68-b3bee843264e', 'Losing their hymn books, picking their noses, spelling words wrong, making mistakes, and pinching chocolate flakes', true, '536b9611-28ac-4599-b74b-021ddad223d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56237bd9-8a68-4d1f-ac0d-0fe15eeac492', 'Stealing cars', false, '536b9611-28ac-4599-b74b-021ddad223d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f2390cc-1922-4364-986a-ef55582bda09', 'Flying kites on rooftops', false, '536b9611-28ac-4599-b74b-021ddad223d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1964b443-38e4-4af2-8678-2cfdc1338af4', 'Fighting in battles', false, '536b9611-28ac-4599-b74b-021ddad223d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2640724-01a0-4828-bfde-011ad6222dc7', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What did the poet Peter Dixon plan to do one day to solve the mystery of teachers?', 'The speaker schemes to follow a teacher home after school and compose a poem revealing their ordinary domestic life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beaae852-b799-4bda-a86c-8cb7ad58ec06', 'Follow one teacher home all the way after school to see what they do, and write a poem about it for other children to read', true, 'a2640724-01a0-4828-bfde-011ad6222dc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b474ae0-4c59-42f0-99a7-b9677c0df77b', 'Ask the police to investigate', false, 'a2640724-01a0-4828-bfde-011ad6222dc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13d2e537-a08a-4c54-b2c1-89e761b64c94', 'Hide inside the teacher''s car', false, 'a2640724-01a0-4828-bfde-011ad6222dc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4014ae19-9997-46ce-8fc9-d1b6d17a5ba8', 'Call the newspaper', false, 'a2640724-01a0-4828-bfde-011ad6222dc7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1964d5b-b2aa-420d-9d4a-94e036f51d75', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What does the word ''Peep'' mean in: ''They promise on their honour not to peep''?', '''Peep'' means to take a quick, illicit, surreptitious glance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f791753-0335-4d8a-befc-8e1ffd565637', 'To look quickly or secretly through a small opening or under the bandage', true, 'c1964d5b-b2aa-420d-9d4a-94e036f51d75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f398c654-f3a4-441d-9723-eab01dd86447', 'To make a bird sound', false, 'c1964d5b-b2aa-420d-9d4a-94e036f51d75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95850446-b0a7-4791-8491-a92f23dbdc02', 'To shout loudly', false, 'c1964d5b-b2aa-420d-9d4a-94e036f51d75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9150924-e1ee-4405-8e50-32a86bf9ea5c', 'To run fast', false, 'c1964d5b-b2aa-420d-9d4a-94e036f51d75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('163fbd48-7992-4fc9-8257-c44922514e00', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Who was Mohammad Ghaus in Tansen''s musical life?', 'Mohammad Ghaus was a venerated Sufi mystic who fostered Tansen''s early musical and spiritual genius in Gwalior.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6adfe39f-18b7-4045-a9b2-43927534cec1', 'A holy Sufi saint of Gwalior with whom Tansen lived and received deep spiritual and musical blessings', true, '163fbd48-7992-4fc9-8257-c44922514e00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8a83811-adeb-407d-a478-72cc3d4c2145', 'A rival musician', false, '163fbd48-7992-4fc9-8257-c44922514e00');
