INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6af75f80-8314-4114-bc04-d66d2958c51f', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Whom did Tansen marry from the court of Rani Mrignayani of Gwalior?', 'Tansen married Hussaini, a talented court singer from Rani Mrignayani''s entourage.', NOW()) ON CONFLICT DO NOTHING;
