INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3895d0a3-1fee-47d0-8532-c1a8d6129e73', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What is the overarching educational message of ''A Different Kind of School''?', 'The narrative emphasizes that moral character and active humanitarian empathy represent the highest aims of pedagogy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f01de46d-38ec-4a27-b9c4-de48a2bd4e8d', 'True education must cultivate emotional intelligence, empathetic social consciousness, and mutual care rather than mere mechanical rote learning', true, '3895d0a3-1fee-47d0-8532-c1a8d6129e73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1dc0592-643f-4f39-b5dc-10468d899f91', 'Children should never go to school', false, '3895d0a3-1fee-47d0-8532-c1a8d6129e73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41cd9976-ff5e-4af1-bdfd-9c527891a25c', 'Disabled people do not need help', false, '3895d0a3-1fee-47d0-8532-c1a8d6129e73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82c03d5b-5db1-47bc-8f6b-7eb7b8f50a2b', 'Schools should only teach games', false, '3895d0a3-1fee-47d0-8532-c1a8d6129e73');
