INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d5274d6-1d14-492a-b5a2-bae5c88d5217', 'Thoughtful - Inconsiderate', false, 'ad03c328-9e2d-443e-bcaf-46f3082b6328');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b55888cc-fbc8-4f0a-b76c-224759eaf712', 'Ghastly - Extremely pleasant', true, 'ad03c328-9e2d-443e-bcaf-46f3082b6328');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('555dfb89-419a-4024-9d4b-09afd8adf731', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'In ''Tansen'', how did the musical duel between Raga Deepak and Raga Megh symbolize the cosmic balance of classical Indian music?', 'Classical Indian music theory holds that ragas evoke elemental resonances (Agni vs Varuna) in cosmic equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b00a6561-ca1a-4caa-89d0-481784042a92', 'It demonstrated that acoustic vibrations correspond to fundamental cosmic forces (Fire/Agni and Water/Varuna) that must remain harmoniously balanced', true, '555dfb89-419a-4024-9d4b-09afd8adf731');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('987ea9b1-7a41-40f6-87a6-aae468f4cb5f', 'It proved that singing was louder than drums', false, '555dfb89-419a-4024-9d4b-09afd8adf731');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('411c927d-4fa2-4bff-b65a-9cff9edb00d4', 'It showed that kings can control weather', false, '555dfb89-419a-4024-9d4b-09afd8adf731');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26d609b5-c19a-4d18-91ef-7d8e8874b90f', 'It proved that courtiers were better singers', false, '555dfb89-419a-4024-9d4b-09afd8adf731');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a639f727-f4a3-4a4f-876b-f58ed7bd5d62', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'Match the following disabilities with the specific challenges described by the children in Miss Beam''s school:
(a) Blind Day   -> (i) Constant fear of being hit by unseen obstacles
(b) Lame Day    -> (ii) Having one leg tied up and hopping on crutches (fun for some)
(c) Injured Day -> (iii) Having an arm tied up so one cannot eat or dress alone
(d) Dumb Day    -> (iv) Constant test of internal willpower to prevent speaking', 'Blind = fear of collisions; Lame = crutch hopping; Injured = tied arm; Dumb = willpower silence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dac4710-e156-4d5e-ade2-475f8cfcfaf6', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'a639f727-f4a3-4a4f-876b-f58ed7bd5d62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53e4e2c5-45cd-421c-a679-ad9bcd8d1e57', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'a639f727-f4a3-4a4f-876b-f58ed7bd5d62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64bf15fa-bf49-46be-a755-8ace8afc68d7', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'a639f727-f4a3-4a4f-876b-f58ed7bd5d62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33f61ad5-10cd-41c4-9095-80a4f25edfe9', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'a639f727-f4a3-4a4f-876b-f58ed7bd5d62');
