INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1373076b-b8eb-47b4-bde2-b07dd290b909', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'Identify the figure of speech used in the line: ''The leaves dried up and fell to the ground, the rivers boiled, and unlit lamps burst into flame.''', 'Hyperbolic legendary imagery depicts the supernatural intensity of Tansen''s perfect raga.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6f8891c-e10b-45a4-80cb-1cdb8a6d4ce8', 'Hyperbole (poetic deliberate exaggeration for dramatic acoustic impact)', true, '1373076b-b8eb-47b4-bde2-b07dd290b909');
