INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92ab13b8-31b9-446d-8861-f94dc99a68d7', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'What does the word ''Mischief'' or ''Mischievous'' mean when describing young Tansen in the forest?', 'Mischief refers to playful, harmless pranks driven by childhood curiosity and high spirits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d80edd1d-1ad2-494b-97e7-9a2908fa6ee1', 'Playfully troublesome, full of tricks, but without intending malicious harm', true, '92ab13b8-31b9-446d-8861-f94dc99a68d7');
