INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16ea402b-7264-4f06-8c46-710c086088d2', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'In ''Where Do All the Teachers Go?'', what poetic perspective does Peter Dixon capture?', 'The poem explores the innocent cognitive duality where children view teachers as flawless, mythical entities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8735f210-b0a5-40b8-bfe8-6f0d3abd6b91', 'The innocent childhood wonder that perceives adult authority figures as supernatural beings devoid of mundane domestic routines', true, '16ea402b-7264-4f06-8c46-710c086088d2');
