INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e60f1d78-dff3-4d51-986a-8af2ec105230', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'Why did the little blindfolded girl describe her guiding experience as ''making her realize so many things she never thought of before''?', 'Sensory deprivation stimulates acute neuro-auditory perception and profound cognitive re-evaluation of the environment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62cf3942-da61-4621-85b3-7259980353cf', 'Because when one cannot see, other senses (hearing, spatial touch, imagination) sharpen intensely to perceive subtle realities', true, 'e60f1d78-dff3-4d51-986a-8af2ec105230');
