INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('018dd335-492c-470e-931e-115f80674197', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'What philosophical synthesis unites both stories in Chapter 5 (''A Different Kind of School'' and ''Tansen'')?', 'Both classic texts elevate human excellence: ethical empathy in pedagogical training and transcendental devotion in classical art.', NOW()) ON CONFLICT DO NOTHING;
