INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9755e40-93d6-409f-abc5-cc2235104d94', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'What is the narrow strip of land connecting North America and South America, and separating the Atlantic Ocean from the Pacific Ocean?', 'An Isthmus is a narrow strip of land joining two landmasses; the Isthmus of Panama bridges North and South America.', NOW()) ON CONFLICT DO NOTHING;
