INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1150cefc-8437-4d06-97e0-6f01f879f6b1', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'What is a narrow passage of water connecting two large bodies of water (such as seas and oceans) called?', 'A strait is a narrow navigable marine channel linking two larger oceans or seas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7226c44-4fbd-4534-bde8-0ef73b961bfb', 'A Strait (e.g. Palk Strait, Bering Strait)', true, '1150cefc-8437-4d06-97e0-6f01f879f6b1');
