INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9957aa7a-33f0-4c1e-b06d-a5fe4aacde6b', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'Which ocean is ''S-shaped'' and is the BUSIEST ocean in the world from the point of view of international maritime trade?', 'The Atlantic''s highly indented coastline creates abundant natural harbors, making it the most heavily trafficked commercial sea route.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a15ee36-a678-441f-8ebb-97d870ae646a', 'Atlantic Ocean', true, '9957aa7a-33f0-4c1e-b06d-a5fe4aacde6b');
