INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd22c085-8378-49ed-980b-8d22aea1b4c2', 'Indian Ocean', false, '9957aa7a-33f0-4c1e-b06d-a5fe4aacde6b');
