INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5dc3c23-4066-4102-9c18-728c8c39737b', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'Which continent is permanently covered with thick ice sheets, completely uninhabited by native human populations, and reserved exclusively for scientific research?', 'Antarctica is governed by the Antarctic Treaty of 1959 as a demilitarized scientific preserve hosting research stations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b1dcbe8-d1c2-44ea-b468-69e9dc88fc3b', 'Antarctica (the White Continent / South Pole)', true, 'a5dc3c23-4066-4102-9c18-728c8c39737b');
