INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0e44093-9c83-44fc-8809-6ba9bd197e14', 'Australia', false, 'a5dc3c23-4066-4102-9c18-728c8c39737b');
