INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17448f13-1cea-4acc-bda6-ffe2035752fa', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'What are the names of the two Indian permanent research stations operating in Antarctica?', 'Maitri (established 1989) and Bharati (established 2012) are active Indian research facilities in Antarctica.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('946e2178-f095-45b5-b7bc-835efd5774a9', 'Maitri and Bharati (along with historic Dakshin Gangotri)', true, '17448f13-1cea-4acc-bda6-ffe2035752fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f90c009d-9225-489a-9a5a-d891eedfb738', 'Himadri and Indira', false, '17448f13-1cea-4acc-bda6-ffe2035752fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36059ed5-68a7-4d93-a65f-3b947e255c84', 'Sagar and Shakti', false, '17448f13-1cea-4acc-bda6-ffe2035752fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daf17652-62fb-4337-98ab-78283b6e4fab', 'Kalam and Sarabhai', false, '17448f13-1cea-4acc-bda6-ffe2035752fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('261d3166-b251-43bb-835a-25e9638f43c8', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'What are the FIVE vertical layers of the Earth''s atmosphere arranged starting from the Earth''s surface upwards?', 'Thermal atmospheric stratification: Troposphere (0-12 km), Stratosphere (12-50 km), Mesosphere (50-80 km), Thermosphere (80-700 km), and Exosphere (>700 km).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d095d70-d181-4d9b-b40d-e7484eca24ea', 'Troposphere -> Stratosphere -> Mesosphere -> Thermosphere -> Exosphere', true, '261d3166-b251-43bb-835a-25e9638f43c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('243fb6ae-1c4a-4d89-8f44-35e0cc2abd01', 'Stratosphere -> Troposphere -> Mesosphere -> Exosphere -> Thermosphere', false, '261d3166-b251-43bb-835a-25e9638f43c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79aa0ae8-0824-43ae-9d8e-497a70bfd8ad', 'Exosphere -> Thermosphere -> Mesosphere -> Stratosphere -> Troposphere', false, '261d3166-b251-43bb-835a-25e9638f43c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eb0858f-c7f7-40dc-9682-376c18633756', 'Troposphere -> Mesosphere -> Stratosphere -> Thermosphere -> Ionosphere', false, '261d3166-b251-43bb-835a-25e9638f43c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc4973bb-ef7a-4df6-b204-1cf57c6d5341', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'Why is Earth uniquely called the ''Blue Planet'' and the ''Water Planet''?', 'Rayleigh scattering of solar light across oceans covering 71% of Earth''s surface yields our planetary blue hue.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0322bb4-80ac-4097-bf32-f5ff14a66eb8', 'More than 71% of Earth''s surface is covered with water, giving it a brilliant azure-blue appearance from outer space', true, 'dc4973bb-ef7a-4df6-b204-1cf57c6d5341');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85e8149b-21fb-46b2-a045-2d56b784a408', 'Because the sky reflects blue paint', false, 'dc4973bb-ef7a-4df6-b204-1cf57c6d5341');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('998ace6c-69f9-4ca7-8413-d1a1da913a04', 'Because mountains are blue', false, 'dc4973bb-ef7a-4df6-b204-1cf57c6d5341');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e48884c9-5d49-4c2c-8985-3a6f260af600', 'Because trees are blue in space', false, 'dc4973bb-ef7a-4df6-b204-1cf57c6d5341');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae784641-4827-4367-a254-5020475c46ff', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'Despite Earth having 71% water, why do humans and land ecosystems face acute freshwater shortages?', 'Only ~0.3% of global water is accessible liquid freshwater in rivers, freshwater lakes, and shallow aquifers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dbe25ec-4b23-48bc-bdce-93614c42e8af', 'More than 97% of Earth''s water is saline seawater in oceans, and of the remaining 3% freshwater, most is locked in polar ice sheets and glaciers', true, 'ae784641-4827-4367-a254-5020475c46ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aeae07ee-5cc7-4de3-be00-1d32fa353628', 'Because water evaporates into outer space', false, 'ae784641-4827-4367-a254-5020475c46ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('640a3eec-23ee-4b64-8958-d719e7521d02', 'Because clouds take water away', false, 'ae784641-4827-4367-a254-5020475c46ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73c6cc8f-09b2-4b6d-a51e-1ed976312de3', 'Because rivers do not flow', false, 'ae784641-4827-4367-a254-5020475c46ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e8f0d73-25a3-4af7-9f95-ec6548ea5c0c', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'What is the crucial biological role of Carbon Dioxide (CO₂) in the atmosphere, despite its small concentration (0.03%)?', 'Radiative greenhouse forcing by CO₂ maintains Earth''s mean surface temperature at +15°C instead of a freezing -18°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('092b7227-4a4b-43c2-b4af-cee3b8933870', 'It absorbs infrared heat radiated by the Earth (Greenhouse effect) to keep the planet comfortably warm and livable, and plants use it for photosynthesis', true, '9e8f0d73-25a3-4af7-9f95-ec6548ea5c0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96aae2cf-4873-40fc-b996-f9b69b8ee382', 'It freezes the oceans', false, '9e8f0d73-25a3-4af7-9f95-ec6548ea5c0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d620fcb7-7048-4295-9e2d-bada19a12d46', 'It produces rain directly', false, '9e8f0d73-25a3-4af7-9f95-ec6548ea5c0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71b1c781-1404-44e3-b85a-18cfb257eebe', 'It makes rocks hard', false, '9e8f0d73-25a3-4af7-9f95-ec6548ea5c0c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89dd104a-c082-4645-8cda-b1a85e64fd35', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'Why does atmospheric density and air pressure decrease rapidly with increasing altitude as mountaineers climb high Himalayan peaks?', 'Barometric hypsometric formula: atmospheric pressure drops exponentially with height, reducing the partial pressure of oxygen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('567f3fbe-279b-481f-bd5e-3d9210a5d638', 'Earth''s gravitational attraction compresses air molecules near sea level; at high altitudes, air molecules spread apart, causing lower oxygen pressure and breathing difficulty', true, '89dd104a-c082-4645-8cda-b1a85e64fd35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0ad3943-7fc2-4d44-8b4f-202e48d4fdde', 'Air is blown away by satellites', false, '89dd104a-c082-4645-8cda-b1a85e64fd35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f179fce-c753-4587-917a-25c1b60f5c0f', 'Sunlight destroys air at high altitude', false, '89dd104a-c082-4645-8cda-b1a85e64fd35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f590698-f04e-4baf-bec3-def3255447a1', 'Clouds push air down', false, '89dd104a-c082-4645-8cda-b1a85e64fd35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('788b58a5-3eb4-4750-aed4-15123fad2470', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Read the statements:
