INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e239d099-10a6-44d7-9192-5590452305dc', '(A) is false, but (R) is true.', false, '788b58a5-3eb4-4750-aed4-15123fad2470');
