INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81135003-30e0-4dba-b569-9c73e223fa49', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Who were the first mountaineers to conquer and step onto the highest summit of Mount Everest on 29th May 1953?', 'Edmund Hillary and Tenzing Norgay achieved the historic first confirmed ascent of Mount Everest in the 1953 British expedition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edc7c053-5b9a-46a6-a7b7-4a7f21130744', 'Sir Edmund Hillary (New Zealand) and Tenzing Norgay Sherpa (India/Nepal)', true, '81135003-30e0-4dba-b569-9c73e223fa49');
