INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('277726f8-5113-4f18-a7a7-372816434f02', 'Reinhold Messner and Peter Habeler', false, '81135003-30e0-4dba-b569-9c73e223fa49');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('df61dcb9-5034-4146-a2d2-7ed8e05370c5', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Match Column I (Earth Domains & Features) with Column II (Definitions & Examples):
(a) Lithosphere -> (i) Gaseous envelope held by gravity
(b) Hydrosphere -> (ii) Solid rock crust and continental landmasses
(c) Atmosphere  -> (iii) 71% planetary ocean and surface water realm
(d) Biosphere   -> (iv) Narrow zone of contact supporting all living organisms', 'Lithosphere = rock crust; Hydrosphere = 71% water; Atmosphere = gas envelope; Biosphere = life zone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c063c0e2-2500-4014-bf88-eef5dbfc733f', 'a-(ii), b-(iii), c-(i), d-(iv)', true, 'df61dcb9-5034-4146-a2d2-7ed8e05370c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9de027f-f363-48d1-8a67-1daf69360e74', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'df61dcb9-5034-4146-a2d2-7ed8e05370c5');
