INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('478c1755-27b9-4321-a10d-19d187dc8bb8', 'Statements 1 and 3 only', true, '17acb831-3ce7-4eba-bd16-a3b7c5717d2c');
