INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('700e7139-86a2-4950-9973-3d9fc2b7c766', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'What is the oceanic body surrounding the continent of Antarctica, formed by the southward extension of the Pacific, Atlantic, and Indian Oceans?', 'The Southern Ocean encompasses the circumpolar Antarctic waters south of 60° S, connected by the Antarctic Circumpolar Current.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db2947af-468f-452a-8743-850ff2e1b8b2', 'The Southern Ocean (or Antarctic Ocean, extending up to 60° S latitude)', true, '700e7139-86a2-4950-9973-3d9fc2b7c766');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('693abbe5-0d2f-4623-8cdc-f25eaed46bc6', 'Arctic Ocean', false, '700e7139-86a2-4950-9973-3d9fc2b7c766');
