INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d0eb13a-31eb-4dca-8bfb-c9ccc44a031b', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Which narrow strait connects the Arctic Ocean with the Pacific Ocean between Alaska (USA) and Siberia (Russia)?', 'The Bering Strait connects the Arctic Chukchi Sea with the Pacific Bering Sea across an 82 km maritime passage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b9c768a-381f-45f9-a6a7-8d58811f5152', 'Bering Strait', true, '8d0eb13a-31eb-4dca-8bfb-c9ccc44a031b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b90043d9-b6e8-4ded-92b7-45dc703e3fa2', 'Strait of Gibraltar', false, '8d0eb13a-31eb-4dca-8bfb-c9ccc44a031b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63a313e0-925d-44f8-8d69-fdc2a0b819bd', 'Palk Strait', false, '8d0eb13a-31eb-4dca-8bfb-c9ccc44a031b');
