INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f22a9d12-25b4-420d-b2f4-22a268c916f1', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Why is the elevation of any land point on Earth always measured from Sea Level, and why is Sea Level taken as zero everywhere?', 'Hydrostatic communicability ensures the global marine surface conforms to an equipotential gravitational geoid serving as the datum (0 m elevation).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fddc5ba-880d-4bdd-9fe1-b7559b1eec78', 'All the interconnected oceans of the world maintain a uniform, continuous hydrostatic surface level at equilibrium (Mean Sea Level = 0 m)', true, 'f22a9d12-25b4-420d-b2f4-22a268c916f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd9d47cb-5666-4439-8383-536c7c03171a', 'Because oceans have no weight', false, 'f22a9d12-25b4-420d-b2f4-22a268c916f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69d2f8ff-0545-46e0-a913-64d726d26718', 'Because sea water cannot be measured', false, 'f22a9d12-25b4-420d-b2f4-22a268c916f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ad133b1-d632-4367-a46a-18919e9991ef', 'Because land sinks every year', false, 'f22a9d12-25b4-420d-b2f4-22a268c916f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2643c960-3e0f-4285-9886-e4d163a785e6', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Consider four atmospheric gases:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0fd539c-e473-44f4-9d39-601e605a75fe', '1 -> 2 -> 3 -> 4', true, '2643c960-3e0f-4285-9886-e4d163a785e6');
