INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4dab81a-1ce8-41b6-853c-3f6022a32414', '1 -> 2 -> 4 -> 3', false, '2643c960-3e0f-4285-9886-e4d163a785e6');
