INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39214ad3-aac7-434f-94a3-6c05ee69352b', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'What is the combined landmass consisting of Europe and Asia joined together without any oceanic separation called?', 'Europe and Asia form a single contiguous tectonic landmass termed Eurasia, demarcated geographically by the Ural Mountains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('601f8948-ff8c-4ec1-9e39-79dd3fb69030', 'Eurasia', true, '39214ad3-aac7-434f-94a3-6c05ee69352b');
