INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ab415df-3ac4-40c0-bed6-947b63b78888', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Who was the FIRST Indian woman to climb the summit of Mount Everest on 23rd May 1984?', 'Bachendri Pal became the first Indian woman and fifth woman in the world to reach the peak of Mount Everest in 1984.', NOW()) ON CONFLICT DO NOTHING;
