INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4bd3a194-cf65-4565-96f9-23ec4e784f75', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Why is human disturbance in one domain of the Earth (e.g. cutting forests in the Lithosphere or emitting gases into Atmosphere) directly detrimental to all other domains?', 'Earth Systems Science shows complex feedback loops (carbon cycle, hydrologic cycle) link all spheres into a single interdependent ecosystem.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('686e9cb7-1eed-42db-b565-b9c1387362f4', 'All four domains (Lithosphere, Hydrosphere, Atmosphere, Biosphere) are dynamically interconnected in continuous thermodynamic and biogeochemical nutrient cycles', true, '4bd3a194-cf65-4565-96f9-23ec4e784f75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ca8d7fc-714b-4e3c-8adf-61f7d80aea8e', 'Because Earth is made of glass', false, '4bd3a194-cf65-4565-96f9-23ec4e784f75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9b0ff27-01e0-432c-a593-cdd1a2780419', 'Because oceans will dry up in one second', false, '4bd3a194-cf65-4565-96f9-23ec4e784f75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5b34119-743c-4238-a601-260c3ba9003e', 'Because gravity will stop working', false, '4bd3a194-cf65-4565-96f9-23ec4e784f75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03c44ff6-94b0-458b-ab69-10d380ce12da', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'संज्ञा शब्द के जिस रूप से उसके पुरुष जाति (नर) या स्त्री जाति (मादा) होने का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'संज्ञा के जाति-निर्धारक रूप (पुरुष या स्त्री जाति के बोधक चिह्न) को ''लिंग'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
