INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74382a47-30a6-462d-8e08-2d43faee77d2', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'हिंदी भाषा में मुख्य रूप से लिंग के कितने भेद (प्रकार) होते हैं?', 'हिंदी में केवल दो लिंग होते हैं: 1. पुल्लिंग (Masculine) तथा 2. स्त्रीलिंग (Feminine)। (संस्कृत की तरह नपुंसक लिंग हिंदी में नहीं होता)।', NOW()) ON CONFLICT DO NOTHING;
