INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('819797a1-fd2c-4312-912e-83e047c53c51', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'जिन संज्ञा शब्दों से पुरुष जाति (Male) का बोध होता है, उन्हें क्या कहते हैं?', 'पुरुषत्व का बोध कराने वाले संज्ञा शब्द पुल्लिंग कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
