INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77373b70-1dfa-497c-a171-a78dcb9c7bb2', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'निम्नलिखित में से ''पुल्लिंग'' शब्द का सही उदाहरण कौन-सा है?', 'पर्वतों के नाम (हिमालय), देशों के नाम (भारत), दिनों के नाम (सोमवार), तथा धातुओं के नाम (लोहा) सदैव पुल्लिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5abea53-9378-4c00-9ff6-7fd7bcec075c', 'हिमालय, भारत, सोमवार, लोहा', true, '77373b70-1dfa-497c-a171-a78dcb9c7bb2');
