INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('706f01f3-ea70-4f40-b324-da91fa6227ce', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'निम्नलिखित में से ''स्त्रीलिंग'' शब्द का सही उदाहरण कौन-सा है?', 'नदियों के नाम (गंगा), भाषाओं के नाम (हिंदी), लिपियों के नाम (देवनागरी), तथा तिथियों के नाम स्त्रीलिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
