INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb701046-110a-4341-a442-7698f7fb5207', 'दूध, पानी, तेल, घी', false, '706f01f3-ea70-4f40-b324-da91fa6227ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ce8ef36-098a-4a99-9dce-cb58b4bf37ec', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''कवि'' का सही स्त्रीलिंग रूप क्या है?', '''कवि'' का मानक शुद्ध स्त्रीलिंग वर्तनी रूप ''कवयित्री'' (क + व + यि + त्री) है।', NOW()) ON CONFLICT DO NOTHING;
