INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fd1e793-88fa-4ed3-9870-121fcda23026', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''सम्राट'' का सही स्त्रीलिंग रूप क्या है?', 'संस्कृत तत्सम नियम के अनुसार ''सम्राट'' का स्त्रीलिंग ''सम्राज्ञी'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1c1102f-88e6-47a7-93a8-930874ab3836', 'सम्राज्ञी', true, '2fd1e793-88fa-4ed3-9870-121fcda23026');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23ef84ee-759f-4cf2-a110-98db70a2b63c', 'सम्राटिनी', false, '2fd1e793-88fa-4ed3-9870-121fcda23026');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a438ba3-f901-454f-9c4b-55b58cc4d951', 'सम्राटी', false, '2fd1e793-88fa-4ed3-9870-121fcda23026');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f01867f2-7fc2-4e5e-8811-69aff4ca3f2b', 'रानी', false, '2fd1e793-88fa-4ed3-9870-121fcda23026');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b12a5e6-9861-4ba3-90fe-1ae3fa746ed1', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''नेता'' और ''अभिनेता'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', '''ता'' का ''त्री'' में परिवर्तन: नेता -> नेत्री; अभिनेता -> अभिनेत्री; धाता -> धात्री।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0133d9a9-a7f4-4740-949e-b90f7de79721', 'नेत्री और अभिनेत्री', true, '8b12a5e6-9861-4ba3-90fe-1ae3fa746ed1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15316f57-6a8e-4c41-841e-7956a56fb94e', 'नेतिन और अभिनेतिन', false, '8b12a5e6-9861-4ba3-90fe-1ae3fa746ed1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32e9f955-5736-4322-a27d-838b64df9d25', 'नेताइन और अभिनेत्र', false, '8b12a5e6-9861-4ba3-90fe-1ae3fa746ed1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72fbf9d4-69c8-4b2f-8d76-dd88fe6958c6', 'नेती और अभिनेती', false, '8b12a5e6-9861-4ba3-90fe-1ae3fa746ed1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75407c0d-2481-43f5-8679-18774a07679e', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''वर'' और ''साधु'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', 'वर का स्त्रीलिंग ''वधू'' तथा साधु का स्त्रीलिंग ''साध्वी'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60f31d99-ccc0-4aa5-91fd-f4f290aacad2', 'वधू और साध्वी', true, '75407c0d-2481-43f5-8679-18774a07679e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bed1b10-cf0f-4132-85bf-abcfd6442fc8', 'वधु और साधुनी', false, '75407c0d-2481-43f5-8679-18774a07679e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed97acf1-32a5-48ab-9962-07ff843f843c', 'पत्नी और सन्यासिनी', false, '75407c0d-2481-43f5-8679-18774a07679e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('696b5bc5-d806-4ace-8d68-8c77a059a75e', 'दुल्हन और औरत', false, '75407c0d-2481-43f5-8679-18774a07679e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa64b516-2361-4aae-b46b-adb6fc116f18', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''बैल'' और ''पुरुष'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', 'भिन्न रूप वाले स्वतंत्र युग्म: बैल -> गाय; पुरुष -> स्त्री; पिता -> माता; भाई -> बहन।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21bb8eb1-6f01-464a-922a-f04af0808431', 'गाय और स्त्री', true, 'fa64b516-2361-4aae-b46b-adb6fc116f18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6497376-7f88-448f-856f-163fd1f4a764', 'भैंस और नारी', false, 'fa64b516-2361-4aae-b46b-adb6fc116f18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81b97470-a641-4397-b035-2360a5ff2531', 'गौ और औरत', false, 'fa64b516-2361-4aae-b46b-adb6fc116f18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('037cdbd1-b3b3-43f5-9779-21f45ed50b1d', 'गाय और महिला', false, 'fa64b516-2361-4aae-b46b-adb6fc116f18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6eb9fe70-1cda-41d2-854c-95161e45d5f1', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'वे शब्द जो पद, व्यवसाय या ओहदे के सूचक होते हैं और स्त्री व पुरुष दोनों के लिए समान रूप से प्रयुक्त होते हैं (जैसे: राष्ट्रपति, प्रधानमंत्री, डॉक्टर, इंजीनियर, जज), उन्हें क्या कहा जाता है?', 'संवैधानिक पद और व्यावसायिक उपाधियाँ (राष्ट्रपति, डॉक्टर, मंत्री) उभयलिंगी रूप में दोनों लिंगों के लिए समान रहती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae404b0b-6dae-460a-8595-acff1545c46a', 'उभयलिंगी शब्द (Common Gender Words)', true, '6eb9fe70-1cda-41d2-854c-95161e45d5f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50532cc0-e57c-45c1-aea7-2084955248d8', 'नपुंसक शब्द', false, '6eb9fe70-1cda-41d2-854c-95161e45d5f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae1a824a-e9a5-4b50-bfce-ebe322d7ffdc', 'सदा स्त्रीलिंग शब्द', false, '6eb9fe70-1cda-41d2-854c-95161e45d5f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c20e269b-66e0-4d15-808b-3646071c9272', 'अविकारी शब्द', false, '6eb9fe70-1cda-41d2-854c-95161e45d5f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11def668-3d8e-465c-9d52-e69120310a3e', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'वे प्राणीवाचक शब्द जो सदा पुल्लिंग में ही प्रयुक्त होते हैं (जैसे: मच्छर, चीता, तोता, भेड़िया, खरगोश), उनका स्त्रीलिंग बनाने के लिए क्या किया जाता है?', 'नित्य पुल्लिंग शब्दों के स्त्रीलिंग रूप हेतु ''मादा'' उपसर्ग जोड़ा जाता है (मादा भेड़िया, मादा चीता)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf731375-4974-426e-b1ab-050075517f77', 'शब्द के आगे ''मादा'' शब्द जोड़ दिया जाता है (जैसे: मादा मच्छर, मादा चीता, मादा तोता)', true, '11def668-3d8e-465c-9d52-e69120310a3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fc46e3a-9ac3-49b9-8757-bd8c230d2ef7', 'शब्द के अंत में ''नी'' प्रत्यय लगाते हैं', false, '11def668-3d8e-465c-9d52-e69120310a3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc6b5c50-acfd-45ef-9b77-be4252f91d0e', 'शब्द को बहुवचन बना देते हैं', false, '11def668-3d8e-465c-9d52-e69120310a3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('364b7fc1-cf3c-406a-87ad-4562df917181', 'उनका कोई स्त्रीलिंग नहीं होता', false, '11def668-3d8e-465c-9d52-e69120310a3e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94c21106-d31a-4d71-8841-d56f209545c8', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'वे शब्द जो सदा स्त्रीलिंग में ही प्रयुक्त होते हैं (जैसे: तितली, मक्खी, कोयल, मछली, मैना, गिलहरी), उनका पुल्लिंग बनाने के लिए क्या किया जाता है?', 'नित्य स्त्रीलिंग शब्दों के पुल्लिंग रूप हेतु ''नर'' उपसर्ग जोड़ा जाता है (नर कोयल, नर मछली, नर गिलहरी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2864971-00a6-48fd-a656-ee6c9f1ce7d9', 'शब्द के आगे ''नर'' शब्द जोड़ दिया जाता है (जैसे: नर तितली, नर मक्खी, नर कोयल, नर मछली)', true, '94c21106-d31a-4d71-8841-d56f209545c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb831fff-f874-4615-b379-7b1afb18d9c6', 'शब्द के अंत में ''आ'' जोड़ते हैं', false, '94c21106-d31a-4d71-8841-d56f209545c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e1e8b9a-fdee-4a7d-b8d2-92143a49af70', 'शब्द को बदल देते हैं', false, '94c21106-d31a-4d71-8841-d56f209545c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de8fd93f-4f68-48e3-98a7-bbf801128ac5', 'कोई परिवर्तन नहीं होता', false, '94c21106-d31a-4d71-8841-d56f209545c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28f93413-e0fc-4649-a1e5-f54d4c702f23', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'निम्नलिखित में से ''सदा पुल्लिंग'' रहने वाले संज्ञा शब्दों का सही समूह कौन-सा है?', 'भूगोलीय महाद्वीप, देश, पर्वत, सागर, वार और महीने सर्वमान्य रूप से नित्य पुल्लिंग वर्ग में आते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06f5a4fe-3824-496b-b613-c0b220df27c3', 'देशों के नाम (भारत, रूस), पर्वतों के नाम (हिमालय), सागरों के नाम (हिंद महासागर), दिनों और महीनों के नाम (सोमवार, चैत्र)', true, '28f93413-e0fc-4649-a1e5-f54d4c702f23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('919bbd6b-c4f4-4ac1-8f77-ad297a8a79e1', 'नदियों के नाम, भाषाओं के नाम', false, '28f93413-e0fc-4649-a1e5-f54d4c702f23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e81e84b-10e3-45d3-a003-04d9221987eb', 'तिथियों के नाम, लिपियों के नाम', false, '28f93413-e0fc-4649-a1e5-f54d4c702f23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01848757-3aa8-403c-9ee5-e4c6ce49d84d', 'बोलियों और झीलों के नाम', false, '28f93413-e0fc-4649-a1e5-f54d4c702f23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('893579d9-0f05-4118-848e-a2355a6f6f61', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'निम्नलिखित में से ''सदा स्त्रीलिंग'' रहने वाले संज्ञा शब्दों का सही समूह कौन-सा है?', 'नदियों, भाषाओं, लिपियों, बोलियों तथा पंचांग तिथियों के नाम हिंदी में अनिवार्यतः स्त्रीलिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa5d0929-d533-47f3-bc5a-d3cf70b3809b', 'नदियों के नाम (गंगा, कावेरी), भाषाओं और बोलियों के नाम (हिंदी, ब्रज), लिपियों के नाम (देवनागरी), तिथियों के नाम (एकादशी)', true, '893579d9-0f05-4118-848e-a2355a6f6f61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1ad9987-be67-44e8-baf2-69af51a6842b', 'पेड़ों के नाम, फलों के नाम', false, '893579d9-0f05-4118-848e-a2355a6f6f61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20a8defb-f0a6-417c-87bf-89555a7a2a01', 'अनाजों के नाम, ग्रहों के नाम', false, '893579d9-0f05-4118-848e-a2355a6f6f61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a99f66e7-a4ea-487f-ae23-65c373a4ba43', 'धातुओं और रत्नों के नाम', false, '893579d9-0f05-4118-848e-a2355a6f6f61');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('921850b7-a360-436c-8c49-d2e58f4b2320', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'अधिकांश धातुएँ और रत्न पुल्लिंग होते हैं, परन्तु कौन-सी धातु और रत्न अपवाद स्वरूप ''स्त्रीलिंग'' माने जाते हैं?', 'सोना, लोहा, ताँबा पुल्लिंग हैं, किन्तु ''चाँदी'' धातु स्त्रीलिंग है; इसी प्रकार अधिकांश रत्न पुल्लिंग हैं किन्तु ''मणि'' स्त्रीलिंग है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd0921ee-a224-4f0a-8cda-02511f9e351e', 'धातु में ''चाँदी'' तथा रत्न में ''मणि'' (स्त्रीलिंग)', true, '921850b7-a360-436c-8c49-d2e58f4b2320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54d8d386-bae0-46b3-b52f-fb9c8c7fa57a', 'लोहा और सोना', false, '921850b7-a360-436c-8c49-d2e58f4b2320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e25d19b6-5851-4150-b539-3929657c3237', 'ताँबा और पीतल', false, '921850b7-a360-436c-8c49-d2e58f4b2320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e26db5e9-0c5e-4a8f-843e-2ba44152a928', 'हीरा और पन्ना', false, '921850b7-a360-436c-8c49-d2e58f4b2320');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27be7513-90e6-4037-9131-4db9324d062e', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'अधिकांश अनाज पुल्लिंग होते हैं (गेहूँ, चावल, चना, बाजरा), परन्तु कौन-से अनाज अपवाद स्वरूप ''स्त्रीलिंग'' होते हैं?', 'मक्का, ज्वार, मूँग, और अरहर दालें स्त्रीलिंग प्रयोग में आती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('786a07d3-ffaf-4ec1-9dc1-c270a3822f41', 'मक्का, ज्वार, मूँग, अरहर (स्त्रीलिंग)', true, '27be7513-90e6-4037-9131-4db9324d062e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f2847c2-1d51-49d7-9434-fa9750e529ec', 'गेहूँ और धान', false, '27be7513-90e6-4037-9131-4db9324d062e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb72bc55-89c5-46cf-a936-a90208c273a3', 'चना और मटर', false, '27be7513-90e6-4037-9131-4db9324d062e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcca192c-0948-4a70-bfe3-535089d128e4', 'जौ और बाजरा', false, '27be7513-90e6-4037-9131-4db9324d062e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa7a105f-7e99-49b8-9e20-0cbc17ffb426', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'अधिकांश द्रव पदार्थ पुल्लिंग होते हैं (पानी, दूध, तेल, घी, शर्बत), परन्तु कौन-से द्रव अपवाद स्वरूप ''स्त्रीलिंग'' होते हैं?', 'चाय, कॉफ़ी, लस्सी, छाछ आदि पेय पदार्थ व्याकरण में स्त्रीलिंग माने जाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6de0cd65-2655-4f1f-ab21-f25bd9824e7d', 'चाय, कॉफ़ी, लस्सी, शराब, छाछ (स्त्रीलिंग)', true, 'fa7a105f-7e99-49b8-9e20-0cbc17ffb426');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('002bdae3-69df-4322-b321-26bbcbc4ab33', 'दूध और दही', false, 'fa7a105f-7e99-49b8-9e20-0cbc17ffb426');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e53ba10-6434-4242-835a-c5bcef250adc', 'तेल और पेट्रोल', false, 'fa7a105f-7e99-49b8-9e20-0cbc17ffb426');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af99264c-f15b-483c-ac22-7eae4210fe51', 'पानी और शरबत', false, 'fa7a105f-7e99-49b8-9e20-0cbc17ffb426');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63fd2f45-d2a7-43d4-a422-bf4afdc47147', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''श्रीमान'' और ''आयुष्मान'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', 'मान् का मती तथा वान् का वती: श्रीमान -> श्रीमती; आयुष्मान -> आयुष्मती; गुणवान -> गुणवती; बलवान -> बलवती।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac365a7f-4d38-4e34-9c74-0d03ae87f757', 'श्रीमती और आयुष्मती', true, '63fd2f45-d2a7-43d4-a422-bf4afdc47147');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2b75d96-eade-42a7-8189-cf5c26ce4623', 'श्रीमान्य और आयुष्मान्', false, '63fd2f45-d2a7-43d4-a422-bf4afdc47147');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('614ab907-ac00-4e8b-a478-6d75d4fe6c77', 'श्रीवती और आयुष्मंती', false, '63fd2f45-d2a7-43d4-a422-bf4afdc47147');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e5bd751-9f8d-40b4-a018-c7fb69b1b553', 'श्रीमतीजी और आयुष्मनी', false, '63fd2f45-d2a7-43d4-a422-bf4afdc47147');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d928c334-bcfc-4bb4-920a-312495a29a62', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''दाता'', ''विधाता'' और ''रचयिता'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', 'संस्कृत तत्सम शब्दों में अंतस्थ ''ता'' स्त्रीलिंग में ''त्री'' बन जाता है: दाता -> दात्री; विधाता -> विधात्री; रचयिता -> रचयित्री।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caa2f4e3-b77c-4fd2-abcd-261a51b25bc3', 'दात्री, विधात्री, रचयित्री', true, 'd928c334-bcfc-4bb4-920a-312495a29a62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc1c9e4d-6373-42ed-83ce-475409b57d04', 'दातिन, विधातिन, रचयिताइन', false, 'd928c334-bcfc-4bb4-920a-312495a29a62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a022eef-7539-4562-87c3-a9422baf1c05', 'दाती, विधाती, रचयिती', false, 'd928c334-bcfc-4bb4-920a-312495a29a62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21a6298b-8e46-4fff-b3b1-bb94497088d0', 'दानी, विधाता, रचनाकार', false, 'd928c334-bcfc-4bb4-920a-312495a29a62');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ead7e02-acd0-4820-b63f-aadbeeaf0d5c', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''धोबी'', ''माली'' और ''तेली'' में ''इन'' प्रत्यय लगाने पर सही स्त्रीलिंग रूप क्या बनेंगे?', 'ई-कारान्त पुल्लिंग शब्दों में ''इन'' प्रत्यय लगने पर ई ह्रस्व होकर ''इन्'' बनता है: धोबी -> धोबिन; माली -> मालिन; तेली -> तेलिन।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae794cd0-9006-455d-b1cc-c0292a6ed101', 'धोबिन, मालिन, तेलिन', true, '8ead7e02-acd0-4820-b63f-aadbeeaf0d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('240eb3d8-020e-4115-8945-bf50a546c162', 'धोबनी, मालनी, तेलनी', false, '8ead7e02-acd0-4820-b63f-aadbeeaf0d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('421c4ba5-6530-4bab-bd26-ab137ad4b9f4', 'धोबन, मालिया, तेलाई', false, '8ead7e02-acd0-4820-b63f-aadbeeaf0d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('644daa54-f013-4911-a867-72ee7d301dcb', 'धोबीइन, मालीइन, तेलीइन', false, '8ead7e02-acd0-4820-b63f-aadbeeaf0d5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0e1638f-2eb3-4dcd-9c6d-d60581c41a32', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''पंडित'', ''चौधरी'' और ''ठाकुर'' में ''आइन'' प्रत्यय लगाने पर सही स्त्रीलिंग रूप क्या बनेंगे?', 'आइन प्रत्यय से स्त्रीलिंग निर्माण: पंडित -> पंडिताइन; चौधरी -> चौधराइन; ठाकुर -> ठकुराइन; बाबू -> बबुआइन।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8e59731-3c2d-4741-a793-af8fea62c54b', 'पंडिताइन, चौधराइन, ठकुराइन', true, 'c0e1638f-2eb3-4dcd-9c6d-d60581c41a32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8e047d0-3d28-4b32-94fa-f59b09af0629', 'पंडिती, चौधरीनी, ठाकुरनी', false, 'c0e1638f-2eb3-4dcd-9c6d-d60581c41a32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9360b24-3d5e-42d7-ac70-ee31472808e0', 'पंडितनी, चौधरायन, ठकुरायन', false, 'c0e1638f-2eb3-4dcd-9c6d-d60581c41a32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e18e9bd7-54f7-4566-ac83-34a83e174ab7', 'पंडितानी, चौधरानी, ठाकुरानी', false, 'c0e1638f-2eb3-4dcd-9c6d-d60581c41a32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16258cc5-ba35-49ed-9034-33bb0e00e75f', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''सेठ'', ''देवर'' और ''इंद्र'' में ''आनी'' प्रत्यय लगाने पर सही स्त्रीलिंग रूप क्या बनेंगे?', 'आनी प्रत्यय से स्त्रीलिंग: सेठ -> सेठानी; देवर -> देवरानी; नौकर -> नौकरानी; इंद्र -> इंद्राणी; रुद्र -> रुद्राणी।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('760a17f7-0ab8-4481-a381-981512490570', 'सेठानी, देवरानी, इंद्राणी', true, '16258cc5-ba35-49ed-9034-33bb0e00e75f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3cb8753-11e5-459a-9438-012ca3cc794f', 'सेठी, देवरी, इंद्री', false, '16258cc5-ba35-49ed-9034-33bb0e00e75f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10576908-7202-453f-95bc-f5413f81e58c', 'सेठिन, देवरिन, इंद्रिन', false, '16258cc5-ba35-49ed-9034-33bb0e00e75f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('175b1e06-2943-42cf-abf8-ca379e9dd721', 'सेठाइन, देवरिया, इंद्रा', false, '16258cc5-ba35-49ed-9034-33bb0e00e75f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('157bf9c5-99c8-461d-be5b-0436f1ac4773', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''नायक'', ''गायक'' और ''लेखक'' में ''इका'' प्रत्यय लगाने पर सही स्त्रीलिंग रूप क्या बनेंगे?', 'अक-अन्त पुल्लिंग शब्दों में ''इका'' प्रत्यय: नायक -> नायिका; गायक -> गायिका; लेखक -> लेखिका; पाठक -> पाठिका।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b902311d-f6a8-4d9a-92a9-bf3f8d12761e', 'नायिका, गायिका, लेखिका', true, '157bf9c5-99c8-461d-be5b-0436f1ac4773');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6700fbb0-1a1b-4c6d-ac33-348eeb9502c7', 'नायकी, गायकी, लेखकी', false, '157bf9c5-99c8-461d-be5b-0436f1ac4773');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db7011c3-6019-46b7-8857-452d93583f25', 'नायकिन, गायकिन, लेखकिन', false, '157bf9c5-99c8-461d-be5b-0436f1ac4773');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c4f25aa-8ce4-4164-bd6e-2d346f41577c', 'नायका, गायका, लेखका', false, '157bf9c5-99c8-461d-be5b-0436f1ac4773');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30dce885-d8e6-4e4e-b1dc-74828f66219a', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''हाथी'' का शुद्ध मानक स्त्रीलिंग रूप क्या होता है?', '''हाथी'' का मानक शुद्ध व्याकरणिक स्त्रीलिंग रूप ''हथिनी'' (ह + थि + नी) होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('196c9128-3b6a-4352-addc-f2c73af64554', 'हथिनी', true, '30dce885-d8e6-4e4e-b1dc-74828f66219a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c40a3791-0282-418f-972d-f171b5dd0ce7', 'हाथिन', false, '30dce885-d8e6-4e4e-b1dc-74828f66219a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8624e3e1-1775-424e-9300-61ff3e8fbc3f', 'हाथिनी', false, '30dce885-d8e6-4e4e-b1dc-74828f66219a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b155d06e-a520-4cac-9205-5cdc17043570', 'हथनी', false, '30dce885-d8e6-4e4e-b1dc-74828f66219a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('223bf90f-a5fa-4a80-98f3-caa355a9555d', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'वाक्य में प्रयुक्त क्रिया से लिंग की पहचान कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e77c284-ed63-4c5a-9270-eade916086ef', 'पत्ता = पुल्लिंग ; पत्ती = स्त्रीलिंग', true, '223bf90f-a5fa-4a80-98f3-caa355a9555d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82bdb301-3231-487b-a9b7-50dcc0974968', 'पत्ता = स्त्रीलिंग ; पत्ती = पुल्लिंग', false, '223bf90f-a5fa-4a80-98f3-caa355a9555d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fab4c9e2-c373-4ed0-a44f-f48e115ec3bd', 'दोनों पुल्लिंग हैं', false, '223bf90f-a5fa-4a80-98f3-caa355a9555d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60db423e-f5fe-4385-aea6-61b9d078aa7c', 'दोनों स्त्रीलिंग हैं', false, '223bf90f-a5fa-4a80-98f3-caa355a9555d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b8d30bb-6056-4ff8-8c77-813cd46374a0', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a109bfc-021e-475c-aa0e-15b32384231d', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '9b8d30bb-6056-4ff8-8c77-813cd46374a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83ded4ec-0605-4ff3-b4e9-9e2e12170215', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '9b8d30bb-6056-4ff8-8c77-813cd46374a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40cf648f-1cf2-4244-9664-66efacb2d79e', '(A) सही है, परन्तु (R) गलत है।', false, '9b8d30bb-6056-4ff8-8c77-813cd46374a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3ce2295-6f9b-48fb-8a51-ea59dfb1d5b3', '(A) गलत है, परन्तु (R) सही है।', false, '9b8d30bb-6056-4ff8-8c77-813cd46374a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('842ad7c5-1b10-443a-b28f-d575812d49b7', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'Spot the IMPOSTER in the following group of ई-कारान्त शब्दों के लिंग के आधार पर:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09ff577b-be88-418e-b5a3-a069fccef892', 'नदी', false, '842ad7c5-1b10-443a-b28f-d575812d49b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e3cfdb6-2c43-4746-afb4-4cd3ef44a35b', 'रोटी', false, '842ad7c5-1b10-443a-b28f-d575812d49b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a46082d5-724c-4b8b-8167-6f9d90fc2514', 'टोपी', false, '842ad7c5-1b10-443a-b28f-d575812d49b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6d099ca-0910-48e2-ad84-c10928ae5e15', 'पानी', true, '842ad7c5-1b10-443a-b28f-d575812d49b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89f34b5c-5072-426a-9d16-3e5e9e2cd41e', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'सुमेलित कीजिए (पुल्लिंग और स्त्रीलिंग के विशिष्ट तत्सम युग्म):
(क) विद्वान  -> (i) तपस्विनी
(ख) तपस्वी   -> (ii) विदुषी
(ग) सम्राट    -> (iii) साध्वी
(घ) साधु     -> (iv) सम्राज्ञी', 'विद्वान = विदुषी; तपस्वी = तपस्विनी; सम्राट = सम्राज्ञी; साधु = साध्वी।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3df9fe7-5e42-497b-b2f6-e6b109921500', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', true, '89f34b5c-5072-426a-9d16-3e5e9e2cd41e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36fdc80e-d596-4fd2-90ad-8ccd71bc4634', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '89f34b5c-5072-426a-9d16-3e5e9e2cd41e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b9bdad9-e972-4c93-a334-9669c94bbaa5', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '89f34b5c-5072-426a-9d16-3e5e9e2cd41e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fddb85ed-e4f3-4771-a697-e1ea09f7c08c', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '89f34b5c-5072-426a-9d16-3e5e9e2cd41e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85a8140a-ec46-42b0-8f10-75f893b0d8f3', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'निम्नलिखित प्रत्ययों वाले भाववाचक शब्दों के लिंग के संदर्भ में कौन-सा कथन सत्य है?', 'ता, आई, आवट, आहट, इमा, ई प्रत्ययान्त भाववाचक शब्द (मानवता, लिखाई, लिखावट, चिकनाहट, महिमा) अनिवार्यतः स्त्रीलिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('578b9d87-3e85-406d-806f-227c84f58e9a', 'जिन शब्दों के अंत में ''ता'', ''आई'', ''आवट'', ''आहट'', ''इमा'' प्रत्यय आते हैं (जैसे: सुंदरता, भलाई, सजावट, घबराहट, लालिमा), वे प्रायः स्त्रीलिंग होते हैं', true, '85a8140a-ec46-42b0-8f10-75f893b0d8f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('831cafb8-94a0-428a-9ed0-af91e2c2c706', 'वे सदा पुल्लिंग होते हैं', false, '85a8140a-ec46-42b0-8f10-75f893b0d8f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c596b86-f0aa-451d-8e33-57751997f2ff', 'वे उभयलिंगी होते हैं', false, '85a8140a-ec46-42b0-8f10-75f893b0d8f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8831a66f-6801-4c67-b76a-bb3bb143786d', 'वे अविकारी होते हैं', false, '85a8140a-ec46-42b0-8f10-75f893b0d8f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9105eb56-5c7f-4381-944c-a8bdd393947b', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'जिन भाववाचक शब्दों के अंत में ''त्व'', ''पन'', ''पा'', ''आव'', ''आस'' आते हैं (जैसे: मनुष्यत्व, बचपन, बुढ़ापा, बहाव, निकास), वे प्रायः किस लिंग में होते हैं?', 'त्व, पन, पा, आव प्रत्ययान्त भाववाचक संज्ञाएँ सदा पुल्लिंग होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ec464c8-d873-4893-b025-4c3a85133817', 'पुल्लिंग (जैसे: देवत्व, अपनापन, मोटापा, फैलाव)', true, '9105eb56-5c7f-4381-944c-a8bdd393947b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34f83b71-38b0-4eea-9372-91299c619b7f', 'स्त्रीलिंग', false, '9105eb56-5c7f-4381-944c-a8bdd393947b');
