INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abcc0090-8967-41d2-bed2-544cec92c48c', 'उभयलिंगी', false, '9105eb56-5c7f-4381-944c-a8bdd393947b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07f19073-94d9-4bf1-aa9c-34c64954975b', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'निम्नलिखित वाक्यों पर विचार कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cf17ffe-bbf9-4257-a758-bd3dac5d06c1', 'सभी वाक्य 1, 2 और 3 सत्य हैं', true, '07f19073-94d9-4bf1-aa9c-34c64954975b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daf87a59-f632-4a95-aefd-037e78a28510', 'वाक्य 1 और 2 केवल', false, '07f19073-94d9-4bf1-aa9c-34c64954975b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a94cb92-e8c8-49dc-9b20-66fcae521392', 'वाक्य 2 and 3 केवल', false, '07f19073-94d9-4bf1-aa9c-34c64954975b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab1b234d-eed3-46d0-8e92-9172838b4555', 'वाक्य 1 और 3 केवल', false, '07f19073-94d9-4bf1-aa9c-34c64954975b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ad1b772-0b75-4a2d-95a8-53203f31044f', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'पुल्लिंग शब्द ''महान'' और ''युवा'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', '''महान'' का तत्सम स्त्रीलिंग रूप ''महती'' (जैसे महती कृपा) तथा ''युवा'' का स्त्रीलिंग ''युवती'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1758cf7-bfbb-4691-8570-12e650f92642', 'महती और युवती', true, '6ad1b772-0b75-4a2d-95a8-53203f31044f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ade3a54-2280-4496-9e11-d71eb0d30438', 'महानता और युवती', false, '6ad1b772-0b75-4a2d-95a8-53203f31044f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51b4ed00-8d10-40ec-af94-15caf51076d4', 'महानि और युवतिन', false, '6ad1b772-0b75-4a2d-95a8-53203f31044f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('641df731-5363-4dad-ab5e-97e203532bb5', 'महानी और युवानी', false, '6ad1b772-0b75-4a2d-95a8-53203f31044f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0be3d76-7170-4df4-b0f9-69ed871d71de', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'शरीर के अंगों के नाम में कौन-से अंग अपवाद स्वरूप ''स्त्रीलिंग'' होते हैं?', 'हाथ, पैर, कान, सिर पुल्लिंग हैं, जबकि आँख, नाक, जीभ, ठोड़ी, उँगली, कलाई स्त्रीलिंग हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a34cabf8-75b4-4068-b9c9-a87d08e66940', 'आँख, नाक, जीभ, ठोड़ी, उँगली, कमर (स्त्रीलिंग)', true, 'f0be3d76-7170-4df4-b0f9-69ed871d71de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edeea36f-8d54-4f06-8ff3-54ff3861c866', 'हाथ, पैर, सिर, कान, मुँह, पेट (पुल्लिंग)', false, 'f0be3d76-7170-4df4-b0f9-69ed871d71de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46e90030-f922-441d-a6b9-fa9419a07442', 'हृदय, फेफड़ा, घुटना (पुल्लिंग)', false, 'f0be3d76-7170-4df4-b0f9-69ed871d71de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a65600d-77f4-4684-a841-4d8490a7e3b4', 'दाँत, नाखून, बाल (पुल्लिंग)', false, 'f0be3d76-7170-4df4-b0f9-69ed871d71de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04f3d1ae-5868-4586-9989-b85b26daa5ef', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'सौरमंडल के सभी ग्रहों के नाम पुल्लिंग होते हैं (सूर्य, चंद्र, मंगल, बुध, गुरु, शुक्र, शनि, राहु, केतु), परन्तु कौन-सा ग्रह अपवाद स्वरूप ''स्त्रीलिंग'' है?', '''पृथ्वी'' हमारी धरती माता होने के कारण व्याकरण में एकमात्र स्त्रीलिंग ग्रह नाम है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0744909-d931-43b6-8f5f-8ed90b03a7ec', 'पृथ्वी (Earth - स्त्रीलिंग)', true, '04f3d1ae-5868-4586-9989-b85b26daa5ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71432afc-115a-4615-87ae-951e08b2845b', 'मंगल', false, '04f3d1ae-5868-4586-9989-b85b26daa5ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1d3fae6-a81b-4fda-9195-e08ceb2d8e5e', 'शुक्र', false, '04f3d1ae-5868-4586-9989-b85b26daa5ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66ab3806-f775-40b7-8017-3c09d0c03c81', 'बृहस्पति', false, '04f3d1ae-5868-4586-9989-b85b26daa5ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82483c79-0a03-4c8a-a256-25ff8b7e704b', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'पुल्लिंग शब्द ''बिलाव'' (या बिलाव/बिलाड़) का सही स्त्रीलिंग रूप क्या है?', 'नर मार्जार को ''बिलाव'' तथा मादा मार्जार को ''बिल्ली'' कहा जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6afd0e2-b5f3-4528-bc0b-a51d6408e57a', 'बिल्ली', true, '82483c79-0a03-4c8a-a256-25ff8b7e704b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcf35ba5-40d8-41e7-946c-a3c5e92ea8e1', 'बिलाविन', false, '82483c79-0a03-4c8a-a256-25ff8b7e704b');
