INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f31229a7-66d1-4474-a6bc-8f948e94815b', 'बिलैया', false, '82483c79-0a03-4c8a-a256-25ff8b7e704b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b698124-acdc-4e43-9c70-e27d51a2e774', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'पुल्लिंग शब्द ''भेड़िया'' का सही स्त्रीलिंग रूप क्या होगा?', '''भेड़िया'' नित्य पुल्लिंग शब्द है, अतः इसका स्त्रीलिंग ''मादा भेड़िया'' बनता है (''भेड़'' अलग प्रजाति का जीव है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f90332ac-e669-4bee-b056-2775f8e8b272', 'मादा भेड़िया', true, '4b698124-acdc-4e43-9c70-e27d51a2e774');
