INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2d2d0e6-6440-4207-a9bc-463d05fd1a79', 'न्यायाधीश = उभयलिंगी (पुल्लिंग पद) ; सज़ा = स्त्रीलिंग', true, 'e1ef75b6-5da0-4ff9-9091-93d65c7de93d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68a68ea9-021b-46d5-8b4e-74e7046aa607', 'न्यायाधीश = स्त्रीलिंग ; सज़ा = पुल्लिंग', false, 'e1ef75b6-5da0-4ff9-9091-93d65c7de93d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b69fd084-e3b3-4e8e-ad0a-759c562479b3', 'दोनों पुल्लिंग हैं', false, 'e1ef75b6-5da0-4ff9-9091-93d65c7de93d');
