INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9865c352-52c0-4750-9f31-a60d2cba927a', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'The natural surroundings or specific environment where a plant or animal naturally lives and thrives is called its:', 'A habitat provides organisms with food, water, air, shelter, and breeding grounds tailored to their ecological niche.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f79ec61-5aa4-48b8-bfbb-0a8bd064ae3a', 'Habitat', true, '9865c352-52c0-4750-9f31-a60d2cba927a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29669832-90c9-4060-bd10-fd897bc76286', 'Adaptation', false, '9865c352-52c0-4750-9f31-a60d2cba927a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c84ce45-134e-435e-9f05-650857dff945', 'Acclimatization', false, '9865c352-52c0-4750-9f31-a60d2cba927a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daf9a10d-4eed-4ba6-ad42-7b01d5065ec5', 'Predation', false, '9865c352-52c0-4750-9f31-a60d2cba927a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('940912ee-996f-4a70-8023-9b2fad50bb1f', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'Habitats located on land (such as forests, grasslands, deserts, coastal, and mountain regions) are called:', 'Terrestrial ecosystems encompass all dry-land continental environments supporting flora and fauna.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('058a1a70-2124-4331-bdbb-1e8d0d5c69b5', 'Terrestrial Habitats', true, '940912ee-996f-4a70-8023-9b2fad50bb1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5988e2e-abd6-49ed-bdf7-9d6c7b920ab0', 'Aquatic Habitats', false, '940912ee-996f-4a70-8023-9b2fad50bb1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86e845b8-c48a-434b-9a80-cfff1e4b779b', 'Amphibious Habitats', false, '940912ee-996f-4a70-8023-9b2fad50bb1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b86b6eb-4049-433a-a9c9-18b35c199aa0', 'Aerial Habitats', false, '940912ee-996f-4a70-8023-9b2fad50bb1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c04f0140-7226-46a1-901c-d39d13e9afea', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'Habitats located in water (such as ponds, swamps, lakes, rivers, and oceans) are called:', 'Aquatic habitats comprise marine saltwater and freshwater biomes hosting aquatic organisms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84057f61-9288-4799-b79c-307b3626a9ed', 'Aquatic Habitats', true, 'c04f0140-7226-46a1-901c-d39d13e9afea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbd0d118-ddc6-468e-917c-caa1dc475592', 'Terrestrial Habitats', false, 'c04f0140-7226-46a1-901c-d39d13e9afea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbdc621d-e611-4173-a16e-bb58d8a300a4', 'Arboreal Habitats', false, 'c04f0140-7226-46a1-901c-d39d13e9afea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8910e5b8-950c-4880-9121-4c0c79a418b2', 'Desert Habitats', false, 'c04f0140-7226-46a1-901c-d39d13e9afea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23c0afbf-dd45-4719-a609-21f4b507000c', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'The living things (such as plants, animals, and microorganisms) that exist in a habitat are called its:', 'Biotic factors comprise all living biological community members interacting within an ecosystem.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d8c19e4-093a-468c-ae84-5314469a5953', 'Biotic Components', true, '23c0afbf-dd45-4719-a609-21f4b507000c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bd225cf-72ea-4644-8be9-29fab60be09b', 'Abiotic Components', false, '23c0afbf-dd45-4719-a609-21f4b507000c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9db3264-59f5-4c9d-9e9b-02a03955a969', 'Inorganic Components', false, '23c0afbf-dd45-4719-a609-21f4b507000c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33d41be9-e476-4272-a65e-835b702bf859', 'Non-living Factors', false, '23c0afbf-dd45-4719-a609-21f4b507000c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65ecd7b9-933a-473d-ae45-2b973bf42457', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'The non-living physical factors (such as rocks, soil, air, water, sunlight, and temperature) in a habitat are called its:', 'Abiotic factors are the chemical and physical non-living environmental parameters shaping habitats.', NOW()) ON CONFLICT DO NOTHING;
