INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13c3a852-b2e1-4552-bd74-d47a6fedc4ca', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'The presence of specific structural features or behavioral habits which enable an organism to live naturally in its surroundings is called:', 'Adaptations are genetically evolved morphological and physiological traits enhancing survival in a given habitat.', NOW()) ON CONFLICT DO NOTHING;
