INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14a2ff3f-2f44-4c1c-b351-2d0ec2a15554', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'Which of the following animals is famously adapted to survive in extremely hot, arid desert habitats, known as the ''Ship of the Desert''?', 'Camels possess wide padded feet, long legs, low sweat rates, concentrated urine, and fat-storing humps.', NOW()) ON CONFLICT DO NOTHING;
