INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4eeb824e-2017-4558-b818-46765065e0c9', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'The biological process by which living organisms get rid of toxic waste materials produced in their bodies is called:', 'Excretion purges toxic metabolic byproducts (urea, CO₂, excess salts) from biological systems.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('897e7674-5487-4a9e-9774-274a9aad8675', 'Excretion', true, '4eeb824e-2017-4558-b818-46765065e0c9');
