INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd839a49-2d7e-452a-a7a2-21c336f71fca', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'The biological process by which organisms produce new individuals of their own kind is called:', 'Reproduction ensures species genetic continuity via sexual or asexual offspring generation.', NOW()) ON CONFLICT DO NOTHING;
