INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73967e00-6de8-4390-a599-8d698b6f1737', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'Changes in our immediate surroundings that make us react and respond to them are called:', 'A stimulus is an environmental cue (light, heat, touch, sound) evoking a behavioral or physiological response.', NOW()) ON CONFLICT DO NOTHING;
