INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c70ab509-db6e-4eeb-9b23-6bee44d9570c', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'Which plant is famous for folding and drooping its leaves immediately when touched by a human hand?', 'Mimosa exhibits thigmonastic turgor loss in pulvini motor cells upon tactile mechanical stimulus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fccd220-44c8-4b38-98b3-ae01f68c3e58', 'Mimosa pudica (''Touch-me-not'' / Chhui-mui)', true, 'c70ab509-db6e-4eeb-9b23-6bee44d9570c');
