INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49d3ef97-aa22-45be-9b80-8d04d536cd89', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'How do Earthworms breathe and exchange respiratory gases (O₂ and CO₂)?', 'Earthworms undergo cutaneous respiration: atmospheric oxygen dissolves across the vascularized moist epidermis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14f0e61b-98a8-4d26-a58e-30c0397bd0d5', 'Through their moist and slimy skin', true, '49d3ef97-aa22-45be-9b80-8d04d536cd89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dfd0c74-207f-46b4-a106-8ab2023fdb49', 'Through lungs', false, '49d3ef97-aa22-45be-9b80-8d04d536cd89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04d09af9-f7c5-4d58-bf6b-826341209aa9', 'Through gills', false, '49d3ef97-aa22-45be-9b80-8d04d536cd89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc42da4a-b8ef-4e29-8a2c-78c7de3af60a', 'Through nostrils', false, '49d3ef97-aa22-45be-9b80-8d04d536cd89');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fc51f94-1f33-420b-b0e8-c800f1bec6b1', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'What is the key difference between ''Adaptation'' and ''Acclimatization''?', 'Acclimatization is short-term physiological tuning (e.g. higher breathing rate in mountains), whereas adaptation is heritable evolutionary change.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47aeaa3d-83ba-4da7-a30a-b3329147e0da', 'Adaptation occurs very slowly over thousands of years across generations through natural selection, while Acclimatization consists of small temporary adjustments made by an individual organism over a few days', true, '5fc51f94-1f33-420b-b0e8-c800f1bec6b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3054ccb-ae17-44f9-8c0a-3df9c39d344e', 'Adaptation only happens in water', false, '5fc51f94-1f33-420b-b0e8-c800f1bec6b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbe9edd2-de1b-48ab-8a82-693c3616fc86', 'Acclimatization takes millions of years', false, '5fc51f94-1f33-420b-b0e8-c800f1bec6b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('384ee5f1-5b48-433e-9b9b-82f90c24355c', 'There is no difference', false, '5fc51f94-1f33-420b-b0e8-c800f1bec6b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5cbb4420-a249-4aa5-9e7d-c5b63a135e72', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How do desert plants (like Cactus / Opuntia) adapt to survive extreme water scarcity?', 'Xerophytic adaptations: spine modifications reduce transpiration, cladode stems store water, and roots penetrate deep.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd4e522b-0c4f-42c3-a704-3bc13d25a1fc', 'Leaves are reduced to sharp spines to minimize transpiration; stems become thick, green, and fleshy to perform photosynthesis and store water, coated with a waxy cuticle', true, '5cbb4420-a249-4aa5-9e7d-c5b63a135e72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a895aa2-a467-4e9b-b1d3-7ed8bbd84857', 'They grow broad leaves to catch rain', false, '5cbb4420-a249-4aa5-9e7d-c5b63a135e72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6526276-3e91-4380-b06b-c2923e97a1d5', 'They absorb water from desert air using flowers', false, '5cbb4420-a249-4aa5-9e7d-c5b63a135e72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed70df8e-2a6b-4544-8ab5-98c1fb977f57', 'They sleep underground all year', false, '5cbb4420-a249-4aa5-9e7d-c5b63a135e72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('193dbeac-44e4-4657-b763-85f9f7b76852', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How do desert animals like Rats and Snakes survive the scorching daytime heat without drinking much water?', 'Fossorial nocturnal behavior avoids diurnal solar heat load while conserving metabolic water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fddc336-1d89-4870-9e9c-13fb92eb055d', 'They stay in deep underground cool burrows during the daytime heat and emerge only during the cool night (Nocturnal habit)', true, '193dbeac-44e4-4657-b763-85f9f7b76852');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24d45f83-d597-4f48-a3cc-b8139edd9fe3', 'They swim in desert lakes', false, '193dbeac-44e4-4657-b763-85f9f7b76852');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fc568fd-79d1-4167-a03c-3273ab7ae92d', 'They sweat constantly', false, '193dbeac-44e4-4657-b763-85f9f7b76852');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61085e9b-205c-4b94-8b5a-3cc10cea7e6d', 'They turn into ice', false, '193dbeac-44e4-4657-b763-85f9f7b76852');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d144c46a-bab8-4a65-8fc6-ea5419591a58', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'What anatomical adaptations allow Mountain Trees (like Pines, Deodars, and Firs) to withstand heavy snow and freezing gales?', 'Conical architecture and needle foliage shed heavy snow loads, preventing mechanical crown fracturing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bad339b-3d74-41ce-8f53-da4c0689c97f', 'Cone-shaped canopy with sloping branches and needle-like leaves, allowing rainwater and snow to slide off effortlessly without snapping branches', true, 'd144c46a-bab8-4a65-8fc6-ea5419591a58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('518f9c3a-b3ee-43fa-b577-b27ad4947e02', 'Broad, flat horizontal leaves to catch snow', false, 'd144c46a-bab8-4a65-8fc6-ea5419591a58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e804318-0585-4654-8f19-5d4e22efaf02', 'Weak climbing stems', false, 'd144c46a-bab8-4a65-8fc6-ea5419591a58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea4c7e9f-2bf4-4522-bda4-4a3dc0db5e51', 'Lack of roots', false, 'd144c46a-bab8-4a65-8fc6-ea5419591a58');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a3e580b-27be-45b8-9d4a-9886fb5f2ce3', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How is the Snow Leopard adapted to its freezing high-altitude rocky habitat?', 'Dense woolly underfur and fur-cushioned paws insulate against snow while providing high-traction cliff grip.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('496e0d4d-87a1-41f9-9282-f0236329995c', 'Thick dense fur on its body, feet, and toes to protect from extreme cold, and a long furry tail for balance and warmth', true, '1a3e580b-27be-45b8-9d4a-9886fb5f2ce3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27ea98be-2624-4147-9c05-0204aaa71ed3', 'A bare skin without fur', false, '1a3e580b-27be-45b8-9d4a-9886fb5f2ce3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5208dbee-dde9-4826-97ab-8ca39fd3c663', 'Large flapping ears', false, '1a3e580b-27be-45b8-9d4a-9886fb5f2ce3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('916a8d4d-29ba-4798-afe9-580a4dafd176', 'Swimming fins', false, '1a3e580b-27be-45b8-9d4a-9886fb5f2ce3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4dcb8e17-42af-4a1f-92f8-144ebcbae784', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'What adaptation enables the Mountain Goat (Markhor / Himalayan Tahr) to run swiftly up steep rocky slopes?', 'Clad-hoofed ungulates possess keratinous outer walls and concave inner pads creating suction grip on vertical crags.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0aea4fa4-bdd4-4162-8432-b8e2503b6ae9', 'Strong, hard hooves with rubbery traction pads for running securely on steep, jagged rocks without slipping', true, '4dcb8e17-42af-4a1f-92f8-144ebcbae784');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f4194f7-5e49-4f76-9af2-ea2ef7d91589', 'Large wings for gliding', false, '4dcb8e17-42af-4a1f-92f8-144ebcbae784');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce05d4d5-be8b-4327-ad10-60a908480a3c', 'A long snake-like tail', false, '4dcb8e17-42af-4a1f-92f8-144ebcbae784');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33d9107d-ff5d-4be5-be83-5da2e86f9988', 'Soft padded paws like a cat', false, '4dcb8e17-42af-4a1f-92f8-144ebcbae784');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98770db1-78f4-484f-9d4b-310199d134bc', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'Why do Lions living in grasslands have light brown (tawny) fur and forward-facing eyes?', 'Predatory binocular vision grants depth field focus, while tawny pelage blends into savanna grassland backgrounds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0212e4ba-f405-489f-a167-0a0db142b6bf', 'Light brown coat camouflages in dry grasses during stalking, and forward-facing eyes allow precise stereoscopic depth perception of prey distance', true, '98770db1-78f4-484f-9d4b-310199d134bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('475c26e1-09c0-4848-987c-f48b34ce59e2', 'To attract sunlight', false, '98770db1-78f4-484f-9d4b-310199d134bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b7efea2-6b96-444c-b247-02d478f18682', 'To scare birds', false, '98770db1-78f4-484f-9d4b-310199d134bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ec05f88-8c75-4a1d-91fd-3febf6be0c5f', 'Because they only eat grass', false, '98770db1-78f4-484f-9d4b-310199d134bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ce33cf2-5df6-49ed-84ad-82a751692e5e', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'Why do prey animals like Deer in grasslands have long ears and eyes positioned on the SIDES of their head?', 'Herbivore side-mounted eyes deliver panoramic peripheral vision to detect approaching carnivores without turning the head.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b6d3dec-0940-4bcf-b877-14318bf9081e', 'Long ears hear subtle predator movements from afar, and lateral eyes provide wide 360° panoramic field of vision to spot danger in all directions', true, '7ce33cf2-5df6-49ed-84ad-82a751692e5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef20e3d6-e578-440f-b75b-15e6ab34a247', 'To look at their own tails', false, '7ce33cf2-5df6-49ed-84ad-82a751692e5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e48b8cce-d75a-42b8-a95e-e89382b0a151', 'To fly in the wind', false, '7ce33cf2-5df6-49ed-84ad-82a751692e5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffe1b1b0-f503-4ab7-90f6-3dba0b9cdb94', 'To keep their head cool', false, '7ce33cf2-5df6-49ed-84ad-82a751692e5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b369c4af-df49-4eca-88f9-a97f65134b65', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How do marine mammals like Dolphins and Whales breathe oxygen since they do NOT possess gills?', 'Cetaceans are air-breathing lung-bearing mammals that surface to ventilate through dorsal blowholes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('804119ad-8ea8-4a1e-9c27-a10a1a658bb3', 'Through Blowholes (nostrils) located on the upper surface of their heads, coming to the ocean surface to breathe air into their lungs', true, 'b369c4af-df49-4eca-88f9-a97f65134b65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72bbc70f-9a66-4117-b087-539704fd8251', 'Through their mouth underwater', false, 'b369c4af-df49-4eca-88f9-a97f65134b65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('714c7068-c677-430c-8597-d3e6f77814f1', 'Through their tail flukes', false, 'b369c4af-df49-4eca-88f9-a97f65134b65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ade6b36d-a122-465b-b851-a70215243f7b', 'They do not breathe oxygen', false, 'b369c4af-df49-4eca-88f9-a97f65134b65');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7a718c6-b713-4485-8ede-1bd912f445ef', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How are completely submerged aquatic plants (like Hydrilla and Vallisneria) adapted to flowing water currents?', 'Ribbon-like linear foliage minimizes hydrodynamic drag, flexing gracefully with aqueous streamflow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf659938-b2a5-429f-b2a9-efc99079f955', 'Narrow, thin, ribbon-like flexible leaves that can bend freely in water currents without tearing', true, 'e7a718c6-b713-4485-8ede-1bd912f445ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae7965ba-a90b-41b9-8ed8-1429ee1d3634', 'Large hard wooden trunks', false, 'e7a718c6-b713-4485-8ede-1bd912f445ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ad156a5-9d91-43de-91ca-7a47cb718f71', 'Thick waxy spines', false, 'e7a718c6-b713-4485-8ede-1bd912f445ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05e2352a-08cc-4e30-a9fe-99f10dbcc107', 'Heavy stone fruits', false, 'e7a718c6-b713-4485-8ede-1bd912f445ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba9948b0-3aaa-4f8c-93eb-80c2244cbf59', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How are floating aquatic plants (like Lotus and Water Lily) adapted to survive on water surfaces?', 'Aerenchyma tissue provides buoyancy, while epistomatous leaves have stomata on the dorsal side to exchange air above water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87edb032-cdd2-4ee3-9922-dc4f2e0c00c7', 'Stems are long, hollow, light, and spongy filled with air spaces; leaves and flowers float on the surface with stomata on the upper surface', true, 'ba9948b0-3aaa-4f8c-93eb-80c2244cbf59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c21e56ff-c84a-4bde-b145-626ad00bc6e7', 'Stems are solid heavy iron wood', false, 'ba9948b0-3aaa-4f8c-93eb-80c2244cbf59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19084f76-f56b-496d-800d-7a5f2cc452b5', 'Roots are 50 meters deep in soil', false, 'ba9948b0-3aaa-4f8c-93eb-80c2244cbf59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bdb848b-f71c-4f0c-a210-03f6073f9331', 'Leaves are covered with ice', false, 'ba9948b0-3aaa-4f8c-93eb-80c2244cbf59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d2e0168-630c-41e9-a513-b1867dff54aa', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How are Frogs adapted to live both on land and in freshwater ponds (Amphibious lifestyle)?', 'Dual respiration (pulmonary on land and cutaneous underwater) combined with webbed feet enables life in both aquatic and terrestrial habitats.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e89a7d33-9157-46fa-bc6f-1a51a236944a', 'They possess strong webbed hind legs for swimming and leaping, breathe through lungs on land, and breathe through moist skin underwater', true, '8d2e0168-630c-41e9-a513-b1867dff54aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bde96f8b-80b6-490d-98bc-6fe4799cc8aa', 'They have feathers to fly', false, '8d2e0168-630c-41e9-a513-b1867dff54aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c3a9f38-e92a-41b8-92fa-cb64bc094382', 'They have gills like sharks', false, '8d2e0168-630c-41e9-a513-b1867dff54aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d88ad56-b8ba-4ec2-9a5b-88e3aab4ee02', 'They eat rocks', false, '8d2e0168-630c-41e9-a513-b1867dff54aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32b34543-3fe9-4f5b-be16-0c4665bfcd47', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'What is the key difference between ''Breathing'' and ''Respiration'' in living organisms?', 'Breathing is physical gas exchange; cellular respiration is the metabolic catabolism of nutrients yielding ATP energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('775e765a-6e6b-48f5-9272-167529a2352f', 'Breathing is the physical intake of oxygen and release of carbon dioxide, while Respiration is the biochemical oxidation of glucose inside cells to release energy', true, '32b34543-3fe9-4f5b-be16-0c4665bfcd47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55c15923-3e04-406b-90f3-a6f9ef528796', 'Breathing produces food', false, '32b34543-3fe9-4f5b-be16-0c4665bfcd47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e94cf602-d541-4e90-8af0-ede101958c2e', 'Respiration is only done by plants', false, '32b34543-3fe9-4f5b-be16-0c4665bfcd47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a060d1eb-c027-4231-bbac-a96093f535b3', 'They are the exact same thing', false, '32b34543-3fe9-4f5b-be16-0c4665bfcd47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81fc2be4-0fe9-464b-a9c4-3a32b65731c0', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'Why is a car or an airplane that moves, consumes fuel, and exhausts smoke NOT considered a living organism?', 'Non-living machines lack biological homeostasis, cellular organization, intrinsic growth, and reproductive heredity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3bcbc9a-93e9-4976-ac98-866ba7419e65', 'It cannot grow, reproduce offspring, respond to biological stimuli, or carry out internal cellular metabolism independently', true, '81fc2be4-0fe9-464b-a9c4-3a32b65731c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1147e2b9-6d01-436b-8f9e-9066d737d60b', 'Because it is made of metal', false, '81fc2be4-0fe9-464b-a9c4-3a32b65731c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b92dc1d1-1976-4f25-a1c4-0f764ef1c19b', 'Because it has wheels', false, '81fc2be4-0fe9-464b-a9c4-3a32b65731c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5665cfea-6b23-4a57-8b0d-5a94cb60a261', 'Because it is too fast', false, '81fc2be4-0fe9-464b-a9c4-3a32b65731c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b609c05-5d16-4b1c-bb5c-89fd5532a35c', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How do green plants respire during the night when there is no sunlight for photosynthesis?', 'Cellular respiration occurs 24/7 in plants; at night without photosynthetic O₂ production, net gas exchange consumes O₂ and expels CO₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1542fa96-7661-4cc9-94b5-22fabd78130c', 'They take in Oxygen (O₂) and release Carbon Dioxide (CO₂) through microscopic stomata, exactly like animals do', true, '8b609c05-5d16-4b1c-bb5c-89fd5532a35c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b7cddb4-8346-4546-a5b9-917e6ba3794d', 'They stop respiring completely', false, '8b609c05-5d16-4b1c-bb5c-89fd5532a35c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0837c1f6-e1d5-4f71-b017-31df96197383', 'They produce glucose from moonlight', false, '8b609c05-5d16-4b1c-bb5c-89fd5532a35c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8500644e-fa28-4477-9fde-fa5a5cee210b', 'They turn into stone', false, '8b609c05-5d16-4b1c-bb5c-89fd5532a35c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7bea96e-1d95-441f-b62b-00b9e80d6c68', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'Which of the following organisms reproduces by laying eggs (Oviparous)?', 'Oviparous animals (birds, reptiles, amphibians, insects) lay eggs that hatch outside the maternal body.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c9d5be3-efc7-45c5-a1a2-4f4a0c1b45bc', 'Birds, Snakes, and Frogs', true, 'd7bea96e-1d95-441f-b62b-00b9e80d6c68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47ad8642-f2d1-4491-b739-4e72d33bbc96', 'Cows and Buffaloes', false, 'd7bea96e-1d95-441f-b62b-00b9e80d6c68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0cc4d98-2d7e-4526-a974-ccf0960d4951', 'Lions and Tigers', false, 'd7bea96e-1d95-441f-b62b-00b9e80d6c68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39cda5a4-501e-44ff-a12b-bf8d2e32eb95', 'Humans and Elephants', false, 'd7bea96e-1d95-441f-b62b-00b9e80d6c68');
