INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27ace157-4206-4208-8acc-9bb4fd356141', 'Fish (Gills)', false, '27d39577-e12d-43fc-8d2e-c59bbd8d5691');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbda60a-37eb-4643-9bfe-5098fb14f77d', 'Prawn (Gills)', false, '27d39577-e12d-43fc-8d2e-c59bbd8d5691');
