INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0cd73e42-4b67-4768-ae48-abb9ae28526d', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'A botanist investigates root development in three plant species: Cactus (Desert), Hydrilla (Submerged aquatic), and Neem (Mesophytic tree). What comparative root adaptations are observed?', 'Xerophytes develop extensive root networks to scavenge moisture; hydrophytes reduce roots because water surrounds the entire plant body.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12209e8a-5c0e-4cf9-8674-c98e5ec18a70', 'Cactus has deep extensive roots to reach deep groundwater; Hydrilla has very reduced roots purely for holding in place; Neem has widespread deep taproots', true, '0cd73e42-4b67-4768-ae48-abb9ae28526d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bd424e6-3bb2-4080-aade-0a04bb3814e4', 'Hydrilla has the deepest roots', false, '0cd73e42-4b67-4768-ae48-abb9ae28526d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('827de4ff-26cc-4eb9-9b59-fcbe3b3e9c4f', 'Cactus roots float in air', false, '0cd73e42-4b67-4768-ae48-abb9ae28526d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9b8646d-4a5c-4201-af93-17c00d272020', 'All three have identical root structures', false, '0cd73e42-4b67-4768-ae48-abb9ae28526d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f276e962-9a6a-47bf-857b-5b245c463e5a', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'Match Column I (Habitats & Adaptations) with Column II (Organisms):
(a) Padded feet, hump, dry dung         -> (i) Snow Leopard
(b) Thick fur on body, feet, long tail   -> (ii) Mountain Pine Tree
(c) Conical crown, sloping branches     -> (iii) Camel
(d) Webbed hind feet, moist skin         -> (iv) Frog', 'Camel = padded feet/hump; Snow Leopard = thick fur; Pine = conical crown; Frog = webbed feet.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5cee150-6087-4458-b5fa-9472d9df1e24', 'a-(iii), b-(i), c-(ii), d-(iv)', true, 'f276e962-9a6a-47bf-857b-5b245c463e5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6a8f741-436d-4e5e-956a-2669ca9db419', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'f276e962-9a6a-47bf-857b-5b245c463e5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c4deb0-41d6-4359-bf00-4bd52606e839', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'f276e962-9a6a-47bf-857b-5b245c463e5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1f24514-d589-4e2b-9fec-a06533af24c0', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'f276e962-9a6a-47bf-857b-5b245c463e5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22df162b-bc20-4fe4-95e8-cc560282e2a2', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'Read the statements regarding plant excretion:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4f542df-587a-4adc-956a-9d409f25c3c8', 'Statements 1 and 2 only', true, '22df162b-bc20-4fe4-95e8-cc560282e2a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8858a2c-7c28-4ac2-a1db-b702e6bb46e9', 'Statements 2 and 3 only', false, '22df162b-bc20-4fe4-95e8-cc560282e2a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60f19a7c-51c4-435e-9fe1-b29e64b53296', 'Statements 1 and 3 only', false, '22df162b-bc20-4fe4-95e8-cc560282e2a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('187871ce-4b1d-40c6-acc8-dbc8ee940cfd', 'All Statements 1, 2, and 3', false, '22df162b-bc20-4fe4-95e8-cc560282e2a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c300013-a25a-480e-bb2e-7f1d6abd4090', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'Why do seeds (like dry kidney beans or wheat grains) kept dry inside a kitchen jar stay dormant without growing for months, yet sprout rapidly when placed in moist soil with warmth and air?', 'Seed dormancy maintains low basal metabolic rate until hydration and oxygen activate gibberellins to initiate embryo growth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c91dba5f-fd0e-4561-a3ce-1a5363852cc3', 'Seeds are living biological entities in a state of suspended dormancy; moisture, oxygen, and warmth trigger enzymatic metabolic germination', true, '3c300013-a25a-480e-bb2e-7f1d6abd4090');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0267cc83-7810-4450-abc8-d41b16572c98', 'Seeds are non-living stones that turn alive', false, '3c300013-a25a-480e-bb2e-7f1d6abd4090');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d906e3c1-5348-4131-b1f7-afd6b9be3707', 'Soil injects electricity into seeds', false, '3c300013-a25a-480e-bb2e-7f1d6abd4090');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11175db9-bea8-4d53-9f83-394d40ebd277', 'Water creates seeds from magic', false, '3c300013-a25a-480e-bb2e-7f1d6abd4090');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d43f5d02-2980-43fa-b8e7-4fd7841df729', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'Consider four animals:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb458b03-48d0-4314-82e0-24927d0e1526', 'Animal 2 (Fish - streamlined body, mucous scales, fins)', true, 'd43f5d02-2980-43fa-b8e7-4fd7841df729');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f097a17-2ab1-40e6-8738-f94dadc4bc31', 'Animal 1', false, 'd43f5d02-2980-43fa-b8e7-4fd7841df729');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03579a46-73fb-4325-8e42-dbc24fe2e599', 'Animal 3', false, 'd43f5d02-2980-43fa-b8e7-4fd7841df729');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30536a8c-8aa2-44c7-850a-8fdd32f72e17', 'Animal 4', false, 'd43f5d02-2980-43fa-b8e7-4fd7841df729');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ac8e99b-b119-4ffb-a67d-e3d5c67d7003', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'How do plants respond to the unidirectional stimulus of sunlight (Phototropism)?', 'Phototropic curvature: Auxin redistributes to shaded stem tissues, promoting differential cell elongation towards the light vector.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13347d54-22a1-4553-8a2a-1d8c12c8e658', 'Shoots bend towards the light source due to the hormone auxin accumulating on the shaded side, while roots grow away from light into the soil', true, '0ac8e99b-b119-4ffb-a67d-e3d5c67d7003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd6e0554-c3b7-46d0-8458-3c2c7f225987', 'Plants close their leaves and hide', false, '0ac8e99b-b119-4ffb-a67d-e3d5c67d7003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b8dbe01-9e88-493b-a708-a612e1236535', 'Plants produce black smoke', false, '0ac8e99b-b119-4ffb-a67d-e3d5c67d7003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9a327c1-21bb-4581-9df8-51ba9845cdb2', 'Shoots grow straight into the ground', false, '0ac8e99b-b119-4ffb-a67d-e3d5c67d7003');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe636710-0289-4dc2-96ec-b90320350a56', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'Why is the urine of a camel extremely concentrated and viscous, and its dung completely dry?', 'Elongate loops of Henle in camel kidneys generate hyperosmotic urine, minimizing urinary and fecal water excretion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9600bad6-4e00-4103-936b-8619f8a1dde4', 'Extreme physiological water conservation: kidneys reabsorb maximum water to allow the camel to survive weeks without drinking water', true, 'fe636710-0289-4dc2-96ec-b90320350a56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46c213e5-68d8-4028-b451-35d73f321ea2', 'Camels eat sand', false, 'fe636710-0289-4dc2-96ec-b90320350a56');
