INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62a3ba65-10e7-4c44-b864-4aa7e9f06c4f', 'To make waste colorful', false, 'fe636710-0289-4dc2-96ec-b90320350a56');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fb0f11e-7f53-4e6a-bb54-05f33e42b93a', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'What is the primary ecological consequence when a non-native invasive species is introduced into a new habitat lacking natural predators?', 'Invasive species disrupt biotic food webs by outcompeting native taxa through aggressive unchecked proliferation.', NOW()) ON CONFLICT DO NOTHING;
