INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c65a6488-868c-444f-97e7-f94572da3924', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Easy', 'The complete collection of numbers consisting of all positive numbers, zero, and all negative numbers (... -3, -2, -1, 0, 1, 2, 3 ...) is called:', 'Integers comprise the set of whole numbers along with their negative additive inverses.', NOW()) ON CONFLICT DO NOTHING;
