INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f6f4845-0299-463e-bf16-ac58d9efd549', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'What does Nasir want to become when he grows up?', 'Nasir from Andhra Pradesh wants to learn how to preserve and collect cotton seeds so his family doesn''t spend money on new seeds every year.', NOW()) ON CONFLICT DO NOTHING;
