INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('502fd514-1ff0-4259-bf78-da5b549e501b', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'What does Serbjit do when he gets angry because people don''t believe him when he tells the truth?', 'Serbjit controls his temper by looking at his shoes and counting to ten when teachers or parents distrust his honest word.', NOW()) ON CONFLICT DO NOTHING;
