INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2653a63-849a-43ce-a1a2-5b22bbcb7e49', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'What is Dolma''s grand ambition for her future career?', 'Dolma has strong leadership qualities; when people say it''s impossible, she insists she will make things better for everyone as Prime Minister.', NOW()) ON CONFLICT DO NOTHING;
