INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc457c32-c8e6-46bf-a98d-9948564b76f9', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'What is Peter''s favorite day of the week, when his entire family goes to the cinema hall to watch a film?', 'Peter loves the second Sunday because the whole family enjoys movie tickets, interval peanuts, and ice cream together.', NOW()) ON CONFLICT DO NOTHING;
