INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80476220-3a88-41aa-b3f2-5e95d43ecb9d', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'What sweet fruit did the generous monkey pluck and throw down to his new friend, the crocodile?', 'The monkey shared delicious fresh berries with the visiting crocodile daily.', NOW()) ON CONFLICT DO NOTHING;
