INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb987803-b4f4-411b-a778-7312640b5b96', 'Mangoes', false, '80476220-3a88-41aa-b3f2-5e95d43ecb9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f94568f-5b42-4c77-ba67-774af18ae710', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'Why was the crocodile''s wife furious when the crocodile returned home very late one day?', 'Waiting impatiently with her newly hatched babies, the crocodile''s wife resented her husband''s long daily chats with the monkey.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bef2b07-e0e3-45c0-919e-2351fe5c4b71', 'She was tired of waiting and managing the newly hatched baby crocodiles alone', true, '0f94568f-5b42-4c77-ba67-774af18ae710');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('244dce8f-f07c-4e36-93a7-df76472a4890', 'She had lost her house', false, '0f94568f-5b42-4c77-ba67-774af18ae710');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bbe815c-4bb4-4d7c-a2ec-5efa6fa5a669', 'She was angry at the river', false, '0f94568f-5b42-4c77-ba67-774af18ae710');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9283dec0-0ff0-4e2f-b474-e3475322d135', 'She wanted to swim to the sea', false, '0f94568f-5b42-4c77-ba67-774af18ae710');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d93e60c-516d-4895-a6a7-2a2c9325d7ee', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'What wicked demand did the crocodile''s wife make after tasting the sweet berries brought home by her husband?', 'Her cruel greed demanded the monkey''s heart as an exotic delicacy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a6d2ac7-6060-46c8-afa5-440f99854eff', 'She demanded to eat the monkey''s heart, arguing that an animal eating such sweet fruit daily must have the sweetest heart', true, '8d93e60c-516d-4895-a6a7-2a2c9325d7ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3e4a457-5ec1-4133-9863-bfe06c7cacff', 'She wanted the monkey''s fur coat', false, '8d93e60c-516d-4895-a6a7-2a2c9325d7ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ae1dee9-470c-49a3-84a3-613010ff0ce1', 'She wanted the tree to be cut down', false, '8d93e60c-516d-4895-a6a7-2a2c9325d7ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4125f002-01e7-4203-b506-cb135b9d1a49', 'She wanted to live in the tree', false, '8d93e60c-516d-4895-a6a7-2a2c9325d7ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98e7508d-2f25-476e-b0c5-33039f39549b', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'How did the crocodile transport the monkey across the river to visit his home?', 'Unable to swim, the trusting monkey rode happily perched on the crocodile''s back.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b3dca76-65b5-4def-a538-a34d2a83add1', 'On the crocodile''s broad back', true, '98e7508d-2f25-476e-b0c5-33039f39549b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d50ff71d-4eba-418c-a57d-2df3f2ba09d5', 'In a wooden boat', false, '98e7508d-2f25-476e-b0c5-33039f39549b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c650862-07d9-4fba-af3f-4ec6d6bb10b4', 'On a floating log', false, '98e7508d-2f25-476e-b0c5-33039f39549b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53a5e821-b4fc-40b6-a6e5-e473a48b07d3', 'On a leaf', false, '98e7508d-2f25-476e-b0c5-33039f39549b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1138475f-aa09-4822-8a9b-7764bc014a4f', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'In the poem ''The Wonderful Words'' by Mary O''Neill, what are words described as?', 'Poet Mary O''Neill writes that words give physical form, elegance, and dynamic expression to human thoughts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('331ba98d-fbd8-4444-aac0-635670d5cde3', 'The food and dress of thought', true, '1138475f-aa09-4822-8a9b-7764bc014a4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2d4da6f-6b4c-47bd-bbf9-0102ee35d85d', 'Sharp weapons of war', false, '1138475f-aa09-4822-8a9b-7764bc014a4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcdb2215-c3e5-47bc-8191-fa070d420661', 'Meaningless sounds', false, '1138475f-aa09-4822-8a9b-7764bc014a4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3dc24d3-1a2d-4ac4-85cb-b71786ce8dd7', 'Cold stones', false, '1138475f-aa09-4822-8a9b-7764bc014a4f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17cd1346-9907-42dc-a04b-44402c88abe5', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What clever trick did the quick-witted monkey play in mid-stream when the crocodile confessed he was taking him to be killed?', 'The brilliant monkey feigned willingness to sacrifice himself, tricking the gullible reptile into returning to the tree to ''fetch his heart''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bf76a1c-058c-44a4-b6a2-70dbfaf4c9ec', 'He declared that he had left his heart safely behind on the tree branch, and persuaded the foolish crocodile to swim back to fetch it', true, '17cd1346-9907-42dc-a04b-44402c88abe5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a373f11-0064-4acb-a3a2-fc1038c3db29', 'He jumped into the water and drowned the crocodile', false, '17cd1346-9907-42dc-a04b-44402c88abe5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0db7b051-de9f-4d92-a0b3-200fdef88bc2', 'He hit the crocodile with a stone', false, '17cd1346-9907-42dc-a04b-44402c88abe5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d9aa318-9590-4f26-a6b8-df8260d3983f', 'He called other monkeys for help', false, '17cd1346-9907-42dc-a04b-44402c88abe5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34a65920-a548-432b-9e9e-4049b68403dd', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What did the monkey do the moment the crocodile reached back to the riverbank tree?', 'Reaching safety, the monkey rebuked the treacherous crocodile for his betrayal and ended the friendship forever.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('580f0fae-1020-4a3e-9607-6c0a3e00d18d', 'He leaped up to the safety of the tree branch in a flash, threw down fruit, and permanently terminated their friendship', true, '34a65920-a548-432b-9e9e-4049b68403dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3043a0a-fc7b-4c25-879b-8711ba2d0713', 'He gave his heart to the crocodile', false, '34a65920-a548-432b-9e9e-4049b68403dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2a7311a-3650-4737-a652-b31a1594d381', 'He jumped into the crocodile''s mouth', false, '34a65920-a548-432b-9e9e-4049b68403dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e7678f1-3dda-4691-b03d-2e604c8e3ff5', 'He invited the crocodile''s wife to the tree', false, '34a65920-a548-432b-9e9e-4049b68403dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae1b0dd7-31a4-4d93-9ca8-132b9218ab24', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What moral lesson does the Panchatantra classic ''The Monkey and the Crocodile'' teach?', 'Mental agility and composure in crises defeat brute betrayal and treachery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4aefbf0-837c-4203-bc5f-8a88b82acd9d', 'Presence of mind, quick wit, and intelligence can overcome the deadliest danger; a treacherous friend is worse than an open enemy', true, 'ae1b0dd7-31a4-4d93-9ca8-132b9218ab24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('782b2f5c-d079-49d9-9621-705a0998b6f0', 'Crocodiles are the fastest swimmers', false, 'ae1b0dd7-31a4-4d93-9ca8-132b9218ab24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da6b72b9-b5c3-4349-a7fa-7b3fa8851c94', 'Monkeys should never eat fruit', false, 'ae1b0dd7-31a4-4d93-9ca8-132b9218ab24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8ac8991-2882-4c4d-b440-1b842c1af1ac', 'Trees should not grow near rivers', false, 'ae1b0dd7-31a4-4d93-9ca8-132b9218ab24');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0f5ba15-1617-40ea-98f5-ba7b21bc852b', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'In ''Who I Am'', what central message is celebrated through the six unique children (Radha, Nasir, Rohit, Serbjit, Dolma, Peter)?', 'The chapter showcases Howard Gardner''s multiple intelligences: bodily-kinesthetic, naturalist, interpersonal, visual-spatial, and linguistic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1b4f744-e982-401b-bed0-3e9fc06636cd', 'Every individual child is uniquely talented, has distinct aspirations, intelligences, and ways of viewing the world that deserve celebration', true, 'b0f5ba15-1617-40ea-98f5-ba7b21bc852b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e0b68a6-ae8b-476d-aeaf-8b241e481794', 'All children must have the exact same career dream', false, 'b0f5ba15-1617-40ea-98f5-ba7b21bc852b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07b20b10-7774-4e6f-ba36-b633f127ce73', 'Only children who climb trees are smart', false, 'b0f5ba15-1617-40ea-98f5-ba7b21bc852b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e644f0b-1fe3-481a-9ac9-fc090a80ebb3', 'Children should never share their thoughts', false, 'b0f5ba15-1617-40ea-98f5-ba7b21bc852b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a74b297d-127c-472b-ae68-32313a3c84c8', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'In the poem ''The Wonderful Words'', why does the poet advise: ''Never let a thought shrivel and die for want of a way to say it''?', 'Language empowers humans to liberate imprisoned thoughts into radiant verbal articulation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96fa8adf-aaa8-4ecb-880d-26c20cd54166', 'Because English is a wonderful game of words that allows anyone to express their finest, brightest ideas clearly and beautifully', true, 'a74b297d-127c-472b-ae68-32313a3c84c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1326bf1-c15d-45fc-a612-e3b526ad86e0', 'Because thoughts can bite you', false, 'a74b297d-127c-472b-ae68-32313a3c84c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('217758a8-e443-4fc1-9a61-766a4ba58b0f', 'Because silence is dangerous', false, 'a74b297d-127c-472b-ae68-32313a3c84c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30b712df-b4f8-4cda-a0db-24605ff780ee', 'Because dictionaries are free', false, 'a74b297d-127c-472b-ae68-32313a3c84c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3535707e-5790-4edc-9f90-80d137a5b2b3', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What is Visual-Spatial intelligence, as demonstrated by someone who thinks in pictures, loves maps, diagrams, and visual arts?', 'Visual-spatial learners navigate 3D environments, orient maps, and conceptualize architectural imagery effortlessly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('562dd081-d6ec-4dcf-be51-7b59f8622c6e', 'Visual intelligence', true, '3535707e-5790-4edc-9f90-80d137a5b2b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df379e9c-4d38-44c2-bf5a-9c699557339e', 'Bodily-Kinesthetic intelligence', false, '3535707e-5790-4edc-9f90-80d137a5b2b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7900d605-3c3e-4d7b-a761-22ac785ce8ef', 'Musical intelligence', false, '3535707e-5790-4edc-9f90-80d137a5b2b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4158708-b01f-47c3-8055-e12930a4147d', 'Mathematical intelligence', false, '3535707e-5790-4edc-9f90-80d137a5b2b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6aab57ab-435d-4ab0-8f69-aad095f24d28', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What is Bodily-Kinesthetic intelligence, as demonstrated by Radha who loves climbing and physical coordination?', 'Bodily-kinesthetic intelligence involves gross and fine motor coordination, physical balance, and tactile mastery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aac48e9-1e03-4d0c-9fc8-2a636ef1cabd', 'The ability to control body movements, physical agility, balance, and handle objects skillfully', true, '6aab57ab-435d-4ab0-8f69-aad095f24d28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78090bf3-999c-468d-8e6b-cb84dcceeb01', 'The ability to solve calculus problems', false, '6aab57ab-435d-4ab0-8f69-aad095f24d28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d40e0f9-f9f2-4134-a486-d4d3864569cb', 'The ability to compose symphony music', false, '6aab57ab-435d-4ab0-8f69-aad095f24d28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e086422-88e4-499f-bbe0-bc53da05f466', 'The ability to speak 10 languages', false, '6aab57ab-435d-4ab0-8f69-aad095f24d28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec2b7051-733e-4f83-a002-f0371d1e8c1a', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What is Interpersonal intelligence, as demonstrated by Dolma who loves resolving classmates'' disputes and leading groups?', 'Interpersonal intelligence enables leadership, social empathy, mediation, and group teamwork.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('998e6765-2c84-4fa8-be40-676278479821', 'The ability to understand, empathize with, motivate, and collaborate effectively with other people', true, 'ec2b7051-733e-4f83-a002-f0371d1e8c1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0453fb33-7eb6-4c8a-9e64-a36688b9b7f6', 'The ability to talk to oneself only', false, 'ec2b7051-733e-4f83-a002-f0371d1e8c1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0c485a0-c750-45d6-b317-f902c4c29b55', 'The ability to paint portraits', false, 'ec2b7051-733e-4f83-a002-f0371d1e8c1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7310cd50-39b5-469b-8242-d729e35a781c', 'The ability to run fast', false, 'ec2b7051-733e-4f83-a002-f0371d1e8c1a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3b451f0-a6ca-413a-80e1-87241202124b', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'Why was the crocodile torn between two conflicting loyalties in the middle of the river?', 'His moral dilemma: honoring sacred friendship versus succumbing to marital pressure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22820f04-162d-44b2-836b-ec36756a4541', 'He genuinely loved his loyal friend the monkey, but could not resist or disobey his aggressive, demanding wife', true, 'd3b451f0-a6ca-413a-80e1-87241202124b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d44ed53-c779-441c-856e-1d23a32b4995', 'He wanted to become a vegetarian', false, 'd3b451f0-a6ca-413a-80e1-87241202124b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ce8fcb4-4f57-4964-9d3f-5a6ff6e531f7', 'He forgot how to swim', false, 'd3b451f0-a6ca-413a-80e1-87241202124b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6114a5aa-1d11-4069-8f85-7986df9d261f', 'He was afraid of water', false, 'd3b451f0-a6ca-413a-80e1-87241202124b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('574c8197-7924-46cc-bdaa-d8e2202585d4', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What does the word ''Preserve'' mean when Nasir talks about cotton seeds?', 'Preservation involves storing and protecting biological germplasm seeds across planting seasons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7f4ab6c-6119-4529-9dda-6ec4f17944f2', 'To save, maintain, and protect something safely for future use', true, '574c8197-7924-46cc-bdaa-d8e2202585d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95cfb59d-f89e-4993-ad80-03f35af799b4', 'To destroy by burning', false, '574c8197-7924-46cc-bdaa-d8e2202585d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4961415a-109d-427b-8cb5-43ab2e65285c', 'To throw into the river', false, '574c8197-7924-46cc-bdaa-d8e2202585d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2454e5aa-da34-4c6e-95e4-2f10f03498e8', 'To eat immediately', false, '574c8197-7924-46cc-bdaa-d8e2202585d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('588e7d25-01e4-492b-9ca8-f1f35e6099eb', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What does the phrase ''to shrivel and die'' mean in ''The Wonderful Words''?', '''Shrivel'' metaphorically depicts unuttered ideas withering away from lack of communicative expression.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93c75259-1d9d-49d3-87dd-f635742cad5f', 'To shrink, dry up, wither away, and disappear without being expressed', true, '588e7d25-01e4-492b-9ca8-f1f35e6099eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('897e0e07-e386-4aea-9052-3db4915b07da', 'To grow very large', false, '588e7d25-01e4-492b-9ca8-f1f35e6099eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bcb8a68-0203-453e-b025-9d475a3e0cd9', 'To sing a song', false, '588e7d25-01e4-492b-9ca8-f1f35e6099eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80462716-935f-4279-ad04-de891e063098', 'To fly like a kite', false, '588e7d25-01e4-492b-9ca8-f1f35e6099eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('891df70e-02e5-45fe-96b1-a1e5537356b4', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'Why does Dolma say: ''I know that when I grow up, I will be a great Prime Minister''?', 'Dolma exhibits natural civic responsibility, public problem-solving, and infrastructural vision for society.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('726952c8-7d6b-407f-be93-6aa50dc527a3', 'Because everyone in school comes to her with problems, teachers trust her to manage things, and she genuinely wants to build better hospitals and roads', true, '891df70e-02e5-45fe-96b1-a1e5537356b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0537917-ef9e-432a-874d-b225318d7eca', 'Because she wants to be rich and famous', false, '891df70e-02e5-45fe-96b1-a1e5537356b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70f9b67b-236a-4344-87d5-a8476923ccfe', 'Because her parents ordered her to', false, '891df70e-02e5-45fe-96b1-a1e5537356b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbd8ffbd-b3d4-429c-888f-099c1f90cf83', 'Because she wants to fly in an aeroplane', false, '891df70e-02e5-45fe-96b1-a1e5537356b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ea6d151-bcd4-4e54-98a3-65c2565fe2a7', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'In the poem ''The Wonderful Words'', what is described as being ''imprisoned behind your eyes''?', 'The poet portrays unvoiced thoughts as captives in the mind awaiting liberation through eloquent vocabulary.', NOW()) ON CONFLICT DO NOTHING;
