INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa7b1a67-ce7d-4384-9fd3-6001258734d8', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What is Musical intelligence in Howard Gardner''s theory?', 'Musical intelligence governs auditory harmonic sensitivity, rhythm, pitch discernment, and compositional skill.', NOW()) ON CONFLICT DO NOTHING;
