INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e9e40bd-2038-4617-82c7-1dfb35b773fe', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'In ''The Wonderful Words'', what profound linguistic philosophy does Mary O''Neill advocate?', 'The poem celebrates verbal literacy as the indispensable vehicle for manifesting internal human consciousness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('561e52fe-4d5e-466e-91bc-44aaeb45c2c4', 'Language is a living creative instrument: we must actively nurture vocabulary so that brilliant human thoughts are not silenced by linguistic poverty', true, '8e9e40bd-2038-4617-82c7-1dfb35b773fe');
