INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0016ea3-4dd2-432d-8130-55ee5bfc2c8f', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'Identify the figure of speech in Mary O''Neill''s line: ''Words are the food and dress of thought.''', 'A direct figurative equation comparing verbal words to food (nourishment) and dress (outer form) without using ''like'' or ''as'' is a Metaphor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50f4feea-7ecd-41bc-a14e-93de0a34ebab', 'Metaphor (direct non-literal comparison between words and nourishing clothing)', true, 'c0016ea3-4dd2-432d-8130-55ee5bfc2c8f');
