INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84c00035-d50e-408c-a62e-95aa75ed1fe7', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'What is the meaning of the adjective ''Treacherous'' as applied to the crocodile''s deceitful act?', '''Treacherous'' characterizes perfidious violation of mutual faith, alliance, or sworn friendship.', NOW()) ON CONFLICT DO NOTHING;
