INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7179ac5-e57d-4038-9c89-0d625220a00e', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'How does Serbjit constructively channel and regulate his intense emotional frustration when misunderstood?', 'Counting to ten and grounding visual focus is an effective cognitive-behavioral technique for anger management.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbb221a9-e9e0-43aa-8cdf-000e1e25ba6e', 'Through cognitive mindfulness: looking down at his shoes and counting to ten to prevent impulsive verbal rage', true, 'a7179ac5-e57d-4038-9c89-0d625220a00e');
