INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96bb1edd-2528-45d8-87f3-34216e4717de', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'What is the grammatical function of the underlined clause in: ''Nasir wants to know *how seeds can be collected for future farming*.''', 'The embedded interrogative clause functions as the direct object of the transitive verb ''know'', making it a Noun Clause.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa285c18-e038-4250-8599-ed96cf992573', 'Noun Clause (functioning as the direct object of the verb ''know'')', true, '96bb1edd-2528-45d8-87f3-34216e4717de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df5d8eb1-4fc2-4b10-b5e4-bc9f043eb34a', 'Adjective Clause', false, '96bb1edd-2528-45d8-87f3-34216e4717de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9dcbaa5-db0c-4302-9714-41e80de13a0c', 'Adverb Clause of Time', false, '96bb1edd-2528-45d8-87f3-34216e4717de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88bd3a10-de86-4c59-b9c0-e6bbe3a43053', 'Prepositional Phrase', false, '96bb1edd-2528-45d8-87f3-34216e4717de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eff436d6-67ec-4619-8904-40dd52d5161b', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'In ''The Monkey and the Crocodile'', what tragic philosophical reality did the crocodile realize upon reaching the bank?', 'Betraying moral integrity for unholy appeasement results in irreversible spiritual and relational bankruptcy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('366f5fbd-3bd4-4670-9e59-4a12d6e959f0', 'That an unprincipled compromise made to please an evil demand cost him the rarest treasure of life: a loyal, noble, and compassionate friend', true, 'eff436d6-67ec-4619-8904-40dd52d5161b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b6e7ee0-f4b9-4aad-a87b-08de39091c47', 'That berries are poisonous', false, 'eff436d6-67ec-4619-8904-40dd52d5161b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cec067cb-d1f9-465f-a743-415e73dc6f15', 'That swimming across rivers is impossible', false, 'eff436d6-67ec-4619-8904-40dd52d5161b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('125feb07-042c-4fb9-b872-92117fa27f0d', 'That his wife was right all along', false, 'eff436d6-67ec-4619-8904-40dd52d5161b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3373504-6941-4fc6-983e-e6a4366812c4', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'What is Intrapersonal intelligence according to psychology?', 'Intrapersonal intelligence is self-reflective awareness of one''s internal cognitive processes, emotional triggers, and identity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73d1633d-a73a-487d-a26d-dbebf7ef13df', 'The capacity for deep self-awareness, metacognition, understanding one''s own emotions, strengths, weaknesses, and values', true, 'f3373504-6941-4fc6-983e-e6a4366812c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5f6b9e9-99d8-4a53-8494-c42a23a75851', 'The ability to talk to 100 people at once', false, 'f3373504-6941-4fc6-983e-e6a4366812c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52d42d9d-ff01-4cd4-a225-3af471456d31', 'The skill of navigating ships', false, 'f3373504-6941-4fc6-983e-e6a4366812c4');
