INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e0e6f25-8da9-4fe4-9a80-9d7700dabe0a', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'What unifying theme links ''Who I Am'', ''The Monkey and the Crocodile'', and ''The Wonderful Words'' in Class 6 English?', 'All three selections celebrate authentic individuality, expressive eloquence, and intellectual wisdom in navigating life''s challenges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d76244ce-9ccb-4461-b543-237a9847672d', 'The profound triumph of self-identity, articulate communication, moral integrity, and mental wisdom over blind conformity and brute malice', true, '1e0e6f25-8da9-4fe4-9a80-9d7700dabe0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('777407ef-d896-483a-8ab1-27f922794cce', 'The superiority of animals over humans', false, '1e0e6f25-8da9-4fe4-9a80-9d7700dabe0a');
