INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9d9f096-068f-47bc-8e80-11f515d3d3dc', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Medium', 'Which sacred Sikh golden shrine in Amritsar, Punjab, founded by Guru Ram Das and constructed by Guru Arjan Dev with its foundation stone laid by Sufi saint Mian Mir, has four open doors symbolizing welcome to people of all faiths and castes?', 'Harmandir Sahib sits in the center of the Amrit Sarovar holy tank, gold-plated by Maharaja Ranjit Singh in 1830, running the world''s largest free community kitchen (Langar).', NOW()) ON CONFLICT DO NOTHING;
