INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37b3816b-09fc-4a7c-bbc9-f198e9ff57a3', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'What is the architectural name of the ancient open-air bas-relief rock sculpture in Mahabalipuram depicting the descent of the sacred river Ganga onto Earth, measuring 27m by 9m?', 'Carved onto two massive pink granite boulders with a natural cleft representing the descending celestial river, it depicts gods, gandharvas, and elephants.', NOW()) ON CONFLICT DO NOTHING;
