INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eadb1948-4ac5-4832-b9c8-f002699f9674', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Match Column I (Iconic Monuments) with Column II (Dynasties / Rulers who built them):
(a) Kailash Rock Temple (Ellora) -> (i) Chola Dynasty (Rajaraja I)
(b) Brihadisvara Temple (Thanjavur) -> (ii) Rashtrakuta Dynasty (Krishna I)
(c) Konark Sun Temple (Odisha)    -> (iii) Mughal Emperor Shah Jahan
(d) Red Fort (Delhi)             -> (iv) Eastern Ganga Dynasty (Narasimhadeva I)', 'Kailash = Rashtrakuta; Brihadisvara = Chola; Konark = Eastern Ganga; Red Fort = Mughal (Shah Jahan).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c5ecd74-0b1d-4a69-8d80-917a28e5471d', 'a-(ii), b-(i), c-(iv), d-(iii)', true, 'eadb1948-4ac5-4832-b9c8-f002699f9674');
