INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b730b74-5376-4b94-b505-5d6a8b6bd55c', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'What is the famous acoustic phenomenon of the whispering gallery inside the massive dome of the Gol Gumbaz (mausoleum of Mohammed Adil Shah in Bijapur, Karnataka)?', 'The acoustic geometry of Gol Gumbaz''s 44-meter unsupported acoustic dome channels sound waves around smooth circular gallery perimeters with minimal decay.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3cdb06e-2a13-4a78-9f4b-bd99c79ebc76', 'The faintest whisper at one side of the 44-meter circular gallery can be heard crystal clear on the diametrically opposite side, and a single handclap echoes 7 to 10 times', true, '1b730b74-5376-4b94-b505-5d6a8b6bd55c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cff7185e-9adc-4c20-9215-9e0dc934c928', 'Sound disappears completely', false, '1b730b74-5376-4b94-b505-5d6a8b6bd55c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6339d4f-0cf1-4daf-af58-496a07153e8a', 'It turns human voices into bird songs', false, '1b730b74-5376-4b94-b505-5d6a8b6bd55c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('692e04ad-c220-4992-a3a1-e5a70026ece3', 'Only whispers in Persian can be heard', false, '1b730b74-5376-4b94-b505-5d6a8b6bd55c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f73e0eb1-4446-4059-b7c2-a5bcb3bc1d4f', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Which 15th-century nine-storey marble and red sandstone victory tower in Chittorgarh Fort, Rajasthan, was built by Maharana Kumbha to commemorate his triumph over the combined Sultanate armies of Malwa and Gujarat?', 'Vijay Stambha is a 37.2-meter high nine-storeyed architectural encyclopedia of Hindu iconography and Vaishnava sculpture completed in 1448.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4984283c-eed1-4411-90a2-3fd7db760913', 'Vijay Stambha (Tower of Victory)', true, 'f73e0eb1-4446-4059-b7c2-a5bcb3bc1d4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e08260db-9093-41e9-be6a-eecd285d7796', 'Kirti Stambha', false, 'f73e0eb1-4446-4059-b7c2-a5bcb3bc1d4f');
