INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('637de633-a3a7-430c-b3e7-b05e99a91557', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Which cave island in Mumbai harbor features the colossal 6-meter high three-headed rock-cut relief sculpture of ''Trimurti'' (Sadashiva representing creation, preservation, and destruction)?', 'Elephanta''s rock-cut monolithic cavern features the celebrated 20-foot high masterpiece sculpture of three-headed Shiva (Aghora, Tatpurusha, and Vamadeva).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e676438-4209-42e0-b5de-c9bcb3e61e70', 'Elephanta Caves (Gharapuri Island)', true, '637de633-a3a7-430c-b3e7-b05e99a91557');
