INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61180140-3366-4de6-b672-de4a0921907d', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Which ancient university in Bihar, founded by Gupta Emperor Kumaragupta I in the 5th century CE, was a renowned global center of learning that housed 10,000 students and 2,000 scholars from across Asia?', 'Nalanda was a premier residential monastic university with a vast nine-storey library (Dharmaganja) visited by Chinese pilgrim Xuanzang.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a7d9348-43d4-431a-b00f-d07b4400317e', 'Nalanda Mahavihara (Nalanda University)', true, '61180140-3366-4de6-b672-de4a0921907d');
