INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4717cf5-d37c-4cb9-b4c2-408df5a9d459', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'What is the unique structural engineering feature of the famous 18th-century stepwell ''Chand Baori'' in Abhaneri, Rajasthan?', 'Chand Baori''s 3,500 geometric zigzagging steps create a mesmerizing optical geometry designed to harvest rainwater in drought-prone eastern Rajasthan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('888b5546-3638-4457-b8e5-6da925710f42', 'It consists of 3,500 narrow, perfectly symmetrical stone steps arranged across 13 storeys plunging 20 meters deep into the earth', true, 'b4717cf5-d37c-4cb9-b4c2-408df5a9d459');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('422e5fb7-f1d1-4f8c-b1ee-ceab428fe481', 'It was built entirely upside down without water', false, 'b4717cf5-d37c-4cb9-b4c2-408df5a9d459');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcf16e71-5d14-4569-a09f-814ffa830714', 'It is carved from gold', false, 'b4717cf5-d37c-4cb9-b4c2-408df5a9d459');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53cb08a2-ef2c-48bd-bc41-d669938e65cf', 'It has no stairs', false, 'b4717cf5-d37c-4cb9-b4c2-408df5a9d459');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b416174-b330-49ae-9146-f4113a09491a', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Which temple complex in Delhi and Gujarat, built by BAPS Swaminarayan Sanstha, holds the Guinness World Record as the world''s largest comprehensive Hindu temple campus, carved entirely from Rajasthani pink sandstone and Italian Carrara marble without using any structural steel?', 'Akshardham New Delhi was constructed strictly following ancient Shilpa Shastra interlocking stone-joinery without any ferrous structural metal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30e5cd09-9d7d-457b-956d-d0dd02435288', 'Akshardham Temple', true, '0b416174-b330-49ae-9146-f4113a09491a');
