INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a9a9a15-3f35-425f-acef-5e8de4845904', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Which Victorian Gothic railway terminus in Mumbai, designed by Frederick William Stevens and completed in 1887, is a UNESCO World Heritage site blending Victorian Italianate High Gothic architecture with traditional Indian stone palace craftsmanship?', 'CSMT is characterized by its grand stone dome, turrets, pointed arches, stained glass, and decorative wood and brass carvings.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4e90b32-7ea3-4d8b-bbfa-96f9d6351648', 'Chhatrapati Shivaji Maharaj Terminus (CSMT / formerly Victoria Terminus)', true, '3a9a9a15-3f35-425f-acef-5e8de4845904');
