INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('385dca8a-d0e7-426a-80f1-242800b19b0b', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Any natural elevation of the Earth''s surface considerably higher and steeper than the surrounding area, with a small summit and broad base, is a:', 'A mountain is a steep natural topographic elevation rising significantly above the surrounding terrain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9366b726-e904-42f8-8b15-43986b750041', 'Mountain', true, '385dca8a-d0e7-426a-80f1-242800b19b0b');
