INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d63da736-8794-4e18-ae80-e4d01f505bcc', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'A line or continuous arrangement of mountains stretching over hundreds of kilometers is called a:', 'A mountain range is a linear succession of interconnected mountain ridges and summits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0946700a-ae1a-43cb-a19f-69809def8ad7', 'Mountain Range (e.g. Himalayas, Andes, Alps)', true, 'd63da736-8794-4e18-ae80-e4d01f505bcc');
