INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('060933ec-c429-454f-b24a-1bce9f5ef40f', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Permanently frozen rivers of solid ice moving slowly down high mountain slopes are called:', 'Glaciers are persistent masses of recrystallized ice flowing downhill under gravity in high alpine zones.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c4a88c3-8f64-4f91-a39b-9e091d8a5882', 'Glaciers (e.g. Gangotri, Siachen)', true, '060933ec-c429-454f-b24a-1bce9f5ef40f');
