INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c538d37e-7a4d-4c1c-86db-0e1e65308bd4', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Mountains formed by the tectonic folding and buckling of crustal rock layers under intense compressive forces are called:', 'Fold mountains form at convergent plate boundaries where crustal sediments buckle into anticlines and synclines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae6f459d-a509-4d4f-9414-ac35ad07592b', 'Fold Mountains (e.g., Himalayas, Alps, Aravalli, Rockies)', true, 'c538d37e-7a4d-4c1c-86db-0e1e65308bd4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b4b1a8e-0dc3-47e7-8284-832f03fc70e0', 'Block Mountains', false, 'c538d37e-7a4d-4c1c-86db-0e1e65308bd4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de183e3e-bc29-4e5f-b262-97fbd44818b3', 'Volcanic Mountains', false, 'c538d37e-7a4d-4c1c-86db-0e1e65308bd4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baf733ba-5492-4f37-9a0f-a4c020b032a5', 'Residual Mountains', false, 'c538d37e-7a4d-4c1c-86db-0e1e65308bd4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81d98c68-df93-4697-9e45-a962bb1d5f4d', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'What are the two major youthful fold mountain systems in Asia and Europe characterized by rugged relief and high conical peaks?', 'The Himalayas and Alps are young Cenozoic fold mountain belts with sharp soaring peaks and deep gorges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('180b5d4b-232d-4349-8d07-65ce6ffe7eb3', 'The Himalayas (Asia) and the Alps (Europe)', true, '81d98c68-df93-4697-9e45-a962bb1d5f4d');
