INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8979b5bd-1780-4c91-9ab0-c688f36ae572', 'The Vosges and Black Forest', false, '81d98c68-df93-4697-9e45-a962bb1d5f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4a1b51f-dc4c-4582-a608-1c052ea4721d', 'Kilimanjaro and Fujiyama', false, '81d98c68-df93-4697-9e45-a962bb1d5f4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d01883b-806a-4e27-b5ff-7bfd6366075f', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'An elevated flat-topped tableland standing abruptly above the surrounding area with one or more steep sides is called a:', 'A plateau is a high-altitude, flat-topped geomorphic tableland bounded by steep escarpments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9843352-5857-41be-86ee-942e3c778ae2', 'Plateau (e.g., Deccan Plateau, Tibetan Plateau)', true, '6d01883b-806a-4e27-b5ff-7bfd6366075f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38e47950-848a-44f2-83bf-1087a4cb608c', 'Plain', false, '6d01883b-806a-4e27-b5ff-7bfd6366075f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('849b9585-b6c3-4bfa-ad51-9116fa114282', 'Mountain', false, '6d01883b-806a-4e27-b5ff-7bfd6366075f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66241a4e-0c22-4252-a1ad-2b8c449eae2c', 'Canyon', false, '6d01883b-806a-4e27-b5ff-7bfd6366075f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf0092e6-92f8-4bc7-a8ee-761242c2f132', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'What is the highest plateau in the world (often crowned the ''Roof of the World'') with an elevation of 4,000 to 6,000 meters above sea level?', 'The Tibetan Plateau covers 2.5 million km² at an average altitude exceeding 4,500 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0741952-6b5e-44ea-ad3c-69a9ec333625', 'Tibetan Plateau', true, 'bf0092e6-92f8-4bc7-a8ee-761242c2f132');
