INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee80ad7b-3f48-453a-9f69-431f4251f663', 'East African Plateau', false, 'bf0092e6-92f8-4bc7-a8ee-761242c2f132');
