INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('481df99e-781a-4269-b56f-16bf2219cfce', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Vast, low-lying flat stretches of land generally not more than 200 meters above mean sea level are called:', 'Plains are extensive level landscapes formed by fluvial alluvium deposition along river systems.', NOW()) ON CONFLICT DO NOTHING;
