INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c650552-1955-4aee-8f62-e3aa9a3947e9', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Why are river Plains the MOST DENSELY POPULATED regions in the world?', 'Deep alluvial topsoils, perennial irrigation, and flat topography support high-yield agriculture and urban transport infrastructure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea5e4647-ec8f-4474-bdaa-22ac8cefee0b', 'Extremely fertile alluvial soil, abundance of fresh river water, level flat land easy for agriculture, transport networks, and building cities', true, '8c650552-1955-4aee-8f62-e3aa9a3947e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d0771a5-cb15-4abe-b887-3174d71b4db2', 'Because plains have no trees', false, '8c650552-1955-4aee-8f62-e3aa9a3947e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fedae67-0da1-4b01-a9e8-34edd20dfa96', 'Because mountains are too hot', false, '8c650552-1955-4aee-8f62-e3aa9a3947e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d1bcfdd-00a7-4116-99e6-c85ac6279051', 'Because plains have no gravity', false, '8c650552-1955-4aee-8f62-e3aa9a3947e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53fac322-3a33-4800-9c34-490592e0140c', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Mountains formed due to the accumulation and cooling of molten volcanic lava, ash, and pyroclastic ejecta around a volcanic vent are:', 'Volcanic stratocones (Kilimanjaro, Fuji, Vesuvius) are constructed from repeated cooled lava flows and tephra.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c19b80d2-448d-40cb-85b3-85737f6bb3d0', 'Volcanic Mountains (e.g., Mount Kilimanjaro in Africa, Mount Fujiyama in Japan)', true, '53fac322-3a33-4800-9c34-490592e0140c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02826d54-5d30-434d-8069-4ad1de2f982a', 'Fold Mountains', false, '53fac322-3a33-4800-9c34-490592e0140c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f97d22b-5afe-4152-a413-53de9667c524', 'Block Mountains', false, '53fac322-3a33-4800-9c34-490592e0140c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89e8a61f-0107-42e2-920f-407f5e1bdde8', 'Erosional Mountains', false, '53fac322-3a33-4800-9c34-490592e0140c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb113c09-6719-4203-9ad2-98e67f7d3bc2', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'The process of the Earth''s surface wearing away and being carried down by running water, wind, and glaciers is called:', 'Erosion is the exogenic geomorphic breakdown and transport of rock particles by mobile natural agents.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0e03839-2e6b-469a-90c2-c452cfdcf20d', 'Erosion', true, 'bb113c09-6719-4203-9ad2-98e67f7d3bc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af595546-d2ad-477e-a2e5-05622f5696bb', 'Deposition', false, 'bb113c09-6719-4203-9ad2-98e67f7d3bc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e3edf38-1aca-4848-9aad-bfe1ee1a7b75', 'Volcanism', false, 'bb113c09-6719-4203-9ad2-98e67f7d3bc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68a44b4f-3929-4952-a01b-8fa522b624c0', 'Faulting', false, 'bb113c09-6719-4203-9ad2-98e67f7d3bc2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fff4ef5-f3b8-475a-b759-af1fdab13a40', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'The process of dropping and laying down weathered rock sediments by water, wind, or ice to rebuild landforms is called:', 'Deposition occurs when the kinetic transport energy of wind, rivers, or glaciers wanes, dropping alluvial silt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa05b96-dd94-4afe-a096-a3d76140135f', 'Deposition', true, '9fff4ef5-f3b8-475a-b759-af1fdab13a40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a5cf5aa-3795-455a-aca1-f9eb48d3dfe1', 'Erosion', false, '9fff4ef5-f3b8-475a-b759-af1fdab13a40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d546d81-b940-4f3d-93e1-e4ff3bc19a55', 'Subduction', false, '9fff4ef5-f3b8-475a-b759-af1fdab13a40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b812447-39c9-4504-b48e-d51b883fc09f', 'Weathering', false, '9fff4ef5-f3b8-475a-b759-af1fdab13a40');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25f42e41-13b4-453b-b779-b1fa6234fb7e', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'How are ''Block Mountains'' formed when large sections of the Earth''s crust crack, fault, and displace vertically?', 'Tensional crustal faulting raises horst block massifs (e.g. Vosges, Black Forest) and drops graben rift valleys (Rhine Valley).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36ad6a67-d4d8-45f8-bd26-70871352ba85', 'The uplifted block between faults is called a ''Horst'' (Block Mountain) and the sunken depressed valley between them is called a ''Graben'' (Rift Valley)', true, '25f42e41-13b4-453b-b779-b1fa6234fb7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fe88cc7-6190-451b-adde-094f10ab1bc4', 'Lava explodes into the sky', false, '25f42e41-13b4-453b-b779-b1fa6234fb7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01f3969b-9b57-43ee-a414-c5dd48e922c8', 'Rivers cut through soft clay', false, '25f42e41-13b4-453b-b779-b1fa6234fb7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('441ed93f-161e-4b8d-b3e9-ec6d895da743', 'Glaciers melt into water', false, '25f42e41-13b4-453b-b779-b1fa6234fb7e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a813b02a-2844-489f-aca5-d0d9d69e9cc1', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Which of the following mountain ranges in Europe are classic examples of Block Mountains and an associated Rift Valley?', 'The Rhine Graben rift valley is bounded on either side by the uplifted Vosges and Black Forest horst fault blocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d45fc9fe-e039-4e25-a5f7-ea257be1f0df', 'The Rhine Valley and the Vosges / Black Forest mountains', true, 'a813b02a-2844-489f-aca5-d0d9d69e9cc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2b083fb-ce1a-401c-8a4a-10dd279ad9c9', 'The Alps and Himalayas', false, 'a813b02a-2844-489f-aca5-d0d9d69e9cc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36ca2dfc-0e05-414b-9303-9b548e76d9d6', 'The Urals and Aravalli', false, 'a813b02a-2844-489f-aca5-d0d9d69e9cc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f92c9f5d-ffae-4a86-b93e-f610ece52553', 'The Andes and Rockies', false, 'a813b02a-2844-489f-aca5-d0d9d69e9cc1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5748644b-5887-44bd-8e03-ce1c8124e170', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Why is the ancient Aravalli Range in India low, rounded, and devoid of sharp conical peaks compared to the towering Himalayas?', 'Proterozoic orogenies created the Aravallis, which over hundreds of millions of years eroded into relict peneplains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05d69bce-133a-457a-a2e8-5577f59ea386', 'It is one of the oldest fold mountain systems in the world that has suffered millions of years of continuous weathering and erosion (Old Fold Mountains)', true, '5748644b-5887-44bd-8e03-ce1c8124e170');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35a0cd1e-6599-4583-93f0-b03cb473ae23', 'It was built by volcanic lava', false, '5748644b-5887-44bd-8e03-ce1c8124e170');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df60b9c0-441a-4348-ba9b-8c854a062b99', 'It was built by human hands', false, '5748644b-5887-44bd-8e03-ce1c8124e170');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c60ae5d2-b41a-425f-a5a4-cf4e80eb215a', 'It sank into the ocean', false, '5748644b-5887-44bd-8e03-ce1c8124e170');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c6bea0d-cb7a-4ec5-937e-2e13d38eda77', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Why are Plateaus world-renowned as the richest storehouses of valuable mineral deposits?', 'Cratonic basalt and crystalline shields in plateaus host vast metallic ores (e.g. Chota Nagpur plateau iron/coal, African gold/diamonds).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f0ddf8d-00ab-4307-81fe-db44cce4e9bd', 'Ancient volcanic and metamorphic activity concentrated rich ores (e.g. Iron, Coal, Manganese, Gold, Diamonds) in plateau rocks', true, '1c6bea0d-cb7a-4ec5-937e-2e13d38eda77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e44c3819-ad29-4684-9d9d-7b225bc525ce', 'Because rivers wash gold onto plateaus', false, '1c6bea0d-cb7a-4ec5-937e-2e13d38eda77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72a71b14-7bf8-433b-b548-e49310729801', 'Because plateaus are made of plastic', false, '1c6bea0d-cb7a-4ec5-937e-2e13d38eda77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cef87e73-29d6-471a-92c1-c7a7a619b759', 'Because plants turn into diamonds on plateaus', false, '1c6bea0d-cb7a-4ec5-937e-2e13d38eda77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6f43118-7e36-4860-ab61-56c360b5e7e4', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Which mineral-rich plateau in eastern India is famous as the ''Ruhr of India'' for its massive reserves of iron ore, coal, bauxite, and manganese?', 'The Gondwana formations and Dharwar shield of the Chota Nagpur Plateau supply India''s primary industrial heavy metals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfee0a46-0be0-44f5-b48b-41ab37b89f36', 'Chota Nagpur Plateau (Jharkhand/Odisha/Chhattisgarh)', true, 'f6f43118-7e36-4860-ab61-56c360b5e7e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b8bfbb1-d5ab-492f-9f7a-b0d05d5e34c8', 'Malwa Plateau', false, 'f6f43118-7e36-4860-ab61-56c360b5e7e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('739dfe0f-f1e7-4ee9-85a9-afb4a8a6616c', 'Shillong Plateau', false, 'f6f43118-7e36-4860-ab61-56c360b5e7e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ecff03a-c1e1-421b-b454-211cd1ce82fc', 'Ladakh Plateau', false, 'f6f43118-7e36-4860-ab61-56c360b5e7e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b72325f-205d-4578-8953-74b45951ba35', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'What is the famous scenic waterfall located on the Subarnarekha River in the Chota Nagpur Plateau of Jharkhand?', 'Hundru Falls plunges 98 meters over a steep escarpment of the Subarnarekha River near Ranchi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c72bcf21-22dc-442f-835a-b455117466d7', 'Hundru Falls', true, '3b72325f-205d-4578-8953-74b45951ba35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46997d90-1c98-4427-89a4-91260b601cb9', 'Jog Falls', false, '3b72325f-205d-4578-8953-74b45951ba35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bf3e908-eff8-413d-b15d-6bd597d9c1ad', 'Dhuandhar Falls', false, '3b72325f-205d-4578-8953-74b45951ba35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d8fe887-60a9-4b17-8e93-03aac14df026', 'Nohkalikai Falls', false, '3b72325f-205d-4578-8953-74b45951ba35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dbc7b896-6e17-49ab-b736-2f3a52943749', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'What famous waterfall on the Sharavathi River in the Western Ghats plateau of Karnataka plunges 253 meters in four cascades?', 'Jog Falls cascades down the rugged western plateau escarpment in four torrents: Raja, Roarer, Rocket, and Rani.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f90be17-102e-463a-a32f-4d8d07ebe2da', 'Jog Falls (Gersoppa Falls)', true, 'dbc7b896-6e17-49ab-b736-2f3a52943749');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b465ba09-3ed5-448a-ae4a-7422db57fb68', 'Hundru Falls', false, 'dbc7b896-6e17-49ab-b736-2f3a52943749');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82586f6e-43e1-4eb8-8864-94d7cee7cf6f', 'Shivanasamudra Falls', false, 'dbc7b896-6e17-49ab-b736-2f3a52943749');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2537d17-f613-404e-9c46-73f3960f8307', 'Dudhsagar Falls', false, 'dbc7b896-6e17-49ab-b736-2f3a52943749');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b577cba7-bac5-41a2-82e3-3cdeaedd5df2', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Why are the volcanic Black Soil (Regur soil) areas of the Deccan Plateau highly prized for agriculture, especially for growing Cotton?', 'Montmorillonite-rich basaltic regur soils possess exceptional cation exchange capacity and hygroscopic moisture retention ideal for cotton.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e56134a-431d-4576-aaac-099841e0b1a1', 'Formed from weathered volcanic basalt lava, black soil is exceptionally rich in clay minerals, highly fertile, and retains moisture for long durations', true, 'b577cba7-bac5-41a2-82e3-3cdeaedd5df2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b14d514-2efc-4c24-823d-ed71fb72ce9d', 'Because black soil has no water', false, 'b577cba7-bac5-41a2-82e3-3cdeaedd5df2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('797ad3d5-30d4-4bbc-91d2-bbab950bdd9f', 'Because black soil turns white in winter', false, 'b577cba7-bac5-41a2-82e3-3cdeaedd5df2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a24c1311-8d9b-4909-b55a-7d91c1287922', 'Because it contains natural dye', false, 'b577cba7-bac5-41a2-82e3-3cdeaedd5df2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73d10985-a73c-41e9-993a-942e7cea61e2', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'How did the great Northern Plains of India (Indo-Gangetic-Brahmaputra Plains) form over geological epochs?', 'Continuous aggradation of fertile alluvium in the Himalayan foredeep depression by the Indus, Ganga, and Brahmaputra formed these vast plains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec0dbc28-0c11-42a8-8e5c-70292ee26edd', 'Perennial Himalayan and peninsular rivers deposited millions of tonnes of fine silt, clay, and sand (Alluvium) in a vast subsiding foreland basin over millions of years', true, '73d10985-a73c-41e9-993a-942e7cea61e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d8e9e86-f506-469d-99c6-28fcfa3dcdbe', 'By volcanic lava filling the sea', false, '73d10985-a73c-41e9-993a-942e7cea61e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78c84f11-023b-4524-91b6-98bc6ee221ed', 'By wind blowing sand from the Thar desert', false, '73d10985-a73c-41e9-993a-942e7cea61e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdecb95b-a6d9-4aeb-81c4-9c85cc3b4d51', 'By glaciers melting in one day', false, '73d10985-a73c-41e9-993a-942e7cea61e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f039b387-af94-4970-88da-21e9c6fe6830', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Which vast plain in China is formed by the extensive alluvial silt deposition of the Yangtze and Yellow (Huang He) rivers?', 'The densely populated North China Plain was built by loess silt transport and flood deposits of the Huang He and Yangtze.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88fde386-b728-4430-94fc-b6a0eb6b7316', 'Yangtze / North China Plain', true, 'f039b387-af94-4970-88da-21e9c6fe6830');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ae04285-e619-4f28-99d3-95443bfa40d0', 'Siberian Plain', false, 'f039b387-af94-4970-88da-21e9c6fe6830');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e166915-a15e-4963-91e2-a04b6f79a6ef', 'Manchurian Plain', false, 'f039b387-af94-4970-88da-21e9c6fe6830');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4953ca99-c580-4785-b4d7-fdc2b4790f96', 'Gobi Plain', false, 'f039b387-af94-4970-88da-21e9c6fe6830');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43d1a953-de06-47a6-acbf-48b2455a96af', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'What are the two major continuous processes constantly shaping and modifying the Earth''s surface landforms?', 'Internal tectonic forces (volcanism, orogeny) uplift relief, while external agents (water, wind, ice) erode and level the terrain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44a4de9f-33e6-487b-acde-21fddcc4a550', 'Internal (Endogenic) processes causing crustal uplift/sinking AND External (Exogenic) processes of erosion and deposition', true, '43d1a953-de06-47a6-acbf-48b2455a96af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('709a2599-8bfe-4b5b-bb0a-5b6d3add842d', 'Solar eclipses and lunar tides', false, '43d1a953-de06-47a6-acbf-48b2455a96af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55194a90-d672-4e16-aa59-797bc6cb241f', 'Ocean waves and lightning', false, '43d1a953-de06-47a6-acbf-48b2455a96af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f694db9-f972-4896-b0a4-2b56365f5188', 'Plant growth and animal walking', false, '43d1a953-de06-47a6-acbf-48b2455a96af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a89f5fc-62ce-47e5-8607-04151c95c099', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Why do Mountain regions generally have very sparse human populations compared to Plains?', 'Steep slope gradients, severe weather, mass-wasting hazards, and logistical construction barriers severely limit demographic carrying capacity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ecb489a-49ef-4c58-80d3-383f7595033d', 'Harsh freezing climate, steep rocky slopes unsuitable for farming, thin infertile soil, and extreme difficulty in building transport roads and railways', true, '8a89f5fc-62ce-47e5-8607-04151c95c099');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01339521-13b5-4ba2-9415-5e977a4e9748', 'Because mountains have no water', false, '8a89f5fc-62ce-47e5-8607-04151c95c099');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ead45f6b-f074-46c1-af3f-6fd04338458c', 'Because mountains move every week', false, '8a89f5fc-62ce-47e5-8607-04151c95c099');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaf2e0df-2637-4232-b9db-675df4b1ab80', 'Because wild animals do not allow humans', false, '8a89f5fc-62ce-47e5-8607-04151c95c099');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d9b9e2e-2f34-492c-9c1b-c24727cdd7ef', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'What agricultural technique is practiced by farmers on steep mountain hillsides to carve out flat step-like fields and prevent soil erosion?', 'Contour bench terracing creates flat horizontal steps, slowing runoff velocity and conserving irrigation water on steep slopes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02350776-ebf0-4ba6-af06-51ea0eb85ec5', 'Terrace Farming (Step Cultivation)', true, '7d9b9e2e-2f34-492c-9c1b-c24727cdd7ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d76a0b14-2bdf-47e2-9d38-d9267a963e09', 'Strip Mining', false, '7d9b9e2e-2f34-492c-9c1b-c24727cdd7ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0566a894-4497-4b7b-bd9f-35b329f86cd3', 'Slash and Burn', false, '7d9b9e2e-2f34-492c-9c1b-c24727cdd7ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6aaf37a-1891-4025-9bde-62cb6e469165', 'Hydroponics', false, '7d9b9e2e-2f34-492c-9c1b-c24727cdd7ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74dd939e-fe54-4e13-968f-0cd96da133ae', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Which of the following mountain sports and tourism activities are popular in high snow-covered mountains?', 'High alpine relief and snow-covered slopes provide ideal environments for winter sports, climbing expeditions, and adventure tourism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4a465b1-b332-460c-b502-dac5047234ed', 'Skiing, Paragliding, Mountaineering, and River Rafting', true, '74dd939e-fe54-4e13-968f-0cd96da133ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95766d24-b2ac-4e4b-aedd-b669b4746231', 'Deep sea diving', false, '74dd939e-fe54-4e13-968f-0cd96da133ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e3c0f84-5ab4-4dae-b67a-c18953592b17', 'Desert dune bashing', false, '74dd939e-fe54-4e13-968f-0cd96da133ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3501761a-2ea1-47ac-a75e-2dce1f14187f', 'Submarine racing', false, '74dd939e-fe54-4e13-968f-0cd96da133ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5b0f891-5e7e-42b0-8cb7-48111fc52c6d', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Why are mountains rightly called ''Storehouses of Water'' for continental river systems?', 'Glacial meltwaters and orographic rainfall in mountain catchments sustain perennial river systems (Ganga, Indus, Brahmaputra).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e76c0b6e-61bd-465d-9934-1b4da5389f53', 'Vast glaciers on high peaks store frozen freshwater that melts in summer, feeding perennial rivers that provide drinking and irrigation water to millions downstream', true, 'a5b0f891-5e7e-42b0-8cb7-48111fc52c6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('790b2449-3880-4b6e-85b4-e099e3d535eb', 'Mountains pump water from the center of Earth', false, 'a5b0f891-5e7e-42b0-8cb7-48111fc52c6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4254a497-b9df-45c9-8844-b9b134763d07', 'Mountains make water from rocks', false, 'a5b0f891-5e7e-42b0-8cb7-48111fc52c6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f352686-e614-41ed-a5fc-3d9d8a8903a9', 'Mountains stop all clouds permanently', false, 'a5b0f891-5e7e-42b0-8cb7-48111fc52c6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0618b187-2241-4003-b01d-7467f90ce513', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'What is the crucial difference between a Mountain and a Hill?', 'Standard geographic conventions classify land elevations with steep slopes rising above 600 meters as mountains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb32bba0-7fd8-49a3-8f2a-73815b0e182d', 'A hill is a land surface with a rounded summit rising moderately above surrounding areas, whereas a steep hill with an elevation of more than 600 meters is classified as a Mountain', true, '0618b187-2241-4003-b01d-7467f90ce513');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c90c2510-d5e4-4a97-8220-8c0280abb065', 'Hills are made of ice and mountains of rock', false, '0618b187-2241-4003-b01d-7467f90ce513');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27332264-b2a5-4cb5-8ab4-dfed9c62d6d1', 'Hills only exist in oceans', false, '0618b187-2241-4003-b01d-7467f90ce513');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e00dc7d-5714-4e69-b334-40b486bf8aa3', 'There is no difference', false, '0618b187-2241-4003-b01d-7467f90ce513');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('094faaec-27dc-4140-89a8-4cb48d9b7429', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Read the statements:
