INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5af5ae9-6f6b-47b9-975e-83f818ad12e0', 'Himalayas (Fold)', false, 'd1e74c5c-97f3-4cba-b23d-2c0dbeab69a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ba500ea-8256-4d4b-91de-bea3e46db629', 'Alps (Fold)', false, 'd1e74c5c-97f3-4cba-b23d-2c0dbeab69a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('435d6c59-9255-43bc-af4d-6f6d83a9cef0', 'Rockies (Fold)', false, 'd1e74c5c-97f3-4cba-b23d-2c0dbeab69a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beb5dc27-8ddf-4c8d-a043-641442077e2b', 'Mount Kilimanjaro (Fold)', true, 'd1e74c5c-97f3-4cba-b23d-2c0dbeab69a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76afc2e2-2bbf-4c7c-bd40-fdb2347a2ebd', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'A tectonic geomorphologist analyzes the Rhine Valley in Germany and the Vosges Mountain in France. What structural landform pair is represented?', 'Parallel extensional normal faulting dropped the central Rhine graben while leaving the adjacent Vosges and Black Forest horst blocks elevated.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bd5d1b5-fd42-46fd-aa33-a868dab06543', 'Rhine Valley = Graben (Rift Valley) ; Vosges = Horst (Block Mountain)', true, '76afc2e2-2bbf-4c7c-bd40-fdb2347a2ebd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34cf8011-83f4-48dc-ac01-5c48094b183f', 'Rhine Valley = Horst ; Vosges = Graben', false, '76afc2e2-2bbf-4c7c-bd40-fdb2347a2ebd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da6e1465-6b23-4b22-87e6-3b57302987e8', 'Both are Fold Mountains', false, '76afc2e2-2bbf-4c7c-bd40-fdb2347a2ebd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7679386-f259-4ee0-b16f-24cab05f6390', 'Both are Volcanic stratocones', false, '76afc2e2-2bbf-4c7c-bd40-fdb2347a2ebd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2226b330-97a9-4d7d-bcd9-6d9021ec77ff', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Match Column I (Mountain Systems) with Column II (Geological Types & Continents):
(a) Mount Fujiyama -> (i) Old Fold Mountain (India)
(b) Himalayas       -> (ii) Volcanic Mountain (Japan)
(c) Vosges          -> (iii) Young Fold Mountain (Asia)
(d) Aravalli        -> (iv) Block Mountain (Europe)', 'Fujiyama = Volcanic; Himalayas = Young Fold; Vosges = Block; Aravalli = Old Fold.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('331f3116-85bd-4fcc-9884-fe70e5197d0a', 'a-(ii), b-(iii), c-(iv), d-(i)', true, '2226b330-97a9-4d7d-bcd9-6d9021ec77ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5b417a0-5f63-4ee8-80cc-ca60b1433220', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '2226b330-97a9-4d7d-bcd9-6d9021ec77ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e1e6e3c-2a23-484b-8e6a-b90cf6a5c8b8', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '2226b330-97a9-4d7d-bcd9-6d9021ec77ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad0b1463-4afb-4e81-be87-fbafeed20bf5', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '2226b330-97a9-4d7d-bcd9-6d9021ec77ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f79ac49a-1409-483e-9471-dbe4652dd58d', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66bbaed5-3dfe-46b6-8313-83e3ec923b84', 'Statements 1 and 2 only', true, 'f79ac49a-1409-483e-9471-dbe4652dd58d');
