INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cf2d36c-1b00-4ce5-82dd-28712f4069d1', 'Statements 1 and 3 only', false, 'f79ac49a-1409-483e-9471-dbe4652dd58d');
