INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43e28595-ffdd-4f87-b2b6-b8e9f64a1167', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Why is building linear transport infrastructure (like multi-lane highways and broad-gauge railways) exponentially more expensive and technically difficult in mountainous terrain than in flat plains?', 'Steep gradients, slope instability, and seismic hazards necessitate complex civil engineering (tunnels, viaducts, avalanche sheds).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f872be0-327f-41db-be97-e68b23564a60', 'Rugged topography demands costly construction of deep tunnels, high viaduct bridges, slope stabilization against landslides, and steep gradient switchbacks', true, '43e28595-ffdd-4f87-b2b6-b8e9f64a1167');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cea45834-444a-40bf-bbf5-05cbd47bab2f', 'Because mountain stone cannot be cut', false, '43e28595-ffdd-4f87-b2b6-b8e9f64a1167');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dda7cae-68f5-43ab-8647-760468d3200b', 'Because trains cannot run at high altitudes', false, '43e28595-ffdd-4f87-b2b6-b8e9f64a1167');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04c3437e-8391-4439-8022-7885a02acd53', 'Because concrete melts in cold air', false, '43e28595-ffdd-4f87-b2b6-b8e9f64a1167');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0295dca3-c0b2-41f2-8798-1e29723e3cd7', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'What is the primary ecological hazard caused by reckless deforestation, quarrying, and unplanned concrete construction on mountain slopes?', 'Stripping stabilizing vegetative root matrices triggers mass-wasting debris flows, soil creep, and deadly landslides during monsoons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3de4a4a7-ac39-4504-8a8b-79e89c665ae5', 'Severe slope destabilization triggering catastrophic Landslides, flash floods, topsoil erosion, and loss of human settlements', true, '0295dca3-c0b2-41f2-8798-1e29723e3cd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc92206c-1804-420f-9f07-328dea36eeb7', 'The mountain turning into a volcano', false, '0295dca3-c0b2-41f2-8798-1e29723e3cd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0a53987-6a56-4949-849a-8d63af4b7f90', 'The mountain flying into space', false, '0295dca3-c0b2-41f2-8798-1e29723e3cd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a194174b-dbaf-4b3c-bca9-39264569bd04', 'Rivers turning into ice permanently', false, '0295dca3-c0b2-41f2-8798-1e29723e3cd7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2aecb54c-8381-41fc-a7ec-ca476a9802e8', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Consider four major plateaus of the world:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1272190c-f3ed-40fb-8bf8-d0f415179e70', 'Plateau 1 (Tibetan Plateau)', true, '2aecb54c-8381-41fc-a7ec-ca476a9802e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1526172a-bc12-4684-9bff-b268666c2ad2', 'Plateau 2', false, '2aecb54c-8381-41fc-a7ec-ca476a9802e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7a29caf-f038-4054-8076-c92bc4ace4b0', 'Plateau 3', false, '2aecb54c-8381-41fc-a7ec-ca476a9802e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da763b7b-df64-4941-a67f-530192f91e34', 'Plateau 4', false, '2aecb54c-8381-41fc-a7ec-ca476a9802e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('718ed94d-4bdf-4072-af13-d044f2f1719a', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'How do volcanic ash soils on the slopes of volcanic mountains (such as around Mount Vesuvius or Mount Etna) benefit agriculture?', 'Andisols formed from volcanic ejecta possess exceptional mineral nutrient fertility and water retention capacity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d494163b-7f82-4ae3-9701-150cff6caf3c', 'Weathered tephra and volcanic ash are extraordinarily rich in bioavailable potassium, phosphorus, iron, and trace minerals, creating fertile soils for vineyards and orchards', true, '718ed94d-4bdf-4072-af13-d044f2f1719a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1128d475-37cc-4803-acbd-0dbf79b6cd79', 'Volcanic ash freezes the crops', false, '718ed94d-4bdf-4072-af13-d044f2f1719a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('283c7019-2548-4032-b45c-bd56eaf7ed4c', 'Volcanic soil prevents weeds by burning them', false, '718ed94d-4bdf-4072-af13-d044f2f1719a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c1161ec-4bab-41c2-9dda-fb66dbde9bef', 'Volcanic soil produces diamonds', false, '718ed94d-4bdf-4072-af13-d044f2f1719a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b84e46c1-3132-4585-a461-48b02f9dbd88', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'What is the geographic name for a steep cliff or long rock wall marking the edge of a plateau or separating two relatively level areas of different elevations?', 'An escarpment is a steep, precipitous cliff or slope resulting from faulting or erosion separating high plateau tablelands from lowlands.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('128ce304-cb88-4343-9fff-ccadb335ee4d', 'Escarpment (or Scarp)', true, 'b84e46c1-3132-4585-a461-48b02f9dbd88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94189563-bf03-421f-939e-5cdd62052130', 'Pass', false, 'b84e46c1-3132-4585-a461-48b02f9dbd88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('923c1dcb-2f31-49af-b852-b87d71c4a965', 'Delta', false, 'b84e46c1-3132-4585-a461-48b02f9dbd88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('516078ab-b10e-47ed-a1d3-4a6e5563c310', 'Gorge', false, 'b84e46c1-3132-4585-a461-48b02f9dbd88');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa431208-802d-4f88-b73c-6c2abe8b2cc4', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Which of the following accurately contrasts the economic significance of Mountains versus Plateaus versus Plains?', 'Each geomorphic macro-domain provides distinct economic utility: mountains supply hydrologic heads/forests, plateaus yield mineral wealth, and plains provide arable farmland.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('782cc00f-16d0-4a93-9a25-26aee03fc808', 'Mountains = Water storehouses, timber forests & tourism ; Plateaus = Rich mineral ore reserves & hydroelectric waterfalls ; Plains = Intensive agriculture & human settlements', true, 'fa431208-802d-4f88-b73c-6c2abe8b2cc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e20c28b-e99c-44c2-8270-fedd91cbb2f0', 'Mountains = Only for farming ; Plateaus = No minerals ; Plains = High altitude sports', false, 'fa431208-802d-4f88-b73c-6c2abe8b2cc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a89c05c8-4167-45ea-938b-6179d2da235d', 'All three have identical economic roles', false, 'fa431208-802d-4f88-b73c-6c2abe8b2cc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('661ad655-4611-4836-9ef7-a71cd95c79cf', 'Plains have only mineral ores', false, 'fa431208-802d-4f88-b73c-6c2abe8b2cc4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f7b9daa-ffaf-45bd-bc42-331a57c04591', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'What international civic responsibility is emphasized in NCERT Social Science regarding the stewardship of land and water resources?', 'Sustainable land management requires treating soil, mountains, and water as shared intergenerational ecological heritage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e381b15f-0856-43ea-b942-47f18e951aeb', 'Conserving land and water for future generations, avoiding wasteful pollution of fertile land with plastic/garbage, and living sustainably in harmony with nature', true, '5f7b9daa-ffaf-45bd-bc42-331a57c04591');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('530c63c7-7d58-41c2-8b0a-0335c1b4bfc1', 'Covering all mountains with concrete', false, '5f7b9daa-ffaf-45bd-bc42-331a57c04591');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0049b046-fe0f-4ec8-9b3e-a887f17027de', 'Draining all river water into the desert', false, '5f7b9daa-ffaf-45bd-bc42-331a57c04591');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdc4ee28-fd00-4161-b4cf-874c33aaef30', 'Building factories inside all forests', false, '5f7b9daa-ffaf-45bd-bc42-331a57c04591');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('629c52fa-91d6-4584-a4d6-d519d3499a60', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'संज्ञा, सर्वनाम, विशेषण या क्रिया के जिस रूप से उसकी संख्या (एक या एक से अधिक) का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'शब्द के जिस रूप से वस्तु या प्राणी की संख्यात्मक स्थिति (एक या अनेक) का ज्ञान हो, उसे ''वचन'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('612457ec-6601-41e2-95ac-708df5969d6b', 'वचन (Number)', true, '629c52fa-91d6-4584-a4d6-d519d3499a60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('457a001f-4dfa-4c96-be1d-cfdb7cfcea59', 'लिंग', false, '629c52fa-91d6-4584-a4d6-d519d3499a60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8174c388-6193-49e3-8f8f-07587c06b213', 'कारक', false, '629c52fa-91d6-4584-a4d6-d519d3499a60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b75ad82-b707-47f3-bef9-6dfc98c3aa18', 'काल', false, '629c52fa-91d6-4584-a4d6-d519d3499a60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4975658f-c756-45ec-844a-d066d0abff62', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'हिंदी भाषा में वचन के कितने भेद (प्रकार) होते हैं?', 'हिंदी में केवल दो वचन होते हैं: 1. एकवचन (Singular) तथा 2. बहुवचन (Plural)। (संस्कृत का द्विवचन हिंदी में नहीं होता)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bef32f18-6e77-4e01-b556-204d81460466', 'दो भेद (एकवचन और बहुवचन)', true, '4975658f-c756-45ec-844a-d066d0abff62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2c7f7d0-8ddb-4f7e-9533-bd033d0b8336', 'तीन भेद', false, '4975658f-c756-45ec-844a-d066d0abff62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee3b5b81-449e-4038-bc3a-5c95bad1bbde', 'चार भेद', false, '4975658f-c756-45ec-844a-d066d0abff62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6772c2b5-0cbf-4f1c-b34e-c647aa9da738', 'पाँच भेद', false, '4975658f-c756-45ec-844a-d066d0abff62');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87ab60bd-c347-4d14-a775-f3345a1993d7', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'शब्द के जिस रूप से केवल एक ही वस्तु, प्राणी या स्थान का बोध होता है, उसे क्या कहते हैं?', 'एकमात्र इकाई की संख्या का बोध कराने वाला रूप ''एकवचन'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28715216-6ac3-4d9d-85b4-f805da96f43e', 'एकवचन (जैसे: लड़का, पुस्तक, नदी, माला, गाय, पंखा)', true, '87ab60bd-c347-4d14-a775-f3345a1993d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e52e935-f54f-42f8-bf49-ac11bd1a13c8', 'बहुवचन', false, '87ab60bd-c347-4d14-a775-f3345a1993d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8961b445-b688-4939-960a-c7e9244b1a53', 'द्विवचन', false, '87ab60bd-c347-4d14-a775-f3345a1993d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c923ca65-c01c-45fd-adc4-9f638f3d088c', 'अव्यय', false, '87ab60bd-c347-4d14-a775-f3345a1993d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e02e1bc-55a4-4886-afb7-14ec983aa998', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'शब्द के जिस रूप से एक से अधिक (अनेक) वस्तुओं, प्राणियों या स्थानों का बोध होता है, उसे क्या कहते हैं?', 'एकाधिक (दो या अधिक) संख्याओं का बोध कराने वाला रूप ''बहुवचन'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5a6622f-6559-4f96-afc7-f0db65e7c035', 'बहुवचन (जैसे: लड़के, पुस्तकें, नदियाँ, मालाएँ, गायें, पंखे)', true, '6e02e1bc-55a4-4886-afb7-14ec983aa998');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2395b8d1-977f-413d-bd25-f0360814d29d', 'एकवचन', false, '6e02e1bc-55a4-4886-afb7-14ec983aa998');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68b47bd2-2265-401a-b34d-6fd0d376c31b', 'द्विवचन', false, '6e02e1bc-55a4-4886-afb7-14ec983aa998');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2441f38d-438c-469b-af31-194442d960da', 'लिंग', false, '6e02e1bc-55a4-4886-afb7-14ec983aa998');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('376653fc-7ece-4dcc-9fcf-b53f8385de95', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'एकवचन शब्द ''लड़का'' का सही बहुवचन रूप क्या है?', 'आ-कारान्त पुल्लिंग संज्ञा में ''आ'' का ''ए'' करने पर बहुवचन बनता है: लड़का -> लड़के।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81d0ea3c-8b7f-435d-a205-a81b6f64c971', 'लड़के', true, '376653fc-7ece-4dcc-9fcf-b53f8385de95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd0ad8b0-aa16-42d6-8993-fbbda8eb97a0', 'लड़कों', false, '376653fc-7ece-4dcc-9fcf-b53f8385de95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2ebf251-c70e-4075-8a50-f51ecd4d10a6', 'लड़कियाँ', false, '376653fc-7ece-4dcc-9fcf-b53f8385de95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae616a21-ff48-4a88-8945-8d3c68f6d9f1', 'लड़कियों', false, '376653fc-7ece-4dcc-9fcf-b53f8385de95');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b12494e-0b9d-4b52-a712-346b46a0ddd5', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'एकवचन शब्द ''पुस्तक'' और ''किताब'' के सही बहुवचन रूप क्रमशः क्या हैं?', 'अ-कारान्त स्त्रीलिंग संज्ञाओं में ''एं'' (अनुस्वार सहित) लगता है: पुस्तक -> पुस्तकें; किताब -> किताबें।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('130a0d54-130c-43b2-8191-9234e977202e', 'पुस्तकें और किताबें', true, '6b12494e-0b9d-4b52-a712-346b46a0ddd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0af0bcc-0352-4cb9-ad27-bfe64b6cf432', 'पुस्तकों और किताबों', false, '6b12494e-0b9d-4b52-a712-346b46a0ddd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf31cfea-1461-4dbc-8d96-f730ae27585f', 'पुस्तकाएं और किताबाएं', false, '6b12494e-0b9d-4b52-a712-346b46a0ddd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42713ed1-e521-43d5-84c9-285a47ffbcd4', 'पुस्तकी और किताबी', false, '6b12494e-0b9d-4b52-a712-346b46a0ddd5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d076455c-f04f-4964-baf2-2cad3038da7d', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'एकवचन शब्द ''माला'' और ''महिला'' के सही बहुवचन रूप क्रमशः क्या हैं?', 'आ-कारान्त स्त्रीलिंग शब्दों में ''एँ'' जोड़कर बहुवचन बनता है: माला -> मालाएँ; महिला -> महिलाएँ; लता -> लताएँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae4b2deb-cfb2-461d-8ab0-120a97d659f6', 'मालाएँ और महिलाएँ', true, 'd076455c-f04f-4964-baf2-2cad3038da7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a52326d-4a3e-4f26-a7d9-96e4e6199136', 'मालाएं और महिलाएं', false, 'd076455c-f04f-4964-baf2-2cad3038da7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a160c1-f441-4516-94c2-930362c91514', 'माले और महिले', false, 'd076455c-f04f-4964-baf2-2cad3038da7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc932f5d-b507-4a01-9051-df2199fe9113', 'मालों और महिलाओं', false, 'd076455c-f04f-4964-baf2-2cad3038da7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('829c30ba-4f98-4a91-8236-e347bb183474', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'एकवचन शब्द ''नदी'' और ''लड़की'' का बहुवचन बनाते समय अंतिम दीर्घ ''ई'' को क्या हो जाता है?', 'ई-कारान्त स्त्रीलिंग शब्दों के बहुवचन में दीर्घ ई ह्रस्व ''इ'' में बदलती है और ''याँ'' जुड़ता है: नदी -> नदियाँ; लड़की -> लड़कियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89d9ca4d-e6e6-4f9f-bf85-0206d934c3cb', 'दीर्घ ''ई'' बदलकर ह्रस्व ''इ'' हो जाती है और अंत में ''याँ'' जुड़ जाता है (नदियाँ, लड़कियाँ)', true, '829c30ba-4f98-4a91-8236-e347bb183474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83d8db8e-0d75-4147-8d02-5b777b444314', 'दीर्घ ''ई'' वैसी ही रहती है', false, '829c30ba-4f98-4a91-8236-e347bb183474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9adfb20e-b87e-4e76-9075-248aada71572', 'ई का ए बन जाता है', false, '829c30ba-4f98-4a91-8236-e347bb183474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14128b81-e049-4757-96bc-0db820b11f87', 'कोई परिवर्तन नहीं होता', false, '829c30ba-4f98-4a91-8236-e347bb183474');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1758921c-3d67-4b21-8ea7-fb0ed301a205', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'एकवचन शब्द ''चिड़िया'' और ''डिबिया'' के सही बहुवचन रूप क्या हैं?', 'या-अन्त स्त्रीलिंग शब्दों के अंत में केवल चंद्रबिंदु (ँ) लगाने से बहुवचन बनता है: चिड़िया -> चिड़ियाँ; डिबिया -> डिबियाँ; गुड़िया -> गुड़ियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d9e3e93-ef72-4e04-b46a-09ea7270f746', 'चिड़ियाँ और डिबियाँ (या के ऊपर चंद्रबिंदु लगाकर)', true, '1758921c-3d67-4b21-8ea7-fb0ed301a205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c0ca2ec-85d9-4aa5-9383-e4c9d0d9290b', 'चिड़िए और डिबिए', false, '1758921c-3d67-4b21-8ea7-fb0ed301a205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4351191-7458-4d5c-9a99-f38753b14712', 'चिड़ियों और डिबियों', false, '1758921c-3d67-4b21-8ea7-fb0ed301a205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecc1bda1-52ea-4dfe-a0e3-a80b2e14425b', 'चिड़ी और डिबी', false, '1758921c-3d67-4b21-8ea7-fb0ed301a205');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94fa471a-120d-4283-a6ab-5770a0b1877e', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'हिंदी में किसी व्यक्ति को आदर, सम्मान या प्रतिष्ठा देने के लिए एकवचन होने पर भी किस वचन की क्रिया का प्रयोग किया जाता है?', 'सम्माननीय या पूज्य व्यक्तियों के लिए एकवचन कर्ता के साथ भी आदरार्थक बहुवचन क्रिया प्रयुक्त होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('388fbba3-3979-487f-955e-6940cd64d15f', 'बहुवचन की क्रिया का (आदरार्थक बहुवचन - जैसे: ''गांधी जी महान नेता थे'', ''पिता जी आ रहे हैं'')', true, '94fa471a-120d-4283-a6ab-5770a0b1877e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f02bcdaf-cba1-475a-ae6c-8a759b4c25e1', 'एकवचन की क्रिया का', false, '94fa471a-120d-4283-a6ab-5770a0b1877e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bbedc7d-852b-4d8d-a8a4-105ad4d879bd', 'द्विवचन का', false, '94fa471a-120d-4283-a6ab-5770a0b1877e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('376a47c1-05ce-44f0-a2b3-356ed08adc6a', 'क्रिया नहीं लगती', false, '94fa471a-120d-4283-a6ab-5770a0b1877e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4300144-538d-4b9e-95a4-5f481be173a8', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'निम्नलिखित में से ''सदा बहुवचन'' (नित्य बहुवचन) में प्रयुक्त होने वाले शब्दों का सही समूह कौन-सा है?', 'प्राण, दर्शन, हस्ताक्षर, आँसू, बाल, होश आदि संज्ञा शब्द हिंदी में सर्वदा बहुवचन में ही प्रयुक्त होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6bf2cde-41c2-4ef0-83b5-29fdd9b87f26', 'प्राण, दर्शन, हस्ताक्षर, आँसू, होश, बाल', true, 'f4300144-538d-4b9e-95a4-5f481be173a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa1b4d25-c599-4d51-9932-36874b36a618', 'पानी, दूध, तेल, घी', false, 'f4300144-538d-4b9e-95a4-5f481be173a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6411102-5957-42a6-9793-b40b9252f1b2', 'जनता, वर्षा, हवा, आकाश', false, 'f4300144-538d-4b9e-95a4-5f481be173a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07340fe0-373f-4b34-955a-7147f03f70cb', 'सोना, चाँदी, ताँबा', false, 'f4300144-538d-4b9e-95a4-5f481be173a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e37a031-240b-4a0c-9464-049b1a898917', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'निम्नलिखित में से ''सदा एकवचन'' (नित्य एकवचन) में प्रयुक्त होने वाले शब्दों का सही समूह कौन-सा है?', 'द्रव्यवाचक संज्ञाएँ (पानी, दूध, सोना), समूहवाचक (जनता), तथा प्राकृतिक (वर्षा) शब्द नित्य एकवचन में रहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6044ae1-b04c-415e-8d5f-7292bbded778', 'जनता, वर्षा, पानी, दूध, सोना, घी, सत्य', true, '3e37a031-240b-4a0c-9464-049b1a898917');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a429475-9237-4ef3-a3f5-ccccdd2992ff', 'प्राण, दर्शन, आँसू', false, '3e37a031-240b-4a0c-9464-049b1a898917');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c679940-9a4b-411d-8cc3-43e70b729d7a', 'लोग, बाल, हस्ताक्षर', false, '3e37a031-240b-4a0c-9464-049b1a898917');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8e86961-cabd-4c8f-ab00-bd520b381efc', 'लड़के, नदियाँ, मालाएँ', false, '3e37a031-240b-4a0c-9464-049b1a898917');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('283c79d6-4651-46bd-a9fd-ebc60b962758', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'वाक्य में प्रयुक्त रेखांकित शब्द का वचन पहचानिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('501090f2-5f37-4baa-b075-8038bb51222b', 'सदा बहुवचन (नित्य बहुवचन)', true, '283c79d6-4651-46bd-a9fd-ebc60b962758');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6336f8d-b949-44e8-9d60-9bff646c3180', 'एकवचन', false, '283c79d6-4651-46bd-a9fd-ebc60b962758');
