INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e60d4c2-e9f3-4aa4-ad72-1c643c569c80', 'अव्यय', false, '283c79d6-4651-46bd-a9fd-ebc60b962758');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f566511-ec39-4aee-b937-694057302f69', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'वाक्य में प्रयुक्त रेखांकित शब्द का वचन बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d099af65-1722-4cdf-8e51-3fb1ebab07ea', 'सदा एकवचन (नित्य एकवचन)', true, '1f566511-ec39-4aee-b937-694057302f69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa5d8ff-c8b1-445f-b467-77aaae781bb2', 'बहुवचन', false, '1f566511-ec39-4aee-b937-694057302f69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc1c1d3f-44dc-4521-a19d-099120a0765e', 'उभयवचन', false, '1f566511-ec39-4aee-b937-694057302f69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1948bd01-33b7-498e-9b80-446aa3493a1f', 'आदरार्थक बहुवचन', false, '1f566511-ec39-4aee-b937-694057302f69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30b46314-531e-4dad-a589-40627e9072a1', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''वधू'' और ''वस्तु'' के सही बहुवचन रूप क्रमशः क्या हैं?', 'उ/ऊ-कारान्त स्त्रीलिंग शब्दों में ''एँ'' जोड़ते हैं तथा दीर्घ ऊ ह्रस्व ''उ'' में बदलता है: वधू -> वधुएँ; वस्तु -> वस्तुएँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ec9d73b-9c06-4990-9b46-63fcba7faefe', 'वधुएँ और वस्तुएँ', true, '30b46314-531e-4dad-a589-40627e9072a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77bbaea1-a36d-45a1-b255-5c08c7e98749', 'वधुओं और वस्तुओं', false, '30b46314-531e-4dad-a589-40627e9072a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab9e3379-aab5-4f7f-8ed2-048a06059454', 'वधुएं और वस्तुएं', false, '30b46314-531e-4dad-a589-40627e9072a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0c22fc0-5747-45c3-bc49-29dededb9752', 'वधुए और वस्तुए', false, '30b46314-531e-4dad-a589-40627e9072a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e860c81-27f3-42cf-947d-06fb37242233', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''कक्षा'', ''माता'' और ''शाखा'' के सही बहुवचन रूप क्या हैं?', 'मानक हिंदी वर्तनी में आ-कारान्त स्त्रीलिंग शब्दों के बहुवचन में ''एँ'' (चंद्रबिंदु युक्त) जोड़ा जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c2eece0-3b79-40a9-8da3-a052adcdb107', 'कक्षाएँ, माताएँ, शाखाएँ', true, '9e860c81-27f3-42cf-947d-06fb37242233');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('839890cc-2292-48a1-bce7-e2e9cf4f22c6', 'कक्षाएं, माताएं, शाखाएं', false, '9e860c81-27f3-42cf-947d-06fb37242233');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37b631aa-ca77-423c-8550-22ed77f44be8', 'कक्षायें, मातायें, शाखायें', false, '9e860c81-27f3-42cf-947d-06fb37242233');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc819768-42cf-4f43-a4b9-e8cf4a12a9b2', 'कक्षों, माताओं, शाखाओं', false, '9e860c81-27f3-42cf-947d-06fb37242233');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9bf26a3a-ad52-4fd4-92b5-0a70845150a4', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'कुछ एकवचन शब्दों के अंत में ''गण'', ''वृंद'', ''जन'', ''वर्ग'' या ''दल'' जोड़कर बहुवचन बनाया जाता है; इसका सही सुमेल कौन-सा है?', 'समूहवाची प्रत्ययों द्वारा आदरयुक्त या समुदायवाची बहुवचन रूप बनते हैं: शिक्षकगण, पक्षीवृंद, गुरुजन, छात्रवर्ग, टिड्डीदल।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3ab6c6a-28f7-491b-8c6c-7fbfd1837f8b', 'शिक्षक -> शिक्षकगण ; पक्षी -> पक्षीवृंद ; गुरु -> गुरुजन ; छात्र -> छात्रवर्ग ; टिड्डी -> टिड्डीदल', true, '9bf26a3a-ad52-4fd4-92b5-0a70845150a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('317a67cd-824c-441c-b300-075acfde97e1', 'शिक्षक -> शिक्षकें ; पक्षी -> पक्षियाँ', false, '9bf26a3a-ad52-4fd4-92b5-0a70845150a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23572544-38c0-48f8-beef-75cd774cc2eb', 'गुरु -> गुरुएँ ; छात्र -> छात्राएँ', false, '9bf26a3a-ad52-4fd4-92b5-0a70845150a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e46967a7-73c3-466c-95f9-ddc9af5b67a3', 'टिड्डी -> टिड्डे', false, '9bf26a3a-ad52-4fd4-92b5-0a70845150a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b94c5e8-c590-4713-a1c4-d70780599940', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'जब किसी संज्ञा के साथ परसर्ग (कारक चिह्न जैसे ने, को, से, में, पर) लगा होता है, तो उसका बहुवचन बनाने के लिए कौन-सा प्रत्यय लगता है?', 'सपरसर्ग (तिर्यक/Oblique) स्थिति में सभी संज्ञाओं का बहुवचन ''ओं'' प्रत्यय लगाकर बनाया जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('727e5594-b1e2-4b1c-9213-22b740154399', '''ओं'' प्रत्यय (तिर्यक बहुवचन - जैसे: लड़कों ने, नदियों में, घरों पर)', true, '0b94c5e8-c590-4713-a1c4-d70780599940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b35b3533-4cd7-4d5b-89f7-991c50fad360', '''एँ'' प्रत्यय', false, '0b94c5e8-c590-4713-a1c4-d70780599940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6791b21d-2e54-46f1-a772-f46864e82ffa', '''याँ'' प्रत्यय', false, '0b94c5e8-c590-4713-a1c4-d70780599940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73af554c-99c8-43db-87ad-c7e165222337', 'कोई प्रत्यय नहीं लगता', false, '0b94c5e8-c590-4713-a1c4-d70780599940');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adce33af-7593-423e-9e50-e3046dd991ca', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''दवाई'' और ''मिठाई'' के सही बहुवचन रूप क्या हैं?', 'ई-कारान्त में दीर्घ ''ई'' ह्रस्व ''इ'' बनकर ''याँ'' जुड़ती है: दवाई -> दवाइयाँ; मिठाई -> मिठाइयाँ; खिड़की -> खिड़कियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaa32327-3bd1-4f85-b4f3-b7a4a22e9168', 'दवाइयाँ और मिठाइयाँ', true, 'adce33af-7593-423e-9e50-e3046dd991ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('988e58aa-154e-43a7-bce5-41a29444cc3f', 'दवाइयों और मिठाइयों', false, 'adce33af-7593-423e-9e50-e3046dd991ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('873171f4-3424-45be-8be9-76b6257ba004', 'दवाईयाँ और मिठाईयाँ', false, 'adce33af-7593-423e-9e50-e3046dd991ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34a99c06-dff3-4431-9dc8-0c61a534c3a1', 'दवाएं और मीठा', false, 'adce33af-7593-423e-9e50-e3046dd991ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb160c15-e95c-4faa-85a9-c17aea890a38', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''ऋतु'' और ''गौ'' के सही बहुवचन रूप क्या हैं?', 'उ/औ-कारान्त शब्दों में ''एँ'' प्रत्यय: ऋतु -> ऋतुएँ; गौ -> गौएँ; धेनु -> धेनुएँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f4ca55d-c7df-4a06-9c44-388f3d4b3fc5', 'ऋतुएँ और गौएँ', true, 'bb160c15-e95c-4faa-85a9-c17aea890a38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7afc20d2-26fa-4ffb-b4b6-7feb58589d10', 'ऋतुएं और गौएं', false, 'bb160c15-e95c-4faa-85a9-c17aea890a38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04bbe237-6e28-472d-aa88-5d9e48ac2c13', 'ऋतुओं और गौओं', false, 'bb160c15-e95c-4faa-85a9-c17aea890a38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3926de15-f7c6-4d7f-946c-cf1ecf42cea2', 'ऋतुए और गौए', false, 'bb160c15-e95c-4faa-85a9-c17aea890a38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a16e0a2-0462-4854-9a18-db5586b71659', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'अ-कारान्त पुल्लिंग शब्द (जैसे: घर, पेड़, हाथी, बालक, साधु) बिना किसी कारक चिह्न के बहुवचन में किस रूप में रहते हैं?', 'निःपरसर्ग (प्रत्ययरहित) स्थिति में अ/उ/ऊ-कारान्त पुल्लिंग शब्द एकवचन और बहुवचन दोनों में समान रूप में रहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84c285d5-d96c-49cf-b712-975888f57a79', 'वे दोनों वचनों (एकवचन और बहुवचन) में समान (अपरिवर्तित) रहते हैं (जैसे: ''एक पेड़ / दस पेड़'', ''एक घर / कई घर'')', true, '8a16e0a2-0462-4854-9a18-db5586b71659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7edddb47-cead-4128-a614-14d4527efb12', 'उनमें ''एँ'' लग जाता है', false, '8a16e0a2-0462-4854-9a18-db5586b71659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faf9d057-d3bc-46e3-89ce-a212cec0e995', 'वे स्त्रीलिंग बन जाते हैं', false, '8a16e0a2-0462-4854-9a18-db5586b71659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fc73938-396e-4723-960b-b26818849656', 'उनका बहुवचन नहीं होता', false, '8a16e0a2-0462-4854-9a18-db5586b71659');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9186c3f6-daf0-4892-b733-e120d9f619f2', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'वाक्य में वचन की पहचान संज्ञा के अतिरिक्त और किस व्याकरणिक पद से आसानी से की जा सकती है?', 'जैसे ''बालक पढ़ता है'' (एकवचन क्रिया) बनाम ''बालक पढ़ते हैं'' (बहुवचन क्रिया); ''अच्छा फल'' बनाम ''अच्छे फल''।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab1dc537-d8d1-4285-9f13-16cb1882c01d', 'क्रिया और विशेषण के रूप से', true, '9186c3f6-daf0-4892-b733-e120d9f619f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72a0c924-7cec-4799-98b0-e113fa44b55a', 'केवल उपसर्ग से', false, '9186c3f6-daf0-4892-b733-e120d9f619f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('220ac8e4-71d4-41c7-8984-d46b015efdae', 'केवल प्रत्यय से', false, '9186c3f6-daf0-4892-b733-e120d9f619f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('781ea225-a88f-4a37-bc6d-721c7f675414', 'संधि से', false, '9186c3f6-daf0-4892-b733-e120d9f619f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab174f7d-5e0a-4d2c-93e3-8db70d091df6', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'सर्वनाम शब्द ''मैं'' और ''वह'' के सही बहुवचन रूप क्रमशः क्या हैं?', 'उत्तम पुरुष ''मैं'' का बहुवचन ''हम'' तथा अन्य पुरुष ''वह'' का बहुवचन ''वे'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69a824f9-91ed-4586-a71c-840b8eb77623', 'हम और वे', true, 'ab174f7d-5e0a-4d2c-93e3-8db70d091df6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87db5cb9-ecc8-4c77-9101-cad404a3cc66', 'मुझे और उसे', false, 'ab174f7d-5e0a-4d2c-93e3-8db70d091df6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bf442c9-b957-4bde-b156-25f52ab52a6d', 'मेरा और उसका', false, 'ab174f7d-5e0a-4d2c-93e3-8db70d091df6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47ae3e2a-07fe-4972-83d7-b30041fba2f6', 'हमलोग और वो', false, 'ab174f7d-5e0a-4d2c-93e3-8db70d091df6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e6f6a3e-5691-4fce-8f1f-1e11c1f9be0b', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'सर्वनाम शब्द ''यह'' और ''तू'' के सही बहुवचन रूप क्रमशः क्या हैं?', '''यह'' का बहुवचन ''ये'' तथा ''तू'' का बहुवचन ''तुम/आप'' होता है।', NOW()) ON CONFLICT DO NOTHING;
