INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('181a16e3-f72e-4c2e-9973-06d1bffb7670', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''रात'', ''बात'' और ''आँख'' के सही बहुवचन रूप क्या हैं?', 'अ-कारान्त स्त्रीलिंग संज्ञाओं में ''एं'' अनुस्वार सहित: रात -> रातें; बात -> बातें; आँख -> आँखें; सड़क -> सड़कें।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97dc4e27-0aac-48d0-9fcc-b21173991b51', 'रातें, बातें, आँखें', true, '181a16e3-f72e-4c2e-9973-06d1bffb7670');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42fd21cc-6dd6-4c36-8e36-025d3442daac', 'रातों, बातों, आँखों', false, '181a16e3-f72e-4c2e-9973-06d1bffb7670');
