INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d6291d9-cb64-498d-a26a-af401700a199', 'राती, बाती, आँखी', false, '181a16e3-f72e-4c2e-9973-06d1bffb7670');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90ef4061-cd7a-40e3-9473-6088dd9a044f', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''पंखा'', ''कमरा'' और ''जूता'' के सही बहुवचन रूप क्या हैं?', 'आ-कारान्त पुल्लिंग शब्दों के अंत में ''ए'': पंखा -> पंखे; कमरा -> कमरे; जूता -> जूते; बेटा -> बेटे।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a5cddf9-89fd-43e4-81ad-3d5e5f4e9d66', 'पंखे, कमरे, जूते', true, '90ef4061-cd7a-40e3-9473-6088dd9a044f');
