INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30112ed6-bfda-426f-8ee8-3c11578c7f79', 'पंखाएं, कमराएं', false, '90ef4061-cd7a-40e3-9473-6088dd9a044f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0532b973-00d7-4905-9fd5-3f974bf9d56c', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'वाक्य को शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24a0bca4-bf96-40e5-9a2a-f9ec7f502001', 'मुझे आपके दर्शन हुए। (''दर्शन'' नित्य बहुवचन शब्द है)', true, '0532b973-00d7-4905-9fd5-3f974bf9d56c');
