INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46ceefa6-93af-4adb-beb8-6c3af2eb38d7', 'आदरार्थक बहुवचन (एकवचन व्यक्ति हेतु सम्मान सूचक बहुवचन क्रिया)', true, '818a85ef-7d50-47e0-b7b9-3272bccd7cb3');
