INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea950a7a-efa5-484e-8f7f-c348bd7a5d2a', 'द्विवचन', false, '818a85ef-7d50-47e0-b7b9-3272bccd7cb3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c0e0132-0cac-488b-9131-3e4ccdaaff3b', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3e04aab-296d-4c33-964f-f37a014ef164', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '9c0e0132-0cac-488b-9131-3e4ccdaaff3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbe49156-51b6-4f80-aef6-0f20e66676d1', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '9c0e0132-0cac-488b-9131-3e4ccdaaff3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14bde37c-49a9-4428-a5c9-422e8d031c63', '(A) सही है, परन्तु (R) गलत है।', false, '9c0e0132-0cac-488b-9131-3e4ccdaaff3b');
