INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb06128a-16e2-4b64-9c99-980d3f071317', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'सुमेलित कीजिए (शब्द और उनके सही बहुवचन):
(क) बहु   -> (i) नीतियां
(ख) नीति  -> (ii) बहुएँ
(ग) चिड़िया -> (iii) चिड़ियाँ
(घ) नारी   -> (iv) नारियाँ', 'बहु = बहुएँ; नीति = नीतियाँ; चिड़िया = चिड़ियाँ; नारी = नारियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c1906d5-197f-4cd4-9fb9-98e1a673ef9c', 'क-(ii), ख-(i), ग-(iii), घ-(iv)', true, 'fb06128a-16e2-4b64-9c99-980d3f071317');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec80ef4c-55ed-405b-9be5-b903e77c8a3e', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, 'fb06128a-16e2-4b64-9c99-980d3f071317');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48718e18-bfe5-4dbe-9d77-9e4c36c9a3d0', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'fb06128a-16e2-4b64-9c99-980d3f071317');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('439ff469-3dc6-40d8-9ff7-909de2e72da9', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'fb06128a-16e2-4b64-9c99-980d3f071317');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdf94f5a-1dd1-431a-a82b-405e202b2c50', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'भाववाचक, गुणवाचक तथा द्रव्यवाचक संज्ञाओं का प्रयोग सामान्यतः किस वचन में होता है?', 'अमूर्त भाववाचक और द्रव्यवाचक संज्ञाएँ नित्य एकवचन में रहती हैं; बहुवचन बनने पर वे जातिवाचक रूप ले लेती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59b5453c-699a-4302-8309-c82160c953ab', 'सदैव एकवचन में (किन्तु जब भाववाचक संज्ञा बहुवचन बनती है, जैसे ''दूरियाँ, बुराइयाँ, अच्छाइयाँ'', तो वह जातिवाचक संज्ञा बन जाती है)', true, 'bdf94f5a-1dd1-431a-a82b-405e202b2c50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b2b822e-c7dc-4dd1-831d-19d951c34b7a', 'सदैव बहुवचन में', false, 'bdf94f5a-1dd1-431a-a82b-405e202b2c50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('186ce966-aa64-457e-a639-5a91c07c0272', 'उभयवचन में', false, 'bdf94f5a-1dd1-431a-a82b-405e202b2c50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1f981c3-52b1-48aa-9f5c-8049d1d06433', 'द्विवचन में', false, 'bdf94f5a-1dd1-431a-a82b-405e202b2c50');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fcd71eec-7d78-4433-98d3-6a499f8ef4b8', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'निम्नलिखित वाक्यों पर विचार कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17631756-07ab-4405-976f-fbe217ca7a69', 'सभी वाक्य 1, 2 और 3 सत्य हैं', true, 'fcd71eec-7d78-4433-98d3-6a499f8ef4b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b569a05a-8604-4d72-a0d7-9ac5340fccb0', 'वाक्य 1 और 2 केवल', false, 'fcd71eec-7d78-4433-98d3-6a499f8ef4b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('272ddbab-db7c-45db-a092-6df8808c68f1', 'वाक्य 2 और 3 केवल', false, 'fcd71eec-7d78-4433-98d3-6a499f8ef4b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3afa035-f9d2-4112-abbb-c2fa9229e938', 'वाक्य 1 और 3 केवल', false, 'fcd71eec-7d78-4433-98d3-6a499f8ef4b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('843eac09-556e-4dba-b1f9-48fff499e4a4', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'संबोधन कारक में बहुवचन बनाते समय ''ओ'' की मात्रा के साथ अनुस्वार (ं) क्यों नहीं लगाया जाता?', 'केंद्रीय हिंदी निदेशालय के मानक वर्तनी नियम के अनुसार संबोधन कारक के बहुवचन में अनुस्वार-रहित ''ओ'' (भाइयो, मित्रो, देवियो) का प्रयोग शुद्ध है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac9a0ad7-712f-4db2-8841-8f58c789f264', 'संबोधन में अनुस्वार का प्रयोग वर्जित है (जैसे: ''हे भाइयो!'', ''बालको!'', ''साथियो!'' शुद्ध हैं ; ''भाइयों!'', ''बालकों!'' अशुद्ध हैं)', true, '843eac09-556e-4dba-b1f9-48fff499e4a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4e6aa28-34e4-4df2-940a-d54b9d7f8e6d', 'क्योंकि संबोधन केवल एकवचन में होता है', false, '843eac09-556e-4dba-b1f9-48fff499e4a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed8c5e09-a85d-4c57-8f1c-0ca6128c277e', 'क्योंकि अनुस्वार लगाने से शब्द बदल जाता है', false, '843eac09-556e-4dba-b1f9-48fff499e4a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fd6330e-9ec6-4ea7-a5cb-73c1d9070c20', 'कोई नियम नहीं है', false, '843eac09-556e-4dba-b1f9-48fff499e4a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d44f3c6-3de9-403f-9cb4-6400b71110d0', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'एकवचन शब्द ''श्रीमती'' और ''कवयित्री'' के सही बहुवचन रूप क्या होंगे?', 'ई-कारान्त स्त्रीलिंग संज्ञाओं के बहुवचन में अंतिम ई ह्रस्व ''इ'' में बदलकर ''याँ'' जुड़ती है: श्रीमतियाँ, कवयित्रियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff88b98a-920c-46f1-91cb-4c4b83441997', 'श्रीमती -> श्रीमतियाँ ; कवयित्री -> कवयित्रियाँ', true, '0d44f3c6-3de9-403f-9cb4-6400b71110d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb65bf98-2e3b-4aaf-9702-c9d881c3d9c4', 'श्रीमती -> श्रीमतियां ; कवयित्री -> कवयित्री', false, '0d44f3c6-3de9-403f-9cb4-6400b71110d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63d4b7f7-54de-459f-9ade-eab7263e0113', 'श्रीमती -> श्रीमतीगण', false, '0d44f3c6-3de9-403f-9cb4-6400b71110d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d61674a-8df6-40ac-b71b-41ceaea62f8e', 'दोनों अपरिवर्तित रहते हैं', false, '0d44f3c6-3de9-403f-9cb4-6400b71110d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73a30181-8a39-4523-943e-33185ef133a6', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'एकवचन शब्द ''अध्यापक'' और ''कवि'' का आदरयुक्त विधिवत बहुवचन रूप क्या होगा?', 'सम्माननीय पदों के समूहवाची बहुवचन रूप ''गण'', ''वृंद'', ''मंडल'' जोड़कर बनाए जाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa72b7c2-d94a-4338-a6f1-78d7cfd256cc', 'अध्यापकवृंद (या अध्यापकगण) और कविगण (या कविमंडल)', true, '73a30181-8a39-4523-943e-33185ef133a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('269ef81f-75da-4258-a814-84209e706e40', 'अध्यापिकाएँ और कविताएँ', false, '73a30181-8a39-4523-943e-33185ef133a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47b598ea-6feb-4206-b0ba-29e67dfcc9ad', 'अध्यापकों और कवियों', false, '73a30181-8a39-4523-943e-33185ef133a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8ed1617-eddf-4eb7-92aa-adfd841cc691', 'अध्यापके और कविये', false, '73a30181-8a39-4523-943e-33185ef133a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58fa0cd1-6ef0-4cb1-85fc-e386414adccc', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'वाक्य को शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dfc9015-ac91-47d2-aa71-acdfac99c482', 'पेड़ों पर चिड़ियाँ बैठी हैं। (''चिड़ियाँ'' बहुवचन के अनुसार ''हैं'' अनुस्वार युक्त क्रिया होगी)', true, '58fa0cd1-6ef0-4cb1-85fc-e386414adccc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9d2323e-9251-41fc-91b1-149bb2513491', 'पेड़ पर चिड़िया बैठी है।', false, '58fa0cd1-6ef0-4cb1-85fc-e386414adccc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5bead37-7bf7-416a-8dda-6d011dd599fe', 'पेड़ों में चिड़ियाँ बैठा है।', false, '58fa0cd1-6ef0-4cb1-85fc-e386414adccc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69a34647-6572-49bb-9e1f-c3ca13199d2b', 'पेड़ पर चिड़ियों बैठी हैं।', false, '58fa0cd1-6ef0-4cb1-85fc-e386414adccc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5923a49-17b1-4eb2-b8b7-ece85e887ece', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'संख्यावाची विशेषणों के साथ जातिवाचक संज्ञाओं के वचन के संबंध में सही नियम कौन-सा है?', 'निश्चित समूहवाची एवं परिमाण सूचक संख्याओं के साथ द्रव्य/जातिवाचक संज्ञाएँ सामान्यतः एकवचन रूप में प्रयुक्त होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9ee19aa-42ab-45a3-832d-6181a1e3b194', 'जब निश्चित संख्यावाची विशेषण आते हैं, तो जातिवाचक संज्ञा प्रायः एकवचन में ही प्रयुक्त होती है (जैसे: ''पाँच सौ रुपया'', ''दो दर्जन केला'')', true, 'a5923a49-17b1-4eb2-b8b7-ece85e887ece');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2646b8bf-f1fb-4c82-a1c4-9ab59b5c0ee5', 'वे सदैव बहुवचन में ही आती हैं', false, 'a5923a49-17b1-4eb2-b8b7-ece85e887ece');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5be71e0e-482f-471d-85e4-9fb03b99ff47', 'वे स्त्रीलिंग बन जाती हैं', false, 'a5923a49-17b1-4eb2-b8b7-ece85e887ece');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d559fa47-3c63-425d-bab4-ae8d39c31e3e', 'कोई नियम नहीं है', false, 'a5923a49-17b1-4eb2-b8b7-ece85e887ece');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d564185-6a0d-48a8-bf1e-aac3ffafbcc8', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'एकवचन शब्द ''तिथि'' और ''जाति'' के सही बहुवचन रूप क्या हैं?', 'इ-कारान्त स्त्रीलिंग शब्दों में अंत में ''याँ'' जुड़ता है: तिथि -> तिथियाँ; जाति -> जातियाँ; रीति -> रीतियाँ; पंक्ति -> पंक्तियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d3ba8fc-e988-4ef0-8847-1b1ce98fc11c', 'तिथियाँ और जातियाँ', true, '0d564185-6a0d-48a8-bf1e-aac3ffafbcc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42bc464b-081f-4ae7-aee8-2429cac63c7f', 'तिथियों और जातियों', false, '0d564185-6a0d-48a8-bf1e-aac3ffafbcc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46fddde4-7f2d-4703-8fd7-1105ae481f39', 'तिथि और जाति', false, '0d564185-6a0d-48a8-bf1e-aac3ffafbcc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('791c8a45-a54f-4983-bf5d-836be7018a52', 'तिथिया और जातिया', false, '0d564185-6a0d-48a8-bf1e-aac3ffafbcc8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ebe994e-a1ce-4129-8340-51e87acd1743', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'वाक्य में रेखांकित पदों के वचन का सही युग्म चुनिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6ccdf79-b3c3-494f-8522-46b297b5833f', 'जनता = नित्य एकवचन ; लाखों रुपए = बहुवचन (तिर्यक बहुवचन)', true, '6ebe994e-a1ce-4129-8340-51e87acd1743');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('869f869d-930e-4c5d-9fc4-1f528c9fde8d', 'जनता = बहुवचन ; लाखों रुपए = एकवचन', false, '6ebe994e-a1ce-4129-8340-51e87acd1743');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('185aae5f-7a35-4b40-a1cd-dec55844f0bc', 'दोनों एकवचन हैं', false, '6ebe994e-a1ce-4129-8340-51e87acd1743');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25a72e05-5c99-449a-95df-fac7383019bb', 'दोनों बहुवचन हैं', false, '6ebe994e-a1ce-4129-8340-51e87acd1743');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d570bbf1-cba8-46b9-ab10-94f8ec681589', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'What is the internationally accepted standard unit of LENGTH in the International System of Units (SI Units)?', 'The Metre (m) is the fundamental base SI unit for measuring linear distance and length worldwide.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc14ce4c-ed67-4d25-9013-58e698609fd5', 'Metre (m)', true, 'd570bbf1-cba8-46b9-ab10-94f8ec681589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e38f52c-e695-46d1-8db5-04157e643c94', 'Centimetre (cm)', false, 'd570bbf1-cba8-46b9-ab10-94f8ec681589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('489898e2-d8f5-472b-86f7-039ba43292c1', 'Kilometre (km)', false, 'd570bbf1-cba8-46b9-ab10-94f8ec681589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4403b7a3-fe5f-4c3d-a79c-141df3aca292', 'Foot (ft)', false, 'd570bbf1-cba8-46b9-ab10-94f8ec681589');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9fdc3fe-ebf3-4c78-b838-72d030af7750', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'How many Centimetres (cm) are there in exactly 1 Metre (m)?', '1 metre = 100 centimetres (1 m = 100 cm = 1,000 mm).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71dfc295-eee2-41cd-b868-bd91ad89131c', '100 cm', true, 'a9fdc3fe-ebf3-4c78-b838-72d030af7750');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8d698d4-02cc-45af-bfbe-e6b2f2ac3673', '10 cm', false, 'a9fdc3fe-ebf3-4c78-b838-72d030af7750');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3a8dfda-28a2-4e64-9354-95633f1dc5b8', '1,000 cm', false, 'a9fdc3fe-ebf3-4c78-b838-72d030af7750');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01ea1a1-c039-4e1b-84fa-8ecd183564c8', '1,000 mm', false, 'a9fdc3fe-ebf3-4c78-b838-72d030af7750');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2c2b21a-65fc-4f98-900c-d2773fd9f112', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'How many Metres (m) make up exactly 1 Kilometre (km)?', 'The metric prefix ''kilo'' represents 1,000; therefore 1 km = 1,000 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73f48de4-c767-4d7c-b5aa-24baa4e91a49', '1,000 metres (1 km = 1,000 m)', true, 'c2c2b21a-65fc-4f98-900c-d2773fd9f112');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('145e55f5-b198-4767-94e8-81b11699a029', '100 metres', false, 'c2c2b21a-65fc-4f98-900c-d2773fd9f112');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ade45ba1-fae1-403c-8589-51d7917b9246', '10,000 metres', false, 'c2c2b21a-65fc-4f98-900c-d2773fd9f112');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bc4c4e4-f2c5-478e-9031-19e9ee68b7f3', '500 metres', false, 'c2c2b21a-65fc-4f98-900c-d2773fd9f112');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2aa5b595-526a-4bb0-8f60-0843b59584f2', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'Why were ancient non-standard units of length like ''Handspan'', ''Footstep'', and ''Cubits'' discarded for scientific measurements?', 'Biological anatomical variations caused commercial discrepancies, necessitating invariant scientific standard units.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a20f8b24-0038-49ee-8413-de0a8d837b6f', 'Because human body dimensions vary from person to person, leading to inconsistent, inaccurate, and unreliable measurements', true, '2aa5b595-526a-4bb0-8f60-0843b59584f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fb98a1d-2ba3-44df-b05d-28c95722b4b0', 'Because rulers are cheaper', false, '2aa5b595-526a-4bb0-8f60-0843b59584f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72c3183f-7094-4ee9-ba57-9b648af3a550', 'Because hands cannot measure wood', false, '2aa5b595-526a-4bb0-8f60-0843b59584f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13a56f61-1817-443a-86f8-df61d06ee87c', 'Because kings banned hands', false, '2aa5b595-526a-4bb0-8f60-0843b59584f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b793bf24-107f-42e7-9059-5a6697578cbe', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'The motion of an object along a straight line path is called:', 'Linear unidirectional motion along a single straight axis is rectilinear motion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2963eb4-13d4-4e16-94c3-6920f8da0787', 'Rectilinear Motion (e.g. a car moving on a straight road, march-past of soldiers)', true, 'b793bf24-107f-42e7-9059-5a6697578cbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3694dcf8-8fa9-424a-8bfd-0e62fef1b432', 'Circular Motion', false, 'b793bf24-107f-42e7-9059-5a6697578cbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef715269-c19f-4456-a2b9-57992731b86c', 'Periodic Motion', false, 'b793bf24-107f-42e7-9059-5a6697578cbe');
