INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0adefd5-b03d-4d40-8d0a-7cda768cfc00', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'The motion of an object along a circular path such that its distance from a fixed central point remains constant is called:', 'Trajectory tracking along the circumference of a circle at constant radial distance is circular motion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('042ad5de-6cc7-4fab-9c7a-c6e5dbc07cb1', 'Circular Motion (e.g. motion of blades of an electric fan, hands of a clock)', true, 'f0adefd5-b03d-4d40-8d0a-7cda768cfc00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dad918a-5cd5-48ac-901f-b989c214c5cc', 'Rectilinear Motion', false, 'f0adefd5-b03d-4d40-8d0a-7cda768cfc00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25dc745d-c189-46a1-8c86-bc01f6f40849', 'Periodic Motion', false, 'f0adefd5-b03d-4d40-8d0a-7cda768cfc00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('135a3a25-36dd-440b-8f7b-ed0650062ce8', 'Random Motion', false, 'f0adefd5-b03d-4d40-8d0a-7cda768cfc00');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8958c95a-4c53-499f-85c0-6f5c84c61e3e', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'Motion that repeats itself at regular equal intervals of time is called:', 'Harmonic oscillatory motions repeating over a constant time period (T) are periodic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f1ed6d1-da56-4a54-a097-2ad5a67e8b93', 'Periodic Motion (e.g. pendulum of a clock, branch of a tree swinging, string of a guitar)', true, '8958c95a-4c53-499f-85c0-6f5c84c61e3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f50f246d-c6fb-414e-bb7f-2f8bfbeb23ff', 'Rectilinear Motion', false, '8958c95a-4c53-499f-85c0-6f5c84c61e3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4494d703-a2c5-4c93-a104-d3c3305d8ed1', 'Random Motion', false, '8958c95a-4c53-499f-85c0-6f5c84c61e3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1360daf2-d59b-420a-bb67-cb618180b8f0', 'Non-periodic Motion', false, '8958c95a-4c53-499f-85c0-6f5c84c61e3e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46dc35a6-d1e2-43b0-b1db-6b8c3d113b75', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'What instrument is used by tailors to measure the curved circumference of a person''s chest or waist?', 'Flexible measuring tape conforms along curved anatomical contours where rigid straight rulers cannot bend.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8871c134-acaf-442d-be54-304f51460ce3', 'A flexible Measuring Tape', true, '46dc35a6-d1e2-43b0-b1db-6b8c3d113b75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96653303-f747-4998-be2e-5c19d1325093', 'A rigid wooden meter rod', false, '46dc35a6-d1e2-43b0-b1db-6b8c3d113b75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29115e77-3ae7-465a-82a7-6edb5be382f5', 'A metal divider', false, '46dc35a6-d1e2-43b0-b1db-6b8c3d113b75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29d61ec6-b862-40f1-8003-faac63cb2aa5', 'A compass', false, '46dc35a6-d1e2-43b0-b1db-6b8c3d113b75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3caaf46-9307-4c3b-99bd-b94efd1f4797', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'What revolutionary invention in the history of human transport made land travel and haulage of heavy loads dramatically faster?', 'The wheel substituted rolling friction for sliding friction, revolutionizing wheeled vehicle transport.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d335e6c-a201-478d-af57-b5fd98689332', 'The invention of the Wheel', true, 'b3caaf46-9307-4c3b-99bd-b94efd1f4797');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e809b5e-1bcd-47ba-8777-fdbb8600b3d5', 'The invention of stone knives', false, 'b3caaf46-9307-4c3b-99bd-b94efd1f4797');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d35a2239-e46d-40c9-a24e-3557a6506028', 'The invention of paper', false, 'b3caaf46-9307-4c3b-99bd-b94efd1f4797');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c1b36e9-6a91-4ca9-80cf-f5441a66e707', 'The invention of glass', false, 'b3caaf46-9307-4c3b-99bd-b94efd1f4797');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a94c13b-b161-49a9-9373-2d2b1a59ab6d', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'Which prime mover invented in the 18th century paved the way for the development of modern high-speed steam locomotives and railways?', 'The Watt steam engine transformed thermodynamic enthalpy into mechanical work for railway transport.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6218bff-de89-47e5-8e8c-4d667fc2209d', 'Steam Engine (by James Watt)', true, '2a94c13b-b161-49a9-9373-2d2b1a59ab6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa88a69f-ede2-4e72-bd38-8284118ec7b8', 'Electric Motor', false, '2a94c13b-b161-49a9-9373-2d2b1a59ab6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96b284f7-14c1-4f57-84ee-af0337ccaa72', 'Jet Engine', false, '2a94c13b-b161-49a9-9373-2d2b1a59ab6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eb73ec0-4fa7-4401-b72e-cedabefd1728', 'Diesel Engine', false, '2a94c13b-b161-49a9-9373-2d2b1a59ab6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c5090f4-6df0-4ea2-8e45-002ebb951862', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'Which of the following is an example of an object exhibiting MULTIPLE types of motion simultaneously?', 'A rolling sphere or bicycle wheel rotates about its axle while translating rectilinearly forward.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1fe0930-7f50-40fb-9500-bc20cc86247b', 'A rolling ball on the ground (both Rotational motion on its axis and Rectilinear motion along the floor)', true, '4c5090f4-6df0-4ea2-8e45-002ebb951862');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47c04829-ee68-49c8-9112-0a1121def9b0', 'A bird sleeping in a nest', false, '4c5090f4-6df0-4ea2-8e45-002ebb951862');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15beb214-7d92-4f73-89ae-6445b1d0e14e', 'A fixed stone on a hill', false, '4c5090f4-6df0-4ea2-8e45-002ebb951862');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('726ed26c-0f47-48f1-8da9-194d731f712d', 'A book lying on a table', false, '4c5090f4-6df0-4ea2-8e45-002ebb951862');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17ff34fb-b95b-40a8-8f49-f69ba5ea8e75', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'A change in the position of an object with time relative to a stationary reference point (frame of reference) is called:', 'Kinematic motion is defined as a temporal displacement in positional coordinates relative to a chosen reference frame.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa0cf626-2125-4c84-8c62-823cbc1a6253', 'Motion', true, '17ff34fb-b95b-40a8-8f49-f69ba5ea8e75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d99ca4c2-5c91-4422-bf53-509a5ff552e4', 'Rest', false, '17ff34fb-b95b-40a8-8f49-f69ba5ea8e75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd692be6-bf76-48d6-af26-687b832f623d', 'Force', false, '17ff34fb-b95b-40a8-8f49-f69ba5ea8e75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6709e171-8e4f-4cc5-a37e-0773e20c49b0', 'Friction', false, '17ff34fb-b95b-40a8-8f49-f69ba5ea8e75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3d727a9-4ad2-4877-a733-9916d05d50aa', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'How can the length of a curved line (such as a winding river curve on a map) be measured accurately?', 'A non-stretchable string traces continuous curvature and is subsequently calibrated against a linear metric scale.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93c0d334-72ff-4ba0-b0d2-a5c957e00907', 'By laying a flexible thread carefully along the curved path from start to end, marking the endpoints on the thread, and then measuring the straightened thread on a standard meter scale', true, 'e3d727a9-4ad2-4877-a733-9916d05d50aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ed402d3-d0c1-483c-81f0-47ff570d048f', 'By bending a wooden ruler until it snaps', false, 'e3d727a9-4ad2-4877-a733-9916d05d50aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c75593b1-983e-4a79-89eb-2655b922ab10', 'By guessing with eyes', false, 'e3d727a9-4ad2-4877-a733-9916d05d50aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2fa75eb-f2de-4502-a394-e10a194d1529', 'By weighing the paper on a balance', false, 'e3d727a9-4ad2-4877-a733-9916d05d50aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07adea24-3d05-4bb8-a500-b41b46152137', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What is ''Parallax Error'' in taking length measurements with a scale, and how is it avoided?', 'Viewing the scale at an oblique angle introduces parallax displacement; the sight line must be perpendicular (90°) to the mark.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a85bd5a-a3d7-45d2-ad07-15eaff7e2524', 'An apparent optical shift error caused by viewing the scale markings from an angle; it is avoided by positioning the eye directly vertically above the point of measurement', true, '07adea24-3d05-4bb8-a500-b41b46152137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c8bd6b1-000c-497e-be24-38fbc16a8018', 'An error caused by wind blowing', false, '07adea24-3d05-4bb8-a500-b41b46152137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24c76b9e-fc2f-497d-8876-3907da61d0e8', 'An error caused by warm weather', false, '07adea24-3d05-4bb8-a500-b41b46152137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79c53f9f-06e4-452e-89ea-c9982f17c477', 'An error caused by dirty paper', false, '07adea24-3d05-4bb8-a500-b41b46152137');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b8c17cd-fcae-448f-8053-d17295cc131f', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'If the zero mark (0 cm) of a ruler is broken or damaged, how should one take an accurate measurement?', 'True length = (Final scale reading) - (Initial non-zero offset reading). E.g. 14.3 cm - 1.0 cm = 13.3 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dc37f04-6649-4706-a870-f246ece64084', 'Start measuring from any other full mark (e.g. 1.0 cm or 2.0 cm) and subtract that initial reading from the final end reading', true, '4b8c17cd-fcae-448f-8053-d17295cc131f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ad419b2-5aa8-4c18-8d81-e9f84b5c5c80', 'Throw the ruler away immediately', false, '4b8c17cd-fcae-448f-8053-d17295cc131f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c68b246d-c13c-4389-a96b-f9356ad3ec60', 'Guess the missing zero mark', false, '4b8c17cd-fcae-448f-8053-d17295cc131f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01421c93-7972-4624-b895-03a83173a1c9', 'Add 10 cm to the final reading', false, '4b8c17cd-fcae-448f-8053-d17295cc131f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6509481b-7357-4d58-b6ec-938cbf44bb1b', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Why is a passenger sitting inside a moving bus in motion relative to a roadside tree, but AT REST relative to a fellow passenger sitting next to them?', 'Kinematics is reference-frame dependent: position vector changes in the Earth frame, but dr/dt = 0 in the bus co-moving frame.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fc51c77-0321-4010-b06c-31050c746baa', 'Motion is relative: position changes relative to the stationary roadside tree, but position remains unchanged relative to the bus interior and fellow passenger', true, '6509481b-7357-4d58-b6ec-938cbf44bb1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('728e843c-8585-46e7-a957-62d94ba7c845', 'Because the bus has windows', false, '6509481b-7357-4d58-b6ec-938cbf44bb1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00240f1f-72f4-45b5-8e0f-c6adc71bf967', 'Because the tree is running backwards', false, '6509481b-7357-4d58-b6ec-938cbf44bb1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('077656cb-80ff-47bd-8199-8017e1c5ff08', 'Because eyes get confused in a bus', false, '6509481b-7357-4d58-b6ec-938cbf44bb1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c674796-3322-473c-958b-f2b1a22bbdd6', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What types of motion are executed by the needle of a sewing machine and its rotating balance wheel?', 'The balance wheel rotates about a fixed axis (circular/rotational), while the crank drives the needle in periodic reciprocating motion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3c3d80f-e2d1-4af4-8f12-626fa2e0fb85', 'The sewing needle moves up and down in Periodic / Oscillatory motion, while the balance wheel executes Circular / Rotational motion', true, '3c674796-3322-473c-958b-f2b1a22bbdd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2207eb0b-13aa-48a7-9490-d9dd5c61a7c3', 'Both move in straight rectilinear motion', false, '3c674796-3322-473c-958b-f2b1a22bbdd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98dc0d55-ad08-4057-8732-a46d69b4e56b', 'The needle moves in circles', false, '3c674796-3322-473c-958b-f2b1a22bbdd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('375d9da4-c8b3-4bd8-a007-7cd7110f7939', 'Both are completely at rest', false, '3c674796-3322-473c-958b-f2b1a22bbdd6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31394231-1838-4816-93e1-92e9d7d7ec7f', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What is the key difference between ''Rotational Motion'' and ''Circular Motion''?', 'Rotation involves spin about an intrinsic internal axis; circular revolution tracks a trajectory around an extrinsic external focus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a61eb7fb-04e6-43b1-bae6-0e49c1c4deb3', 'In Rotational motion, the entire body spins about an internal fixed axis passing through itself (e.g. spinning top, Earth''s spin); in Circular motion, an object moves around an external central point (e.g. Earth revolving around the Sun)', true, '31394231-1838-4816-93e1-92e9d7d7ec7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2ae057e-62c5-4d3b-9dce-8c280ea28c3c', 'Rotational motion has no speed', false, '31394231-1838-4816-93e1-92e9d7d7ec7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('441997ef-0550-4386-9c64-7c888b21a305', 'Circular motion is always straight', false, '31394231-1838-4816-93e1-92e9d7d7ec7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e4ffcbf-098e-46d3-af1e-8d1c7ed6b2a7', 'There is no difference', false, '31394231-1838-4816-93e1-92e9d7d7ec7f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6ab27c4-cfdc-46d8-ad33-ebca78957d67', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Convert a distance of 4.5 kilometres into metres (m) and centimetres (cm):', '4.5 km × 1,000 m/km = 4,500 m. 4,500 m × 100 cm/m = 450,000 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f96c20d3-5b44-4a4a-9888-135b10ed7272', '4,500 m and 450,000 cm', true, 'f6ab27c4-cfdc-46d8-ad33-ebca78957d67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f746411b-eaab-4f84-aaf0-e0ab7e396cd1', '450 m and 45,000 cm', false, 'f6ab27c4-cfdc-46d8-ad33-ebca78957d67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b7ac8dc-085d-4462-b5db-1eba9900604e', '45,000 m and 4,500 cm', false, 'f6ab27c4-cfdc-46d8-ad33-ebca78957d67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5acca8c3-55a3-44af-a921-a2a13e53af48', '4.5 m and 450 cm', false, 'f6ab27c4-cfdc-46d8-ad33-ebca78957d67');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81d6496c-1489-41ad-b4e1-c941a6a04796', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Convert the length of a pencil measuring 18.5 cm into millimetres (mm):', '1 cm = 10 mm. 18.5 cm × 10 mm/cm = 185 mm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d46d5394-d73c-409b-b705-2d57e92e4c45', '185 mm (18.5 × 10 mm = 185 mm)', true, '81d6496c-1489-41ad-b4e1-c941a6a04796');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51bf08f5-7b9b-450c-8548-cf1d575dfe39', '1.85 mm', false, '81d6496c-1489-41ad-b4e1-c941a6a04796');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb87cd9c-a5d5-4ac5-a317-32dec7831510', '1,850 mm', false, '81d6496c-1489-41ad-b4e1-c941a6a04796');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3a5eab4-328a-430f-b5b5-63347d698613', '0.185 mm', false, '81d6496c-1489-41ad-b4e1-c941a6a04796');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3733a47c-c060-46a5-ab9f-e6af8a026bee', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Which of the following motions is NON-PERIODIC (does not repeat itself at regular intervals)?', 'Random athletic maneuvering has no fixed periodic time interval, making it non-periodic/random.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('682874de-a7f9-4f6f-b3b1-ee50c5734574', 'A footballer running unpredictably across the sports ground', true, '3733a47c-c060-46a5-ab9f-e6af8a026bee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbd150f-b5a9-4bd8-84ff-b542e7a6339f', 'The swing of a simple pendulum', false, '3733a47c-c060-46a5-ab9f-e6af8a026bee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67caaa3e-1470-4e6a-947c-77c754e9c82a', 'The revolution of the Earth around the Sun', false, '3733a47c-c060-46a5-ab9f-e6af8a026bee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0164352a-36a3-453b-8d18-68bd0696e2a5', 'The heartbeat of a healthy resting human', false, '3733a47c-c060-46a5-ab9f-e6af8a026bee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cf231f2-304b-4610-adb7-6d89ec1a0cfa', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What type of motion is executed by the plucked strings of a Sitar or Guitar when playing musical notes?', 'Tensioned strings execute transverse periodic standing wave vibrations generating acoustic harmonics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('517e7de8-a098-4b27-8481-aed097662e56', 'Periodic / Vibratory (Oscillatory) Motion', true, '6cf231f2-304b-4610-adb7-6d89ec1a0cfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a05eb84-c698-4b95-9dff-11e63dc44ca4', 'Rectilinear Motion', false, '6cf231f2-304b-4610-adb7-6d89ec1a0cfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f4aae15-88b9-4598-8a97-3e95c9845880', 'Rotational Motion', false, '6cf231f2-304b-4610-adb7-6d89ec1a0cfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b5c8921-f01a-4a0e-80e6-3a467f65c54a', 'Circular Motion', false, '6cf231f2-304b-4610-adb7-6d89ec1a0cfa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f8164b0-340b-4a45-8422-3d3bb9cfe1a5', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Why does an elastic rubber measuring tape give incorrect and inconsistent measurements of length?', 'Elastic deformation alters the calibrated spacing between interval markers under variable tensile stress.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa14a37a-42a4-4690-a9e1-dc742737cf95', 'Because rubber stretches variably depending on how hard a person pulls it, giving different lengths for the exact same object', true, '6f8164b0-340b-4a45-8422-3d3bb9cfe1a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c20cb06-c1aa-4796-8b94-ca6870a88ec7', 'Because rubber has no numbers printed on it', false, '6f8164b0-340b-4a45-8422-3d3bb9cfe1a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4cf50ee-380d-4eb7-9df8-3f40ef86b779', 'Because rubber dissolves in air', false, '6f8164b0-340b-4a45-8422-3d3bb9cfe1a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06b7c6ee-f38b-4f88-b759-5165e7c868b8', 'Because rubber is too heavy', false, '6f8164b0-340b-4a45-8422-3d3bb9cfe1a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d642b2d-83e7-4d06-b3c4-3987b1e557ea', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What is the historical chronological progression of transportation technology across human civilizations?', 'Transport evolved from biological walking to animal draught, mechanical combustion steam engines, internal combustion cars, and aerospace rocketry.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a13cb712-c804-41bb-9bae-92590218b84e', 'Walking on foot -> Pack animals -> Wooden wheeled bullock carts / Sailboats -> Steam engine railways -> Motorcars & Aeroplanes -> Supersonic jets & Spacecraft', true, '4d642b2d-83e7-4d06-b3c4-3987b1e557ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07c97af9-0653-41f8-b333-31f305d0e83f', 'Aeroplanes -> Walking -> Steam engines', false, '4d642b2d-83e7-4d06-b3c4-3987b1e557ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86dc8759-a814-4b70-b384-1dda395a8a86', 'Steam engines -> Spacecraft -> Walking', false, '4d642b2d-83e7-4d06-b3c4-3987b1e557ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b89850f-aa78-422b-9380-83a47d645070', 'Bicycles -> Spacecraft -> Bullock carts', false, '4d642b2d-83e7-4d06-b3c4-3987b1e557ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d9815f3-6568-4909-9c2a-b4f101c59938', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'A student measures the thickness of a single page of a 500-page book using a 15 cm plastic scale. How can they achieve high accuracy?', 'Bulk averaging method: dividing composite thickness by total sheet count minimizes least-count reading error.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60b190e5-3b5c-40d6-bc08-284576473fdf', 'Measure the total thickness of all 500 pages together with the scale and divide that total thickness by 500', true, '6d9815f3-6568-4909-9c2a-b4f101c59938');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78b68b46-3433-41a7-a7cd-83856ce4a675', 'Try to read a single page with a magnifying lens', false, '6d9815f3-6568-4909-9c2a-b4f101c59938');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bea0473f-6144-43f5-8adc-07deb0aa0a5a', 'Guess the thickness as 1 mm', false, '6d9815f3-6568-4909-9c2a-b4f101c59938');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6a1697a-ade8-42be-8879-fb47c9a74f94', 'Burn the book and weigh the ash', false, '6d9815f3-6568-4909-9c2a-b4f101c59938');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14852cdb-114e-4df3-81c9-f23cefcba74f', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Which of the following SI unit abbreviations is written CORRECTLY according to standard international IUPAP conventions?', 'SI unit symbols are written in lower case (m for metre), never pluralized with ''s'', and never followed by periods unless at sentence ends.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19441b7b-39a1-427a-be8b-7347a152d43a', '50 m (lower-case m without plural ''s'' or full stop)', true, '14852cdb-114e-4df3-81c9-f23cefcba74f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8297931f-d013-4b44-a3e2-c914fe6f8b35', '50 ms.', false, '14852cdb-114e-4df3-81c9-f23cefcba74f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55a0a185-59bf-4648-b758-6a2523a684d4', '50 Metres.', false, '14852cdb-114e-4df3-81c9-f23cefcba74f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db740145-3a4f-4c72-921c-7fdcad5a5fb6', '50 Mts', false, '14852cdb-114e-4df3-81c9-f23cefcba74f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe86b929-f3e1-4637-81c9-e03b4c006715', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What motion is performed by the Earth around its own polar axis and around the Sun respectively?', 'Earth combines intrinsic diurnal axial rotation (24h) with periodic orbital revolution (365.25d).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a41c50b5-1dcc-4b11-a53e-ebd3b1df8136', 'Rotational motion on its own axis (every 24 hours) AND Circular/Elliptical Periodic revolution around the Sun (every 365¼ days)', true, 'fe86b929-f3e1-4637-81c9-e03b4c006715');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74552322-fab7-493e-b15d-07f3b95694a2', 'Rectilinear motion only', false, 'fe86b929-f3e1-4637-81c9-e03b4c006715');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae234fe8-fce6-432f-9b37-057c9c60b294', 'Random non-periodic motion', false, 'fe86b929-f3e1-4637-81c9-e03b4c006715');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ad3ef54-a43f-4d4a-ace1-11e964e1c420', 'It remains completely at rest', false, 'fe86b929-f3e1-4637-81c9-e03b4c006715');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52c5f010-5417-4c5c-9e80-3db514ace80e', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'In which year was the International System of Units (SI) accepted internationally by the General Conference on Weights and Measures?', 'The 11th CGPM officially established the International System of Units (SI) based on the metric system in 1960.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4dac376-dfe5-4062-bf7f-bfaef7f243f5', '1960', true, '52c5f010-5417-4c5c-9e80-3db514ace80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6b8ae1d-870b-47e5-b4d2-fb8113f00737', '1947', false, '52c5f010-5417-4c5c-9e80-3db514ace80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee84ef45-fbbd-4765-b56e-cbdb196f7dce', '1900', false, '52c5f010-5417-4c5c-9e80-3db514ace80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45b62c8c-0525-433d-a691-f1ec4c973d6d', '2000', false, '52c5f010-5417-4c5c-9e80-3db514ace80e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7839275f-6f56-42ca-92d6-fbb59138ec07', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d8057fd-e595-4989-8f8c-f63c1d1b53f6', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '7839275f-6f56-42ca-92d6-fbb59138ec07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2e1076a-6a82-468b-85be-aff142e0429d', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '7839275f-6f56-42ca-92d6-fbb59138ec07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44ad0509-6767-42ac-b7bc-846a6b6b70a0', '(A) is true, but (R) is false.', false, '7839275f-6f56-42ca-92d6-fbb59138ec07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f9f4d65-98fb-4b5a-beac-936ad9059348', '(A) is false, but (R) is true.', false, '7839275f-6f56-42ca-92d6-fbb59138ec07');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbf66583-bca5-4228-a081-0c4f80cb8e8c', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Spot the IMPOSTER in the following group of motions classified as Periodic Motion:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b1e8384-850f-47af-b533-99e0451b93e8', 'Motion of a child on a swing', false, 'bbf66583-bca5-4228-a081-0c4f80cb8e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a28581f-de11-440b-852b-9dce27f8317f', 'Oscillation of a clock pendulum', false, 'bbf66583-bca5-4228-a081-0c4f80cb8e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a97a59c-f447-4989-9fe1-2790b8f995a9', 'Plucked string of a sitar', false, 'bbf66583-bca5-4228-a081-0c4f80cb8e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d212836-16fb-4401-9283-92b13720e8dd', 'A dry leaf falling in turbulent wind', true, 'bbf66583-bca5-4228-a081-0c4f80cb8e8c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e764cfc-f153-4323-9859-58f303cf778d', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'A student measures the length of a wooden block using a broken scale starting at 2.4 cm mark. The reading at the other end is 18.7 cm. What is the true physical length of the block?', 'True length = Final reading - Initial offset = 18.7 cm - 2.4 cm = 16.3 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b96e1c6-a09c-45ff-9435-3f86d25c5814', '16.3 cm (18.7 cm - 2.4 cm = 16.3 cm)', true, '0e764cfc-f153-4323-9859-58f303cf778d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84a5af92-2d22-40ef-a63a-64be370b48c5', '18.7 cm', false, '0e764cfc-f153-4323-9859-58f303cf778d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3833bbd7-fea6-4d2c-aeda-faef98229422', '21.1 cm', false, '0e764cfc-f153-4323-9859-58f303cf778d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7aa7e26a-50d1-44c0-8283-3b780d75ce35', '14.3 cm', false, '0e764cfc-f153-4323-9859-58f303cf778d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b7fa7ef-2db4-4054-8893-e780525c7ec4', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Match Column I (Moving Objects) with Column II (Primary Types of Motion):
(a) A stone tied to a string and whirled overhead -> (i) Rectilinear Motion
(b) An apple falling vertically from a tree       -> (ii) Periodic / Oscillatory Motion
(c) The membrane of a tabla being played        -> (iii) Circular Motion
(d) A potter''s wheel spinning on its pivot      -> (iv) Rotational Motion', 'Whirled stone = Circular; Falling apple = Rectilinear; Tabla membrane = Periodic; Potter''s wheel = Rotational.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60730625-bc7b-4547-88fb-e12dec63d8dc', 'a-(iii), b-(i), c-(ii), d-(iv)', true, '2b7fa7ef-2db4-4054-8893-e780525c7ec4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02cc4808-9447-466d-b1a1-5e4a5e438301', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '2b7fa7ef-2db4-4054-8893-e780525c7ec4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf7f8d6d-d7b2-4e49-8e47-797b8e66ab39', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '2b7fa7ef-2db4-4054-8893-e780525c7ec4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1085d8cb-e900-4906-a35c-2553fbc9b322', 'a-(ii), b-(iv), c-(i), d-(iii)', false, '2b7fa7ef-2db4-4054-8893-e780525c7ec4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa8acc44-b521-4226-8eb3-6c228361cbf8', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Read the statements regarding measurement conventions:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('960b8ca2-86cd-458d-a65e-d549fec59a9f', 'Statements 1 and 3 only', true, 'aa8acc44-b521-4226-8eb3-6c228361cbf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41c6f640-e25d-4b97-ab7b-1c2bc49cfb40', 'Statements 1 and 2 only', false, 'aa8acc44-b521-4226-8eb3-6c228361cbf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1723f2bd-a4b6-4cfa-b7e8-01568e3c1cdb', 'Statements 2 and 3 only', false, 'aa8acc44-b521-4226-8eb3-6c228361cbf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1feb86b9-cb08-497e-a76c-5ed745d8a913', 'All Statements 1, 2, and 3', false, 'aa8acc44-b521-4226-8eb3-6c228361cbf8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('266ac3b3-8d76-4e63-8e0a-a05aaa673ce0', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Why was the standard prototype metre bar historically crafted from an alloy of 90% Platinum and 10% Iridium and preserved at 0°C near Paris?', 'Pt-Ir provides supreme chemical inertness, high mechanical hardness, and minimal thermal contraction/expansion across seasonal shifts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5b364d7-eb63-4484-870d-529480211116', 'Platinum-Iridium alloy exhibits extreme resistance to corrosion and an exceptionally low coefficient of thermal expansion, preserving invariant physical length', true, '266ac3b3-8d76-4e63-8e0a-a05aaa673ce0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85682d4b-fa14-4ffb-a045-1f8f657fdbb1', 'To make the ruler shiny and expensive', false, '266ac3b3-8d76-4e63-8e0a-a05aaa673ce0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca968ba6-9334-4aed-b165-5b1601cea9c2', 'Because platinum melts easily in cold water', false, '266ac3b3-8d76-4e63-8e0a-a05aaa673ce0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d24d119-1ecc-4616-8c25-729769336a47', 'Because France wanted to hoard gold', false, '266ac3b3-8d76-4e63-8e0a-a05aaa673ce0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b49bd565-1ea4-47ef-93e2-d0b09a12de26', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'A cyclist pedals along a straight level road at 15 km/h. Analyze the motion of the bicycle''s WHEEL versus the motion of the cyclist''s PEDALS:', 'Wheels translate along the ground while spinning on their hub; foot pedals trace circular revolutions around the central bottom bracket spindle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11215313-f063-48ab-a402-cc8c57a7436f', 'The wheels execute both Rotational motion and Rectilinear translation forward, while the pedals execute Circular motion around the crank axle', true, 'b49bd565-1ea4-47ef-93e2-d0b09a12de26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b61e8818-6a51-42b7-ae35-3425dfabe752', 'Both move in straight lines only', false, 'b49bd565-1ea4-47ef-93e2-d0b09a12de26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf78e2a7-3941-4284-8a04-630d5319222a', 'Both move in random motion', false, 'b49bd565-1ea4-47ef-93e2-d0b09a12de26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8412b639-18cf-4e17-bc53-e4ab13c994a3', 'The bicycle is at rest', false, 'b49bd565-1ea4-47ef-93e2-d0b09a12de26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('680050a9-c9c1-4485-baf6-3716e043cf5a', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Consider four measurement scenarios:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c816b7e-ea00-4064-9f09-a9637fe05bd5', '1: cm ; 2: km (or AU) ; 3: mm ; 4: km', true, '680050a9-c9c1-4485-baf6-3716e043cf5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c921340-0300-4aaa-93a6-28a67db7a865', '1: mm ; 2: m ; 3: km ; 4: cm', false, '680050a9-c9c1-4485-baf6-3716e043cf5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2276771d-67e8-4bbe-a778-6d3aabb44550', '1: m ; 2: cm ; 3: km ; 4: mm', false, '680050a9-c9c1-4485-baf6-3716e043cf5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7f3b642-f582-4ced-a199-9cc0e54cdd38', '1: km ; 2: mm ; 3: cm ; 4: m', false, '680050a9-c9c1-4485-baf6-3716e043cf5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a88d23bd-c6f1-4a96-b06f-de14d87f1aa9', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Why must a measurement always be expressed as BOTH a number (magnitude) AND a unit (e.g. ''15 metres'' and NOT just ''15'')?', 'A physical quantity Q = n · [U], where n is the dimensionless numerical multiplier and U is the standardized invariant unit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbc5fb72-96fa-4c04-a5d2-ad70cbe03793', 'A pure number conveys no physical dimension or scale; the unit gives definite physical meaning and comparability to standard references', true, 'a88d23bd-c6f1-4a96-b06f-de14d87f1aa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bb54373-e575-46a5-adb9-571e7033eee2', 'Because numbers are illegal without letters', false, 'a88d23bd-c6f1-4a96-b06f-de14d87f1aa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0c7cd64-9a15-427f-ab8b-2454733bde64', 'To make sentences longer', false, 'a88d23bd-c6f1-4a96-b06f-de14d87f1aa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f61077f9-6250-437c-8814-85e479166175', 'Because scientists like words', false, 'a88d23bd-c6f1-4a96-b06f-de14d87f1aa9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f05aba42-e46c-459c-93e1-c9ff17a5df2f', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'What type of motion is executed by a marching soldier during a Republic Day parade along the straight Kartavya Path?', 'Linear forward center-of-mass translation (rectilinear) combines with periodic antagonistic pendular limb oscillations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('110733b6-eb56-40e7-bc97-3303f97abc5b', 'The soldier''s entire body moves in Rectilinear motion along the road, while their arms and legs swing in Periodic / Oscillatory motion', true, 'f05aba42-e46c-459c-93e1-c9ff17a5df2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04a97609-6e1b-4d81-b5fd-ebfe61094283', 'Pure circular motion', false, 'f05aba42-e46c-459c-93e1-c9ff17a5df2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('287d2be4-dda5-41cb-b427-962ecfa71758', 'Random chaotic motion', false, 'f05aba42-e46c-459c-93e1-c9ff17a5df2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ceb6ba6-9de9-4909-8f1b-043393244602', 'Rotational spin', false, 'f05aba42-e46c-459c-93e1-c9ff17a5df2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cff323e8-5456-43ca-a395-747176e23ad7', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Which of the following accurately describes the modern SI definition of 1 Metre adopted in 1983 by the CGPM?', 'The metre is defined by fixing the speed of light in vacuum c = 299,792,458 m/s, tying length directly to cesium atomic clocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd7e0973-d485-4a1c-a8b5-57477cea3a43', 'The distance travelled by light in absolute vacuum during a time interval of 1 / 299,792,458 of a second', true, 'cff323e8-5456-43ca-a395-747176e23ad7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49232d3f-5203-42fe-b342-1065b946f03f', 'The length of a king''s arm', false, 'cff323e8-5456-43ca-a395-747176e23ad7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('590f0be3-f66c-4ffa-8ffc-52092bff6ecd', 'The circumference of Earth divided by 100', false, 'cff323e8-5456-43ca-a395-747176e23ad7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7a5aaf7-c398-4568-953b-018f477b96d9', 'The length of a gold bar in London', false, 'cff323e8-5456-43ca-a395-747176e23ad7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46b7c268-19e1-4bf6-845b-7ceee770c9db', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'A toy train moves along a circular railway track of radius 7 metres. When it completes one full circle, what are its Distance travelled and Net Displacement respectively?', 'Scalar path distance = circumference = 2πr = 44 m; vector displacement = Δr = r_final - r_initial = 0 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b7b434e-1020-4ceb-93f4-61707e6ec85f', 'Distance = 44 metres (2πr = 2 × 22/7 × 7) ; Displacement = 0 metres (since start and end points coincide)', true, '46b7c268-19e1-4bf6-845b-7ceee770c9db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94782eaa-240c-40c4-8916-8924f5276da6', 'Distance = 0 m ; Displacement = 44 m', false, '46b7c268-19e1-4bf6-845b-7ceee770c9db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3125ff8-d058-4b5b-a084-56de61c264c0', 'Distance = 14 m ; Displacement = 14 m', false, '46b7c268-19e1-4bf6-845b-7ceee770c9db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a549f45-2d1c-47b8-bb00-17fe66d28a81', 'Distance = 44 m ; Displacement = 44 m', false, '46b7c268-19e1-4bf6-845b-7ceee770c9db');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce30ed30-cdf4-4f24-8c81-c654fba75583', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'A number representing a part of a whole (where the whole may be a single object or a group of objects) is called a:', 'A fraction a/b expresses a parts taken out of b equal partitions of a whole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6591581f-a491-4cb4-80c1-f20c6663b0fe', 'Fraction (written as a/b where b ≠ 0)', true, 'ce30ed30-cdf4-4f24-8c81-c654fba75583');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('069fed4d-806d-4a90-b7dd-131a799c5cb5', 'Integer', false, 'ce30ed30-cdf4-4f24-8c81-c654fba75583');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90197095-9cf1-4c1d-831b-8eff6ce09d32', 'Natural Number', false, 'ce30ed30-cdf4-4f24-8c81-c654fba75583');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('595dd141-95bd-4fa3-b672-aaafd9f108f0', 'Equation', false, 'ce30ed30-cdf4-4f24-8c81-c654fba75583');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0f04fd8-763c-4cc8-aa33-e07d1ac2a7cb', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'In the fraction 3/5, what is the number 3 called and what is the number 5 called?', 'The top number is the Numerator (parts counted); the bottom number is the Denominator (total equal parts).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dd85685-90bd-4739-8358-36f6382e4b12', '3 is the Numerator and 5 is the Denominator', true, 'c0f04fd8-763c-4cc8-aa33-e07d1ac2a7cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f805ca2-0f97-46f5-b78d-0d5fd57fa752', '3 is the Denominator and 5 is the Numerator', false, 'c0f04fd8-763c-4cc8-aa33-e07d1ac2a7cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3a41673-9ba8-4abf-94f5-0f43c100abf3', 'Both are Numerators', false, 'c0f04fd8-763c-4cc8-aa33-e07d1ac2a7cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fac6cadc-f19a-4e82-9a61-a6a67e7802ab', 'Both are Denominators', false, 'c0f04fd8-763c-4cc8-aa33-e07d1ac2a7cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2534fb77-c13d-44f7-9e43-cf76f9e30601', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'A fraction in which the Numerator is strictly LESS than the Denominator (Numerator < Denominator, representing a quantity less than 1) is a:', 'A proper fraction has a numerator smaller than its denominator, with a numeric value strictly between 0 and 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5602a047-b30f-4ebc-98f4-b45c443cdb02', 'Proper Fraction (e.g., 2/3, 5/8, 1/4)', true, '2534fb77-c13d-44f7-9e43-cf76f9e30601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('145ba055-a286-4b8c-bf29-5b08ef39bc88', 'Improper Fraction', false, '2534fb77-c13d-44f7-9e43-cf76f9e30601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27fb94a2-3475-47fe-b94f-9596f1185893', 'Mixed Fraction', false, '2534fb77-c13d-44f7-9e43-cf76f9e30601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49405a7d-161f-4f03-af19-176d3a1f7d21', 'Unit Fraction', false, '2534fb77-c13d-44f7-9e43-cf76f9e30601');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49a46005-ccc2-4b8d-816a-28c4dbdafe2f', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'A fraction in which the Numerator is GREATER than or equal to the Denominator (Numerator ≥ Denominator, representing a quantity ≥ 1) is an:', 'An improper fraction has a numerator greater than or equal to its denominator (value ≥ 1).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3886a790-1768-4051-abc7-b18bd4c96367', 'Improper Fraction (e.g., 7/4, 9/5, 11/3)', true, '49a46005-ccc2-4b8d-816a-28c4dbdafe2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('536036f1-35b0-4383-a133-261286728f47', 'Proper Fraction', false, '49a46005-ccc2-4b8d-816a-28c4dbdafe2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8d475cc-b2e1-4708-9a65-6a792b24f82d', 'Unit Fraction', false, '49a46005-ccc2-4b8d-816a-28c4dbdafe2f');
