INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1e3a49d-c3a2-4ded-966b-ae21816a64cf', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'A number expressed as a combination of a Whole number and a Proper fraction (like 2 ¾) is called a:', 'A mixed fraction (e.g. 2 ¾ = 2 + ¾ = 11/4) represents an integer quotient combined with a proper fractional remainder.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8695eba-cfb4-4ae0-babb-903f0c8a8bd4', 'Mixed Fraction', true, 'a1e3a49d-c3a2-4ded-966b-ae21816a64cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f38e980-d238-4677-ba8c-cf9b1a202f60', 'Proper Fraction', false, 'a1e3a49d-c3a2-4ded-966b-ae21816a64cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f79a2a91-87d4-4c83-a098-b54bc5f2e579', 'Unit Fraction', false, 'a1e3a49d-c3a2-4ded-966b-ae21816a64cf');
