INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ab8c9bc-ae13-4a12-9bfa-5539c78c531a', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'Fractions having the EXACT SAME denominator (such as 2/7, 5/7, 6/7) are called:', 'Fractions sharing an identical denominator are Like Fractions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47e909fd-2837-4580-921a-63e88a478eeb', 'Like Fractions', true, '3ab8c9bc-ae13-4a12-9bfa-5539c78c531a');
