INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22d46d6c-3066-42e6-a4ad-64973135c6db', 'Equivalent Fractions', false, '3ab8c9bc-ae13-4a12-9bfa-5539c78c531a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d87c473-e5fe-43ca-ac3e-b4e8915fcb97', 'Improper Fractions', false, '3ab8c9bc-ae13-4a12-9bfa-5539c78c531a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30d24da7-1c60-44d3-9aeb-0e4f97aa62b3', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'Fractions having DIFFERENT denominators (such as 2/3, 4/5, 7/9) are called:', 'Fractions with unequal denominators are Unlike Fractions.', NOW()) ON CONFLICT DO NOTHING;
