INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e79e40a-c13a-41c4-a28e-9a257f10217e', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'A fraction whose numerator is always 1 (such as 1/2, 1/3, 1/4, 1/7) is called a:', 'A fraction of the form 1/n where n is a natural number is a Unit Fraction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('182c659f-a7f7-4f9f-a938-0ce413cb3a54', 'Unit Fraction', true, '3e79e40a-c13a-41c4-a28e-9a257f10217e');
