INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0371fc63-01c3-4585-8b95-92cd9d4bed88', 'Like Fraction', false, '3e79e40a-c13a-41c4-a28e-9a257f10217e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b720db85-67fb-496f-aeef-185d6b4e891a', 'Mixed Fraction', false, '3e79e40a-c13a-41c4-a28e-9a257f10217e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72c5ac64-8c1b-49c1-b644-442fa3466253', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'What fraction of an hour is 20 minutes?', '1 hour = 60 minutes. Fraction = 20/60 = 1/3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('857e514f-16df-4244-b5d5-fa58e48fc1a1', '1/3 (20/60 = 1/3)', true, '72c5ac64-8c1b-49c1-b644-442fa3466253');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a033f1b-b91b-4fbd-bdda-b5a18ac164f4', '1/2', false, '72c5ac64-8c1b-49c1-b644-442fa3466253');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eabc311d-1145-4242-8c79-00798c23ab41', '1/4', false, '72c5ac64-8c1b-49c1-b644-442fa3466253');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('812cd000-008f-4d52-88ba-053564e81bee', '2/5', false, '72c5ac64-8c1b-49c1-b644-442fa3466253');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c410c25-4de1-4ae6-ba73-e737ee4bc4ec', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'What fraction of a day is 8 hours?', '1 day = 24 hours. Fraction = 8/24 = 1/3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f7134f0-37c1-4245-a246-91847208b85f', '1/3 (8/24 = 1/3)', true, '4c410c25-4de1-4ae6-ba73-e737ee4bc4ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b53cd88e-ba10-4308-81ee-77dde5ba55a8', '1/4', false, '4c410c25-4de1-4ae6-ba73-e737ee4bc4ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fa94a6b-6fe9-4b8e-9499-4501dee448b3', '1/2', false, '4c410c25-4de1-4ae6-ba73-e737ee4bc4ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bc628c9-c417-42e4-a8ca-289dab634470', '3/8', false, '4c410c25-4de1-4ae6-ba73-e737ee4bc4ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e82379c1-6d66-4c5d-903d-cf895b0f62cb', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'Convert the improper fraction 17/4 into a Mixed Fraction:', '17 ÷ 4 = 4 with remainder 1, yielding 4 ¼.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09bcb76f-2167-453c-87ac-7631866744c7', '4 ¼ (17 ÷ 4 = 4 with remainder 1)', true, 'e82379c1-6d66-4c5d-903d-cf895b0f62cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('111af535-d790-4431-8d15-22f87a01d331', '3 ¾', false, 'e82379c1-6d66-4c5d-903d-cf895b0f62cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7e2b070-6402-4fce-933f-88e77437c818', '4 ½', false, 'e82379c1-6d66-4c5d-903d-cf895b0f62cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb43711b-1f2a-4fc0-90e2-395a8f1ec631', '5 ¼', false, 'e82379c1-6d66-4c5d-903d-cf895b0f62cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c244b7c-b90f-4516-9d45-89a3bfdb3ca1', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'Convert the mixed fraction 5 ⅔ into an Improper Fraction:', '(5 × 3 + 2) / 3 = (15 + 2) / 3 = 17/3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ecdd5d9-607e-4bca-bc95-f17d3133a8f7', '17/3 ((5 × 3 + 2)/3 = 17/3)', true, '8c244b7c-b90f-4516-9d45-89a3bfdb3ca1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a5f4819-ba78-4125-83c5-72f18b2b1779', '13/3', false, '8c244b7c-b90f-4516-9d45-89a3bfdb3ca1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1761395-927c-4cbe-9c30-90078b446488', '15/3', false, '8c244b7c-b90f-4516-9d45-89a3bfdb3ca1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3100438-861c-418f-ae0f-ec5d10290ad5', '10/3', false, '8c244b7c-b90f-4516-9d45-89a3bfdb3ca1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('996f1aff-0309-4603-8e5b-3d962d7afc2d', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Which of the following is an Equivalent Fraction to 2/5 with numerator 6?', 'Multiplying numerator and denominator by 3 gives (2 × 3) / (5 × 3) = 6/15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9bc26bf-b1a6-4d69-a03e-533d742643f9', '6/15 (multiply numerator and denominator by 3: 2×3 / 5×3)', true, '996f1aff-0309-4603-8e5b-3d962d7afc2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19c373a8-b8cc-4a59-8091-c38f8b02c22b', '6/10', false, '996f1aff-0309-4603-8e5b-3d962d7afc2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3a58d15-d452-42aa-9b06-41de1a6b043e', '6/20', false, '996f1aff-0309-4603-8e5b-3d962d7afc2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9885730-933e-4e38-908b-84d0e2285414', '6/25', false, '996f1aff-0309-4603-8e5b-3d962d7afc2d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('335c2cd2-30ee-49d0-86dd-0fe1beab4686', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'A fraction is said to be in its ''Simplest Form'' (or lowest terms) when:', 'A fraction a/b is in simplest irreducible form if gcd(a, b) = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8ce6947-53e7-468b-974e-064f36650db7', 'The HCF of its Numerator and Denominator is strictly 1 (they are co-prime)', true, '335c2cd2-30ee-49d0-86dd-0fe1beab4686');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a12bd92-0a98-4b3e-8fa5-848c6187e360', 'The numerator is 1', false, '335c2cd2-30ee-49d0-86dd-0fe1beab4686');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68056e1c-73cc-4985-89c0-f920d30a54d1', 'The denominator is 100', false, '335c2cd2-30ee-49d0-86dd-0fe1beab4686');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b024b67-2d7a-4583-8d08-42dd60992d67', 'The fraction is greater than 1', false, '335c2cd2-30ee-49d0-86dd-0fe1beab4686');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8849177b-d31b-4e5b-9023-3a3ebdf6b5af', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Reduce the fraction 36/48 to its Simplest Form:', 'HCF(36, 48) = 12. 36 ÷ 12 / 48 ÷ 12 = 3/4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('488b233f-2437-484f-9dff-53fb89c5000b', '3/4 (divide numerator and denominator by HCF = 12)', true, '8849177b-d31b-4e5b-9023-3a3ebdf6b5af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5810d38b-a968-46cc-888f-c03484b872cb', '2/3', false, '8849177b-d31b-4e5b-9023-3a3ebdf6b5af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22bc98c7-1116-40c6-89ed-c6bd1eaec991', '6/8', false, '8849177b-d31b-4e5b-9023-3a3ebdf6b5af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21bce5e2-6399-4ad8-8736-09fb2258b92a', '18/24', false, '8849177b-d31b-4e5b-9023-3a3ebdf6b5af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53373ca8-44e3-4c97-a154-551c13e10f52', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Which fraction is LARGER: 3/5 or 4/7?', '3/5 = 21/35 and 4/7 = 20/35. Since 21/35 > 20/35, 3/5 is larger.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38aaf8e3-ab5a-4f6a-827d-914e93e44971', '3/5 (Cross-multiplying: 3 × 7 = 21 > 5 × 4 = 20)', true, '53373ca8-44e3-4c97-a154-551c13e10f52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bd4ef5c-6485-48e0-91a5-cf361ba77cdd', '4/7', false, '53373ca8-44e3-4c97-a154-551c13e10f52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6fe7dc7-a4fe-49a1-ab9b-1026b8ce3270', 'Both are equal', false, '53373ca8-44e3-4c97-a154-551c13e10f52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf5c5ece-6864-4742-b0db-ef7fe7107b13', 'Cannot be compared', false, '53373ca8-44e3-4c97-a154-551c13e10f52');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('309b1550-9832-4ae0-b35b-a359d27c0b77', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Calculate the sum of like fractions: 3/11 + 5/11 + 2/11', 'For like fractions, add numerators over the common denominator: (3 + 5 + 2)/11 = 10/11.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('579e52bd-55bc-4557-8d6d-2a7d4794331e', '10/11', true, '309b1550-9832-4ae0-b35b-a359d27c0b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22b187c1-3321-4aa8-a9cc-49cc4668fba5', '10/33', false, '309b1550-9832-4ae0-b35b-a359d27c0b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79859c8e-0bf8-4339-bd84-f7520d89ac03', '1', false, '309b1550-9832-4ae0-b35b-a359d27c0b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('263e026b-8142-4e84-9344-bbd6fa55ca89', '8/11', false, '309b1550-9832-4ae0-b35b-a359d27c0b77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7daac9c-4cea-4321-a534-61ab9df89157', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Calculate the difference: 7/9 - 4/9', '(7 - 4)/9 = 3/9 = 1/3 in simplest form.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea74e86b-b59b-4486-8cb0-e37fecba2333', '3/9 = 1/3', true, 'a7daac9c-4cea-4321-a534-61ab9df89157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b821632c-100f-47ed-b072-986dc3da2af0', '3/0', false, 'a7daac9c-4cea-4321-a534-61ab9df89157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c91cdf1b-4841-4420-93be-73ae4b8494e5', '11/9', false, 'a7daac9c-4cea-4321-a534-61ab9df89157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cff1ff6-6a83-46c7-b8cb-b79d256194bb', '3/18', false, 'a7daac9c-4cea-4321-a534-61ab9df89157');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0480c88b-1119-4fe3-b96b-c4d135208b40', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Calculate the sum of unlike fractions: 2/5 + 1/3', 'LCM(5, 3) = 15. 2/5 = 6/15 and 1/3 = 5/15. Sum = (6 + 5)/15 = 11/15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e637147-dcb4-461c-bce4-732ed8a3f667', '11/15 ((6 + 5)/15 = 11/15)', true, '0480c88b-1119-4fe3-b96b-c4d135208b40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cf86403-5e87-432c-9ecf-ebe955f0eb2b', '3/8', false, '0480c88b-1119-4fe3-b96b-c4d135208b40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb538b8a-79d8-42db-b377-a018419295cd', '2/15', false, '0480c88b-1119-4fe3-b96b-c4d135208b40');
