INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fbc43ec7-c6d1-4a43-8648-076060ffb4eb', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Calculate the difference: 5/6 - 3/4', 'LCM(6, 4) = 12. 5/6 = 10/12 and 3/4 = 9/12. Difference = (10 - 9)/12 = 1/12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a24a90e3-6d07-48dd-a7fc-7e41534cd67d', '1/12 ((10 - 9)/12 = 1/12)', true, 'fbc43ec7-c6d1-4a43-8648-076060ffb4eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccc4c795-d181-490b-b94a-7ef1e2158e5c', '2/2', false, 'fbc43ec7-c6d1-4a43-8648-076060ffb4eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('897310a9-e645-4d83-92f2-4662fa578578', '2/24', false, 'fbc43ec7-c6d1-4a43-8648-076060ffb4eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa4b6412-98c9-4b60-aa49-392e1628fa2f', '1/6', false, 'fbc43ec7-c6d1-4a43-8648-076060ffb4eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('405faa65-007b-49db-8eff-83c4643f5fc6', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Solve the addition of mixed fractions: 2 ⅓ + 3 ½', 'Whole parts sum = 2 + 3 = 5. Fractional parts = 1/3 + 1/2 = 5/6. Total = 5 5/6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b611cb04-e487-4edc-b085-f363e6939b8b', '5 ⅚ (7/3 + 7/2 = (14 + 21)/6 = 35/6 = 5 ⅚)', true, '405faa65-007b-49db-8eff-83c4643f5fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d7e5173-f4e4-4665-a9ca-e476e2eaf150', '5 ⅖', false, '405faa65-007b-49db-8eff-83c4643f5fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6afd175-eed9-47c3-b3ff-610971b796d6', '6 ⅚', false, '405faa65-007b-49db-8eff-83c4643f5fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dce8965-fc99-4c34-9ee2-5f203c173c4b', '5 ⅔', false, '405faa65-007b-49db-8eff-83c4643f5fc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60bf1a3d-497e-4e53-b803-c7ddd738d1e0', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Solve the subtraction of mixed fractions: 4 ⅔ - 2 ⅕', '4 2/3 - 2 1/5 = (4 - 2) + (2/3 - 1/5) = 2 + (10 - 3)/15 = 2 7/15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a693d08f-7a1e-4b72-bf3b-ec2c83366361', '2 ⁷/₁₅ ((14/3 - 11/5) = (70 - 33)/15 = 37/15 = 2 ⁷/₁₅)', true, '60bf1a3d-497e-4e53-b803-c7ddd738d1e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5653b5a4-d87d-4ceb-ab35-f1261c9297d7', '2 ⅖', false, '60bf1a3d-497e-4e53-b803-c7ddd738d1e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9a2033f-132d-4c36-ba96-3f93026f234f', '2 ⅔', false, '60bf1a3d-497e-4e53-b803-c7ddd738d1e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73e66bcd-3589-4fba-8a80-a041ed1b53ab', '1 ⁸/₁₅', false, '60bf1a3d-497e-4e53-b803-c7ddd738d1e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a6458ad-76dc-4a91-bb96-f67ba3979363', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Ramesh had 20 pencils, Sheelu had 50 pencils, and Jamaal had 80 pencils. After 4 months, Ramesh used up 10 pencils, Sheelu used up 25 pencils, and Jamaal used up 40 pencils. What fraction of pencils did each use up?', '10/20 = 1/2; 25/50 = 1/2; 40/80 = 1/2. All three used up identical proportions (1/2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb35a064-b760-43f3-bf6c-80fa27e2e57b', 'Each used up exactly 1/2 of their pencils (10/20 = 25/50 = 40/80 = 1/2)', true, '1a6458ad-76dc-4a91-bb96-f67ba3979363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80a60dd7-2ba2-4000-9d91-0a15aa7a7532', 'Ramesh used 1/4, Sheelu 1/2, Jamaal 3/4', false, '1a6458ad-76dc-4a91-bb96-f67ba3979363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90988aa8-69f8-4f0e-861b-ea6e908db588', 'Each used 1/3', false, '1a6458ad-76dc-4a91-bb96-f67ba3979363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e940f45-0821-44fe-b35f-4ed6491d2369', 'Each used 3/4', false, '1a6458ad-76dc-4a91-bb96-f67ba3979363');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b026ad1-6465-4f45-a7cb-73e4e89c9a23', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Jaidev takes 2 ⅕ minutes to walk across the school ground. Rahul takes 7/4 minutes to do the same. Who takes less time and by what fraction?', '11/5 = 44/20 min; 7/4 = 35/20 min. Rahul takes less time: 44/20 - 35/20 = 9/20 minutes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1240d79c-3231-4ddd-b444-9801e87015a1', 'Rahul takes less time by 9/20 minutes (Jaidev = 11/5 = 44/20 min ; Rahul = 7/4 = 35/20 min ; Difference = 9/20 min)', true, '0b026ad1-6465-4f45-a7cb-73e4e89c9a23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eb57a3b-90eb-4f4b-a333-8ab01a3f5ef1', 'Jaidev takes less time by 1/2 min', false, '0b026ad1-6465-4f45-a7cb-73e4e89c9a23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4be04d2-ae24-4d84-93a2-14c88c279831', 'Both take equal time', false, '0b026ad1-6465-4f45-a7cb-73e4e89c9a23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a5dedd4-c8b9-4f37-be16-aeb7c8ba59a1', 'Rahul takes less time by 1/4 min', false, '0b026ad1-6465-4f45-a7cb-73e4e89c9a23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25b57d64-b77e-47d3-a222-fdde1f30e89e', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'What must be subtracted from 7/8 to get 1/3?', '7/8 - x = 1/3 -> x = 7/8 - 1/3 = (21 - 8)/24 = 13/24.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('759578bb-4bb6-4f5a-b408-def4f4347539', '13/24 (7/8 - 1/3 = (21 - 8)/24 = 13/24)', true, '25b57d64-b77e-47d3-a222-fdde1f30e89e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef018f21-21ff-435f-8f26-fae8f281d097', '11/24', false, '25b57d64-b77e-47d3-a222-fdde1f30e89e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4518b293-71d3-4093-8761-9872773007f6', '5/8', false, '25b57d64-b77e-47d3-a222-fdde1f30e89e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('690ca548-de34-43d9-b6ea-26f22e74a0d6', '2/3', false, '25b57d64-b77e-47d3-a222-fdde1f30e89e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f459c51-20ff-46e9-bb7a-7d84edc09158', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'What should be added to 3/7 to get 1?', '1 - 3/7 = 7/7 - 3/7 = 4/7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e83b98f1-49a1-4320-8fd4-1c21fb454bb9', '4/7 (1 - 3/7 = (7 - 3)/7 = 4/7)', true, '4f459c51-20ff-46e9-bb7a-7d84edc09158');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f751118-c620-4b00-a185-1a4dddca2083', '3/7', false, '4f459c51-20ff-46e9-bb7a-7d84edc09158');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae84bb8e-18df-4cfb-bedc-abf1f32d94cb', '7/3', false, '4f459c51-20ff-46e9-bb7a-7d84edc09158');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('251f0d00-40ab-4b84-a4bb-14341ee7268c', '1/7', false, '4f459c51-20ff-46e9-bb7a-7d84edc09158');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f64d2981-61f6-426a-be8f-a3eba0164f72', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Sarita bought 2/5 metre of ribbon and Lalita bought 3/4 metre of ribbon. What is the total length of the ribbon they bought together?', '2/5 + 3/4 = (8 + 15)/20 = 23/20 = 1 3/20 metres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e49d4e6d-7807-4542-ad31-759ce351a748', '1 ³/₂₀ metres ((8 + 15)/20 = 23/20 = 1 ³/₂₀ m)', true, 'f64d2981-61f6-426a-be8f-a3eba0164f72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a47b57d-efd6-49d5-95dd-0db72588f568', '1 ½ m', false, 'f64d2981-61f6-426a-be8f-a3eba0164f72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b8290d3-4ea7-42bf-b2fd-58d85202e78f', '5/9 m', false, 'f64d2981-61f6-426a-be8f-a3eba0164f72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87a0088b-00e0-4108-9303-70e28a06ab8e', '1 ⅖ m', false, 'f64d2981-61f6-426a-be8f-a3eba0164f72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3df4e81-0757-450f-aed7-5c9d4c5a4b2d', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'A piece of wire 7/8 metre long broke into two pieces. One piece was 1/4 metre long. How long is the other piece?', '7/8 - 1/4 = 7/8 - 2/8 = 5/8 metre.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a5f2af1-8038-4e20-a7dd-0247c66db793', '5/8 metre (7/8 - 1/4 = 7/8 - 2/8 = 5/8 m)', true, 'a3df4e81-0757-450f-aed7-5c9d4c5a4b2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8061320-834f-4600-8eb9-1adc0c1686d1', '3/8 m', false, 'a3df4e81-0757-450f-aed7-5c9d4c5a4b2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01934af-01dd-4116-9e6c-cf41e35e5b9d', '6/8 m', false, 'a3df4e81-0757-450f-aed7-5c9d4c5a4b2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c7df99b-9799-4815-9b30-42a084b73e44', '1/2 m', false, 'a3df4e81-0757-450f-aed7-5c9d4c5a4b2d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8cdf5e4c-ccae-4ace-b3b8-1bdec7856946', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01c76d05-0f68-48df-b871-ebb726a9a058', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '8cdf5e4c-ccae-4ace-b3b8-1bdec7856946');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1ec12b4-8f82-4b9f-919b-9311338ceb76', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '8cdf5e4c-ccae-4ace-b3b8-1bdec7856946');
