INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb71310c-42ab-456a-b731-442aa717011d', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Spot the IMPOSTER in the following group of fractions that is NOT equivalent to 2/3:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6c39f3a-ddaf-4cf9-a316-e582310f235e', '4/6', false, 'eb71310c-42ab-456a-b731-442aa717011d');
