INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc33624f-9414-4e90-a045-54fe638b3d00', '14/21', false, 'eb71310c-42ab-456a-b731-442aa717011d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c96c5859-076f-463f-8f18-eb10fc8c0025', '16/25', true, 'eb71310c-42ab-456a-b731-442aa717011d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ac543a8-def2-4a8e-8122-8bb9f3a39482', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Simplify the complex fractional expression:
(3 ⅓ + 4 ¼) - (2 ½ + 1 ⅚)', '(10/3 + 17/4) - (5/2 + 11/6) = (40 + 51)/12 - (15 + 11)/6 = 91/12 - 26/6 = 91/12 - 52/12 = 39/12 = 13/4 = 3 ¼.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79814e34-64c4-44a0-9bd8-612842a52df3', '3 ¼ (7 ⁷/₁₂ - 4 ⁴/₆ = 91/12 - 52/12 = 39/12 = 13/4 = 3 ¼)', true, '4ac543a8-def2-4a8e-8122-8bb9f3a39482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4cef899-e689-42a0-95cd-b31d1f1813f0', '3 ½', false, '4ac543a8-def2-4a8e-8122-8bb9f3a39482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('925771fd-5630-4894-9910-66a4b7950f92', '2 ¾', false, '4ac543a8-def2-4a8e-8122-8bb9f3a39482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69963b65-123b-4991-b243-f33e75e2a67a', '4 ¼', false, '4ac543a8-def2-4a8e-8122-8bb9f3a39482');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7839a52d-825a-4e91-b03a-a9b31a684374', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Match Column I (Fraction Pairs) with Column II (Comparison Symbol):
(a) 5/8  ____ 5/12 -> (i) > (Same numerator: smaller denominator is larger)
(b) 3/7  ____ 4/7  -> (ii) < (Same denominator: larger numerator is larger)
(c) 4/6  ____ 2/3  -> (iii) =
(d) 7/10 ____ 3/5  -> (iv) > (since 7/10 > 6/10)', 'a: 5/8 > 5/12; b: 3/7 < 4/7; c: 4/6 = 2/3; d: 7/10 > 3/5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a70a4d0-17f2-4dab-bccb-953194070bb0', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '7839a52d-825a-4e91-b03a-a9b31a684374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6fc8388-4a2a-4e5b-b7cc-2375fa068be6', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '7839a52d-825a-4e91-b03a-a9b31a684374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d621758b-1a5f-423a-8d2a-e898e4432cbb', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '7839a52d-825a-4e91-b03a-a9b31a684374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdea0fd5-52b4-4182-8c12-09e201cda51f', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '7839a52d-825a-4e91-b03a-a9b31a684374');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c323806a-f16c-4fe3-bf35-394fe2743e76', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc2452bb-9725-4baf-9502-4cdfa56053aa', 'Statements 1 and 2 only', true, 'c323806a-f16c-4fe3-bf35-394fe2743e76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75c78e4d-e592-486e-a161-bf680dd8b4a7', 'Statements 2 and 3 only', false, 'c323806a-f16c-4fe3-bf35-394fe2743e76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1ef1982-5fb8-499d-8ee4-0edd26ceca8b', 'Statements 1 and 3 only', false, 'c323806a-f16c-4fe3-bf35-394fe2743e76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec9fa821-03ca-40ac-9525-de1dc0931064', 'All Statements 1, 2, and 3', false, 'c323806a-f16c-4fe3-bf35-394fe2743e76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('317b0741-7a48-4ac0-892c-ac9059f9b0f6', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Arrange the following unlike fractions in ASCENDING order: 2/3, 1/6, 5/9, 7/12', 'LCM(3, 6, 9, 12) = 36: 1/6 = 6/36, 5/9 = 20/36, 7/12 = 21/36, 2/3 = 24/36.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f90fb221-f6ab-41e1-9bd5-aee147c5476c', '1/6 < 5/9 < 7/12 < 2/3 (LCM = 36: 6/36 < 20/36 < 21/36 < 24/36)', true, '317b0741-7a48-4ac0-892c-ac9059f9b0f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f665615-8438-457f-87f8-765f29576c1e', '1/6 < 7/12 < 5/9 < 2/3', false, '317b0741-7a48-4ac0-892c-ac9059f9b0f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('781ee4bf-67cb-4aec-a87f-ae977bd2d32f', '2/3 < 7/12 < 5/9 < 1/6', false, '317b0741-7a48-4ac0-892c-ac9059f9b0f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2f39ef7-e1c8-48b7-b302-ddc52dde41ca', '5/9 < 1/6 < 7/12 < 2/3', false, '317b0741-7a48-4ac0-892c-ac9059f9b0f6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ab0fec1-11f7-42aa-b915-6b227affd2c0', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'In a class of 45 students, 2/5 of the total students are girls. How many boys are there in the class?', 'Girls = 2/5 of 45 = 18. Boys = 3/5 of 45 = 27.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2313bc48-e04b-4833-8080-308a00cf4d28', '27 boys (Girls = 45 × 2/5 = 18 ; Boys = 45 - 18 = 27)', true, '8ab0fec1-11f7-42aa-b915-6b227affd2c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7ab24e9-7e20-4b77-92ba-e43d623c9cd4', '18 boys', false, '8ab0fec1-11f7-42aa-b915-6b227affd2c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c71f263-fa48-43b1-98ec-b71fd60b18bc', '25 boys', false, '8ab0fec1-11f7-42aa-b915-6b227affd2c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4399bb6-405e-41cd-b354-0af6075263ae', '30 boys', false, '8ab0fec1-11f7-42aa-b915-6b227affd2c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fc03491-ae89-4dfa-8a18-efd24bfb9680', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'A tank is 3/5 full of water. If 50 litres of water is needed to fill the tank completely, what is the total capacity of the tank?', 'Remaining 2/5 = 50 litres -> Full capacity = 50 × (5/2) = 125 litres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('575eaedc-55b4-4600-b195-5e271b673423', '125 litres (Empty fraction = 1 - 3/5 = 2/5 ; 2/5 of Total = 50 L -> Total = 50 × 5/2 = 125 L)', true, '5fc03491-ae89-4dfa-8a18-efd24bfb9680');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfb8f1c8-b591-4dba-97e1-ac264e090244', '100 litres', false, '5fc03491-ae89-4dfa-8a18-efd24bfb9680');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06fbb99c-8e5f-4de7-811b-1bfb8b7616f6', '150 litres', false, '5fc03491-ae89-4dfa-8a18-efd24bfb9680');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b2557c7-1318-4e24-b5dc-7c8957749801', '200 litres', false, '5fc03491-ae89-4dfa-8a18-efd24bfb9680');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03f95d89-bc20-464a-8195-409c200cc4ba', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'How is the fraction 3 ⅝ represented on a number line?', '3 ⅝ lies on the interval [3, 4] at 3/8 distance beyond 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ab33336-1997-4892-8968-534382e6268a', 'Between integers 3 and 4, dividing the unit segment into 8 equal parts and taking the 3rd mark from 3', true, '03f95d89-bc20-464a-8195-409c200cc4ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eafd31c-72af-48a8-b243-c572edc925c5', 'Between 0 and 1', false, '03f95d89-bc20-464a-8195-409c200cc4ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f0e2d01-2f50-4a3f-bdd0-74f89a4ca8a6', 'Between 2 and 3', false, '03f95d89-bc20-464a-8195-409c200cc4ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0105f3e4-42cf-4dfe-bceb-4ecc6b02a9be', 'Between 5 and 6', false, '03f95d89-bc20-464a-8195-409c200cc4ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7f5bbae-64a3-4c51-a73f-740c8c6d5e9b', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Which of the following fraction pairs are NOT co-prime in their current form and can be reduced further?', 'HCF(84, 98) = 14 ≠ 1. 84/98 = 6/7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6aa091fe-da99-438d-8e43-855063b6de2f', '84/98 (both divisible by 14: 6/7)', true, 'd7f5bbae-64a3-4c51-a73f-740c8c6d5e9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8e410e0-0fc2-4f83-8338-66da2bfa4044', '15/37', false, 'd7f5bbae-64a3-4c51-a73f-740c8c6d5e9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04a40cef-145c-4b34-9fa3-2c472397ab02', '8/15', false, 'd7f5bbae-64a3-4c51-a73f-740c8c6d5e9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a677f575-dfa0-4421-a64c-68a2fd888d4f', '11/17', false, 'd7f5bbae-64a3-4c51-a73f-740c8c6d5e9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5e589df-e351-4692-bb51-ed19cc40f9bc', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Solve the missing fraction in the box: [ ? ] - 5/8 = 1/4', '? = 1/4 + 5/8 = 2/8 + 5/8 = 7/8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27b1e439-47a3-43d8-97d3-be5a290e11d4', '7/8 (1/4 + 5/8 = 2/8 + 5/8 = 7/8)', true, 'f5e589df-e351-4692-bb51-ed19cc40f9bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d22d578e-7890-408b-9b91-3fb435fdef0e', '6/8', false, 'f5e589df-e351-4692-bb51-ed19cc40f9bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c8a8237-05a1-4e25-8093-4184cccc2e40', '3/8', false, 'f5e589df-e351-4692-bb51-ed19cc40f9bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4e9a92f-5598-4460-a97f-7e4fc0907ef9', '1/2', false, 'f5e589df-e351-4692-bb51-ed19cc40f9bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('137cef56-0c8f-4ab1-b45e-d415271f0dcd', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'A cake was divided into 12 equal slices. Anil ate 1/4 of the cake, Sunita ate 1/3 of the cake, and the rest was eaten by Rohan. What fraction of the cake did Rohan eat?', '1 - (1/4 + 1/3) = 1 - (3/12 + 4/12) = 1 - 7/12 = 5/12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a3ab412-f23d-4a01-8eb7-8a2f26167d1f', '5/12 (Anil = 3/12 ; Sunita = 4/12 ; Remaining = 12/12 - 7/12 = 5/12)', true, '137cef56-0c8f-4ab1-b45e-d415271f0dcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85be9011-0fe0-4949-a0b3-7f990cb637a2', '1/12', false, '137cef56-0c8f-4ab1-b45e-d415271f0dcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ff65830-89e2-48ee-a78b-dae709b0c149', '7/12', false, '137cef56-0c8f-4ab1-b45e-d415271f0dcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bb0305f-538e-44e6-8d51-abb579d33d15', '1/2', false, '137cef56-0c8f-4ab1-b45e-d415271f0dcd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffc028c9-3d0c-47b8-8917-f15e1c26143e', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'Who were the two inseparable childhood friends whose deep bond of friendship was celebrated across the village in ''Fair Play''?', 'Jumman Shaikh and Algu Chowdhry shared an iconic village friendship; whenever either went away, the other looked after his household.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('207aee49-901f-4acb-a025-1b522efefd5c', 'Jumman Shaikh and Algu Chowdhry', true, 'ffc028c9-3d0c-47b8-8917-f15e1c26143e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eb6826f-ffb3-4a35-9ef2-989788ef88af', 'Samjhu Sahu and Jumman', false, 'ffc028c9-3d0c-47b8-8917-f15e1c26143e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('628b6797-987d-4cbb-bd8e-4b119aade456', 'Premchand and Algu', false, 'ffc028c9-3d0c-47b8-8917-f15e1c26143e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6af8a138-4889-42fd-ae45-6a94af4bda08', 'Rahim and Karim', false, 'ffc028c9-3d0c-47b8-8917-f15e1c26143e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be73dede-4788-4b0a-80d1-b767992ca005', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'Why did Jumman''s elderly maternal aunt transfer her property and land to Jumman?', 'The aunt transferred her property in exchange for lifelong care and maintenance from Jumman and his family.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af705b18-34b5-485f-8312-01fc97070d6d', 'On the condition that she would stay with him and he would look after and care for her until her death', true, 'be73dede-4788-4b0a-80d1-b767992ca005');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d8f74d7-2367-491e-9569-2a8a1e646f9e', 'Because she wanted to sell the land', false, 'be73dede-4788-4b0a-80d1-b767992ca005');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d8c5889-114d-4198-99f2-943ee46b1f7c', 'Because she had no house', false, 'be73dede-4788-4b0a-80d1-b767992ca005');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32f1aa90-0083-4c39-8d6c-0c1675d6e63c', 'Because the village panchayat ordered her', false, 'be73dede-4788-4b0a-80d1-b767992ca005');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e396574-78ae-43c4-8c98-0f4086f199b3', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'How did Jumman and his wife Kariman treat the old aunt after the property transfer was officially completed?', 'Once the land was secured, Jumman grew cold and his wife Kariman grudged every bite of food given to the old lady.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96bb0e72-c40f-4b48-be5e-0dd0beaee1da', 'They became indifferent and harsh, grudging even the small amount of daily food she ate and insulting her', true, '4e396574-78ae-43c4-8c98-0f4086f199b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c1f13d2-bc11-49b6-80ab-4c54e347234e', 'They treated her like a queen', false, '4e396574-78ae-43c4-8c98-0f4086f199b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d9c9f16-3aff-4cd7-99e7-8ffcb4d3978e', 'They built her a palace', false, '4e396574-78ae-43c4-8c98-0f4086f199b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1575d54b-0ea6-4589-8940-48858443844e', 'They gave her all their money', false, '4e396574-78ae-43c4-8c98-0f4086f199b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f22926fa-cfc8-44c2-9843-6a582f978182', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'What reasonable demand did the mistreated aunt make when she could no longer bear the daily insults?', 'The aunt requested a modest monthly allowance so she could cook independently with dignity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b5ea5ee-03b3-4f29-a4b8-67d065710f6a', 'She asked for a small monthly allowance to set up a separate kitchen for herself', true, 'f22926fa-cfc8-44c2-9843-6a582f978182');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d274ec3f-00e2-47a8-95a9-374f46947d66', 'She asked for all of Jumman''s property', false, 'f22926fa-cfc8-44c2-9843-6a582f978182');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d863462-e70f-4d94-a595-a1dd1bdefe8e', 'She asked to leave the country', false, 'f22926fa-cfc8-44c2-9843-6a582f978182');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cfa2870-704b-464c-8ee4-43407be4c83c', 'She asked for a car', false, 'f22926fa-cfc8-44c2-9843-6a582f978182');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eceaf545-6ce8-4ff9-bda5-18785e044eaa', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'Whom did the aunt nominate as the Head Panch (Sarpanch) in the village panchayat?', 'Trusting in pure justice, the aunt nominated Algu Chowdhry, knowing a true Panch has no friends or enemies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cef8c4e-d87f-4d8d-b6d1-9391e176e0d3', 'Algu Chowdhry (Jumman''s best friend)', true, 'eceaf545-6ce8-4ff9-bda5-18785e044eaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2efcfeff-a80d-4e0a-a547-2049733dd791', 'Samjhu Sahu', false, 'eceaf545-6ce8-4ff9-bda5-18785e044eaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bdd8e21-d183-49c6-95c1-a620d76f546d', 'The Village Headman', false, 'eceaf545-6ce8-4ff9-bda5-18785e044eaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9a207f0-5bba-4cfd-8453-7ea2042278ee', 'Her nephew', false, 'eceaf545-6ce8-4ff9-bda5-18785e044eaa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7b5c604-34b0-4500-93fc-451ad232b82d', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'What famous principle did the aunt state to Algu: ''The voice of the Panch is the voice of...''?', 'The aunt declared: ''God lives in the heart of the Panch, and his voice is the voice of God.''', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80716807-5363-4325-8c1d-339be63e63cd', 'God', true, 'd7b5c604-34b0-4500-93fc-451ad232b82d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8973ffc8-8f0c-484b-939c-f345ed4e0721', 'The King', false, 'd7b5c604-34b0-4500-93fc-451ad232b82d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('effe598f-d691-4dea-859e-1163cc5647ac', 'The Village', false, 'd7b5c604-34b0-4500-93fc-451ad232b82d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a87fa835-f62a-4c1a-ac85-c65868f09b71', 'Justice', false, 'd7b5c604-34b0-4500-93fc-451ad232b82d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bfc15239-1dae-4b19-bbc0-856f29fb0c48', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'What verdict did Head Panch Algu Chowdhry deliver in the panchayat case regarding the aunt?', 'Upholding absolute justice over personal friendship, Algu ruled that Jumman must pay the allowance or surrender the land.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3fdc343-a124-4a53-873a-8af36f8f682c', 'Jumman must pay his aunt a monthly allowance, or the transferred property will be returned to her immediately', true, 'bfc15239-1dae-4b19-bbc0-856f29fb0c48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20884d37-9cfc-4ccf-8b92-bc1fd1b6496d', 'The aunt must leave the village', false, 'bfc15239-1dae-4b19-bbc0-856f29fb0c48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ffe9611-6a4c-47c7-b81b-6402e66f2148', 'Jumman is innocent', false, 'bfc15239-1dae-4b19-bbc0-856f29fb0c48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73d8cd21-466d-4f88-bee3-4c1dc344950e', 'The property must be sold', false, 'bfc15239-1dae-4b19-bbc0-856f29fb0c48');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ab19aef-0d17-4a3f-bed0-8e809761cb41', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'How did Algu''s fair judgment affect his friendship with Jumman?', 'Jumman harbored deep resentment against Algu, awaiting an opportunity to take revenge.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c178bfc-5bd9-473e-9b70-30d814f3dca9', 'The bond of friendship was broken; Jumman felt betrayed and saw Algu as his bitter enemy, seeking revenge', true, '2ab19aef-0d17-4a3f-bed0-8e809761cb41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('813e1277-c983-40d9-942f-5121aa283c2d', 'They became even closer friends', false, '2ab19aef-0d17-4a3f-bed0-8e809761cb41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea5368e4-396d-43d3-b5cf-a0e8c716b92f', 'They started a business together', false, '2ab19aef-0d17-4a3f-bed0-8e809761cb41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c573e255-353c-4b97-af58-70fde44e5779', 'They moved to the city', false, '2ab19aef-0d17-4a3f-bed0-8e809761cb41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7df8ee41-f765-4299-814b-d151446c3ce1', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'To whom did Algu sell his fine surviving bullock on the promise of payment within a month?', 'Algu sold his bullock to Samjhu Sahu, who used it to transport goods between the village and town.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac160edc-9691-464a-b874-3555a6524267', 'Samjhu Sahu (a village cart driver)', true, '7df8ee41-f765-4299-814b-d151446c3ce1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f509170-8a1b-4010-bc44-9c046d3e4ff0', 'Jumman Shaikh', false, '7df8ee41-f765-4299-814b-d151446c3ce1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc37ad76-d3e1-4dfe-b4c4-8df544711eaf', 'The village priest', false, '7df8ee41-f765-4299-814b-d151446c3ce1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e60bc84f-d742-4aa4-8898-f8535b9aa56a', 'A merchant in town', false, '7df8ee41-f765-4299-814b-d151446c3ce1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b1e2764-3efd-46c2-a4d2-11b707c082f9', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'Why did the bullock die within a month of being purchased by Samjhu Sahu?', 'Cruel overworking and severe malnutrition caused the exhausted beast to collapse and die on the road.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1435028-624a-473a-b415-e9ccfb4377b6', 'Sahu overworked the poor animal with multiple daily trips, gave it little water and only dry straw/fodder to eat', true, '6b1e2764-3efd-46c2-a4d2-11b707c082f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3852306e-fa6c-4af7-893c-c38ffbb5b7a9', 'It fell into a deep river', false, '6b1e2764-3efd-46c2-a4d2-11b707c082f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e95f802-ec85-4018-a518-987d2139e59a', 'It was bitten by a snake', false, '6b1e2764-3efd-46c2-a4d2-11b707c082f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('002eb019-aa5a-43a6-80ce-4a6ee7cf9e79', 'It was poisoned', false, '6b1e2764-3efd-46c2-a4d2-11b707c082f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d34bf80a-4f18-44f2-8ef2-a58f7797666a', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'Whom did Samjhu Sahu nominate as Head Panch when Algu took the unpaid bullock case to the panchayat?', 'Sahu cunningly chose Jumman, expecting him to deliver a revenge verdict against Algu.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e37ab452-3c05-4937-8a42-3ce03dc731c7', 'Jumman Shaikh (Algu''s estranged enemy)', true, 'd34bf80a-4f18-44f2-8ef2-a58f7797666a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ef066ec-be91-415a-989f-580fcc83cdb4', 'The village headman', false, 'd34bf80a-4f18-44f2-8ef2-a58f7797666a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('669be066-555a-4ed2-a2c0-a1107195d38c', 'The old aunt', false, 'd34bf80a-4f18-44f2-8ef2-a58f7797666a');
