INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1663f876-659b-49f2-8092-d3137e47220c', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'In the supplementary chapter ''The Wonder Called Sleep'', what happens to our body temperature and blood pressure during deep sleep?', 'During deep somatic sleep, metabolic basal rate drops, reducing muscular tone, body temperature, and arterial pressure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e1a4b36-2adb-44fb-9f5b-a4d0757afec7', 'Body temperature falls and blood pressure drops as muscles relax completely', true, '1663f876-659b-49f2-8092-d3137e47220c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4c8928e-9559-4cd2-8b87-4fde1c7a6778', 'Body temperature rises to boiling point', false, '1663f876-659b-49f2-8092-d3137e47220c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2452e07-390d-4f25-bfd8-c8a5adf4449b', 'Blood pressure doubles', false, '1663f876-659b-49f2-8092-d3137e47220c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6f84949-e622-469b-b509-a072e6f60d52', 'The heart stops beating', false, '1663f876-659b-49f2-8092-d3137e47220c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9cdab046-99d7-4dd3-ba5c-72c95cab5061', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What profound realization came over Jumman Shaikh the moment he sat on the seat of the Head Panch?', 'The solemn office of Sarpanch awakened Jumman''s conscience, transcending personal grudge to embrace immaculate justice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4d97347-603e-4768-b1c5-1de1ea56aabb', 'He felt the supreme gravity and sanctity of justice; as a Panch, he represented divine truth above all personal enmity or friendship', true, '9cdab046-99d7-4dd3-ba5c-72c95cab5061');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9b73191-a348-4baf-b23e-16c927cc8099', 'He decided to take sweet revenge on Algu', false, '9cdab046-99d7-4dd3-ba5c-72c95cab5061');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96f48ba7-19c9-46d0-a00d-b25f9cdf4c80', 'He wanted to punish everyone', false, '9cdab046-99d7-4dd3-ba5c-72c95cab5061');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e717397-671a-4bfd-98bc-ed0b020e79b0', 'He wanted to run away', false, '9cdab046-99d7-4dd3-ba5c-72c95cab5061');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e27431a1-2b99-4813-a952-45ceba8f02b0', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What verdict did Head Panch Jumman deliver in the dispute between Algu and Samjhu Sahu?', 'Jumman ruled impartially: since the bullock was healthy at purchase, Sahu was legally and morally obligated to pay the full price.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5827f9f5-e281-4e38-be1d-e74f33040dc6', 'Samjhu Sahu must pay Algu the full price of the bullock, because the bullock suffered from no disability when sold and died solely due to Sahu''s ill-treatment and neglect', true, 'e27431a1-2b99-4813-a952-45ceba8f02b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b48355e-6a54-4f82-b3b1-6b3969b7d0b1', 'Algu must pay a fine to Sahu', false, 'e27431a1-2b99-4813-a952-45ceba8f02b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0979250-11a8-4bf9-84eb-6abfc7c92651', 'Both must go to jail', false, 'e27431a1-2b99-4813-a952-45ceba8f02b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa5ff493-fd1b-459e-81ea-a0e096d6204c', 'The money should be given to the panchayat', false, 'e27431a1-2b99-4813-a952-45ceba8f02b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('152e3778-8f1f-459d-8b83-189c82667a7b', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What did Algu and Jumman do after the verdict was pronounced?', 'The righteous judgment reconciled the two friends, restoring their mutual respect and sacred bond.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bed1881c-51f8-449e-82a3-ee997a5859a6', 'Algu wept with joy shouting ''Victory to the Panchayat!'', and both friends embraced each other, washing away all misunderstandings with tears', true, '152e3778-8f1f-459d-8b83-189c82667a7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bf78a6c-f779-4b5f-b512-f28d334b1143', 'They had a fist fight', false, '152e3778-8f1f-459d-8b83-189c82667a7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6056d262-76d0-405d-b9da-01b65f3523e0', 'They left the village forever', false, '152e3778-8f1f-459d-8b83-189c82667a7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fdd7c3e-d646-4863-be94-3a8bfbbdb85f', 'They refused to speak', false, '152e3778-8f1f-459d-8b83-189c82667a7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed6c3e04-dfba-4771-a9f4-0a5baddef42b', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What is the core moral and philosophical message of Premchand''s ''Fair Play''?', 'The story immortalizes the principle that judicial duty demands immaculate neutrality and allegiance to truth alone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1219d4ac-16fa-4988-bf85-e996ab0f69fe', 'Justice transcends all personal relationships, friendships, and enmities; when seated in judgment, one is the voice of God and must remain strictly impartial', true, 'ed6c3e04-dfba-4771-a9f4-0a5baddef42b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e32e971-8484-43d3-8a70-2f4c09823ff0', 'Friends should never lend money', false, 'ed6c3e04-dfba-4771-a9f4-0a5baddef42b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f725726a-8a32-4795-b6b5-6387f861c074', 'Bullocks should not be sold', false, 'ed6c3e04-dfba-4771-a9f4-0a5baddef42b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52893e2f-8929-47d6-be43-aad3aca8277d', 'Panchayats should be avoided', false, 'ed6c3e04-dfba-4771-a9f4-0a5baddef42b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49e0ec4a-8f41-415d-87ae-fb7a24b776a8', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'In ''The Wonder Called Sleep'', why is sleep called an ''unconscious state of rest'' and a miraculous wonder?', 'Sleep is biological restorative maintenance, facilitating neurocellular recovery and memory consolidation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('093b8105-1d21-4476-9b9e-67729c425c4d', 'It recharges and heals our fatigued body and mind, restoring full vigor, mental clarity, and somatic energy for the next day''s activities', true, '49e0ec4a-8f41-415d-87ae-fb7a24b776a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8bdaee8-b5c0-4aa3-9c05-8d90a3e48a4f', 'It makes humans fly in reality', false, '49e0ec4a-8f41-415d-87ae-fb7a24b776a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ce0b134-771d-488f-81dd-60d2c3a18de6', 'It stops aging permanently', false, '49e0ec4a-8f41-415d-87ae-fb7a24b776a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d42b503-2537-47a0-a5b7-e30f0f941293', 'It erases all human memories', false, '49e0ec4a-8f41-415d-87ae-fb7a24b776a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('753c5eeb-8961-4ae6-b0c1-a517123b883b', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What is a ''Dream'' according to the scientific explanation in ''The Wonder Called Sleep''?', 'Dreams are neuro-cognitive simulations during REM sleep aiding psychological equilibrium and creative problem solving.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4672ce3a-45b0-42ab-8ae1-b8d263dabec7', 'An active state of mind during sleep where the brain processes subconscious thoughts, emotions, and daily memories, sometimes revealing solutions to problems', true, '753c5eeb-8961-4ae6-b0c1-a517123b883b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('063c18d7-9c52-47e3-96bd-e247e58d72a3', 'A message from aliens', false, '753c5eeb-8961-4ae6-b0c1-a517123b883b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('435c1986-b0ae-4cd5-9942-c39afffb6724', 'A magical vision of the past', false, '753c5eeb-8961-4ae6-b0c1-a517123b883b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53e445ce-605d-481a-8852-68d012fc8660', 'A disease of the brain', false, '753c5eeb-8961-4ae6-b0c1-a517123b883b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56726266-d2e9-4c32-bc9b-48da01f048da', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'Why can dreams NEVER predict the future?', 'NCERT clarifies that while dreams process subjective memory traces, they possess no supernatural predictive validity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c2b2037-fe8f-4718-a385-0fc530e319aa', 'Dreams are merely internal neural processing of our own past experiences, subconscious desires, and fears, having no magical psychic power to foretell future events', true, '56726266-d2e9-4c32-bc9b-48da01f048da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c3f106c-043e-4289-ad30-2a302af25d91', 'Because dreams only last 1 second', false, '56726266-d2e9-4c32-bc9b-48da01f048da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ababc20-2906-4f34-8fa2-8ce69d345176', 'Because future is written in stone', false, '56726266-d2e9-4c32-bc9b-48da01f048da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('030cd2d7-0971-40f3-a321-d3d4586a5865', 'Because sleep blocks the future', false, '56726266-d2e9-4c32-bc9b-48da01f048da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b3351c3-41fb-48c3-ae0a-4f7962cf0880', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What poetic phrase did Edward Thomas use to describe sleep in his famous poem ''Lights Out''?', 'Thomas portrays sleep as an enigmatic boundless forest into which all travelers, ambition, and passions inevitably descend.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d244fe2-8888-43b6-a38b-ea21447c6f57', 'The unfathomable deep forest where all human paths must lose their way', true, '7b3351c3-41fb-48c3-ae0a-4f7962cf0880');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f174c8a9-afb8-4295-82b4-7d2a2417fb18', 'A shining golden castle', false, '7b3351c3-41fb-48c3-ae0a-4f7962cf0880');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44ee12da-9c01-40d7-982f-ee5889ae6617', 'A stormy ocean', false, '7b3351c3-41fb-48c3-ae0a-4f7962cf0880');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b653786-d51b-4279-ac5a-c90a253abf79', 'A dark prison cell', false, '7b3351c3-41fb-48c3-ae0a-4f7962cf0880');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca9d3bdf-687e-494d-9c65-1c7eb83a2dcd', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What does the idiom ''to swallow insults'' mean in the context of the aunt enduring mistreatment?', '''To swallow insults'' denotes stoically absorbing verbal humiliation without outward resistance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8577ffcd-d3f6-4281-af06-e67e11e42cb9', 'To tolerate humiliation, abuse, or offensive remarks quietly without protesting or retaliating', true, 'ca9d3bdf-687e-494d-9c65-1c7eb83a2dcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fc35c3f-65b0-4c6d-97ef-ecdacc451a1b', 'To eat poisonous food', false, 'ca9d3bdf-687e-494d-9c65-1c7eb83a2dcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73f0b8b3-4d2c-4b51-a061-5d5042a92a2f', 'To speak very loudly', false, 'ca9d3bdf-687e-494d-9c65-1c7eb83a2dcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1db16a60-dc51-4cc0-90cc-66b519eadb87', 'To laugh at someone', false, 'ca9d3bdf-687e-494d-9c65-1c7eb83a2dcd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76ef3907-fd9d-49e6-a601-1792460b4042', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'Why did Algu''s heart sink when Samjhu Sahu nominated Jumman as the Head Panch?', 'Knowing their severed friendship, Algu dreaded that personal enmity would bias Jumman''s judgment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cce42026-2b89-4056-967c-94fcc9d75457', 'Algu feared that Jumman would use this judicial opportunity to exact vengeance and rule against him maliciously', true, '76ef3907-fd9d-49e6-a601-1792460b4042');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7c71e95-9fe2-4a0b-a463-cb3714535ae6', 'Algu didn''t like Jumman''s clothes', false, '76ef3907-fd9d-49e6-a601-1792460b4042');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce5ff618-a18a-4231-8dfb-32d68bc70dc6', 'Algu wanted to go home early', false, '76ef3907-fd9d-49e6-a601-1792460b4042');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1405c644-731b-490a-a45b-7d580cf43312', 'Algu had forgotten the facts of the case', false, '76ef3907-fd9d-49e6-a601-1792460b4042');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d32b8762-cd2e-488e-a1e7-740180de6fa7', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What is the meaning of the word ''Panchayat'' in rural Indian governance?', 'Panchayat is a traditional democratic council of five elders deliberating community disputes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faa92d5f-7869-4c85-b888-bb17f3eeb4ad', 'A traditional council of village elders gathered to resolve disputes and administer local justice and welfare', true, 'd32b8762-cd2e-488e-a1e7-740180de6fa7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91aa2219-8a7a-4c58-bbdf-e08f0f5892d9', 'A big market fair', false, 'd32b8762-cd2e-488e-a1e7-740180de6fa7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71a5f1ce-5262-44cd-a4b3-8add3d442582', 'A wrestling match', false, 'd32b8762-cd2e-488e-a1e7-740180de6fa7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb576044-d6ad-462b-bf8d-0e9acff46b1e', 'A religious festival', false, 'd32b8762-cd2e-488e-a1e7-740180de6fa7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6928feba-091a-40ad-a8b7-fd134109f8b4', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What physiological change occurs in the brain when a sleeping person transitions into the Rapid Eye Movement (REM) dream stage?', 'REM sleep exhibits paradoxical cortical activation and rapid ocular oscillations alongside somatic motor inhibition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe42bfb6-5f6d-4835-a855-01edaecd5f18', 'Brain activity increases, eyes move rapidly behind closed eyelids, while large skeletal muscles remain temporarily paralyzed (atonic)', true, '6928feba-091a-40ad-a8b7-fd134109f8b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b207bd3-e869-4fd7-827a-6e0eb74f8b79', 'The brain stops working completely', false, '6928feba-091a-40ad-a8b7-fd134109f8b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97b23774-831a-4162-8a78-f598fe8a9e06', 'The body starts walking automatically', false, '6928feba-091a-40ad-a8b7-fd134109f8b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e854d8c-6f77-4bd7-b22c-de563ce5958d', 'The person speaks fluent Greek', false, '6928feba-091a-40ad-a8b7-fd134109f8b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('259975f5-cea3-4ca2-a664-5ffbd875d73f', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What does the expression ''a tight spot'' mean when Algu found himself in trouble after the death of his bullock?', '''In a tight spot'' is an idiomatic metaphor signifying financial or personal dilemma.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('160fe876-b770-4d68-b38f-060b71e5b9bb', 'A difficult, perplexing, or precarious situation', true, '259975f5-cea3-4ca2-a664-5ffbd875d73f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09223fcc-d15f-488f-8e3b-f00acc238ffa', 'A narrow physical hallway', false, '259975f5-cea3-4ca2-a664-5ffbd875d73f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5a3e7a1-92a9-4157-92bf-ca5a8ba421d0', 'A small shoe', false, '259975f5-cea3-4ca2-a664-5ffbd875d73f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38a2355c-0574-4cc6-9034-376694c75aef', 'A warm blanket', false, '259975f5-cea3-4ca2-a664-5ffbd875d73f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f09ed40-c582-493a-89cf-15d1b26d5a1d', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'Who is the legendary author of the original Hindi classic story ''Panch Parmeshwar'', translated into English as ''Fair Play''?', 'Munshi Premchand penned the iconic masterpiece ''पंच परमेश्वर'' (Panch Parmeshwar) portraying rural judicial ethics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b928f05-6f7a-40b9-92ea-6bce972130c0', 'Munshi Premchand (Dhanpat Rai Shrivastava)', true, '7f09ed40-c582-493a-89cf-15d1b26d5a1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a334e5b0-70b7-464d-9ecf-a7ff7aeb1aa6', 'Rabindranath Tagore', false, '7f09ed40-c582-493a-89cf-15d1b26d5a1d');
