INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2a61ec3-e714-46f2-b12b-e26554259138', 'Mulk Raj Anand', false, '7f09ed40-c582-493a-89cf-15d1b26d5a1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95125433-a825-469a-be3e-e50c307f28bc', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'Why did the villagers cheer ''Victory to the Panchayat! This is justice!'' at the end of both trials?', 'The community celebrated the incorruptibility and divine moral authority of the village judicial institution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d6cf6a4-1e92-4d16-92dc-c068e77b0a7f', 'Because in both cases, the Panch proved that truth and justice prevail above personal biases, friendships, and vendettas', true, '95125433-a825-469a-be3e-e50c307f28bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a171954-0ace-49b6-82bd-280b5bbf3f7d', 'Because the trial was very short', false, '95125433-a825-469a-be3e-e50c307f28bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f27391b-74e5-4379-acdf-0595db804c87', 'Because they received free sweets', false, '95125433-a825-469a-be3e-e50c307f28bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee9ccbda-8377-4cb0-a980-260302f24615', 'Because it started raining', false, '95125433-a825-469a-be3e-e50c307f28bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23d8a170-3a5b-42fb-8358-7c8945124ab2', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'In ''The Wonder Called Sleep'', why is sleep compared to an enchanting ''haven'' or ''sweet land''?', 'Sleep serves as a biological and emotional oasis restoring physical equilibrium away from conscious distress.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('771bbd35-cdec-459d-acdb-b6b9afaf7e0f', 'Because it provides a tranquil sanctuary where all sorrows, fatigue, worries, and pain are forgotten in peaceful rest', true, '23d8a170-3a5b-42fb-8358-7c8945124ab2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4754371-f003-4b16-98e3-54df99dc5f88', 'Because you can buy candy there', false, '23d8a170-3a5b-42fb-8358-7c8945124ab2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51b3b21b-e539-45f6-bb4c-1d726626ba08', 'Because nobody can wake you up', false, '23d8a170-3a5b-42fb-8358-7c8945124ab2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97c1fea7-8777-4919-a166-7082e7534854', 'Because it has golden rivers', false, '23d8a170-3a5b-42fb-8358-7c8945124ab2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72e4aa20-5866-4724-9095-6813b4803193', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf769b46-4e0a-47ee-abbd-169a476ce748', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '72e4aa20-5866-4724-9095-6813b4803193');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09d7ab69-e912-4d25-9489-13650f93e0b3', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '72e4aa20-5866-4724-9095-6813b4803193');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea9a6d9d-cedd-49af-be28-da34d9950ba4', '(A) is true, but (R) is false.', false, '72e4aa20-5866-4724-9095-6813b4803193');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a1ad49b-2940-49ea-b563-9525acc460ab', '(A) is false, but (R) is true.', false, '72e4aa20-5866-4724-9095-6813b4803193');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c0b33b3-90df-4569-a2fc-61c7fb39c03e', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Spot the IMPOSTER in the following group of character descriptions from ''Fair Play'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ef0b346-990c-4941-9f38-d2a2635fc0a9', 'Jumman Shaikh - Nephew of the old aunt', false, '1c0b33b3-90df-4569-a2fc-61c7fb39c03e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aa94534-af9a-45bc-bb27-314cfd8b568a', 'Algu Chowdhry - Head Panch in the aunt''s case', false, '1c0b33b3-90df-4569-a2fc-61c7fb39c03e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57649bff-0109-4481-90c2-249b187bb5fd', 'Samjhu Sahu - Village cart driver who bought the bullock', false, '1c0b33b3-90df-4569-a2fc-61c7fb39c03e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('756ea91a-d75c-4dbb-b753-cf055d089a86', 'Kariman - The kind daughter who gave money to the aunt', true, '1c0b33b3-90df-4569-a2fc-61c7fb39c03e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8fcf30c8-da97-4654-97e5-3247beabf439', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Analyze the dramatic irony in Samjhu Sahu''s decision to nominate Jumman Shaikh as the Head Panch in his dispute with Algu:', 'Dramatic irony arises when Sahu''s calculated attempt to exploit a personal feud collapses before the sanctity of judicial truth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4aab444-ea5c-4dfe-b5c0-322f69d5e9bd', 'Sahu expected Jumman''s enmity with Algu to guarantee a biased ruling in his favor, but the sacred seat transformed Jumman into an impartial judge who ruled against Sahu', true, '8fcf30c8-da97-4654-97e5-3247beabf439');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79188d75-ea8f-4122-8f27-c9ded7854e83', 'Sahu wanted Jumman to lose money', false, '8fcf30c8-da97-4654-97e5-3247beabf439');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e92e4341-a0e7-4f1e-ba3d-a71b86dce22a', 'Sahu knew Jumman was Algu''s brother', false, '8fcf30c8-da97-4654-97e5-3247beabf439');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93ba3221-bc35-4150-8bf3-8de942c85e7d', 'Sahu wanted to pay double money', false, '8fcf30c8-da97-4654-97e5-3247beabf439');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('959dfba5-5be0-4bfa-9dbf-86ff8af4ec4a', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Match Column I (Characters / Concepts) with Column II (Key Roles / Quotes):
(a) The Old Aunt     -> (i) ''God lives in the heart of the Panch''
(b) Jumman Shaikh    -> (ii) ''Algu, since you gave verdict against me, I became your enemy''
(c) Samjhu Sahu      -> (iii) Cruelly overworked the bullock to death
(d) Edward Thomas    -> (iv) Poet of ''Lights Out'' describing the deep forest of sleep', 'Aunt = ''God lives in the Panch''; Jumman = ''I became your enemy''; Sahu = overworked bullock; Edward Thomas = ''Lights Out''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6482c365-8e6e-42d4-ab61-8045c4378597', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '959dfba5-5be0-4bfa-9dbf-86ff8af4ec4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a81e10fe-b220-4420-91d5-ea5b1d325afc', 'a-(ii), b-(i), c-(iii), d-(iv)', false, '959dfba5-5be0-4bfa-9dbf-86ff8af4ec4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1268935-7cad-4c21-9357-e5fa32902243', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '959dfba5-5be0-4bfa-9dbf-86ff8af4ec4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0c5f0b2-c5d7-4fdd-a2bc-c91936bb55c6', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '959dfba5-5be0-4bfa-9dbf-86ff8af4ec4a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5268105c-29bd-4bea-8326-65573467bc5e', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Read the statements regarding ''The Wonder Called Sleep'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72f35b11-9e31-418a-b1c8-fd7b559a551d', 'Statements 2 and 3 only', true, '5268105c-29bd-4bea-8326-65573467bc5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e28701c-cad3-44b2-989e-e584310bae12', 'Statements 1 and 2 only', false, '5268105c-29bd-4bea-8326-65573467bc5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8b63422-8412-4e78-ab88-31ea2cf847ca', 'Statements 1 and 3 only', false, '5268105c-29bd-4bea-8326-65573467bc5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('610d3b83-5876-4f1c-97c7-8f52b2875bc1', 'All Statements 1, 2, and 3', false, '5268105c-29bd-4bea-8326-65573467bc5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5f0c088-a9df-4d43-babc-f6f45105f4d6', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'What is the grammatical voice and structure of the sentence: ''A monthly allowance must be paid to the aunt by Jumman.''?', 'The modal passive construction ''must be + V3'' places the patient (monthly allowance) in subject position.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fa871f1-4f79-46d1-ab76-b7a22dd4d475', 'Passive Voice (with modal auxiliary ''must be'' + past participle ''paid'')', true, 'b5f0c088-a9df-4d43-babc-f6f45105f4d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da6bc60e-ea97-468a-b12c-1fd2a0f819b5', 'Active Voice', false, 'b5f0c088-a9df-4d43-babc-f6f45105f4d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('126e4e4b-36c8-47e4-9694-0e332a1e8e9f', 'Indirect Speech', false, 'b5f0c088-a9df-4d43-babc-f6f45105f4d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20eeff1a-eaab-4948-8ef3-d123fc26f55e', 'Imperative Sentence', false, 'b5f0c088-a9df-4d43-babc-f6f45105f4d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7dbd9a81-f5a1-49a0-bd30-8e5e259747ae', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Identify the figure of speech in Edward Thomas''s lines from ''Lights Out'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e22244cc-b734-4afd-90a8-facf3d89842a', 'Extended Metaphor (comparing sleep to an all-encompassing dark impenetrable forest)', true, '7dbd9a81-f5a1-49a0-bd30-8e5e259747ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ccf9876-fc6b-45dd-8c7c-59902845875d', 'Simile', false, '7dbd9a81-f5a1-49a0-bd30-8e5e259747ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5255298-da43-4780-818e-03fcb58710df', 'Onomatopoeia', false, '7dbd9a81-f5a1-49a0-bd30-8e5e259747ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03bd1fbb-944f-4a82-88e9-72ec60bd347c', 'Hyperbole', false, '7dbd9a81-f5a1-49a0-bd30-8e5e259747ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0e353f0-3346-4297-81e7-3f6e910c2d5c', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Why does the narrator state: ''The Panch has neither friend nor enemy''?', 'Judicial impartiality requires that judges strip away personal ties when sitting on the seat of truth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e586740-730d-45f5-8480-128648a49fdb', 'Because judicial office demands complete transcendence of personal ego, prejudice, and private affection to serve absolute cosmic justice', true, 'c0e353f0-3346-4297-81e7-3f6e910c2d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6ae5f65-13b4-457d-98e8-c112b0dc4ee8', 'Because Panchs are not allowed to talk to villagers', false, 'c0e353f0-3346-4297-81e7-3f6e910c2d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dbc230d-7a90-45bd-a98a-b1cdb8ab6bfd', 'Because Panchs live outside the village', false, 'c0e353f0-3346-4297-81e7-3f6e910c2d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13400623-906a-497f-8739-c3dac922a457', 'Because Panchs have no family', false, 'c0e353f0-3346-4297-81e7-3f6e910c2d5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07b6a3c0-a5e9-4063-b21d-3dba5d3f920e', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'What is the meaning of the archaic/formal phrasal verb ''to make up one''s mind'' as used by the aunt before approaching the village elders?', '''To make up one''s mind'' is an English idiom meaning to resolve or decide firmly upon a course of action.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbd8ea47-2bf6-415d-a5ae-cc720436653d', 'To reach a firm and decisive decision', true, '07b6a3c0-a5e9-4063-b21d-3dba5d3f920e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16a10b6a-58e9-4b6f-a619-74f5dda645d8', 'To forget everything', false, '07b6a3c0-a5e9-4063-b21d-3dba5d3f920e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcd8df41-c1e4-40e9-b04f-f06525e8e3a0', 'To change thoughts randomly', false, '07b6a3c0-a5e9-4063-b21d-3dba5d3f920e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('740417ba-b1d5-46a9-8569-2e7a19507634', 'To clean one''s face', false, '07b6a3c0-a5e9-4063-b21d-3dba5d3f920e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8dd75b2d-36b1-4d3e-9027-33069071cae7', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'How does Premchand use the bullock''s tragic death to critique commercial greed and animal cruelty in rural society?', 'Premchand exposes unbridled commercial exploitation that sacrifices sentient lives for mercenary profit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48d9d89e-95e8-4353-b25e-f714a8f28004', 'Through Sahu''s ruthless exploitation of the defenseless animal for quick profit without food or rest, illustrating how avarice degrades humanity', true, '8dd75b2d-36b1-4d3e-9027-33069071cae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8487be0d-0d2e-4380-8459-db1f7b38b262', 'By showing that bullocks should not pull carts', false, '8dd75b2d-36b1-4d3e-9027-33069071cae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbdc81fd-cd38-48dd-ae64-8887274a673f', 'By arguing that all carts should be banned', false, '8dd75b2d-36b1-4d3e-9027-33069071cae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5782d8d-7576-409b-a93a-3902cf94ab19', 'By showing that traders are always poor', false, '8dd75b2d-36b1-4d3e-9027-33069071cae7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34dcf360-296a-40b7-b2ac-1d6a7d377940', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'In ''The Wonder Called Sleep'', what happens to our conscious sensory awareness when external stimuli (such as an alarm clock ringing or sunlight hitting eyelids) occur?', 'Subconscious sensory incorporation (e.g. dreaming of a church bell when the alarm rings) occurs before full cortical awakening.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a9480a2-f8b0-428a-89ef-e96aaa1ab042', 'Our brain integrates the sensory stimulus into our ongoing dream narrative until neural arousal crosses the waking threshold', true, '34dcf360-296a-40b7-b2ac-1d6a7d377940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bee1478e-e690-41d7-a519-5ea04ff4f9e8', 'The brain explodes', false, '34dcf360-296a-40b7-b2ac-1d6a7d377940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d21702b-8038-4cb4-8745-235e33c1e1c4', 'The person forgets who they are', false, '34dcf360-296a-40b7-b2ac-1d6a7d377940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72f6432d-5bb0-4f20-8c7e-2e7137d6e468', 'Sleep becomes permanent', false, '34dcf360-296a-40b7-b2ac-1d6a7d377940');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e0fa327-6ee1-46c5-8967-8c3996623e84', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'What timeless ethical synthesis emerges when comparing the judicial triumphs of ''Fair Play'' with modern democratic jurisprudence?', 'Both traditional panchayats and modern constitutional courts derive legitimacy from unwavering impartiality and adherence to natural justice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7785afab-45fc-4574-a7a1-680366dd427e', 'The Rule of Law and ethical integrity must always stand sovereign above individual power, friendship, caste, or wealth', true, '5e0fa327-6ee1-46c5-8967-8c3996623e84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d60ce80-63b8-437e-be12-062e4f8e3a0b', 'Friends should always protect each other even when guilty', false, '5e0fa327-6ee1-46c5-8967-8c3996623e84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9243703-7a4f-4e2a-963d-2c478bc19c54', 'Judges should take bribes', false, '5e0fa327-6ee1-46c5-8967-8c3996623e84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a1c9be2-506b-49d8-9687-fb68dea93c37', 'Panchayats should only favor rich traders', false, '5e0fa327-6ee1-46c5-8967-8c3996623e84');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf1cce5f-a446-4421-810b-35ced2058bc9', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What is the supreme legal and constitutional document of India, establishing the framework of government, fundamental rights, and duties?', 'The Constitution of India is the supreme law of the land, drafted by the Constituent Assembly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a1d5863-78ef-4d10-860f-e39e325c55f9', 'The Constitution of India', true, 'cf1cce5f-a446-4421-810b-35ced2058bc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1a592fb-8764-45bf-9fe9-711ce23e211d', 'The Indian Penal Code', false, 'cf1cce5f-a446-4421-810b-35ced2058bc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84182d70-372c-4ff0-a189-a38f1eb4ab84', 'The Magna Carta', false, 'cf1cce5f-a446-4421-810b-35ced2058bc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12f28a8a-5bfd-44a1-9c5e-3e0bd573b926', 'The Parliament Act', false, 'cf1cce5f-a446-4421-810b-35ced2058bc9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bce276d-4585-4f43-91a2-994a213dfe4d', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'Who is revered as the ''Chief Architect and Father of the Indian Constitution'' and served as the Chairman of the Drafting Committee?', 'Dr. B.R. Ambedkar chaired the Drafting Committee, synthesizing social justice into constitutional jurisprudence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db971fd6-c377-45ea-afd5-0db7a0e570c0', 'Dr. B.R. Ambedkar (Bhimrao Ramji Ambedkar)', true, '8bce276d-4585-4f43-91a2-994a213dfe4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1dbefe6-cb5c-444b-acb5-1e08545c819f', 'Dr. Rajendra Prasad', false, '8bce276d-4585-4f43-91a2-994a213dfe4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf01b9f5-3f44-41c4-a3f2-d12fb655ba1c', 'Jawaharlal Nehru', false, '8bce276d-4585-4f43-91a2-994a213dfe4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ee41d66-ace8-405c-a67b-15f12b5001e2', 'Sardar Vallabhbhai Patel', false, '8bce276d-4585-4f43-91a2-994a213dfe4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('728a4a7a-6ef7-424a-9ec5-a18e0aaf76e4', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'On which historic date did the Constitution of India come into full effect, celebrated annually as Republic Day across the country?', 'The Constitution came into force on 26 January 1950, commemorated every year as India''s Republic Day.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('493f378b-30b6-4f0b-88e3-450c04decf2c', '26th January 1950', true, '728a4a7a-6ef7-424a-9ec5-a18e0aaf76e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f75be06f-7392-4cff-b781-9bc72ca9fb65', '15th August 1947', false, '728a4a7a-6ef7-424a-9ec5-a18e0aaf76e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbbc8c32-35ee-4a7e-8d53-37c35b8f4d06', '26th November 1949', false, '728a4a7a-6ef7-424a-9ec5-a18e0aaf76e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2c3b2aa-b092-4fb6-905a-6d5e5112e068', '2nd October 1950', false, '728a4a7a-6ef7-424a-9ec5-a18e0aaf76e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ada7a5d9-9007-4eae-9a8d-b203b5c2d4ee', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'On which date was the Constitution of India officially ADOPTED by the Constituent Assembly, celebrated annually as ''Constitution Day'' (Samvidhan Divas)?', 'The Constituent Assembly adopted the Constitution on 26 November 1949, designated as Constitution Day.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1fcda2d-bdda-443e-bce6-b5ada12929ad', '26th November 1949', true, 'ada7a5d9-9007-4eae-9a8d-b203b5c2d4ee');
