INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6e1ff4c-a2fb-45e1-8fce-8adde0caecee', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'Who was the FIRST President of the Republic of India and also the President of the Constituent Assembly?', 'Dr. Rajendra Prasad presided over the Constituent Assembly and served as India''s first President from 1950 to 1962.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab0da567-30dc-4700-be6a-74b1a808d160', 'Dr. Rajendra Prasad', true, 'c6e1ff4c-a2fb-45e1-8fce-8adde0caecee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e89285a-7622-4e0b-b5cb-20bc33e833e1', 'Dr. S. Radhakrishnan', false, 'c6e1ff4c-a2fb-45e1-8fce-8adde0caecee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36205861-9c68-4ec2-bda4-fd6561bd2bc5', 'Dr. Zakir Husain', false, 'c6e1ff4c-a2fb-45e1-8fce-8adde0caecee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f074416-bbbc-4d23-9764-91aae3117376', 'C. Rajagopalachari', false, 'c6e1ff4c-a2fb-45e1-8fce-8adde0caecee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1dc41301-669b-4b0d-8e27-4b971bcbde52', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'Who is the FIRST citizen of India and the Supreme Commander of the Indian Armed Forces?', 'The President is the constitutional Head of State, First Citizen, and Supreme Commander of the Army, Navy, and Air Force.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c5e15ce-d66f-48e0-868e-0399103fbf21', 'The President of India', true, '1dc41301-669b-4b0d-8e27-4b971bcbde52');
