INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('547f10cc-981e-4ba4-895d-779b8203f31d', 'The Chief Justice of India', false, '1dc41301-669b-4b0d-8e27-4b971bcbde52');
