INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65e75eca-378c-4b2b-98a4-6188e49cc7ab', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'Who is the real executive Head of Government and leader of the Council of Ministers in India?', 'Under our parliamentary system, the Prime Minister is the de facto head of government leading the executive cabinet.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a59c4bd-b4eb-4a7a-8eae-8f85c785addf', 'The Prime Minister of India', true, '65e75eca-378c-4b2b-98a4-6188e49cc7ab');
