INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5b7af83-6479-4533-8e72-89d83325fd4a', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What are the two Houses of the Parliament of India (Bicameral Legislature)?', 'The Indian Parliament comprises the President and two Houses: Lok Sabha (Lower House) and Rajya Sabha (Upper House).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a3082bd-bb5c-4dc8-928d-7a1b450362c6', 'Lok Sabha (House of the People) and Rajya Sabha (Council of States)', true, 'c5b7af83-6479-4533-8e72-89d83325fd4a');
