INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47a20a2b-c41d-46a9-874a-af5963fbbbff', 'Senate and House of Representatives', false, 'c5b7af83-6479-4533-8e72-89d83325fd4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd95e822-ccf8-453f-915e-553eff01ec93', 'Supreme Court and High Court', false, 'c5b7af83-6479-4533-8e72-89d83325fd4a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a59427c8-4f1f-47cb-8740-dc427f6d96a1', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What is the minimum voting age for Indian citizens in general democratic elections under Universal Adult Suffrage?', 'Every Indian citizen aged 18 years or above possesses the constitutional fundamental right to vote without discrimination.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4530dce3-0463-443f-a5fc-2e1a907b0fe1', '18 years (lowered from 21 by 61st Constitutional Amendment in 1988)', true, 'a59427c8-4f1f-47cb-8740-dc427f6d96a1');
