INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0cb2330-eeb6-4e11-b28b-fb4b4297a832', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What is the highest judicial court of appeal in India, situated in New Delhi?', 'The Supreme Court of India is the apex judicial guardian and final interpreter of the Constitution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fbd61e0-96e5-4a2b-a278-6910e582e46d', 'Supreme Court of India (headed by the Chief Justice of India)', true, 'c0cb2330-eeb6-4e11-b28b-fb4b4297a832');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf77cb5e-306a-4585-9546-ea677d53e60c', 'High Court', false, 'c0cb2330-eeb6-4e11-b28b-fb4b4297a832');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dccc7a8-dc80-4897-b258-1c8bbefbe399', 'District Court', false, 'c0cb2330-eeb6-4e11-b28b-fb4b4297a832');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe2832cd-1796-4347-a4f5-4da9a846bcde', 'Panchayat Court', false, 'c0cb2330-eeb6-4e11-b28b-fb4b4297a832');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b1e7667-81e7-4b2b-8633-22acd5afd5df', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What opening introductory statement sets out the guiding ideals, philosophy, and principles of the Constitution of India?', 'The Preamble is the identity card and philosophical soul of the Indian Constitution, declaring India a Sovereign, Socialist, Secular, Democratic Republic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a74b654f-a7c2-42b6-bb6b-e1a51c99f68f', 'The Preamble (''WE, THE PEOPLE OF INDIA...'')', true, '0b1e7667-81e7-4b2b-8633-22acd5afd5df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9462a241-f017-42df-b322-526af7e0e44c', 'The Index', false, '0b1e7667-81e7-4b2b-8633-22acd5afd5df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3bdfb6d-d974-489a-9d44-664a472c1edd', 'The Appendix', false, '0b1e7667-81e7-4b2b-8633-22acd5afd5df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d2ea387-ae22-4a5c-a130-2dcee43eaba4', 'The First Schedule', false, '0b1e7667-81e7-4b2b-8633-22acd5afd5df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd8cf38a-edd7-423b-b82a-8e7d1101c60b', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What is the national motto of India inscribed below the State Emblem, taken from the ancient Mundaka Upanishad?', '''Satyameva Jayate'' (''Truth alone triumphs'') is the national motto inscribed in Devanagari script at the base of the national emblem.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cea9ea62-798e-491a-adf6-b4b026f0d319', '''Satyameva Jayate'' (Truth Alone Triumphs)', true, 'dd8cf38a-edd7-423b-b82a-8e7d1101c60b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b32aa95a-d529-4840-b2f7-9daa6015c9f1', '''Vande Mataram''', false, 'dd8cf38a-edd7-423b-b82a-8e7d1101c60b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('584d2f2c-fd72-4fc5-8066-082882c8ff3e', '''Jai Hind''', false, 'dd8cf38a-edd7-423b-b82a-8e7d1101c60b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3f11d88-1a3f-4092-b651-d0de604d5c20', '''Jan Gan Man''', false, 'dd8cf38a-edd7-423b-b82a-8e7d1101c60b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36daa77a-db4f-46d8-bb5c-fcd67d36e46b', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'How many Fundamental Rights are currently guaranteed to all Indian citizens under Part III of the Constitution?', 'There are 6 Fundamental Rights (the 7th, Right to Property, was converted to a legal right by the 44th Amendment in 1978).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ac8e15e-b7a6-4451-a083-0191da59df52', '6 Fundamental Rights (Right to Equality, Right to Freedom, Right against Exploitation, Right to Freedom of Religion, Cultural & Educational Rights, Right to Constitutional Remedies)', true, '36daa77a-db4f-46d8-bb5c-fcd67d36e46b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('335ac87f-4bc0-467d-8784-a76605c1898e', '7 Fundamental Rights', false, '36daa77a-db4f-46d8-bb5c-fcd67d36e46b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20732105-3bed-4869-a7a2-e9a79c037b16', '10 Fundamental Rights', false, '36daa77a-db4f-46d8-bb5c-fcd67d36e46b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a31312-9995-4af7-8989-8df2277f34e4', '5 Fundamental Rights', false, '36daa77a-db4f-46d8-bb5c-fcd67d36e46b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e02adad9-f4a8-4277-9ca6-12750b5662ac', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'Which Fundamental Right under Article 32 was famously called the ''Heart and Soul of the Constitution'' by Dr. B.R. Ambedkar?', 'Article 32 empowers the Supreme Court to issue prerogative writs to enforce fundamental rights, making rights truly enforceable.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e57363f-b6db-4354-aae7-be869ebb2903', 'Right to Constitutional Remedies (allowing citizens to approach Supreme Court via writs like Habeas Corpus, Mandamus)', true, 'e02adad9-f4a8-4277-9ca6-12750b5662ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('590d9db5-69e0-4532-9ac9-9c8bc890b36c', 'Right to Equality', false, 'e02adad9-f4a8-4277-9ca6-12750b5662ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f0f93a2-1bab-4c17-959f-c141a238642c', 'Right to Freedom of Speech', false, 'e02adad9-f4a8-4277-9ca6-12750b5662ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ebeb2da-270c-4618-9abe-3cfae82eed15', 'Right to Property', false, 'e02adad9-f4a8-4277-9ca6-12750b5662ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('084cfcea-4a1f-4b8b-a6f8-2bf1fa5ad2a8', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'How many Fundamental Duties are prescribed for Indian citizens under Article 51A (Part IVA) of the Constitution?', 'Originally 10 duties recommended by Swaran Singh Committee were added in 1976; the 11th duty on education was added in 2002.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('239c2e24-d68e-4d19-a3fd-6346b06cc75a', '11 Fundamental Duties (added by 42nd & 86th Amendments)', true, '084cfcea-4a1f-4b8b-a6f8-2bf1fa5ad2a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('874ca8fe-6fcf-4f46-bbc0-32633b330ade', '10 Fundamental Duties', false, '084cfcea-4a1f-4b8b-a6f8-2bf1fa5ad2a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a1c4dc5-20fa-480a-be5d-64ed81d243c3', '8 Fundamental Duties', false, '084cfcea-4a1f-4b8b-a6f8-2bf1fa5ad2a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb082574-3908-47c3-86e8-02dfb063ed07', '12 Fundamental Duties', false, '084cfcea-4a1f-4b8b-a6f8-2bf1fa5ad2a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd441930-9d48-47ad-9d73-df2b34bc9393', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the normal term of office for elected Members of the Lok Sabha (Lower House)?', 'Lok Sabha members are elected directly by the people for a standard 5-year term unless dissolved earlier.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('836e7564-60e6-4daa-bace-841d5f22e4d2', '5 years', true, 'fd441930-9d48-47ad-9d73-df2b34bc9393');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bec9fbd-c425-4cd3-8f92-72edc7202c6a', '6 years', false, 'fd441930-9d48-47ad-9d73-df2b34bc9393');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('643b6a5c-07fd-4772-a473-acc0fe81cd27', '4 years', false, 'fd441930-9d48-47ad-9d73-df2b34bc9393');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9743544-37ef-4075-bdd0-55f20bdc1361', 'Permanent (no term limit)', false, 'fd441930-9d48-47ad-9d73-df2b34bc9393');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9efae887-d5fc-4e01-99d6-f52808b6edda', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the permanent nature and term of members in the Rajya Sabha (Upper House)?', 'Rajya Sabha is a continuous permanent federal chamber where 1/3rd of members retire biennially after 6-year terms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5870face-7ed2-40fa-a604-ee61e934690a', 'It is a permanent House never subject to total dissolution; members serve 6-year terms with one-third retiring every 2 years', true, '9efae887-d5fc-4e01-99d6-f52808b6edda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f965d46-3c4a-4e86-ace0-55b309aa3cf8', 'It dissolves every 5 years', false, '9efae887-d5fc-4e01-99d6-f52808b6edda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2605001-bbca-4dd2-96fa-6df0f715fe60', 'Members serve for life', false, '9efae887-d5fc-4e01-99d6-f52808b6edda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e9b7f5d-8f01-4e58-bf9f-f1e9d4575662', 'It dissolves every year', false, '9efae887-d5fc-4e01-99d6-f52808b6edda');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('972f7448-9398-46a4-88d2-dd04f8a19205', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'Who is the ex-officio Chairman of the Rajya Sabha in India?', 'Under Article 64, the Vice-President of India serves as the constitutional ex-officio Chairman of the Rajya Sabha.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cee2ef2a-14dc-4197-b0a3-14f85e99a58b', 'The Vice-President of India', true, '972f7448-9398-46a4-88d2-dd04f8a19205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66782584-baba-446e-b6cd-9b66aed2bcc3', 'The Prime Minister', false, '972f7448-9398-46a4-88d2-dd04f8a19205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1b63a43-7acf-4f9e-b607-4bbcf1356569', 'The Speaker of Lok Sabha', false, '972f7448-9398-46a4-88d2-dd04f8a19205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('096faf97-075b-4dae-b03b-81e3f41bcfd7', 'The Chief Justice', false, '972f7448-9398-46a4-88d2-dd04f8a19205');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a78e3d0-9eda-4ada-b876-745c2b2ba48b', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the Three-Tier system of rural local self-government in India called?', 'Constitutionalized by the 73rd Amendment (1992), Panchayati Raj establishes a 3-tier democratic decentralization system.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f451811c-263c-4282-9b62-c1f76f3a16c2', 'Panchayati Raj (Gram Panchayat at village level, Panchayat Samiti at block level, Zilla Parishad at district level)', true, '7a78e3d0-9eda-4ada-b876-745c2b2ba48b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8c89611-d17c-426b-9c9b-ec4af0c1bfa9', 'Municipal Corporation', false, '7a78e3d0-9eda-4ada-b876-745c2b2ba48b');
