INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99dd12df-f138-4c96-b1da-beb359671a49', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'Which Indian state was the first to establish the Panchayati Raj system on 2nd October 1959 at Nagaur?', 'Prime Minister Jawaharlal Nehru inaugurated democratic Panchayati Raj in Nagaur district, Rajasthan on Gandhi Jayanti in 1959.', NOW()) ON CONFLICT DO NOTHING;
