INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4699355-27c3-4913-8b7d-dbb0a11a46c7', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What constitutional body conducts free, fair, and impartial democratic elections for Parliament, State Assemblies, President, and Vice-President in India?', 'The Election Commission of India (Article 324) is an autonomous constitutional watchdog conducting national and state elections.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07a8ff00-5523-4abb-8152-9d5da46cc79c', 'Election Commission of India (ECI - Article 324)', true, 'f4699355-27c3-4913-8b7d-dbb0a11a46c7');
