INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b1c1f14-e358-4631-9c10-1b2e08d33f44', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'Who was the FIRST Chief Election Commissioner of Independent India who supervised India''s first historic General Elections in 1951–52?', 'Sukumar Sen organized India''s gigantic first democratic general election of 173 million voters across remote geographies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4eb9736a-b7d5-4dc5-a555-8802777ee3fd', 'Sukumar Sen', true, '2b1c1f14-e358-4631-9c10-1b2e08d33f44');
