INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95909ea8-ea92-4e99-8340-4e0fb5456184', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the maximum strength of Lok Sabha and Rajya Sabha sanctioned by the Constitution of India?', 'Maximum sanctioned strength: Lok Sabha = 550; Rajya Sabha = 250 (including 12 nominated eminent persons in arts, literature, science, social service).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f30021df-27fa-4c81-a9e2-7fe661950feb', 'Lok Sabha: 550 members ; Rajya Sabha: 250 members (238 elected + 12 nominated by President)', true, '95909ea8-ea92-4e99-8340-4e0fb5456184');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('772f55d4-1d6f-4c17-b593-ff437fbfd77d', 'Lok Sabha: 500 ; Rajya Sabha: 200', false, '95909ea8-ea92-4e99-8340-4e0fb5456184');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e126ca75-7d96-49b6-b056-3e25d3067cb7', 'Lok Sabha: 600 ; Rajya Sabha: 300', false, '95909ea8-ea92-4e99-8340-4e0fb5456184');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e1e2ff6-4a8b-44ac-a51c-88c090347412', 'Both have 500 members', false, '95909ea8-ea92-4e99-8340-4e0fb5456184');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64b8e740-92f1-4afb-8d6a-e3f300b81995', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What does the term ''Secular State'' in the Indian Preamble signify?', 'Indian secularism (Sarva Dharma Sambhava) mandates absolute neutrality, non-discrimination, and equal protection for all faiths.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bfd943e-1cef-4991-85c8-83586ea7c5b2', 'The State has no official state religion and treats all religions equally with complete freedom of faith, worship, and conscience', true, '64b8e740-92f1-4afb-8d6a-e3f300b81995');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f29dd305-9ba7-4011-8717-437e58a3b4e8', 'The State bans all religions', false, '64b8e740-92f1-4afb-8d6a-e3f300b81995');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1445c00a-bb6a-49a8-ad09-7f84c656d18a', 'The State only supports one religion', false, '64b8e740-92f1-4afb-8d6a-e3f300b81995');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bef1192-5daf-4583-8ea8-8c45ec666c72', 'The State is ruled by priests', false, '64b8e740-92f1-4afb-8d6a-e3f300b81995');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c0a49bd-32d8-4fbe-b910-075f899fd78a', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'Who presides over the joint sittings of both Houses of Parliament in India?', 'Under Article 118(4), the Speaker of the Lok Sabha presides over joint sittings summoned by the President to resolve legislative deadlocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6b8f76f-261a-48fb-8ee5-cd668e865186', 'The Speaker of the Lok Sabha', true, '3c0a49bd-32d8-4fbe-b910-075f899fd78a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da873391-04ad-4c34-9d2d-8e4c8c53d8a6', 'The Chairman of Rajya Sabha', false, '3c0a49bd-32d8-4fbe-b910-075f899fd78a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ce40019-72f1-4783-b257-51f6c4856b1b', 'The President', false, '3c0a49bd-32d8-4fbe-b910-075f899fd78a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9339d06-70b6-4aef-b3ac-44f5824618ba', 'The Prime Minister', false, '3c0a49bd-32d8-4fbe-b910-075f899fd78a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a67ba9d0-a5b6-4d46-b903-e4b6594acadd', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the retirement age of a Judge of the Supreme Court of India and a Judge of a High Court respectively?', 'Constitutionally, Supreme Court judges hold office until 65 years of age, whereas High Court judges retire at 62 years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6315f74-57c6-4b60-86f6-d96c9b299742', 'Supreme Court Judge: 65 years ; High Court Judge: 62 years', true, 'a67ba9d0-a5b6-4d46-b903-e4b6594acadd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2da305ef-563b-43bc-a08b-9972c01f0def', 'Both 60 years', false, 'a67ba9d0-a5b6-4d46-b903-e4b6594acadd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1df9435d-42f8-4839-b888-b3c2a1bdf397', 'Both 65 years', false, 'a67ba9d0-a5b6-4d46-b903-e4b6594acadd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccca64e6-0915-4d5f-9c90-70e0d0ba44b3', 'Supreme Court: 70 years ; High Court: 65 years', false, 'a67ba9d0-a5b6-4d46-b903-e4b6594acadd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69195a5e-f6b1-4f44-83da-25e304de61c1', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the policy think-tank of the Government of India that replaced the Planning Commission in 2015, chaired by the Prime Minister?', 'Established on 1 January 2015, NITI Aayog fosters cooperative federalism and strategic policy advisory.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31d5e394-0bb2-454c-9fa4-4e20faa52c56', 'NITI Aayog (National Institution for Transforming India)', true, '69195a5e-f6b1-4f44-83da-25e304de61c1');
