INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7de08b72-f001-45a9-813c-bdfb69a41ec9', 'National Development Council', false, '69195a5e-f6b1-4f44-83da-25e304de61c1');
