INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32148db1-28b3-4f91-a3f3-4c694a535374', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'How long did the Constituent Assembly take to draft and complete the Constitution of India?', 'The Constituent Assembly held 11 plenary sessions spanning 165 days over a total period of 2 years, 11 months, and 18 days.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f2ae102-f40f-4ad0-96cb-1d96353d7edb', '2 years, 11 months, and 18 days', true, '32148db1-28b3-4f91-a3f3-4c694a535374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39d583c9-f3ca-416b-8e2b-db6bf8493217', '1 year and 6 months', false, '32148db1-28b3-4f91-a3f3-4c694a535374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b0decdd-84c4-4864-b8ef-57bab0105714', '5 full years', false, '32148db1-28b3-4f91-a3f3-4c694a535374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2411ca33-8be2-4927-8201-4fa307726e56', '3 years exactly', false, '32148db1-28b3-4f91-a3f3-4c694a535374');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('275d01c2-6c54-43a8-ba0f-c5a0ced894d6', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea91c220-55fd-4dec-98ac-4b519a9cd6d0', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '275d01c2-6c54-43a8-ba0f-c5a0ced894d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f362760b-c26e-4164-8cf1-4fc89e8a6e0d', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '275d01c2-6c54-43a8-ba0f-c5a0ced894d6');
