INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2232183-6f01-4455-adbe-dc31eb612ff3', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Spot the IMPOSTER in the following group of Fundamental Rights paired with their constitutional articles:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('704a80f3-a20b-4380-a05d-69f1c01f325b', 'Right to Equality - Articles 14-18', false, 'b2232183-6f01-4455-adbe-dc31eb612ff3');
