INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d094e5ae-3b17-402e-b470-1b3d9d630051', 'Right against Exploitation - Articles 23-24', false, 'b2232183-6f01-4455-adbe-dc31eb612ff3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0594cee-c48c-48fc-8c28-6d1eb1068aa2', 'Right to Education - Article 51A', true, 'b2232183-6f01-4455-adbe-dc31eb612ff3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd966496-4d98-4930-8c1d-ec0fc446c5e1', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'What historic landmark judgment by a 13-judge constitutional bench of the Supreme Court in 1973 established that Parliament cannot alter the ''Basic Structure'' of the Indian Constitution?', 'The Kesavananda Bharati verdict ruled that while Article 368 empowers Parliament to amend the Constitution, it cannot destroy its essential basic structure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df5fb160-fe85-4d32-b78d-64d42f8e3124', 'Kesavananda Bharati v. State of Kerala (1973)', true, 'dd966496-4d98-4930-8c1d-ec0fc446c5e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee70fc0d-b0e4-44cc-a1ca-4cccd66b4750', 'Golaknath Case (1967)', false, 'dd966496-4d98-4930-8c1d-ec0fc446c5e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ac08a1c-e396-45d2-88f9-2db21bc25fe7', 'Minerva Mills Case (1980)', false, 'dd966496-4d98-4930-8c1d-ec0fc446c5e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02fb2ed1-b80e-4f09-9cd0-a6955a8261d9', 'Maneka Gandhi Case (1978)', false, 'dd966496-4d98-4930-8c1d-ec0fc446c5e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4b4ca7c-d6da-489f-98f2-c3c65867978e', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Match Column I (Constitutional Bodies & Articles) with Column II (Functions):
(a) Article 324  -> (i) Autonomous Election Commission of India
(b) Article 280  -> (ii) Finance Commission for tax devolution
(c) Article 148  -> (iii) Comptroller and Auditor General (CAG) of India
(d) Article 76   -> (iv) Attorney General for India (highest law officer)', '324 = ECI; 280 = Finance Commission; 148 = CAG; 76 = Attorney General.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03649b26-7368-4e40-a96d-272b46df5633', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'e4b4ca7c-d6da-489f-98f2-c3c65867978e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ebffc25-b263-475c-9b13-420274907c25', 'a-(ii), b-(i), c-(iii), d-(iv)', false, 'e4b4ca7c-d6da-489f-98f2-c3c65867978e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a711f26-326c-4cd4-8ad0-0d08b2e21f60', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'e4b4ca7c-d6da-489f-98f2-c3c65867978e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f54c6db-720b-4a3d-aa3f-16a56bf42c95', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'e4b4ca7c-d6da-489f-98f2-c3c65867978e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40e9d25c-551b-4b29-9c2d-99bd05afcc32', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Read the statements regarding the Preamble of the Indian Constitution:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('102b49e7-5b2b-460f-850e-985961adc61b', 'Statements 1 and 3 only', true, '40e9d25c-551b-4b29-9c2d-99bd05afcc32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f510dc1d-b2cb-45b8-a339-80816a36f59c', 'Statements 1 and 2 only', false, '40e9d25c-551b-4b29-9c2d-99bd05afcc32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8ac5a5e-0557-4a34-a624-8531c29fd5cc', 'Statements 2 and 3 only', false, '40e9d25c-551b-4b29-9c2d-99bd05afcc32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('206a483d-1a1c-41e7-a30e-5095c284f4bd', 'All Statements 1, 2, and 3', false, '40e9d25c-551b-4b29-9c2d-99bd05afcc32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8efc580-0bb3-4028-aebd-ef6bfaba6706', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Which Constitutional Amendment Act lowered the voting age for Lok Sabha and Legislative Assembly elections from 21 years to 18 years?', 'The 61st Amendment amended Article 326, empowering 18-year-old Indian youth with democratic voting rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4bf7487-79c1-427f-8094-0c08a4ae45b0', '61st Constitutional Amendment Act (1988)', true, 'c8efc580-0bb3-4028-aebd-ef6bfaba6706');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08c2769b-7783-445e-806f-33cb2c214961', '42nd Constitutional Amendment Act (1976)', false, 'c8efc580-0bb3-4028-aebd-ef6bfaba6706');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('294e35ce-3593-4ef2-8246-09882281f5d9', '44th Constitutional Amendment Act (1978)', false, 'c8efc580-0bb3-4028-aebd-ef6bfaba6706');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59197fd4-d7f0-4003-90e6-f8c2ffb39102', '73rd Constitutional Amendment Act (1992)', false, 'c8efc580-0bb3-4028-aebd-ef6bfaba6706');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24b8f65f-9ba1-4601-add5-d09b26afe869', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'What are the Three Types of Emergencies that the President of India can proclaim under Part XVIII of the Constitution?', 'Articles 352 (National/War), 356 (Constitutional machinery failure in states), and 360 (Financial threat) constitute emergency provisions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce4b8f01-a2cd-4525-b19e-fac627a0c634', 'National Emergency (Article 352), State Emergency / President''s Rule (Article 356), and Financial Emergency (Article 360)', true, '24b8f65f-9ba1-4601-add5-d09b26afe869');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3d1379a-deab-4ded-93df-8615ec3dcf6b', 'War Emergency, Climate Emergency, Health Emergency', false, '24b8f65f-9ba1-4601-add5-d09b26afe869');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0310f646-76de-4e31-995b-18c2b1870cbb', 'Police Emergency, Judicial Emergency, Army Emergency', false, '24b8f65f-9ba1-4601-add5-d09b26afe869');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('761fa51b-f411-434c-ae16-8243579d0ccb', 'Only one type of emergency exists', false, '24b8f65f-9ba1-4601-add5-d09b26afe869');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a4af887-ee1c-4877-ac03-460a80ba3ab5', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Which of the following constitutional features of the Indian Constitution was borrowed from the Constitution of the United Kingdom (British Parliamentary Model)?', 'The Westminster parliamentary model, bicameralism, single citizenship, and legislative procedure were derived from the UK.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('931aeee6-ac78-4eff-a557-ec959108fed7', 'Parliamentary form of government, Rule of Law, Single Citizenship, and Cabinet System', true, '3a4af887-ee1c-4877-ac03-460a80ba3ab5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e259fdae-6ac8-4146-aac3-edab72531fa6', 'Fundamental Rights (USA)', false, '3a4af887-ee1c-4877-ac03-460a80ba3ab5');
