INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1af8b3de-6f5a-4c68-b3de-54a06c2fcc94', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'What is the constitutional mechanism known as ''Gram Sabha'' under the 73rd Amendment Act?', 'Gram Sabha comprises every registered voter in the village panchayat area, deliberating village plans and budget expenditures.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c0f853f-7103-43d0-9245-5f9a5a3915d0', 'A village assembly consisting of ALL registered adult voters of a village, serving as the foundational grassroots direct democracy organ', true, '1af8b3de-6f5a-4c68-b3de-54a06c2fcc94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48af577c-df04-43b1-8847-ba8fb49e0043', 'A council of village priests only', false, '1af8b3de-6f5a-4c68-b3de-54a06c2fcc94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d78c3411-398d-4c31-ae61-905a5295a878', 'A group of rich landowners', false, '1af8b3de-6f5a-4c68-b3de-54a06c2fcc94');
