INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7bee7ad8-5475-46d8-8a0a-7797008a3b29', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Who was the famous master artist of Shantiniketan who, along with his students (including Beohar Rammanohar Sinha), painstakingly illuminated and hand-decorated the original calligraphy pages of the Constitution of India?', 'Nandalal Bose decorated the original manuscript with classical Indian motifs, while Prem Behari Narain Raizada wrote the elegant calligraphy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('062ed20f-5d8c-4e93-90a8-c8f1ab1132ae', 'Nandalal Bose', true, '7bee7ad8-5475-46d8-8a0a-7797008a3b29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c89ef0a-d1e7-482b-a2f6-b518350fc6bf', 'Raja Ravi Varma', false, '7bee7ad8-5475-46d8-8a0a-7797008a3b29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e78b5b-1fba-4bdd-927f-6672246bbf08', 'Abanindranath Tagore', false, '7bee7ad8-5475-46d8-8a0a-7797008a3b29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20b6d9e7-05b6-40cf-b1a8-32920c22c0af', 'M.F. Husain', false, '7bee7ad8-5475-46d8-8a0a-7797008a3b29');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f57ab8f-fef8-46df-a6df-d77e98b027df', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'What is the primary function of the ''Directive Principles of State Policy'' (DPSP) contained in Part IV (Articles 36–51) of the Indian Constitution?', 'Inspired by Ireland, DPSPs guide governmental legislation towards achieving social and economic democracy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dbddebc-7520-4c3c-bd27-9b3f6ae6d25f', 'They are non-justiciable socio-economic policy guidelines and goals for the State to establish a Welfare State (Kalyankari Rajya) based on social justice', true, '2f57ab8f-fef8-46df-a6df-d77e98b027df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af9c06a4-89db-4983-abd2-59e336eb9b8e', 'They are criminal punishment laws', false, '2f57ab8f-fef8-46df-a6df-d77e98b027df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f88d83b-a0a8-4c9a-b501-0951e3fb88da', 'They are rules for the Indian Army', false, '2f57ab8f-fef8-46df-a6df-d77e98b027df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3140404a-46cd-47b2-af61-b2b1c1b5afa9', 'They are tax collection rules', false, '2f57ab8f-fef8-46df-a6df-d77e98b027df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f60435a-cdb8-4689-92da-e3602e2d38e5', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'How is the President of India elected according to the Constitution?', 'Article 54 prescribes an Electoral College comprising elected MPs and MLAs through proportional representation by single transferable vote.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95d972d3-93b5-4a70-adca-ed52d23a3a63', 'Indirectly by an Electoral College consisting of elected members of both Houses of Parliament AND elected members of State Legislative Assemblies (using Single Transferable Vote)', true, '9f60435a-cdb8-4689-92da-e3602e2d38e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f42a6da-54c0-4115-a9b9-71495198249d', 'Directly by all voting citizens of India', false, '9f60435a-cdb8-4689-92da-e3602e2d38e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fc9b583-382a-4d3e-adee-f72d0375fc24', 'Nominated solely by the Prime Minister', false, '9f60435a-cdb8-4689-92da-e3602e2d38e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b93445a3-d30c-43c9-bbe1-d207992a443b', 'Chosen by the Supreme Court judges', false, '9f60435a-cdb8-4689-92da-e3602e2d38e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3083ec0-99a2-48d9-afbd-1a84eb3ad413', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Easy', 'What is the total geographical area of India, making it the 7th largest country in the world?', 'India spans 3.28 million km², accounting for ~2.4% of total world land area.', NOW()) ON CONFLICT DO NOTHING;
