INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d62e380b-9f17-481c-88d2-4f65c8158b1f', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Easy', 'What is the North-to-South longitudinal extent of India from Ladakh (Indira Col) to Kanyakumari?', 'The mainland North-South distance spans approximately 3,200 km from northern Ladakh to Kanyakumari.', NOW()) ON CONFLICT DO NOTHING;
