INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d18eb52-8b51-4e44-a265-6787a7b9f710', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Easy', 'Which important latitude circle passes almost halfway through the middle of India at 23°30'' N?', 'The Tropic of Cancer (23°30'' N) bisects India through 8 states (Gujarat, Rajasthan, MP, Chhattisgarh, Jharkhand, West Bengal, Tripura, Mizoram).', NOW()) ON CONFLICT DO NOTHING;
