INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f9e1cae-d8a2-432a-9c66-93b476063093', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Easy', 'What is a piece of land that is surrounded by water on THREE sides called?', 'A peninsula is a landmass bordered by sea on 3 sides; southern India is bounded by the Arabian Sea, Bay of Bengal, and Indian Ocean.', NOW()) ON CONFLICT DO NOTHING;
