INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b45c46a-3d87-457f-bdf1-89d51f454627', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Easy', 'Which high mountain range guards the northern boundary of India like a gigantic natural wall?', 'The Himalayas (''Him'' + ''Alaya'' = Abode of Snow) form the 2,400 km northern alpine frontier of India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84843a3e-a206-456d-b059-2a004f4bc8be', 'The Himalayas (''Abode of Snow'')', true, '8b45c46a-3d87-457f-bdf1-89d51f454627');
