INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33f3ae05-3258-4185-871b-d094447689a8', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Easy', 'What are the THREE parallel mountain ranges of the Himalayas from north to south?', 'From north to south: 1. Himadri (Great Himalayas), 2. Himachal (Lesser Himalayas), 3. Shiwalik (Outer Himalayas).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95c0ca94-4b40-48bd-b19d-2cacfd36737f', 'Great Himalayas (Himadri) -> Middle Himalayas (Himachal) -> Outer Himalayas (Shiwalik)', true, '33f3ae05-3258-4185-871b-d094447689a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f915103-8a91-4257-9925-15f730348fc4', 'Shiwalik -> Himadri -> Himachal', false, '33f3ae05-3258-4185-871b-d094447689a8');
