INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8677296-1dd3-4b48-9083-dfcf29ab9794', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Easy', 'Which two Indian island groups belong to the Republic of India?', 'Lakshadweep (coral atolls in Arabian Sea) and Andaman & Nicobar (submerged volcanic peaks in Bay of Bengal) are Indian Union Territories.', NOW()) ON CONFLICT DO NOTHING;
