INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b768cbd0-7b5d-49bb-8858-ce1d346122c6', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Easy', 'Which coral island group of India is located off the coast of Kerala in the Arabian Sea?', 'Lakshadweep consists of 36 coral atoll islands situated 200–440 km off the Malabar Coast of Kerala.', NOW()) ON CONFLICT DO NOTHING;
