INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88e2d4f8-62ac-4744-9776-697cb0927c8b', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Easy', 'What is the capital city of India?', 'New Delhi serves as the national capital territory of the Republic of India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cbb1214-1f47-420d-ac9b-6aac479cfc81', 'New Delhi', true, '88e2d4f8-62ac-4744-9776-697cb0927c8b');
