INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18fcf53f-ff1d-4123-b6a1-aa5b48db04b1', 'Kolkata', false, '88e2d4f8-62ac-4744-9776-697cb0927c8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e749be41-e3a9-458e-9c3b-4aed6cece48a', 'Chennai', false, '88e2d4f8-62ac-4744-9776-697cb0927c8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('078a25e4-e4db-4fd1-8a54-209c20b92517', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What is the Standard Meridian of India, chosen to determine the Indian Standard Time (IST)?', 'The 82°30'' E meridian is the standard time meridian for India, exactly 5 hours and 30 minutes ahead of Greenwich Mean Time (UTC+05:30).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a13773fb-357d-416c-a8bd-c9c6193f7df1', '82°30'' E longitude (passing through Mirzapur / Prayagraj in Uttar Pradesh)', true, '078a25e4-e4db-4fd1-8a54-209c20b92517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e29c3a69-2b04-4e7a-bffd-0ab9f0aed8d8', '80°00'' E', false, '078a25e4-e4db-4fd1-8a54-209c20b92517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('955e2c12-a54e-4ff9-864a-3f3945223705', '75°30'' E', false, '078a25e4-e4db-4fd1-8a54-209c20b92517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('689e9d93-9d92-4952-b9c3-cfab5a801be8', '90°00'' E', false, '078a25e4-e4db-4fd1-8a54-209c20b92517');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74866f34-127e-494d-9286-222bbe77c820', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'Why is there a time difference of nearly TWO HOURS in local sunrise time between Arunachal Pradesh in the east and Gujarat in the west?', 'Diurnal rotation: 360° in 24 hours = 1° in 4 minutes. A longitudinal span of ~29° equates to roughly 116 minutes (~2 hours) local solar lag.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ef4c937-4091-402b-b1e5-2626a40a3b3a', 'India spans a longitudinal width of nearly 30° (68°7'' E to 97°25'' E); since Earth rotates 1° of longitude in 4 minutes, 30° × 4 min = 120 minutes (2 hours)', true, '74866f34-127e-494d-9286-222bbe77c820');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e37cd1d-c914-4cd3-8a1f-d52fc89e676a', 'Because clocks run faster in Gujarat', false, '74866f34-127e-494d-9286-222bbe77c820');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93f1a9ac-0d8c-4b9c-ae08-b69971e835b9', 'Because the Sun rises in the west in India', false, '74866f34-127e-494d-9286-222bbe77c820');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beceec6c-6779-4a02-afc3-22e1bf4c3679', 'Because mountains block the Sun', false, '74866f34-127e-494d-9286-222bbe77c820');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1dca308-94ea-4fbe-8288-05fabcc8aa14', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'How many countries share land borders with India?', 'India shares 15,106 km of land borders with 7 neighboring nations: Bangladesh, China, Pakistan, Nepal, Myanmar, Bhutan, and Afghanistan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3692ea7-cb4e-47a5-963f-021f1f839096', '7 countries (Pakistan, Afghanistan, China, Nepal, Bhutan, Bangladesh, and Myanmar)', true, 'e1dca308-94ea-4fbe-8288-05fabcc8aa14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01f0d63-81e3-4d53-9bf8-0f1804ce12d5', '5 countries', false, 'e1dca308-94ea-4fbe-8288-05fabcc8aa14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab7b69f5-2e8f-438b-b71c-82b2b62ad54e', '6 countries', false, 'e1dca308-94ea-4fbe-8288-05fabcc8aa14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('863fdf80-43b0-4b3b-958e-8aaf9b99625a', '8 countries', false, 'e1dca308-94ea-4fbe-8288-05fabcc8aa14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c85ea53-65ba-492d-9f8a-278eeecf48ba', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'With which country does India share its LONGEST international land border (4,096.7 km)?', 'India shares its longest land frontier with Bangladesh (4,096.7 km), encircling it from West Bengal, Assam, Meghalaya, Tripura, and Mizoram.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ada5fbf-91fd-45c0-b72c-0bf414992036', 'Bangladesh', true, '5c85ea53-65ba-492d-9f8a-278eeecf48ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8cdf66f-d970-4c55-a20b-f8aca62e3369', 'China', false, '5c85ea53-65ba-492d-9f8a-278eeecf48ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cae5d39-47af-4bd4-9a24-90490b3a9cb8', 'Pakistan', false, '5c85ea53-65ba-492d-9f8a-278eeecf48ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('823bb0db-47ac-41c8-a71e-c0ace983551d', 'Nepal', false, '5c85ea53-65ba-492d-9f8a-278eeecf48ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae024317-37d1-4802-acd0-89006dbfecb3', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What is the world''s LARGEST river delta, formed by the confluence of the Ganga and Brahmaputra rivers emptying into the Bay of Bengal?', 'The triangular Sundarbans mangrove delta covers ~100,000 km², named after the abundant Sundari mangrove trees (Heritiera fomes).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('089dcadc-f4e5-48ea-9ed0-ac1d2e135555', 'Sundarbans Delta (Ganga-Brahmaputra Delta)', true, 'ae024317-37d1-4802-acd0-89006dbfecb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d273291-440a-47e0-b88d-549fd56760c4', 'Nile Delta', false, 'ae024317-37d1-4802-acd0-89006dbfecb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af0ee53c-5062-4530-ab71-055ee7773734', 'Mississippi Delta', false, 'ae024317-37d1-4802-acd0-89006dbfecb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75170b49-23f7-49dc-be35-95f2212484f1', 'Amazon Delta', false, 'ae024317-37d1-4802-acd0-89006dbfecb3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9895fdc-575b-4dd0-9b51-8320ecd02643', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'Which triangular relief feature of India is an ancient elevated tableland composed of old crystalline, igneous, and metamorphic rocks?', 'The Peninsular Plateau is the oldest and most stable geological landmass of India, forming part of ancient Gondwanaland.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd9774f5-6e76-41bf-b1df-d21147cf4b91', 'The Peninsular Plateau', true, 'a9895fdc-575b-4dd0-9b51-8320ecd02643');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72ac1f7a-9a62-4114-8ef0-469ce3378cdb', 'The Northern Plains', false, 'a9895fdc-575b-4dd0-9b51-8320ecd02643');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76ffaf9f-2eaa-4d2c-8b82-973fed55c5a3', 'The Coastal Plains', false, 'a9895fdc-575b-4dd0-9b51-8320ecd02643');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dfd35fe-a997-4c48-9723-f6b1ec739aa5', 'The Thar Desert', false, 'a9895fdc-575b-4dd0-9b51-8320ecd02643');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1b6fc0c-62eb-41ac-a2f5-fd5ca738c34a', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What are the continuous elevated mountain ranges bordering the western edge of the Deccan Plateau called?', 'The Western Ghats (Sahyadris) form an unbroken high escarpment along the western coast with passes like Thal, Bhor, and Pal Ghats.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b9d0204-f3d1-4972-943c-a589884da21b', 'Western Ghats (or Sahyadris)', true, 'c1b6fc0c-62eb-41ac-a2f5-fd5ca738c34a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a0c1527-d0be-4d48-8b9a-e3dbcc121120', 'Eastern Ghats', false, 'c1b6fc0c-62eb-41ac-a2f5-fd5ca738c34a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06508b52-0f32-46b6-815b-904ffdeceb0b', 'Aravalli Range', false, 'c1b6fc0c-62eb-41ac-a2f5-fd5ca738c34a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e768535-0241-4384-81d2-9835e13dec0d', 'Vindhya Range', false, 'c1b6fc0c-62eb-41ac-a2f5-fd5ca738c34a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78e571d8-fac0-4212-b10b-850d588e74a6', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'How do the Eastern Ghats differ from the Western Ghats?', 'East-flowing peninsular rivers cut wide valleys through the Eastern Ghats, making them discontinuous and lower in average altitude (600m vs 1200m).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e939add8-921b-4dfb-b7be-f9521ba454a0', 'The Eastern Ghats are discontinuous, lower in height, and dissected by east-flowing rivers (Mahanadi, Godavari, Krishna, Kaveri), whereas the Western Ghats are continuous and higher', true, '78e571d8-fac0-4212-b10b-850d588e74a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fe2f9f5-ed92-4764-a10b-132768dccd68', 'The Eastern Ghats have snow glaciers', false, '78e571d8-fac0-4212-b10b-850d588e74a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ed9e2bd-2fe0-48f7-ac12-b7736be30396', 'The Eastern Ghats are in the Arabian Sea', false, '78e571d8-fac0-4212-b10b-850d588e74a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ccecbb7-6441-4eba-91e2-c8d1ee10982b', 'There is no difference', false, '78e571d8-fac0-4212-b10b-850d588e74a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e025a22-861a-499a-800e-0a3d790acc4b', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'Which are the only two major west-flowing peninsular rivers in India that drain into the Arabian Sea through rift valleys without forming deltas?', 'Narmada and Tapi flow westward in structural fault rift valleys between the Vindhya and Satpura ranges, forming estuaries instead of deltas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e28f60dd-70d6-4b0e-b745-0fb2485705b4', 'Narmada and Tapi (Tapti)', true, '6e025a22-861a-499a-800e-0a3d790acc4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c081b960-2245-444f-bd5e-f76c1ee38447', 'Ganga and Yamuna', false, '6e025a22-861a-499a-800e-0a3d790acc4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aeda2258-b20c-40c4-b425-e009278e6d5e', 'Godavari and Krishna', false, '6e025a22-861a-499a-800e-0a3d790acc4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b24fcdbe-1f3f-4286-829c-d308e51c2442', 'Mahanadi and Kaveri', false, '6e025a22-861a-499a-800e-0a3d790acc4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d776328e-6bd2-4688-8aee-590b67b79c7b', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'Which major peninsular rivers flow eastward and drain into the Bay of Bengal, forming large fertile deltas at their mouths?', 'Godavari (Dakshin Ganga), Krishna, Kaveri, and Mahanadi flow down the eastward regional plateau gradient, depositing extensive deltas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('402ebd3c-d67b-4782-befb-f6b279cb955b', 'Mahanadi, Godavari, Krishna, and Kaveri', true, 'd776328e-6bd2-4688-8aee-590b67b79c7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c33e898-da31-4045-9a85-80ee5a2c9466', 'Narmada and Tapi', false, 'd776328e-6bd2-4688-8aee-590b67b79c7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ff46e51-be12-4b6f-8916-68d3c935f799', 'Indus and Jhelum', false, 'd776328e-6bd2-4688-8aee-590b67b79c7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b64e3428-0766-41ac-8fc7-5cab4714c1a7', 'Luni and Sabarmati', false, 'd776328e-6bd2-4688-8aee-590b67b79c7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99554a78-fc04-4877-a368-0654311c868f', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'How do the Western Coastal Plains compare with the Eastern Coastal Plains of India?', 'Western coastal strip (Konkan, Malabar) is narrow (~50 km); Eastern coastal strip (Northern Circars, Coromandel) is wide (~100–120 km) with deltas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('324679ec-67fb-4ffc-b345-6c0a34f5e241', 'Western Coastal Plains are very narrow between the Western Ghats and Arabian Sea, while Eastern Coastal Plains are much broader and wider along the Bay of Bengal', true, '99554a78-fc04-4877-a368-0654311c868f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b438bb8-ba1e-4934-8146-bde946e8a33c', 'Western Coastal Plains are covered in snow', false, '99554a78-fc04-4877-a368-0654311c868f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac28e23e-1293-462b-b3b5-1cb38372a7cb', 'Eastern Coastal Plains have no rivers', false, '99554a78-fc04-4877-a368-0654311c868f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0faf52e4-4bef-4646-8a15-686d1ef25b99', 'Both are identical in width', false, '99554a78-fc04-4877-a368-0654311c868f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ce4b5f9-9ae5-4593-b614-dcf3d5a7dfb3', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What are ''Corals'' and how did coral islands like Lakshadweep form?', 'Scleractinian anthozoan polyps secrete calcium carbonate exoskeletons; generational biogenic reef accumulation builds atolls.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29040e4a-e76d-426a-b4d0-dc2b8e6ece1e', 'Corals are tiny marine animals (Polyps); when polyps die, their hard calcium carbonate skeletons accumulate over millennia to form coral reefs and islands', true, '3ce4b5f9-9ae5-4593-b614-dcf3d5a7dfb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afaa70f3-2467-4c09-863e-f8e8d69b309e', 'They are volcanic stones thrown by volcanoes', false, '3ce4b5f9-9ae5-4593-b614-dcf3d5a7dfb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bd40714-f96a-4c1a-b95e-fb4bcb1c4625', 'They are plants that turn into wood', false, '3ce4b5f9-9ae5-4593-b614-dcf3d5a7dfb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1134494-2920-4187-8d4c-09205567eb26', 'They are icebergs from the South Pole', false, '3ce4b5f9-9ae5-4593-b614-dcf3d5a7dfb3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9c967fa-43c6-49ec-b39e-7335361e6144', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What is the southernmost point of the Indian Union territory (located in Great Nicobar), which was submerged during the devastating 2004 Indian Ocean tsunami?', 'Indira Point on Great Nicobar island at 6°45'' N is the southernmost geographic point of the sovereign Indian Republic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac5a5667-53ca-42c1-a046-143a54d13fee', 'Indira Point (6°45'' N latitude)', true, 'd9c967fa-43c6-49ec-b39e-7335361e6144');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1336d884-f337-4bfc-bc85-d981e5853036', 'Kanyakumari', false, 'd9c967fa-43c6-49ec-b39e-7335361e6144');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db068535-04b3-486d-a2c8-103ff1ce5106', 'Dhanushkodi', false, 'd9c967fa-43c6-49ec-b39e-7335361e6144');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('779d2907-35cf-4cd0-afb0-13c1835b339b', 'Rameswaram', false, 'd9c967fa-43c6-49ec-b39e-7335361e6144');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30958f7b-06ea-4ba3-ad5b-a0b3b84935c9', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What is the southernmost tip of the MAINLAND of India located in Tamil Nadu where three water bodies (Arabian Sea, Bay of Bengal, Indian Ocean) meet?', 'Cape Comorin (Kanyakumari) at 8°4'' N is the southern apex of mainland peninsular India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdbc2e33-984e-4fc9-82f7-db8d2013aa35', 'Kanyakumari (Cape Comorin at 8°4'' N)', true, '30958f7b-06ea-4ba3-ad5b-a0b3b84935c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9034d322-4252-4696-9ac4-1c0fd8dcc0a1', 'Indira Point', false, '30958f7b-06ea-4ba3-ad5b-a0b3b84935c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e850348-ae08-468c-9713-03f3da789c32', 'Tuticorin', false, '30958f7b-06ea-4ba3-ad5b-a0b3b84935c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e2841da-ac57-441c-b57d-553dbe4fc1d4', 'Thiruvananthapuram', false, '30958f7b-06ea-4ba3-ad5b-a0b3b84935c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f10e598-c312-430b-9ccc-d4d4faf3845d', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'Which mountain range is the oldest fold mountain system in India and among the oldest in the world, running from Gujarat to Delhi across Rajasthan?', 'The Aravalli Range is a Precambrian fold mountain system severely eroded into relict hills (highest peak Guru Shikhar at 1,722 m).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37334215-37a1-42a8-abc4-1475b54e06da', 'Aravalli Range', true, '4f10e598-c312-430b-9ccc-d4d4faf3845d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c12542d6-5fdd-4a04-bf7f-5536a93e2f24', 'Himalayas', false, '4f10e598-c312-430b-9ccc-d4d4faf3845d');
