INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('962cfa95-38d5-4d22-89f7-a09b69f6efe8', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What are the states of India known as the ''Seven Sisters'' of the North-Eastern region?', 'The 7 contiguous North-Eastern states: Arunachal Pradesh, Assam, Meghalaya, Nagaland, Manipur, Mizoram, and Tripura.', NOW()) ON CONFLICT DO NOTHING;
