INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1c06a52-0b45-4d59-8c8c-506dcc8e33f0', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'A geography student charts the latitudinal and longitudinal coordinates of the Indian mainland. What are the exact mathematical coordinates?', 'Mainland limits: Latitudes 8°4'' N (Kanyakumari) to 37°6'' N (Indira Col); Longitudes 68°7'' E (Gujarat) to 97°25'' E (Arunachal).', NOW()) ON CONFLICT DO NOTHING;
