INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dab62c59-fc8c-4dac-aacc-5638f9859410', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Match Column I (Physical Divisions) with Column II (Dominant Characteristics):
(a) Himadri           -> (i) Northernmost highest Himalayan crest with perennial snow
(b) Northern Plains   -> (ii) Fertile alluvial basin formed by Indus, Ganga, Brahmaputra
(c) Thar Desert       -> (iii) Arid sandy tract with shifting barchan dunes
(d) Lakshadweep       -> (iv) Coral atoll island archipelago in the Arabian Sea', 'Himadri = highest snow peaks; Northern Plains = alluvium; Thar = sandy dunes; Lakshadweep = coral atolls.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ad7aa56-d319-4a5f-80a3-ecdc62402417', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'dab62c59-fc8c-4dac-aacc-5638f9859410');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70453163-286f-43f6-9981-d2355cccf957', 'a-(ii), b-(i), c-(iii), d-(iv)', false, 'dab62c59-fc8c-4dac-aacc-5638f9859410');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b812d05-744f-462e-9683-2360013c33da', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'dab62c59-fc8c-4dac-aacc-5638f9859410');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c165443-b52a-4da4-bc71-55a4eed158f4', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'dab62c59-fc8c-4dac-aacc-5638f9859410');
