INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddebc715-db1b-4c80-b20b-4bdb58fdeda5', 'Statements 1 and 2 only', true, 'c972b2bf-e31f-4938-8abf-14caac2b949b');
