INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26fa97ef-f4fd-42e4-a430-792443133dfa', 'Statements 1 and 3 only', false, 'c972b2bf-e31f-4938-8abf-14caac2b949b');
