INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c067a4b-48f6-489b-aa8d-c9b2ec0c0a5a', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Which of the following coastal sub-regions are located along the WESTERN coast and EASTERN coast of India respectively?', 'West coast: Konkan (north) and Malabar (south); East coast: Northern Circar (north) and Coromandel (south).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6235a171-0220-4374-8054-154c5668d285', 'Western Coast: Konkan & Malabar Coast ; Eastern Coast: Northern Circars & Coromandel Coast', true, '3c067a4b-48f6-489b-aa8d-c9b2ec0c0a5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c665fd8-2857-4721-9bcb-2d69fd955374', 'Western Coast: Coromandel ; Eastern Coast: Konkan', false, '3c067a4b-48f6-489b-aa8d-c9b2ec0c0a5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ab4c612-b5b1-4b22-98c2-3b7446a02d91', 'Western Coast: Northern Circars ; Eastern Coast: Malabar', false, '3c067a4b-48f6-489b-aa8d-c9b2ec0c0a5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce59fb77-53a2-4021-9847-93ed53e2e7b9', 'Both are called Malabar', false, '3c067a4b-48f6-489b-aa8d-c9b2ec0c0a5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a4eb14a-012d-4c9b-a9dd-546c0aa3367f', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Why does the Sundarbans Delta feature extensive amphibious Mangrove forests adapted to coastal saline waters?', 'Halophytic adaptations: viviparous germination, salt-excreting glands, and negative geotropic pneumatophores flourish in intertidal muds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0318d591-a5bd-4913-bb0d-167314634b0d', 'Tidal sea surges mix with freshwater river floods; mangrove species (Sundari) develop specialized breathing roots (pneumatophores) and stilt roots to survive in anaerobic saline mudflats', true, '9a4eb14a-012d-4c9b-a9dd-546c0aa3367f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db992fb9-f82b-4724-b1c7-14ecf4af17a5', 'Because mangroves only grow in snow', false, '9a4eb14a-012d-4c9b-a9dd-546c0aa3367f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cb7f541-7f82-4896-9023-90a34ac37823', 'Because salt water kills all other trees except plastic trees', false, '9a4eb14a-012d-4c9b-a9dd-546c0aa3367f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22ca5500-6a2e-4781-a2a1-0c6f278212ed', 'Because it never rains there', false, '9a4eb14a-012d-4c9b-a9dd-546c0aa3367f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6c52364-6dce-4835-b807-706230064251', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'What is the highest mountain peak situated entirely within the undisputed sovereign territory of India?', 'Kangchenjunga (8,586 m) in Sikkim on the India-Nepal border is the highest peak in India (and 3rd highest in the world).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed9096ba-5d36-4c28-b632-bf481ad8824a', 'Kangchenjunga (8,586 meters, Sikkim)', true, 'f6c52364-6dce-4835-b807-706230064251');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c31d775-08e2-45cc-8e82-5ab95cb77881', 'Nanda Devi (7,816 m)', false, 'f6c52364-6dce-4835-b807-706230064251');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1b56376-84e5-4bf0-a4ab-84bccdf96731', 'Kamet', false, 'f6c52364-6dce-4835-b807-706230064251');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc2a09ac-baad-4676-aa3d-828d41d29c69', 'Anamudi', false, 'f6c52364-6dce-4835-b807-706230064251');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de420092-e353-4c2e-89a7-07d18caedd5f', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'What is the highest peak in the Western Ghats and in the entire Peninsular South India (located in Kerala)?', 'Anamudi (''Elephant''s Forehead'') stands at 2,695 m in Eravikulam National Park, Kerala, the highest summit in South India.', NOW()) ON CONFLICT DO NOTHING;
