INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7bb22b4-cc12-4ce3-b723-7d03ccc2a626', 'Doda Betta (2,637 m)', false, 'de420092-e353-4c2e-89a7-07d18caedd5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34019d2e-7a53-439a-a232-a96a744e7437', 'Mahendragiri', false, 'de420092-e353-4c2e-89a7-07d18caedd5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf3530bd-2307-4978-b16f-1706e56cd4cd', 'Kalsubai', false, 'de420092-e353-4c2e-89a7-07d18caedd5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9111161-a5e0-4abc-bcdd-9c76d2f777ca', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Which of the following Indian states do NOT share an international boundary with any foreign country and have no coastline (landlocked internal states)?', 'MP, Chhattisgarh, Jharkhand, Telangana, and Haryana are entirely landlocked interior states with neither international frontiers nor coastlines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88d56802-30aa-4ba1-933e-28983923c23d', 'Madhya Pradesh, Chhattisgarh, Jharkhand, Telangana, and Haryana', true, 'e9111161-a5e0-4abc-bcdd-9c76d2f777ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cf4075c-8515-4ec8-b527-2e11f88cf9f1', 'Gujarat, Rajasthan, Punjab', false, 'e9111161-a5e0-4abc-bcdd-9c76d2f777ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('491092d8-3bee-44ba-b933-04e2bd04a8d8', 'West Bengal, Assam, Bihar', false, 'e9111161-a5e0-4abc-bcdd-9c76d2f777ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6702714-7950-447f-99ad-f1b7ae1e1708', 'Tamil Nadu, Kerala, Karnataka', false, 'e9111161-a5e0-4abc-bcdd-9c76d2f777ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b72cabde-378e-4bc2-b390-60c2a05d7fa8', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'What is the physical geographic significance of the ''Ten Degree Channel'' (10° N latitude)?', 'The 10° Channel lies along the 10° N parallel, separating Little Andaman from Car Nicobar across a 150 km strait.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58640758-d38a-49cf-968b-da469d6d3a28', 'It is a maritime channel in the Bay of Bengal that separates the Andaman Islands in the north from the Nicobar Islands in the south', true, 'b72cabde-378e-4bc2-b390-60c2a05d7fa8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc15db16-b596-4c0b-8830-008295978c16', 'It separates India from Sri Lanka', false, 'b72cabde-378e-4bc2-b390-60c2a05d7fa8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5180e059-c35f-4a65-9121-931967f88bb5', 'It separates Lakshadweep from Maldives', false, 'b72cabde-378e-4bc2-b390-60c2a05d7fa8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17d5ff3c-105d-4635-9ac0-976df66e1317', 'It separates Gujarat from Pakistan', false, 'b72cabde-378e-4bc2-b390-60c2a05d7fa8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef542eaa-13d3-440e-b12f-a0319f95a0c6', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Why is India described as a land of immense ''Unity in Diversity'' in NCERT Social Science?', 'Coined by Jawaharlal Nehru, ''Unity in Diversity'' celebrates India''s pluralistic mosaic united by shared civilizational and constitutional ethos.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f78caf9b-ab32-4c2e-af63-dccd696eb53e', 'Despite profound geographical, climatic, linguistic, religious, and cultural diversity, a deep underlying thread of common national civilization and constitutional brotherhood binds the people of India together as one nation', true, 'ef542eaa-13d3-440e-b12f-a0319f95a0c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee1d4657-03a1-43e7-b90f-650f6ba0e162', 'Because all Indians speak only one language', false, 'ef542eaa-13d3-440e-b12f-a0319f95a0c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e5e6804-9d8b-4223-b3e3-8832676cd40f', 'Because all regions look identical', false, 'ef542eaa-13d3-440e-b12f-a0319f95a0c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dc30264-1072-4882-bb53-9bb14509201e', 'Because everyone eats the exact same food', false, 'ef542eaa-13d3-440e-b12f-a0319f95a0c6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8ea9220-560f-4ede-953a-b4e9f72364c4', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'संज्ञा या सर्वनाम के जिस रूप से उसका संबंध वाक्य की क्रिया तथा अन्य शब्दों से जाना जाता है, उसे व्याकरण में क्या कहते हैं?', 'क्रिया से साक्षात् संबंध स्थापित करने वाले संज्ञा/सर्वनाम के रूपात्मक संबंध को ''कारक'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acbf855e-95a4-4954-b9e8-f84ebe37d110', 'कारक (Case)', true, 'b8ea9220-560f-4ede-953a-b4e9f72364c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cbe6245-1648-4434-9c88-daaf5f4433fe', 'काल', false, 'b8ea9220-560f-4ede-953a-b4e9f72364c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb6c6ce2-c58e-4fa3-9e91-53c951c823c5', 'वाच्य', false, 'b8ea9220-560f-4ede-953a-b4e9f72364c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a6b01c8-c0ad-4943-8887-3c5547e779eb', 'संधि', false, 'b8ea9220-560f-4ede-953a-b4e9f72364c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd71a2d3-6300-4ea0-96ca-01133f53650e', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'हिंदी भाषा में कारक के मुख्य रूप से कितने भेद (प्रकार) होते हैं?', 'हिंदी में आठ कारक होते हैं: कर्ता, कर्म, करण, संप्रदान, अपादान, संबंध, अधिकरण और संबोधन।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6f0fad8-0711-44e9-882e-f2325dc431e1', 'आठ भेद (8 Types)', true, 'dd71a2d3-6300-4ea0-96ca-01133f53650e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69d555d9-19db-4b46-b219-817b28778078', 'छह भेद', false, 'dd71a2d3-6300-4ea0-96ca-01133f53650e');
