INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8b75ef5-8faa-4d8e-80c9-afdfed132b16', 'पाँच भेद', false, 'dd71a2d3-6300-4ea0-96ca-01133f53650e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61ce6720-12fb-47c9-ba82-197a40e5a43e', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'कारकों को प्रकट करने के लिए संज्ञा या सर्वनाम के साथ लगाए जाने वाले चिह्नों (जैसे: ने, को, से, के लिए, का, में, पर) को क्या कहते हैं?', 'कारक संबंधों को व्यक्त करने वाले प्रत्यय/चिह्न ''विभक्ति'' या ''परसर्ग'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa7beef1-5130-4d67-bbb4-a74f829fdf75', 'विभक्ति चिह्न या परसर्ग (Case Endings / Postpositions)', true, '61ce6720-12fb-47c9-ba82-197a40e5a43e');
