INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5366c19-f6e0-4011-acde-a339958e4cbd', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'वाक्य में कार्य (क्रिया) को करने वाले पद को कौन-सा कारक कहते हैं और इसका विभक्ति चिह्न क्या है?', 'क्रिया को संपन्न करने वाला ''कर्ता कारक'' होता है, जिसका प्रमुख परसर्ग ''ने'' है (जैसे: ''राम ने पत्र लिखा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bc07060-df9f-49f1-b5ef-0e45aacba0e3', 'कर्ता कारक (विभक्ति: ''ने'')', true, 'e5366c19-f6e0-4011-acde-a339958e4cbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08adde77-ddc4-4f43-8fb0-f50a963cc2f0', 'कर्म कारक (विभक्ति: ''को'')', false, 'e5366c19-f6e0-4011-acde-a339958e4cbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f9223df-d83a-4ccc-874f-ee00550597cf', 'करण कारक (विभक्ति: ''से'')', false, 'e5366c19-f6e0-4011-acde-a339958e4cbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e21bc624-3c07-4367-b2db-ecbd3f27ca68', 'अपादान कारक', false, 'e5366c19-f6e0-4011-acde-a339958e4cbd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fec746c-1f46-43d7-9ff2-31546e4ac7e8', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'क्रिया का फल (प्रभाव) जिस संज्ञा या सर्वनाम पर पड़ता है, उसे कौन-सा कारक कहते हैं और इसका विभक्ति चिह्न क्या है?', 'जिस वस्तु/प्राणी पर क्रिया का व्यापारिक फल पड़े वह ''कर्म कारक'' है, जिसका परसर्ग ''को'' है (जैसे: ''अध्यापक ने छात्र को पढ़ाया'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1984c3f5-3d2b-4f09-8232-f887223d0914', 'कर्म कारक (विभक्ति: ''को'')', true, '7fec746c-1f46-43d7-9ff2-31546e4ac7e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8ae2a29-125b-45b0-83b1-9c2122553d3f', 'कर्ता कारक', false, '7fec746c-1f46-43d7-9ff2-31546e4ac7e8');
