INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8843f123-e168-4a19-8d36-8197f5b4793e', 'संबंध कारक', false, '7fec746c-1f46-43d7-9ff2-31546e4ac7e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97edeb70-80ad-457c-814e-994ee8294031', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'कर्ता जिस साधन या माध्यम की सहायता से क्रिया को संपन्न करता है, उसे कौन-सा कारक कहते हैं और इसका विभक्ति चिह्न क्या है?', 'साधनवाची कारक ''करण कारक'' कहलाता है (विभक्ति: ''से/के द्वारा'' - जैसे: ''उसने चाकू से सेब काटा'', ''कलम से लिखा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d59692c-6197-4315-8ea3-0b98dba1dca6', 'करण कारक (विभक्ति: ''से'' / ''के द्वारा'')', true, '97edeb70-80ad-457c-814e-994ee8294031');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6ed2a3d-7476-497c-89ab-26148eba430e', 'अपादान कारक', false, '97edeb70-80ad-457c-814e-994ee8294031');
