INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26572b39-8d4c-41ae-94fe-db9c5a3c0fad', 'अधिकरण कारक', false, '97edeb70-80ad-457c-814e-994ee8294031');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af701bfc-da7e-4cc1-b090-454f7d3d8399', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'जिसके लिए कोई कार्य किया जाए या जिसे कुछ दिया जाए, उसे कौन-सा कारक कहते हैं और इसका विभक्ति चिह्न क्या है?', 'दान या उपकार के पात्र हेतु ''संप्रदान कारक'' होता है (विभक्ति: ''के लिए'', ''को'' - जैसे: ''माता जी ने भिखारी को भोजन दिया'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a2cfac9-bd4f-4044-bbe4-43c19f4c80a0', 'संप्रदान कारक (विभक्ति: ''के लिए'' / ''को'')', true, 'af701bfc-da7e-4cc1-b090-454f7d3d8399');
