INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10351c7f-974f-4163-a5f3-050064c99d7f', 'कर्ता कारक', false, 'af701bfc-da7e-4cc1-b090-454f7d3d8399');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3a50d78-0988-4d34-976f-b9c41cbe3f90', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'संज्ञा के जिस रूप से किसी वस्तु या प्राणी का दूसरी वस्तु से अलग (पृथक) होने का भाव प्रकट हो, उसे कौन-सा कारक कहते हैं और इसका विभक्ति चिह्न क्या है?', 'अलगाव, पृथक्करण, भय या तुलना के भाव में ''अपादान कारक'' होता है (विभक्ति: ''से'' - जैसे: ''पेड़ से पत्ता गिरा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cf18e1f-841f-4383-bf54-52173e548f32', 'अपादान कारक (विभक्ति: ''से'' - अलग होने के अर्थ में)', true, 'b3a50d78-0988-4d34-976f-b9c41cbe3f90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7b10ff5-2c7e-4d0c-b5d3-9ca3ab385111', 'करण कारक', false, 'b3a50d78-0988-4d34-976f-b9c41cbe3f90');
