INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9560ff40-de21-40bf-8cce-2ed10b7bcc7d', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'संज्ञा या सर्वनाम के जिस रूप से उसका संबंध वाक्य के किसी अन्य संज्ञा/सर्वनाम से प्रकट हो, उसे कौन-सा कारक कहते हैं?', 'पारस्परिक स्वामित्व व संबंध दर्शाने वाला ''संबंध कारक'' होता है (जैसे: ''यह रोहन का घर है'', ''मेरी पुस्तक'')।', NOW()) ON CONFLICT DO NOTHING;
