INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('050a1b79-4295-4292-90fc-f4226579ed97', 'संप्रदान कारक', false, '9560ff40-de21-40bf-8cce-2ed10b7bcc7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2240ea0-c9c9-4f1b-9ec1-726bdc6f3075', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'क्रिया के घटित होने के स्थान, आधार या समय का बोध कराने वाले संज्ञा पद को कौन-सा कारक कहते हैं?', 'क्रिया के आधार (स्थान/काल) का बोधक ''अधिकरण कारक'' कहलाता है (जैसे: ''पक्षी पेड़ पर बैठे हैं'', ''कमरे में पंखा है'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4792edde-9589-4c75-9f00-ec9b2ec5beb7', 'अधिकरण कारक (विभक्ति: ''में'', ''पर'', ''पे'')', true, 'e2240ea0-c9c9-4f1b-9ec1-726bdc6f3075');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9076c08a-fee9-406d-aecf-c9838da254a8', 'अपादान कारक', false, 'e2240ea0-c9c9-4f1b-9ec1-726bdc6f3075');
