INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f80761f-a0bd-47bd-8cc7-f3be1a045709', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'संज्ञा के जिस रूप से किसी को पुकारने, बुलाने, सचेत करने या संबोधित करने का भाव प्रकट हो, उसे कौन-सा कारक कहते हैं?', 'आह्वान या संबोधन हेतु विस्मयादिबोधक चिह्न (!) युक्त ''संबोधन कारक'' प्रयुक्त होता है (जैसे: ''हे प्रभु! रक्षा करो'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd3a590c-9b7c-4dd6-8a9b-e2743fcb7449', 'संबोधन कारक (विभक्ति: ''हे!'', ''अरे!'', ''ओ!'', ''सुनो!'')', true, '8f80761f-a0bd-47bd-8cc7-f3be1a045709');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e2497f0-5ba0-41af-a901-7e298c947f6c', 'अधिकरण कारक', false, '8f80761f-a0bd-47bd-8cc7-f3be1a045709');
