INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('740b2f83-52aa-4553-a1e2-97f6c07c562c', 'अपादान कारक (पेड़ से अलग होने के अर्थ में ''से'' विभक्ति)', true, '3c284e53-8d56-4f25-814a-f277d7c7f260');
