INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f703b15-4a0c-45a6-ab53-bae3b833b4b5', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Medium', 'करण कारक और अपादान कारक दोनों का विभक्ति चिह्न ''से'' होता है। इन दोनों में क्या मूलभूत अंतर है?', 'करण का ''से'' सहायक इंस्ट्रूमेंटल साधन है; अपादान का ''से'' एब्लेटिव सेपरेशन, फियर या ओरिजिन का परिचायक है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0148073c-febe-41c6-ac55-67974c045b04', 'करण कारक में ''से'' का प्रयोग ''साधन/माध्यम'' के रूप में होता है (जैसे: ''कलम से लिखना''), जबकि अपादान कारक में ''से'' का प्रयोग ''अलग होने, डरने या तुलना करने'' के अर्थ में होता है (जैसे: ''पेड़ से गिरना'', ''शेर से डरना'')', true, '8f703b15-4a0c-45a6-ab53-bae3b833b4b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a9bf882-93c7-40a4-a479-7c5f35d7f25e', 'करण कारक केवल इंसानों के लिए आता है', false, '8f703b15-4a0c-45a6-ab53-bae3b833b4b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f93ed25-f2dd-4df1-ad9d-ae68a04e996a', 'अपादान कारक में ''से'' कभी नहीं आता', false, '8f703b15-4a0c-45a6-ab53-bae3b833b4b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81509ad5-9a9f-4334-bfab-80b43dcdfe74', 'कोई अंतर नहीं है', false, '8f703b15-4a0c-45a6-ab53-bae3b833b4b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6baa86c-7571-4a64-a49c-f39e84813b4d', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Medium', 'वाक्य में प्रयुक्त दोनों ''से'' का सही कारक क्रम बताइए:
