INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb9f8750-395f-4af7-9f58-3c42abc9f847', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Medium', 'कर्म कारक और संप्रदान कारक दोनों में ''को'' विभक्ति का प्रयोग होता है। इन दोनों में क्या अंतर है?', 'दानार्थे चतुर्थी (संप्रदान) में जब कोई वस्तु किसी को हमेशा के लिए दी जाए तो ''को'' संप्रदान कारक बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6560e103-9bb9-438c-ac18-348b87521561', 'कर्म कारक में ''को'' क्रिया के प्रभाव/फल को दर्शाता है, जबकि संप्रदान कारक में ''को'' ''देने के भाव'' (उपकार/दान) में ''के लिए'' के स्थान पर आता है (जैसे: ''गरीब को कम्बल दो'')', true, 'cb9f8750-395f-4af7-9f58-3c42abc9f847');
