INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d1624be-2caa-43a8-9e5b-f56fe2eea60f', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Medium', 'सर्वनाम शब्दों में कारक विभक्ति चिह्न जोड़ने पर बनने वाले रूपों का सही युग्म कौन-सा है?', 'सर्वनामों के साथ विभक्तियाँ मिलाकर संश्लिष्ट (synthesized) रूप में लिखी जाती हैं: मैंने, उसे, हमसे, तुम्हारा।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('727e7bbf-5712-4121-8c44-5f8fd40db1e3', 'मैं + ने = मैंने ; वह + को = उसको / उसे ; हम + से = हमसे ; तुम + का = तुम्हारा', true, '5d1624be-2caa-43a8-9e5b-f56fe2eea60f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6a253f9-e49b-4a3e-ac31-90e533257290', 'मैं + ने = मैन्ने ; वह + को = वहको', false, '5d1624be-2caa-43a8-9e5b-f56fe2eea60f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f33d401e-21bd-42fa-9dc1-013072145b9c', 'हम + से = हमोंसे', false, '5d1624be-2caa-43a8-9e5b-f56fe2eea60f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dc5b6a5-6234-496c-8891-a31a9035ec3a', 'तुम + का = तुमाका', false, '5d1624be-2caa-43a8-9e5b-f56fe2eea60f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9e6fa8e-0ee0-4ba7-ad11-4ee937e5a82b', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Medium', 'संज्ञा शब्दों के साथ कारक विभक्तियाँ किस प्रकार लिखी जाती हैं?', 'मानक हिंदी वर्तनी नियम: संज्ञा के साथ परसर्ग अलग (स्पेस देकर) लिखे जाते हैं, जबकि सर्वनाम के साथ जोड़कर लिखे जाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fe8dc2d-af4d-4a43-8120-ed0c7a89e1bf', 'संज्ञा शब्दों से अलग (विश्लिष्ट) हटाकर लिखी जाती हैं (जैसे: ''राम ने'', ''पेड़ पर'', ''घर से'')', true, 'e9e6fa8e-0ee0-4ba7-ad11-4ee937e5a82b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('290b4b5f-1c45-45b7-bab7-eb9dc0e25575', 'संज्ञा के साथ चिपकाकर मिलाकर लिखी जाती हैं', false, 'e9e6fa8e-0ee0-4ba7-ad11-4ee937e5a82b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92dd459a-cee0-4aed-aec6-838882c02a53', 'विभक्तियाँ कभी नहीं लिखी जातीं', false, 'e9e6fa8e-0ee0-4ba7-ad11-4ee937e5a82b');
