INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bfa8fef1-4d9d-4513-83c7-13369b1835bc', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Easy', 'In the decimal system, what does the second place value to the right of the decimal point represent?', 'The second digit to the right of the decimal point represents 1/100 (Hundredths).', NOW()) ON CONFLICT DO NOTHING;
