INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('055650a4-bc4f-46d7-ba2d-1bd5be09000e', 'Thousandths (1/1000)', false, 'bfa8fef1-4d9d-4513-83c7-13369b1835bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4210d2c-bd75-4602-bfda-c98af9409d76', 'Tens (10)', false, 'bfa8fef1-4d9d-4513-83c7-13369b1835bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1be5f75-ed28-4c46-b7c1-d1bd90cb4894', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Easy', 'Write the fraction 7/10 as a Decimal:', '7/10 = 0.7.', NOW()) ON CONFLICT DO NOTHING;
