INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d0c0a51-7c83-4db6-a55d-e818628b7598', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Easy', 'Convert 65 paise into Rupees using Decimals (since ₹1 = 100 paise):', '1 paisa = ₹1/100 -> 65 paise = ₹65/100 = ₹0.65.', NOW()) ON CONFLICT DO NOTHING;
