INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('314db424-cff2-4f4c-868c-525083c4b87c', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Easy', 'Convert 8 cm into Metres using Decimals (since 1 m = 100 cm):', '1 cm = 1/100 m -> 8 cm = 8/100 m = 0.08 m.', NOW()) ON CONFLICT DO NOTHING;
