INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a9d8dad-b979-40df-8b4b-8b5f75c2b719', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Medium', 'Naresh walked 2 km 35 m in the morning and 1 km 7 m in the evening. How much total distance did he walk in kilometres?', '2 km 35 m = 2.035 km; 1 km 7 m = 1.007 km. Total = 2.035 + 1.007 = 3.042 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffa7814c-d2f5-46c9-a48b-5b28daa6e369', '3.042 km (2.035 km + 1.007 km = 3.042 km)', true, '5a9d8dad-b979-40df-8b4b-8b5f75c2b719');
