INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31bfec2d-69fa-4abe-940c-005a4d60bb7d', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Medium', 'Sunita bought 5 kg 75 g of potatoes, 2 kg 500 g of tomatoes, and 1 kg 50 g of onions. What is the total weight of her purchases in kilograms?', '5.075 kg + 2.500 kg + 1.050 kg = 8.625 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('385a845c-35e2-410d-b746-34ebcd5d8109', '8.625 kg (5.075 + 2.500 + 1.050 = 8.625 kg)', true, '31bfec2d-69fa-4abe-940c-005a4d60bb7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('030ce94b-d3a7-4cf7-9824-b85456ff6d6b', '8.125 kg', false, '31bfec2d-69fa-4abe-940c-005a4d60bb7d');
