INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ade982b-d077-463c-a2b2-683f88e28c1c', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Medium', 'Raju bought a book for ₹35.65. He gave a ₹50 note to the shopkeeper. How much money did he get back from the shopkeeper?', '₹50.00 - ₹35.65 = ₹14.35.', NOW()) ON CONFLICT DO NOTHING;
