INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61721ad2-888f-44ae-b1c7-0f1b85b522d6', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Medium', 'Aakash bought vegetables weighing 10 kg in total. Out of this, 3 kg 500 g is onions, 2 kg 75 g is tomatoes, and the rest is potatoes. What is the weight of the potatoes?', 'Total other veggies = 3.500 + 2.075 = 5.575 kg. Potatoes = 10.000 - 5.575 = 4.425 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f5c829e-5b94-46c9-b12f-279a6918aed3', '4.425 kg (10.000 - (3.500 + 2.075) = 10.000 - 5.575 = 4.425 kg)', true, '61721ad2-888f-44ae-b1c7-0f1b85b522d6');
