INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('387f8d4e-95f2-4394-99e6-1471624aa709', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'Match Column I (Fractions) with Column II (Exact Decimal Equivalents):
(a) 1/4   -> (i) 0.25
(b) 3/8   -> (ii) 0.375
(c) 7/20  -> (iii) 0.35
(d) 4/25  -> (iv) 0.16', '1/4 = 0.25; 3/8 = 0.375; 7/20 = 35/100 = 0.35; 4/25 = 16/100 = 0.16.', NOW()) ON CONFLICT DO NOTHING;
