INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1f17b2b-8325-4145-bc2f-676a3caef214', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'Arrange the following decimals in DESCENDING (decreasing) order: 2.2, 2.02, 2.22, 2.002, 2.202', 'Aligning 3 decimal places: 2.220 > 2.202 > 2.200 > 2.020 > 2.002.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78039f34-1cf1-427e-8110-4c5794886e24', '2.22 > 2.202 > 2.2 > 2.02 > 2.002', true, 'e1f17b2b-8325-4145-bc2f-676a3caef214');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e367c1a2-d61e-4d86-8d07-a92cc3e8c5a2', '2.2 > 2.22 > 2.202 > 2.02 > 2.002', false, 'e1f17b2b-8325-4145-bc2f-676a3caef214');
