INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36a4edfe-3610-43c7-bcff-d7966ab712d9', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'A wire of length 20 m is cut into three pieces. The first piece is 4.35 m long and the second piece is 8.7 m long. What is the length of the third piece?', '4.35 + 8.70 = 13.05 m. Remaining = 20.00 - 13.05 = 6.95 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d8ae5f3-a028-4c77-8f45-af696fa96b44', '6.95 m (20.00 - (4.35 + 8.70) = 20.00 - 13.05 = 6.95 m)', true, '36a4edfe-3610-43c7-bcff-d7966ab712d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98178d59-8379-4e82-a0c0-df7a4487d194', '7.95 m', false, '36a4edfe-3610-43c7-bcff-d7966ab712d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b35d9875-9c4a-4b82-bc1d-a7068e3e1606', '6.05 m', false, '36a4edfe-3610-43c7-bcff-d7966ab712d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a880a811-ff3e-4c04-959d-85b201896bd1', '7.05 m', false, '36a4edfe-3610-43c7-bcff-d7966ab712d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6abb15bc-03ba-45b7-9a9b-a1e0ccb34c16', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'What number should be added to the sum of 18.05 and 12.9 to get 40?', '18.05 + 12.90 = 30.95. Required addend = 40.00 - 30.95 = 9.05.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e54ae771-1362-4515-bdad-e3704f5a40cf', '9.05 (40.00 - (18.05 + 12.90) = 40.00 - 30.95 = 9.05)', true, '6abb15bc-03ba-45b7-9a9b-a1e0ccb34c16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88c7b6b5-cb62-4fc4-acc5-c1be32b0032a', '8.95', false, '6abb15bc-03ba-45b7-9a9b-a1e0ccb34c16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8334620-2e3e-4b12-a292-d010aa60c0a5', '9.15', false, '6abb15bc-03ba-45b7-9a9b-a1e0ccb34c16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16459daf-152d-4f5d-bcb3-a5835aba8e5c', '10.05', false, '6abb15bc-03ba-45b7-9a9b-a1e0ccb34c16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b84438a-3097-4a3e-9908-902ca71466b4', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'How is the decimal 1.7 represented accurately on a number line?', '1.7 = 1 + 7/10, situated 7/10ths of the distance from 1 towards 2 on the number line.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('573a8531-357d-4784-88ed-6e6f7047fce8', 'Between integers 1 and 2, dividing the unit length into 10 equal subdivisions and marking the 7th subdivision from 1', true, '7b84438a-3097-4a3e-9908-902ca71466b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6c272d3-4f68-47a8-96c2-a446a45889c0', 'Between 0 and 1 at 7th subdivision', false, '7b84438a-3097-4a3e-9908-902ca71466b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52c232e0-a60a-4c5e-887b-0a9f6085961e', 'Between 7 and 8', false, '7b84438a-3097-4a3e-9908-902ca71466b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('164130b3-688f-45ce-9087-ac4d96a421a5', 'Directly at 1', false, '7b84438a-3097-4a3e-9908-902ca71466b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('053eeec5-06c5-4a08-869d-52a3d478af1e', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'What is the expanded form of the decimal number 253.408 in place-value notation?', '200 + 50 + 3 + 4/10 + 0/100 + 8/1000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10c86a83-8c0a-48e4-9ca3-95817dd00983', '2 × 100 + 5 × 10 + 3 × 1 + 4 × (1/10) + 0 × (1/100) + 8 × (1/1000)', true, '053eeec5-06c5-4a08-869d-52a3d478af1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1bfd522-538f-40bf-b187-19f07c24e620', '2 × 100 + 5 × 10 + 3 × 1 + 4 × 10 + 8 × 100', false, '053eeec5-06c5-4a08-869d-52a3d478af1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5c45706-fb65-4d76-a4da-e5e2911b0a13', '253 + 408/100', false, '053eeec5-06c5-4a08-869d-52a3d478af1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3701df0d-908f-4181-97ef-0a5cf0279ce8', '200 + 50 + 3 + 4/100 + 8/10', false, '053eeec5-06c5-4a08-869d-52a3d478af1e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3202b2b-766f-4410-9675-38f7afdf148f', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'Express 725 paise as rupees, 485 cm as metres, and 3050 g as kilograms respectively in Decimals:', '725 paise = ₹7.25; 485 cm = 4.85 m; 3050 g = 3.050 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96b747ee-8210-4af2-9487-2e585b667c30', '₹7.25 ; 4.85 m ; 3.050 kg', true, 'd3202b2b-766f-4410-9675-38f7afdf148f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37ea6f28-ebf2-4cb0-856b-2339ea366b66', '₹72.5 ; 48.5 m ; 30.5 kg', false, 'd3202b2b-766f-4410-9675-38f7afdf148f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfe804b5-9f8c-4991-9b19-944a5fb48b60', '₹0.725 ; 0.485 m ; 0.305 kg', false, 'd3202b2b-766f-4410-9675-38f7afdf148f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b42740d-9fde-44b5-9736-a686a10d26bc', '₹7.25 ; 48.5 m ; 3.5 kg', false, 'd3202b2b-766f-4410-9675-38f7afdf148f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('70df5b52-1469-46ff-aa66-87d4f8073704', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'A container has 15.5 litres of milk. If 3.75 litres is used for tea and 6.8 litres is used for sweets, how much milk is left in the container?', 'Used = 3.75 + 6.80 = 10.55 L. Remaining = 15.50 - 10.55 = 4.95 litres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88779434-cd2e-47d0-93f8-e8f2e936b04c', '4.95 litres (15.50 - (3.75 + 6.80) = 15.50 - 10.55 = 4.95 L)', true, '70df5b52-1469-46ff-aa66-87d4f8073704');
