INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04713fc1-9442-43af-8d32-9629a966a369', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What strict warning did Uncle give Rasheed before leaving him to meet some friends at the fair?', 'Uncle strictly cautioned Rasheed neither to buy anything nor to wander away while he was away.', NOW()) ON CONFLICT DO NOTHING;
