INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ea49ccb-ca40-4c51-a62c-8c55b6c0f081', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What was the name of the shop that caught Rasheed''s attention with numbered discs?', 'The stall was called ''Lucky Shop'', run by a middle-aged shopkeeper who seemed neither too smart nor too lazy.', NOW()) ON CONFLICT DO NOTHING;
