INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a8846eb-0562-4ee2-8a47-7c31a8a53334', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'How much did it cost to try one''s luck by picking six numbered discs at the Lucky Shop?', 'The rule required paying 50 paise to choose six numbered discs, summing the numbers to claim the matching article.', NOW()) ON CONFLICT DO NOTHING;
