INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('812aed71-c8d9-4ad6-b965-d4ac38136f45', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What valuable prize did an old man apparently win at the Lucky Shop and sell back to the shopkeeper for ₹15?', 'An elderly player picked discs summing to 15, won a handsome wall clock, and happily sold it back for ₹15.', NOW()) ON CONFLICT DO NOTHING;
