INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dfbcecf0-a153-46f4-8666-667cad1202c6', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What did Rasheed win on his first couple of attempts at the Lucky Shop?', 'Rasheed won cheap items (two pencils, an ink bottle) which the shopkeeper bought back for a few paise.', NOW()) ON CONFLICT DO NOTHING;
