INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d3265ce-ea44-4dc9-a4bb-bcab40f34761', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What happened to all of Rasheed''s pocket money as he kept playing in the hope of winning a big prize?', 'Gambling repeatedly in vain hope, Rasheed lost all his money to the cunning shopkeeper.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62de4cce-9488-4656-bc41-a06827b25646', 'He lost every single paisa he had, ending up completely empty-handed', true, '5d3265ce-ea44-4dc9-a4bb-bcab40f34761');
