INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0cda6d4-6c27-456e-b5b0-8a7a2469c436', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'In the supplementary story ''A Pact with the Sun'', what was Saeeda''s ailing mother suffering from for a long time?', 'Saeeda''s mother had been suffering from chronic fever, body ache, and cough, confined to a dark dingy room.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d417fa97-d021-4f9c-8cf4-1feb16f1442c', 'Fever, body ache, joint pain, and chronic unhealed cough/illness', true, 'b0cda6d4-6c27-456e-b5b0-8a7a2469c436');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f1f23db-b298-4b8c-89eb-357d25614858', 'Broken leg', false, 'b0cda6d4-6c27-456e-b5b0-8a7a2469c436');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c3faf68-b67f-415a-8460-ce00fdc2aa32', 'Loss of vision', false, 'b0cda6d4-6c27-456e-b5b0-8a7a2469c436');
