INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('239fa00c-ba9b-4b02-a8c8-988853f5e55e', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What foolish advice had orthodox quacks given to Saeeda''s mother before the wise specialist doctor arrived?', 'Quacks strictly forbade fresh air, sunshine, and normal food, worsening her physical deterioration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d8e2240-11a6-4eaa-a2b9-9b652f38bb65', 'To stay locked in a dark, dingy small room with closed doors/windows, deprived of fresh air and sunlight', true, '239fa00c-ba9b-4b02-a8c8-988853f5e55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d8b7ce8-d3ae-4909-a220-2448bfa2a896', 'To go on a world tour', false, '239fa00c-ba9b-4b02-a8c8-988853f5e55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e7f3016-1efa-4bf6-8420-fedc329e0d7b', 'To swim in cold water', false, '239fa00c-ba9b-4b02-a8c8-988853f5e55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b194998-0a81-4d08-8b9a-29cba4a93306', 'To eat only sweets', false, '239fa00c-ba9b-4b02-a8c8-988853f5e55e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f3a6e0d-0746-427b-bb2e-844c90bf36ec', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What crucial life-saving prescription did the learned specialist physician give to Saeeda''s mother?', 'The doctor prescribed normal diet plus one hour of daily morning sunshine and fresh air as essential medicine.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7bbff76-683b-47d7-9b7e-4833790d0c67', 'To move into a larger room with open windows and sit in the bright morning sunshine for an hour every day while breathing fresh air', true, '9f3a6e0d-0746-427b-bb2e-844c90bf36ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fa76298-2b86-4639-990e-df8f3869e7b5', 'To take 50 pills a day in a dark room', false, '9f3a6e0d-0746-427b-bb2e-844c90bf36ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96c67086-3113-48cc-924c-cb3720fcd267', 'To stay in bed without food', false, '9f3a6e0d-0746-427b-bb2e-844c90bf36ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b07fd6b-00fa-4a77-83f8-e2c8022121a9', 'To move to the cold mountains', false, '9f3a6e0d-0746-427b-bb2e-844c90bf36ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6b7e49f-b136-4a10-b5b5-f5c39561b82b', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'To whom did little Saeeda make a heartfelt secret pact/prayer in the courtyard in the evening?', 'Saeeda made a solemn pact with the evening sunrays to arrive the following morning with warmth for her mother.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4db2dd02-b45f-4c17-aa68-ae4eaf3212df', 'To the departing rays of the setting Sun, asking them to come next morning with warmth and brightness to cure her sick mother', true, 'b6b7e49f-b136-4a10-b5b5-f5c39561b82b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e36682d0-873e-44f3-9980-5c0842b54a07', 'To the birds in the tree', false, 'b6b7e49f-b136-4a10-b5b5-f5c39561b82b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee4765ce-6ab5-4876-933c-1711942e858b', 'To the rain clouds', false, 'b6b7e49f-b136-4a10-b5b5-f5c39561b82b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24aa2b59-dcf4-48ce-93c3-b3e845a6f0c5', 'To the moon', false, 'b6b7e49f-b136-4a10-b5b5-f5c39561b82b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af9029bf-1344-43ba-ae83-8cdd72f6c1a8', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'How did Uncle react when he saw Rasheed looking utterly sad and dejected with an empty pocket?', 'Uncle consoled Rasheed with gifts and explained how the shopkeeper tricked naive customers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c905d0-fbc2-4e2f-86dc-02e70c33e0bc', 'Uncle smiled kindly, bought him a beautiful umbrella, biscuits, sweets, and other gifts, and gently explained the reality of the game', true, 'af9029bf-1344-43ba-ae83-8cdd72f6c1a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e676b2d0-b555-441f-89a6-cfd02b52ab1d', 'Uncle scolded and beat him harshly', false, 'af9029bf-1344-43ba-ae83-8cdd72f6c1a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e63cb40-709a-4125-a751-2539bc88cbb2', 'Uncle punished Bhaiya', false, 'af9029bf-1344-43ba-ae83-8cdd72f6c1a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af0a2ff3-8df2-4d6b-a8d4-7cf8a25ffd01', 'Uncle complained to the police', false, 'af9029bf-1344-43ba-ae83-8cdd72f6c1a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a5e9b21-4467-4b2b-8918-cd269009c138', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What secret truth did Uncle reveal to Rasheed about the old man and the boy who won expensive prizes at the Lucky Shop?', 'Uncle revealed that the ''winners'' were shills working in league with the shopkeeper to deceive gullible spectators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc589812-9da4-4fe8-93f5-76d4fbcdc5b6', 'They were all accomplices and friends of the shopkeeper, playing rigged tricks to tempt greedy onlookers into gambling away their money', true, '0a5e9b21-4467-4b2b-8918-cd269009c138');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('566a0cb7-663b-42a9-8ace-b79ffd70d4d5', 'They were the luckiest people in the world', false, '0a5e9b21-4467-4b2b-8918-cd269009c138');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('549c1aea-7505-49e1-a37b-5fbbd46429af', 'They were professional magicians', false, '0a5e9b21-4467-4b2b-8918-cd269009c138');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65a2cc50-4551-416b-a4d2-9d580be4f2d7', 'They owned the shop', false, '0a5e9b21-4467-4b2b-8918-cd269009c138');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e82c885-d123-445a-9bd5-32cae3ccb5c0', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What important life lesson did Uncle teach Rasheed about ''Bad Luck'' versus ''Foolishness''?', 'Uncle advised him to forget the incident and realize that tricksters exploit greed rather than genuine luck.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44e78e5f-0d43-48fd-8fdc-fadcb5218821', 'It was NOT bad luck at all, but pure gullibility and foolishness; one should never fall prey to get-rich-quick gambles or rigged games of chance', true, '9e82c885-d123-445a-9bd5-32cae3ccb5c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c06f4e5-0df8-4f46-bb5d-a27656fadac0', 'Rasheed was born under an unlucky star', false, '9e82c885-d123-445a-9bd5-32cae3ccb5c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87e27b07-c38c-423a-b077-4990b9a8ca2a', 'Fairs should be banned completely', false, '9e82c885-d123-445a-9bd5-32cae3ccb5c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54319976-f394-456a-ba3b-caa3798c4f06', 'Children should never carry umbrellas', false, '9e82c885-d123-445a-9bd5-32cae3ccb5c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f64cece5-b216-4edb-b2fa-be50079cc0bc', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'Why were the sunrays determined to break through the thick, dark army of clouds the next morning despite the Sun King''s hesitation?', 'Bound by their sacred promise to Saeeda, the loyal sunrays pierced the overcast clouds to fulfill their word.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f91e2ce1-ff67-45e5-89ec-e5baa1ff2a8f', 'Because they had given their word of honour to little Saeeda, and breaking their promise would make them liars in the eyes of humans', true, 'f64cece5-b216-4edb-b2fa-be50079cc0bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b00c1a0b-d614-4607-b302-9c2b5ce6749f', 'Because they hated clouds', false, 'f64cece5-b216-4edb-b2fa-be50079cc0bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ba0c4bf-b425-412e-8409-7afe78978327', 'Because they wanted to burn the earth', false, 'f64cece5-b216-4edb-b2fa-be50079cc0bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('318bc117-6ccb-4d32-91c3-7624f51c821c', 'Because they were cold', false, 'f64cece5-b216-4edb-b2fa-be50079cc0bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c516542-66b9-45d1-a3f1-340448a50e05', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What happened when the bright, warm morning sunrays bathed Saeeda''s mother as she lay in the courtyard?', 'Sunlight and fresh air rejuvenated her immune system, bringing swift, joyful physical recovery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ad691b7-b99a-426d-8e9a-b3450db7ec4f', 'Her pale face glowed with fresh vitality, her eyes sparkled, tears of joy welled up, and she recovered her health rapidly', true, '8c516542-66b9-45d1-a3f1-340448a50e05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3766d923-1905-4f60-b976-032bace3afd3', 'She felt too hot and went inside', false, '8c516542-66b9-45d1-a3f1-340448a50e05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec558155-3947-48b7-b308-86755e872226', 'She got angry at Saeeda', false, '8c516542-66b9-45d1-a3f1-340448a50e05');
