INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c5ba2ae-673f-48c9-9ca7-b84163cecf27', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What central scientific and health message is conveyed in ''A Pact with the Sun'' by Zakir Husain?', 'The story highlights the therapeutic power of sunshine (Vitamin D) and fresh air over confining darkness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a8a3d5b-2497-4747-9ac0-626e731a5255', 'Sunlight and fresh open air are nature''s supreme indispensable medicines for human vitality, mental health, and physical healing', true, '5c5ba2ae-673f-48c9-9ca7-b84163cecf27');
