INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32069e35-a4d1-4a47-be43-94f3ea79b0fc', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'Who is the eminent author of the original Urdu classic story ''A Pact with the Sun''?', 'Dr. Zakir Husain, eminent educationist and 3rd President of India, penned this allegorical children''s classic.', NOW()) ON CONFLICT DO NOTHING;
