INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ea4b46c-0c06-470e-9724-03aa720a4cc0', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'In the poem ''Vocation'' by Rabindranath Tagore, what three workers does the schoolboy observe and envy throughout his day?', 'Tagore''s young narrator envies the unconstrained freedom of the bangle-hawker, the gardener, and the night watchman.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb0f437-0536-4e19-89c4-d7b2cfd4b0b5', 'The Hawker selling bangles (10 AM), the Gardener digging soil (4 PM), and the Watchman swinging his lantern at night (dark evening)', true, '9ea4b46c-0c06-470e-9724-03aa720a4cc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('275adf07-d93a-4937-95d8-06a569e215e0', 'A carpenter, a doctor, and a pilot', false, '9ea4b46c-0c06-470e-9724-03aa720a4cc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df7c42bb-1e82-4fe4-81d0-1a8e77e0d2f9', 'A farmer, a soldier, and a sailor', false, '9ea4b46c-0c06-470e-9724-03aa720a4cc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d967eccd-aec0-4ca3-af41-7e4daea8202a', 'A teacher, a painter, and a singer', false, '9ea4b46c-0c06-470e-9724-03aa720a4cc0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2ea98ae-69d8-43b0-84ef-8993e3318237', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'Why does the young schoolboy in Tagore''s poem ''Vocation'' envy the Gardener?', 'The boy yearns for the unrestricted physical freedom to get dirty and dig in nature without parental reprimand.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7effae2c-0c56-48e1-b692-ecdeaed84fb9', 'Because the gardener bakes in the sun and gets soaked in rain, soils his clothes with mud, and nobody scolds him or stops him from digging', true, 'f2ea98ae-69d8-43b0-84ef-8993e3318237');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('830d92af-cc07-486d-96f7-464d66950a54', 'Because the gardener gets to eat flowers', false, 'f2ea98ae-69d8-43b0-84ef-8993e3318237');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47650fb0-4f33-4a2e-9a79-62ea19288de8', 'Because the gardener has a big house', false, 'f2ea98ae-69d8-43b0-84ef-8993e3318237');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('064b5467-3775-46ab-9cd8-55df17a2aa8b', 'Because the gardener never works', false, 'f2ea98ae-69d8-43b0-84ef-8993e3318237');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb463aad-9b21-4cb8-ad29-3df4472a7df5', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'Why does the schoolboy in ''Vocation'' wish to become a Night Watchman?', 'The child desires nocturnal freedom, roaming open streetscapes beneath starlit skies instead of early bedtime rules.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f81eabc0-b709-4f5a-a805-a25be1b09cbe', 'To walk the lonely dark streets all night chasing shadows with his glowing lantern without ever being ordered to go to bed', true, 'fb463aad-9b21-4cb8-ad29-3df4472a7df5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('590935a8-db39-4545-a79f-51a7f58acef1', 'To catch thieves with a sword', false, 'fb463aad-9b21-4cb8-ad29-3df4472a7df5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5bcba8d-b959-4aa1-b249-91308815fb46', 'To sleep all night on a bench', false, 'fb463aad-9b21-4cb8-ad29-3df4472a7df5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d746358d-8f59-47fb-9ef9-8c46ab6d099b', 'To blow a whistle loudly', false, 'fb463aad-9b21-4cb8-ad29-3df4472a7df5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c57dc95-8023-48b4-915c-e445894f91e4', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What does the word ''Trifles'' mean in ''A Game of Chance''?', '''Trifles'' refers to cheap, trivial items (such as small pencils, cheap ink) worth negligible money.', NOW()) ON CONFLICT DO NOTHING;
