INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71f0399f-51f5-4445-acb1-956a93b527a5', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What does the phrase ''to play a trick on someone'' mean in Uncle''s explanation?', '''To play a trick'' means using deceptive stratagems to dupe an unsuspecting mark.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('551d9a28-c628-4a74-a93d-363551ed984b', 'To deceive, cheat, or mislead someone cunningly for one''s own selfish gain', true, '71f0399f-51f5-4445-acb1-956a93b527a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dbabe93-8d41-4d4d-9d9d-aa71c8a75ff7', 'To perform a magic show for fun', false, '71f0399f-51f5-4445-acb1-956a93b527a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e16b1aaa-7644-46f5-baa3-ab6792406056', 'To play football together', false, '71f0399f-51f5-4445-acb1-956a93b527a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('701be2f7-7294-4cdc-84a8-1c1531d865c2', 'To buy someone a gift', false, '71f0399f-51f5-4445-acb1-956a93b527a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f974dce2-2dea-4b74-8b7c-f7bf880a4674', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'Why was the shopkeeper described as ''neither too young nor too old, neither smart nor lazy''?', 'His nondescript facade disarmed suspicion, making the rigged game appear benign and authentic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ea37178-6295-4fa1-aa72-f20c9b22903a', 'To maintain an innocent, ordinary, harmless appearance so that unsuspecting customers would not suspect his deceitful scheme', true, 'f974dce2-2dea-4b74-8b7c-f7bf880a4674');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8ea13d5-981a-4f32-9b6f-9093321216c3', 'Because he was sick', false, 'f974dce2-2dea-4b74-8b7c-f7bf880a4674');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7a84c52-bfe7-4f6e-9950-d2912904c59d', 'Because he was very sleepy', false, 'f974dce2-2dea-4b74-8b7c-f7bf880a4674');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bdc17f6-b77d-4681-8a6e-394522f046f3', 'Because he was a king in disguise', false, 'f974dce2-2dea-4b74-8b7c-f7bf880a4674');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ec1fff8-600a-4a3d-b141-7b8251ace7ce', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What psychological weakness in Rasheed did the shopkeeper exploit to make him lose all his money?', 'The gambler''s fallacy and lure of easy riches seduced Rasheed into reckless stakes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ec4bb93-bb2d-4ddf-8e64-a4b1113ae8e2', 'His temptation, greed, and false pride that he could win a costly prize like the other shill players', true, '1ec1fff8-600a-4a3d-b141-7b8251ace7ce');
