INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e77aa9a-417c-45f5-807c-42f71623ba22', 'His hunger for food', false, '1ec1fff8-600a-4a3d-b141-7b8251ace7ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2726ded2-2f79-4399-88ce-e26b06f10ea8', 'His anger at his uncle', false, '1ec1fff8-600a-4a3d-b141-7b8251ace7ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9240cc6-1cb3-41b7-bac6-74d8fd2db987', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'How did little Saeeda communicate with the sunrays in the courtyard?', 'The story personifies nature responding to the pure, heartfelt language of a child''s filial devotion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e18eb33-13a8-4505-b7ae-a78b7a19ef00', 'In her own special innocent language of childhood love, which nature and the elements understood perfectly', true, 'a9240cc6-1cb3-41b7-bac6-74d8fd2db987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('465e5f54-8f2f-4375-856a-bf6b5efe3e0e', 'Using a telephone', false, 'a9240cc6-1cb3-41b7-bac6-74d8fd2db987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc4dceda-6c3d-4904-a84c-376fc66bed1c', 'By writing a letter on paper', false, 'a9240cc6-1cb3-41b7-bac6-74d8fd2db987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc487152-042a-4897-834b-8969d36b4c0b', 'Through a loudspeaker', false, 'a9240cc6-1cb3-41b7-bac6-74d8fd2db987');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e94ae01b-4f73-4211-ab68-56b65f6d7157', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What poetic yearning lies at the heart of Rabindranath Tagore''s poem ''Vocation''?', 'Tagore captures childhood''s innocence, viewing adult manual labor as heroic liberation from disciplinary domestic constraints.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31b56516-9f50-49f2-958f-cbc366af483d', 'A child''s romantic longing for complete autonomy, freedom from rigid adult schedules, and intimate immersion in the open outdoor world', true, 'e94ae01b-4f73-4211-ab68-56b65f6d7157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c952780-a957-4bf1-9e37-ab78f5fa5fc0', 'A desire to become a king', false, 'e94ae01b-4f73-4211-ab68-56b65f6d7157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6347ceb8-9512-4f2e-917f-d4a33887f5d0', 'A wish to avoid learning books', false, 'e94ae01b-4f73-4211-ab68-56b65f6d7157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9046663e-3af9-44ff-9aea-bf021b49f659', 'A plan to build a ship', false, 'e94ae01b-4f73-4211-ab68-56b65f6d7157');
