INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72a90a60-d64a-4be1-b262-0ab44a51fb86', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Hard', 'Analyze the allegorical conflict between the Sunrays and the dark clouds in ''A Pact with the Sun'':', 'The breakthrough of rays allegorizes enlightened rational medicine and steadfast fidelity triumphing over superstitious confinement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f21fd94c-74e5-4114-8cde-fdc09ef9aef0', 'The sunrays represent life-giving truth, healing, and fidelity to moral vows overcoming the suffocating, obscurantist darkness of dogmatic quackery and despair', true, '72a90a60-d64a-4be1-b262-0ab44a51fb86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38c6236c-a915-4d7b-91d1-aba57d47e471', 'A literal battle with cannons in the sky', false, '72a90a60-d64a-4be1-b262-0ab44a51fb86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f07d365-4163-4c76-879c-36f8a243fb18', 'A meteor striking the earth', false, '72a90a60-d64a-4be1-b262-0ab44a51fb86');
