INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a13b61c2-1d81-469a-8540-cc648d4deea7', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Hard', 'What deep psychological insight did Uncle share when he told Rasheed: ''Do not tell anybody at home about your bad luck or your foolishness''?', 'Uncle balances empathetic emotional protection with constructive moral mentorship, preserving the child''s dignity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b48910b4-86b3-4f6f-9f42-4d39ca62cc02', 'To protect the boy''s self-esteem and dignity from unnecessary family mockery while ensuring he internalized the core moral lesson privately', true, 'a13b61c2-1d81-469a-8540-cc648d4deea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63f75a5d-6b5a-4111-b4a9-6ddd9abf2a60', 'To hide crimes from the police', false, 'a13b61c2-1d81-469a-8540-cc648d4deea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa45b00f-1599-4996-b63a-53ec580ddab3', 'Because Uncle was afraid of parents', false, 'a13b61c2-1d81-469a-8540-cc648d4deea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ad739c9-a222-4e09-b1cf-94db4a970cb1', 'Because the money was stolen', false, 'a13b61c2-1d81-469a-8540-cc648d4deea7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a590b44-33a6-4784-9924-a3b1e6c522e8', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Hard', 'In ''A Pact with the Sun'', how is the personification of the Sun''s court depicted?', 'Anthropomorphic personification endows celestial entities with royal court hierarchy, ethical agency, and compassionate vows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5334e970-7adb-4c53-8f75-e69a40e9ec64', 'The Sun is portrayed as a majestic sovereign king, and the rays are his dutiful courtiers and celestial emissaries bound by sacred honour', true, '4a590b44-33a6-4784-9924-a3b1e6c522e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2375fdc8-300f-4b07-bca4-a2b71e22c9f5', 'As a burning furnace of coal', false, '4a590b44-33a6-4784-9924-a3b1e6c522e8');
