INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89be0999-7d59-42e2-97d0-18a945e32105', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Hard', 'What is the meaning of the idiom ''to try one''s luck'' in English?', '''To try one''s luck'' signifies taking a calculated risk in a probabilistic endeavor.', NOW()) ON CONFLICT DO NOTHING;
