INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f06e0b3-2c78-4cc7-b95d-42bc21907a03', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Hard', 'Why does the schoolboy in ''Vocation'' find the routine of school and bedtime oppressive compared to street workers?', 'Tagore captures childhood romanticism where external discipline contrasts with the perceived romantic freedom of street life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7fbc834-255c-4831-8e33-2a95c5b6a0e6', 'To a young child''s imagination, structured adult discipline (timetables, homework, bedtime) feels restrictive, while manual outdoor trades appear full of thrilling adventures', true, '5f06e0b3-2c78-4cc7-b95d-42bc21907a03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0815d02c-71d2-4cbb-b996-240769f0e059', 'Because school was broken', false, '5f06e0b3-2c78-4cc7-b95d-42bc21907a03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93521f9a-5cf9-4c3a-97df-836797c77399', 'Because he wanted to sleep in mud', false, '5f06e0b3-2c78-4cc7-b95d-42bc21907a03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5ecd6d3-62da-4fb6-95a6-f2f4d8cb31bf', 'Because the teacher was a giant', false, '5f06e0b3-2c78-4cc7-b95d-42bc21907a03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a36830c9-f9e5-4dbb-b01c-89c2b305b221', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Hard', 'What overarching humanist philosophy unites the three literary texts in Class 6 Chapter 8?', 'The stories harmonize childhood innocence, ethical mentorship, and harmonious coexistence with nature''s radiant forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a646610-aa66-47c6-bbdc-4dce00009408', 'The celebration of innocent childhood vulnerability, the necessity of protective wisdom, and the healing benevolence of nature and truth', true, 'a36830c9-f9e5-4dbb-b01c-89c2b305b221');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58bced19-14bf-4082-b1ed-d7f69e752ccd', 'The absolute superiority of city life over village life', false, 'a36830c9-f9e5-4dbb-b01c-89c2b305b221');
