INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb2ece9b-9974-4841-baf1-8494671ee91e', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Medium', 'How many Global Biodiversity Hotspots overlap with the territory of India?', 'India hosts portions of 4 global biodiversity hotspots: 1. Himalayas, 2. Western Ghats-Sri Lanka, 3. Indo-Burma, and 4. Sundaland.', NOW()) ON CONFLICT DO NOTHING;
