INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40643f3a-e1b5-496a-8922-83370f3ca217', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Medium', 'What is the primary objective of the ''Montreal Protocol'' (1987), universally ratified as one of the most successful international environmental treaties?', 'The Montreal Protocol phased out chlorofluorocarbons, leading to the gradual healing of the Antarctic ozone hole.', NOW()) ON CONFLICT DO NOTHING;
