INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89a0c751-84aa-4271-856d-3c15618b7c04', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'What is the unique marine mammal species known as the ''Sea Cow'' (Dugong dugon), herbivorous and protected in the Gulf of Mannar and Palk Bay Dugong Conservation Reserve?', 'Dugongs are endangered sirenians grazing exclusively on coastal seagrass beds in Tamil Nadu''s Palk Bay and Andaman waters.', NOW()) ON CONFLICT DO NOTHING;
