INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('888488e7-75dc-4076-8b39-689de1588fb6', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'Which high-altitude mountain lake in Ladakh at 4,350 m altitude is a Ramsar wetland site famous for breeding colonies of the rare Black-necked Crane and Bar-headed Geese?', 'Tso Kar and Tsomoriri in Changthang, Ladakh provide alpine nesting wetlands for vulnerable Black-necked Cranes (Grus nigricollis).', NOW()) ON CONFLICT DO NOTHING;
