INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3aab2599-443a-41e6-8805-82c766e65a25', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'Who was the renowned environmental activist and forester from Assam known as the ''Forest Man of India'', who single-handedly planted an entire 1,360-acre forest (Molai Forest) over 30 years on a barren Brahmaputra sandbar?', 'Jadav Payeng created a thriving forest ecosystem single-handedly on Majuli sandbars, attracting elephants, tigers, and rhinos.', NOW()) ON CONFLICT DO NOTHING;
