INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('687f23a8-b79e-47c3-ae90-ac9c2957b48a', 'The growth of large trees in forests', false, '720f2345-1283-4e8e-b172-9ca3da11739c');
