INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d880ec1b-e702-408b-96b7-a5dc08259a34', 'The magnification of cells under a microscope', false, '720f2345-1283-4e8e-b172-9ca3da11739c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96b3e3be-9190-4f6e-832c-1ea1d8306bc4', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'Why did the populations of three species of vultures (Gyps species) in India collapse by over 99% during the 1990s, leading to a catastrophic ecological crisis?', 'Diclofenac residues in livestock carcasses proved lethally nephrotoxic to vultures, leading to a total national veterinary ban on diclofenac.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5ccc46f-f74b-4008-bdee-547669d042b2', 'Veterinary use of the non-steroidal anti-inflammatory drug ''Diclofenac'' in cattle, which caused acute renal failure and visceral gout in scavenging vultures', true, '96b3e3be-9190-4f6e-832c-1ea1d8306bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('952d07d5-4bd4-4ed2-8fc4-b9a7b89e4283', 'Deforestation of all tall trees', false, '96b3e3be-9190-4f6e-832c-1ea1d8306bc4');
