INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e4e34df-aea7-4f95-bcd6-d2311a2253c4', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'Which ancient tribal forest community in the Niyamgiri hills of Odisha successfully asserted their sacred ecological rights under the Forest Rights Act to save their mountain from bauxite mining?', 'The Dongria Kondh venerate the Niyamgiri ranges as Niyam Raja, winning a historic Supreme Court forest rights consensus in 2013.', NOW()) ON CONFLICT DO NOTHING;
