INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('133478d7-a1e9-4ba0-8222-a5bf8e8d8c1e', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'What is the primary objective of the ''International Solar Alliance'' (ISA), headquartered in Gurugram, India, co-founded by India and France in 2015?', 'The ISA coordinates over 120 member states to unlock $1 trillion in solar infrastructure deployment under the ''One Sun One World One Grid'' vision.', NOW()) ON CONFLICT DO NOTHING;
