INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f62d57b-8aec-4669-8518-4f69557bc228', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'Which season occurs in India from December to February when the sun rays do not fall directly in the region, bringing cool temperatures?', 'During winter (Dec–Feb), oblique solar rays over Northern India cause temperatures to drop sharply.', NOW()) ON CONFLICT DO NOTHING;
