INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63006092-2a27-4027-8038-402c59cad14f', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Why do the coastal states of Tamil Nadu and Andhra Pradesh receive a major part of their annual rainfall during the ''Retreating Monsoon'' (Autumn season in October & November)?', 'Retreating monsoonal winds pick up marine moisture crossing the Bay of Bengal, causing heavy rainfall along the Coromandel coast.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0bae811-6ea6-467b-8bcf-40e3170a4afe', 'Winds blow back from the mainland towards the Bay of Bengal, picking up moisture over the Bay of Bengal and striking the Coromandel coast (Northeast Monsoon)', true, '63006092-2a27-4027-8038-402c59cad14f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaa94256-6ba4-46b2-b2b7-76624e549fd8', 'Because snow melts in the Himalayas', false, '63006092-2a27-4027-8038-402c59cad14f');
