INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('afc25723-7eee-4348-9c4d-a68e8b95d189', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What are the four primary factors that influence and determine the climate of any place on Earth?', 'Climate drivers: 1. Latitude, 2. Altitude, 3. Continentality / distance from sea, and 4. Topographic relief barriers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13384886-2e6c-4828-a026-dc686b2922d3', 'Location (Latitude), Altitude (Height above sea level), Distance from the sea, and Relief (Topography)', true, 'afc25723-7eee-4348-9c4d-a68e8b95d189');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1f053be-42ca-4c12-8789-50d2ecfda2fa', 'Number of cars, houses, trains, and planes', false, 'afc25723-7eee-4348-9c4d-a68e8b95d189');
