INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('767dfe82-ecb7-4c36-a3b2-3e86cf892eca', 'Color of clouds, birds, rivers, and trees', false, 'afc25723-7eee-4348-9c4d-a68e8b95d189');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('718dee52-5d8b-49ed-b76a-be03a933607a', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Why do coastal places like Mumbai, Kolkata, and Chennai experience an ''Equable Climate'' (moderate temperature with neither extreme hot nor extreme cold), whereas Delhi and Jaipur experience ''Extreme Climate''?', 'High specific heat capacity of seawater dampens temperature extremes in maritime coastal regions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2766b0b-1fbf-4fae-8565-d16a3c62e12d', 'Proximity to the vast ocean provides a moderating maritime sea breeze, whereas interior landlocked places suffer high continental temperature variations', true, '718dee52-5d8b-49ed-b76a-be03a933607a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04c1cda3-0bc2-46fd-b9a4-4c405d623012', 'Because coastal cities have more air conditioners', false, '718dee52-5d8b-49ed-b76a-be03a933607a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6270acad-544e-4d16-8ac9-8285159c18be', 'Because the sun doesn''t shine on oceans', false, '718dee52-5d8b-49ed-b76a-be03a933607a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('558d5cd6-e8ff-4312-952c-b3c9914e2dad', 'Because Delhi has no rain', false, '718dee52-5d8b-49ed-b76a-be03a933607a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a63e90a3-03a8-4fa7-b291-ba90372fd554', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What are the two extreme temperature locations in India: Drass (Ladakh) and Jaisalmer (Rajasthan)?', 'Drass in Ladakh is the 2nd coldest inhabited place on Earth (-45°C), while Thar''s Jaisalmer reaches +50°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29573167-85b5-4149-9680-f63e4f4b729c', 'Drass is freezing cold with temperatures dropping to -45°C, while Jaisalmer is scorching hot with summer temperatures touching 50°C', true, 'a63e90a3-03a8-4fa7-b291-ba90372fd554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dcb362c-13e5-47de-968b-c37c52b97cf2', 'Both are freezing ice caps', false, 'a63e90a3-03a8-4fa7-b291-ba90372fd554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4b22817-009f-4e57-bbec-216472282579', 'Both are scorching hot deserts', false, 'a63e90a3-03a8-4fa7-b291-ba90372fd554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbf1bc4c-99cf-4de4-b6dd-9b25298cb08c', 'Both have identical moderate temperatures', false, 'a63e90a3-03a8-4fa7-b291-ba90372fd554');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('545df1b4-5401-4764-bbf2-2a1bc7a80645', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'How are Thorny Bushes and vegetation in arid desert regions (Rajasthan, Gujarat, dry Deccan) adapted to survive with minimal rainfall?', 'Xerophytic adaptations: microphyllous spines reduce transpiration, deep roots tap aquifers, and suberized bark insulates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34e482d4-2347-435b-a666-a8cc2e98f88b', 'Leaves are modified into sharp spines (thorns) to minimize transpiration water loss, and stems are fleshy with deep taproots to absorb groundwater', true, '545df1b4-5401-4764-bbf2-2a1bc7a80645');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55ade1b3-6357-48e6-8173-58c382859869', 'They have broad giant leaves', false, '545df1b4-5401-4764-bbf2-2a1bc7a80645');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f128f7e-b2aa-42a4-8709-2076af424753', 'They float in air', false, '545df1b4-5401-4764-bbf2-2a1bc7a80645');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('138b26d9-e6c3-405e-81f7-eab7425cba29', 'They shed leaves every day', false, '545df1b4-5401-4764-bbf2-2a1bc7a80645');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a36463b0-f674-4e06-a575-7f9e46a0c0a2', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'How does vegetation change with increasing altitude in the Himalayan mountain zones (Mountain Vegetation)?', 'Altitudinal zonation transitions from sub-tropical foothills to temperate coniferous taiga (Pinus, Cedrus deodara) and alpine meadows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e31e947-177a-4ebe-a380-8cc54075bb61', 'Between 1,500 m and 2,500 m, trees become conical in shape with needle-like leaves called Coniferous Trees (e.g. Chir, Pine, Deodar)', true, 'a36463b0-f674-4e06-a575-7f9e46a0c0a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c2af8b6-368c-40c3-8d43-286265f3388f', 'Trees become thorny bushes', false, 'a36463b0-f674-4e06-a575-7f9e46a0c0a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0855ccb-d890-4d17-b44b-a30dacc915d2', 'Trees turn into ocean kelp', false, 'a36463b0-f674-4e06-a575-7f9e46a0c0a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c67e3a3-be83-483c-8ee3-8353c8126979', 'No trees exist in mountains', false, 'a36463b0-f674-4e06-a575-7f9e46a0c0a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce903c6c-b253-49ab-8ae2-e59b95976166', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What are ''Mangrove Forests'' and in which type of water environment do they thrive?', 'Mangroves are tidal halophytes with salt-filtering roots and pneumatophores adapted to saline coastal estuaries.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e03c7be-ec80-42ef-9764-b20954a130b9', 'Specialized halophytic coastal forests that can survive and thrive in saline seawater mudflats (e.g. Sundari trees in Sundarbans)', true, 'ce903c6c-b253-49ab-8ae2-e59b95976166');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac7c3939-6a6d-4d39-8385-3f43f0954ff4', 'Forests that grow on mountaintops in snow', false, 'ce903c6c-b253-49ab-8ae2-e59b95976166');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b079d26-322f-476e-8279-88a3e6dd4213', 'Desert cactus plants', false, 'ce903c6c-b253-49ab-8ae2-e59b95976166');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce0c0654-f603-4111-b036-421941fae7e4', 'Freshwater lake lilies', false, 'ce903c6c-b253-49ab-8ae2-e59b95976166');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03494540-df39-4876-844e-b0eeae016c44', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What is the famous mangrove tree species found in the Ganga-Brahmaputra delta after which the ''Sundarbans'' are named?', 'Sundari trees (Heritiera fomes) dominate the tidal delta, providing timber and lending their name to the Sundarbans.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cb11c54-13dd-4813-8c81-b8ac16f1f75b', 'Sundari tree (Heritiera fomes)', true, '03494540-df39-4876-844e-b0eeae016c44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20579cef-4828-4d04-8e94-501c0f0bf80d', 'Sal tree', false, '03494540-df39-4876-844e-b0eeae016c44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b09e93c-68af-495e-a69f-2866eed8c832', 'Teak tree', false, '03494540-df39-4876-844e-b0eeae016c44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32842ef9-1920-45ac-97cb-f15c99775fbc', 'Chir Pine', false, '03494540-df39-4876-844e-b0eeae016c44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8f72de8-f1ee-4493-8b35-4436612ef754', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Why are natural forests of vital ecological and economic importance to our planet and human society?', 'Forests provide ecosystem services: oxygen production, carbon sequestration, soil anchoring, and non-timber forest products.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cf39c4e-9c0f-4e05-9b8d-d12fb857d512', 'They release Oxygen and absorb Carbon Dioxide, bind soil roots to prevent erosion, regulate rainfall, and provide timber, medicinal herbs, lac, and honey', true, 'e8f72de8-f1ee-4493-8b35-4436612ef754');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10945407-fc56-4052-87bc-c68178f9a7fe', 'They take away all oxygen', false, 'e8f72de8-f1ee-4493-8b35-4436612ef754');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e6d0918-7a1f-425c-88d5-0fd334d36561', 'They cause soil erosion', false, 'e8f72de8-f1ee-4493-8b35-4436612ef754');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7de4a982-feb8-42c1-80e9-413810b0c14e', 'They make land barren', false, 'e8f72de8-f1ee-4493-8b35-4436612ef754');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd024556-68e9-4050-9f00-56c84d32655b', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Which forest in Gujarat is world-famous as the home of the Asiatic Lion?', 'The dry deciduous teak forests of Gir in Gujarat constitute the exclusive natural habitat of the Asiatic Lion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3af588a5-f600-45ff-b38d-bfc1d1d2855c', 'Gir Forest', true, 'fd024556-68e9-4050-9f00-56c84d32655b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d9387ce-992d-4125-aeb8-e1302aa5f823', 'Kaziranga', false, 'fd024556-68e9-4050-9f00-56c84d32655b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17a853d7-7441-4c6f-ad68-406202c79f8c', 'Corbett', false, 'fd024556-68e9-4050-9f00-56c84d32655b');
