INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f457f0a-49b9-4cca-944d-12a7d4e98099', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Where in India are wild Elephants and One-Horned Rhinoceroses naturally found roaming together in tall alluvial grasslands?', 'The floodplains of Assam support mega-herbivores like Asian Elephants, One-horned Rhinos, and Wild Water Buffaloes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6600ce04-5b6e-415a-812a-3d34e3ceb505', 'In the forests of Assam (Kaziranga and Manas)', true, '4f457f0a-49b9-4cca-944d-12a7d4e98099');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e768e773-68c7-4369-bc77-ba37889d210a', 'In the Thar Desert of Rajasthan', false, '4f457f0a-49b9-4cca-944d-12a7d4e98099');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('116eaa1d-0635-459d-86f4-862899092616', 'In the cold deserts of Ladakh', false, '4f457f0a-49b9-4cca-944d-12a7d4e98099');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f6bc9c4-ba48-4fa2-9fbc-df70ec5fb7c7', 'In the Andaman Islands', false, '4f457f0a-49b9-4cca-944d-12a7d4e98099');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c01f3784-e152-4bab-bf04-1a50ba4105cf', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Which high-altitude animals with thick woolly coats are found roaming in the snow-bound Himalayan and Ladakh ranges?', 'High alpine Himalayan fauna features thick pelts: Bos mutus (Wild Yak), Chiru, Snow Leopards, and Bharal (Blue Sheep).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47f22b2e-8bd4-4be4-9e36-0f6d57edd463', 'Wild Yaks, Tibetan Antelope (Chiru), Snow Leopards, and Himalayan Ibex', true, 'c01f3784-e152-4bab-bf04-1a50ba4105cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0221dbde-6369-4bc0-864b-dbc5b1b4e6f1', 'Camels and Lions', false, 'c01f3784-e152-4bab-bf04-1a50ba4105cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b767b1f-ae57-4a85-9b1a-8e26dbc20cbf', 'Elephants and Rhinos', false, 'c01f3784-e152-4bab-bf04-1a50ba4105cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed46fd9e-1314-4ad4-9aa3-6980dffaeb75', 'Peacocks and Flamingos', false, 'c01f3784-e152-4bab-bf04-1a50ba4105cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2dfb4f5-97b0-43ec-8182-a051bf24effa', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What are ''Migratory Birds'' and why do birds like Siberian Cranes, Flamingos, and Pintail Ducks migrate to Indian wetlands every winter?', 'Migratory avifauna escape freezing sub-polar temperatures along the Central Asian Flyway to winter in hospitable Indian wetlands.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ad376de-33d4-43e1-9c1c-7be01829e297', 'They fly thousands of kilometres from freezing Arctic/Siberian winter extremes to warmer Indian wetlands in search of food and nesting grounds', true, 'a2dfb4f5-97b0-43ec-8182-a051bf24effa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae5e09e6-7517-479e-b4db-42e6da871449', 'They migrate because they get lost', false, 'a2dfb4f5-97b0-43ec-8182-a051bf24effa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a99a1c6d-198b-47eb-9258-76197446bc06', 'They come to India to hibernate underwater', false, 'a2dfb4f5-97b0-43ec-8182-a051bf24effa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac78c36f-1ac9-4ed1-8984-ada3f8f5bcb5', 'They only fly in summer', false, 'a2dfb4f5-97b0-43ec-8182-a051bf24effa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97b9494d-5ba6-49b0-b32b-a9b259a205c2', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Which desert animals are specially adapted to the arid Rann of Kachchh and Thar Desert of northwestern India?', 'The Indian Wild Ass (Equus hemionus khur) thrives in the saline flats of Rann of Kachchh alongside desert camels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32237810-567f-4cde-869b-b94d725201b0', 'Camels (in Thar) and Wild Ass / Khur (in the Little Rann of Kachchh)', true, '97b9494d-5ba6-49b0-b32b-a9b259a205c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38a7cb71-d3ab-4dae-9fc1-2b8e9793322c', 'Yaks and Snow Leopards', false, '97b9494d-5ba6-49b0-b32b-a9b259a205c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2830a00f-0c9a-4b2b-9baa-28d2c2b3358e', 'Tigers and Rhinos', false, '97b9494d-5ba6-49b0-b32b-a9b259a205c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34bd70a4-41c6-4727-bf0f-274aac8f9204', 'Elephants and Gibbons', false, '97b9494d-5ba6-49b0-b32b-a9b259a205c2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e2628a4-b309-470b-8ff0-26684b0155c2', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What civic programme was launched to encourage people and school students across India to plant millions of trees during the monsoon season?', 'Initiated by K.M. Munshi in 1950, Van Mahotsav is an annual tree-planting festival celebrated in the first week of July.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc86fe49-ae9e-4f6f-864f-93f49c6fa2d3', 'Van Mahotsav (''Forest Festival'')', true, '7e2628a4-b309-470b-8ff0-26684b0155c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a15a131-0869-4716-a31e-4a237dcfe66c', 'Project Tiger', false, '7e2628a4-b309-470b-8ff0-26684b0155c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c7720a5-4917-45e3-b7b6-4bf3f34ff8f7', 'Swachh Bharat', false, '7e2628a4-b309-470b-8ff0-26684b0155c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44013826-5276-45d6-898e-f8d45cabcde7', 'Digital India', false, '7e2628a4-b309-470b-8ff0-26684b0155c2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ff640ad-5af9-417f-8364-42444d166b6a', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Why is agriculture in India predominantly described as a ''Gamble with the Monsoons''?', 'Rainfed agrarian livelihoods depend heavily on the spatio-temporal distribution of southwest monsoonal rains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b895729-c5ce-4153-89be-afe8a8f29d89', 'A vast majority of Indian farming relies on timely, adequate monsoon rainfall; a weak or delayed monsoon causes severe drought and crop failure', true, '3ff640ad-5af9-417f-8364-42444d166b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d07f6719-9207-4d4e-8d43-ff1de0b7278c', 'Because farmers play card games in fields', false, '3ff640ad-5af9-417f-8364-42444d166b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa64816d-9064-4d6f-b21a-61680b83d27b', 'Because crops grow without water', false, '3ff640ad-5af9-417f-8364-42444d166b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('653f7952-611c-4333-abdb-9e9d4ec69ef6', 'Because monsoons only bring snow', false, '3ff640ad-5af9-417f-8364-42444d166b6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a96885f5-c1af-4929-866d-f971adbb78ba', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d562bcf-004f-4aaa-8e7f-d18539f7541c', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'a96885f5-c1af-4929-866d-f971adbb78ba');
