INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('115c7d6f-cbda-4233-a7fd-99019a1b6b04', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Spot the IMPOSTER in the following group of trees classified by their natural forest type:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5672f68-9b32-4379-9be6-cdf463b7540c', 'Ebony (Evergreen)', false, '115c7d6f-cbda-4233-a7fd-99019a1b6b04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('431647d4-dc39-4420-aa24-d2b12dd6ee12', 'Mahogany (Evergreen)', false, '115c7d6f-cbda-4233-a7fd-99019a1b6b04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce3224ff-63c4-4c04-aa4f-15220466b827', 'Rosewood (Evergreen)', false, '115c7d6f-cbda-4233-a7fd-99019a1b6b04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5a06aa3-62ea-4335-934e-8f35fa49e2eb', 'Teak (Evergreen)', true, '115c7d6f-cbda-4233-a7fd-99019a1b6b04');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5b2f710-5944-4c96-aac2-99bae035acec', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'A climatologist records the seasonal pressure patterns over South Asia in July. What atmospheric mechanism drives the Southwest Monsoon?', 'Thermal depression over the continental interior draws cross-equatorial Coriolis-deflected southwesterly trade winds carrying ocean moisture.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f948a9f7-acc9-4e41-9b68-7f445c27b5ec', 'Intense solar heating creates an intense thermal Low-Pressure trough over the northwestern plains/Tibetan plateau, sucking in moist High-Pressure oceanic trade winds from the southern Indian Ocean', true, 'c5b2f710-5944-4c96-aac2-99bae035acec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c94fb2ce-fac6-49bb-b2f8-92f1d273c941', 'Cold snow in the Himalayas blows wind to the sea', false, 'c5b2f710-5944-4c96-aac2-99bae035acec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f275fac4-43a1-401c-8d51-584f0604459d', 'The moon pulls all ocean water onto the land', false, 'c5b2f710-5944-4c96-aac2-99bae035acec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e2be91c-7a9b-48dd-a3fc-1af64c9d2b98', 'Earth stops rotating for a month', false, 'c5b2f710-5944-4c96-aac2-99bae035acec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79047178-6707-4535-afd5-44494603db83', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Match Column I (Forest Types) with Column II (Dominant Species / Typical Regions):
(a) Tropical Rainforest  -> (i) Sundari / Ganga-Brahmaputra delta
(b) Tropical Deciduous   -> (ii) Ebony, Mahogany, Rosewood / Western Ghats
(c) Coniferous Mountain   -> (iii) Sal, Teak, Peepal, Shisham / Central India
(d) Mangrove Forest      -> (iv) Chir, Pine, Deodar / Himalayan slopes', 'Rainforest = Ebony/Mahogany; Deciduous = Sal/Teak; Coniferous = Chir/Deodar; Mangrove = Sundari.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dd6dd6e-f34b-425d-a861-69d547085341', 'a-(ii), b-(iii), c-(iv), d-(i)', true, '79047178-6707-4535-afd5-44494603db83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a2cbdb3-5f52-494d-b27c-282a1af44d1f', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '79047178-6707-4535-afd5-44494603db83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49c9a653-c3a6-4d25-ab5e-684cb310dbae', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '79047178-6707-4535-afd5-44494603db83');
