INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('162c4c78-9cf6-46fc-90d2-9a8e5c42e752', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Read the statements regarding Indian climate and forests:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f7d6dd1-5f6f-4329-8af6-ee45a4ab1a2b', 'Statements 1 and 2 only', true, '162c4c78-9cf6-46fc-90d2-9a8e5c42e752');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc4a8be1-7f3f-4d76-bc6c-3f4e0ef03029', 'Statements 2 and 3 only', false, '162c4c78-9cf6-46fc-90d2-9a8e5c42e752');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('250a6f62-21fb-4b48-b26d-9536808292e5', 'Statements 1 and 3 only', false, '162c4c78-9cf6-46fc-90d2-9a8e5c42e752');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1f0d194-871a-48b9-8889-854996c8668d', 'All Statements 1, 2, and 3', false, '162c4c78-9cf6-46fc-90d2-9a8e5c42e752');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e74e879-d828-43ac-827d-278e34550d36', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Why do plants in thorny scrub forests (like Acacia/Babool, Cactus, and Khejri) develop extensive underground root networks stretching meters deep and wide?', 'Deep phreatophytic taproots reach capillary fringe water tables, sustaining desert scrub in xerophytic environments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dfab6f3-3547-4d57-8c62-ce221bdb295d', 'To maximize groundwater scavenging across deep arid soil profiles where surface moisture is scarce', true, '3e74e879-d828-43ac-827d-278e34550d36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d91af91e-6b3a-429b-be75-03137ddf21f2', 'To anchor against heavy snowstorms', false, '3e74e879-d828-43ac-827d-278e34550d36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b74df14-6cf3-4035-ab25-717520b61179', 'To store frozen ice', false, '3e74e879-d828-43ac-827d-278e34550d36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d477774-d526-4eb4-9a07-ed21fc7510b4', 'To connect with ocean water', false, '3e74e879-d828-43ac-827d-278e34550d36');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b3b4829-1108-4b72-883d-7d944ed96e84', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Consider four national conservation sanctuaries:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89658d14-4ce7-4347-a0d0-95b6d2e9b243', '1: Asiatic Lion ; 2: One-Horned Rhino ; 3: Hangul (Kashmir Stag) ; 4: Sangai (Dancing Deer)', true, '9b3b4829-1108-4b72-883d-7d944ed96e84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8c892eb-1eea-4aed-a284-6ce084e4df36', '1: Snow Leopard ; 2: Royal Bengal Tiger ; 3: Asiatic Lion ; 4: Elephant', false, '9b3b4829-1108-4b72-883d-7d944ed96e84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9da84f7-8677-4b15-a364-1e4c29de2703', '1: Hangul ; 2: Sangai ; 3: Asiatic Lion ; 4: Rhino', false, '9b3b4829-1108-4b72-883d-7d944ed96e84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55d02630-388c-4a21-be08-64803e80bc49', '1: Elephant ; 2: Tiger ; 3: Snow Leopard ; 4: Hangul', false, '9b3b4829-1108-4b72-883d-7d944ed96e84');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5d761f7-4213-49d8-9b69-ee4d418bee2b', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'What is the phenomenon of ''Western Disturbances'' that brings winter rainfall and mountain snowfall to north-western India in December and January?', 'Mediterranean extra-tropical cyclones steered by westerly jet streams provide crucial rabi crop (wheat) moisture in northwest India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5862c91e-6028-44b5-9ecf-5757c1817443', 'Temperate cyclonic low-pressure systems originating over the Mediterranean Sea that are carried eastward into India by the subtropical westerly jet stream', true, 'c5d761f7-4213-49d8-9b69-ee4d418bee2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09520929-e7f5-4f92-ad89-4f5cea80e4f2', 'Cyclones from the Bay of Bengal', false, 'c5d761f7-4213-49d8-9b69-ee4d418bee2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a33a89b8-d369-4f0c-b6ee-e16fec24df72', 'Dust storms from the Sahara', false, 'c5d761f7-4213-49d8-9b69-ee4d418bee2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccf7a0b2-472d-4e8a-b448-7554e42cf4b3', 'Tornadoes from the Pacific', false, 'c5d761f7-4213-49d8-9b69-ee4d418bee2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67a045bf-9af7-4f1a-84a1-4ae57a9ff0ff', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Why is the Tibetan Antelope (''Chiru'') illegally hunted and endangered in high-altitude Himalayas?', 'Chiru is poached for Shahtoosh (''King of Wools''), prompting strict international CITES Appendix I trade bans.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('229fbe2d-8d1f-4a0a-8b8c-8321622fc780', 'For its ultra-fine, warm, and lightweight wool called ''Shahtoosh'', which is spun into expensive luxury shawls', true, '67a045bf-9af7-4f1a-84a1-4ae57a9ff0ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98003960-e6fc-406f-90e8-ab5bd4eb6cf8', 'For its horn meat', false, '67a045bf-9af7-4f1a-84a1-4ae57a9ff0ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f652b0c-e230-4d20-820d-9f2523812157', 'For leather shoes', false, '67a045bf-9af7-4f1a-84a1-4ae57a9ff0ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed8a0313-e073-4782-b858-e99bb09f6bbd', 'Because it attacks domestic sheep', false, '67a045bf-9af7-4f1a-84a1-4ae57a9ff0ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1869c0aa-fc5a-4405-9249-c60d1026d001', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'What ecological role do coastal Mangrove forests perform during violent tropical cyclones and tsunamis?', 'Mangrove bioshields act as natural coastal wave attenuators, dampening destructive hydro-dynamic surge energies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a90ff7b-b47a-4c12-bcb6-23617398eee8', 'Their dense root networks absorb and attenuate high-energy oceanic storm surges, drastically reducing inland coastal erosion and protecting human lives', true, '1869c0aa-fc5a-4405-9249-c60d1026d001');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6c0cc7e-1c63-46f4-b4dc-3977a1b94090', 'They create bigger waves', false, '1869c0aa-fc5a-4405-9249-c60d1026d001');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8efe8b6-4c21-4c88-8749-6510933fb159', 'They pump seawater into clouds', false, '1869c0aa-fc5a-4405-9249-c60d1026d001');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23cf4d4f-70f2-415f-a011-59385c623a46', 'They blow cyclone winds away', false, '1869c0aa-fc5a-4405-9249-c60d1026d001');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2688a8b9-8acf-437f-b95d-445f2d80d873', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'What is the primary conservation objective of establishing ''Wildlife Corridors'' between fragmented National Parks and Tiger Reserves?', 'Landscape ecological corridors connect fragmented habitats, preventing genetic bottlenecks and human-wildlife conflict.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44ca86fe-acbd-4767-a1de-14284fdb9904', 'To enable safe, unobstructed seasonal migration, gene flow, and territorial dispersal of wildlife populations, preventing inbreeding depression', true, '2688a8b9-8acf-437f-b95d-445f2d80d873');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83e27fff-4b64-46a7-b872-63edc091bd2d', 'To build tourist highways through forests', false, '2688a8b9-8acf-437f-b95d-445f2d80d873');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0874c55c-8202-4ff1-ad47-2499e658473a', 'To fence animals in cages', false, '2688a8b9-8acf-437f-b95d-445f2d80d873');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('709b3151-303e-4e50-8502-886dc59e509f', 'To separate male and female animals', false, '2688a8b9-8acf-437f-b95d-445f2d80d873');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('422529bc-dcf1-46d6-b6a8-618dd8e3a75d', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'What fundamental message does the final chapter of NCERT Class 6 Geography emphasize regarding wildlife coexistence?', 'NCERT urges ethical consumer boycotts of wildlife derivatives and active community afforestation for ecological sustainability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3be9fb8d-7400-4986-9ace-35dbfdcb4a2d', 'Refusing to purchase items made from animal parts (bones, horns, fur, feathers, ivory), planting native trees, and respecting all biological life on Earth', true, '422529bc-dcf1-46d6-b6a8-618dd8e3a75d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bad9b4bd-5b96-45d9-ba16-a90d855005de', 'Cutting down all forests for cities', false, '422529bc-dcf1-46d6-b6a8-618dd8e3a75d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b497ba7-5dc0-4ba0-a97e-debfe1d984d9', 'Keeping wild tigers as domestic pets', false, '422529bc-dcf1-46d6-b6a8-618dd8e3a75d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50b2198c-979b-4f11-a2a5-a64602c8a2c3', 'Hunting birds during winter', false, '422529bc-dcf1-46d6-b6a8-618dd8e3a75d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6dcfda66-3367-47c7-8216-892f5bc77b32', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'संज्ञा के स्थान पर प्रयुक्त होने वाले शब्दों (जैसे: मैं, तुम, वह, हम, आप, यह, कोई, क्या) को व्याकरण में क्या कहते हैं?', 'संज्ञा की पुनरुक्ति को रोककर वाक्य को सुंदर व संक्षिप्त बनाने वाले विकारी शब्द ''सर्वनाम'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2798a4c-93af-4c36-9ccc-300cb69fc943', 'सर्वनाम (Pronoun)', true, '6dcfda66-3367-47c7-8216-892f5bc77b32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c095a158-0bd4-4428-a9e7-f88deed9e8fe', 'विशेषण', false, '6dcfda66-3367-47c7-8216-892f5bc77b32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba80215a-c51c-410b-aedb-06a0b0992a8a', 'क्रिया', false, '6dcfda66-3367-47c7-8216-892f5bc77b32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fc670be-0179-4ea9-9d1d-becfb08c95d8', 'अव्यय', false, '6dcfda66-3367-47c7-8216-892f5bc77b32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a0ab892-ba98-432f-9d58-19d96f03ca52', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'हिंदी भाषा में सर्वनाम के मुख्य रूप से कितने भेद (प्रकार) होते हैं?', 'सर्वनाम के 6 प्रमुख भेद हैं: 1. पुरुषवाचक, 2. निश्चयवाचक, 3. अनिश्चयवाचक, 4. संबंधवाचक, 5. प्रश्नवाचक, और 6. निजवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5230461-018b-434e-b242-449d53a0abb4', 'छह भेद (6 Types)', true, '0a0ab892-ba98-432f-9d58-19d96f03ca52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d20aff7-35e6-4a4b-bbab-1560892abc41', 'पाँच भेद', false, '0a0ab892-ba98-432f-9d58-19d96f03ca52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('546a345f-74ba-4138-8fdc-57039fdbaeab', 'चार भेद', false, '0a0ab892-ba98-432f-9d58-19d96f03ca52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03b3db48-9ae8-4d80-b8bf-e63fda29e5eb', 'आठ भेद', false, '0a0ab892-ba98-432f-9d58-19d96f03ca52');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89023f7c-f88e-467d-85ea-d3d4f74df5a7', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'बोलने वाले (वक्ता), सुनने वाले (श्रोता) अथवा किसी अन्य व्यक्ति के लिए प्रयुक्त होने वाले सर्वनाम को क्या कहते हैं?', 'संवाद में तीनों पुरुषों (वक्ता, श्रोता, अन्य) के लिए प्रयुक्त सर्वनाम ''पुरुषवाचक सर्वनाम'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75dfa43a-400a-4c7a-8d41-d88b8b8088b8', 'पुरुषवाचक सर्वनाम (Personal Pronoun)', true, '89023f7c-f88e-467d-85ea-d3d4f74df5a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cfb8587-857d-4a63-b705-06178b32c57f', 'निश्चयवाचक सर्वनाम', false, '89023f7c-f88e-467d-85ea-d3d4f74df5a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac4328ad-a974-4d11-becb-10782a8b955c', 'निजवाचक सर्वनाम', false, '89023f7c-f88e-467d-85ea-d3d4f74df5a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f0956d4-9b3a-402e-b4a5-c4178bd314d5', 'प्रश्नवाचक सर्वनाम', false, '89023f7c-f88e-467d-85ea-d3d4f74df5a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23da06ad-f710-43b8-a84d-933dca76b226', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'पुरुषवाचक सर्वनाम के कितने भेद होते हैं?', 'पुरुषवाचक के 3 भेद हैं: उत्तम पुरुष (First Person - मैं/हम), मध्यम पुरुष (Second Person - तू/तुम/आप), अन्य पुरुष (Third Person - वह/वे)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c9f6c93-6d75-4a3b-985d-1f15a0f014dd', 'तीन भेद (उत्तम पुरुष, मध्यम पुरुष, और अन्य पुरुष)', true, '23da06ad-f710-43b8-a84d-933dca76b226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbf34d1c-6b39-4983-8cc7-cfc97e24af14', 'दो भेद', false, '23da06ad-f710-43b8-a84d-933dca76b226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a52f7ef-f2f7-40b7-88c5-e52ca30dcde2', 'चार भेद', false, '23da06ad-f710-43b8-a84d-933dca76b226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bc8a9e3-0483-45fb-a2e1-7c5d1201b85c', 'पाँच भेद', false, '23da06ad-f710-43b8-a84d-933dca76b226');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97de33c7-596d-413c-a3e5-1873d7bd7fff', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'बोलने वाला (वक्ता) या लिखने वाला अपने लिए जिन सर्वनाम शब्दों का प्रयोग करता है (जैसे: मैं, हम, मुझे, मेरा, हमारा), वे क्या कहलाते हैं?', 'वक्ता द्वारा स्वयं के संदर्भ में प्रयुक्त पद ''उत्तम पुरुष'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11a348ec-5dc2-4d68-8764-65cd3b9cf4c4', 'उत्तम पुरुषवाचक सर्वनाम (First Person)', true, '97de33c7-596d-413c-a3e5-1873d7bd7fff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00df2cd3-a51b-4c8f-9b82-389dd19fab90', 'मध्यम पुरुषवाचक', false, '97de33c7-596d-413c-a3e5-1873d7bd7fff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56780894-bbf9-49e6-b25b-ccd4c4d4f41b', 'अन्य पुरुषवाचक', false, '97de33c7-596d-413c-a3e5-1873d7bd7fff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ec04afa-4ab5-4d16-9cfc-a7e77a712d7b', 'निजवाचक', false, '97de33c7-596d-413c-a3e5-1873d7bd7fff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8aae5e7-235f-4494-b1c9-9fa12e8ec84d', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'जिससे बात की जाए (श्रोता/सुनने वाले) के लिए जिन सर्वनाम शब्दों का प्रयोग होता है (जैसे: तू, तुम, आप, तुझे, तुम्हारा, आपका), वे क्या कहलाते हैं?', 'श्रोता के लिए प्रयुक्त सर्वनाम पद ''मध्यम पुरुष'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d69e99dc-b55e-44c1-a00e-5aaefef1f44c', 'मध्यम पुरुषवाचक सर्वनाम (Second Person)', true, 'f8aae5e7-235f-4494-b1c9-9fa12e8ec84d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64394493-c86c-44cd-9ada-329a7f1b7706', 'उत्तम पुरुषवाचक', false, 'f8aae5e7-235f-4494-b1c9-9fa12e8ec84d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a85a6f1-6e1c-4a21-a4db-155491c1a14f', 'अन्य पुरुषवाचक', false, 'f8aae5e7-235f-4494-b1c9-9fa12e8ec84d');
