INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c323a9bb-4611-42b8-8096-96b57f422c63', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'वक्ता और श्रोता जिसके विषय में बात कर रहे हों (किसी तीसरे व्यक्ति) के लिए प्रयुक्त सर्वनाम (जैसे: वह, वे, उसे, उनका, उन्होंने) क्या कहलाते हैं?', 'अनुपस्थित या किसी अन्य व्यक्ति के लिए प्रयुक्त पद ''अन्य पुरुष'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82531738-5387-4508-b9cd-fc76adce5105', 'अन्य पुरुषवाचक सर्वनाम (Third Person)', true, 'c323a9bb-4611-42b8-8096-96b57f422c63');
