INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9560f7fb-86c6-4679-841f-f89a3ae7bafc', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'जो सर्वनाम शब्द किसी निश्चित व्यक्ति, वस्तु या स्थान का निश्चित संकेत करते हैं (जैसे: ''यह मेरी पुस्तक है'', ''वह रोहन का घर है''), उन्हें क्या कहते हैं?', 'निश्चित दूरस्थ या निकटवर्ती वस्तु की ओर संकेत करने वाले सर्वनाम (यह, वह, ये, वे) ''निश्चयवाचक'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7480e94e-63f1-4b28-bb36-8abebcab08db', 'निश्चयवाचक सर्वनाम या संकेतवाचक सर्वनाम (Demonstrative Pronoun)', true, '9560f7fb-86c6-4679-841f-f89a3ae7bafc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('697a5f18-8965-4273-8333-446e91a2a36e', 'अनिश्चयवाचक सर्वनाम', false, '9560f7fb-86c6-4679-841f-f89a3ae7bafc');
