INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('161c442b-3b88-4989-a7cb-35d786bd0d9c', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'जिन सर्वनाम शब्दों से किसी निश्चित व्यक्ति या वस्तु का बोध नहीं होता (जैसे: ''दूध में कुछ गिर गया है'', ''दरवाजे पर कोई खड़ा है''), उन्हें क्या कहते हैं?', 'अस्पष्ट या अनिर्दिष्ट संज्ञा के स्थान पर आने वाले शब्द (कोई, कुछ, किसी) ''अनिश्चयवाचक सर्वनाम'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6ef26ce-235f-46ee-b3ce-4772dcfe131b', 'अनिश्चयवाचक सर्वनाम (Indefinite Pronoun - ''कोई'', ''कुछ'')', true, '161c442b-3b88-4989-a7cb-35d786bd0d9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a221b87-d64c-42ec-b0d8-aaeb9aefa8e1', 'निश्चयवाचक सर्वनाम', false, '161c442b-3b88-4989-a7cb-35d786bd0d9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9944281e-c3ad-4649-9a63-b0dbe68b37a1', 'संबंधवाचक सर्वनाम', false, '161c442b-3b88-4989-a7cb-35d786bd0d9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('999b3bca-03bc-4411-9b47-8453b88a2198', 'निजवाचक सर्वनाम', false, '161c442b-3b88-4989-a7cb-35d786bd0d9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adce2467-355f-4e0b-abd9-1d84311fd96f', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'वाक्य में एक संज्ञा या सर्वनाम का दूसरे संज्ञा या सर्वनाम से संबंध जोड़ने वाले शब्द (जैसे: ''जो मेहनत करेगा, वह सफल होगा'', ''जिसकी लाठी उसकी भैंस'') क्या कहलाते हैं?', 'पारस्परिक उपवाक्यों में संबंध प्रकट करने वाले सर्वनाम युग्म ''संबंधवाचक'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac039ddb-83f1-490b-8880-d36695584653', 'संबंधवाचक सर्वनाम (Relative Pronoun - ''जो-सो'', ''जैसा-वैसा'', ''जिसकी-उसकी'')', true, 'adce2467-355f-4e0b-abd9-1d84311fd96f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05f62da3-711a-40d1-949c-fcae7a5c1750', 'पुरुषवाचक सर्वनाम', false, 'adce2467-355f-4e0b-abd9-1d84311fd96f');
