INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7671c397-b953-4632-8170-79f55442145a', 'निजवाचक सर्वनाम', false, 'adce2467-355f-4e0b-abd9-1d84311fd96f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73da4b5f-25c2-4f4a-af65-70744defc48d', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'जिन सर्वनाम शब्दों का प्रयोग किसी व्यक्ति, वस्तु या घटना के विषय में प्रश्न पूछने के लिए किया जाता है (जैसे: ''तुम्हारा नाम क्या है?'', ''वहाँ कौन आया है?''), उन्हें क्या कहते हैं?', 'जिज्ञासा व प्रश्न पूछने हेतु प्रयुक्त सर्वनाम (कौन, क्या, किसे, किसका) ''प्रश्नवाचक सर्वनाम'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
