INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c4e7583-bc24-48bb-9721-e4ef0227239b', 'संबंधवाचक सर्वनाम', false, '73da4b5f-25c2-4f4a-af65-70744defc48d');
