INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('864c7c89-de12-4655-aad4-1e9f90cbd321', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'जिन सर्वनाम शब्दों का प्रयोग कर्ता स्वयं अपने लिए (अपने आप के अर्थ में) करता है (जैसे: ''मैं अपना काम स्वयं करूँगा'', ''वह खुद चला गया'', ''आप ही कर लो''), उन्हें क्या कहते हैं?', 'कर्ता द्वारा आत्मबोध (स्वयं/खुद/अपने आप) हेतु प्रयुक्त सर्वनाम ''निजवाचक सर्वनाम'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
