INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ee57263-d740-4d39-a644-2a30477cf962', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', '''आप'' शब्द का प्रयोग मध्यम पुरुष और निजवाचक दोनों में होता है। निम्नलिखित में से किस वाक्य में ''आप'' का प्रयोग ''निजवाचक सर्वनाम'' के रूप में हुआ है?', 'जब ''आप'' का अर्थ ''स्वयं/खुद'' (अपने आप) हो तो वह निजवाचक सर्वनाम होता है; जब आदरपूर्वक श्रोता के लिए हो तो मध्यम पुरुष होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da3c898e-52e6-4752-ae74-2d81d77a3662', '''मैं यह काम आप (स्वयं) ही कर लूँगा।'' (निजवाचक)', true, '8ee57263-d740-4d39-a644-2a30477cf962');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25d2db08-db16-4072-9b23-4a93235b893a', '''आप कहाँ जा रहे हैं?'' (आदरार्थक मध्यम पुरुष)', false, '8ee57263-d740-4d39-a644-2a30477cf962');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9617691d-1ca8-4a45-8f3b-21bfd722d98c', '''आप हमारे आदरणीय शिक्षक हैं।'' (मध्यम पुरुष)', false, '8ee57263-d740-4d39-a644-2a30477cf962');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dd426db-b4e4-4087-8d2f-552dc15cb673', '''आप चाय पीजिए।'' (मध्यम पुरुष)', false, '8ee57263-d740-4d39-a644-2a30477cf962');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adde25f7-425c-42dd-bcab-4d9705342936', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'सर्वनाम और सार्वनामिक विशेषण में क्या मूलभूत अंतर होता है?', 'संज्ञा के स्थान पर प्रयुक्त अकेला पद = सर्वनाम; संज्ञा के आगे लगकर निर्देश करने वाला पद = सार्वनामिक विशेषण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5fed59c-4d7f-4d72-860b-7a730463b6c5', 'जब ''यह/वह'' संज्ञा के स्थान पर अकेले आते हैं तो सर्वनाम होते हैं (जैसे: ''यह मेरी कार है'') ; किन्तु जब वे संज्ञा शब्द के ठीक पहले आकर उसकी विशेषता बताते हैं तो सार्वनामिक विशेषण कहलाते हैं (जैसे: ''यह कार मेरी है'')', true, 'adde25f7-425c-42dd-bcab-4d9705342936');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91609695-46ef-473f-ba2f-5087bfb087e7', 'सर्वनाम केवल बहुवचन होते हैं', false, 'adde25f7-425c-42dd-bcab-4d9705342936');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f06e5fbb-266e-434d-aed4-774ce2a02510', 'सार्वनामिक विशेषण में संज्ञा नहीं होती', false, 'adde25f7-425c-42dd-bcab-4d9705342936');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efd40917-82ea-4fc8-86c8-436b2ef1bfc7', 'दोनों में कोई अंतर नहीं है', false, 'adde25f7-425c-42dd-bcab-4d9705342936');
