INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b58f002c-5623-4f9b-88c4-c90d9e975968', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'सर्वनाम शब्दों में लिंग का निर्धारण किस आधार पर होता है?', 'सर्वनाम स्वयं लिंग-निरपेक्ष होते हैं (वह, मैं, तुम); उनका लिंग वाक्य की समापिका क्रिया से स्पष्ट होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d3c51d7-7094-4eb5-91d7-66247c817435', 'सर्वनाम का रूप दोनों लिंगों में समान रहता है; लिंग की पहचान वाक्य में प्रयुक्त क्रिया पद से होती है (जैसे: ''वह पढ़ता है'' - पुल्लिंग ; ''वह पढ़ती है'' - स्त्रीलिंग)', true, 'b58f002c-5623-4f9b-88c4-c90d9e975968');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7adc5f3f-0044-4754-b5bc-0da4d4de7103', 'सर्वनाम शब्द में मात्रा बदलकर', false, 'b58f002c-5623-4f9b-88c4-c90d9e975968');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84190eda-e2c3-48fd-b266-e9101a840421', 'सर्वनाम केवल पुल्लिंग होते हैं', false, 'b58f002c-5623-4f9b-88c4-c90d9e975968');
