INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d11d83e8-6c39-4667-8585-46162132e7c6', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'वाक्य को सर्वनाम की दृष्टि से शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d63b148-47ae-409e-819a-519cbae3e07e', 'मुझे आपकी कलम चाहिए। (''मेरे को'' के स्थान पर ''मुझे'' मानक शुद्ध रूप है)', true, 'd11d83e8-6c39-4667-8585-46162132e7c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d6df303-54b0-43f2-a9ff-88fbe87b7c09', 'मुझको आपकी कलम चाहिए है।', false, 'd11d83e8-6c39-4667-8585-46162132e7c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03ddd71b-f832-44f8-8dfd-4354ea8fabaa', 'मैं आपकी कलम मांगता।', false, 'd11d83e8-6c39-4667-8585-46162132e7c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59b85ad1-8da3-4b0d-94ba-a9e8a06de15e', 'मेरा आपकी कलम चाहिए।', false, 'd11d83e8-6c39-4667-8585-46162132e7c6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23c42759-2178-4106-ae2a-addc375ef1c7', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'वाक्य को शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4971525-af30-4aa3-8118-fd02675a07f2', 'वे लोग कल दिल्ली जा रहे हैं। (बहुवचन संज्ञा ''लोग'' के साथ बहुवचन सर्वनाम ''वे'' शुद्ध है)', true, '23c42759-2178-4106-ae2a-addc375ef1c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97ea29b5-7cbb-420d-b930-71a3e4c1d48a', 'वह लोग दिल्ली जाएगा।', false, '23c42759-2178-4106-ae2a-addc375ef1c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6df87d15-fd14-4d88-95bc-db0c0e068f10', 'उसे लोग दिल्ली जा रहे हैं।', false, '23c42759-2178-4106-ae2a-addc375ef1c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36deaf4e-0abe-499e-95d9-da0272db7e49', 'उन लोग दिल्ली जा रहा है।', false, '23c42759-2178-4106-ae2a-addc375ef1c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b1072d1-cfe9-4c6f-be4d-5f049b046422', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'सर्वनाम शब्द ''जो'' के विभिन्न कारक रूपों का सही युग्म कौन-सा है?', 'संबंधवाचक सर्वनाम ''जो'' के कारक रूप ''जिस-'' प्रातिपदिक से बनते हैं (जिसने, जिसे, जिससे, जिसका)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7231326a-8993-437c-994f-955347e16035', 'जिसने (कर्ता), जिसको/जिसे (कर्म), जिससे (करण/अपादान), जिसका/जिसके/जिसकी (संबंध), जिसमें/जिसपर (अधिकरण)', true, '3b1072d1-cfe9-4c6f-be4d-5f049b046422');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4be1edb7-da08-44f0-8c5d-cee0fe0f624f', 'जोने, जोको, जोसे', false, '3b1072d1-cfe9-4c6f-be4d-5f049b046422');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63398b58-c4a4-4088-a0b5-20934aa9194b', 'ज्याका, ज्याकी', false, '3b1072d1-cfe9-4c6f-be4d-5f049b046422');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc27deb1-c8d4-431d-9b5d-2678df398988', 'जोए, जोओ', false, '3b1072d1-cfe9-4c6f-be4d-5f049b046422');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a69a71e7-0398-47f9-a267-ef88819a6abc', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'प्रश्नवाचक सर्वनाम ''कौन'' और ''क्या'' का प्रयोग क्रमशः किनके लिए होता है?', 'प्राणीवाचक प्रश्न = ''कौन'' (बाहर कौन है?); अप्राणीवाचक प्रश्न = ''क्या'' (हाथ में क्या है?)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9515d1d1-0cb9-4c52-b5bf-76ebaebf2b62', '''कौन'' का प्रयोग सजीव प्राणियों (व्यक्तियों) के लिए तथा ''क्या'' का प्रयोग निर्जीव वस्तुओं या घटनाओं के लिए होता है', true, 'a69a71e7-0398-47f9-a267-ef88819a6abc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a933c6c6-914d-4c4f-a755-791934fde11e', '''क्या'' केवल इंसानों के लिए आता है', false, 'a69a71e7-0398-47f9-a267-ef88819a6abc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40443715-ab6e-4707-9549-161a5ddc837a', 'दोनों केवल जानवरों के लिए आते हैं', false, 'a69a71e7-0398-47f9-a267-ef88819a6abc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f500410-b049-4319-920b-987121afe4cf', 'कोई नियम नहीं है', false, 'a69a71e7-0398-47f9-a267-ef88819a6abc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6703d628-b15f-4edd-a1c7-cee3b84e39b0', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'वाक्य में प्रयुक्त रेखांकित पद का सर्वनाम भेद बताइए:
