INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd051b90-7f4c-458a-b7ed-7e84a26202f3', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'सर्वनाम के साथ जब दो कारक चिह्न (विभक्तियाँ) एक साथ आती हैं, तो उन्हें कैसे लिखा जाता है?', 'मानक हिंदी वर्तनी नियम: ''उसके लिए'' में पहला परसर्ग ''के'' संश्लिष्ट तथा दूसरा ''लिए'' विश्लिष्ट लिखा जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aed62a59-792b-4fe0-b643-624deeac9b97', 'पहला कारक चिह्न सर्वनाम से मिलाकर और दूसरा अलग लिखा जाता है (जैसे: ''उसके लिए'', ''उनमें से'')', true, 'cd051b90-7f4c-458a-b7ed-7e84a26202f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e23b94e8-4dda-4f92-97bb-f5c3db144f4a', 'दोनों मिलाकर लिखे जाते हैं (''उसकेलिए'')', false, 'cd051b90-7f4c-458a-b7ed-7e84a26202f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6dc2b72-0a2f-4b95-a259-431a34bc0189', 'दोनों अलग लिखे जाते हैं (''उस के लिए'')', false, 'cd051b90-7f4c-458a-b7ed-7e84a26202f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('659106c4-0d6c-4de2-9667-ea98649fe1f7', 'कारक चिह्न कभी नहीं आते', false, 'cd051b90-7f4c-458a-b7ed-7e84a26202f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b96314ce-9571-4d2a-9d8a-e3fab192f86b', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'वाक्य में प्रयुक्त रेखांकित पद का सर्वनाम भेद बताइए:
