INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87306597-2c58-4047-afc6-ded656afe116', 'निश्चयवाचक सर्वनाम', false, 'b96314ce-9571-4d2a-9d8a-e3fab192f86b');
