INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a79eaa76-96c1-41b2-a8cd-7ce9337892f2', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9926d281-9191-4fcf-b4bb-dd015e12df56', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'a79eaa76-96c1-41b2-a8cd-7ce9337892f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4820b203-155d-40c0-b207-5b1cede97fe1', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'a79eaa76-96c1-41b2-a8cd-7ce9337892f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f6652d8-cd3f-4cf0-afcd-4d018c6538b9', '(A) सही है, परन्तु (R) गलत है।', false, 'a79eaa76-96c1-41b2-a8cd-7ce9337892f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d407465f-5f92-4685-a84e-56c7fde97c6d', '(A) गलत है, परन्तु (R) सही है।', false, 'a79eaa76-96c1-41b2-a8cd-7ce9337892f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5d2ed2d-4253-4619-911b-d2d61740f8c2', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'Spot the IMPOSTER in the following group of सर्वनाम और उनके भेदों के युग्म में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24265cd4-54d7-485a-9b52-bf2e0b9de7b5', 'हम - उत्तम पुरुष', false, 'f5d2ed2d-4253-4619-911b-d2d61740f8c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17eb3372-0605-4511-8a97-bc4ddd5ad4d3', 'तुम - मध्यम पुरुष', false, 'f5d2ed2d-4253-4619-911b-d2d61740f8c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('871b19db-76d1-459f-9c81-9e6c00bbf476', 'कोई - अनिश्चयवाचक', false, 'f5d2ed2d-4253-4619-911b-d2d61740f8c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eb5afaa-6e72-4e7c-9c0d-7a2919cc2bd4', 'स्वयं - प्रश्नवाचक', true, 'f5d2ed2d-4253-4619-911b-d2d61740f8c2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60587c04-00a9-4752-8830-9d357b0b6fdf', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'सुमेलित कीजिए (सर्वनाम शब्द और उनके व्याकरणिक भेद):
(क) हम      -> (i) अनिश्चयवाचक सर्वनाम
(ख) कोई     -> (ii) उत्तम पुरुषवाचक सर्वनाम
(ग) जो-वह   -> (iii) निजवाचक सर्वनाम
(घ) अपने आप -> (iv) संबंधवाचक सर्वनाम', 'हम = उत्तम पुरुष; कोई = अनिश्चयवाचक; जो-वह = संबंधवाचक; अपने आप = निजवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0283a3c-5b20-4d3a-9f54-bacbe8cc4995', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', true, '60587c04-00a9-4752-8830-9d357b0b6fdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3306963-fa90-4e94-857b-0f3ed55401e8', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '60587c04-00a9-4752-8830-9d357b0b6fdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11bfd019-51f0-40ab-9a49-004ed3ab15d6', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '60587c04-00a9-4752-8830-9d357b0b6fdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1697d3a4-aa10-4b7d-8c61-96ed904c9af3', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '60587c04-00a9-4752-8830-9d357b0b6fdf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06ac8a79-8298-45d5-8204-530b85f57ec3', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'निम्नलिखित वाक्य में प्रयुक्त सर्वनामों की सही संख्या और भेद पहचानिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d62e9fe4-52c8-44db-a46e-29d4bd6cd790', '5 सर्वनाम पद (मैं = उत्तम पुरुष, अपना = निजवाचक, स्वयं = निजवाचक, उसे = अन्य पुरुष, कुछ = अनिश्चयवाचक)', true, '06ac8a79-8298-45d5-8204-530b85f57ec3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f43704b1-44e8-4556-bc84-831257486c4e', '3 सर्वनाम पद', false, '06ac8a79-8298-45d5-8204-530b85f57ec3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b556f29-a407-4e3f-a4a3-86728d46a2bc', '2 सर्वनाम पद', false, '06ac8a79-8298-45d5-8204-530b85f57ec3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cbaf9b8-fd73-45a7-9f1d-beda20ba7da4', '6 सर्वनाम पद', false, '06ac8a79-8298-45d5-8204-530b85f57ec3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41ebd746-8bac-4ed9-9c82-1fbb1d7e5fbd', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'सर्वनाम शब्दों में किस कारक की विभक्ति का प्रयोग पूर्णतः वर्जित होता है (अर्थात् वह कारक सर्वनाम में नहीं होता)?', 'सर्वनाम में संबोधन कारक नहीं होता; अतः सर्वनाम के 7 कारक रूप ही बनते हैं (संबोधन रहित)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f3e644f-b278-41cc-9aa5-2db3cbe8c466', 'संबोधन कारक (हे!, अरे! - सर्वनामों का संबोधन नहीं होता, जैसे ''हे तुम!'', ''अरे मैं!'' अमानक हैं)', true, '41ebd746-8bac-4ed9-9c82-1fbb1d7e5fbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d96c4b1f-b79a-4432-94a9-c145610def7b', 'कर्ता कारक', false, '41ebd746-8bac-4ed9-9c82-1fbb1d7e5fbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8416c641-cc79-4c92-a899-011ec1aa2978', 'अधिकरण कारक', false, '41ebd746-8bac-4ed9-9c82-1fbb1d7e5fbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc98cbb9-b21a-4dc1-a10f-b84a270f3d7b', 'अपादान कारक', false, '41ebd746-8bac-4ed9-9c82-1fbb1d7e5fbd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a87f3c41-102b-43be-9001-987e8b1e64a7', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'अनिश्चयवाचक सर्वनाम ''कोई'' का तिर्यक (सपरसर्ग) बहुवचन रूप क्या होता है?', '''कोई'' का एकवचन तिर्यक ''किसी'' तथा बहुवचन तिर्यक ''किन्हीं'' (किन्हीं ने, किन्हीं को) होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06a8d8f8-56ed-407f-9349-a146525ab95e', 'किन्हीं (जैसे: ''किन्हीं लोगों ने कहा'', ''किन्हीं को बुलाओ'')', true, 'a87f3c41-102b-43be-9001-987e8b1e64a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d3a8bc0-585e-473b-ae54-34eb13347784', 'कोइयों', false, 'a87f3c41-102b-43be-9001-987e8b1e64a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('411da289-aa40-4b63-8361-e07c7b0949e5', 'कोइने', false, 'a87f3c41-102b-43be-9001-987e8b1e64a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79a4cecf-5975-4dbb-8ba2-79416cc06096', 'कोई-कोई', false, 'a87f3c41-102b-43be-9001-987e8b1e64a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3506548-a6e6-4aef-ab91-57a7326bb611', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'सर्वनाम शब्द ''क्या'' का प्रयोग जब विस्मय (आश्चर्य) प्रकट करने के लिए होता है (जैसे: ''क्या शानदार दृश्य है!''), तो वह क्या कहलाता है?', 'यहाँ प्रश्न न पूछकर विस्मय/प्रशंसा की जा रही है, अतः यह विस्मयादिबोधक अव्यय के रूप में प्रयुक्त हुआ है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6abda41a-bbb6-4fa8-8f95-b3f609bd344d', 'विस्मयादिबोधक अव्यय रूप', true, 'e3506548-a6e6-4aef-ab91-57a7326bb611');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85b739ac-e03b-42af-8e32-55400b3422b5', 'प्रश्नवाचक सर्वनाम', false, 'e3506548-a6e6-4aef-ab91-57a7326bb611');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8951e2f1-6ba9-4500-9b58-b1c00b5b8143', 'निश्चयवाचक सर्वनाम', false, 'e3506548-a6e6-4aef-ab91-57a7326bb611');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('904eab9d-5c0b-4646-a4a3-ee4bdda12fa5', 'निजवाचक सर्वनाम', false, 'e3506548-a6e6-4aef-ab91-57a7326bb611');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea3588f6-0c79-4be4-9dc6-bab8210649e8', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'वाक्य में प्रयुक्त रेखांकित पदों के सर्वनाम भेदों का सही क्रम बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e61ba81-fde2-4be0-bb1d-dc001c97010a', 'आप = मध्यम पुरुष ; मैं = उत्तम पुरुष ; स्वयं = निजवाचक ; कौन = प्रश्नवाचक', true, 'ea3588f6-0c79-4be4-9dc6-bab8210649e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('918b147d-b270-4b43-95c6-1a15ccf4299f', 'आप = निजवाचक ; मैं = अन्य पुरुष ; स्वयं = मध्यम पुरुष ; कौन = अनिश्चयवाचक', false, 'ea3588f6-0c79-4be4-9dc6-bab8210649e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a883cce-8ad2-4908-8ec1-1ebe598cadf8', 'चारों पुरुषवाचक हैं', false, 'ea3588f6-0c79-4be4-9dc6-bab8210649e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50d37189-8a7e-4101-9d66-4c0ed5d6f8dc', 'चारों निजवाचक हैं', false, 'ea3588f6-0c79-4be4-9dc6-bab8210649e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5bb0d47b-ff7f-4131-b194-d3ab7847c4b0', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'वाक्य को मानक हिंदी व्याकरण के अनुसार शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca41c3d9-c551-4d17-b8f2-062b662a85a8', 'तुझे क्या चाहिए? (या ''आपको क्या चाहिए?'')', true, '5bb0d47b-ff7f-4131-b194-d3ab7847c4b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('256d81fa-191d-49ea-8d16-ef6b30421c9e', 'तेरे को क्या मंगता?', false, '5bb0d47b-ff7f-4131-b194-d3ab7847c4b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('349a11f5-a9c3-41e8-8a7c-c05030621f6f', 'तू को क्या चाहिए?', false, '5bb0d47b-ff7f-4131-b194-d3ab7847c4b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3abcdf0-39f3-4933-b33a-df466117dff8', 'तेरा क्या चाहिए?', false, '5bb0d47b-ff7f-4131-b194-d3ab7847c4b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b1d468e-d11c-4b79-807b-c7b5343e5e8a', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'संयुक्त सर्वनाम (Compound Pronoun) का सही उदाहरण कौन-सा है?', 'डॉ. दीमशित्स के अनुसार दो सर्वनामों के संयोग से बनने वाले पद ''संयुक्त सर्वनाम'' कहलाते हैं (जो कोई, कोई न कोई, सब कुछ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19501a0e-fb6f-4531-96da-abd5ebd01b23', 'जो कोई, कोई न कोई, कुछ न कुछ, सब कुछ, और कोई', true, '4b1d468e-d11c-4b79-807b-c7b5343e5e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10ade4f6-46ac-4b90-a78c-4562f9c8810e', 'केवल ''मैं'' और ''तुम''', false, '4b1d468e-d11c-4b79-807b-c7b5343e5e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a89f7e2a-e42a-49ab-b1e3-636a56f5021d', 'केवल ''यह'' और ''वह''', false, '4b1d468e-d11c-4b79-807b-c7b5343e5e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('836512d1-21d5-4542-b46f-6a204d48dfea', 'संज्ञा और क्रिया', false, '4b1d468e-d11c-4b79-807b-c7b5343e5e8a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4560934-8c22-4a8d-a293-634a5f6d7788', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'वाक्य में प्रयुक्त रेखांकित पद का सही सर्वनाम भेद बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60f6c594-6212-499c-bc48-7891d834b8b5', 'संयुक्त अनिश्चयवाचक सर्वनाम', true, 'b4560934-8c22-4a8d-a293-634a5f6d7788');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a15352f-3dde-4f34-842c-ae65cef302ec', 'निश्चयवाचक सर्वनाम', false, 'b4560934-8c22-4a8d-a293-634a5f6d7788');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7602fac1-9269-4c46-bc19-2d94d460c2b6', 'निजवाचक सर्वनाम', false, 'b4560934-8c22-4a8d-a293-634a5f6d7788');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a961d82a-e9f7-4e0c-9f23-426b6ab1ddbe', 'उत्तम पुरुष', false, 'b4560934-8c22-4a8d-a293-634a5f6d7788');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52d5ba70-da13-4df7-b78a-fc52b47ac330', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'सर्वनाम की उपयोगिता के संदर्भ में कौन-सा कथन सर्वाधिक सटीक है?', 'संज्ञा की बार-बार होने वाली अप्रिय पुनरावृत्ति से मुक्ति दिलाकर भाषा में प्रवाह और लालित्य उत्पन्न करना सर्वनाम का मुख्य प्रयोजन है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e297fba8-dd2b-4957-8365-49e33452176b', 'सर्वनाम भाषा को सहज, संक्षिप्त, प्रवाहपूर्ण और पुनरुक्ति दोष से मुक्त बनाते हैं, जिससे भाषा की अभिव्यक्ति क्षमता उत्कृष्ट हो जाती है', true, '52d5ba70-da13-4df7-b78a-fc52b47ac330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de6b24cf-5726-4f3e-807f-5c1684534435', 'सर्वनाम केवल संस्कृत में उपयोगी हैं', false, '52d5ba70-da13-4df7-b78a-fc52b47ac330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c8ceda0-a8d6-4faf-a70b-f766aad6fac9', 'सर्वनाम से वाक्य कठिन हो जाते हैं', false, '52d5ba70-da13-4df7-b78a-fc52b47ac330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a760daca-d7be-4b82-a65b-780802388cfd', 'सर्वनाम का कोई व्याकरणिक महत्व नहीं है', false, '52d5ba70-da13-4df7-b78a-fc52b47ac330');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27a0503b-f53d-4255-a4ef-fda960651810', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'What is a portable source of electricity that produces electric current from chemicals stored inside it?', 'An electric cell converts internal chemical energy into electrical energy through electrochemical reactions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68f54bfc-9186-45a6-bea3-121e8c3a12d5', 'Electric Cell (Dry Cell / Battery)', true, '27a0503b-f53d-4255-a4ef-fda960651810');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5eb131f2-6bca-4907-8728-7be28bd77e5d', 'Electric Switch', false, '27a0503b-f53d-4255-a4ef-fda960651810');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27f5ffd8-a56b-4bda-b4d3-08b2475d753c', 'Electric Bulb', false, '27a0503b-f53d-4255-a4ef-fda960651810');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff05c4be-1c30-4c7f-8a5b-014aa1e1dab5', 'Conductor', false, '27a0503b-f53d-4255-a4ef-fda960651810');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8c7f709-f241-4074-b566-c254163a8b1e', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'How many terminals does an electric cell have?', 'The metal cap on top is the Positive (+) terminal, while the flat metal disc at the base is the Negative (-) terminal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cffd2da3-4243-4818-9aee-d034bbaa1ebb', 'Two terminals (a Positive terminal marked ''+'' and a Negative terminal marked ''-'')', true, 'e8c7f709-f241-4074-b566-c254163a8b1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('356849f1-e89d-42e9-bdb1-fb61b64a3ca4', 'One terminal', false, 'e8c7f709-f241-4074-b566-c254163a8b1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10a3a8c1-cb47-48be-925a-2fe2ecd28fcb', 'Three terminals', false, 'e8c7f709-f241-4074-b566-c254163a8b1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc61cad3-df23-47e2-aa7e-a874327746a9', 'Four terminals', false, 'e8c7f709-f241-4074-b566-c254163a8b1e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc77a918-adb3-45e1-8c04-21d68b4f188a', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'What is the tiny, thin coiled metallic wire inside an incandescent bulb that glows white-hot and emits light when electricity passes through it?', 'The high-resistance tungsten filament heats up due to Joule heating, glowing incandescently to emit visible light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86856d3e-64ad-4bea-8632-b4b609c85e23', 'Filament (made of Tungsten)', true, 'fc77a918-adb3-45e1-8c04-21d68b4f188a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef69de5f-22d0-421f-a1f0-378761636bbf', 'Terminal', false, 'fc77a918-adb3-45e1-8c04-21d68b4f188a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8ee7a22-16f8-4212-ad49-53bdd49be324', 'Switch', false, 'fc77a918-adb3-45e1-8c04-21d68b4f188a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cc67908-a9cb-4770-b5cd-2568eae6bf9b', 'Insulator', false, 'fc77a918-adb3-45e1-8c04-21d68b4f188a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('084b40a5-57e6-41c1-a29a-b238104ef052', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'A simple electrical device used to either break (open) an electric circuit or complete (close) it is called a:', 'An electrical switch acts as a mechanical gate opening or closing the conductive loop.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4822394f-0549-4498-886b-04dc7bd91940', 'Switch', true, '084b40a5-57e6-41c1-a29a-b238104ef052');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff10000e-cdf5-47f4-a38b-4779311e60f5', 'Filament', false, '084b40a5-57e6-41c1-a29a-b238104ef052');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b14bc8c-76a1-4ff9-b41b-b4fce67702c1', 'Cell', false, '084b40a5-57e6-41c1-a29a-b238104ef052');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a56d0a0c-a8ed-451f-9ea7-611f197fcc13', 'Fuse', false, '084b40a5-57e6-41c1-a29a-b238104ef052');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e11e369-b703-403b-a684-3e58c53a9819', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Materials that allow electric current to pass through them easily (such as copper wire, aluminium, iron, silver) are called:', 'Conductors possess abundant free delocalized valence electrons that facilitate electric charge flow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c0a5843-91df-40bf-b68d-1d62ce02485c', 'Conductors of Electricity', true, '2e11e369-b703-403b-a684-3e58c53a9819');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5231140a-2b1d-4e3e-92e2-88396e803581', 'Insulators', false, '2e11e369-b703-403b-a684-3e58c53a9819');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('084379c3-1b88-4a4b-b35e-9e3ee465e60b', 'Semiconductors', false, '2e11e369-b703-403b-a684-3e58c53a9819');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4e510e0-92ad-4680-aaf9-868e0e47ba7a', 'Dielectrics', false, '2e11e369-b703-403b-a684-3e58c53a9819');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7121c929-e16f-4b5d-8855-cad1f0b7addd', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Materials that do NOT allow electric current to pass through them (such as rubber, plastic, dry wood, glass) are called:', 'Insulators have tightly bound localized valence electrons with high dielectric resistivity, blocking electrical conduction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04d180a9-819e-4a61-b868-e83113a622dd', 'Insulators of Electricity', true, '7121c929-e16f-4b5d-8855-cad1f0b7addd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15c65c32-40eb-4482-9493-75febb7813c7', 'Conductors', false, '7121c929-e16f-4b5d-8855-cad1f0b7addd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfce5dca-d3c1-42e9-8868-cc3d6c847e2d', 'Metals', false, '7121c929-e16f-4b5d-8855-cad1f0b7addd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3212cf6d-f5c4-4a68-b725-209e27bd1bb1', 'Electrolytes', false, '7121c929-e16f-4b5d-8855-cad1f0b7addd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea1796fe-56a7-4386-a7b9-4759a66fc7c3', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'What is the conventional direction of electric current flow in an electric circuit?', 'By historical convention, current is defined as positive charge flow moving from the positive (+) to negative (-) terminal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9eba08f1-f6f1-45f3-b23b-7396dd4b1d7f', 'From the Positive (+) terminal to the Negative (-) terminal of the electric cell', true, 'ea1796fe-56a7-4386-a7b9-4759a66fc7c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86d8bb09-c329-4394-8376-cc295bbbb72a', 'From the Negative (-) terminal to the Positive (+) terminal', false, 'ea1796fe-56a7-4386-a7b9-4759a66fc7c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e478e30-d899-424b-bf89-1fb7db3b3f66', 'From both terminals at the same time', false, 'ea1796fe-56a7-4386-a7b9-4759a66fc7c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('763cf891-b6d2-4595-a08a-dcddd32c2291', 'Current does not have any direction', false, 'ea1796fe-56a7-4386-a7b9-4759a66fc7c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('043ecfd1-cab1-42f3-afca-e89659283104', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Why does an electric bulb NOT glow when its internal filament is broken (fused bulb)?', 'A severed filament breaks electrical continuity, preventing loop closure and extinguishing electron drift.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('189297b1-f2df-4407-b5e8-95ed3994c43d', 'Because a broken filament creates a gap in the path, resulting in an Incomplete (Open) Circuit through which current cannot flow', true, '043ecfd1-cab1-42f3-afca-e89659283104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16218e3f-8776-4c8e-a9ae-ccc0e2cf552b', 'Because the glass melts', false, '043ecfd1-cab1-42f3-afca-e89659283104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8f74a82-7753-4c5c-98a9-2808bba10bba', 'Because the cell explodes', false, '043ecfd1-cab1-42f3-afca-e89659283104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54dc09c9-1620-464c-875b-f88877646c8e', 'Because light leaks out of the hole', false, '043ecfd1-cab1-42f3-afca-e89659283104');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2ac7561-fca5-4730-887d-3326eedcbede', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Why are electrical wires and screwdriver handles coated with Rubber or Plastic?', 'Insulating polymer sleeves shield against direct galvanic human contact with live energized conductors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d805afef-2afe-490e-832b-d6d4a097f0f5', 'Rubber and plastic are electrical Insulators that protect electricians and users from dangerous electric shocks', true, 'c2ac7561-fca5-4730-887d-3326eedcbede');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94c8d206-9843-4473-bad0-8adc246ffe84', 'To make wires look colorful and shiny', false, 'c2ac7561-fca5-4730-887d-3326eedcbede');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('341af991-174c-42f6-b12d-6ea11fc9b618', 'To make wires heavier', false, 'c2ac7561-fca5-4730-887d-3326eedcbede');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3390280-b269-43a6-a20e-13fd3cbb85a1', 'Because metals melt in air', false, 'c2ac7561-fca5-4730-887d-3326eedcbede');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6bd71c0c-bcb5-4cba-8db2-297225a952d5', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Is the human body a Conductor or an Insulator of electricity?', 'Saline electrolytes in blood and tissues render the human body conductive, which is why electric shocks occur.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a12c4a4b-2027-4e0c-b7c5-9afb3fbb09b6', 'A Conductor of electricity (since our body fluid contains dissolved mineral salts and water)', true, '6bd71c0c-bcb5-4cba-8db2-297225a952d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9ba4ae9-bfd6-49a8-bf10-3712a1675ced', 'An Insulator', false, '6bd71c0c-bcb5-4cba-8db2-297225a952d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0c82cde-b242-4a23-9408-dd09c93c7265', 'Neither', false, '6bd71c0c-bcb5-4cba-8db2-297225a952d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f2275f1-2fcd-4490-8317-46de6dfaa226', 'Only our hair conducts electricity', false, '6bd71c0c-bcb5-4cba-8db2-297225a952d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db6d7a63-3871-4d79-98d2-186fec8653d4', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'What happens if the two terminals of an electric cell are connected directly with a wire WITHOUT connecting a bulb or switch?', 'A direct zero-resistance short-circuit produces high discharge current, rapidly draining chemical potential and overheating the cell.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('478cb64f-be50-4ccb-b13a-c5c7e0e465ff', 'The chemicals in the cell get exhausted very rapidly, generating dangerous heat that can damage the cell (Short Circuit)', true, 'db6d7a63-3871-4d79-98d2-186fec8653d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5da2b79a-5b5a-4fb8-ab78-e8c649739337', 'The wire turns into gold', false, 'db6d7a63-3871-4d79-98d2-186fec8653d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26c4e32e-0f0b-4a42-b46c-7ea61874d625', 'The cell charges to 1000 volts', false, 'db6d7a63-3871-4d79-98d2-186fec8653d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d71084b-978f-4be8-b0a5-d48c049e6f3c', 'Nothing happens', false, 'db6d7a63-3871-4d79-98d2-186fec8653d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be3be1b1-0721-46bc-9f97-3575fab62a81', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Which metal is the MOST COMMONLY used for making domestic electrical connecting wires due to its high conductivity and affordability?', 'Copper has exceptionally low electrical resistivity, high ductility, and corrosion resistance, making it the industry standard.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faf809b5-8a9f-4af5-b330-435a505cbdc2', 'Copper (and Aluminium)', true, 'be3be1b1-0721-46bc-9f97-3575fab62a81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bab1a06f-1e9b-4cc8-8567-d161812986bd', 'Iron', false, 'be3be1b1-0721-46bc-9f97-3575fab62a81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e02cba2-09ec-4156-af14-80bfd366c6e7', 'Lead', false, 'be3be1b1-0721-46bc-9f97-3575fab62a81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81a9d1d4-5acd-44f9-bd29-241ed2defb37', 'Mercury', false, 'be3be1b1-0721-46bc-9f97-3575fab62a81');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6aaac446-dc8f-4abd-8e94-403b55b3dcc7', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What is an ''Electric Circuit'' in physics?', 'An electric circuit provides a closed continuous conducting path for circulating electric charges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b55480f-04ae-449d-a5c5-0746204660c4', 'A complete, unbroken closed conducting loop through which electric current can flow continuously from one terminal of the source to the other', true, '6aaac446-dc8f-4abd-8e94-403b55b3dcc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e515d7-b6bf-4012-8609-cba5aeccf02e', 'A machine that makes electricity from coal', false, '6aaac446-dc8f-4abd-8e94-403b55b3dcc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e362651f-3d0c-4fd1-98ce-3bddafc9db17', 'A broken wire hanging in air', false, '6aaac446-dc8f-4abd-8e94-403b55b3dcc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b162757-7860-4976-9225-061e1bd32a0c', 'A battery inside a toy', false, '6aaac446-dc8f-4abd-8e94-403b55b3dcc7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('270cbdfe-d222-4f7e-ac72-f5320cc54d41', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What is the difference between a ''Closed Circuit'' and an ''Open Circuit''?', 'Closed = complete conducting loop (current flows); Open = disconnected path (infinite resistance, zero current).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c04aad79-2dc8-4ff6-95d1-90884137caa3', 'In a Closed Circuit, the conducting path is completely unbroken and current flows to glow the bulb; in an Open Circuit, there is a break or open switch, stopping current flow', true, '270cbdfe-d222-4f7e-ac72-f5320cc54d41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28397198-8fb2-49ed-8ecc-bea5ad4a6763', 'In a Closed Circuit, the switch is OFF', false, '270cbdfe-d222-4f7e-ac72-f5320cc54d41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00b2c233-9f89-4477-a900-7d6bbc54c65d', 'In an Open Circuit, electricity flows faster', false, '270cbdfe-d222-4f7e-ac72-f5320cc54d41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7ed39c4-212d-40a5-b4b4-ddebf0613307', 'There is no difference', false, '270cbdfe-d222-4f7e-ac72-f5320cc54d41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e7fc757-7c4d-4d22-ac58-38655d9b9d1d', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'How can a student build a simple DIY electric switch using common household items?', 'The metal safety pin rotates into contact with the second brass drawing pin, completing or opening the conductive circuit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ff48560-1425-4fb4-807a-c37ff2b7a753', 'Using two metal drawing pins pushed into a wooden board, connected by a movable metal safety pin that bridges the gap when rotated', true, '9e7fc757-7c4d-4d22-ac58-38655d9b9d1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d36a2f0-d504-408b-9b7e-922f75dec1c5', 'Using a piece of plastic thread', false, '9e7fc757-7c4d-4d22-ac58-38655d9b9d1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e2a4faa-80ba-461f-871d-ef0de650c778', 'Using a rubber eraser', false, '9e7fc757-7c4d-4d22-ac58-38655d9b9d1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf2f1d29-9f4c-4ab2-8123-24539281777a', 'Using a dry stick', false, '9e7fc757-7c4d-4d22-ac58-38655d9b9d1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05c546e8-57ae-4495-8e49-fd0d91cf4d1a', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What happens when you insert an iron key versus a rubber eraser into the gap of a conduction tester circuit?', 'Iron conducts electrons, completing the circuit; rubber blocks electron flow, leaving the circuit open.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5873106b-a94e-4efe-a66b-686b09fda16e', 'With the iron key (conductor), the bulb glows brightly; with the rubber eraser (insulator), the bulb does NOT glow', true, '05c546e8-57ae-4495-8e49-fd0d91cf4d1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbbf5116-da3b-4053-871d-d2285df11865', 'Both make the bulb glow', false, '05c546e8-57ae-4495-8e49-fd0d91cf4d1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49184da3-2101-4ea1-aa3f-471feb23084a', 'Neither makes the bulb glow', false, '05c546e8-57ae-4495-8e49-fd0d91cf4d1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a42b8c0-762c-4ace-a149-a1169ce50db2', 'The rubber eraser makes the bulb explode', false, '05c546e8-57ae-4495-8e49-fd0d91cf4d1a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c0970c8-c26f-4651-8197-48298951182d', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why is pure Distilled Water an insulator, whereas ordinary Tap Water / Salty Water is a conductor of electricity?', 'Dissociated cations (Na⁺, Ca²⁺) and anions (Cl⁻, SO₄²⁻) in tap water provide electrolytic charge transport.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62ce4b92-208a-45d4-b175-ea08e5d56a85', 'Distilled water has no free ions; tap water and saline water contain dissolved mineral salts and electrolytes that dissociate into free charge carriers', true, '2c0970c8-c26f-4651-8197-48298951182d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4344866-9861-4bed-84a9-2bd09f62457e', 'Because tap water is colder', false, '2c0970c8-c26f-4651-8197-48298951182d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d206245-9700-4d02-a069-bfd5eeff1b79', 'Because distilled water is made of oil', false, '2c0970c8-c26f-4651-8197-48298951182d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7104cbd4-54d9-46ec-975f-5f4077def551', 'Because salt destroys electricity', false, '2c0970c8-c26f-4651-8197-48298951182d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d0e286f-9305-4d11-b71e-42f34c7cf608', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why is graphite (the lead inside a pencil) an exception among non-metals in terms of electrical conductivity?', 'Sp² hybridized carbon sheets in graphite possess free pi electrons, making pencil lead electrically conductive.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d5807fe-0c2d-4740-b5b5-97a6a9306105', 'Graphite is a good conductor of electricity because its layered hexagonal carbon lattice has delocalized pi electrons that move freely', true, '4d0e286f-9305-4d11-b71e-42f34c7cf608');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b18632dc-a699-43aa-ab5d-0578e3e74c9b', 'Because pencil lead is made of iron', false, '4d0e286f-9305-4d11-b71e-42f34c7cf608');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4482aad-1998-459c-86b9-f51bc01a001b', 'Because it is painted black', false, '4d0e286f-9305-4d11-b71e-42f34c7cf608');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81d2fc28-6ba8-48c9-9945-00ba08622bcd', 'Pencils do not conduct electricity', false, '4d0e286f-9305-4d11-b71e-42f34c7cf608');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2524cf44-e6c0-4271-bebb-782a2c8b92c8', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What are the two thick supporting wires inside an electric bulb attached to?', 'The two lead-in support wires connect the filament ends to two isolated terminal contacts at the bulb base.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab960df3-5dfc-4220-b4b4-8ea3a0b7586e', 'One thick wire is attached to the metal tip at the base, and the other is attached to the metal casing around the base (the two terminals of the bulb)', true, '2524cf44-e6c0-4271-bebb-782a2c8b92c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e903bee-f76b-4a46-8aa2-a205873e16d8', 'Both are connected to the glass shell', false, '2524cf44-e6c0-4271-bebb-782a2c8b92c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91b89667-0768-4f7c-a29d-db80458ef816', 'Both are connected to the ceiling', false, '2524cf44-e6c0-4271-bebb-782a2c8b92c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2924fa9-2550-4fc7-9d7d-127c7138a2ca', 'They are not connected to anything', false, '2524cf44-e6c0-4271-bebb-782a2c8b92c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5592b66-ea69-4d12-b457-da049fc441d0', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why should you NEVER touch an electric wall socket or an operating electrical appliance with WET hands?', 'Wet skin impedance drops from 100,000 Ω to <1,000 Ω, allowing dangerous milliamps of 230V current to pass through the body.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8f61b18-e742-4925-b471-dffe04b9db17', 'Water drastically reduces the electrical resistance of human skin, facilitating massive electric shock that can be fatal', true, 'a5592b66-ea69-4d12-b457-da049fc441d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6723d8be-230b-411f-b4b8-4925d43f5581', 'Because water makes the socket dirty', false, 'a5592b66-ea69-4d12-b457-da049fc441d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('814d1a67-46a2-4b72-bc3f-d230d2efbba7', 'Because the appliance will switch off', false, 'a5592b66-ea69-4d12-b457-da049fc441d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98939457-30be-41f5-8cc2-f8225777fd7a', 'Because water turns into ice', false, 'a5592b66-ea69-4d12-b457-da049fc441d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abec3d5d-eba5-4c13-8bc7-7a5471686ed8', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why do electricians wear thick Rubber Gloves and rubber-soled shoes while repairing electrical installations?', 'Dielectric rubber PPE isolates the worker from electrical grounding, preventing electrocution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d932d463-fdb7-493c-addb-ff4a076c6736', 'Rubber is an electrical insulator that breaks any potential ground path for electric current through their body to the earth', true, 'abec3d5d-eba5-4c13-8bc7-7a5471686ed8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f21d1390-845c-4f2d-b178-df57eae2780d', 'To keep their hands warm in winter', false, 'abec3d5d-eba5-4c13-8bc7-7a5471686ed8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a7a1757-4684-41dc-aea9-d7880f557ae5', 'To improve their grip on tools', false, 'abec3d5d-eba5-4c13-8bc7-7a5471686ed8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45a9f1b2-a3f7-4169-81bd-33558fdcbb5d', 'To follow fashion rules', false, 'abec3d5d-eba5-4c13-8bc7-7a5471686ed8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0d0f4c9-8ba3-4020-bef5-97b9c97e9157', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What is an ''Electric Torch'' and how does it function when switched ON?', 'Sliding the switch closes the internal spring-contact circuit, illuminating the bulb backed by a parabolic reflector.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ba24021-be3e-423c-bb46-1f9d053fa1df', 'The slide switch pushes a metal contact strip against the bulb base, completing the closed circuit between cells, reflector, and bulb', true, 'd0d0f4c9-8ba3-4020-bef5-97b9c97e9157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1ce35c7-a326-46b2-9458-169f8863871a', 'It uses burning oil', false, 'd0d0f4c9-8ba3-4020-bef5-97b9c97e9157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e4b1fc2-b272-42ff-9ef0-1e059a5fc891', 'It catches sunlight in a glass', false, 'd0d0f4c9-8ba3-4020-bef5-97b9c97e9157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2aeb4598-8618-480d-a249-3af8a67f01b3', 'It generates electricity from air', false, 'd0d0f4c9-8ba3-4020-bef5-97b9c97e9157');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf75481e-b6c1-49f4-baf3-46f334225d70', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why is Tungsten metal specifically chosen to make the filament of an electric incandescent bulb?', 'Tungsten sustains operating temperatures over 2,500°C due to its record metallic melting point of 3,422°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f08638f-c0ce-41d5-b1ac-a8ffa6270932', 'It has an exceptionally high melting point (~3422°C) and high electrical resistance, glowing white-hot without melting', true, 'bf75481e-b6c1-49f4-baf3-46f334225d70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5179d16-0c61-4032-b1fb-65f42be1e4cf', 'Because it is very cheap', false, 'bf75481e-b6c1-49f4-baf3-46f334225d70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac5cc80f-f68c-4dba-a57d-ff6cf3a62845', 'Because it is a liquid at room temperature', false, 'bf75481e-b6c1-49f4-baf3-46f334225d70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e44d3bb-98ab-4fcf-9576-9b6070abcdcb', 'Because it is transparent', false, 'bf75481e-b6c1-49f4-baf3-46f334225d70');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('398d716f-4d97-486f-a4b0-5212ebcb86fc', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why should we NEVER use the electric current from domestic 230V AC mains wall sockets for classroom experiments?', 'Domestic 230V mains is lethal; educational circuits must strictly use low-voltage 1.5V DC dry cells for complete safety.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb8afb3d-d114-4134-b490-487cd7f727fc', '230V AC mains current carries lethal power that can cause fatal electric shocks and fires; school experiments must strictly use small 1.5V DC electric cells', true, '398d716f-4d97-486f-a4b0-5212ebcb86fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f2e55d1-c621-491d-bbc4-fdef1a8c6e5e', 'Because the school bill will be too high', false, '398d716f-4d97-486f-a4b0-5212ebcb86fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60af5226-ed4e-4d24-8658-f2403b9dfb4f', 'Because wall sockets do not work during the day', false, '398d716f-4d97-486f-a4b0-5212ebcb86fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d679f5c7-ef24-4a75-b703-9869a5d5d3e5', 'Because mains electricity has no voltage', false, '398d716f-4d97-486f-a4b0-5212ebcb86fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89c31000-2c82-452f-a09f-b44e336f7767', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Which of the following common household objects is an electrical CONDUCTOR?', 'Brass (copper-zinc alloy) and aluminium foil are metallic conductors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1b7fed2-f662-411d-8061-d7713415e782', 'Brass key and aluminium foil', true, '89c31000-2c82-452f-a09f-b44e336f7767');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50623748-bad6-4a82-b9f1-b900bf0a4570', 'Plastic ruler and wooden pencil body', false, '89c31000-2c82-452f-a09f-b44e336f7767');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6e71946-a70d-4a57-ac57-ed1803bba878', 'Glass bangle and rubber band', false, '89c31000-2c82-452f-a09f-b44e336f7767');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d787fdab-be36-4e23-b1b3-c5059ccad0a2', 'Cotton cloth and paper sheet', false, '89c31000-2c82-452f-a09f-b44e336f7767');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0cb60514-4ecc-4c11-89da-eec4bee69a9b', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Which of the following common household objects is an electrical INSULATOR?', 'Polymers, ceramics, elastomers, and celluloid wood are non-conductive electrical insulators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d79253eb-28e6-47e0-91e9-9116ea3042b7', 'Plastic pen body, glass marble, dry rubber eraser, wooden stick', true, '0cb60514-4ecc-4c11-89da-eec4bee69a9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcf438c1-11c8-41a4-a21b-59f6cfe5130a', 'Iron nail and steel spoon', false, '0cb60514-4ecc-4c11-89da-eec4bee69a9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82d352a1-4d24-49f8-9e20-e643f127d663', 'Copper wire and gold ring', false, '0cb60514-4ecc-4c11-89da-eec4bee69a9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ad800c5-758d-43f5-bdb4-c4c23db5ba1b', 'Aluminium key', false, '0cb60514-4ecc-4c11-89da-eec4bee69a9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80e951e6-c625-4bc8-abe4-aea677c314ab', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why is air generally classified as a non-conductor (insulator) of electricity?', 'Air has a high dielectric breakdown threshold (~3 kV/mm); neutral N₂ and O₂ molecules block low-voltage conduction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f7663a4-e94c-455f-b053-bdf201a5bd30', 'Dry atmospheric air consists of neutral gas molecules without free charge carriers, preventing electric current from jumping across open gaps under normal voltages', true, '80e951e6-c625-4bc8-abe4-aea677c314ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79be70b8-c79b-4bd2-95aa-13f2d5b4114c', 'Because air is too light', false, '80e951e6-c625-4bc8-abe4-aea677c314ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21fd0e55-43fa-4012-bbce-d04e4d54aefb', 'Because air has no oxygen', false, '80e951e6-c625-4bc8-abe4-aea677c314ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9d76cbe-f11c-4c69-b8c4-6c95f755a512', 'Because air only conducts heat', false, '80e951e6-c625-4bc8-abe4-aea677c314ab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd26d6f0-22f7-4afe-b4e0-dccb3939d363', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What warning sign featuring a skull and crossed bones is prominently displayed on electrical substations and transformers?', 'The skull and crossbones caution sign warns of lethal high-voltage electrocution hazards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6126323b-5283-4d47-88b2-7c880eef0f05', 'DANGER - High Voltage Electric Shock Hazard', true, 'bd26d6f0-22f7-4afe-b4e0-dccb3939d363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05a7180b-9938-4824-84e7-480cf0c99ba7', 'Hospital zone', false, 'bd26d6f0-22f7-4afe-b4e0-dccb3939d363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d1e8f87-adb2-42f1-8de4-67c7e2737c48', 'No parking', false, 'bd26d6f0-22f7-4afe-b4e0-dccb3939d363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc3d7c07-6e14-4fc8-8132-3fd857dbbf83', 'Speed breaker ahead', false, 'bd26d6f0-22f7-4afe-b4e0-dccb3939d363');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c40ad55f-4854-4a48-b290-ceb2880beb54', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0bee063-684e-4b1a-a2c3-ec710ca7b52b', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'c40ad55f-4854-4a48-b290-ceb2880beb54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d058d7c6-21ab-4747-bb95-6acbe78259c1', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'c40ad55f-4854-4a48-b290-ceb2880beb54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15b39e0c-094f-4b03-a54c-3dc90ee6446a', '(A) is true, but (R) is false.', false, 'c40ad55f-4854-4a48-b290-ceb2880beb54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c41dba5-8715-4748-98d4-79d258bb6445', '(A) is false, but (R) is true.', false, 'c40ad55f-4854-4a48-b290-ceb2880beb54');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8bdad77-fe90-4502-af67-36c14b82ce85', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Spot the IMPOSTER in the following group of materials classified by their electrical conductivity:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eebd7488-db3c-4b72-a989-a79551396a25', 'Silver (Conductor)', false, 'f8bdad77-fe90-4502-af67-36c14b82ce85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73242b57-809d-4b00-8857-aa6c922cd533', 'Copper (Conductor)', false, 'f8bdad77-fe90-4502-af67-36c14b82ce85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8fb033f-9c5f-4a55-a048-b07d60bc87a6', 'Graphite (Conductor)', false, 'f8bdad77-fe90-4502-af67-36c14b82ce85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de40c083-942e-4253-a10c-b2771acee5e2', 'Pure Rubber (Conductor)', true, 'f8bdad77-fe90-4502-af67-36c14b82ce85');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cefb44e4-43fe-4892-a3b2-218532b72277', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'A student connects two electric cells in series to power a bulb. Which terminal connection configuration is CORRECT to light up the bulb?', 'Series battery connection requires connecting opposite polarity terminals (+ to -) to add cell voltages (1.5V + 1.5V = 3.0V).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93a11feb-0dc0-42f7-af45-533de0ab564c', 'The Positive (+) terminal of the first cell is connected to the Negative (-) terminal of the second cell in series', true, 'cefb44e4-43fe-4892-a3b2-218532b72277');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5abaf1f1-2c77-42fa-a951-d5b2b4282a96', 'Positive connected to Positive', false, 'cefb44e4-43fe-4892-a3b2-218532b72277');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9326336e-6626-4515-945f-8fbbedbdb71d', 'Negative connected to Negative', false, 'cefb44e4-43fe-4892-a3b2-218532b72277');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a992c89-bafc-456d-9ecf-ace26e8f2c99', 'Connecting only one cell and leaving the other disconnected', false, 'cefb44e4-43fe-4892-a3b2-218532b72277');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b5d2bb5-9a5c-4536-a168-a3ae8d5e9618', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Match Column I (Electrical Components) with Column II (Functions):
(a) Electric Cell -> (i) Produces electricity from chemical energy
(b) Switch        -> (ii) Breaks or completes an electric circuit
(c) Filament      -> (iii) Glows incandescently to emit light
(d) Rubber sleeve -> (iv) Insulates and prevents electric shock', 'Cell = chemical energy; Switch = circuit breaker; Filament = light emission; Rubber = insulation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa1d6b41-0df7-43d2-ba73-99047da62d9b', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '2b5d2bb5-9a5c-4536-a168-a3ae8d5e9618');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e5cccd1-2e12-45d4-838d-f90fda56f52d', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '2b5d2bb5-9a5c-4536-a168-a3ae8d5e9618');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6df74178-4d72-4736-90c3-b068ba87c494', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '2b5d2bb5-9a5c-4536-a168-a3ae8d5e9618');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3afccdc8-8109-4afe-bac6-a64632c73cb6', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '2b5d2bb5-9a5c-4536-a168-a3ae8d5e9618');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc1e6d1a-e0a6-46e6-8e8d-f35d3eb4d509', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Read the statements regarding electric circuits:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a447232-29cb-41f5-a702-480126604e67', 'Statements 1 and 2 only', true, 'bc1e6d1a-e0a6-46e6-8e8d-f35d3eb4d509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25cc09c4-5355-4bf4-9024-87b8e544e520', 'Statements 2 and 3 only', false, 'bc1e6d1a-e0a6-46e6-8e8d-f35d3eb4d509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a45fbce-ea1f-4aab-9520-31768ba05ecb', 'Statements 1 and 3 only', false, 'bc1e6d1a-e0a6-46e6-8e8d-f35d3eb4d509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26e75103-b2d5-4551-a49c-ece8a638a21e', 'All Statements 1, 2, and 3', false, 'bc1e6d1a-e0a6-46e6-8e8d-f35d3eb4d509');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdd83302-dd26-4886-8177-c763bf494c73', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Why is an incandescent bulb filled with an inert gas like Argon or Nitrogen rather than ordinary air?', 'Inert argon/nitrogen eliminates oxidative combustion of the tungsten filament while suppressing filament thermal evaporation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58fce452-5445-47fb-a52f-bb2181c3da86', 'Atmospheric oxygen in air would instantly burn and oxidize the white-hot tungsten filament into vapor within seconds; inert gas prevents oxidation', true, 'bdd83302-dd26-4886-8177-c763bf494c73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffd89d66-2427-401e-8818-10ee30cfc0a2', 'To make the bulb lighter so it can float', false, 'bdd83302-dd26-4886-8177-c763bf494c73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('958fdff4-6238-409c-9c3a-563359f47d47', 'Because argon makes the bulb green', false, 'bdd83302-dd26-4886-8177-c763bf494c73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36262f19-b172-4114-ae4b-e15df86a8fcd', 'To cool the glass completely', false, 'bdd83302-dd26-4886-8177-c763bf494c73');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d98879a9-7316-4abe-aa8f-770d6ab77538', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Consider four test materials placed in the gap of a conduction tester circuit:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8a3ef54-61e3-4df5-b8f9-3a7577015ac8', 'Materials 1 and 3 only (Steel and Aluminium)', true, 'd98879a9-7316-4abe-aa8f-770d6ab77538');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54bff0ee-7fb0-47f6-8981-c30096507dc0', 'Materials 2 and 4 only', false, 'd98879a9-7316-4abe-aa8f-770d6ab77538');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65637d53-6545-4b16-8102-68d176a1b6bb', 'Materials 1, 2, and 3', false, 'd98879a9-7316-4abe-aa8f-770d6ab77538');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eb9e273-7fda-45fa-bfc5-a68bbc1cea91', 'All 4 materials', false, 'd98879a9-7316-4abe-aa8f-770d6ab77538');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19f751e7-7058-4574-a339-de62a40dc84d', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'What is the physical reason why a bird perching with BOTH feet on a single bare 11,000V live high-tension electrical wire does NOT get electrocuted?', 'Current requires a potential difference (I = ΔV/R); being at equipotential with no ground circuit prevents current flow through the bird.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d46ca93-ea7b-4c18-be01-d8bbb6b2c8af', 'Both feet are on the same conductor wire at the exact same electrical potential (voltage), so there is zero potential difference (ΔV = 0) and no current flows through the bird''s body', true, '19f751e7-7058-4574-a339-de62a40dc84d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b347c257-6f6b-46c8-afaf-e534efc707be', 'Because birds have rubber feet', false, '19f751e7-7058-4574-a339-de62a40dc84d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fabe2144-4c07-43fe-8890-a6d7aa7e7fd2', 'Because high voltage cannot hurt animals', false, '19f751e7-7058-4574-a339-de62a40dc84d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13c1ebb3-3eca-4b8c-ad8d-13efef97677f', 'Because birds fly faster than current', false, '19f751e7-7058-4574-a339-de62a40dc84d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('877a2767-68ae-46ae-88ad-62a4d161a60a', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'What is a ''Light Emitting Diode'' (LED) and why is it rapidly replacing traditional tungsten incandescent bulbs in modern lighting?', 'Solid-state electroluminescence in LEDs achieves high luminous efficacy (>100 lm/W) without incandescent thermal waste.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e02a47ee-2bc0-4591-ba88-ddf3121fbfe7', 'A semiconductor diode that converts electrical energy directly into light with minimal heat generation, consuming up to 85% less electricity and lasting 25 times longer', true, '877a2767-68ae-46ae-88ad-62a4d161a60a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f993dd9-68cc-42c2-872b-9c5b241a490d', 'A bulb that works on kerosene', false, '877a2767-68ae-46ae-88ad-62a4d161a60a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b481dee-d77f-40fb-afc4-3699ed00b444', 'A chemical candle in a tube', false, '877a2767-68ae-46ae-88ad-62a4d161a60a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e00b769d-5e10-4692-9e49-9a57c53b3d7c', 'A battery that shines on its own', false, '877a2767-68ae-46ae-88ad-62a4d161a60a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73d81857-8a17-4190-aadb-b118edc46cb2', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Why must the metal terminals of an electric cell and connecting wires be scraped clean with sandpaper before making circuit connections?', 'Abrasive cleaning strips insulating metal oxide tarnish films, establishing pristine low-impedance galvanic contact.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a25ef7c7-71a0-4856-9f63-ef945c97a5f4', 'To remove non-conductive oxide layers, dirt, or lacquer coatings on the metal surface that create high contact resistance and block electric flow', true, '73d81857-8a17-4190-aadb-b118edc46cb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7389562f-e13a-42cf-925b-191b325b2272', 'To make the wire shiny', false, '73d81857-8a17-4190-aadb-b118edc46cb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9efd8e5c-ef65-4a3d-9214-b44fde2cc6e0', 'To change the wire''s color', false, '73d81857-8a17-4190-aadb-b118edc46cb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c25adb97-ead6-480f-b372-aa2a6dcbf94a', 'To make the wire thinner', false, '73d81857-8a17-4190-aadb-b118edc46cb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8178de3b-d3be-4d8d-b421-611dc286d121', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'What is the primary function of a safety ''Electric Fuse'' in household circuits?', 'A fuse provides over-current protection: excessive fault current melts the fusible alloy link, interrupting the circuit before wires overheat.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c989ad21-702c-42df-a857-9dea97ac10ff', 'A sacrificial safety wire with a low melting point that melts and breaks the circuit automatically if excessive dangerously high current flows', true, '8178de3b-d3be-4d8d-b421-611dc286d121');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29911996-8ebd-42dd-816c-540d98987fcf', 'To store extra electricity for night', false, '8178de3b-d3be-4d8d-b421-611dc286d121');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dc297d6-bf7e-4cc7-9016-d9013fb4938c', 'To make the current flow faster', false, '8178de3b-d3be-4d8d-b421-611dc286d121');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b563041f-cc55-41ea-817b-3e2a1bd49834', 'To turn off the water pump', false, '8178de3b-d3be-4d8d-b421-611dc286d121');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd98df59-8a6c-4626-aa5d-aec37eb1a20a', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'What is the foundational law of electricity established in physics regarding the conservation of electric charge in any closed circuit?', 'Kirchhoff''s Current Law reflects fundamental charge conservation: net nodal divergence of continuous current is zero.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81d11426-7e98-412b-9b64-5dac26c1fabb', 'Electric charge is neither created nor destroyed in a circuit; the total rate of charge entering any point must exactly equal the rate of charge leaving it', true, 'dd98df59-8a6c-4626-aa5d-aec37eb1a20a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3a0bd73-5e02-4495-be4a-8c5e28cfaa81', 'Electricity disappears into thin air', false, 'dd98df59-8a6c-4626-aa5d-aec37eb1a20a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c58de709-c0e4-43e9-87ec-47431e1b500d', 'Batteries create new electrons from nothing', false, 'dd98df59-8a6c-4626-aa5d-aec37eb1a20a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('227cc127-39ff-4020-8dfb-e2104a2f4558', 'Charges turn into gravity', false, 'dd98df59-8a6c-4626-aa5d-aec37eb1a20a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b62d717b-51d8-45d0-af7a-bd68c4741106', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'A collection of numbers or facts gathered together to give meaningful information is called:', 'Data is a systematic collection of numerical facts, observations, and measurements gathered for analysis.', NOW()) ON CONFLICT DO NOTHING;
