INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8af55411-fe63-4343-82c0-2c8637b3784e', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'In data handling, vertical and diagonal strokes used to count and group data items in bunches of FIVE (5) are called:', 'Tally marks group counts into bundles of 5 (four vertical lines crossed diagonally by a fifth) for rapid counting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4829848-31f6-48c8-8a0a-20a5c375f54b', 'Tally Marks (卌 = 5)', true, '8af55411-fe63-4343-82c0-2c8637b3784e');
