INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78fba39f-450f-4169-b082-70ef1c0c2fe0', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'What number is represented by the standard tally marks: 卌 卌 ||| ?', 'Two full 5-bundles (5 + 5 = 10) plus 3 individual strokes equals 13.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cecdcc0-7058-49a4-bad0-eaaa582c84bc', '13 (5 + 5 + 3 = 13)', true, '78fba39f-450f-4169-b082-70ef1c0c2fe0');
