INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c9ae695-7540-40f1-84c1-08555b19a4b9', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'The representation of statistical data through PICTURES or symbols of objects is called a:', 'A pictograph represents data counts using icons or pictorial symbols with an assigned scaling key.', NOW()) ON CONFLICT DO NOTHING;
