INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae18d3fa-1bf2-4306-a272-f0ab7d2b353d', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'In a pictograph, if one symbol 🚗 represents 10 cars, how many cars are represented by 4 complete car symbols: 🚗🚗🚗🚗 ?', '4 symbols × 10 cars per symbol = 40 cars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d936dee1-1447-464b-a0aa-4d9670a357fb', '40 cars (4 × 10 = 40)', true, 'ae18d3fa-1bf2-4306-a272-f0ab7d2b353d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a00da742-6956-450f-ad90-3c227b606f66', '4 cars', false, 'ae18d3fa-1bf2-4306-a272-f0ab7d2b353d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d270b41-4734-4930-9ec8-9bb7d9879072', '10 cars', false, 'ae18d3fa-1bf2-4306-a272-f0ab7d2b353d');
