INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3db81617-66e7-40e5-b445-398af031bafa', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'In a pictograph, if one symbol 📖 represents 50 books, how many book symbols are needed to represent 250 books in a school library?', '250 books ÷ 50 books/symbol = 5 symbols.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83aa468c-5c03-4965-a4cd-c1e14437b0c9', '5 symbols (250 ÷ 50 = 5)', true, '3db81617-66e7-40e5-b445-398af031bafa');
