INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7bad4f6-056f-4dad-8449-73ed1431d95a', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'A visual representation of data using rectangular bars of UNIFORM WIDTH with equal spacing between them is called a:', 'A bar graph uses uniform rectangular bars whose lengths/heights are proportional to the values they represent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('519a6276-8506-4540-8dbd-9a310171f6d5', 'Bar Graph (or Bar Diagram)', true, 'b7bad4f6-056f-4dad-8449-73ed1431d95a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c31a7ad5-511e-4020-b429-1dec157ed2ac', 'Pictograph', false, 'b7bad4f6-056f-4dad-8449-73ed1431d95a');
