INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2df5f6b-6190-4afa-a1f8-53409db41f4d', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'In a standard bar graph, what does the HEIGHT (or length) of each rectangular bar represent?', 'The height/length of a bar is directly proportional to the magnitude/frequency of the data it represents.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90f69ff4-f4f1-48bb-8eb2-d3cd206ace73', 'The numerical value or frequency of that category', true, 'a2df5f6b-6190-4afa-a1f8-53409db41f4d');
