INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('616922a7-6259-4e61-a673-5988e06b027a', 'The width of the page', false, 'a2df5f6b-6190-4afa-a1f8-53409db41f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7858d251-c941-461f-9730-06861693231e', 'The time of day', false, 'a2df5f6b-6190-4afa-a1f8-53409db41f4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60eaccec-e3f8-4884-aa66-28674c5554a7', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'The number of times a particular observation or data item occurs in a given dataset is called its:', 'Frequency measures the repetition count of a specific data value in a dataset.', NOW()) ON CONFLICT DO NOTHING;
