INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e15c505-0682-48a6-bc04-ae0816de64bb', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'How is the number 18 represented using standard Tally Marks?', '18 = 3 groups of 5 plus 3 individual strokes = 卌 卌 卌 |||.', NOW()) ON CONFLICT DO NOTHING;
