INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1088d1c-a4a5-4f09-997c-a65606917101', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'If a bar graph uses a scale of ''1 unit length = 5 students'', what is the number of students represented by a bar of height 6 units?', '6 units × 5 students/unit = 30 students.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28baa1e8-32f8-43b1-94ad-fd8db6c9931c', '30 students (6 × 5 = 30)', true, 'd1088d1c-a4a5-4f09-997c-a65606917101');
