INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a84107a2-69dc-42d6-aea2-fd741309914b', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'What is data collected originally by an investigator firsthand for a specific purpose called?', 'Primary raw data is collected firsthand directly from original sources by the investigator.', NOW()) ON CONFLICT DO NOTHING;
