INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e6d7cda-4357-4683-a233-78fd93750c32', 'Bar Graph', false, 'a84107a2-69dc-42d6-aea2-fd741309914b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cb088be-36ef-4604-959f-9a1e1eb4adf4', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'The following are marks scored by 20 students out of 10 in a class test: 5, 8, 4, 7, 5, 8, 6, 7, 5, 9, 8, 5, 6, 4, 7, 5, 6, 8, 9, 5. What is the frequency of mark 5?', 'Counting instances of mark 5 in the list: 5, 5, 5, 5, 5, 5 -> exactly 6 times.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a0b77c1-13f0-431c-a635-b291404b1671', '6 times (Mark 5 appears 6 times)', true, '6cb088be-36ef-4604-959f-9a1e1eb4adf4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cac4840-1e3b-4aea-8d4a-03012d396541', '5 times', false, '6cb088be-36ef-4604-959f-9a1e1eb4adf4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51541454-f549-4adb-bbee-70015943ded8', '4 times', false, '6cb088be-36ef-4604-959f-9a1e1eb4adf4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6aff6c1-3090-4c80-9e68-63119fe55f78', '7 times', false, '6cb088be-36ef-4604-959f-9a1e1eb4adf4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eba2ffac-6f48-4cc7-bc73-3306973de831', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'In a school library survey, the number of books read across subjects is: English: 40, Maths: 60, Science: 80, Social Science: 50. If 1 book icon represents 10 books in a pictograph, how many icons represent Science and Social Science respectively?', 'Science = 80/10 = 8 icons; Social Science = 50/10 = 5 icons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dea0eac6-0c38-4b4d-a10d-feaf1e3310f3', 'Science: 8 icons ; Social Science: 5 icons', true, 'eba2ffac-6f48-4cc7-bc73-3306973de831');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83400a6f-554f-4467-8b7e-638618195441', 'Science: 6 icons ; Social: 4 icons', false, 'eba2ffac-6f48-4cc7-bc73-3306973de831');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e30b278e-d7d9-4340-b8a7-0351621a8dca', 'Science: 80 icons ; Social: 50 icons', false, 'eba2ffac-6f48-4cc7-bc73-3306973de831');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b8bc613-2da6-4b6c-a8e2-473e40df6f3a', 'Science: 4 icons ; Social: 5 icons', false, 'eba2ffac-6f48-4cc7-bc73-3306973de831');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95968ffe-1ff4-4172-8b93-065da8da148b', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'A bar graph shows the number of bicycles manufactured by a factory from Monday to Friday: Mon: 300, Tue: 250, Wed: 400, Thu: 350, Fri: 500. On which day was the MAXIMUM number of bicycles manufactured, and on which day was the MINIMUM?', 'Highest bar = Friday (500 bicycles); Shortest bar = Tuesday (250 bicycles).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df634652-cfe7-4b00-9363-1ab1d74edab0', 'Maximum: Friday (500) ; Minimum: Tuesday (250)', true, '95968ffe-1ff4-4172-8b93-065da8da148b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3614450c-8987-450f-bf88-03b7be74f86d', 'Maximum: Wednesday ; Minimum: Monday', false, '95968ffe-1ff4-4172-8b93-065da8da148b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb8078a1-eac8-43ef-8995-f0a80fe3bfc4', 'Maximum: Friday ; Minimum: Monday', false, '95968ffe-1ff4-4172-8b93-065da8da148b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04e2e288-c462-4a57-b3ce-fc4d46e7bfbb', 'Maximum: Thursday ; Minimum: Tuesday', false, '95968ffe-1ff4-4172-8b93-065da8da148b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e39fc21f-c2aa-452d-8f85-110732f2d4be', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'What is the total number of bicycles manufactured from Monday to Friday in the above factory?', '300 + 250 + 400 + 350 + 500 = 1,800 bicycles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f94b62dd-3dad-4870-a2c2-a13d362293fb', '1,800 bicycles (300 + 250 + 400 + 350 + 500 = 1,800)', true, 'e39fc21f-c2aa-452d-8f85-110732f2d4be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9586ca9e-1cff-4922-bc5a-2c041691f4af', '1,700 bicycles', false, 'e39fc21f-c2aa-452d-8f85-110732f2d4be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7edfef18-56a4-450e-b0df-5594081ffedb', '2,000 bicycles', false, 'e39fc21f-c2aa-452d-8f85-110732f2d4be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8aaed30-6bb2-4d90-8226-1eb7e71699b2', '1,650 bicycles', false, 'e39fc21f-c2aa-452d-8f85-110732f2d4be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abaae31a-10c8-4282-a2c3-d206bef79a24', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'In a bar graph showing the favorite fruits of students: Mango: 45, Apple: 30, Banana: 25, Orange: 20. How many MORE students prefer Mango than Orange?', 'Difference = 45 - 20 = 25 students.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('873e7214-d917-493c-9cdb-437ec8cbfdee', '25 students (45 - 20 = 25)', true, 'abaae31a-10c8-4282-a2c3-d206bef79a24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b73c4fb5-a6dc-4a48-bf27-69ebcdce3193', '15 students', false, 'abaae31a-10c8-4282-a2c3-d206bef79a24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82ec35b2-8367-42ce-a284-2d01cbf31266', '20 students', false, 'abaae31a-10c8-4282-a2c3-d206bef79a24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('007f8e3e-7373-46b5-a2cc-bf1a8b23e948', '35 students', false, 'abaae31a-10c8-4282-a2c3-d206bef79a24');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8a7ef18-a46c-48d8-a398-022d12803b24', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'If a bar graph is drawn with a vertical scale of ''1 cm = 20 vehicles'', what will be the height of the bar representing 140 vehicles?', '140 vehicles ÷ 20 vehicles/cm = 7 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baaed2e4-7742-45af-9232-90259bc88110', '7 cm (140 ÷ 20 = 7 cm)', true, 'e8a7ef18-a46c-48d8-a398-022d12803b24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cd02259-8536-4cc6-827d-2423d19b7d9d', '6 cm', false, 'e8a7ef18-a46c-48d8-a398-022d12803b24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe6448a3-daa8-410b-942b-b4a742bf2d25', '8 cm', false, 'e8a7ef18-a46c-48d8-a398-022d12803b24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7ab3a46-d962-4469-82e9-0e9546e22793', '14 cm', false, 'e8a7ef18-a46c-48d8-a398-022d12803b24');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae2d6f5a-9225-430e-95bb-e49b53681040', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'A die was thrown 25 times and the following outcomes were recorded: 1, 2, 5, 4, 3, 6, 1, 3, 2, 5, 6, 4, 5, 2, 1, 3, 6, 5, 4, 2, 5, 3, 1, 5, 6. Which outcome appeared the MAXIMUM number of times?', 'Counting frequencies: 1:4, 2:4, 3:4, 4:3, 5:6, 6:4. Number 5 has the highest frequency (6).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf479ff9-2a39-480f-95ba-8b8fd7cddb13', 'Number 5 (frequency = 6 times)', true, 'ae2d6f5a-9225-430e-95bb-e49b53681040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab65773b-8a7a-454f-94b3-734a2f90fe22', 'Number 6 (frequency = 4 times)', false, 'ae2d6f5a-9225-430e-95bb-e49b53681040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d99015a-a986-4575-8f0a-31ff85b5eb7b', 'Number 1 (frequency = 4 times)', false, 'ae2d6f5a-9225-430e-95bb-e49b53681040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('951d38bf-f289-4cf0-be6d-3c5e3dcde975', 'Number 2 (frequency = 4 times)', false, 'ae2d6f5a-9225-430e-95bb-e49b53681040');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f18d8149-3bb0-4974-a8be-d44c4431966f', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'What is the primary advantage of a Bar Graph over a raw list of data numbers?', 'Bar graphs provide immediate visual comparison of magnitudes across categorical variables.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f24fb55-ca60-4396-be05-025e1074df5a', 'It allows instant visual comparison of different categories at a single glance without tedious manual counting', true, 'f18d8149-3bb0-4974-a8be-d44c4431966f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b64e1c83-851b-4689-8122-231bfd8c7eda', 'It makes the page look colorful', false, 'f18d8149-3bb0-4974-a8be-d44c4431966f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('120419e0-1521-4c13-b51a-63dc7eca2e71', 'It reduces the actual numbers', false, 'f18d8149-3bb0-4974-a8be-d44c4431966f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdb226d1-d407-4a50-a3cb-5f233b3a0ab3', 'It changes mathematics into art', false, 'f18d8149-3bb0-4974-a8be-d44c4431966f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc5bc280-725b-4322-979c-56667d530771', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'In a pictograph where 1 🌲 represents 100 trees, Village A has 6 🌲, Village B has 4 🌲, and Village C has 7 🌲. What is the total tree count in all three villages together?', '(6 + 4 + 7) = 17 symbols × 100 trees/symbol = 1,700 trees.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a878ff4d-fdd2-4957-a0b0-afca0573d499', '1,700 trees ((6 + 4 + 7) × 100 = 17 × 100 = 1,700)', true, 'fc5bc280-725b-4322-979c-56667d530771');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29439abf-1224-4c08-ba31-225b3ab23380', '1,500 trees', false, 'fc5bc280-725b-4322-979c-56667d530771');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d47ef6b8-7ebb-495d-a8c7-4d0d57bc6405', '1,800 trees', false, 'fc5bc280-725b-4322-979c-56667d530771');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d223219-0289-41a3-8923-41efe8db4231', '1,600 trees', false, 'fc5bc280-725b-4322-979c-56667d530771');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffed8565-af36-4fa3-861a-12902c8c9744', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'Why must all rectangular bars in a bar graph be of EQUAL WIDTH?', 'Bar width is non-data carrying; uniform width ensures that visual area remains strictly proportional to bar height.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('532451de-7807-4a51-87ae-e093f05ecd2b', 'Because the width does not represent any data value; keeping widths uniform prevents visual distortion and misleading impressions', true, 'ffed8565-af36-4fa3-861a-12902c8c9744');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12401b9d-8327-43bf-88fc-8882bf2244fa', 'Because paper only has one width', false, 'ffed8565-af36-4fa3-861a-12902c8c9744');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('601d09d2-44b8-4ec8-9f00-7c53fb84dd7a', 'Because rulers cannot draw different widths', false, 'ffed8565-af36-4fa3-861a-12902c8c9744');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ba2e020-940b-4cb8-b196-782f5039939a', 'It is not necessary, widths can be random', false, 'ffed8565-af36-4fa3-861a-12902c8c9744');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf556280-114d-4104-a65d-5831585947ce', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'In a class of 30 students, blood groups were recorded as: A: 8, B: 12, O: 7, AB: 3. What fraction of the total class has blood group B?', '12 / 30 = 2/5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9547b7df-47c5-451a-85aa-236e61607670', '2/5 (12/30 = 2/5)', true, 'bf556280-114d-4104-a65d-5831585947ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f512418-3f54-4b8e-badc-b989b1acf06d', '1/3', false, 'bf556280-114d-4104-a65d-5831585947ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adeb8da9-731e-44db-9d18-0743728bb976', '1/4', false, 'bf556280-114d-4104-a65d-5831585947ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9fbeaa3-d163-443e-886b-42fbda593274', '3/10', false, 'bf556280-114d-4104-a65d-5831585947ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04694ffd-90de-43ad-af6c-4d350cc1b01a', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'What is the first step in constructing a frequency distribution table from disorganized raw data?', 'Systematic tally grouping transforms raw unstructured data into an organized frequency distribution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('952887d9-e39b-440f-a718-e32d16b1f887', 'Identify the distinct categories, count occurrences systematically using tally marks, and total the frequencies', true, '04694ffd-90de-43ad-af6c-4d350cc1b01a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42007e8a-d2ae-4784-84cf-a7f26a49cf9b', 'Draw bars immediately without counting', false, '04694ffd-90de-43ad-af6c-4d350cc1b01a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c04fcb2d-e06f-42db-8ae2-1cc9328bc8e0', 'Color the page with pencils', false, '04694ffd-90de-43ad-af6c-4d350cc1b01a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d2c2801-a284-4ace-a66c-dc6061452e40', 'Guess the highest number', false, '04694ffd-90de-43ad-af6c-4d350cc1b01a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f59adf33-a7a3-4cd0-881e-40e8fa5b68ec', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'If 1 symbol 👶 represents 20 babies born in a hospital, how many symbols represent 70 babies (including a partial symbol)?', '70 ÷ 20 = 3.5 symbols (3 full icons + 1 half icon).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d8b7acb-2253-4b62-a71c-69c666a2b4bb', '3 ½ symbols (3 complete symbols = 60 + half symbol = 10)', true, 'f59adf33-a7a3-4cd0-881e-40e8fa5b68ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46a3961f-15c7-4131-b36b-6e32d28fbe45', '4 symbols', false, 'f59adf33-a7a3-4cd0-881e-40e8fa5b68ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d3173f6-470e-44fe-996c-e53dce350dde', '3 symbols', false, 'f59adf33-a7a3-4cd0-881e-40e8fa5b68ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb953f1f-5f9e-4c3d-99d2-6f701a28b464', '7 symbols', false, 'f59adf33-a7a3-4cd0-881e-40e8fa5b68ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dfe16251-a52c-441b-970f-a968160abe43', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'In a bar graph showing weekly rainfall: Mon: 2 cm, Tue: 5 cm, Wed: 0 cm, Thu: 3 cm, Fri: 6 cm, Sat: 4 cm, Sun: 1 cm. What is the difference in rainfall between the wettest and driest days?', 'Maximum (6 cm) - Minimum (0 cm) = 6 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04b73240-163c-4b1c-9a7c-7df4e042bc0b', '6 cm (Wettest = Fri: 6 cm ; Driest = Wed: 0 cm ; Difference = 6 - 0 = 6 cm)', true, 'dfe16251-a52c-441b-970f-a968160abe43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b84f68f5-82e3-4528-98a2-5e71a990f3d2', '5 cm', false, 'dfe16251-a52c-441b-970f-a968160abe43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d93a1a9e-4471-4ac9-94d3-8f717b392e82', '4 cm', false, 'dfe16251-a52c-441b-970f-a968160abe43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('450252aa-eeae-435a-8274-b7e6e91627b3', '7 cm', false, 'dfe16251-a52c-441b-970f-a968160abe43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a05f7443-70cd-46c7-9bf9-9f396e0cf81f', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'How can a bar graph be drawn horizontally instead of vertically?', 'Horizontal bar graphs plot categories along the ordinate (Y) and lengths along the abscissa (X).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81720dc2-4bf9-4bc4-9766-af0dd8a653fc', 'By placing categories on the vertical Y-axis and numerical values/scale on the horizontal X-axis (Horizontal Bar Graph)', true, 'a05f7443-70cd-46c7-9bf9-9f396e0cf81f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1868ae5b-554c-4a63-b3cc-f580ba4bde62', 'By turning the paper upside down', false, 'a05f7443-70cd-46c7-9bf9-9f396e0cf81f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('613bc742-b867-42a9-9fc5-7c8dced92e0d', 'By drawing curved lines', false, 'a05f7443-70cd-46c7-9bf9-9f396e0cf81f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dc7ab52-44ad-4829-aedd-05740e3aeeae', 'Bar graphs cannot be drawn horizontally', false, 'a05f7443-70cd-46c7-9bf9-9f396e0cf81f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('560ac667-a35b-4722-84be-4f00d58f7d34', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'What is the total sum of frequencies in a complete frequency table equal to?', 'The sum of all category frequencies (Σf) must exactly equal total sample size N.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d22e94b-1c40-4b59-b8c3-d78e0b4e72ba', 'The total number of observations in the original dataset', true, '560ac667-a35b-4722-84be-4f00d58f7d34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3336abe-6963-4cd5-b6ee-53e8a2a70b09', 'Zero', false, '560ac667-a35b-4722-84be-4f00d58f7d34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66d2c0a0-66d0-44bd-ba7b-c16bbe6c9e11', 'Always 100', false, '560ac667-a35b-4722-84be-4f00d58f7d34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e170b934-d4a4-4a0e-aee4-e5518e79217f', 'The highest mark', false, '560ac667-a35b-4722-84be-4f00d58f7d34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a6b8c42-3159-42f6-a302-0686630e366c', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa3455d0-b378-41d5-81aa-5fa79ada2085', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '4a6b8c42-3159-42f6-a302-0686630e366c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c72512a-a450-42d4-8020-a752ebc127ce', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '4a6b8c42-3159-42f6-a302-0686630e366c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d1b94b9-4e64-44c8-9985-98474031d7b2', '(A) is true, but (R) is false.', false, '4a6b8c42-3159-42f6-a302-0686630e366c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c287fbc7-21cb-4e96-9ddf-cee36678f283', '(A) is false, but (R) is true.', false, '4a6b8c42-3159-42f6-a302-0686630e366c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e064d34-981a-4295-ad8d-beb38f58fb4d', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Spot the IMPOSTER in the following tally representations of numbers:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95047cad-f4a1-4bbf-a2d5-8b91a41cc30b', '8 = 卌 |||', false, '7e064d34-981a-4295-ad8d-beb38f58fb4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc78c3f2-129a-4c24-80b9-2a67b4b509a0', '10 = 卌 卌', false, '7e064d34-981a-4295-ad8d-beb38f58fb4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('426f6195-a71d-435c-af51-e93c90723a9a', '14 = 卌 卌 ||||', false, '7e064d34-981a-4295-ad8d-beb38f58fb4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0735129e-6980-438a-aee7-d2c7c50ab5dd', '16 = 卌 卌 卌 ||', true, '7e064d34-981a-4295-ad8d-beb38f58fb4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be3e8382-1cf6-44b4-bc2c-15f490023841', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'A bar graph shows the population of a town over four decades:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa102a38-79ce-49fc-b0a3-3d9f2f24b928', '2010 to 2020 (Increase = 80,000 - 55,000 = 25,000)', true, 'be3e8382-1cf6-44b4-bc2c-15f490023841');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f104144-b5b3-4ef9-b917-2aad5585a483', '1990 to 2000 (15,000)', false, 'be3e8382-1cf6-44b4-bc2c-15f490023841');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc1766b5-af0e-4fcb-a136-74f56071ad28', '2000 to 2010 (20,000)', false, 'be3e8382-1cf6-44b4-bc2c-15f490023841');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9cdb8cf-f4fa-4e2f-9ab7-6f5367328785', 'All decades had equal increase', false, 'be3e8382-1cf6-44b4-bc2c-15f490023841');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42dfabd7-f1f5-40e6-b905-b112fce1c5db', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Match Column I (Data Concepts) with Column II (Definitions / Symbols):
(a) Tally Mark bundle 卌 -> (i) Proportional rectangular visual display
(b) Pictograph          -> (ii) Groups 5 counts together
(c) Frequency            -> (iii) Uses pictures with scaling keys
(d) Bar Graph            -> (iv) Number of occurrences of a data item', '卌 = 5 bundle; Pictograph = picture icons; Frequency = count; Bar graph = proportional bars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8504f443-b1bd-4fa1-98dc-36e29269ce01', 'a-(ii), b-(iii), c-(iv), d-(i)', true, '42dfabd7-f1f5-40e6-b905-b112fce1c5db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4c3a983-529b-455c-810a-a59a9e1f50b8', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '42dfabd7-f1f5-40e6-b905-b112fce1c5db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69f1c15e-0806-4830-ae72-e325d84be453', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '42dfabd7-f1f5-40e6-b905-b112fce1c5db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13a89319-18dc-48a9-85d9-69d8ae442718', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '42dfabd7-f1f5-40e6-b905-b112fce1c5db');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f7ffcbf-d2ac-45b4-92a2-68dc548ca2c4', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Read the statements regarding graphs:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e598d6d2-2ac7-4886-bdfe-69b866321c5e', 'Statements 1 and 2 only', true, '0f7ffcbf-d2ac-45b4-92a2-68dc548ca2c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab75f1b4-4bea-4178-b5a9-550c8e02c65a', 'Statements 2 and 3 only', false, '0f7ffcbf-d2ac-45b4-92a2-68dc548ca2c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97ead109-b69f-43d8-a9fc-54225884e55a', 'Statements 1 and 3 only', false, '0f7ffcbf-d2ac-45b4-92a2-68dc548ca2c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b68f825-0729-43ad-9c62-3f9916024f25', 'All Statements 1, 2, and 3', false, '0f7ffcbf-d2ac-45b4-92a2-68dc548ca2c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00b25bfb-e3e4-4aa0-8626-c4ca1dbc24e7', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'A factory produces 4 types of vehicles in a month: Cars: 120, Vans: 60, Trucks: 40, Motorcycles: 180. If drawn on a bar graph with scale 1 cm = 20 vehicles, what will be the combined total height of all 4 bars?', 'Heights: Cars=6 cm, Vans=3 cm, Trucks=2 cm, Bikes=9 cm. Total = 6+3+2+9 = 20 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d605420-f031-45da-a79f-247084482657', '20 cm ((120 + 60 + 40 + 180)/20 = 400/20 = 20 cm)', true, '00b25bfb-e3e4-4aa0-8626-c4ca1dbc24e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7ca2b9f-c9e0-4f15-be2e-57c62dd64518', '18 cm', false, '00b25bfb-e3e4-4aa0-8626-c4ca1dbc24e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9bcba54-f239-42d6-89c7-eef2454b070a', '25 cm', false, '00b25bfb-e3e4-4aa0-8626-c4ca1dbc24e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f3d42b9-5be7-4350-b8c0-29bdf66abe33', '40 cm', false, '00b25bfb-e3e4-4aa0-8626-c4ca1dbc24e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63777415-9bc7-41ca-a0f7-77b54ae62280', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Consider a dataset of 50 student test scores ranging from minimum score 12 to maximum score 98. What is the most appropriate scale for the vertical axis of a bar graph on standard graph paper (height ~20 cm)?', '1 unit = 10 marks maps the 0–100 range across a 10 cm vertical span.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8a942a3-eb88-4ef9-aebb-5510f60da560', '1 unit length = 10 marks (so 100 marks fits comfortably in 10 cm)', true, '63777415-9bc7-41ca-a0f7-77b54ae62280');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98a1a64e-4b9a-4f19-906d-fdeaac956a40', '1 unit length = 1 mark (needs 100 cm paper)', false, '63777415-9bc7-41ca-a0f7-77b54ae62280');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21b1d686-841b-4dd6-afc0-7650457d7791', '1 unit length = 50 marks', false, '63777415-9bc7-41ca-a0f7-77b54ae62280');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beef341f-c003-4b20-9f47-548d3c4f4ac3', '1 unit length = 100 marks', false, '63777415-9bc7-41ca-a0f7-77b54ae62280');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c64f09e2-4d34-4956-9d81-b26edeb83669', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'In a pictograph where 1 🌸 represents 50 flowers, a florist sells 225 roses and 175 lilies. How many total flower symbols (including fractions) represent roses and lilies together?', 'Total flowers = 225 + 175 = 400 flowers ÷ 50 flowers/symbol = 8 symbols.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00b96ee2-01ae-4a3e-b37c-6c1e2cc40d20', '8 symbols (225/50 = 4.5 symbols ; 175/50 = 3.5 symbols ; Total = 4.5 + 3.5 = 8 symbols)', true, 'c64f09e2-4d34-4956-9d81-b26edeb83669');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('711a43e0-f427-4446-9b78-0cb61288dc4b', '7 symbols', false, 'c64f09e2-4d34-4956-9d81-b26edeb83669');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7f65a0a-2273-429a-9331-5b2459b9dd1d', '9 symbols', false, 'c64f09e2-4d34-4956-9d81-b26edeb83669');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73326561-73c3-4830-ba49-d63bad1b4047', '10 symbols', false, 'c64f09e2-4d34-4956-9d81-b26edeb83669');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bffc8348-65f3-44b2-a5a8-62ab5c3f3f26', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'A survey asked 120 people their favorite mode of transport: Bus: 48, Train: 36, Car: 24, Bicycle: 12. What percentage of total people prefer Bus?', '(48 ÷ 120) × 100% = 0.40 × 100% = 40%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4992f6f-dd57-479c-8673-45490bc5a9fd', '40% ((48/120) × 100% = 40%)', true, 'bffc8348-65f3-44b2-a5a8-62ab5c3f3f26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb20d253-09e0-40b2-950f-ca6a9bd8641e', '48%', false, 'bffc8348-65f3-44b2-a5a8-62ab5c3f3f26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f201e7bc-3fb2-4d7a-b60a-c6ec0ce87f74', '30%', false, 'bffc8348-65f3-44b2-a5a8-62ab5c3f3f26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b92a218-30b4-457a-9037-0b35a4a2ebec', '36%', false, 'bffc8348-65f3-44b2-a5a8-62ab5c3f3f26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8dc21d4-d16c-4309-a4e2-32d8503b2db6', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'What is a ''Double Bar Graph'' used for in advanced data handling?', 'Double bar graphs pair bivariate data series side by side across common categories.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb90da53-7beb-4321-a547-3d60bcaeefa6', 'To display two sets of data simultaneously side by side for direct comparison between two groups or two time periods', true, 'b8dc21d4-d16c-4309-a4e2-32d8503b2db6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('630d42b1-a269-47e0-ba65-effd38befd09', 'To draw bars twice as wide', false, 'b8dc21d4-d16c-4309-a4e2-32d8503b2db6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8696acfd-3769-4064-a048-5887b69799d5', 'To color bars with two paints', false, 'b8dc21d4-d16c-4309-a4e2-32d8503b2db6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b684e849-03ee-4b4a-ad67-f06edf56a208', 'To erase mistakes', false, 'b8dc21d4-d16c-4309-a4e2-32d8503b2db6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aff60cbf-2047-4fcb-8af5-5803d33d72b6', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'If the mean (average) score of 5 matches played by a batsman is 42 runs, what is the total number of runs scored by him in all 5 matches?', 'Sum = Mean × N = 42 × 5 = 210 runs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51db0360-3c16-49e4-b0b1-df639aa9f96c', '210 runs (Total = Mean × Number of matches = 42 × 5 = 210)', true, 'aff60cbf-2047-4fcb-8af5-5803d33d72b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2eadc95-7ef3-40d7-829c-8c3bed34d95d', '200 runs', false, 'aff60cbf-2047-4fcb-8af5-5803d33d72b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1e694a8-baf3-4e86-9181-74037f90f191', '225 runs', false, 'aff60cbf-2047-4fcb-8af5-5803d33d72b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6aa66e3-f5fa-4c94-99e0-86e93289a094', '180 runs', false, 'aff60cbf-2047-4fcb-8af5-5803d33d72b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76a6c7e1-0f89-484e-ba36-5b1720b072bc', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Why is statistical data collection and visual representation critical in modern scientific and government decision making?', 'Visual analytics reveal underlying trends, outliers, and distributions to guide evidence-based policy formulation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('664eb15a-d224-4431-b04e-3ca9b9cba9ad', 'It transforms vast, complex numerical data into clear, objective visual trends, enabling evidence-based policy, planning, and scientific forecasting', true, '76a6c7e1-0f89-484e-ba36-5b1720b072bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ca029a8-b91e-4e11-982e-cc7f7fec74b2', 'Because computers cannot read numbers without graphs', false, '76a6c7e1-0f89-484e-ba36-5b1720b072bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aae82c0-0b7c-4119-8dae-e5a723562fcc', 'To make government books heavier', false, '76a6c7e1-0f89-484e-ba36-5b1720b072bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75d4a4b1-4531-4754-a34b-551fea146221', 'Because graphs eliminate the need for mathematics', false, '76a6c7e1-0f89-484e-ba36-5b1720b072bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6542f1da-b896-4823-a102-4617db42db56', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'What are Deserts defined as in ''Desert Animals''?', 'Deserts are hyper-arid biomes enduring prolonged droughts, yet harboring uniquely adapted wildlife.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f82b329-18ac-4a44-9895-f9e74ce71e61', 'The driest places on Earth that sometimes go for months or even years without any rainfall', true, '6542f1da-b896-4823-a102-4617db42db56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9679a902-74fe-4f30-892b-664d34d202e3', 'Areas covered with snow', false, '6542f1da-b896-4823-a102-4617db42db56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca5c95ef-15ee-49b7-9757-2363f635bc86', 'Places full of rivers', false, '6542f1da-b896-4823-a102-4617db42db56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdfbf868-5982-4cb1-bf2d-fdb9c1c71497', 'Dense tropical forests', false, '6542f1da-b896-4823-a102-4617db42db56');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f0eb54a-9f85-415d-a134-a442fd777342', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'How do tiny desert rodents called ''Gerbils'' spend the hottest scorching hours of the desert day?', 'Gerbils avoid lethal surface heat by retreating into cool subterranean burrows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5c05f1f-0f6a-4115-b6dc-c53d19c8c0ce', 'In cool, deep underground burrows', true, '5f0eb54a-9f85-415d-a134-a442fd777342');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d13fefb-a5d8-4117-a340-e8133efd0020', 'Swimming in desert lakes', false, '5f0eb54a-9f85-415d-a134-a442fd777342');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('751738f4-5be2-482b-91c3-dc9be1f51acc', 'Climbing cactus trees', false, '5f0eb54a-9f85-415d-a134-a442fd777342');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e724688-f32c-44aa-87c7-83c623122a89', 'Sleeping in clouds', false, '5f0eb54a-9f85-415d-a134-a442fd777342');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fba85c3d-e99f-4881-bab8-5d22bad378e3', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'How do strange desert insects called ''Darkling Beetles'' harvest drinking water in the arid desert?', 'Stenocara beetles employ fog-basking: condensing coastal fog on hydrophilic shell bumps and tilting to drink.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a55da6b3-190b-4a88-b191-e75d2f8ee61b', 'They catch morning fog droplets on their legs and tilt their bodies upward so the water drops trickle down directly into their mouths', true, 'fba85c3d-e99f-4881-bab8-5d22bad378e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f03d42ea-2ec0-4ce7-8cd1-09ea19f819e0', 'They dig 50-foot wells', false, 'fba85c3d-e99f-4881-bab8-5d22bad378e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f4a9847-a01a-4568-b98e-e55749d57591', 'They drink water from cactus roots', false, 'fba85c3d-e99f-4881-bab8-5d22bad378e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32e0d322-f8db-4742-afa2-14ddedf5bc2f', 'They don''t need water at all', false, 'fba85c3d-e99f-4881-bab8-5d22bad378e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52480d50-01a7-4c30-9d29-b7aeafb4ba3d', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'Why do Rattlesnakes vibrate their dry rattle tails when threatened by an intruder?', 'Interlocking keratinous rattle segments buzz audibly at 30 meters as an aposematic defensive warning.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('357fef9a-15b6-474f-9563-923fd154f812', 'To produce a loud rattling warning sound that can be heard up to 30 metres away, warning the intruder to back off', true, '52480d50-01a7-4c30-9d29-b7aeafb4ba3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7df0d270-2388-4c47-9108-17be4ebcae62', 'To attract prey animals', false, '52480d50-01a7-4c30-9d29-b7aeafb4ba3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eef311ad-704f-4423-9365-56d43e6a6a4e', 'To keep their tail warm', false, '52480d50-01a7-4c30-9d29-b7aeafb4ba3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d381adb5-7179-4354-ad36-37f0cf2345ae', 'To make music in the desert', false, '52480d50-01a7-4c30-9d29-b7aeafb4ba3d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6af20f43-b95a-461c-b1e7-73f9e7b5a39d', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'How do snakes ''hear'' approaching footsteps despite being completely deaf to airborne sounds?', 'Lacking tympanic ears, snakes detect substrate acoustic seismic vibrations through somatic mechanoreceptors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68052f1b-800b-4167-9b32-38196f70f8d8', 'They feel ground vibrations directly through their sensitive belly scales and lower jawbones', true, '6af20f43-b95a-461c-b1e7-73f9e7b5a39d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e7284cf-27de-4733-86a8-e198a8654d13', 'Through big hidden ears', false, '6af20f43-b95a-461c-b1e7-73f9e7b5a39d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad8b226d-8709-4555-8eb9-9c43c62b8a89', 'Through their long tongues', false, '6af20f43-b95a-461c-b1e7-73f9e7b5a39d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd055376-f9f5-4c3a-9349-ca82a6a1d980', 'Through their eyes', false, '6af20f43-b95a-461c-b1e7-73f9e7b5a39d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66a2f02b-fd40-47e4-be00-e809f11a2fb2', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'What animal is famous for its astonishing speed and lightning-fast reflexes that enable it to kill deadly venomous snakes without getting bitten?', 'Mongooses combine agile predatory reflexes with specialized neurotoxin resistance to conquer venomous snakes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('077da31e-f425-41d4-ae5e-f75e62b77b2e', 'Mongoose', true, '66a2f02b-fd40-47e4-be00-e809f11a2fb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa639a45-b8e5-45c4-b822-eaa24f586648', 'Desert Rat', false, '66a2f02b-fd40-47e4-be00-e809f11a2fb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a71bed83-e97a-4661-a511-dd1ddf70a064', 'Camel', false, '66a2f02b-fd40-47e4-be00-e809f11a2fb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05da0aa2-73d0-435f-a42f-db55b116e38e', 'Gerbil', false, '66a2f02b-fd40-47e4-be00-e809f11a2fb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f5b7f4d-dffb-4ca2-a137-aa0e6ae57281', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'What are the two distinct types of Camels found in the world?', 'Camelus dromedarius has a single hump, while Central Asian Camelus bactrianus possesses two humps.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ea2a072-d292-4cb5-af6b-38dfee4081bd', 'Dromedary Camel (with ONE hump) and Bactrian Camel (with TWO humps)', true, '1f5b7f4d-dffb-4ca2-a137-aa0e6ae57281');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c641ec6f-af10-483a-81ab-e77e01792752', 'African Camel and Arctic Camel', false, '1f5b7f4d-dffb-4ca2-a137-aa0e6ae57281');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68edee8f-e047-4a20-9e70-ff439c0496ee', 'Water Camel and Land Camel', false, '1f5b7f4d-dffb-4ca2-a137-aa0e6ae57281');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69af8306-a8d0-4573-b50d-82e067e9c8a6', 'Mountain Camel and Forest Camel', false, '1f5b7f4d-dffb-4ca2-a137-aa0e6ae57281');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ada2ede-6e4d-464e-a85c-006dd87b2053', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'What is stored inside a Camel''s hump?', 'A camel''s hump stores adipose fat tissue, metabolizing into metabolic water and nourishment during famine.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ea73271-0eb9-4764-be64-f37de1dfe091', 'Fat (which acts as a nourishment reserve and metabolic food supply)', true, '8ada2ede-6e4d-464e-a85c-006dd87b2053');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d54d8f2d-46c6-4411-b8dd-d0159900a4b2', 'Drinking water', false, '8ada2ede-6e4d-464e-a85c-006dd87b2053');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9303c743-23d9-4838-972c-2e6b540f4bdb', 'Air', false, '8ada2ede-6e4d-464e-a85c-006dd87b2053');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0981a582-f97a-4624-907e-687ec8fd20b2', 'Bones', false, '8ada2ede-6e4d-464e-a85c-006dd87b2053');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a23a3ec-2923-41b5-ae60-b62b19acc399', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'In the supplementary story ''What Happened to the Reptiles'', what was the peaceful forest village called?', 'Pambupatti was an idyllic peaceful village where Prem took shelter after escaping communal violence in his hometown.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('696a5996-cbcc-4608-9a0a-078a88c6019c', 'Pambupatti (a village where people of all communities lived in peace)', true, '1a23a3ec-2923-41b5-ae60-b62b19acc399');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b4ad2f4-6bc6-44fa-aead-62f38dd2b000', 'Rampur', false, '1a23a3ec-2923-41b5-ae60-b62b19acc399');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8812928b-cd9a-4350-aeea-d296fe5b7ea7', 'Shampur', false, '1a23a3ec-2923-41b5-ae60-b62b19acc399');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b3890a5-bf25-415b-80df-d9cd8d43379d', 'Sitapur', false, '1a23a3ec-2923-41b5-ae60-b62b19acc399');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8776bca0-c67a-42fc-a91b-0ec9e601bd01', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'Who was Makara in the ancient fable of Pambupatti?', 'Makara was a domineering tyrant crocodile who bullied other reptiles into unquestioning subservience.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ba0d731-0c2f-4137-bda9-47469a2e77cc', 'The biggest, strongest, and most arrogant crocodile who was the president of the reptile council', true, '8776bca0-c67a-42fc-a91b-0ec9e601bd01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50b3d8b8-641f-4f73-b466-9577696a3fc6', 'A wise old tortoise', false, '8776bca0-c67a-42fc-a91b-0ec9e601bd01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80a5d9e5-395d-4d03-ab16-c3689b19c781', 'A poisonous snake', false, '8776bca0-c67a-42fc-a91b-0ec9e601bd01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0d0d54d-2062-44d4-accc-6caf03a9ef48', 'A harmless lizard', false, '8776bca0-c67a-42fc-a91b-0ec9e601bd01');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3c5966b-eae8-44da-a895-2abaf44f173a', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'Which gentle, slow-moving creature was the FIRST to be expelled from the forest by Makara''s tyrannical decree?', 'Makara expelled peaceful tortoises first, arrogantly mocking their slow pace and protective shells.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35224869-3aeb-438e-825b-8ec86672d6fc', 'The Tortoises (led by wise old Prem)', true, 'e3c5966b-eae8-44da-a895-2abaf44f173a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2ef173a-5257-4455-926b-f456473f6995', 'The Snakes', false, 'e3c5966b-eae8-44da-a895-2abaf44f173a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66d1cb89-726c-4cbd-bf79-e970e116ac93', 'The Lizards', false, 'e3c5966b-eae8-44da-a895-2abaf44f173a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0ffbcbf-6ffe-481d-9751-4ad152552343', 'The Frogs', false, 'e3c5966b-eae8-44da-a895-2abaf44f173a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c398f78-831e-480c-9b87-9e6d86d837b3', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'What happened to the forest ecosystem of Pambupatti after Makara drove out tortoises, snakes, and lizards?', 'Expelling natural predator and scavenger reptiles triggered an explosive plague of rats and insect pests.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c78ca2c5-603e-4473-81e2-ed1ec10ca8c0', 'A disastrous ecological crisis occurred: rats multiplied out of control eating eggs, rotting smell filled the air, and millions of insects infested the forest', true, '7c398f78-831e-480c-9b87-9e6d86d837b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf2b75bc-1d0c-4a68-bc80-44f9fac72025', 'The forest became a paradise', false, '7c398f78-831e-480c-9b87-9e6d86d837b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4df187b-fc5b-4a5c-9a16-526d45988b9b', 'Crocodiles became twice as large', false, '7c398f78-831e-480c-9b87-9e6d86d837b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f29862e8-b9a0-4129-892b-3b4dd05113fe', 'All rivers turned into gold', false, '7c398f78-831e-480c-9b87-9e6d86d837b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('192b12e7-3653-4932-9459-2ed465cbf904', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'How does a Mongoose successfully defeat a venomous cobra in combat?', 'Tactical agility: the mongoose dances out of strike range, exhausting the serpent''s energy reserves before delivering a lethal cervical bite.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1df060c5-3fc5-431a-b297-e065fc7f467c', 'By constantly dodging, darting, and exhausting the snake through repeated evasive maneuvers until the tired snake strikes slowly, then biting its neck', true, '192b12e7-3653-4932-9459-2ed465cbf904');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59236ad1-530f-4e96-a29f-8d67b6ca01d9', 'By using poison gas', false, '192b12e7-3653-4932-9459-2ed465cbf904');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2ece41d-1ed0-4590-853b-edcd2c4612ba', 'By hypnotizing the snake with music', false, '192b12e7-3653-4932-9459-2ed465cbf904');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06acf687-db24-46e3-91b7-e68b2664353f', 'By hiding in trees', false, '192b12e7-3653-4932-9459-2ed465cbf904');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5f9c3c4-c5b4-403b-a817-0ebca82eba87', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Why do Mongooses hunt in friendly groups and constantly stay in touch using twittering and whistling sounds?', 'Cooperative social foraging: contact calls coordinate foraging while sentinel alarm chirps warn of aerial raptors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b0abacf-b311-4d6b-8f10-3534230973a2', 'To keep track of each other while hunting in dense brush and alert the whole clan immediately if a predator (like a hawk or eagle) appears', true, 'a5f9c3c4-c5b4-403b-a817-0ebca82eba87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d26fba58-675f-4790-860d-d479433d7d14', 'Because they like to sing songs', false, 'a5f9c3c4-c5b4-403b-a817-0ebca82eba87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1afb5ca-0e91-428a-b08a-8fb33619f9a4', 'To scare away all insects', false, 'a5f9c3c4-c5b4-403b-a817-0ebca82eba87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4778d026-e428-4676-9686-37f6eb4f20b6', 'To practice speaking human words', false, 'a5f9c3c4-c5b4-403b-a817-0ebca82eba87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b003edc-ce54-4104-a9e1-ad4ddd21406e', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'How much water can a thirsty camel drink in a single 10-minute session?', 'Rehydrating camels can drink over 100 litres of water in 10 minutes without osmotic hemolysis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b42bdbd6-6b2e-4f81-8c48-68800471630a', 'As much as 30 gallons (about 500 glasses of water / ~115 to 135 litres)', true, '0b003edc-ce54-4104-a9e1-ad4ddd21406e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('373379da-3686-430c-ba21-771be27f6da2', 'Only 1 glass', false, '0b003edc-ce54-4104-a9e1-ad4ddd21406e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04885c7b-541a-4220-abb6-1538c00908cd', '5 litres', false, '0b003edc-ce54-4104-a9e1-ad4ddd21406e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dd2e85d-ba42-4195-98ce-4d315840dad7', '500 gallons', false, '0b003edc-ce54-4104-a9e1-ad4ddd21406e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd494c27-19c5-4a58-9ce3-2babf7658357', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'How does a Camel''s mouth adapt to eating thorny desert cactus plants without getting hurt?', 'Dense, heavily keratinized conical oral papillae protect the camel''s palate and gums against sharp desert thorns.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d79ede58-1ec8-4c30-b27a-fef3d2c0e6bd', 'Its mouth is lined with tough, thick leathery mucous membranes that sharp thorns cannot pierce', true, 'cd494c27-19c5-4a58-9ce3-2babf7658357');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cae5854b-9e4a-42eb-b1c2-f2981ba05d76', 'It melts thorns with boiling saliva', false, 'cd494c27-19c5-4a58-9ce3-2babf7658357');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('066c05bf-d4d2-45d0-9edb-cde1b3433969', 'It has steel teeth', false, 'cd494c27-19c5-4a58-9ce3-2babf7658357');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a8b250a-0f2d-49f0-9bb8-560be8c42c6d', 'It only eats powdered cactus', false, 'cd494c27-19c5-4a58-9ce3-2babf7658357');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47e7bfe5-faa1-481a-9c5a-b4a1d38167fb', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Why was Makara forced to send urgent letters recalling all the expelled snakes, tortoises, and lizards back to Pambupatti?', 'Ecological pestilence humbled Makara''s tyranny, forcing him to restore the reptile community.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b78e637-e8e5-4464-98d8-26d46fc4f7b5', 'Because millions of bold rats were chewing baby crocodile tails, frogs were invading every pool, and the forest had become unlivable without ecological balance', true, '47e7bfe5-faa1-481a-9c5a-b4a1d38167fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d91f65b4-43f2-4b8c-ac90-2e29dcd9dc7b', 'Because Makara wanted to have a dance party', false, '47e7bfe5-faa1-481a-9c5a-b4a1d38167fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d5a67fd-f203-41d1-a8ad-670df0542d4b', 'Because the crocodiles felt lonely', false, '47e7bfe5-faa1-481a-9c5a-b4a1d38167fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1eb5353f-c9b3-49df-949c-7eb805f56d16', 'Because the government ordered them', false, '47e7bfe5-faa1-481a-9c5a-b4a1d38167fb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('803f8623-a4ea-41cf-a284-74d54c050f4f', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'What profound moral and environmental lesson does Zai Whitaker''s story ''What Happened to the Reptiles'' teach?', 'An ecological and socio-political allegory demonstrating that biodiversity and human pluralism are essential for survival.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c32533c-960d-4fcc-9779-0a095dc3e30e', 'Every single creature in an ecosystem has an indispensable role; no species or human community is superior, and harmony requires celebrating diversity and mutual coexistence', true, '803f8623-a4ea-41cf-a284-74d54c050f4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd194a11-eae3-44ac-a6c5-c3949680dcaa', 'Crocodiles are the wisest animals', false, '803f8623-a4ea-41cf-a284-74d54c050f4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2edbca19-b830-4e87-9bd0-d9a926e4ed95', 'Villages should have no reptiles', false, '803f8623-a4ea-41cf-a284-74d54c050f4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('092961be-8147-4cdd-b06d-df67efcf76ab', 'Rats make the best pets', false, '803f8623-a4ea-41cf-a284-74d54c050f4f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84810e05-51be-45b3-8aa8-502c01ad4aed', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Why did the old man in Pambupatti tell the story to Prem, who had fled from communal riots in his distant city?', 'The elder uses the ecological parable to heal Prem''s trauma and inspire him as an ambassador of communal harmony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b8021db-371a-4ee5-a240-932bf58af85e', 'To make Prem realize that hatred, exclusion, and intolerance destroy society, and that he must return home to spread the message of peaceful communal coexistence', true, '84810e05-51be-45b3-8aa8-502c01ad4aed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('819f32a3-d7e1-4720-a544-fa2d18a2d7aa', 'To scare Prem with crocodile tales', false, '84810e05-51be-45b3-8aa8-502c01ad4aed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ca1ccd7-99cc-4162-b867-0ceb255151bf', 'To teach him how to hunt snakes', false, '84810e05-51be-45b3-8aa8-502c01ad4aed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cf3332f-4412-4052-9d1e-6c951bf57fe6', 'To pass time before dinner', false, '84810e05-51be-45b3-8aa8-502c01ad4aed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b868a2d2-6581-4572-b639-59855f6b7f4b', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'What does the word ''Predator'' mean in biological ecology?', 'A predator is a carnivorous organism that preys upon other organisms for metabolic sustenance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93039eae-a8c1-4480-8914-d0e58db56701', 'An animal that hunts, kills, and feeds on other animals (prey)', true, 'b868a2d2-6581-4572-b639-59855f6b7f4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81bd01ba-7305-407e-b997-622d1f76e7ee', 'An animal that only eats grass', false, 'b868a2d2-6581-4572-b639-59855f6b7f4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99bc957d-90a6-4ee3-8fe1-1b717a3c86f1', 'An animal that lives underwater', false, 'b868a2d2-6581-4572-b639-59855f6b7f4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc5dec99-16ad-418c-b4d0-c3b53cf5489f', 'A pet animal', false, 'b868a2d2-6581-4572-b639-59855f6b7f4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a27c4349-8f83-437c-9317-889931879123', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'How do Rattle snakes perceive warm-blooded prey in total darkness?', 'Pit vipers possess infrared pit organs mapping thermal infrared signatures of endothermic rodent prey.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9d29a83-da76-4391-808a-bd98b4bf0c19', 'Through thermal heat-sensing pit organs located between their eyes and nostrils that detect infrared thermal radiation', true, 'a27c4349-8f83-437c-9317-889931879123');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dd2fdc8-9d20-4eb6-87bc-f629fcdc4c18', 'Using night-vision glasses', false, 'a27c4349-8f83-437c-9317-889931879123');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19e187b1-5a1b-4d4d-a338-ebdd7784e31c', 'Through loud shouts', false, 'a27c4349-8f83-437c-9317-889931879123');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbad7311-9960-4f22-91b1-6d437d6bd375', 'By smelling with their ears', false, 'a27c4349-8f83-437c-9317-889931879123');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d86d382f-1fd6-49fa-af31-2906f89d104e', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'What is ''Communal Harmony'' as reflected in the village of Pambupatti?', 'Communal harmony embodies interfaith tolerance, pluralistic fraternity, and peaceful social cohesion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55615e8e-4790-4605-a20b-da09c572f92a', 'People belonging to different religions, backgrounds, and communities living together in mutual peace, respect, equality, and brotherhood', true, 'd86d382f-1fd6-49fa-af31-2906f89d104e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('120ae7d2-6230-415b-bc4e-694706f4fbd1', 'People fighting over property', false, 'd86d382f-1fd6-49fa-af31-2906f89d104e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62de5fc0-58df-4dfd-bae6-80de41b1bd01', 'Only one group ruling everyone else', false, 'd86d382f-1fd6-49fa-af31-2906f89d104e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f3cd5a3-0104-471e-8836-6e9c8ad8e282', 'Living without any laws', false, 'd86d382f-1fd6-49fa-af31-2906f89d104e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1eab0053-1363-4320-8a72-46d9e41d4ce7', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Why does a camel sweat so little compared to humans?', 'Adaptive heterothermy: camels tolerate diurnal body temperatures from 34°C to 41°C, minimizing evaporative sweat loss.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70e53878-5c76-42d0-998e-b084dc2889b0', 'Camels can withstand body temperature fluctuations up to 42°C without sweating, conserving vital body water in desert heat', true, '1eab0053-1363-4320-8a72-46d9e41d4ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ef74a40-d3a6-4f3e-a130-61e2bbe3bfac', 'Camels have no sweat glands', false, '1eab0053-1363-4320-8a72-46d9e41d4ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e168a6b9-d856-4f53-9c73-71addc8f5f0d', 'Camels are made of stone', false, '1eab0053-1363-4320-8a72-46d9e41d4ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76851fc6-540b-427d-bc0e-59d298e16234', 'Camels only sweat in winter', false, '1eab0053-1363-4320-8a72-46d9e41d4ce7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19d9b10d-8ad6-4d8f-8ee6-1ee2dc602b09', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'What role do lizards and chameleons play in maintaining the forest ecology of Pambupatti?', 'Insectivorous lizards provide critical top-down biological pest control in forest biomes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf108353-a806-4edb-9bab-54040ad5da75', 'They consume millions of insects and pests daily, preventing insect swarms from destroying plants and trees', true, '19d9b10d-8ad6-4d8f-8ee6-1ee2dc602b09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fefdc772-ff23-4534-9c19-594cf5efc3a8', 'They build wooden bridges', false, '19d9b10d-8ad6-4d8f-8ee6-1ee2dc602b09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20621e48-4984-43d6-8132-474595a6cebc', 'They dig deep rivers', false, '19d9b10d-8ad6-4d8f-8ee6-1ee2dc602b09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07656cca-4d3a-41cf-9326-40599973f5fc', 'They hunt crocodiles', false, '19d9b10d-8ad6-4d8f-8ee6-1ee2dc602b09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b60ad923-a987-49a7-b042-3d6587de13d5', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'What does the phrase ''to turn a deaf ear'' mean when Makara ignored the pleas of smaller animals?', '''To turn a deaf ear'' is an idiom meaning to deliberately disregard advice or compassionate appeals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8efed633-d323-43e1-bb68-d5e0a02ae51f', 'To deliberately refuse to listen or pay attention to someone', true, 'b60ad923-a987-49a7-b042-3d6587de13d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7a0c774-763f-4ca9-b5f0-674efcdbf0b7', 'To become physically deaf from loud noise', false, 'b60ad923-a987-49a7-b042-3d6587de13d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bccea8d9-db77-4955-aa34-d547963c7755', 'To clean one''s ear', false, 'b60ad923-a987-49a7-b042-3d6587de13d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f3c9743-0625-4b77-850a-2c18babeb544', 'To whisper a secret', false, 'b60ad923-a987-49a7-b042-3d6587de13d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bec52e61-2e28-4f26-baa7-04ccc4b0b0df', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Why do female mongooses in a clan give birth to litters at the same time in communal dens?', 'Synchronous breeding enables communal alloparental care, elevating pup survival against predators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7718b20-32b7-424c-873f-8796658d37ea', 'So that nursing mothers can share parental duties and adult group members take turns babysitting while others forage for food', true, 'bec52e61-2e28-4f26-baa7-04ccc4b0b0df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ffd25dc-9776-43c0-9cfe-ccb0e53687ad', 'Because they have no houses', false, 'bec52e61-2e28-4f26-baa7-04ccc4b0b0df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c119cedf-e263-4a62-b4fc-837c5dfef37c', 'To fight other animals', false, 'bec52e61-2e28-4f26-baa7-04ccc4b0b0df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ba34bc5-bbd4-492a-a99d-f76c39863126', 'By pure accidental coincidence', false, 'bec52e61-2e28-4f26-baa7-04ccc4b0b0df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff04feb9-1616-4293-bfc7-a8073f989dd3', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'In ''What Happened to the Reptiles'', what happened to the forest''s atmosphere after the expelled animals returned?', 'Trophic balance was immediately restored as returning predators and scavengers re-established ecological equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c1ea158-3655-453d-bc92-9b468dd0081f', 'The rats were eaten, insects were controlled, rotting foul smell vanished, and the pristine green forest returned to healthy peace and normal balance', true, 'ff04feb9-1616-4293-bfc7-a8073f989dd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7bf95ee-aa0b-40ff-b0ad-4f2403556fc9', 'The forest caught fire', false, 'ff04feb9-1616-4293-bfc7-a8073f989dd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40e91125-fc19-43b7-8203-b6ce2af29253', 'The animals fought a war', false, 'ff04feb9-1616-4293-bfc7-a8073f989dd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3686cda0-ea73-4cee-8200-5688eebcd1c2', 'The river dried up', false, 'ff04feb9-1616-4293-bfc7-a8073f989dd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13ea2f17-f066-43fc-bfae-ded330bb4fc3', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Who is the prominent naturalist and wildlife author who wrote ''What Happened to the Reptiles''?', 'Zai Whitaker, co-founder of the Madras Crocodile Bank Trust, authored this environmental allegory.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39e83b42-478e-44df-993e-b8da17d4bdfd', 'Zai Whitaker', true, '13ea2f17-f066-43fc-bfae-ded330bb4fc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc29d2ba-20c4-4ea9-818e-b592232a67ed', 'Ruskin Bond', false, '13ea2f17-f066-43fc-bfae-ded330bb4fc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5137f77a-2f46-4c39-9139-3ebf40e9bfa6', 'Jim Corbett', false, '13ea2f17-f066-43fc-bfae-ded330bb4fc3');
