INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7117780f-2950-4a6a-aff9-2894035c559c', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '57db7323-3ac5-46fc-9325-3ecf42098a0e');
