INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8ca3d1e-12a3-46a7-98f6-78e9bad72975', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'What literary device is utilized in ''What Happened to the Reptiles'' to address human social conflicts through animal characters?', 'An Allegory uses a narrative surface level (reptiles in a forest) to symbolize deeper political realities (communal tolerance).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ad87b6f-8a4c-4880-bdaf-88a1d84a9d7c', 'Allegory / Fable (using animal personification to deliver deep moral, social, and political truths)', true, 'c8ca3d1e-12a3-46a7-98f6-78e9bad72975');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3ed1b8d-6df1-49bb-8737-f84364a25c96', 'Satirical farce', false, 'c8ca3d1e-12a3-46a7-98f6-78e9bad72975');
