INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6dca2f26-626b-4147-b414-2d40e122614c', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'What ultimate philosophical conviction inspires Prem to return to his wounded city at the conclusion of the story?', 'Prem embraces the duty of storytelling to heal fractured societies through the gospel of pluralistic harmony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a517ad74-49c2-44c7-9828-8e9492979299', 'That even if cynical people laugh or resist at first, repeating the story of Pambupatti will eventually open human minds to the sacred truth of mutual harmony and interdependence', true, '6dca2f26-626b-4147-b414-2d40e122614c');
