INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d2685be-3cc4-4164-8a14-7b22d31a4896', 'Class 6', 'GK', 'Chapter 9: Sports, Famous Champions & Traditional Games of India', 'Hard', 'What is the iconic ancient board game originating in ancient India as ''Moksha Patam'' (created by Saint Gyandev) to teach moral philosophy, known globally today as:', 'Moksha Patam depicted ladders as virtues (humility, faith) leading to salvation, and snakes as vices (anger, greed) dragging the soul down.', NOW()) ON CONFLICT DO NOTHING;
