INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea18854d-2d27-4465-97b9-00b8d8287690', 'Class 6', 'GK', 'Chapter 9: Sports, Famous Champions & Traditional Games of India', 'Hard', 'Who was the legendary athlete who won the Olympic Silver medal in Men''s 200m and 200m Hurdles at the Paris 1900 Olympics, representing British India as India''s first ever Olympic medalist?', 'Calcutta-born Norman Pritchard won two silver medals in athletics in Paris 1900, recognized by the IOC as India''s first Olympic participant.', NOW()) ON CONFLICT DO NOTHING;
