INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('213255e5-1339-405e-b68c-949cf3d5421e', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Easy', 'In the ancient Tamil region, what were landless agricultural labourers and slaves called?', 'Landless daily laborers were ''Kadaisiyar'' and bonded slaves were ''Adimai''.', NOW()) ON CONFLICT DO NOTHING;
