INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aaed9ed9-da86-4175-8d47-3f4c17a71a7c', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Easy', 'In northern Indian villages, who was the influential Village Headman who owned the largest land and collected taxes for the king?', 'The hereditary ''Gramabhojaka'' was the largest landlord, tax collector, judge, and police authority in northern villages.', NOW()) ON CONFLICT DO NOTHING;
