INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('224201bb-e667-401f-b0f8-788a596af9c5', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Easy', 'In northern Indian villages, what were independent small landowners called?', '''Grihapatis'' were independent small-scale peasant farmers working their own family land.', NOW()) ON CONFLICT DO NOTHING;
