INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a53ac2a1-5af0-4fcc-b34e-378934774b63', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Easy', 'What is the earliest body of Tamil literature composed around 2,300 years ago in assemblies of poets held in the city of Madurai called?', '''Sangam'' literature refers to ancient Tamil poetry anthologies compiled in assemblies (sangams) of bards under Pandyan patronage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94487f1b-70a5-482b-a5ff-736fe6631cd1', 'Sangam Literature', true, 'a53ac2a1-5af0-4fcc-b34e-378934774b63');
