INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('009120a1-733c-4901-ab7e-a124785d2217', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Easy', 'What are the earliest coins used in India for about 500 years (from c. 600 BCE), made of silver or copper punched with distinct symbols called?', 'Punch-marked coins were stamped with metallurgical dies featuring symbols (hills, trees, animals) on silver and copper flans.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be79b16d-7054-462b-a2c2-399b8278afe9', 'Punch-Marked Coins (Aahat Mudra)', true, '009120a1-733c-4901-ab7e-a124785d2217');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbf8e7b6-ccc8-4f0f-800b-dde272374537', 'Gold Dinars', false, '009120a1-733c-4901-ab7e-a124785d2217');
