INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0273226-1104-4a80-a750-ec770bb7cebc', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Easy', 'Which ancient coastal port settlement in Puducherry (excavated by Sir Mortimer Wheeler) was a thriving international trade hub with the Roman Empire between 2200 and 1900 years ago?', 'Arikamedu excavations yielded Roman amphorae wine jars, Arretine red-glazed pottery, and Roman gold coins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('981d57ab-dd66-47ff-871a-ade32a1f24b4', 'Arikamedu (Podouke of the Periplus)', true, 'a0273226-1104-4a80-a750-ec770bb7cebc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ef30c98-c23f-4d52-b95f-9c990bf0563f', 'Kaveripattinam', false, 'a0273226-1104-4a80-a750-ec770bb7cebc');
