INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5867e5f-f27c-4bf8-ba0f-48ef5fe81b89', 'Surat', false, 'a0273226-1104-4a80-a750-ec770bb7cebc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f746c43b-e482-4726-857d-6e138ec89ea7', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What were ''Shrenis'' in ancient Indian urban centers?', 'Shrenis operated as merchant/artisan guilds, providing credit finance, technical quality control, and banking services.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9294392d-0244-472a-af1e-a802fc0aaf76', 'Associations and guilds formed by craftspersons and merchants to procure raw materials, train artisans, distribute goods, and function as banks', true, 'f746c43b-e482-4726-857d-6e138ec89ea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ed9fc52-4a17-4f7d-9d02-8f8a1533fab2', 'Royal palaces of kings', false, 'f746c43b-e482-4726-857d-6e138ec89ea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42d22473-c29e-42ce-bfe0-f208e10a7233', 'Military battalions', false, 'f746c43b-e482-4726-857d-6e138ec89ea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5636ed1c-d7de-4537-b982-729b2c9281ea', 'Taxes paid by farmers', false, 'f746c43b-e482-4726-857d-6e138ec89ea7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8fbc22ca-32b8-4f32-bf04-37512965324c', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'Why was Mathura a major, thriving multi-functional urban city for over 2,500 years?', 'Mathura''s strategic commercial crossroads location and vibrant religious syncretism made it the second capital of the Kushanas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8014793c-047d-46e0-9542-eaf5c48ab949', 'It was located at the vital crossroads of two major ancient trade routes (North-west to East, and North to South), a center of fine sculpture, and a religious hub for Krishna worship, Buddhism, and Jainism', true, '8fbc22ca-32b8-4f32-bf04-37512965324c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2eb04fc8-6277-4865-8775-dfc1a5b6ee2b', 'Because it had gold mines', false, '8fbc22ca-32b8-4f32-bf04-37512965324c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a3960e6-55ad-406f-b3b8-12a2fd1a2faa', 'Because it was on the sea coast', false, '8fbc22ca-32b8-4f32-bf04-37512965324c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d882de1f-fd74-4210-a74f-90799948db74', 'Because it had no agriculture', false, '8fbc22ca-32b8-4f32-bf04-37512965324c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50ed622a-1f3d-441f-accf-37482dd5ba35', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What was ''Northern Black Polished Ware'' (NBPW) produced in ancient urban centers of the Gangetic valley?', 'NBPW was premium deluxe tableware fired at high kilns, producing an iridescent black gloss.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22c97039-4fd9-450b-acde-6c45a3b9232f', 'A very fine, ultra-smooth, glossy black earthenware pottery with a mirror-like metallic shine used as luxury tableware', true, '50ed622a-1f3d-441f-accf-37482dd5ba35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c1e5000-daab-4d10-8311-0f3a8fd11cb2', 'A heavy iron shield', false, '50ed622a-1f3d-441f-accf-37482dd5ba35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4ce9cfd-8a92-4e7c-b455-75e1a8404c1d', 'A type of black stone', false, '50ed622a-1f3d-441f-accf-37482dd5ba35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6b08431-68e4-40c5-9a44-7144244aa772', 'A wooden plate', false, '50ed622a-1f3d-441f-accf-37482dd5ba35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af3785e3-3755-4b48-81a9-a0b7537d9a48', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What were ''Ring Wells'' discovered in archaeological excavations of ancient cities like Delhi and Hastinapur used for?', 'Stacked ceramic terracotta ring wells served as soakage pits, sullage drains, and latrines in dense urban quarters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e330475-8d7d-4192-99fc-efaed985dc8e', 'As domestic toilets, drain pipes, or garbage waste pits by stacking terracotta rings vertically in the ground', true, 'af3785e3-3755-4b48-81a9-a0b7537d9a48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f936a32-0a0e-4bf5-bef0-f975c4dd3634', 'As gold treasure vaults', false, 'af3785e3-3755-4b48-81a9-a0b7537d9a48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c13ecbc5-657a-45f3-b1f5-002b913455f0', 'As musical instruments', false, 'af3785e3-3755-4b48-81a9-a0b7537d9a48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ad593f2-d775-4250-a236-d23704f59599', 'As animal traps', false, 'af3785e3-3755-4b48-81a9-a0b7537d9a48');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36920018-35b9-4a2b-a3c8-6e791f743b0b', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What ancient Greco-Roman travel guidebook written by an anonymous Greek sailor in the 1st century CE describes Indian coastal ports and maritime trade items?', 'The ''Periplus of the Erythraean Sea'' details trade goods traded at Bharuch (Barygaza), Muziris, and Arikamedu.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a32d6851-1b84-4809-b4a3-a2864d994abc', 'The Periplus of the Erythraean Sea (''Periplus of the Red/Arabian Sea'')', true, '36920018-35b9-4a2b-a3c8-6e791f743b0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e94df9e-c3d4-4c3b-8a67-1a70428e20f2', 'Indica by Megasthenes', false, '36920018-35b9-4a2b-a3c8-6e791f743b0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ba5829a-9f80-43e2-aae3-5dcf8ff248ea', 'Geographia by Ptolemy', false, '36920018-35b9-4a2b-a3c8-6e791f743b0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('356ef71d-92b0-445a-90b0-8405c393c72f', 'Naturalis Historia', false, '36920018-35b9-4a2b-a3c8-6e791f743b0b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('555a234d-3306-4f99-a9fe-43012b042efd', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What goods were EXPORTED from Indian ports like Barygaza (Bharuch in Gujarat) to the Roman Empire?', 'Indian exports comprised fine muslins, black pepper (''black gold''), ivory, precious gemstones, and aromatics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea4addf8-6a01-4727-90d4-250cc8f72d8a', 'Fine cotton textiles, silk, black pepper and spices, ivory, agate, jasper, and medicinal herbs', true, '555a234d-3306-4f99-a9fe-43012b042efd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55524ebf-13ee-4874-b838-780bf0595fdf', 'Wine and Italian pottery', false, '555a234d-3306-4f99-a9fe-43012b042efd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdab6157-e13a-42af-9188-93cd621563e2', 'Roman gold and silver coins', false, '555a234d-3306-4f99-a9fe-43012b042efd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48b89899-faf0-47da-a7e1-a0e8403c5e63', 'Tin, lead, and glass', false, '555a234d-3306-4f99-a9fe-43012b042efd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4287aead-07c2-431d-8c30-73d266ffde43', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What goods were IMPORTED into India from the Mediterranean Roman world?', 'Rome exported wine, metals (tin/lead), coral, and huge hoards of imperial gold/silver denarii to balance trade.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('219c9dd7-e301-4997-9d50-fbc3afc04de1', 'Italian wine in amphorae jars, Roman gold and silver coins, copper, tin, lead, coral, and topaz', true, '4287aead-07c2-431d-8c30-73d266ffde43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d620f984-c3a5-4c17-bc7e-304e3954f05e', 'Black pepper and cardamoms', false, '4287aead-07c2-431d-8c30-73d266ffde43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85e3395e-4962-4be7-95ed-6c8c9f91d7ad', 'Fine cotton cloth', false, '4287aead-07c2-431d-8c30-73d266ffde43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('147b04e6-5c5e-4313-bb74-b13046e545f4', 'Ivory and peacocks', false, '4287aead-07c2-431d-8c30-73d266ffde43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91b1b49f-ae53-4c5c-a2c9-8d5091609171', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What were ''Arretine Ware'' vessels discovered at Arikamedu?', 'Arretine ware was Italian fine slip-coated red terra sigillata exported across Mediterranean maritime trade networks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('214d385f-81d6-4b6c-9e99-c192376c1e3e', 'Fine red-glazed Roman pottery named after the Italian city of Arezzo, stamped with decorative designs using wet clay molds', true, '91b1b49f-ae53-4c5c-a2c9-8d5091609171');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4beaf51-b483-458a-a1e7-67e46673ea51', 'Chinese porcelain vases', false, '91b1b49f-ae53-4c5c-a2c9-8d5091609171');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bbbf145-7ea7-4092-a8fd-7cf44cce80e7', 'Ancient bronze statues', false, '91b1b49f-ae53-4c5c-a2c9-8d5091609171');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42cef961-e393-4309-a14a-3a8015416c4f', 'Iron cooking pots', false, '91b1b49f-ae53-4c5c-a2c9-8d5091609171');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6371c4a4-2636-404f-997d-3fc7c445c0a8', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'Why did Pliny the Elder, a Roman historian, lament that ''not a year passes without India taking fifty million sesterces of Roman gold''?', 'Pliny''s ''Naturalis Historia'' lamented the massive trade deficit and gold drain caused by aristocratic Roman addiction to Indian luxury spices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f5cbadc-3a61-41cf-bf42-cc686f3cf38b', 'Because Roman wealth was draining into India to purchase Indian luxury spices (black pepper), silk, and gemstones', true, '6371c4a4-2636-404f-997d-3fc7c445c0a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61381bc1-4c7e-4910-9f86-064c2ea614d3', 'Because India was buying all Roman wheat', false, '6371c4a4-2636-404f-997d-3fc7c445c0a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c33bc46b-36d4-435e-b7b9-b97fb4af1184', 'Because Roman armies lost wars to India', false, '6371c4a4-2636-404f-997d-3fc7c445c0a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70fac31c-0cc1-4734-b92c-b09cd7f25082', 'Because Roman emperors gave gifts to India', false, '6371c4a4-2636-404f-997d-3fc7c445c0a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adad2de5-425e-426f-97fe-015747e7ea8c', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What were the famous ancient centers of cotton textile weaving in northern and southern India mentioned in Kautilya''s Arthashastra?', 'Arthashastra identifies Varanasi and Madurai as renowned manufacturing guild centers of fine cotton textiles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce0a80b9-8810-4d74-ba47-dbcb106469fe', 'Varanasi (in the north) and Madurai (in the south)', true, 'adad2de5-425e-426f-97fe-015747e7ea8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a3afdb1-77c4-45f1-b102-31fccbb07902', 'Delhi and Mumbai', false, 'adad2de5-425e-426f-97fe-015747e7ea8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3833377-32dc-441e-ac7e-e43b1521bd8b', 'Taxila and Ujjain', false, 'adad2de5-425e-426f-97fe-015747e7ea8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d81b5426-45a7-4bda-bd2a-072ad6fda224', 'Patliputra and Kanchi', false, 'adad2de5-425e-426f-97fe-015747e7ea8c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3de7994d-3444-46d5-aeb5-fa1d9e536afb', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'Why was the post of ''Gramabhojaka'' hereditary in northern villages?', 'Hereditary succession maintained aristocratic lineage control over village revenues and rural administration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cc370ee-4b54-4064-bd6b-e19c263d358d', 'The position passed from father to son across generations within the village''s wealthiest landowning family', true, '3de7994d-3444-46d5-aeb5-fa1d9e536afb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('434e034f-fbcb-4900-b10d-9a5d46973c2b', 'Because kings held elections every year', false, '3de7994d-3444-46d5-aeb5-fa1d9e536afb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c48f0f6a-7f51-4e07-8d76-b2bb9192ed29', 'Because villagers voted with stones', false, '3de7994d-3444-46d5-aeb5-fa1d9e536afb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba11bc52-e3f3-4a8b-bbd9-52120f940d1f', 'Because only priests could hold the post', false, '3de7994d-3444-46d5-aeb5-fa1d9e536afb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10497cae-c0f8-4548-8139-fd44a0916902', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What are ''Jatakas'' in ancient Indian literature?', 'Jatakas are moral Buddhist folk narratives (e.g. story of the clever poor young man) preserved in Pali canon.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbd0131-8d96-45cc-be79-2d90561912ad', 'Popular folk stories depicting previous lives of the Buddha, composed by ordinary people and written down by Buddhist monks', true, '10497cae-c0f8-4548-8139-fd44a0916902');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14692d5b-90ff-4b45-8f9c-b124c9366451', 'Royal inscriptions carved on rocks', false, '10497cae-c0f8-4548-8139-fd44a0916902');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45f81060-9fd7-4340-96a4-dffe2bdc3835', 'Mathematical textbooks', false, '10497cae-c0f8-4548-8139-fd44a0916902');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fc5cb06-d0e4-41ea-802b-804ff88de031', 'Military strategies of kings', false, '10497cae-c0f8-4548-8139-fd44a0916902');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03d8f502-737b-4c19-a208-e4906f6f0d44', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What crucial archaeological evidence proves the existence of flourishing international trade at ancient port sites?', 'Numismatic hoards, imported pottery (terra sigillata), and wharves confirm historical maritime trade connectivity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('661879a5-34d2-4d94-a7b3-ab2a1f31741d', 'Foreign coins, imported amphorae wine jars, foreign stamped pottery, and specialized port warehouse brick structures', true, '03d8f502-737b-4c19-a208-e4906f6f0d44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24f0e8bb-03ca-4782-96bb-4a3ee6285a28', 'Modern asphalt roads', false, '03d8f502-737b-4c19-a208-e4906f6f0d44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a678f2db-c6fb-41d7-b771-137e8b958519', 'Plastic toys', false, '03d8f502-737b-4c19-a208-e4906f6f0d44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1412999a-aec0-49ea-a2e8-7412618f7521', 'Steel cargo ships', false, '03d8f502-737b-4c19-a208-e4906f6f0d44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f248649-4721-49b5-84bf-d40f08af1a53', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'How did the invention and expansion of Iron tools transform civilization between 1000 BCE and 500 BCE?', 'Iron metallurgy enabled forest clearance and agricultural surplus in the Gangetic basin, catalyzing the Second Urbanization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34c39a23-7970-44c9-927c-3b6ffc7cee05', 'Heavy iron axes cleared dense subtropical Gangetic monsoon forests for settled farming, and iron ploughs dramatically increased food surpluses, sustaining urbanization', true, '7f248649-4721-49b5-84bf-d40f08af1a53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c264fe4c-8cdc-44f3-90d4-653dc4c3f7f4', 'It destroyed all cities', false, '7f248649-4721-49b5-84bf-d40f08af1a53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94b63eee-62d0-49f6-bf99-37c1273c690b', 'It stopped all agriculture', false, '7f248649-4721-49b5-84bf-d40f08af1a53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d17ff6b8-7bef-437f-9339-dcaf55949943', 'It made people leave India', false, '7f248649-4721-49b5-84bf-d40f08af1a53');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('249bcece-4b9a-4741-adbe-e2678738b0cd', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What religious donations were inscribed on stone pillars and railings of Buddhist stupas (such as Sanchi and Mathura)?', 'Votive epigraphs record pious donations by diverse socio-economic strata (guilds, artisans, lay devotees) to monastic orders.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4753e9df-3d58-43f7-aecc-23aab685572a', 'Votive Inscriptions recording gifts given by kings, queens, guild merchants, weavers, goldsmiths, and monks/nuns', true, '249bcece-4b9a-4741-adbe-e2678738b0cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddaf2d31-fb3f-486a-a0ef-81b3a7c09076', 'Tax receipts from farmers', false, '249bcece-4b9a-4741-adbe-e2678738b0cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91b2a46b-68d8-42cb-8fdf-b0962be91a95', 'Cooking recipes', false, '249bcece-4b9a-4741-adbe-e2678738b0cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06c4ce87-2376-42e0-8d93-3f0c2f0725f1', 'War declarations', false, '249bcece-4b9a-4741-adbe-e2678738b0cd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a30ccd66-2703-4814-8c8c-79a133f5d61b', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'Why was the ancient port of Barygaza (modern Bharuch) in the Gulf of Khambhat difficult for foreign ships to navigate?', 'The ''Periplus'' records that violent tidal bores in the narrow Gulf of Khambhat required specialized pilots.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8332e19c-5145-48ea-83d2-b055553e19ae', 'The gulf was narrow, shallow, and plagued by fierce tidal bore currents, requiring skillful local fishermen employed by the king to steer ships into port', true, 'a30ccd66-2703-4814-8c8c-79a133f5d61b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('137d31f8-37bc-49cc-a33d-7c12828deb28', 'Because of icebergs', false, 'a30ccd66-2703-4814-8c8c-79a133f5d61b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7226fe50-7e58-4608-aecd-516afe2a584c', 'Because of pirates with cannons', false, 'a30ccd66-2703-4814-8c8c-79a133f5d61b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('716f8b1e-3855-4693-b47e-1a23195b6a6d', 'Because there was no water', false, 'a30ccd66-2703-4814-8c8c-79a133f5d61b');
