INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5df01059-8e54-4993-80d4-b90ae9c85e7c', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'An archaeologist excavates an ancient trade site and discovers: (1) Amphorae containing dried wine residue, (2) Red-glazed stamped pottery, (3) Roman gold coins of Emperor Augustus. What historical site is represented?', 'Mortimer Wheeler''s excavations at Arikamedu proved it was an Indo-Roman maritime emporium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bb6ea15-7122-4c75-bf57-dedade3c0118', 'Arikamedu (near Puducherry on the southeastern Coromandel coast)', true, '5df01059-8e54-4993-80d4-b90ae9c85e7c');
