INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66d325ca-5398-4302-ad74-fd24470438e6', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'Match Column I (Ancient Terms) with Column II (Definitions & Roles):
(a) Shrenis        -> (i) Earliest stamped silver/copper coins
(b) Gramabhojaka   -> (ii) Guilds of craftspersons & merchants
(c) Punch-marked   -> (iii) Hereditary village headman & tax collector (North)
(d) Sangam         -> (iv) Assemblies of ancient Tamil poets in Madurai', 'Shrenis = guilds; Gramabhojaka = northern village headman; Punch-marked = coins; Sangam = poet assemblies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bd464e7-e309-45b1-a1d9-f8d18e067175', 'a-(ii), b-(iii), c-(i), d-(iv)', true, '66d325ca-5398-4302-ad74-fd24470438e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b87b7c3a-52c5-4efd-bb69-2296bcea636e', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '66d325ca-5398-4302-ad74-fd24470438e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05c3f64d-b03a-47ea-b467-b9dce41b4ee9', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '66d325ca-5398-4302-ad74-fd24470438e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('302b8693-e9f9-4009-8e64-f37e1556b071', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '66d325ca-5398-4302-ad74-fd24470438e6');
