INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ed59057-eae7-4771-8470-62e338e2a391', 'Statements 1 and 2 only', true, 'fb21f144-5d76-47e0-9fa5-26d3e525ba38');
