INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('660c7b30-1e37-4084-8b53-e1be30f0231a', 'All Statements 1, 2, and 3', false, 'fb21f144-5d76-47e0-9fa5-26d3e525ba38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a94e251e-c7e8-4677-9fe0-16936c217332', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'What was the significance of Mathura becoming the second capital of the Kushana Empire (under Emperor Kanishka)?', 'Mathura flourished as the southern capital of the Kushanas, creating the Mathura school of art in mottled red Sikri sandstone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b37aaf0-10cf-4a8b-a003-1bf9c47958da', 'It became a premier center of red sandstone sculpture (producing magnificent Buddha images) and a crossroads linking Gandhara with Gangetic trade', true, 'a94e251e-c7e8-4677-9fe0-16936c217332');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a07253ac-bc90-4e80-be3e-690feb2d7d66', 'It was made of ice', false, 'a94e251e-c7e8-4677-9fe0-16936c217332');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33a2fa21-e75b-4cf6-81c8-4f53a07a9237', 'It was abandoned forever', false, 'a94e251e-c7e8-4677-9fe0-16936c217332');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9852ebd-dbd4-4bf4-95ae-169095dfa543', 'It was only used as a prison', false, 'a94e251e-c7e8-4677-9fe0-16936c217332');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b34f1bef-d49e-4885-85d6-269cca88dee5', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'Why was the process of ''Paddy (Rice) Transplantation'' around 2,500 years ago a major technological turning point in Gangetic agriculture?', 'Transplantation minimized seedling mortality, drastically raising grain productivity per hectare.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ce891d0-aa85-470b-adf8-afff36ff13dc', 'Instead of scattering dry seeds on soil where many died, saplings were grown in nurseries and transplanted into water-logged flooded fields, ensuring far higher plant survival and bumper yields', true, 'b34f1bef-d49e-4885-85d6-269cca88dee5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4d1cb7b-0362-411e-b8a9-68fec7f5c7cb', 'Because it stopped weeds by burning', false, 'b34f1bef-d49e-4885-85d6-269cca88dee5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15cf7eb9-5cbf-4d47-9f51-33cbb9ff6e6f', 'Because rice could grow without water', false, 'b34f1bef-d49e-4885-85d6-269cca88dee5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41623c73-c16f-46db-8d73-6d7b5e1cc1fd', 'Because animals did all the work', false, 'b34f1bef-d49e-4885-85d6-269cca88dee5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fe5ae03-1b64-4047-b563-1850df74c8b5', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'Consider four occupational groups in an ancient village:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b4fe3ec-a4a9-435a-a16d-f4e95937e120', '1 -> 2 -> 4 -> 3', true, '7fe5ae03-1b64-4047-b563-1850df74c8b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('979f26c4-9019-4758-8d12-c89f37534d19', '3 -> 4 -> 2 -> 1', false, '7fe5ae03-1b64-4047-b563-1850df74c8b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb133352-1ea9-4800-bd11-ed22e39e5bb9', '2 -> 1 -> 3 -> 4', false, '7fe5ae03-1b64-4047-b563-1850df74c8b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29256de5-f587-4876-9b36-fdd191990c51', '4 -> 3 -> 2 -> 1', false, '7fe5ae03-1b64-4047-b563-1850df74c8b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92c60690-0451-40eb-848a-72c68c4b3f4d', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'What archaeological feature distinguishes Northern Black Polished Ware (NBPW) from earlier Painted Grey Ware (PGW)?', 'NBPW''s distinctive black mirror gloss derived from iron-rich ferruginous slips subjected to reduction firing in sealed kilns.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d993174f-dcb8-4459-8221-83801bfe55fe', 'NBPW is characterized by its lustrous, mirror-like jet-black surface sheen achieved by two-stage reducing atmosphere kiln firing and organic slip application', true, '92c60690-0451-40eb-848a-72c68c4b3f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c38cec3-8630-4014-8bd0-da0cef95b793', 'NBPW is made of metal', false, '92c60690-0451-40eb-848a-72c68c4b3f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79570433-2fe0-489a-94f0-18dde3a94501', 'NBPW has red flowers painted on it', false, '92c60690-0451-40eb-848a-72c68c4b3f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee34ec70-150b-4285-95fc-d665ebade6f8', 'NBPW is unbaked mud', false, '92c60690-0451-40eb-848a-72c68c4b3f4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e59763d-eed2-4847-8df8-f4f16a77caf7', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'What do the numerous Megalithic burial stone circles in South India (dating from c. 1000 BCE) contain inside them that proves early iron metallurgy?', 'Megalithic cists and urns contain funerary grave goods: iron swords, daggers, agricultural sickles, and horse bits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0516b5f-1a01-4144-baa5-2973772bfd51', 'Large assortments of iron weapons, iron hoes, sickles, horse equipment, and black-and-red pottery buried alongside human skeletons', true, '0e59763d-eed2-4847-8df8-f4f16a77caf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('659cab71-9c04-4902-a1c2-ad8ed1ff7fcc', 'Paper books and modern pens', false, '0e59763d-eed2-4847-8df8-f4f16a77caf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9e15970-801e-4dcb-83b1-fa5035c42350', 'Steam engines', false, '0e59763d-eed2-4847-8df8-f4f16a77caf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1cdd368-6cdb-4ad0-9e73-fb416e6a3daa', 'Plastic utensils', false, '0e59763d-eed2-4847-8df8-f4f16a77caf7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b7893bf-0be7-46c6-988c-4a037abcce80', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'How did ancient kings in India ensure the loyalty of the Gramabhojaka in administering rural territories?', 'Monarchs co-opted dominant local landed elites, delegating fiscal and judicial power in exchange for tax remittance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('105625b5-0b15-4eec-bdef-f2f9eab57815', 'By recognizing his hereditary local land power and delegating official state functions (tax collection, judicial dispute settlement, and local policing) to him', true, '6b7893bf-0be7-46c6-988c-4a037abcce80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d68b5088-ef39-4358-8479-f7ae44e08435', 'By imprisoning his family', false, '6b7893bf-0be7-46c6-988c-4a037abcce80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa3bb4bd-5df0-4080-8ad0-cb5135d2a7c1', 'By destroying his crops', false, '6b7893bf-0be7-46c6-988c-4a037abcce80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e44eb1d-787d-47f0-a892-5aa0b3d6baf3', 'By replacing him every month', false, '6b7893bf-0be7-46c6-988c-4a037abcce80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2eb932be-888c-4a19-851a-a29f161c2ae4', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'What holistic picture of ancient society emerges from reading NCERT Class 6 History on villages and towns?', 'History portrays an integrated ecosystem connecting agrarian villages, craft guilds, and international maritime trade emporia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b615037-0be4-4da3-9020-13db077a3c75', 'An interdependent socio-economic web where thriving agricultural villages, specialized urban craft guilds, and global maritime ports sustained flourishing civilization through trade and cultural exchange', true, '2eb932be-888c-4a19-851a-a29f161c2ae4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('313b05d6-cb43-4ed7-a55c-65fa965dafa8', 'A society where towns had no connection to villages', false, '2eb932be-888c-4a19-851a-a29f161c2ae4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed458c26-b42d-4f0c-a13a-4807f65f9323', 'A civilization that had no tools or trade', false, '2eb932be-888c-4a19-851a-a29f161c2ae4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ed14628-6be6-4868-9070-0a5f0c46fd8b', 'A world without any laws or coins', false, '2eb932be-888c-4a19-851a-a29f161c2ae4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('632d84c3-6b00-4f1b-99cf-bba37bd1822b', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'संज्ञा अथवा सर्वनाम शब्दों की विशेषता (गुण, दोष, रूप, रंग, आकार, संख्या, परिमाण) बताने वाले शब्दों को क्या कहते हैं?', 'संज्ञा या सर्वनाम की विशेषता प्रकट करने वाले विकारी शब्द ''विशेषण'' कहलाते हैं (जैसे: ''सुंदर'', ''लाल'', ''पाँच'', ''मीठा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27e95946-5302-4616-ae21-1eda9d47eb22', 'विशेषण (Adjective)', true, '632d84c3-6b00-4f1b-99cf-bba37bd1822b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b70578d-6ff1-432a-b7c3-11c6bc7a4c3e', 'क्रिया', false, '632d84c3-6b00-4f1b-99cf-bba37bd1822b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6bec91c-4958-40e2-9434-22678d6845f7', 'अव्यय', false, '632d84c3-6b00-4f1b-99cf-bba37bd1822b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a596618-ad56-4bd0-a58a-72c3c755a862', 'कारक', false, '632d84c3-6b00-4f1b-99cf-bba37bd1822b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('985b5c33-303e-4fce-a412-65321c3beb11', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'विशेषण शब्द जिस संज्ञा या सर्वनाम शब्द की विशेषता बताता है, उसे व्याकरण में क्या कहते हैं?', 'जिसकी विशेषता बताई जाए वह ''विशेष्य'' कहलाता है (जैसे: ''मीठा सेब'' में ''मीठा'' = विशेषण, ''सेब'' = विशेष्य)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10728803-2583-4c48-97cf-c4a8984bd646', 'विशेष्य (जैसे: ''काली गाय'' में ''गाय'' विशेष्य है)', true, '985b5c33-303e-4fce-a412-65321c3beb11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00861920-1470-4344-80a9-4dfed7460c99', 'प्रविशेषण', false, '985b5c33-303e-4fce-a412-65321c3beb11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50c53785-11c6-4254-a658-951e6b667ee0', 'क्रिया', false, '985b5c33-303e-4fce-a412-65321c3beb11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27091fa2-040a-4f18-93da-1c7595a95d9b', 'कर्म', false, '985b5c33-303e-4fce-a412-65321c3beb11');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6bd1b31-9d5a-4caf-8406-8f19f21d8727', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'हिंदी भाषा में विशेषण के मुख्य रूप से कितने भेद (प्रकार) होते हैं?', 'विशेषण के 4 मुख्य भेद हैं: 1. गुणवाचक, 2. संख्यावाचक, 3. परिमाणवाचक, तथा 4. सार्वनामिक विशेषण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30187340-4438-43de-95d6-197d2ae63d8c', 'चार भेद (गुणवाचक, संख्यावाचक, परिमाणवाचक, और सार्वनामिक विशेषण)', true, 'c6bd1b31-9d5a-4caf-8406-8f19f21d8727');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29b782cc-ed39-4df4-84fd-9fa3639d06b2', 'तीन भेद', false, 'c6bd1b31-9d5a-4caf-8406-8f19f21d8727');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b15bdce-7189-43a1-bc9c-a0e9d82f705c', 'पाँच भेद', false, 'c6bd1b31-9d5a-4caf-8406-8f19f21d8727');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebc44216-b9b9-4e05-9739-9ed6d0d0c5a2', 'छह भेद', false, 'c6bd1b31-9d5a-4caf-8406-8f19f21d8727');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4451c8ef-9bfe-491c-8706-c1ae79a8a3dd', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'जो विशेषण शब्द संज्ञा या सर्वनाम के गुण, दोष, रंग, रूप, आकार, दशा, स्वाद या स्पर्श का बोध कराते हैं, उन्हें क्या कहते हैं?', 'गुण, दोष, रंग, आकार, अवस्था का बोध कराने वाले शब्द ''गुणवाचक विशेषण'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cdcc807-6cc1-434b-b09a-674a7e68947a', 'गुणवाचक विशेषण (जैसे: ''ईमानदार लड़का'', ''काला घोड़ा'', ''गोल मेज'', ''मीठा आम'')', true, '4451c8ef-9bfe-491c-8706-c1ae79a8a3dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('badf3394-e03a-4698-86fe-c902e7dca781', 'संख्यावाचक विशेषण', false, '4451c8ef-9bfe-491c-8706-c1ae79a8a3dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88aa263c-0a19-4fb1-aba0-917c42263bf5', 'परिमाणवाचक विशेषण', false, '4451c8ef-9bfe-491c-8706-c1ae79a8a3dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81859e0b-474a-4f38-8c37-95d59f6cb335', 'सार्वनामिक विशेषण', false, '4451c8ef-9bfe-491c-8706-c1ae79a8a3dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e020a24b-dd6b-462c-9abb-52b65f3efb37', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'जो विशेषण शब्द संज्ञा या सर्वनाम की संख्या (गिनती) का बोध कराते हैं, उन्हें क्या कहते हैं?', 'गणनीय वस्तुओं की संख्या दर्शाने वाले शब्द ''संख्यावाचक विशेषण'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e69611ce-e879-4946-8e30-23ec49f43885', 'संख्यावाचक विशेषण (जैसे: ''चार पुस्तकें'', ''कुछ बच्चे'', ''पहला स्थान'')', true, 'e020a24b-dd6b-462c-9abb-52b65f3efb37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18eb0175-2340-4183-871b-57ca5fde69b6', 'गुणवाचक विशेषण', false, 'e020a24b-dd6b-462c-9abb-52b65f3efb37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6a636bc-a025-4861-8395-201839968282', 'परिमाणवाचक विशेषण', false, 'e020a24b-dd6b-462c-9abb-52b65f3efb37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1aa3b01-3d48-4f2e-ba9b-25be9cd1d808', 'सार्वनामिक विशेषण', false, 'e020a24b-dd6b-462c-9abb-52b65f3efb37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37c24812-3ab8-4c6c-a797-e29b9bb167a8', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'संख्यावाचक विशेषण के कितने उपभेद होते हैं?', 'निश्चित संख्या (पाँच, दस, पहला) तथा अनिश्चित संख्या (कुछ, कई, अनेक, सब) इसके दो उपभेद हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f1bc314-014b-4b8c-954e-831da534bf08', 'दो उपभेद (1. निश्चित संख्यावाचक जैसे ''दस छात्र'', और 2. अनिश्चित संख्यावाचक जैसे ''कुछ लोग'')', true, '37c24812-3ab8-4c6c-a797-e29b9bb167a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a7ff3d3-5f39-4e7e-a52b-ffe3c98ad1ac', 'तीन उपभेद', false, '37c24812-3ab8-4c6c-a797-e29b9bb167a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7a16440-5f36-49c2-bbc4-81ee5e830eb2', 'चार उपभेद', false, '37c24812-3ab8-4c6c-a797-e29b9bb167a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03eafd54-a7f9-4159-8ee5-e5cb7ffdb95c', 'पाँच उपभेद', false, '37c24812-3ab8-4c6c-a797-e29b9bb167a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96a7ba89-14c2-44a6-a755-10afacadf48c', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'जो विशेषण शब्द किसी वस्तु की नाप, तौल या माप (मात्रा) का बोध कराते हैं (जिन्हें गिना नहीं जा सकता, केवल नापा/तौला जाता है), उन्हें क्या कहते हैं?', 'द्रव्य या अगणनीय वस्तुओं की माप-तौल बताने वाले शब्द ''परिमाणवाचक विशेषण'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa9df54-9789-4f1c-bb15-3fe28c4ad353', 'परिमाणवाचक विशेषण (जैसे: ''दो लीटर दूध'', ''पाँच किलो आटा'', ''थोड़ा पानी'')', true, '96a7ba89-14c2-44a6-a755-10afacadf48c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35c0798c-e4a7-449b-a140-951a2937cdf2', 'संख्यावाचक विशेषण', false, '96a7ba89-14c2-44a6-a755-10afacadf48c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('347b30bd-2185-40b3-ba57-88ff455126ff', 'गुणवाचक विशेषण', false, '96a7ba89-14c2-44a6-a755-10afacadf48c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51e819a5-0d35-42ec-b395-30c459f6c13c', 'सार्वनामिक विशेषण', false, '96a7ba89-14c2-44a6-a755-10afacadf48c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8becdd0c-2c26-41b5-abba-234680bae843', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'परिमाणवाचक विशेषण के दो उपभेद कौन-से हैं?', 'निश्चित माप-तौल = निश्चित परिमाणवाचक; अनुमानित अनिर्दिष्ट माप = अनिश्चित परिमाणवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e31ce82-3e3b-46a4-a873-f9714cd39c7b', 'निश्चित परिमाणवाचक (जैसे: ''3 मीटर कपड़ा'', ''2 किलो चीनी'') और अनिश्चित परिमाणवाचक (जैसे: ''थोड़ा दूध'', ''ज्यादा पानी'')', true, '8becdd0c-2c26-41b5-abba-234680bae843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a40bf9bb-4642-4b8d-94a8-44cd934c6011', 'उत्तम और मध्यम', false, '8becdd0c-2c26-41b5-abba-234680bae843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fb08e23-a229-4e6a-96d6-8ca365a4674e', 'सकर्मक और अकर्मक', false, '8becdd0c-2c26-41b5-abba-234680bae843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cacf526-2169-49a6-b5fa-1f94bfdcf8ff', 'प्रत्यय और उपसर्ग', false, '8becdd0c-2c26-41b5-abba-234680bae843');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4695ccb-a9eb-450e-8d99-d1f08d11d06a', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'जो सर्वनाम शब्द संज्ञा से ठीक पहले आकर उसकी ओर संकेत करते हैं और विशेषण का कार्य करते हैं, उन्हें क्या कहते हैं?', 'संज्ञा से पूर्व प्रयुक्त होकर निर्देश करने वाले सर्वनाम पद ''सार्वनामिक विशेषण'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fcd6ddf-7225-4779-8d8a-cd1b0fb3e193', 'सार्वनामिक विशेषण या संकेतवाचक विशेषण (जैसे: ''यह घर मेरा है'', ''वह पुस्तक अच्छी है'')', true, 'd4695ccb-a9eb-450e-8d99-d1f08d11d06a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cac2421d-6c94-466b-bf08-261a3e361b50', 'निजवाचक सर्वनाम', false, 'd4695ccb-a9eb-450e-8d99-d1f08d11d06a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('917d710b-ec6d-46da-9024-1e32b18eef22', 'गुणवाचक विशेषण', false, 'd4695ccb-a9eb-450e-8d99-d1f08d11d06a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0ee6c8f-a550-4efe-a285-13e93fffcf9e', 'प्रविशेषण', false, 'd4695ccb-a9eb-450e-8d99-d1f08d11d06a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f302332c-681a-4bd0-9ace-303535f10e2a', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'जो शब्द विशेषण की भी विशेषता बताते हैं (जैसे: ''रोहन **बहुत** चतुर लड़का है'', ''सेब **अत्यंत** मीठा है''), उन्हें व्याकरण में क्या कहते हैं?', 'विशेषण शब्दों की तीव्रता या न्यूनता बताने वाले पद ''प्रविशेषण'' कहलाते हैं (जैसे: ''बहुत'' सुंदर)।', NOW()) ON CONFLICT DO NOTHING;
