INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cbc44bdd-7808-40f7-a419-cbb8a6e2ab04', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'संख्यावाचक विशेषण और परिमाणवाचक विशेषण में क्या मुख्य अंतर होता है?', 'गणनीय संज्ञा = संख्यावाचक विशेषण; माप-तौल योग्य अगणनीय द्रव्य = परिमाणवाचक विशेषण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d406b53-c3ab-405a-9530-fcb60ff6bde7', 'संख्यावाचक विशेषण उन वस्तुओं के लिए आता है जिन्हें गिना जा सकता है (Countable - जैसे: ''चार केले'', ''दस पुस्तकें'') ; परिमाणवाचक विशेषण उन वस्तुओं के लिए आता है जिन्हें गिना नहीं जा सकता, केवल नापा/तौला जाता है (Uncountable - जैसे: ''चार लीटर दूध'', ''दस किलो गेहूँ'')', true, 'cbc44bdd-7808-40f7-a419-cbb8a6e2ab04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0db3fc70-82df-42cc-957d-3bb7dcd786c2', 'संख्यावाचक केवल जानवरों के लिए आता है', false, 'cbc44bdd-7808-40f7-a419-cbb8a6e2ab04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f49dbca2-3d00-410b-b3f0-a4402cc65306', 'परिमाणवाचक में संख्या नहीं होती', false, 'cbc44bdd-7808-40f7-a419-cbb8a6e2ab04');
