INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c63097ac-b837-4703-b0b0-53b3dc3dcc22', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'वाक्य में प्रयुक्त दोनों ''कुछ'' का सही विशेषण क्रम बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('417ac7ad-f6bf-47ca-baa6-2599fca4dc83', 'कुछ फल = अनिश्चित संख्यावाचक ; कुछ दूध = अनिश्चित परिमाणवाचक', true, 'c63097ac-b837-4703-b0b0-53b3dc3dcc22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d7b2ec7-8416-4358-a4f7-ba8bf63009a8', 'कुछ फल = परिमाणवाचक ; कुछ दूध = संख्यावाचक', false, 'c63097ac-b837-4703-b0b0-53b3dc3dcc22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0344c360-0f2e-4362-a4b5-f0e25a598e47', 'दोनों संख्यावाचक हैं', false, 'c63097ac-b837-4703-b0b0-53b3dc3dcc22');
