INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13e75f62-5a40-4352-be5e-1487c56905aa', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'संज्ञा शब्द ''भारत'' और ''इतिहास'' से बनने वाले सही विशेषण शब्द क्रमशः क्या हैं?', 'भारत + ईय = भारतीय; इतिहास + इक = ऐतिहासिक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a33dac17-f49b-4d0b-bb38-dccc242eda8f', 'भारतीय और ऐतिहासिक', true, '13e75f62-5a40-4352-be5e-1487c56905aa');
