INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5c4afe9-6bf2-44da-8a0b-e8c78eb22ec7', 'भारती और इतिहासवान', false, '13e75f62-5a40-4352-be5e-1487c56905aa');
