INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95d6e193-28bd-4133-a029-83df74b32c4b', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'संज्ञा शब्द ''दया'', ''धर्म'' और ''नगर'' से ''इक'' या ''लु'' प्रत्यय जोड़कर बनने वाले विशेषण शब्द क्या हैं?', 'दया + आलु = दयालु; धर्म + इक = धार्मिक; नगर + इक = नागरिक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe745de1-46af-4df1-ba93-b0d93b31ad49', 'दयालु, धार्मिक, नागरिक', true, '95d6e193-28bd-4133-a029-83df74b32c4b');
