INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5f1174e-40d3-4076-a034-e8a62d33677f', 'दयावान, धर्महीन, नगरिया', false, '95d6e193-28bd-4133-a029-83df74b32c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b3dae7f-0b72-416a-a860-6fea65bb8a0a', 'दयानंद, धर्मिक, नगरवासी', false, '95d6e193-28bd-4133-a029-83df74b32c4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0de345f3-e9de-482f-a72b-55c844ec7a0f', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'संज्ञा शब्द ''जंग'' और ''विष'' से ''ईला'' प्रत्यय लगाकर बनने वाले सही विशेषण रूप क्या हैं?', 'जंगल + ई = जंगली; विष + ऐला = विषैला।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f3ebc54-4553-4a30-aa44-669778c5fc31', 'जंगली और विषैला (या जहरीला)', true, '0de345f3-e9de-482f-a72b-55c844ec7a0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d9bd7ab-ad8c-4ac5-b2d8-1a7d45fa08c4', 'जंगला और विषैली', false, '0de345f3-e9de-482f-a72b-55c844ec7a0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdc080ae-6dd4-4b03-9121-720f8b47bfab', 'जंगलू और विषवान', false, '0de345f3-e9de-482f-a72b-55c844ec7a0f');
