INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3684b005-e932-478a-a24d-65a624c7828c', 'निश्चयवाचक सर्वनाम', false, '633d0b79-f6be-4260-9d4b-848d88545811');
