INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2678ea69-22ba-4d90-bf7b-318c8b05a3e9', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'विशेषण की तुलना की दृष्टि से कितनी अवस्थाएँ (Degrees of Comparison) होती हैं?', 'तुलनात्मक 3 अवस्थाएँ: मूलावस्था (Positive), उत्तरावस्था (Comparative: -तर), उत्तमावस्था (Superlative: -तम)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0babb23f-8f92-4745-bc43-0aaafdd7c668', 'तीन अवस्थाएँ (1. मूलावस्था - जैसे ''सुंदर'', 2. उत्तरावस्था - जैसे ''सुंदरतर / अधिक सुंदर'', 3. उत्तमावस्था - जैसे ''सुंदरतम / सबसे सुंदर'')', true, '2678ea69-22ba-4d90-bf7b-318c8b05a3e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('517d9baa-1f88-4994-81f1-e570b1d0e49d', 'दो अवस्थाएँ', false, '2678ea69-22ba-4d90-bf7b-318c8b05a3e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0150c7c2-50cd-41ca-b92e-78c86bc05b3a', 'चार अवस्थाएँ', false, '2678ea69-22ba-4d90-bf7b-318c8b05a3e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d44e309c-de64-412e-aa1a-99896d748bd3', 'पाँच अवस्थाएँ', false, '2678ea69-22ba-4d90-bf7b-318c8b05a3e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82509672-78ca-47cb-b005-31ab30e6d416', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'शब्द ''उच्च'' की उत्तरावस्था और उत्तमावस्था के सही रूप क्रमशः क्या हैं?', 'उच्च (मूलावस्था) -> उच्चतर (उत्तरावस्था) -> उच्चतम (उत्तमावस्था)।', NOW()) ON CONFLICT DO NOTHING;
