INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b73cd74d-875d-4f0b-8aef-a648d33f19ed', 'उच्चतम और उच्चतर', false, '82509672-78ca-47cb-b005-31ab30e6d416');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18d103ff-3130-4c9d-b414-7ac571d25837', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'वाक्य में प्रयुक्त रेखांकित पद का व्याकरणिक परिचय दीजिए:
