INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b62c16a1-d77a-40fe-8f62-d573cebc098e', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'क्रिया पद ''हँसना'' और ''पढ़ना'' से बनने वाले सही विशेषण शब्द क्रमशः क्या हैं?', 'हँसना -> हँसमुख/हँसोड़; पढ़ना -> पढ़ाकू (कृदंत विशेषण)।', NOW()) ON CONFLICT DO NOTHING;
