INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20b067fa-1061-450c-b196-b7a24790ee82', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'अव्यय पद ''बाहर'' और ''आगे'' से बनने वाले विशेषण शब्द क्रमशः क्या हैं?', 'बाहर + ई = बाहरी; आगे + ला = अगला; पीछे + ला = पिछला।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fcb824e-6b33-411e-84a1-309a3a08b642', 'बाहरी और अगला', true, '20b067fa-1061-450c-b196-b7a24790ee82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6e4b869-b0af-426f-80c4-d791f5617495', 'बाहरवाला और आगेवाला', false, '20b067fa-1061-450c-b196-b7a24790ee82');
