INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d4661ff-1a6d-4bdd-a303-e07016424e56', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'स्थानवाचक गुणवाचक विशेषण का सही समूह कौन-सा है?', 'स्थान, भूभाग या क्षेत्र से संबद्ध विशेषता बताने वाले शब्द स्थानवाचक गुणवाचक विशेषण हैं (बनारसी साड़ी, जोधपुरी पगड़ी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('971cc665-eb84-45d2-86ba-43ab78301a41', 'भारतीय, जापानी, बनारसी, ग्रामीण, शहरी, पहाड़ी', true, '8d4661ff-1a6d-4bdd-a303-e07016424e56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('444a74d4-df15-49c8-9909-ad41a7d82e0e', 'लाल, पीला, नीला, हरा', false, '8d4661ff-1a6d-4bdd-a303-e07016424e56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b9a01ca-b4b0-41f4-a637-20041f6492e8', 'गोल, चौकोर, नुकीला', false, '8d4661ff-1a6d-4bdd-a303-e07016424e56');
