INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ab3dc4e-98b6-4f20-86a7-602b25671d8d', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'स्पर्शवाचक गुणवाचक विशेषण का सही उदाहरण कौन-सा है?', 'त्वचा द्वारा अनुभव किए जाने वाले गुण (कोमल, कठोर, खुरदुरा) स्पर्शवाचक विशेषण हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65d3ee3e-8764-4f5c-81d5-6dd6c7d9ce4e', 'कोमल, कठोर, खुरदुरा, मुलायम, चिकना, ठंडा', true, '7ab3dc4e-98b6-4f20-86a7-602b25671d8d');
