INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0870ee7d-a450-4578-9ee1-fc7fa27cc1fa', 'स्वस्थ और रोगी', false, '7ab3dc4e-98b6-4f20-86a7-602b25671d8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82095af1-eb83-47c8-af80-9a2ee48bac26', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'कालवाचक गुणवाचक विशेषण का सही उदाहरण कौन-सा है?', 'समय या काल की विशेषता दर्शाने वाले पद (प्राचीन, नवीन, दैनिक, मौसमी) कालवाचक विशेषण हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68176ebb-31bd-4f20-823c-e946f865e539', 'नया, पुराना, प्राचीन, दैनिक, वार्षिक, मौसमी, आधुनिक', true, '82095af1-eb83-47c8-af80-9a2ee48bac26');
