INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16d3cd57-42fc-45a6-b879-add631c752e2', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50a30cbe-7349-4435-b26d-a5c48736cc4d', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '16d3cd57-42fc-45a6-b879-add631c752e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7752a30a-e027-4da0-888b-4c5f8e70fea8', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '16d3cd57-42fc-45a6-b879-add631c752e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('032a41e9-1d13-44d8-87ac-fb16bdcb8a85', '(A) सही है, परन्तु (R) गलत है।', false, '16d3cd57-42fc-45a6-b879-add631c752e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59783291-354b-4044-a8e8-d08a943c5a1a', '(A) गलत है, परन्तु (R) सही है।', false, '16d3cd57-42fc-45a6-b879-add631c752e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34c6b9b0-e68d-410f-a772-6afdc43f7b3f', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'Spot the IMPOSTER in the following group of विशेषण और उनके भेदों के युग्म में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e09d01b-752f-4649-8a06-66a7d9ad8b0f', 'चार पुस्तकें - निश्चित संख्यावाचक', false, '34c6b9b0-e68d-410f-a772-6afdc43f7b3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1997610-f212-4762-875e-8d4ad729bfdf', 'थोड़ा पानी - अनिश्चित परिमाणवाचक', false, '34c6b9b0-e68d-410f-a772-6afdc43f7b3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53dc4640-72af-448d-9d90-2af3e5ba0891', 'यह बालक - सार्वनामिक विशेषण', false, '34c6b9b0-e68d-410f-a772-6afdc43f7b3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecb111dc-4430-4334-85e9-b1ca41eb2cf1', 'ईमानदार लड़का - अनिश्चित संख्यावाचक', true, '34c6b9b0-e68d-410f-a772-6afdc43f7b3f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28bdc788-f0b7-4c7f-a801-baec26c81d1f', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'सुमेलित कीजिए (संज्ञा शब्द और उनसे बने शुद्ध विशेषण):
(क) भूगोल  -> (i) वार्षिक
(ख) वर्ष    -> (ii) भौगोलिक
(ग) चमक    -> (iii) विषैला
(घ) विष     -> (iv) चमकीला', 'भूगोल = भौगोलिक; वर्ष = वार्षिक; चमक = चमकीला; विष = विषैला।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('635b8f6e-de7a-472b-a477-a67c24615303', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', true, '28bdc788-f0b7-4c7f-a801-baec26c81d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eab03a3-e3f5-4462-b656-f98a2dee318e', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '28bdc788-f0b7-4c7f-a801-baec26c81d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f9241ba-a8f2-4151-aa39-8fc874abeae1', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '28bdc788-f0b7-4c7f-a801-baec26c81d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a06d0c59-9858-4db7-b5a7-2b005ca35187', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '28bdc788-f0b7-4c7f-a801-baec26c81d1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('850c510a-2121-4152-b336-a5458d886022', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'निश्चित संख्यावाचक विशेषण के पाँच प्रमुख उप-प्रकारों (गणनावाचक, क्रमवाचक, आवृत्तिवाचक, समुदायवाचक, प्रत्येकबोधक) का सही सुमेल कौन-सा है?', 'निश्चित संख्या के 5 प्रकार: गणना (1, 2), क्रम (पहला, दूसरा), आवृत्ति (दुगुना, चौगुना), समुदाय (दोनों, तीनों), प्रत्येकबोधक (हर एक, प्रति)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73243a2d-687f-46c0-8dbe-0b6efc642794', 'एक, दो (गणनावाचक) ; पहला, दूसरा (क्रमवाचक) ; दुगुना, तिगुना (आवृत्तिवाचक) ; दोनों, चारों (समुदायवाचक) ; प्रत्येक, हर एक (प्रत्येकबोधक)', true, '850c510a-2121-4152-b336-a5458d886022');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07428df8-9578-410d-a75f-a962485a675e', 'सभी केवल गणनावाचक हैं', false, '850c510a-2121-4152-b336-a5458d886022');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30650cdf-3909-4e95-b477-aaada0a821f5', 'पहला दूसरा समुदायवाचक है', false, '850c510a-2121-4152-b336-a5458d886022');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5b3d4ad-ee32-4d98-902a-7a66653dafaf', 'दुगुना तिगुना क्रमवाचक है', false, '850c510a-2121-4152-b336-a5458d886022');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d938646-4ab1-4dcb-9dad-ea5ec142bb0c', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'वाक्य में प्रयुक्त रेखांकित पद का सही व्याकरणिक भेद बताइए:
