INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76eca6f0-b4c2-4e5b-99fb-deda4bd5c0a4', 'मूलावस्था', false, '7d938646-4ab1-4dcb-9dad-ea5ec142bb0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2168404-b051-48f2-a26a-1c4ef84fc254', 'प्रविशेषण', false, '7d938646-4ab1-4dcb-9dad-ea5ec142bb0c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('361cf8fe-dcc4-43b4-bb09-8aceddb68da3', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'उद्देश्य विशेषण (Attributive) और विधेय विशेषण (Predicative) में क्या अंतर होता है?', 'विशेष्य से पूर्व स्थिति = उद्देश्य विशेषण (लाल गुलाब); विशेष्य के उपरांत स्थिति = विधेय विशेषण (गुलाब लाल है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e971e27-7451-4ace-a7d9-bb67c50f5f05', 'जब विशेषण शब्द विशेष्य (संज्ञा) से पहले आता है तो वह ''उद्देश्य विशेषण'' कहलाता है (जैसे: ''यह मीठा सेब है'') ; और जब विशेषण विशेष्य के बाद तथा क्रिया से पहले आता है तो वह ''विधेय विशेषण'' कहलाता है (जैसे: ''यह सेब मीठा है'')', true, '361cf8fe-dcc4-43b4-bb09-8aceddb68da3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55f1060f-e023-4677-bb51-bb5a373d90a9', 'उद्देश्य विशेषण में विशेष्य नहीं होता', false, '361cf8fe-dcc4-43b4-bb09-8aceddb68da3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2fbc138-797b-42d7-9e11-bbb0c331ebd2', 'विधेय विशेषण केवल भूतकाल में आता है', false, '361cf8fe-dcc4-43b4-bb09-8aceddb68da3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15df4042-a1f3-450a-aed1-1d61372472a1', 'दोनों में कोई अंतर नहीं है', false, '361cf8fe-dcc4-43b4-bb09-8aceddb68da3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0a634ba-47d9-428c-b21d-00fae653c5e1', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'संज्ञा शब्द ''शरीर'', ''बुद्धि'' और ''ज्ञान'' से ''इक'' या ''वान'' प्रत्यय लगाने पर सही विशेषण रूप क्या बनेंगे?', 'शरीर + इक = शारीरिक (आदि स्वर वृद्धि); बुद्धि + इक = बौद्धिक (उ का औ); ज्ञान + वान = ज्ञानवान।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f508ba1-b325-46aa-9efb-2a129fa20127', 'शारीरिक, बौद्धिक, ज्ञानवान', true, 'd0a634ba-47d9-428c-b21d-00fae653c5e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fa6e456-7476-4b4e-af85-185348d3d3c0', 'शरीरी, बुद्धिमान, ज्ञानी', false, 'd0a634ba-47d9-428c-b21d-00fae653c5e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3dfbf87-6cf6-4f68-b4df-fd576bc3d5fd', 'शारीरिक, बुद्धिक, ज्ञानमय', false, 'd0a634ba-47d9-428c-b21d-00fae653c5e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3f24098-0b53-4375-a75f-f49d8fb9f275', 'शरीरवान, बुद्धिहीन, ज्ञानिक', false, 'd0a634ba-47d9-428c-b21d-00fae653c5e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d68b569-b341-451d-a9f4-cd0006348f3d', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'सर्वनाम पद ''यह'' और ''वह'' से निर्मित विशेषण शब्द क्रमशः क्या हैं?', 'सर्वनामों से रूपांतरित यौगिक विशेषण: ''यह'' -> ऐसा/इतना; ''वह'' -> वैसा/उतना; ''कौन'' -> कैसा/कितना; ''जो'' -> जैसा/जितना।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d815827-c2d9-4514-a591-e0ea32c67acc', 'ऐसा (या इतना) और वैसा (या उतना)', true, '5d68b569-b341-451d-a9f4-cd0006348f3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab5e46f2-0220-4c85-8c11-f70e2564041a', 'यहवाला और वहवाला', false, '5d68b569-b341-451d-a9f4-cd0006348f3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf99c4c9-8f98-4df8-9645-377d9a7c15e4', 'यहाँ और वहाँ', false, '5d68b569-b341-451d-a9f4-cd0006348f3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6a4416e-2eb8-4cd6-8b7c-b4dd9acd623f', 'इसका और उसका', false, '5d68b569-b341-451d-a9f4-cd0006348f3d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9578a8bb-25dc-432d-9ee7-d00f572845b4', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'व्यक्तिवाचक विशेषण (Proper Adjective) का सही उदाहरण कौन-सा है?', 'व्यक्तिवाचक संज्ञाओं से निर्मित विशेषण ''व्यक्तिवाचक विशेषण'' कहलाते हैं (जयपुर -> जयपुरी; बनारस -> बनारसी; कश्मीर -> कश्मीरी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bf121b6-75d7-4c81-b794-b7cf8154ff02', 'जयपुरी रज़ाई, बनारसी साड़ी, लखनवी चिकन, कश्मीरी सेब, बीकानेरी भुजिया', true, '9578a8bb-25dc-432d-9ee7-d00f572845b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('118713ce-7c36-4870-9643-0b4f8e92b829', 'अच्छा लड़का और सुंदर लड़की', false, '9578a8bb-25dc-432d-9ee7-d00f572845b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('134227ff-3e98-482b-bdbf-b67995d91913', 'दो किलो आम', false, '9578a8bb-25dc-432d-9ee7-d00f572845b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c29e2e0d-42b4-4cbb-8eb0-66146ea9fc70', 'पहला और दूसरा', false, '9578a8bb-25dc-432d-9ee7-d00f572845b4');
