INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf150222-c057-435f-af89-c32eee399c03', 'प्रत्येकबोधक निश्चित संख्यावाचक विशेषण', true, 'b52bb76c-64b0-4fcc-b7a4-4ac9f0ab4c86');
