INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95cb169a-e93d-40b6-989b-b5c7bfc949a7', '''यह सबसे सुंदर फूल है।'' (या ''यह सुंदरतम फूल है।'' - ''सबसे'' और ''-तम'' दोनों का एक साथ प्रयोग पुनरुक्ति दोष है)', true, '7089b134-6e64-420f-9bd9-8584bfd42197');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('817f7a57-9b81-4bb6-8dfe-64cbfd5daa39', 'यह सुंदर फूल है सबसे।', false, '7089b134-6e64-420f-9bd9-8584bfd42197');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d291054a-6088-4d5f-bb1f-c81ee7636f2c', 'यह सुंदरतम सबसे फूल है।', false, '7089b134-6e64-420f-9bd9-8584bfd42197');
