INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da5eed33-b287-4f34-9af3-4402e9e8575c', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'विशेषण पदों की पद-व्याख्या (पद-परिचय) करते समय किन-किन व्याकरणिक तत्वों का उल्लेख करना अनिवार्य होता है?', 'विशेषण के पद-परिचय में 5 तत्व शामिल होते हैं: भेद, अवस्था, लिंग, वचन और विशेष्य।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a23d9e9e-0f71-4e8d-ab91-e0f54aa3fb29', 'विशेषण का भेद, उसकी अवस्था (मूलावस्था/उत्तरावस्था/उत्तमावस्था), उसका लिंग, वचन, तथा उसका संबंधित विशेष्य पद', true, 'da5eed33-b287-4f34-9af3-4402e9e8575c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acb41fbb-6de8-48f5-aa6a-12eb4d2d47d5', 'केवल उसका अर्थ', false, 'da5eed33-b287-4f34-9af3-4402e9e8575c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f45c6a0-cef3-44ed-9b97-2dc36ee83d3e', 'केवल कारक चिह्न', false, 'da5eed33-b287-4f34-9af3-4402e9e8575c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b010d69-42c4-4689-9167-8c52be881a25', 'केवल काल', false, 'da5eed33-b287-4f34-9af3-4402e9e8575c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3579fcb-37ff-4355-951b-78a9cfc0297c', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'What is a naturally occurring magnetic rock/mineral consisting of iron oxide (Fe₃O₄) that was discovered in ancient Greece?', 'Magnetite is a natural permanent magnet discovered in Magnesia, ancient Greece, also called ''lodestone'' (''leading stone'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c95dfc5-8437-4351-ba1b-bfad10ddea74', 'Magnetite (Lodestone)', true, 'c3579fcb-37ff-4355-951b-78a9cfc0297c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('130cd4cb-9b83-468d-92f7-b9af379e988a', 'Hematite', false, 'c3579fcb-37ff-4355-951b-78a9cfc0297c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('379d5697-2caa-4256-8d62-a1eb3fcc321a', 'Bauxite', false, 'c3579fcb-37ff-4355-951b-78a9cfc0297c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23771bc4-582b-47a7-8acc-38e864bfd3d2', 'Pyrite', false, 'c3579fcb-37ff-4355-951b-78a9cfc0297c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72190127-a33a-4341-aaa1-b6df79833699', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'Who was the ancient Greek shepherd who discovered natural magnetic rock when the iron tip of his walking stick and iron nails in his shoes got stuck to a black rock?', 'Legend says the shepherd Magnes discovered magnetic ore on Mount Ida when his iron-tipped staff stuck to magnetite rocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54003b16-b2af-45db-baaa-87f880897123', 'Magnes', true, '72190127-a33a-4341-aaa1-b6df79833699');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbd068e3-318b-41b2-957a-6c6028c22b63', 'Archimedes', false, '72190127-a33a-4341-aaa1-b6df79833699');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34466711-a1b0-4b58-8991-4f6faedc609e', 'Aristotle', false, '72190127-a33a-4341-aaa1-b6df79833699');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acabb0e8-2ab4-4861-9faf-5ef939bb3a98', 'Socrates', false, '72190127-a33a-4341-aaa1-b6df79833699');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d571096f-8a92-4170-9b3e-72c5727ea5d3', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'Materials that are attracted strongly towards a magnet (such as iron, nickel, cobalt, and steel) are called:', 'Ferromagnetic materials containing unpaired d-electrons (Fe, Ni, Co) are attracted to magnetic fields.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f8595e0-ff1d-4308-941b-9b6d09fbac86', 'Magnetic Materials', true, 'd571096f-8a92-4170-9b3e-72c5727ea5d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5d19a01-8972-4410-8280-268f2f766cc7', 'Non-magnetic Materials', false, 'd571096f-8a92-4170-9b3e-72c5727ea5d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76d8664b-910c-4628-9563-a1b784d51649', 'Insulators', false, 'd571096f-8a92-4170-9b3e-72c5727ea5d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63052d51-d2cd-4334-a8cc-75fc73837505', 'Plastic Materials', false, 'd571096f-8a92-4170-9b3e-72c5727ea5d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d6a8b55-5c2e-46f4-801f-bbd83293c6e1', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'Materials that are NOT attracted towards a magnet (such as wood, plastic, rubber, glass, paper, gold, aluminium) are called:', 'Non-magnetic materials lack permanent atomic magnetic dipoles and do not exhibit magnetic attraction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76ce672d-65a6-47e4-ba87-9089e74ef2d1', 'Non-magnetic Materials', true, '9d6a8b55-5c2e-46f4-801f-bbd83293c6e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2d5438b-9eef-4a14-956f-6d389dc37a46', 'Magnetic Materials', false, '9d6a8b55-5c2e-46f4-801f-bbd83293c6e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4139b628-d6e5-496b-8150-0ee37d393534', 'Electromagnets', false, '9d6a8b55-5c2e-46f4-801f-bbd83293c6e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('656813c4-a18f-4172-9dc5-f6ea5be35870', 'Lodestones', false, '9d6a8b55-5c2e-46f4-801f-bbd83293c6e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f2bbd8a-9cc2-4291-b98d-999053f52c4c', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'How many magnetic poles does EVERY magnet possess, regardless of its shape or size?', 'Magnetic dipoles always exist in pairs: a North-seeking pole (N) and a South-seeking pole (S).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b912c3b-083e-4f3f-aab4-7ad49e9831a2', 'Two poles (North Pole ''N'' and South Pole ''S'')', true, '5f2bbd8a-9cc2-4291-b98d-999053f52c4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d0a17f2-666f-448f-bacb-3cc787cde0e8', 'One single pole', false, '5f2bbd8a-9cc2-4291-b98d-999053f52c4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2c2579f-c744-4a4b-a7f2-d4e93ad12d71', 'Three poles', false, '5f2bbd8a-9cc2-4291-b98d-999053f52c4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60fa6d55-0a0d-45c4-802f-b96c86e24084', 'Four poles', false, '5f2bbd8a-9cc2-4291-b98d-999053f52c4c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cf807bf-8960-423a-aea2-9cc4299d8576', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'Where is the magnetic force (attraction power) of a bar magnet the STRONGEST?', 'Magnetic field flux density converges at the two terminal poles, where iron filings cling in dense clusters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6095b100-cd0b-443e-aadc-1f6606fcf961', 'Near its two end Poles (North and South Poles)', true, '3cf807bf-8960-423a-aea2-9cc4299d8576');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f14c13ed-54e2-41f6-82fd-11aed5992f69', 'Exactly at the center of the magnet', false, '3cf807bf-8960-423a-aea2-9cc4299d8576');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36c9bd04-b84f-4fca-9150-b224e12e6c80', 'Uniform everywhere across its body', false, '3cf807bf-8960-423a-aea2-9cc4299d8576');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ccc2c15-f385-4aa1-8560-202fef6790ff', 'Only on its top surface', false, '3cf807bf-8960-423a-aea2-9cc4299d8576');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84e176d6-3179-4358-8fe1-24fc2182ab83', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'In which geographical direction does a freely suspended bar magnet ALWAYS come to rest?', 'A freely pivoted magnet aligns with Earth''s geomagnetic field lines along the geographic North-South meridian.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7893763f-c500-4878-b4f2-6b6a84038297', 'North-South direction (N-S)', true, '84e176d6-3179-4358-8fe1-24fc2182ab83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48125e81-84d4-4aba-aced-6150887b02e4', 'East-West direction (E-W)', false, '84e176d6-3179-4358-8fe1-24fc2182ab83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43f586eb-cd47-44fd-b085-473779d47c6a', 'North-East direction', false, '84e176d6-3179-4358-8fe1-24fc2182ab83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('117db178-1f28-46e2-97a0-43d7a5522e90', 'Any random direction', false, '84e176d6-3179-4358-8fe1-24fc2182ab83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fa0b42a-a39b-4e0b-aa52-535592239e23', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'What navigational instrument uses a magnetized needle freely pivoted inside a dial to find geographical directions?', 'A magnetic compass features a pivoted magnetized needle whose painted North tip indicates geomagnetic north.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0315b6ac-bb2e-4417-a796-f0a258678790', 'Magnetic Compass', true, '7fa0b42a-a39b-4e0b-aa52-535592239e23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8403d53-bd94-406a-8ae0-1aa524eb0b2c', 'Speedometer', false, '7fa0b42a-a39b-4e0b-aa52-535592239e23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('508fc07d-03a6-4ab3-ab1b-c377c53c0cef', 'Barometer', false, '7fa0b42a-a39b-4e0b-aa52-535592239e23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd946d77-3526-4b57-b20a-52542251df46', 'Thermometer', false, '7fa0b42a-a39b-4e0b-aa52-535592239e23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce1feb97-8d56-42e4-9eac-e1e1a7a32971', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'What happens when two LIKE magnetic poles (North and North, or South and South) are brought close to each other?', 'Fundamental magnetic law: Like poles repel (N-N or S-S); unlike poles attract (N-S).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66bae864-86dc-4193-a220-cab660445635', 'They REPEL (push away from) each other', true, 'ce1feb97-8d56-42e4-9eac-e1e1a7a32971');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61e0b786-57ce-44f1-9fa6-2112f6ff7672', 'They attract each other', false, 'ce1feb97-8d56-42e4-9eac-e1e1a7a32971');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4895b523-8afb-427f-a35f-e15223c6d26e', 'They stick together tightly', false, 'ce1feb97-8d56-42e4-9eac-e1e1a7a32971');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62b96fb1-7b43-4ac7-a86c-997b395429bb', 'They turn into copper', false, 'ce1feb97-8d56-42e4-9eac-e1e1a7a32971');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0cb31d26-1920-48bc-a491-dc2e9cbaa48b', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'What happens when two UNLIKE magnetic poles (North and South) are brought close to each other?', 'Opposite magnetic polarities (N and S) experience mutual attractive Lorentz/dipolar forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a693e2f6-c6ee-43eb-8f0b-e9fd08bc1915', 'They ATTRACT (pull towards) each other', true, '0cb31d26-1920-48bc-a491-dc2e9cbaa48b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfd8789f-0036-499f-b0d3-59ab4150923e', 'They repel each other', false, '0cb31d26-1920-48bc-a491-dc2e9cbaa48b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('635f4788-79c8-44a2-82c1-5095cbd4fae7', 'They lose their magnetism immediately', false, '0cb31d26-1920-48bc-a491-dc2e9cbaa48b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b27637d-8e0f-417f-af98-2810d3e8d632', 'They heat up and melt', false, '0cb31d26-1920-48bc-a491-dc2e9cbaa48b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d63d9d1-b44a-4293-8bb8-aba2b95cb308', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'Which of the following is a classic artificial shape of manufactured permanent magnets?', 'Artificial magnets are cast/sintered in bar, horseshoe, disc, cylindrical, and ring geometries.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30b1f9ae-c171-4062-8738-78f8a8580e09', 'Bar magnet, Horse-shoe magnet, Cylindrical magnet, and Ball-ended magnet', true, '2d63d9d1-b44a-4293-8bb8-aba2b95cb308');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25afce3f-6141-4ab3-b3bc-eed93e10a137', 'Square paper magnet', false, '2d63d9d1-b44a-4293-8bb8-aba2b95cb308');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('422ee8dc-5293-4e65-ab21-770da4c155ea', 'Liquid water magnet', false, '2d63d9d1-b44a-4293-8bb8-aba2b95cb308');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41f1945c-341d-4c24-aa1b-6354326f9f63', 'Cloth magnet', false, '2d63d9d1-b44a-4293-8bb8-aba2b95cb308');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93a8a599-97cb-4cf7-8e2f-d470d7be402c', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'What is the surest and only foolproof test to confirm whether an unknown metal piece is an active magnet or merely a magnetic iron piece?', 'Unmagnetized ferromagnetic iron is attracted by both N and S poles; only a true magnet repels like poles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eb34748-cf41-4f24-8c4f-c7ec6e83365e', 'REPULSION test (only another magnet will experience repulsion; an ordinary iron piece is attracted to both poles)', true, '93a8a599-97cb-4cf7-8e2f-d470d7be402c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bebc405-3914-4b3c-be9d-b469d2649963', 'Attraction test', false, '93a8a599-97cb-4cf7-8e2f-d470d7be402c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3baef53a-8f4d-4e50-9e6f-7b145c7edc4b', 'Weighing test', false, '93a8a599-97cb-4cf7-8e2f-d470d7be402c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d72daf12-a00f-484d-bd58-eec1d54dd25a', 'Color test', false, '93a8a599-97cb-4cf7-8e2f-d470d7be402c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f3925a5-53c7-4502-a0d7-ab824df3cc2a', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'What happens when a bar magnet is cut or broken into TWO halves across its middle?', 'Atomic magnetic domains remain dipolar; cutting a magnet creates two smaller dipoles each with N and S poles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09d9c8b2-0359-4f58-9de3-013d7e1ccafe', 'Each broken piece becomes a complete, independent magnet with its own North and South Pole (Magnetic monopoles do NOT exist)', true, '7f3925a5-53c7-4502-a0d7-ab824df3cc2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c96eaa3d-1b51-4ba4-81e9-ac7f3c065178', 'One piece becomes pure North pole and the other pure South pole', false, '7f3925a5-53c7-4502-a0d7-ab824df3cc2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07e7557e-d56b-41c7-8221-7e6cbf0960e9', 'Both pieces lose all magnetism permanently', false, '7f3925a5-53c7-4502-a0d7-ab824df3cc2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39a55574-7961-4344-8349-f19558863bb2', 'The magnet explodes', false, '7f3925a5-53c7-4502-a0d7-ab824df3cc2a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e386cfef-31fa-4240-a913-eb7257da2941', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'How can you magnetize an ordinary iron nail or sewing needle using the ''Single-Touch'' method?', 'Unidirectional stroking aligns magnetic Weiss domains in the ferromagnetic nail along the stroke vector.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65e50114-032a-4c75-8a3b-6620bcd07c5a', 'Stroke the iron nail with one pole of a bar magnet repeatedly in ONE fixed direction along its length (30–40 times) without reversing direction', true, 'e386cfef-31fa-4240-a913-eb7257da2941');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('320e7e22-b2b8-41f1-a0e2-6a369cd2d895', 'Rub the magnet back and forth randomly', false, 'e386cfef-31fa-4240-a913-eb7257da2941');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dd176ad-81f2-43e1-a472-e4266510145f', 'Heat the nail in a fire with the magnet', false, 'e386cfef-31fa-4240-a913-eb7257da2941');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f54d143-72a8-41d8-b6d6-6cf101a4258c', 'Drop the nail in cold water', false, 'e386cfef-31fa-4240-a913-eb7257da2941');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5427ca2f-4f78-413d-961e-d9e24d4f4946', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Which of the following actions can cause a permanent magnet to LOSE its magnetism (Demagnetization)?', 'Thermal energy (above Curie temperature) and mechanical impact randomize aligned magnetic domain orientations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0451f91-e4f2-4b77-b664-09f85b6f586e', 'Heating to high temperatures, hammering vigorously with a mallet, or dropping it repeatedly from a height onto hard floor', true, '5427ca2f-4f78-413d-961e-d9e24d4f4946');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1eaf9aec-d8fa-4ef0-93bc-f37f6d8dbe92', 'Washing it with clean water', false, '5427ca2f-4f78-413d-961e-d9e24d4f4946');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef186438-f3fd-49c7-94f3-c9b5da659623', 'Keeping it in a dark wooden box', false, '5427ca2f-4f78-413d-961e-d9e24d4f4946');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('879cde39-a244-477e-aea0-46a86ce6bf76', 'Using it to pick up paper clips', false, '5427ca2f-4f78-413d-961e-d9e24d4f4946');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d877b9a-90fe-4bdf-bc0c-19d25155e351', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'How should Bar Magnets be safely stored in pairs to preserve their magnetic strength over years?', 'Soft iron magnetic keepers close magnetic flux loops, preventing self-demagnetizing free pole dissipation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28587499-e703-4cdd-b581-0eba997f9990', 'Stored in pairs with UNLIKE poles opposite each other, separated by a wooden spacer in the middle and connected by soft iron pieces (Keepers) across their ends', true, '1d877b9a-90fe-4bdf-bc0c-19d25155e351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb91b73-2052-4a74-9d4f-0cb004500555', 'Stored with like poles touching', false, '1d877b9a-90fe-4bdf-bc0c-19d25155e351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b5c8539-1237-41d1-ae45-8c468a3c72c2', 'Stored loose in an iron bucket', false, '1d877b9a-90fe-4bdf-bc0c-19d25155e351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff701e26-ae33-4493-b376-8ee030d547cd', 'Stored submerged in salt water', false, '1d877b9a-90fe-4bdf-bc0c-19d25155e351');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7af2152-444e-414f-b290-7485c9b687fc', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'How should a Horseshoe Magnet be stored properly?', 'A soft iron keeper across both adjacent poles of a horseshoe magnet bridges the gap, completing the magnetic circuit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1400bb1b-c540-4a4f-a1d0-d683f96640b4', 'By placing a single piece of soft iron (magnetic keeper) across its two open poles', true, 'f7af2152-444e-414f-b290-7485c9b687fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ea6fba6-6405-45a3-a21e-4bbc17675fa8', 'By bending its arms together', false, 'f7af2152-444e-414f-b290-7485c9b687fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4938527-913f-4486-8e16-10a94d40a91b', 'By heating it before storing', false, 'f7af2152-444e-414f-b290-7485c9b687fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05f3f740-a113-4f5e-8ba3-5505837180e3', 'By wrapping it in aluminium foil', false, 'f7af2152-444e-414f-b290-7485c9b687fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea727221-c72d-40a5-816e-717d3482eedd', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Why does the Earth itself behave like a colossal gigantic magnet?', 'Geodynamo convection in the outer core generates Earth''s geomagnetic field; geographic North hosts geomagnetic South polarity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fce6b698-f2c4-4b12-808a-c52fd58bcb2c', 'Circulating molten iron-nickel liquid currents in Earth''s outer core generate a geomagnetic field, with its magnetic south pole located near the geographic North Pole', true, 'ea727221-c72d-40a5-816e-717d3482eedd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6703d09-58c6-489f-b22c-ae36a60fe794', 'Because Earth is made of giant plastic magnets', false, 'ea727221-c72d-40a5-816e-717d3482eedd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3077e6a0-395d-4803-986c-f0d469683340', 'Because mountains are magnetic', false, 'ea727221-c72d-40a5-816e-717d3482eedd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c31e716-ecc4-4873-a8ff-cb2d2c8d8fa3', 'Because satellites magnetize Earth', false, 'ea727221-c72d-40a5-816e-717d3482eedd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da3ef80d-b208-4cb7-a8da-96ffe2a6fa95', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'What ancient Chinese legend describes an emperor''s chariot equipped with a rotating wooden statue holding an outstretched arm that always pointed SOUTH?', 'Huang Di''s legendary chariot utilized a lodestone/geared mechanism whose statue arm consistently pointed South.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8cc857c-c6a4-4486-96b6-f51af928f459', 'The South-Pointing Chariot of Emperor Huang Di', true, 'da3ef80d-b208-4cb7-a8da-96ffe2a6fa95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34ae12db-f04c-40ab-b776-325d98748f4d', 'The Dragon Compass', false, 'da3ef80d-b208-4cb7-a8da-96ffe2a6fa95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88c460e9-99e3-49ba-91e6-dc9e92ad2ffb', 'The Great Wall Chariot', false, 'da3ef80d-b208-4cb7-a8da-96ffe2a6fa95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26540cd4-fefc-4bfd-8ee0-9d69c740f6ec', 'The Silk Navigator', false, 'da3ef80d-b208-4cb7-a8da-96ffe2a6fa95');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fab1e47-9be2-4c3c-971b-994fc7696ef7', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Why should permanent strong magnets be kept away from cassette tapes, credit cards, computer hard drives, and mobile phones?', 'External stray magnetic flux can corrupt magnetically stored binary bits and saturate Hall sensors in electronics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b8e14ca-60fd-4fde-a7ea-0474cb3ed83a', 'The strong magnetic field can alter or erase the magnetic data encoded on magnetic strips, chips, and micro-circuitry', true, '0fab1e47-9be2-4c3c-971b-994fc7696ef7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8df49e3d-4c0a-49f8-9d29-50056a1f9096', 'Because magnets will catch fire near phones', false, '0fab1e47-9be2-4c3c-971b-994fc7696ef7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e27fed5-e1b8-4b53-abab-23ff1a5642c8', 'Because phones will become too heavy', false, '0fab1e47-9be2-4c3c-971b-994fc7696ef7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c841f34-24ee-4b39-800a-30c41239e6e2', 'Because phone glass turns into mirror', false, '0fab1e47-9be2-4c3c-971b-994fc7696ef7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8b0f7ef-2963-4b22-a342-fab3c9091c25', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'If an iron needle is magnetized by stroking with the North pole of a bar magnet starting from end A to end B, what magnetic pole is formed at end B?', 'The trailing end B of the stroke acquires opposite polarity (South pole) to the departing North pole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab46fb95-082e-4169-8311-6c94b9fad6cc', 'South Pole (opposite to the stroking pole)', true, 'f8b0f7ef-2963-4b22-a342-fab3c9091c25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ebad0d0-a164-439a-abf1-9bafe0a99365', 'North Pole', false, 'f8b0f7ef-2963-4b22-a342-fab3c9091c25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('890afeb4-2e2f-4173-8ed8-a923e5599b9b', 'No pole is formed', false, 'f8b0f7ef-2963-4b22-a342-fab3c9091c25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4be1ef49-1b48-4fc8-9b7c-535ee13cc62b', 'End B becomes non-magnetic', false, 'f8b0f7ef-2963-4b22-a342-fab3c9091c25');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bff8149b-b38b-4b0d-beef-a873c20ff6ae', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Can magnetic force act through non-magnetic barriers (like a sheet of paper, cardboard, or a plastic ruler)?', 'Magnetic flux permeates non-ferromagnetic dielectric media with magnetic permeability μ ≈ μ₀.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afe3b2ce-a9d6-4fa6-9713-4fcef23396e5', 'Yes, magnetic field lines penetrate through non-magnetic materials like paper, glass, plastic, and water effortlessly', true, 'bff8149b-b38b-4b0d-beef-a873c20ff6ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('012cacc9-2847-41e4-8f9d-29988ca226cd', 'No, paper blocks all magnetic forces completely', false, 'bff8149b-b38b-4b0d-beef-a873c20ff6ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81a06f3e-a654-41cc-a67e-2e49f8bb24fa', 'Only if the paper is wet', false, 'bff8149b-b38b-4b0d-beef-a873c20ff6ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72c66ab8-5b54-4753-89f7-2c0acc289ac2', 'Only in space', false, 'bff8149b-b38b-4b0d-beef-a873c20ff6ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d8af44f-f6cd-4a0b-942d-81a71fc8b665', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'A tailor dropped a box of sewing needles into a box of sawdust. What is the fastest and easiest way to separate all the steel needles without searching by hand?', 'Magnetic separation extracts ferromagnetic steel needles while leaving non-magnetic sawdust behind.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64b4441b-e944-47b6-9b34-8572157dad02', 'Pass a strong magnet through the sawdust; all steel needles will cling to the magnet instantly', true, '7d8af44f-f6cd-4a0b-942d-81a71fc8b665');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e396083-0da7-4e8b-b547-5512924009b5', 'Burn the sawdust', false, '7d8af44f-f6cd-4a0b-942d-81a71fc8b665');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40971e58-e982-4ac5-8011-ed9e3d10e8ce', 'Dissolve in water', false, '7d8af44f-f6cd-4a0b-942d-81a71fc8b665');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ae9b23e-0b9c-4d60-b1c9-779c2f579fe4', 'Use a microscope', false, '7d8af44f-f6cd-4a0b-942d-81a71fc8b665');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fdef217f-c63f-4a5e-98d4-9beac8ca0619', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Which of the following modern technological devices utilizes powerful magnets to operate?', 'Electromagnetic induction and magnetic levitation power electric motors, Maglev transit, MRI tomography, and acoustic transducers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('352aeedd-24a2-431d-88f2-4aacde63a184', 'Electric motors, Dynamos, MRI medical scanners, Maglev trains, and Audio speakers', true, 'fdef217f-c63f-4a5e-98d4-9beac8ca0619');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('806d4ad3-4f47-4f12-83eb-5c864a087523', 'Wooden chairs', false, 'fdef217f-c63f-4a5e-98d4-9beac8ca0619');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef22095b-57c7-4775-8548-d6a533ea733f', 'Cotton shirts', false, 'fdef217f-c63f-4a5e-98d4-9beac8ca0619');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f796b56f-ef8f-4a20-9275-3fa92323e2fc', 'Glass bottles', false, 'fdef217f-c63f-4a5e-98d4-9beac8ca0619');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06320e2d-e1e2-4a72-aa08-5c89413719a7', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'How does a Maglev (Magnetic Levitation) high-speed bullet train run without touching the track rails?', 'Electrodynamic/electromagnetic levitation utilizes magnetic repulsion to float carriages ~10–15 mm above guideways.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89df7b60-278c-4388-a84c-ead71f7a2b23', 'Superconducting electromagnets on the train and track repel each other with strong like magnetic poles, levitating the train in air and eliminating mechanical friction', true, '06320e2d-e1e2-4a72-aa08-5c89413719a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97c48714-95c1-44a7-96ca-4498b1d5195f', 'It flies using jet wings', false, '06320e2d-e1e2-4a72-aa08-5c89413719a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37cfcdec-c418-4d07-8d99-dcfbe3ce5e2d', 'It rolls on millions of tiny ball bearings', false, '06320e2d-e1e2-4a72-aa08-5c89413719a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c8ce225-87cd-420a-9107-cd3ec6e78df7', 'It floats on a layer of hot steam', false, '06320e2d-e1e2-4a72-aa08-5c89413719a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46d41706-872a-4213-8701-a4367d302940', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'What is an ''Electromagnet''?', 'An electromagnet generates a controllable magnetic field via current flow through an insulated solenoid coil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59a46aaf-beca-4ee5-a97f-fbeea5c7c935', 'A temporary magnet formed by winding an insulated copper wire around a soft iron core and passing electric current through it', true, '46d41706-872a-4213-8701-a4367d302940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb82abed-651b-41a8-9600-84712fa3f08e', 'A rock found in the ocean', false, '46d41706-872a-4213-8701-a4367d302940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5058275-7bf6-45cb-9d84-fb7bc71f6b82', 'A permanent bar magnet that never loses magnetism', false, '46d41706-872a-4213-8701-a4367d302940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9f5ccf5-08bd-4ac2-97cd-c0434a10725e', 'A magnet made of pure plastic', false, '46d41706-872a-4213-8701-a4367d302940');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bbbb5a5-4311-403b-9213-fa7673bdfee4', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Why do iron filings sprinkle on a sheet of paper over a bar magnet arrange themselves in distinct curved lines?', 'Induced magnetic dipolar moments torque iron filings tangent to lines of magnetic flux density.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2f14b89-6552-4609-86f8-97db64eabb36', 'Each tiny iron filing becomes a miniature induced magnet and aligns along the invisible curved Magnetic Field Lines running from North to South pole', true, '1bbbb5a5-4311-403b-9213-fa7673bdfee4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('512dc0ba-61bb-44ac-91a2-c4bee0672a09', 'Because the paper is curved', false, '1bbbb5a5-4311-403b-9213-fa7673bdfee4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b911cc3-eb0e-448a-80a5-030915eeedc6', 'Because iron filings melt', false, '1bbbb5a5-4311-403b-9213-fa7673bdfee4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d0c8148-611a-44e1-8a1b-b95fc387cdab', 'Because of gravity pulling them sideways', false, '1bbbb5a5-4311-403b-9213-fa7673bdfee4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1043fd2e-339a-4cd8-8307-1fcaf4d7bf78', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'What happens if a freely suspended bar magnet is brought near another strong magnet?', 'Torque τ = m × B causes the pivoted dipole to rotate until its magnetic moment aligns with the external field.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fccb687f-3de6-40c8-b258-ba2ce5e7db3e', 'The suspended magnet will rotate and re-align: its North pole will be attracted to the other''s South pole and repelled by its North pole', true, '1043fd2e-339a-4cd8-8307-1fcaf4d7bf78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aeee0f4-f621-47cf-86c6-d92dc7eef4dc', 'It will stop moving forever', false, '1043fd2e-339a-4cd8-8307-1fcaf4d7bf78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('730e3ed2-e0f5-4526-9963-fd909001f9aa', 'It will turn into copper', false, '1043fd2e-339a-4cd8-8307-1fcaf4d7bf78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd304c3e-2b90-42bd-8c38-8611aee0caab', 'It will ignore the second magnet', false, '1043fd2e-339a-4cd8-8307-1fcaf4d7bf78');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a56fd53-47f4-48b4-b9e4-4e8a62add7eb', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a7b989b-7a86-45ec-b1bf-4ed429427252', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '7a56fd53-47f4-48b4-b9e4-4e8a62add7eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f28fa48d-7846-4272-9838-5fab3d15474a', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '7a56fd53-47f4-48b4-b9e4-4e8a62add7eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8da0d256-c033-4412-b3f3-c5774d118c82', '(A) is true, but (R) is false.', false, '7a56fd53-47f4-48b4-b9e4-4e8a62add7eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc09f331-4582-4432-9cf4-3f953cadcf0d', '(A) is false, but (R) is true.', false, '7a56fd53-47f4-48b4-b9e4-4e8a62add7eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0994a38-503c-4d14-bcea-3fe87165316c', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Spot the IMPOSTER in the following group of materials categorized as Non-magnetic:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b279933-524c-485b-8d47-0483197ab7db', 'Pure Aluminium', false, 'a0994a38-503c-4d14-bcea-3fe87165316c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d05496a9-8547-45ba-b214-b407ac6e202c', 'Copper coin', false, 'a0994a38-503c-4d14-bcea-3fe87165316c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f150dbb-743a-40e0-93a5-d2e647d4c3cb', 'Brass screw', false, 'a0994a38-503c-4d14-bcea-3fe87165316c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e015f38c-fb5f-4dc7-bd42-558dcbff2e13', 'Cobalt plate', true, 'a0994a38-503c-4d14-bcea-3fe87165316c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d457c8d3-1e23-4559-90a6-8d12289fbd24', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'A student suspends an unmarked metallic bar X-Y freely. End X points towards geographic North. When the North pole of a known bar magnet is brought near end X, end X is strongly REPELLED. What can you conclude definitively about end X and end Y?', 'Repulsion definitively confirms that bar X-Y is a magnet and end X is a North pole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd39807e-34f1-43ad-ae38-6b5a8b577178', 'The bar is a magnet; end X is a North Pole and end Y is a South Pole', true, 'd457c8d3-1e23-4559-90a6-8d12289fbd24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('126afb35-3612-45c5-8daf-b253b7889073', 'The bar is ordinary non-magnetic aluminium', false, 'd457c8d3-1e23-4559-90a6-8d12289fbd24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b993988a-35d5-4a37-9ca7-6f86df41981c', 'End X is a South Pole', false, 'd457c8d3-1e23-4559-90a6-8d12289fbd24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('556cf5e5-b0a2-409f-875a-0b18db55f861', 'The bar is unmagnetized soft iron', false, 'd457c8d3-1e23-4559-90a6-8d12289fbd24');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f806fbc9-9774-40eb-a3d2-92adefce7ed9', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Match Column I (Magnetic Phenomena) with Column II (Scientific Principles):
(a) Freely suspended magnet -> (i) Opposite poles experience mutual attraction
(b) Like poles (N-N / S-S)     -> (ii) Like poles experience mutual repulsion
(c) Unlike poles (N-S)       -> (iii) Aligns along Earth''s geomagnetic N-S meridian
(d) Soft iron keeper         -> (iv) Closes magnetic flux loop preventing demagnetization', 'Suspended magnet = Earth N-S; Like poles = Repulsion; Unlike poles = Attraction; Keepers = Prevents demagnetization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e3d6c04-8e0b-4fd3-8101-ea56e18ed43a', 'a-(iii), b-(ii), c-(i), d-(iv)', true, 'f806fbc9-9774-40eb-a3d2-92adefce7ed9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('080cfa63-04aa-440e-af1f-98428cd4b1e8', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'f806fbc9-9774-40eb-a3d2-92adefce7ed9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82595895-8a5c-437e-9ba7-60f3380b3234', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'f806fbc9-9774-40eb-a3d2-92adefce7ed9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6669c79f-31f7-4899-a6c6-405b5c17ad03', 'a-(ii), b-(iv), c-(i), d-(iii)', false, 'f806fbc9-9774-40eb-a3d2-92adefce7ed9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da5c5c5b-d2f2-4b68-87b5-1348b8c6a3be', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Read the statements regarding magnetic properties:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa973162-4d20-48ea-bb97-a9388ea724b0', 'Statements 1 and 2 only', true, 'da5c5c5b-d2f2-4b68-87b5-1348b8c6a3be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3569cc10-e94d-4c03-a21e-871cea0eac0d', 'Statements 2 and 3 only', false, 'da5c5c5b-d2f2-4b68-87b5-1348b8c6a3be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ba92e25-155b-454d-94ac-3bb59eb8665a', 'Statements 1 and 3 only', false, 'da5c5c5b-d2f2-4b68-87b5-1348b8c6a3be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c50e710a-3629-4ffe-bdfa-14c627ac7a45', 'All Statements 1, 2, and 3', false, 'da5c5c5b-d2f2-4b68-87b5-1348b8c6a3be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d63e02b1-a7db-43e8-8a9c-299b096607ea', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Why does the geographic North Pole of Earth attract the NORTH-seeking pole of a compass needle?', 'Earth''s internal magnetic dipole is inverted relative to geography: the geomagnetic South pole resides near Arctic geographic North.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24450cba-a1b7-4677-80c6-f3067c1e6dca', 'Because Earth''s geomagnetic SOUTH magnetic pole is physically located near the geographic North Pole, exerting attractive force on the needle''s North pole', true, 'd63e02b1-a7db-43e8-8a9c-299b096607ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08b9e428-a0da-4821-8b0c-d56ca7b4cbde', 'Because like poles attract in space', false, 'd63e02b1-a7db-43e8-8a9c-299b096607ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89883710-f574-4216-bc42-0d024dc3a4ac', 'Because geographic north has positive electricity', false, 'd63e02b1-a7db-43e8-8a9c-299b096607ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5e5dce9-ac3d-47ef-84a8-a5ec2090b772', 'Because the compass is upside down', false, 'd63e02b1-a7db-43e8-8a9c-299b096607ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2590d58-68ec-4a6d-a7e3-b7b882a8e763', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'A heavy-duty industrial magnetic crane in a junkyard lifts 5 tonnes of scrap iron cars and drops them precisely into a furnace. How does the crane operator release the scrap iron instantly?', 'Electromagnets provide instantaneous on/off control: cutting the solenoid circuit demagnetizes the soft iron core, dropping the load.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d73c5a7-6ab0-402b-b8f8-9d0019acfb7d', 'The crane uses a powerful Electromagnet; switching OFF the electric current stops the magnetic field instantly, releasing the scrap iron', true, 'c2590d58-68ec-4a6d-a7e3-b7b882a8e763');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e5f4dcd-e2e2-4695-bd79-6ae4f6eb681c', 'By hitting the magnet with a hammer', false, 'c2590d58-68ec-4a6d-a7e3-b7b882a8e763');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e98079c-d21b-44fc-9b5e-0286a7b43c19', 'By spraying cold water on the cars', false, 'c2590d58-68ec-4a6d-a7e3-b7b882a8e763');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a047cd2-5572-4239-86ae-9d6bfacaf562', 'By turning the crane upside down', false, 'c2590d58-68ec-4a6d-a7e3-b7b882a8e763');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad83317a-313a-478c-9838-8200c3f56b92', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Consider four rings placed over a vertical wooden pencil:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcf1bac9-cb76-4f80-a73e-89fc4f643c64', 'Between Ring 1 and Ring 2 (both facing surfaces have South Pole ''S-S'', causing strong mutual repulsion and levitation)', true, 'ad83317a-313a-478c-9838-8200c3f56b92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c12cb2b1-d4ce-4dd4-aac7-9e55fa789bf3', 'Between Ring 2 and Ring 3', false, 'ad83317a-313a-478c-9838-8200c3f56b92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7761aedf-5864-46d7-9e79-94a459d6f51b', 'Between Ring 3 and Ring 4', false, 'ad83317a-313a-478c-9838-8200c3f56b92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cff5c81b-4adc-4c00-b8c3-c436009aba28', 'All rings stick tightly without gaps', false, 'ad83317a-313a-478c-9838-8200c3f56b92');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0dd46c2f-7ec4-4343-bc01-423335c6ef72', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Why is Soft Iron preferred over Hard Steel for making magnetic keepers and cores of electromagnets?', 'Soft iron possesses low coercive force and narrow hysteresis loop, ideal for temporary magnetic coupling.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d0e850c-aaf1-4361-85b0-1d81ce2cf550', 'Soft iron has high magnetic permeability and low retentivity, magnetizing and demagnetizing instantly without retaining permanent residual magnetism', true, '0dd46c2f-7ec4-4343-bc01-423335c6ef72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baf9876b-8c57-4d92-af3c-f69d9b37dc17', 'Because soft iron is cheaper than wood', false, '0dd46c2f-7ec4-4343-bc01-423335c6ef72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2acaff27-0da8-4edb-9aaa-a7e5b487444e', 'Because soft iron is transparent', false, '0dd46c2f-7ec4-4343-bc01-423335c6ef72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('606db07e-bc8f-4ec4-8354-a8d83fdde063', 'Because steel cannot be magnetized', false, '0dd46c2f-7ec4-4343-bc01-423335c6ef72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad27cb85-9496-4126-9248-4ea0d031776a', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'What is an alloy made of Aluminium, Nickel, and Cobalt widely used to manufacture ultra-strong permanent industrial magnets called?', 'Alnico ferromagnetic alloys combine high coercivity and temperature stability for permanent magnets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edc77f94-eaee-4f44-9444-7dd5ff3fb2a8', 'Alnico (Al-Ni-Co)', true, 'ad27cb85-9496-4126-9248-4ea0d031776a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd5e34af-306d-47a7-80c7-f8a66dae4007', 'Brass', false, 'ad27cb85-9496-4126-9248-4ea0d031776a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c171bb1-6767-4fd2-a1dc-672ce40cdb70', 'Bronze', false, 'ad27cb85-9496-4126-9248-4ea0d031776a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64093761-f46c-4aad-89f0-1644a1d65f9a', 'Solder', false, 'ad27cb85-9496-4126-9248-4ea0d031776a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5dd0f8b-7aa0-4481-a440-224bab833548', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'A compass is placed near an unknown hidden box. The compass needle deflects wildly away when brought near one corner of the box and deflects in reverse at the other corner. What is inside the box?', 'Bipolar deflection matching inverse field directions proves an active magnetic dipole source inside the enclosure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78f361ee-0b97-4163-898e-9d7bbb5c1f6a', 'A permanent magnet (the deflection reversals reflect the presence of North and South dipolar poles)', true, 'e5dd0f8b-7aa0-4481-a440-224bab833548');
