INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3142f0ae-8cf2-49b2-8a4f-75d98cf270e2', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Find the cost of fencing a square park of side 175 m at the rate of ₹20 per metre:', 'Perimeter = 4 × 175 = 700 m. Cost = 700 × ₹20 = ₹14,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62cba0e0-9321-4a12-a1cb-190cec6a980e', '₹14,000 (Perimeter = 4 × 175 = 700 m ; Cost = 700 × ₹20 = ₹14,000)', true, '3142f0ae-8cf2-49b2-8a4f-75d98cf270e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45552303-cc92-45a0-9d49-52619df30300', '₹7,000', false, '3142f0ae-8cf2-49b2-8a4f-75d98cf270e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b02cb0d-4cb5-4a32-b0a2-ba9f977183d8', '₹3,500', false, '3142f0ae-8cf2-49b2-8a4f-75d98cf270e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9b2fb39-f2a5-41eb-9d5e-c7c977cac307', '₹28,000', false, '3142f0ae-8cf2-49b2-8a4f-75d98cf270e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecdc80fe-3d14-4530-a3b2-28bfbe90fa0d', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'The area of a rectangular garden 50 m long is 300 sq m. Find the breadth of the garden:', 'Breadth = Area ÷ Length = 300 ÷ 50 = 6 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3336e40b-73d1-487a-9eaf-7d3a91b2146b', '6 metres (Breadth = Area / Length = 300 / 50 = 6 m)', true, 'ecdc80fe-3d14-4530-a3b2-28bfbe90fa0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dde11da-a0f2-4a34-807f-31783f2035db', '10 metres', false, 'ecdc80fe-3d14-4530-a3b2-28bfbe90fa0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cf89060-2251-436c-aa66-257ea16720e3', '15 metres', false, 'ecdc80fe-3d14-4530-a3b2-28bfbe90fa0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92802e57-6108-4e7e-bfa8-9b0245e9fc4c', '8 metres', false, 'ecdc80fe-3d14-4530-a3b2-28bfbe90fa0d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a0b53c4-8b18-402d-8339-0f6aadcbaa91', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'A floor is 5 m long and 4 m wide. A square carpet of side 3 m is laid on the floor. Find the area of the floor that is NOT carpeted:', 'Total floor = 20 m²; Carpeted = 9 m²; Uncarpeted = 20 - 9 = 11 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed22e7a6-f12f-48a3-be73-6b0a27f149cd', '11 sq m (Floor Area = 5 × 4 = 20 m² ; Carpet Area = 3 × 3 = 9 m² ; Uncarpeted = 20 - 9 = 11 m²)', true, '4a0b53c4-8b18-402d-8339-0f6aadcbaa91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7256aa8a-7758-4f46-8de6-557b6537de50', '9 sq m', false, '4a0b53c4-8b18-402d-8339-0f6aadcbaa91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c3b2435-c432-41c3-8655-818da16cc8dc', '20 sq m', false, '4a0b53c4-8b18-402d-8339-0f6aadcbaa91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3da60e7e-201a-4087-a39e-bc9edd2e6a5b', '15 sq m', false, '4a0b53c4-8b18-402d-8339-0f6aadcbaa91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('481b2d2b-c411-4cca-9a2a-1d2fd6d9fd88', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'How many square tiles of side 10 cm will be needed to pave a rectangular bathroom floor of size 2 m by 1.5 m?', 'Floor = 200 × 150 = 30,000 cm². Tile = 100 cm². Number of tiles = 30,000 ÷ 100 = 300 tiles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('191729a2-6a6f-4fc1-8bfc-ae1bc70c9b84', '300 tiles (Floor = 200 cm × 150 cm = 30,000 cm² ; Tile = 10 × 10 = 100 cm² ; Tiles = 30,000 / 100 = 300)', true, '481b2d2b-c411-4cca-9a2a-1d2fd6d9fd88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bedd20d7-f072-4697-b7a8-68179c5ff059', '30 tiles', false, '481b2d2b-c411-4cca-9a2a-1d2fd6d9fd88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ef9cabb-0351-4f4e-8247-185f1d4ee79a', '150 tiles', false, '481b2d2b-c411-4cca-9a2a-1d2fd6d9fd88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a72f3302-5095-4390-91bb-638a48b8dabf', '3,000 tiles', false, '481b2d2b-c411-4cca-9a2a-1d2fd6d9fd88');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09921be7-9302-494d-972c-5dd6203b6c28', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Find the perimeter of a regular Octagon (8 equal sides) having side length 4.5 cm:', 'Perimeter = 8 × 4.5 = 36 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ac87ab3-44a8-44fb-a144-f77ee44b534c', '36 cm (8 × 4.5 = 36 cm)', true, '09921be7-9302-494d-972c-5dd6203b6c28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2b7043f-f7ee-44b0-a57f-9ccaf0dd8884', '32 cm', false, '09921be7-9302-494d-972c-5dd6203b6c28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa4c6461-97d5-4a81-8083-0cdb5c2de5ad', '40 cm', false, '09921be7-9302-494d-972c-5dd6203b6c28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf707899-221e-443e-af96-ace62247f146', '28 cm', false, '09921be7-9302-494d-972c-5dd6203b6c28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f016a0db-c762-4a92-9c41-50626a61c80e', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Two sides of a triangle are 12 cm and 14 cm. The perimeter of the triangle is 36 cm. What is the length of the third side?', 'Side 3 = Perimeter - (Side 1 + Side 2) = 36 - 26 = 10 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2cb10eb-77cd-43fe-b3d6-f96f5f99dd6e', '10 cm (Third side = 36 - (12 + 14) = 36 - 26 = 10 cm)', true, 'f016a0db-c762-4a92-9c41-50626a61c80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a176281e-e809-4d46-8a87-13a08bc6e458', '12 cm', false, 'f016a0db-c762-4a92-9c41-50626a61c80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08a19e42-7a95-4020-a252-2884aaccc2bf', '8 cm', false, 'f016a0db-c762-4a92-9c41-50626a61c80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c444a9d-dbb9-4d06-8e48-94403d228e0b', '11 cm', false, 'f016a0db-c762-4a92-9c41-50626a61c80e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1a9a823-06eb-4037-91a2-12e30885ed28', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Find the cost of leveling a rectangular playground of dimensions 70 m by 50 m at the rate of ₹5 per square metre:', 'Area = 70 × 50 = 3,500 m². Cost = 3,500 × 5 = ₹17,500.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f8ade10-9442-4058-a7e5-9fe9f8fcb378', '₹17,500 (Area = 70 × 50 = 3,500 m² ; Cost = 3,500 × 5 = ₹17,500)', true, 'd1a9a823-06eb-4037-91a2-12e30885ed28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dacbca7-8568-4f1c-8a93-dfcea919fbe1', '₹12,000', false, 'd1a9a823-06eb-4037-91a2-12e30885ed28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff831754-e75b-4ed7-8c16-aca996af1eec', '₹35,000', false, 'd1a9a823-06eb-4037-91a2-12e30885ed28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5175b4ae-3681-4018-ab74-d9db936a8382', '₹15,000', false, 'd1a9a823-06eb-4037-91a2-12e30885ed28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('858d1a85-8d5d-449d-b10b-2ba9dc88271f', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Sweety runs around a square park of side 75 m. Bulbul runs around a rectangular park of length 60 m and breadth 45 m. Who covers LESS distance and by how much?', 'Sweety perimeter = 300 m; Bulbul perimeter = 210 m. Bulbul covers 90 m less.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('884cfeb6-238c-4e0e-953d-ecf8772aec3e', 'Bulbul covers less distance by 90 metres (Sweety = 4 × 75 = 300 m ; Bulbul = 2 × (60 + 45) = 210 m ; Difference = 300 - 210 = 90 m)', true, '858d1a85-8d5d-449d-b10b-2ba9dc88271f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2870fe6f-b548-4fa7-8cc4-d297955362de', 'Sweety covers less distance by 90 m', false, '858d1a85-8d5d-449d-b10b-2ba9dc88271f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab89ba21-4ae0-4487-970c-63d622c61921', 'Both cover exactly the same distance', false, '858d1a85-8d5d-449d-b10b-2ba9dc88271f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('543870f4-5baf-47b4-8d43-b9940f427386', 'Bulbul covers less distance by 50 m', false, '858d1a85-8d5d-449d-b10b-2ba9dc88271f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa086c37-ddcc-47fd-a9f0-8dcebd80c4e1', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'How is the approximate area of an irregular closed shape estimated using standard 1 cm × 1 cm squared grid paper?', 'Standard grid approximation: full squares = 1, >half squares = 1, =half squares = 0.5, <half squares = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('551828d7-e734-4cb0-bf4c-a89633ed3c01', 'Count 1 sq unit for fully covered squares + ignore squares less than half covered + count 1 sq unit for squares more than half covered + count ½ sq unit for exactly half covered squares', true, 'fa086c37-ddcc-47fd-a9f0-8dcebd80c4e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdf011f1-92bc-44d5-b19e-42c5a84f7cd4', 'Only count full squares and throw away everything else', false, 'fa086c37-ddcc-47fd-a9f0-8dcebd80c4e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65cc8b62-47a5-4922-ad79-47161dcd5167', 'Multiply width by height directly', false, 'fa086c37-ddcc-47fd-a9f0-8dcebd80c4e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcbe61de-2152-4239-b905-d019dfaddafa', 'Weigh the paper on a balance', false, 'fa086c37-ddcc-47fd-a9f0-8dcebd80c4e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d76bbfaa-f245-4a4c-b93c-50c09403722f', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'What happens to the AREA of a square if its side length is DOUBLED (multiplied by 2)?', 'A_new = (2s)² = 4s² (area quadruples / 4 times).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0caffbb7-c01d-4c1d-972b-ef497c1f5409', 'The area becomes 4 TIMES the original area ((2s)² = 4s²)', true, 'd76bbfaa-f245-4a4c-b93c-50c09403722f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dabc05c-c0c8-405d-a5af-a8a0bdf4719d', 'The area doubles (2 times)', false, 'd76bbfaa-f245-4a4c-b93c-50c09403722f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('621d05e6-9dde-4922-9a43-b4d0cc96144a', 'The area triples (3 times)', false, 'd76bbfaa-f245-4a4c-b93c-50c09403722f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d006003-61d3-4b3e-9adb-0ff9b2fb2de5', 'The area remains unchanged', false, 'd76bbfaa-f245-4a4c-b93c-50c09403722f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74cf00eb-62f1-4d6d-a1e2-2c3b717bcf5e', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'What happens to the PERIMETER of a square if its side length is DOUBLED?', 'P_new = 4(2s) = 2(4s) = 2 × P_old (doubles).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('885105ad-4b29-42f8-ab79-9ce0fb3370f0', 'The perimeter is DOUBLED (2 times: 4 × (2s) = 2 × (4s))', true, '74cf00eb-62f1-4d6d-a1e2-2c3b717bcf5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7473f127-83fb-495d-b56b-2e5bc8afec76', 'The perimeter becomes 4 times', false, '74cf00eb-62f1-4d6d-a1e2-2c3b717bcf5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3cabc83-4725-4f62-aac7-ddb4fd77f06e', 'The perimeter remains the same', false, '74cf00eb-62f1-4d6d-a1e2-2c3b717bcf5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('486d240f-8e18-402e-b9db-b6316c2eac33', 'The perimeter halves', false, '74cf00eb-62f1-4d6d-a1e2-2c3b717bcf5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e907cfe-0fe5-45ff-8e0c-0edd582272b5', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Five square flower beds each of side 1 m are dug on a piece of rectangular land 5 m long and 4 m wide. What is the remaining area of the land?', 'Total area = 20 m²; 5 beds = 5 m²; Remaining = 20 - 5 = 15 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('167740a4-71e5-4dd2-ba28-ddb3a622a269', '15 sq m (Total Land = 5 × 4 = 20 m² ; Beds = 5 × (1 × 1) = 5 m² ; Remaining = 20 - 5 = 15 m²)', true, '1e907cfe-0fe5-45ff-8e0c-0edd582272b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d5388d5-97b8-4232-9e32-d6620b30ca95', '10 sq m', false, '1e907cfe-0fe5-45ff-8e0c-0edd582272b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0712edbd-7d26-467e-ac0e-cc1ff79f2fff', '19 sq m', false, '1e907cfe-0fe5-45ff-8e0c-0edd582272b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7428fb1-c653-48b5-991e-888cdbf0b951', '16 sq m', false, '1e907cfe-0fe5-45ff-8e0c-0edd582272b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eccbfa43-ab0e-4caa-bbad-81097c972313', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5e75ccd-e227-4b9b-bac0-15ab36882ce8', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'eccbfa43-ab0e-4caa-bbad-81097c972313');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1704d801-7973-4b35-ba84-b63d60eafabb', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'eccbfa43-ab0e-4caa-bbad-81097c972313');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fff9961d-b4fe-4fd4-8ea3-a230f9b333e4', '(A) is true, but (R) is false.', false, 'eccbfa43-ab0e-4caa-bbad-81097c972313');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26329804-f99b-48ed-bb99-edc48ac238d8', '(A) is false, but (R) is true.', false, 'eccbfa43-ab0e-4caa-bbad-81097c972313');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e031b2a-9d2b-4d9a-9c10-7f41882d162d', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Spot the IMPOSTER in the following polygon perimeters where each side length s = 6 cm:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2d3f419-9778-49da-ac41-fb93a2400475', 'Square (P = 24 cm)', false, '9e031b2a-9d2b-4d9a-9c10-7f41882d162d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d7e2c89-c965-46fd-baf8-2f72206c6c5e', 'Equilateral Triangle (P = 18 cm)', false, '9e031b2a-9d2b-4d9a-9c10-7f41882d162d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4359c62f-9805-4862-9152-dad4f42c8f40', 'Regular Hexagon (P = 36 cm)', false, '9e031b2a-9d2b-4d9a-9c10-7f41882d162d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc42b887-b872-4f94-a8cf-345e5a5f58c2', 'Regular Pentagon (P = 35 cm)', true, '9e031b2a-9d2b-4d9a-9c10-7f41882d162d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae00c9c4-4de5-4c36-a5f0-a655c56af03d', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'A rectangular hall of length 30 m and breadth 20 m is surrounded on all outer sides by a 2.5 m wide verandah. What is the total AREA of the verandah path alone?', 'Outer dims = (30 + 5) × (20 + 5) = 35 × 25 = 875 m²; Inner = 600 m²; Path = 875 - 600 = 275 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa340fe8-ce35-47fa-b33f-5953aa947577', '275 sq m (Outer length = 35 m, Outer breadth = 25 m ; Outer Area = 35 × 25 = 875 m² ; Inner Area = 30 × 20 = 600 m² ; Path Area = 875 - 600 = 275 m²)', true, 'ae00c9c4-4de5-4c36-a5f0-a655c56af03d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f1cde63-1c8f-4b4d-8a51-59ec6fa7f544', '250 sq m', false, 'ae00c9c4-4de5-4c36-a5f0-a655c56af03d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90120c60-262c-4bcc-82dd-c204669f4b3b', '300 sq m', false, 'ae00c9c4-4de5-4c36-a5f0-a655c56af03d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09b3e0b5-63f2-4561-8730-902f23b3f25c', '150 sq m', false, 'ae00c9c4-4de5-4c36-a5f0-a655c56af03d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50881d54-c01b-4f06-a88b-055561c5f379', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Match Column I (Geometric Figures) with Column II (Perimeter / Area Formulas):
(a) Square Area              -> (i) 2(l + b)
(b) Rectangle Perimeter      -> (ii) s²
(c) Equilateral Triangle P   -> (iii) l × b
(d) Rectangle Area           -> (iv) 3s', 'Square Area = s²; Rectangle P = 2(l+b); Triangle P = 3s; Rectangle Area = l×b.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54c1738a-046a-4787-8b73-ed3276c1e58c', 'a-(ii), b-(i), c-(iv), d-(iii)', true, '50881d54-c01b-4f06-a88b-055561c5f379');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70813790-8591-4e34-8aa0-c434eaf77e61', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '50881d54-c01b-4f06-a88b-055561c5f379');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('726eae29-6d03-450c-a9d4-4239dc015c21', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '50881d54-c01b-4f06-a88b-055561c5f379');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09610787-26e5-4ada-b34a-ce64756e17cd', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '50881d54-c01b-4f06-a88b-055561c5f379');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c4ce68a-f344-423b-b6f9-fad0098b3891', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Read the statements regarding geometric measures:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce5e9781-4005-40d6-9dfd-e2268a8ef107', 'Statements 1 and 2 only', true, '6c4ce68a-f344-423b-b6f9-fad0098b3891');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cfd185f-0747-4e1f-a6ee-e6670539af9c', 'Statements 2 and 3 only', false, '6c4ce68a-f344-423b-b6f9-fad0098b3891');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57c6e7e1-df7a-4919-b981-dbe5aa43fd36', 'Statements 1 and 3 only', false, '6c4ce68a-f344-423b-b6f9-fad0098b3891');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4ce158c-d3c9-4f65-9619-72c75297165c', 'All Statements 1, 2, and 3', false, '6c4ce68a-f344-423b-b6f9-fad0098b3891');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0b72b99-d31f-4c13-bc2f-3c3a1f120990', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'A wire in the shape of a Rectangle of dimensions 18 cm by 10 cm is cut, straightened, and rebent into a Square. What will be the area of this new Square?', 'Perimeter = 2(18 + 10) = 56 cm. Square side = 56/4 = 14 cm. Square area = 14² = 196 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6492271a-2af4-4932-a727-6ddc36a40063', '196 sq cm (Perimeter = 2(18 + 10) = 56 cm ; Square side = 56/4 = 14 cm ; Area = 14 × 14 = 196 cm²)', true, 'b0b72b99-d31f-4c13-bc2f-3c3a1f120990');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('831da970-a3de-44ab-98a6-9362bd67dfe1', '180 sq cm', false, 'b0b72b99-d31f-4c13-bc2f-3c3a1f120990');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fedabbe-fffd-4b60-8f41-f6cbc1e86cb1', '144 sq cm', false, 'b0b72b99-d31f-4c13-bc2f-3c3a1f120990');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7db8ba4-22ad-4b8a-a293-cccc0663af42', '256 sq cm', false, 'b0b72b99-d31f-4c13-bc2f-3c3a1f120990');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('857d0f5f-afeb-4f15-8ae5-5ac67f59073a', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Find the total perimeter of an L-shaped polygon with side lengths: bottom = 10 cm, left vertical = 8 cm, top horizontal = 4 cm, inner vertical = 5 cm, inner horizontal = 6 cm, right vertical = 3 cm:', 'Summing all 6 contiguous boundary edges: 10 + 8 + 4 + 5 + 6 + 3 = 36 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52b8e0a1-3b6a-4960-8943-a722f559fb79', '36 cm (10 + 8 + 4 + 5 + 6 + 3 = 36 cm)', true, '857d0f5f-afeb-4f15-8ae5-5ac67f59073a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('982dbf3d-3da7-4788-80df-406688b62990', '32 cm', false, '857d0f5f-afeb-4f15-8ae5-5ac67f59073a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0e261cd-2775-4985-823b-d2bc2cfae2b5', '40 cm', false, '857d0f5f-afeb-4f15-8ae5-5ac67f59073a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f1ddc8a-db19-478d-9d91-2bb9dc2efd0c', '28 cm', false, '857d0f5f-afeb-4f15-8ae5-5ac67f59073a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16a60a0c-71d6-4f14-b867-712fffb331fc', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'A rectangular lawn of length 60 m and breadth 40 m has two crossroads each 2 m wide running at right angles through its center parallel to its sides. What is the area of the crossroads?', 'Area of crossroads = (60 × 2) + (40 × 2) - (2 × 2) = 120 + 80 - 4 = 196 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc61a77b-c46d-425a-8b9a-65627483253c', '196 sq m (Road 1 = 60 × 2 = 120 m² ; Road 2 = 40 × 2 = 80 m² ; Center overlap = 2 × 2 = 4 m² ; Net Area = 120 + 80 - 4 = 196 m²)', true, '16a60a0c-71d6-4f14-b867-712fffb331fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86cb36b6-f370-450a-b589-12f98ee7eff5', '200 sq m', false, '16a60a0c-71d6-4f14-b867-712fffb331fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('187a76f7-9f40-4fed-90aa-91ab311f82e9', '192 sq m', false, '16a60a0c-71d6-4f14-b867-712fffb331fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf108371-9c9b-4f53-9f45-acdb00f8a168', '204 sq m', false, '16a60a0c-71d6-4f14-b867-712fffb331fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a46f756-93b9-4f82-88c4-0a1819bf2694', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'If 1 hectare = 10,000 square metres, how many hectares is a rectangular agricultural farm of length 500 m and breadth 200 m?', 'Area = 500 × 200 = 100,000 m² ÷ 10,000 m²/ha = 10 hectares.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cddc284e-8786-4923-9eb6-7c9f5a4941b9', '10 hectares (Area = 500 × 200 = 100,000 m² ; Hectares = 100,000 / 10,000 = 10)', true, '1a46f756-93b9-4f82-88c4-0a1819bf2694');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('462c29fe-1d1d-4e17-81d6-bfe902d0c3a5', '5 hectares', false, '1a46f756-93b9-4f82-88c4-0a1819bf2694');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a5b6dcc-5f9b-4aff-a570-e9db8d4070f2', '20 hectares', false, '1a46f756-93b9-4f82-88c4-0a1819bf2694');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('491b4365-0ffb-4c85-a7a0-3900f8e05141', '100 hectares', false, '1a46f756-93b9-4f82-88c4-0a1819bf2694');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4aa663e9-4448-4dc1-86b1-922ddf6c2750', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'A square park of side 60 m has a walking path of uniform width 3 m constructed INSIDE along its boundary. What is the area of this internal path?', 'Outer = 3600 m²; Inner = (60-6)² = 54² = 2916 m²; Path = 3600 - 2916 = 684 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cbdecf1-4e00-4109-ab3b-4d070fc9544b', '684 sq m (Outer Area = 60 × 60 = 3600 m² ; Inner side = 60 - 6 = 54 m ; Inner Area = 54 × 54 = 2916 m² ; Path = 3600 - 2916 = 684 m²)', true, '4aa663e9-4448-4dc1-86b1-922ddf6c2750');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33ba3df5-4b61-4d09-b7e1-ddf913fd3843', '720 sq m', false, '4aa663e9-4448-4dc1-86b1-922ddf6c2750');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a698fe5-dcca-45d9-a162-8f94398380e8', '600 sq m', false, '4aa663e9-4448-4dc1-86b1-922ddf6c2750');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59d615c2-e293-4935-9b76-d3780b30b0df', '648 sq m', false, '4aa663e9-4448-4dc1-86b1-922ddf6c2750');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d30bee10-c9e4-4caf-982f-2facce03a3c5', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'If the length of a rectangle is increased by 50% and its breadth is decreased by 20%, what is the percentage change in its area?', 'New Area = 1.50 × 0.80 = 1.20 × Original Area (+20% increase).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e665815b-63f2-4c7c-9494-e9ea08c1fe06', 'Increases by 20% (A_new = (1.5 l) × (0.8 b) = 1.20 (l × b) -> 20% increase)', true, 'd30bee10-c9e4-4caf-982f-2facce03a3c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c233b6a2-1337-4b74-bac1-1e1a91ae4f05', 'Increases by 30%', false, 'd30bee10-c9e4-4caf-982f-2facce03a3c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc18a9b0-3295-4fd9-9f24-b19675b2617a', 'Decreases by 10%', false, 'd30bee10-c9e4-4caf-982f-2facce03a3c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a58d51f-3e53-4168-9f9d-4c06dac86e6a', 'Remains unchanged', false, 'd30bee10-c9e4-4caf-982f-2facce03a3c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72bf81cf-e901-4824-989e-10ceb88a7c4e', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Why is the study of Mensuration (perimeter and area) essential in architectural engineering and real-world civil planning?', 'Mensuration provides foundational geometric formulas for structural material estimation, cost budgeting, and land surveying.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('944d1ddc-43bf-45e7-a569-7c89d19f6cbf', 'It enables precise material quantification, budget estimation for construction, land cadastral mapping, and cost calculation for tiling, painting, and fencing', true, '72bf81cf-e901-4824-989e-10ceb88a7c4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cfed24e-7946-46a0-bab8-17fc1ca7a087', 'Because numbers make buildings stronger by magic', false, '72bf81cf-e901-4824-989e-10ceb88a7c4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('412c9d2e-5666-44ec-91f1-f4a97d7e31ae', 'To prevent land from moving', false, '72bf81cf-e901-4824-989e-10ceb88a7c4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c23cfab9-7d43-43b3-8eba-b9f10e63836b', 'Because rulers only measure area', false, '72bf81cf-e901-4824-989e-10ceb88a7c4e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('893b6600-eb54-4050-83ac-071bd767ae3b', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'Who is the world-renowned Indian author who wrote the autobiographical nature story ''The Banyan Tree''?', 'Ruskin Bond penned ''The Banyan Tree'', describing his childhood natural explorations in his grandfather''s garden in Dehradun.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('678fff9e-769d-4077-941c-51a3b1d7f5e0', 'Ruskin Bond', true, '893b6600-eb54-4050-83ac-071bd767ae3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fb4a0e8-5e52-4070-b68b-aca976bc182c', 'R.K. Narayan', false, '893b6600-eb54-4050-83ac-071bd767ae3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2af1574a-ee70-4c70-921e-12d2b6a37e22', 'Mulk Raj Anand', false, '893b6600-eb54-4050-83ac-071bd767ae3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fab1575-721f-4fae-a76b-81b116b45c85', 'Vikram Seth', false, '893b6600-eb54-4050-83ac-071bd767ae3b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd0c5cc7-d0e0-4b90-9201-232def6f0a52', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'Why did the young boy (narrator) claim that the magnificent old banyan tree belonged exclusively to HIM rather than his grandfather?', 'Grandfather at sixty-five had lost the agility to climb, making the sprawling banyan the young boy''s private leafy kingdom.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de3b518d-164d-4712-8070-0d38bc2213c4', 'Because his sixty-five-year-old grandfather was too old to climb trees anymore', true, 'cd0c5cc7-d0e0-4b90-9201-232def6f0a52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae60cc89-6d4a-4543-9e65-a769706e9854', 'Because the boy bought the tree with pocket money', false, 'cd0c5cc7-d0e0-4b90-9201-232def6f0a52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7da243fd-4a94-4b84-8ff9-028929bfe42c', 'Because the tree was planted by the boy', false, 'cd0c5cc7-d0e0-4b90-9201-232def6f0a52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e69c6ad0-2bbb-46bc-b9c8-6448118c5ef5', 'Because grandfather hated trees', false, 'cd0c5cc7-d0e0-4b90-9201-232def6f0a52');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f62c256-ce51-4d83-b6ca-2aabd69ef330', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'Which small creature in the banyan tree became the narrator''s first bold friend, even eating pieces of cake and biscuits out of his hand?', 'A young grey squirrel shed its initial fear when it found the boy carried no catapult, soon eating crumbs from his hand.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b61d5315-08d2-406e-bf14-52aa1f838d81', 'A small grey Squirrel', true, '9f62c256-ce51-4d83-b6ca-2aabd69ef330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25a718b5-f9e3-40f5-a787-e23a2dc2d9f7', 'A green parrot', false, '9f62c256-ce51-4d83-b6ca-2aabd69ef330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fffc71e4-97f8-4af7-a933-974410e162b9', 'A white rabbit', false, '9f62c256-ce51-4d83-b6ca-2aabd69ef330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1207396f-80ee-4f59-9e9b-ae7ce2c9d264', 'A chameleon', false, '9f62c256-ce51-4d83-b6ca-2aabd69ef330');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78d8e62f-786a-42ed-9291-7c849b39a69a', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What did the boy build halfway up the banyan tree so he could spend hot afternoons reading adventure books?', 'The boy built a makeshift treehouse platform among the leafy branches, reading ''Treasure Island'' and ''Robinson Crusoe''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e54847e-fade-471e-9e5b-993cb3280083', 'A crude wooden platform with cushions', true, '78d8e62f-786a-42ed-9291-7c849b39a69a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21bb66d6-bb97-46ff-a3e9-802906ca922b', 'A stone castle', false, '78d8e62f-786a-42ed-9291-7c849b39a69a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35c3030a-f4fb-4070-8efd-12292a276585', 'A glass house', false, '78d8e62f-786a-42ed-9291-7c849b39a69a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ef2b10d-732e-44a4-ab2f-a41f88ff1279', 'An iron cage', false, '78d8e62f-786a-42ed-9291-7c849b39a69a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ca7b27c-9781-453b-90dd-c4313c835ff4', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What dramatic classic battle of nature did the boy witness from his banyan tree platform on a drowsy summer afternoon?', 'The boy witnessed the primordial duel between a 6-foot venomous black cobra and an agile 3-foot mongoose.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('577c8d3b-fe49-4d7f-8c3c-cbb2cf675b67', 'A deadly fight between a huge black Cobra and a nimble grey Mongoose', true, '0ca7b27c-9781-453b-90dd-c4313c835ff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb6d4ebf-096a-47ae-94d5-2af1fd3b5791', 'A fight between a tiger and an elephant', false, '0ca7b27c-9781-453b-90dd-c4313c835ff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('603f7f98-0933-4bd1-a40e-5379ee544df2', 'A race between two horses', false, '0ca7b27c-9781-453b-90dd-c4313c835ff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e82b9da-b03b-4fb7-ac3a-d1c716311820', 'A battle between eagles', false, '0ca7b27c-9781-453b-90dd-c4313c835ff4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e4d9ce4-2939-4583-b60a-32cb80d7d7c8', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What two bird spectators perched on a nearby cactus bush to watch the cobra-mongoose fight?', 'A jungle crow and a myna sat on a prickly cactus bush, acting as eager onlookers and attempting to dive into the fight.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b7030c4-de8f-411b-ae84-68501b8b1bf8', 'A Crow and a Myna', true, '2e4d9ce4-2939-4583-b60a-32cb80d7d7c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d6bfffa-0747-468b-9a5d-635df45543ba', 'An Eagle and a Hawk', false, '2e4d9ce4-2939-4583-b60a-32cb80d7d7c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df475a95-61de-4ffc-9454-a7b879932d8a', 'A Parrot and a Pigeon', false, '2e4d9ce4-2939-4583-b60a-32cb80d7d7c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('122672b1-91db-4800-abb2-0203e6f2e229', 'A Peacock and a Sparrow', false, '2e4d9ce4-2939-4583-b60a-32cb80d7d7c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6582763-4090-4550-af06-17b772b1a4e8', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What happened to the foolish Crow when it persistently dived at the cobra during the battle?', 'On its third reckless dive, the cobra countered with a lightning strike, fatally colliding with the crow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d9ed7b0-88a1-4358-b96c-64f412ad6bbc', 'The cobra whipped its head back with lightning speed and struck the crow with its snout, flinging it dead onto the garden path', true, 'd6582763-4090-4550-af06-17b772b1a4e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5a02e18-fd5f-48d2-8bbd-bcfc2dfb1ccf', 'The crow flew away with the cobra', false, 'd6582763-4090-4550-af06-17b772b1a4e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7792ba4a-35a2-499d-a163-d9c9bd467a34', 'The crow won the fight', false, 'd6582763-4090-4550-af06-17b772b1a4e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ffc2b48-2b45-4d67-8588-f2de4f04df11', 'The myna saved the crow', false, 'd6582763-4090-4550-af06-17b772b1a4e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87c34095-ea31-4232-8b4b-18683ad5cf16', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'Who emerged VICTORIOUS in the epic duel beneath the banyan tree?', 'The mongoose exhausted the cobra with lightning feints, bit through its spine, and dragged its carcass into the bushes.', NOW()) ON CONFLICT DO NOTHING;
