INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10cbc0ed-7d4e-4397-a39a-555268ca3f59', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What was Vijay Singh''s boastful claim that led him to travel to the Haunted Deserts?', 'In an unguarded moment of bravado, Vijay Singh declared his desire to meet and thrash a ghost in the Haunted Desert.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49a527b5-4a00-42c8-90d6-f320faa91ca6', 'That he was not afraid of any ghost and wished to meet a real ghost to teach him a wrestling lesson', true, '10cbc0ed-7d4e-4397-a39a-555268ca3f59');
