INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce17f740-76c5-4b67-81be-8535ebd9edbc', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What two seemingly bizarre gifts did the eccentric old woman in the village give Vijay Singh in a packet before his departure?', 'The old woman handed him a small bag containing an ordinary raw egg and a lump of rock salt.', NOW()) ON CONFLICT DO NOTHING;
