INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15104211-b4fc-483c-8da8-85de49027966', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'Who was Natwar in ''A Strange Wrestling Match''?', 'Natwar was the ghost of the Haunted Desert who lured travelers to their doom until he met Vijay Singh.', NOW()) ON CONFLICT DO NOTHING;
