INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('235c7a70-a311-455d-b24a-8d897ed884e5', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'How did Vijay Singh trick the ghost Natwar into believing that he possessed superhuman physical strength by squeezing a rock?', 'Vijay Singh''s sleight of hand substituted the egg; crushing it fooled the naive ghost into believing he squeezed liquid from rock.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73105c0c-fb55-4f1e-870e-58d5853ba614', 'Vijay Singh secretly slipped the raw egg into his palm alongside a rock, squeezed hard until yellow yolk oozed out, making the ghost think he crushed stone into liquid', true, '235c7a70-a311-455d-b24a-8d897ed884e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13e4efc6-cbda-4d35-95f6-7aaff7519d6f', 'He broke the rock with a hammer', false, '235c7a70-a311-455d-b24a-8d897ed884e5');
