INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('571b161e-f7b9-41bf-9498-32b2e4b19ca6', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'How did Vijay Singh trick the ghost a second time using the lump of salt?', 'Vijay Singh pulverized the brittle rock salt lump in his grip, convincing the terrified ghost he had turned stone into salt powder.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d401e771-5180-448e-af06-c72b1fdd8747', 'He handed the ghost another stone containing the salt lump, crushed the salt into fine powder in darkness, and made the ghost taste the salty stone dust', true, '571b161e-f7b9-41bf-9498-32b2e4b19ca6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb1544c2-d60e-457e-95f0-e434a863266d', 'He threw salt into the ghost''s eyes', false, '571b161e-f7b9-41bf-9498-32b2e4b19ca6');
