INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f0c9873-a77c-474c-8e0e-1a41078e4f55', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'How did Vijay Singh outwit the ghost''s nocturnal assassination attempt inside the ghost''s cave?', 'Vijay Singh rolled a bolster under his blanket; the ghost battered the pillow with a club thinking he had killed the wrestler.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4af9c91b-f229-4609-96a6-09be142ff516', 'Vijay Singh slipped out of bed, placed a bolster/pillow under the blanket to resemble a sleeping body, and hid in the corner while the ghost struck the bed seven times with a stout club', true, '9f0c9873-a77c-474c-8e0e-1a41078e4f55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e978928-5ada-49d6-bc14-f9652597ba18', 'He tied the ghost to a tree', false, '9f0c9873-a77c-474c-8e0e-1a41078e4f55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3f7ca17-84bc-4da7-b90f-2c648cef66a9', 'He stayed awake with a sword', false, '9f0c9873-a77c-474c-8e0e-1a41078e4f55');
