INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94fa8bcf-c67a-4146-8238-5a3d80d483b9', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'What witty psychological remark did Vijay Singh make to the terrified ghost the next morning after the clubbing incident?', 'By dismissing seven crushing club blows as mere ''insect wing flaps'', Vijay Singh utterly demoralized the terrified ghost.', NOW()) ON CONFLICT DO NOTHING;
