INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56778e23-4448-41a8-9a93-984b506b3a91', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'What was the final outcome of Vijay Singh''s encounter with the ghost in the Haunted Desert?', 'The ghost abandoned the desert; Vijay Singh restored stolen treasures to rightful owners and renounced boastful pride.', NOW()) ON CONFLICT DO NOTHING;
