INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9937b02-f9b0-4eb0-bdc1-a7aa1ff28c34', 'Vijay Singh became the new ghost', false, '56778e23-4448-41a8-9a93-984b506b3a91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f25dc1b-68f3-4af6-a767-02fd03cca76e', 'They became wrestling partners', false, '56778e23-4448-41a8-9a93-984b506b3a91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c878923e-21ff-4a03-81b0-50e5286539d3', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'Why did the Myna fly away safely while the Crow died in ''The Banyan Tree''?', 'The myna exercised prudent caution, declining to intervene in a battle between lethal apex specialists.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c70da61-68ff-4826-9623-2736798c5e31', 'The Myna learned from the crow''s fatal mistake, wisely stayed perched on the cactus bush, and merely congratulated the victor with a shrill cry', true, 'c878923e-21ff-4a03-81b0-50e5286539d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23eda71d-01ce-4b2a-ba3a-0c4a97304295', 'Because the myna was faster than light', false, 'c878923e-21ff-4a03-81b0-50e5286539d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58013448-0aa3-4a6a-a002-58de6d10a301', 'Because the cobra was afraid of mynas', false, 'c878923e-21ff-4a03-81b0-50e5286539d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f0b79a2-2302-498e-a5ca-bdc16d432562', 'Because the boy caught the myna', false, 'c878923e-21ff-4a03-81b0-50e5286539d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12b80ae5-c047-469b-8d0e-006f98d32403', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'What special physiological defense does the Mongoose deploy during its combat with the cobra?', 'Bristling piloerection creates a defensive fur shield while maximizing optical intimidation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9d72fd7-616b-41e5-9f22-804e30d19bb4', 'Its thick bushy tail and bristled hair make it look twice as large and absorb grazing strikes, while its rapid footwork allows instant dodging', true, '12b80ae5-c047-469b-8d0e-006f98d32403');
