INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61dddd2b-bff5-4ea8-b872-9273f46ee71f', 'It burrows underground instantly', false, '12b80ae5-c047-469b-8d0e-006f98d32403');
