INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab4c2564-f916-4602-b5be-cff096536751', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'What does the word ''Catapult'' (slingshot) refer to in Ruskin Bond''s story?', 'A catapult is a handheld slingshot; the squirrel trusted the boy because he carried no hostile weapons.', NOW()) ON CONFLICT DO NOTHING;
