INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa95a998-6d6b-4709-9f65-799ca59976e0', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'What white, miraculous creatures were discovered inside the nest in the banyan tree after the squirrel mated with a pet white rat?', 'In an astonishing cross-species hybrid episode, grandfather found three tiny albino white baby squirrels.', NOW()) ON CONFLICT DO NOTHING;
