INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a36bc36-4030-4dd3-a5c3-0824808a2a13', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'What does the phrase ''to take the wind out of someone''s sails'' mean when Vijay Singh confronted the ghost?', 'Vijay Singh''s fearless assertiveness disarmed the ghost, deflating his supernatural intimidation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a023483-3a2b-4011-af9c-353ecaa3f327', 'To suddenly destroy someone''s confidence, pride, or advantage by doing or saying something unexpected', true, '5a36bc36-4030-4dd3-a5c3-0824808a2a13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb5a42b3-c699-4b24-9ee3-49b04bc38c11', 'To stop a sailing ship', false, '5a36bc36-4030-4dd3-a5c3-0824808a2a13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e69f9d7b-9ce9-499e-9353-9aa918430750', 'To blow a storm with one''s breath', false, '5a36bc36-4030-4dd3-a5c3-0824808a2a13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b35565d-cf95-490f-8fdc-d8b988748610', 'To run out of air', false, '5a36bc36-4030-4dd3-a5c3-0824808a2a13');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('231812bf-24ad-40ec-bb1c-1afa017534e9', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'Why was the banyan tree described as ''older than the house, older than grandfather, as old as Dehra Dun itself''?', 'Bond captures the ancient, sprawling majesty of the giant Ficus benghalensis anchoring the valley''s history.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1bfcd76-5eb3-4594-8e61-e360eaa09a99', 'To emphasize the immense majestic age, vast spreading root branches, and timeless ecological heritage of the tree', true, '231812bf-24ad-40ec-bb1c-1afa017534e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15113a4a-e522-478f-9c6d-05c1a80dab2b', 'Because the tree was built of stone', false, '231812bf-24ad-40ec-bb1c-1afa017534e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ee625fb-6c78-472e-aff2-43b73f05d83c', 'Because grandfather built the tree', false, '231812bf-24ad-40ec-bb1c-1afa017534e9');
