INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc25e18c-f4d1-45bc-bde2-852ef956209c', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'What classic folktale moral is demonstrated by Vijay Singh''s victory over the supernatural ghost?', 'Sharp intellect, psychological fortitude, and quick wit triumph over brute force and supernatural fear.', NOW()) ON CONFLICT DO NOTHING;
