INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55a6d519-98c8-4af4-8476-1f97a67fcbf0', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'Why did the cobra raise three of its six feet off the ground and spread its broad, spectacled hood?', 'The elevated hood posture maximizes visual threat display and provides mechanical leverage for downward strikes.', NOW()) ON CONFLICT DO NOTHING;
