INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aea20b6f-0d0e-4d3c-9910-ec3f1cbc96d6', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'In ''The Banyan Tree'', how did the boy feel while sitting quietly in the banyan tree during spring?', 'Bond captures the sublime romantic communion between a sensitive child observer and the vibrant natural world.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5050fba0-94d9-4d8a-9d8b-d14be6a7ccbe', 'He felt a profound, intimate kinship with nature, surrounded by chirping birds, buzzing bees, and red figs', true, 'aea20b6f-0d0e-4d3c-9910-ec3f1cbc96d6');
