INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c7fce8b-8c72-40da-8f4f-14c0f3961e9c', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'Analyze how Vijay Singh''s boastfulness in the opening of the story represents a classic folkloric character arc:', 'The classic moral arc moves from hubristic vulnerability to intellectual realization and moral humility.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fa232e8-820d-47d4-8eba-c761fabf56bf', 'His hubristic flaw (vanity and bragging) leads him into mortal peril, which he survives through razor-sharp wit, emerging thoroughly humbled and wiser', true, '3c7fce8b-8c72-40da-8f4f-14c0f3961e9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1e22832-3848-4d55-8105-4181d6af8c4f', 'He becomes a magical wizard', false, '3c7fce8b-8c72-40da-8f4f-14c0f3961e9c');
