INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0842f95-2521-4537-adc6-4e317abd21b5', 'He joins the ghosts in haunting deserts', false, '3c7fce8b-8c72-40da-8f4f-14c0f3961e9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a17b9ba-7d30-4864-9807-e6da6c772519', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'Match Column I (Characters / Items) with Column II (Roles in Chapter 10):
(a) Ruskin Bond    -> (i) Young boy observing nature from banyan tree platform
(b) Grey Mongoose   -> (ii) Agile victor of the epic garden duel
(c) Raw Egg & Salt  -> (iii) Improvised psychological props used to trick the ghost
(d) Bolster / Pillow-> (iv) Decoy used under blanket to survive midnight clubbing', 'Bond = narrator; Mongoose = victor; Egg/Salt = psychological props; Bolster = bed decoy.', NOW()) ON CONFLICT DO NOTHING;
