INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35ea35cd-5a49-4b77-8c3c-8af201169eae', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'What is the grammatical classification of the underlined participle in: ''The boy sat on the branch, *watching* the fierce duel.''?', '''Watching'' is a Present Participle forming an adverbial/adjectival participial phrase qualifying the subject.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba549478-eb94-4cf9-86b0-b8695a5e9a82', 'Present Participle functioning as a Participial Phrase modifying the subject ''The boy''', true, '35ea35cd-5a49-4b77-8c3c-8af201169eae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35229214-ac5d-40b5-8359-b3ccf5d3f4de', 'Gerund noun', false, '35ea35cd-5a49-4b77-8c3c-8af201169eae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eccf51e-2526-41b7-a613-63cd2137f167', 'Finite past verb', false, '35ea35cd-5a49-4b77-8c3c-8af201169eae');
