INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cdfa9ce0-4287-4b8a-ba87-6fc79ecfec9e', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'Why does Ruskin Bond describe the banyan tree as an ''unrivalled sanctuary'' for bird and animal life in summer?', 'Keystone ecological status: Ficus benghalensis provides perennial shade, thermal microclimates, and massive fig fruit yields.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67359bf2-9c7b-42e5-92aa-438d29517b17', 'Its massive dense canopy provided cool shade, abundant red fig fruits for birds (parrots, bulbuls, mynas), and sheltering hollows for squirrels and insects', true, 'cdfa9ce0-4287-4b8a-ba87-6fc79ecfec9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e14f5555-e98b-42f6-a951-105a9b517196', 'Because humans were banned from entering', false, 'cdfa9ce0-4287-4b8a-ba87-6fc79ecfec9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fae4f4a1-8826-4651-a667-36833987f379', 'Because it had iron gates', false, 'cdfa9ce0-4287-4b8a-ba87-6fc79ecfec9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e71a716b-abb3-443e-8ab4-f3ea3820ea0a', 'Because it grew in a zoo', false, 'cdfa9ce0-4287-4b8a-ba87-6fc79ecfec9e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78caa2f6-19ca-4909-aadc-6d215fdd7aeb', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'What psychological technique did Vijay Singh employ when he told the ghost: ''You are no ghost, but an ordinary imposter!''?', 'Cognitive subversion: aggressively stripping the adversary of supernatural mystique destabilized the ghost''s confidence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4526bac-7908-4191-be8d-8d5807a939b4', 'Reverse psychological intimidation to shatter the ghost''s belief in its own terrifying supernatural supremacy', true, '78caa2f6-19ca-4909-aadc-6d215fdd7aeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d516bae0-e502-4bd1-a25a-124d6c10e7a8', 'He wanted to become friends', false, '78caa2f6-19ca-4909-aadc-6d215fdd7aeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('460215f6-6ad9-4c2c-aab4-c01cf6d006a4', 'He was reciting a poem', false, '78caa2f6-19ca-4909-aadc-6d215fdd7aeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('484f9597-c5c3-4c2e-bc2c-9f4a3687919c', 'He forgot who he was talking to', false, '78caa2f6-19ca-4909-aadc-6d215fdd7aeb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02cddb34-9ab8-4131-b0c1-82f4aa1c8875', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'What is the meaning of the archaic/idiomatic term ''haunted'' in folklore?', '''Haunted'' denotes supernatural occupancy by phantoms and spectral disturbances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c24cf2a6-3590-4be9-8ca6-81049ec18df7', 'A location persistently visited or inhabited by spectral ghosts, spirits, or lingering dread', true, '02cddb34-9ab8-4131-b0c1-82f4aa1c8875');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('478d7741-6e0c-47ed-86b4-abc1c40290ba', 'A place with high trees', false, '02cddb34-9ab8-4131-b0c1-82f4aa1c8875');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6442248-8af9-40db-b30b-bc33ed8bd794', 'A dry water well', false, '02cddb34-9ab8-4131-b0c1-82f4aa1c8875');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3120c30-5ab9-4239-9f26-1d0ca9fb62ce', 'A noisy marketplace', false, '02cddb34-9ab8-4131-b0c1-82f4aa1c8875');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96cedfd1-0531-48c4-8904-f29af0057c0a', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'Why did the grandfather refuse to allow the narrator to kill or disturb the mongoose in the garden?', 'Ecological balance: mongooses provide indispensable non-chemical apex protection against lethal viperids and elapids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85e9aad8-5406-4805-ba23-283ee2c218ca', 'Grandfather recognized that mongooses are natural, invaluable biological protectors that keep residential gardens free from lethal venomous snakes', true, '96cedfd1-0531-48c4-8904-f29af0057c0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df44dc8c-146b-445c-845d-1bce1deeb209', 'Because the mongoose was made of gold', false, '96cedfd1-0531-48c4-8904-f29af0057c0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50a3bc89-e450-48cb-b2f7-2170a69b67a0', 'Because grandfather was afraid of the mongoose', false, '96cedfd1-0531-48c4-8904-f29af0057c0a');
