INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecc6c888-6964-448d-84a5-e585d97a8b74', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'What overarching humanist and ecological worldview defines the conclusion of the NCERT Class 6 English curriculum?', 'The curriculum culminates in ecological mindfulness, reverence for nature''s biodiversity, and emotional maturity.', NOW()) ON CONFLICT DO NOTHING;
