INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48873921-700f-4d16-b12a-17ec5a402621', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Easy', 'What are ''Pilgrims'' in historical religious studies?', 'Pilgrims travel across continents on spiritual journeys to pay homage at sacred shrines and monasteries.', NOW()) ON CONFLICT DO NOTHING;
