INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e7281b2-8458-42f3-b920-b92bb7833783', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Easy', 'Which famous Chinese Buddhist pilgrim visited India around 1600 years ago during the reign of Chandragupta II (Gupta Empire)?', 'Fa Xian traveled to India (399–414 CE) overland through Central Asia, collecting Sanskrit Buddhist Vinaya manuscripts.', NOW()) ON CONFLICT DO NOTHING;
