INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('642f9d95-62bc-4802-860d-a4f8c30c90ab', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Easy', 'Which Chinese pilgrim visited India around 1400 years ago during the reign of King Harshavardhana and studied at Nalanda University?', 'Xuan Zang spent 16 years in India (629–645 CE), studying Yogachara philosophy under Shilabhadra at Nalanda.', NOW()) ON CONFLICT DO NOTHING;
