INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('afb7dbb7-b11e-4205-8adb-7d509b7e1717', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Easy', 'What was the most famous international center of Buddhist learning and monastery university in ancient Bihar where scholars from all over the world studied?', 'Founded in the 5th century CE by Kumargupta I, Nalanda hosted over 10,000 students and monks from across Asia.', NOW()) ON CONFLICT DO NOTHING;
