INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93b9700f-b462-4c4c-9c97-4eaf1d884dd5', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'Why did ancient kings try hard to control the Silk Route?', 'Controlling choke points allowed kingdoms to levy transit tolls, ensuring armed security in exchange for tariffs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88c707e7-d72b-45f5-b0cd-8871f9c45dc7', 'Because they could collect rich taxes, customs duties, and precious gifts from wealthy merchants traveling with valuable goods along the route', true, '93b9700f-b462-4c4c-9c97-4eaf1d884dd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e517640-64a0-454c-b999-ff54769fcb74', 'Because kings wanted to make silk shirts themselves', false, '93b9700f-b462-4c4c-9c97-4eaf1d884dd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5face5e-254d-4fcf-9967-14e7bfe5971f', 'Because the route was made of gold', false, '93b9700f-b462-4c4c-9c97-4eaf1d884dd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c523fbb-99b7-4295-9460-bb9a784d2877', 'Because nobody else was allowed on the road', false, '93b9700f-b462-4c4c-9c97-4eaf1d884dd5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93a488bf-ebc9-4813-9555-eaa3b8f4ba62', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What two major sculptural art schools produced exquisite Buddha statues under Mahayana Buddhism?', 'Gandhara fused Hellenistic drapery with Buddhist themes, while Mathura evolved robust indigenous stone iconography.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48dc9102-6b5f-4171-ae77-9349f1359642', 'Mathura Art School (indigenous red sandstone style) and Gandhara Art School (Greco-Buddhist style in Taxila/Peshawar)', true, '93a488bf-ebc9-4813-9555-eaa3b8f4ba62');
