INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d839bb63-b7b5-4a7a-b6ba-6ddbc0d26ce9', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'How did Xuan Zang transport hundreds of sacred Buddhist manuscripts and golden statues back from India to China in 645 CE?', 'Xuan Zang transported 657 Sanskrit texts on pack horses, spending his remaining life in Chang''an translating them into Chinese.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8de01fd9-a67e-40b8-ab82-3a050dbbf7cf', 'Loaded on the backs of 20 horses across the overland mountain passes of the Pamirs, Hindu Kush, and Taklamakan desert', true, 'd839bb63-b7b5-4a7a-b6ba-6ddbc0d26ce9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59b9a031-2a91-46cf-bd6c-b1311e7f551f', 'On a modern cargo airplane', false, 'd839bb63-b7b5-4a7a-b6ba-6ddbc0d26ce9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0818d4d-dd27-493d-8cec-b422c30ac7a0', 'By sending a postal parcel', false, 'd839bb63-b7b5-4a7a-b6ba-6ddbc0d26ce9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73bb16de-8757-44b5-a7a9-b2933a8d7000', 'Through underwater tunnels', false, 'd839bb63-b7b5-4a7a-b6ba-6ddbc0d26ce9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc11752b-6743-457d-9838-a1415dd89d73', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What religious path gained immense popularity in India during this period, emphasizing intense personal devotion and pure love for a chosen deity (Ishta-Deva) regardless of caste or gender?', 'Bhakti (from Sanskrit ''bhaj'' = to share/devote) emphasized egalitarian personal devotion to Shiva, Vishnu, or Durga.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95b5db76-b7a6-40f5-a4fb-95c6f166f8a2', 'Bhakti Movement (Bhakti Marga)', true, 'cc11752b-6743-457d-9838-a1415dd89d73');
