INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e13c4afc-f735-4a5b-8a22-a0c2abe51198', 'Vedic sacrifice', false, 'cc11752b-6743-457d-9838-a1415dd89d73');
