INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cea37bd1-380e-4800-a676-8a04869f2373', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'Which sacred Hindu scripture (a 700-verse section of the Mahabharata) contains the foundational doctrine of Bhakti taught by Lord Krishna to Arjuna?', 'In the Gita, Krishna reveals ''Bhakti Marga'' (devotional self-surrender) as the supreme path to spiritual liberation.', NOW()) ON CONFLICT DO NOTHING;
