INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84a67353-f417-4de4-bbef-2467a00a141f', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What does the Sanskrit root word ''Bhaj'' in ''Bhakti'' literally mean?', '''Bhaj'' means to share intimately, signifying a mutual emotional relationship between the bhakta and the Divine.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecd5b72d-9f03-4202-9d61-f9fe964b5704', 'To divide, share, participate in, or belong to (creating a reciprocal loving bond between the devotee and deity)', true, '84a67353-f417-4de4-bbef-2467a00a141f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6461855-077f-451d-9397-7e7eac49fec2', 'To fight in war', false, '84a67353-f417-4de4-bbef-2467a00a141f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcd34d65-2fd9-4705-8367-5b00e9981a02', 'To fast without food', false, '84a67353-f417-4de4-bbef-2467a00a141f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eee9e890-e587-41e8-9347-b808e48f80a0', 'To speak Sanskrit', false, '84a67353-f417-4de4-bbef-2467a00a141f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9d0ef9e-49ba-4542-aee5-9741d89a92b8', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'Why was the Bhakti movement revolutionary in the socio-religious history of ancient India?', 'Bhakti dismantled caste-based religious exclusivism, making direct devotion universally accessible to all social strata.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93171b39-ecfc-4ad1-a556-b27201f1c1c8', 'It threw open spiritual salvation to everyone—rich or poor, high caste or low caste, men or women—without expensive priestly rituals or animal sacrifices', true, 'f9d0ef9e-49ba-4542-aee5-9741d89a92b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a075ee1a-2fe7-45ec-8aba-8bcf9de87425', 'It banned all temples', false, 'f9d0ef9e-49ba-4542-aee5-9741d89a92b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13274736-2065-40c3-989c-9782256c0767', 'It ordered everyone to become monks', false, 'f9d0ef9e-49ba-4542-aee5-9741d89a92b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f95fc5c-336f-474a-b9ba-3f3cb2dee7d3', 'It was only for kings', false, 'f9d0ef9e-49ba-4542-aee5-9741d89a92b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e1da88e-3c1c-4b11-8aaa-dc937ba5e797', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What is the famous depiction of Lord Vishnu as the ''Varaha'' (Boar) avatar rescuing Mother Earth (Bhudevi) from the cosmic ocean carved in stone at:', 'Gupta-era colossal Varaha bas-reliefs at Udayagiri and Eran symbolize cosmic restoration and divine salvation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82f764ce-1e14-42ec-be4b-d4934fbf8977', 'Eran (Madhya Pradesh) and Udayagiri caves', true, '0e1da88e-3c1c-4b11-8aaa-dc937ba5e797');
