INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('afecba05-1e74-4de4-a312-03933e061ab8', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'How did Buddhist monk pilgrim Fa Xian describe his perilous sea return journey from Tamralipti port (Bengal) to China via Sri Lanka and Java?', 'Fa Xian''s travelogue chronicles the terror of monsoonal typhoons, clinging to his precious Buddhist manuscripts on board.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be0060a8-e2e4-45c3-be6e-786232905cf6', 'His merchant ship encountered a catastrophic cyclone storm for 13 days, forcing merchants to throw all heavy trade cargo overboard to prevent the ship from sinking', true, 'afecba05-1e74-4de4-a312-03933e061ab8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a118ebb-8363-437a-8a88-d2cf48866aef', 'He sailed smoothly without wind', false, 'afecba05-1e74-4de4-a312-03933e061ab8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('789ca25f-9b69-44e9-a9d6-4ee67f99de01', 'He was captured by Roman soldiers', false, 'afecba05-1e74-4de4-a312-03933e061ab8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29068f7a-f110-44d5-98fb-154ce6889ecf', 'He walked across the ocean on foot', false, 'afecba05-1e74-4de4-a312-03933e061ab8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7f5de8d-3ee4-4bd4-a8bf-3f04e39e3759', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What strict entrance examination did students have to pass to gain admission into Nalanda University, according to Xuan Zang?', 'Xuan Zang noted that Nalanda maintained rigorous academic standards, screening applicants through oral philosophical disputation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a178f78e-fc96-41d0-9cf7-457232338c7b', 'The Gatekeeper (Dvarapandita) posed deep philosophical questions at the main entrance gate; only 20% to 30% of applicants could answer and gain admission', true, 'b7f5de8d-3ee4-4bd4-a8bf-3f04e39e3759');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adc3a5db-743b-4272-821f-276f57069a26', 'They had to pay 100 gold coins', false, 'b7f5de8d-3ee4-4bd4-a8bf-3f04e39e3759');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b806da92-dc2c-4fd1-96a7-b8b21564880c', 'They had to run a 5-mile race', false, 'b7f5de8d-3ee4-4bd4-a8bf-3f04e39e3759');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8399a8af-97fd-48f0-b9c2-db46296cea7b', 'They had to belong to royal families', false, 'b7f5de8d-3ee4-4bd4-a8bf-3f04e39e3759');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92e93d4c-20ca-4fde-a145-7a2e69bcf7a1', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'Who was the South Indian Bhakti poet-saint Appar (a devotee of Lord Shiva) who composed soulful devotional poems in Tamil celebrating equality?', 'Appar (Thirunavukkarasar), a peasant Vellalar, composed Tevaram hymns proclaiming that sincere devotion supersedes caste origins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('357d8b84-93b5-490c-8312-cd23a6f4ba71', 'A 7th-century Nayanar saint who was a Vellalar (farmer)', true, '92e93d4c-20ca-4fde-a145-7a2e69bcf7a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d28b3c5-3057-489c-b368-29dda5dcc54f', 'A Buddhist monk', false, '92e93d4c-20ca-4fde-a145-7a2e69bcf7a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c183684-db98-438a-8fed-ea35eb81d57a', 'A Greek trader', false, '92e93d4c-20ca-4fde-a145-7a2e69bcf7a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac3d7dff-8891-48c5-816c-76f375523602', 'A Kushana king', false, '92e93d4c-20ca-4fde-a145-7a2e69bcf7a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a84b7f8-a1b6-4a60-9cc6-2a10bbdcb52b', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What three ruling dynasties were known as the ''Muvendar'' (Three Crowned Kings) who controlled the fertile Kaveri delta and southern coastal ports around 2,300 years ago?', 'Sangam literature celebrates the ''Muvendar'': the Cholas (Uraiyur/Puhar), Cheras (Karur/Muziris), and Pandyas (Madurai/Korkai).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b84bc57-20fa-4de4-9806-26a3f5c0108c', 'The Cholas, the Cheras, and the Pandyas', true, '4a84b7f8-a1b6-4a60-9cc6-2a10bbdcb52b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2afd4a1e-75c4-4cdd-aefd-5692828c3ac5', 'The Mauryas, Guptas, and Kushanas', false, '4a84b7f8-a1b6-4a60-9cc6-2a10bbdcb52b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('932c78c3-3c9e-4eea-9be4-b783409e8d60', 'The Pallavas, Chalukyas, and Rashtrakutas', false, '4a84b7f8-a1b6-4a60-9cc6-2a10bbdcb52b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75798e93-dfdf-4820-9758-025325fd96b6', 'The Mughals, Marathas, and Rajputs', false, '4a84b7f8-a1b6-4a60-9cc6-2a10bbdcb52b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f76ed07f-7bc7-4f9a-96e4-961360425bbb', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What was Puhar (also known as Kaveripattinam) in ancient South India?', 'Puhar was the bustling maritime port of the Cholas, vividly depicted in the Tamil epic ''Silappadikaram''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94ff0554-3bd9-4f36-8097-42b3ffa3ff5d', 'The premier coastal port city of the early Cholas on the Bay of Bengal, bustling with international sea trade', true, 'f76ed07f-7bc7-4f9a-96e4-961360425bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c73bc1f-5321-4c30-bd22-f2bcda4424f1', 'The capital of the Kushanas', false, 'f76ed07f-7bc7-4f9a-96e4-961360425bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('189e224f-a9ec-47d3-b90a-7a368d5ea3de', 'A monastery in Kashmir', false, 'f76ed07f-7bc7-4f9a-96e4-961360425bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0449f5c-cfbc-40b2-8699-71c2eca725ec', 'A desert oasis', false, 'f76ed07f-7bc7-4f9a-96e4-961360425bbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('220353cf-f828-4a40-89bf-48a4f924b50b', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What Indian commodity was so prized in the ancient Roman Empire that it was popularly called ''Black Gold'' (Yavanapriya)?', 'Malabar black pepper was in such huge demand in Rome that it was traded for its weight in gold and termed ''Black Gold''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7a22c97-73c0-468a-a32f-951bdc4ed6f7', 'Black Pepper (Kali Mirch)', true, '220353cf-f828-4a40-89bf-48a4f924b50b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2877bf2d-3899-458a-a251-faa6e03d9094', 'Black tea', false, '220353cf-f828-4a40-89bf-48a4f924b50b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4af3fce6-be74-4b92-ae51-a9f3bf996145', 'Coal', false, '220353cf-f828-4a40-89bf-48a4f924b50b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7b9806e-7bf9-483a-b47d-bf578d315c11', 'Black stone', false, '220353cf-f828-4a40-89bf-48a4f924b50b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa9b0675-6f09-4301-a122-afe4947336a8', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'How did ancient sailors and merchant navigators cross the Arabian Sea to reach the western ports of India quickly?', 'Hippalus and Greek sailors harnessed the predictable seasonal Southwest Monsoon winds to sail straight across the open Arabian Sea.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0318b49-7cff-43f7-9389-b9e31d58b610', 'They took strategic advantage of the seasonal Southwest Monsoon winds to sail directly across the open ocean from the Gulf of Aden to the Malabar coast in summer', true, 'aa9b0675-6f09-4301-a122-afe4947336a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8200f529-7b1f-4324-ba60-662de0f969d7', 'Using steam engine ships', false, 'aa9b0675-6f09-4301-a122-afe4947336a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9360f27c-380b-43f6-a1f6-bc0d85670357', 'By rowing continuously by hand without sails', false, 'aa9b0675-6f09-4301-a122-afe4947336a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b4c61f0-8f0e-42cd-b1fe-e3aae5a30a4e', 'By following stars in winter only', false, 'aa9b0675-6f09-4301-a122-afe4947336a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de65282a-f4ee-4fa0-8248-16673eacedf0', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What is the primary spiritual concept behind the construction of magnificent Hindu temple architecture that evolved from the Bhakti movement?', 'Bhakti catalyzed temple architecture: housing the enshrined deity in the sanctum sanctorum (Garbhagriha) for direct darshan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f1d8980-84e3-42e4-9438-e9ea78182368', 'Creating sacred physical abodes (Prasad/Garbhagriha) where the chosen deity resides to receive personal loving worship and darshan from devotees', true, 'de65282a-f4ee-4fa0-8248-16673eacedf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c53485d-a542-4103-89d4-dde295d53945', 'Building fortresses for war', false, 'de65282a-f4ee-4fa0-8248-16673eacedf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94d68649-5440-49a1-a798-952fb70866dc', 'Storing grain for famine', false, 'de65282a-f4ee-4fa0-8248-16673eacedf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20a9bce3-78a8-4601-8fab-0403582004d1', 'Astronomical observatories only', false, 'de65282a-f4ee-4fa0-8248-16673eacedf0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e52e7883-748b-4e58-8151-6382cefe8d72', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Read the statements:
