INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7bad712-4fdb-4cb8-b7fc-172f9a22c51b', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Spot the IMPOSTER in the following group of ancient Chinese pilgrims who visited India to study Buddhist texts:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19ad6a5a-a870-467e-ad1b-73dcb2dd7be4', 'Fa Xian (Faxian)', false, 'c7bad712-4fdb-4cb8-b7fc-172f9a22c51b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5c3a34e-65fa-4bb6-afa1-0ff78be4d910', 'Xuan Zang (Hiuen Tsang)', false, 'c7bad712-4fdb-4cb8-b7fc-172f9a22c51b');
