INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc32cdb8-113d-474c-9c80-e79a4fa94272', 'Megasthenes', true, 'c7bad712-4fdb-4cb8-b7fc-172f9a22c51b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63aea207-6ebc-4ba7-8f07-77d626482c11', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Consider the theological evolution between Early Buddhism (Theravada) and Later Buddhism (Mahayana):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a4edfe4-5fa1-49c5-9893-a74195833791', 'Depicting Buddha in anthropomorphic human statue form and worshipping Bodhisattvas who postpone nirvana to save all sentient beings', true, '63aea207-6ebc-4ba7-8f07-77d626482c11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcea024a-4110-4164-8e73-ff8bf1731784', 'Strictly representing Buddha through aniconic symbols (footprints, empty throne, wheel)', false, '63aea207-6ebc-4ba7-8f07-77d626482c11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3e6768e-66e7-47c9-bcf0-f785e203920b', 'Banning all statues and rituals', false, '63aea207-6ebc-4ba7-8f07-77d626482c11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de28770c-9b37-4f74-86ba-9f9da395155f', 'Using only Pali language and rejecting Sanskrit', false, '63aea207-6ebc-4ba7-8f07-77d626482c11');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e709287-3e47-4e92-b8e6-9dab4f0950fc', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Match Column I (Ancient Personalities / Texts) with Column II (Historical Contributions):
(a) Kanishka     -> (i) Author of Buddhacharita in Sanskrit
(b) Ashvaghosha  -> (ii) Kushana Emperor who convened 4th Buddhist Council
(c) Xuan Zang    -> (iii) Pilgrim who spent 16 years studying at Nalanda
(d) Appar        -> (iv) Nayanar saint who composed Tamil devotional hymns', 'Kanishka = 4th Council; Ashvaghosha = Buddhacharita; Xuan Zang = Nalanda scholar; Appar = Nayanar saint.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6baf217-8ac4-4f42-86c3-fa225aee03ff', 'a-(ii), b-(i), c-(iii), d-(iv)', true, '3e709287-3e47-4e92-b8e6-9dab4f0950fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79af7164-80a6-4483-8091-fdaecab79483', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '3e709287-3e47-4e92-b8e6-9dab4f0950fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f8667d7-f383-41a9-ad91-7fe213700ce8', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '3e709287-3e47-4e92-b8e6-9dab4f0950fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbf73ec7-835d-457b-bbba-4b19ce81e9ef', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '3e709287-3e47-4e92-b8e6-9dab4f0950fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c491ae9b-d2a3-447e-b336-20e7e181acb7', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Read the statements regarding ancient pilgrims:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2964ee76-91de-4ff5-92de-4ad3cb562ed3', 'Statements 1 and 3 only', true, 'c491ae9b-d2a3-447e-b336-20e7e181acb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df039d25-1ad0-475d-a7ae-e2e7bf711b36', 'Statements 1 and 2 only', false, 'c491ae9b-d2a3-447e-b336-20e7e181acb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9eb1d749-f0ca-4780-93c7-ff108b011461', 'Statements 2 and 3 only', false, 'c491ae9b-d2a3-447e-b336-20e7e181acb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d109798d-9246-432a-8c22-1db72e0fedc1', 'All Statements 1, 2, and 3', false, 'c491ae9b-d2a3-447e-b336-20e7e181acb7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ff9bd87-14bd-4b48-a211-5943fc396e47', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'What was the administrative concept of ''Muvendar'' mentioned in Sangam poems, where each of the three ruling chiefs had TWO centers of power?', 'Dual nodes of power: Cholas (Uraiyur inland + Puhar port), Pandyas (Madurai inland + Korkai port), Cheras (Karur inland + Muziris port).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdcb6bfc-c75e-400d-a041-e873f25ce099', 'Each dynasty (Cholas, Cheras, Pandyas) maintained ONE inland capital city and ONE coastal seaport, totaling six major urban power hubs in South India', true, '9ff9bd87-14bd-4b48-a211-5943fc396e47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d5c0fb6-cb75-4b53-a113-fef2a7d86031', 'Each had two kings ruling at once', false, '9ff9bd87-14bd-4b48-a211-5943fc396e47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb50e738-e05c-42b9-a021-a70bee9a0d2a', 'Each ruled over two separate islands', false, '9ff9bd87-14bd-4b48-a211-5943fc396e47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a848f4ed-ce72-41e7-b924-4264d197a64f', 'Each had two armies', false, '9ff9bd87-14bd-4b48-a211-5943fc396e47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6bf0d0b-3517-4d75-bc05-d84b5f7af8b8', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Why did the Kushana rulers issue such high-denomination, pure GOLD coins around the 1st century CE?', 'Kushana gold dinars mirrored Roman imperial weight standards (8 grams), creating a convertible reserve currency along the Silk Road.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f4d9637-fe72-4248-8282-d1386d9cbd40', 'To facilitate large-scale international transactions on the Silk Route, fueled by massive inflows of Roman gold and overland transit profits', true, 'd6bf0d0b-3517-4d75-bc05-d84b5f7af8b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d17310f8-82be-4d34-ad22-c46b5c311b48', 'Because they had no copper or silver', false, 'd6bf0d0b-3517-4d75-bc05-d84b5f7af8b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17d349d9-7c8e-46f6-b827-2c871a4f9294', 'To give as gifts to pilgrims', false, 'd6bf0d0b-3517-4d75-bc05-d84b5f7af8b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05e6bcdc-ae5a-4414-92cc-48938d23f438', 'To melt and build gold palaces', false, 'd6bf0d0b-3517-4d75-bc05-d84b5f7af8b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e9d3b56-a7a7-435f-ad1d-4437dac92395', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Consider four events in the history of trade and pilgrimage:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a98bc914-199f-4baf-b73e-421a10029463', '1 -> 2 -> 3 -> 4', true, '9e9d3b56-a7a7-435f-ad1d-4437dac92395');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4b92c8e-1197-409f-8c62-98f421662a26', '2 -> 1 -> 3 -> 4', false, '9e9d3b56-a7a7-435f-ad1d-4437dac92395');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dd09854-b399-4507-b763-3f7922b7bcc6', '1 -> 3 -> 2 -> 4', false, '9e9d3b56-a7a7-435f-ad1d-4437dac92395');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e9cf1a0-ab36-4091-bdc1-f055f1562320', '4 -> 3 -> 2 -> 1', false, '9e9d3b56-a7a7-435f-ad1d-4437dac92395');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d946d50a-2ab1-48d6-bde6-a27b24185511', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'What role did Buddhist monastic establishments along trade routes (such as Kanheri, Karle, and Ajanta rock-cut chaityas and viharas) play in ancient commerce?', 'Rock-cut viharas located along mountain passes (Bhor Ghat, Thal Ghat) offered safe lodging, credit, and water for merchant guilds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('371f3773-ff5c-4d1e-9052-588bd6164199', 'They served as secure rest stops, financial banking vaults, and provisioning stations for traveling merchant caravans passing through Western Ghat passes', true, 'd946d50a-2ab1-48d6-bde6-a27b24185511');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba91e026-2c56-4cc5-ad1f-5d9e921228ac', 'They were military garrisons', false, 'd946d50a-2ab1-48d6-bde6-a27b24185511');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ba775e3-96c5-482e-acc3-1b2d120be4ba', 'They manufactured silk', false, 'd946d50a-2ab1-48d6-bde6-a27b24185511');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b91815c0-8d1d-4249-b83a-8a51ec635865', 'They minted royal coins', false, 'd946d50a-2ab1-48d6-bde6-a27b24185511');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75a7ca48-de47-4848-86a5-0565a83b86b8', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'How did the Bhakti philosophy transform Indian art, poetry, and regional vernacular languages?', 'Bhakti democratized culture, spawning vernacular literature (Tevaram, Divya Prabandham) and emotive temple sculpture.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0efe58b7-7de4-43b2-a15d-438ada44d106', 'It inspired an explosion of devotional poetry, music, and sculpture composed in popular regional spoken languages (Tamil, Kannada, Marathi, Hindi) rather than exclusive elite Sanskrit alone', true, '75a7ca48-de47-4848-86a5-0565a83b86b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('904ca9ef-64d6-4152-bbee-c9370ea04086', 'It banned all vernacular poetry', false, '75a7ca48-de47-4848-86a5-0565a83b86b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca7ce62d-3128-4270-bbcf-37b02bca0931', 'It stopped people from painting', false, '75a7ca48-de47-4848-86a5-0565a83b86b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6992600-63e4-4a85-9255-dd3a4da62872', 'It mandated writing books only in Greek', false, '75a7ca48-de47-4848-86a5-0565a83b86b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3bff0ad6-9d44-4b7a-af70-e1feee3d2f3b', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'What is the profound philosophical meaning behind the Bhagavad Gita''s teaching on ''Nishkama Karma'' in the context of Bhakti?', 'Nishkama Karma unites selfless duty with spiritual devotion, purifying human intent of egoistic desire.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8609cd74-f7c6-4b40-89b7-0dbfd4741fbf', 'Performing one''s righteous duty selflessly without selfish attachment to the fruits or rewards of action, dedicating all outcomes in love to the Divine', true, '3bff0ad6-9d44-4b7a-af70-e1feee3d2f3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a0fc071-4082-4996-be99-5890f1cc6229', 'Renouncing all work and sitting idle', false, '3bff0ad6-9d44-4b7a-af70-e1feee3d2f3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8842a08b-4a0b-4679-8ddd-db7c7c5b637e', 'Fighting wars to acquire personal wealth', false, '3bff0ad6-9d44-4b7a-af70-e1feee3d2f3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d34f6ed-e06b-4861-9ad8-127dca528cca', 'Doing good deeds only for praise', false, '3bff0ad6-9d44-4b7a-af70-e1feee3d2f3b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c7a98fd-e7fb-4335-89c9-e3d07a76409d', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'What grand historical synthesis does Chapter 10 of NCERT History reveal about the ancient world?', 'The chapter portrays an open, interconnected global ancient world enriched by trade, intellectual cross-pollination, and shared spiritual quest.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fc2411e-f1dc-43db-a98c-c725f0502daa', 'A dynamic, interconnected world where trans-continental trade corridors, imperial patronage, philosophical reformations, and spiritual pilgrimages fostered deep cross-cultural synthesis across human civilization', true, '4c7a98fd-e7fb-4335-89c9-e3d07a76409d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f3281f7-dc1c-4fa9-b2ff-823ef5a4a09f', 'A collection of completely isolated civilizations with zero contact', false, '4c7a98fd-e7fb-4335-89c9-e3d07a76409d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ceef85e5-33b9-4cc9-abb0-fa430e427be5', 'A world where only war existed without trade', false, '4c7a98fd-e7fb-4335-89c9-e3d07a76409d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21edf8ae-7896-4ea7-806b-bd551717d863', 'A primitive society without roads or ideas', false, '4c7a98fd-e7fb-4335-89c9-e3d07a76409d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e356dec-1db6-4364-9854-2a3646abccb0', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जिस शब्द से किसी कार्य के करने या होने का बोध होता है (जैसे: पढ़ना, लिखना, दौड़ना, खाना, सोना, होना), उसे व्याकरण में क्या कहते हैं?', 'कार्य के निष्पादन या स्वतः होने का बोध कराने वाले विकारी शब्द ''क्रिया'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('208bb7e1-3d0a-4c63-9724-40497de62edb', 'क्रिया (Verb)', true, '7e356dec-1db6-4364-9854-2a3646abccb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0114838e-8e57-46a1-9185-8558cec28e6f', 'संज्ञा', false, '7e356dec-1db6-4364-9854-2a3646abccb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86040dc9-ba8b-4191-90c1-e2dce26748fe', 'विशेषण', false, '7e356dec-1db6-4364-9854-2a3646abccb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57da5c24-e491-46de-9bf6-eff7266033f5', 'सर्वनाम', false, '7e356dec-1db6-4364-9854-2a3646abccb0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b64244a1-43bb-4507-9b0e-2a0dd4626691', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'क्रिया के मूल रूप (Basic root form) को क्या कहते हैं, जिससे विभिन्न क्रिया पद बनते हैं (जैसे: ''पढ़'' से पढ़ना, पढ़ता, पढ़ेगा)?', 'क्रिया के मूल अविभाज्य रूप को ''धातु'' कहते हैं (जैसे: लिख, खा, देख, गा, हँस)। धातु में ''ना'' प्रत्यय जोड़कर सामान्य क्रिया बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0132c0e-eabf-44f1-81b6-06c8cf23d58c', 'धातु (Root)', true, 'b64244a1-43bb-4507-9b0e-2a0dd4626691');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec2dc37e-5a46-4069-ae1c-9b79be4443ff', 'उपसर्ग', false, 'b64244a1-43bb-4507-9b0e-2a0dd4626691');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9167647-777d-4ea1-88e9-7f82bf240a8c', 'प्रत्यय', false, 'b64244a1-43bb-4507-9b0e-2a0dd4626691');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fdcfee1-05e6-4534-b779-191cd7455bb0', 'समास', false, 'b64244a1-43bb-4507-9b0e-2a0dd4626691');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4d77a2f-6e5d-493d-a60d-5f7bae7d5594', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'कर्म के आधार पर क्रिया के मुख्य रूप से कितने भेद होते हैं?', 'कर्म की अपेक्षा के आधार पर क्रिया के 2 प्रमुख भेद हैं: सकर्मक (कर्म सहित) और अकर्मक (कर्म रहित)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d812626-424f-43ab-ade8-9b489f8c571a', 'दो भेद (1. सकर्मक क्रिया, और 2. अकर्मक क्रिया)', true, 'b4d77a2f-6e5d-493d-a60d-5f7bae7d5594');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77e6441d-b853-40cf-8ff2-c35793562ade', 'तीन भेद', false, 'b4d77a2f-6e5d-493d-a60d-5f7bae7d5594');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ba972be-0d53-4845-a9be-8087a883c226', 'चार भेद', false, 'b4d77a2f-6e5d-493d-a60d-5f7bae7d5594');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('153f2c81-8c0c-41fa-9f64-1cf813c36ff6', 'पाँच भेद', false, 'b4d77a2f-6e5d-493d-a60d-5f7bae7d5594');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf9fbf41-6b0f-40ae-aed9-cc7e4e64d9a3', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जिस क्रिया के व्यापार (कार्य) का फल कर्ता पर न पड़कर ''कर्म'' पर पड़ता है (अर्थात् जिसमें कर्म की आवश्यकता होती है), उसे क्या कहते हैं?', 'जिस क्रिया का प्रभाव कर्म पर पड़े (क्या/किसे का उत्तर मिले), वह ''सकर्मक क्रिया'' होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18322090-5a37-4399-9bb1-2af6967479a3', 'सकर्मक क्रिया (Transitive Verb - जैसे: ''राम पुस्तक पढ़ता है'')', true, 'cf9fbf41-6b0f-40ae-aed9-cc7e4e64d9a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('891fb1da-bde0-40c0-8957-47ffe94157ab', 'अकर्मक क्रिया', false, 'cf9fbf41-6b0f-40ae-aed9-cc7e4e64d9a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc0fbff7-7998-4450-82a9-955a7d33ff4a', 'प्रेरणार्थक क्रिया', false, 'cf9fbf41-6b0f-40ae-aed9-cc7e4e64d9a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06b35137-9745-49d2-a531-9967ae480ff5', 'सहायक क्रिया', false, 'cf9fbf41-6b0f-40ae-aed9-cc7e4e64d9a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff355b9d-78f3-4d32-b4c1-45c2445fa8ae', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जिस क्रिया के व्यापार का फल सीधे कर्ता पर ही पड़ता है और जिसमें कर्म नहीं होता (जैसे: ''बच्चा रोता है'', ''पक्षी उड़ते हैं''), उसे क्या कहते हैं?', 'जिसमें कर्म की अपेक्षा न हो और कार्य का प्रभाव कर्ता पर ही सीमित रहे, वह ''अकर्मक क्रिया'' होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b97f1b1-4cfc-4628-8233-46b7ef6ad990', 'अकर्मक क्रिया (Intransitive Verb)', true, 'ff355b9d-78f3-4d32-b4c1-45c2445fa8ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('518a0d5a-b043-4c1f-a78e-11052101ffd4', 'सकर्मक क्रिया', false, 'ff355b9d-78f3-4d32-b4c1-45c2445fa8ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7d72e8d-4723-4eb1-a14d-1141ace6fcf6', 'द्विकर्मक क्रिया', false, 'ff355b9d-78f3-4d32-b4c1-45c2445fa8ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d3db24a-ae62-422e-87e0-45892100c18d', 'संयुक्त क्रिया', false, 'ff355b9d-78f3-4d32-b4c1-45c2445fa8ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('488d0739-b997-410d-a3e4-3637d81422fe', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'वाक्य में क्रिया के साथ ''क्या'' या ''किसे/किसको'' लगाकर प्रश्न पूछने पर यदि कोई उत्तर मिलता है, तो वह क्रिया क्या कहलाती है?', '''क्या/किसे'' प्रश्न का सार्थक उत्तर मिलना सकर्मक क्रिया की सबसे सरल व प्रामाणिक पहचान है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25b58d71-4cb8-428f-892e-e10809fee19a', 'सकर्मक क्रिया (उत्तर मिलने वाला पद ''कर्म'' होता है)', true, '488d0739-b997-410d-a3e4-3637d81422fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a723daa-1a7e-428e-b4a6-6e6d1711afee', 'अकर्मक क्रिया', false, '488d0739-b997-410d-a3e4-3637d81422fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87e44ace-c3b5-4c2b-bc59-db40014bebce', 'नामधातु क्रिया', false, '488d0739-b997-410d-a3e4-3637d81422fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb5cdcb3-a89b-4bb0-a953-0c9d89a95534', 'अव्यय', false, '488d0739-b997-410d-a3e4-3637d81422fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc69dd8b-6f0a-45d1-b8b4-a5db4721eff0', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जिस सकर्मक क्रिया में दो कर्म होते हैं (जैसे: ''अध्यापक ने छात्रों को हिंदी पढ़ाई''), उसे क्या कहते हैं?', 'दो कर्मों (मुख्य कर्म वस्तुवाचक + गौण कर्म प्राणीवाचक) से युक्त क्रिया ''द्विकर्मक क्रिया'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34e6d72d-04ac-47db-be79-8d22e7c0cb76', 'द्विकर्मक क्रिया (छात्रों = गौण कर्म ; हिंदी = मुख्य कर्म)', true, 'dc69dd8b-6f0a-45d1-b8b4-a5db4721eff0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afa9f3aa-abc1-41f2-a537-515bfc0b9798', 'एककर्मक क्रिया', false, 'dc69dd8b-6f0a-45d1-b8b4-a5db4721eff0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfba29de-926f-431e-8348-09dd277b78fe', 'अकर्मक क्रिया', false, 'dc69dd8b-6f0a-45d1-b8b4-a5db4721eff0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfc6af52-733f-46e9-b7ba-96602b6b9e77', 'सहायक क्रिया', false, 'dc69dd8b-6f0a-45d1-b8b4-a5db4721eff0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be7d6969-a042-4301-a090-21329167334b', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जब कर्ता स्वयं कार्य न करके किसी अन्य को कार्य करने की प्रेरणा देता है या करवाता है (जैसे: ''माँ नौकरानी से कपड़े धुलवाती है''), तो उस क्रिया को क्या कहते हैं?', 'कर्ता द्वारा किसी अन्य को कार्य में प्रवृत्त कराने वाली क्रिया ''प्रेरणार्थक क्रिया'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81c971d5-3aed-4818-862b-2599b929b7f7', 'प्रेरणार्थक क्रिया (Causative Verb)', true, 'be7d6969-a042-4301-a090-21329167334b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21264774-d4af-4945-b360-591c4692480a', 'अकर्मक क्रिया', false, 'be7d6969-a042-4301-a090-21329167334b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec256c23-8401-42ed-a542-d1c179705388', 'नामधातु क्रिया', false, 'be7d6969-a042-4301-a090-21329167334b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77a033c9-20e3-497c-a40c-db5ad138a1f0', 'पूर्वकालिक क्रिया', false, 'be7d6969-a042-4301-a090-21329167334b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4d9439c-08cb-456b-a09c-cc6f09dd87ad', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'संज्ञा, सर्वनाम या विशेषण शब्दों से बनने वाली क्रियाओं (जैसे: ''हाथ'' से हथियाना, ''बात'' से बतियाना, ''शर्म'' से शर्माना, ''गर्म'' से गरमाना) को क्या कहते हैं?', 'संज्ञा/सर्वनाम/विशेषण प्रातिपदिकों में प्रत्यय जोड़कर निर्मित क्रियाएँ ''नामधातु क्रिया'' कहलाती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d446d16-5353-438d-99b1-cccabdbede02', 'नामधातु क्रिया (Nominal Verb)', true, 'b4d9439c-08cb-456b-a09c-cc6f09dd87ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('723dbd9f-fd21-40d4-b473-11aebf70a5ab', 'प्रेरणार्थक क्रिया', false, 'b4d9439c-08cb-456b-a09c-cc6f09dd87ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08c0114d-ac9b-4d74-88e2-d249dab07896', 'संयुक्त क्रिया', false, 'b4d9439c-08cb-456b-a09c-cc6f09dd87ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5e5ac4e-e20d-452c-be2a-f69b31b49d0e', 'पूर्वकालिक क्रिया', false, 'b4d9439c-08cb-456b-a09c-cc6f09dd87ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6458b79c-5f48-4645-bd69-7428118f0a78', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जब दो या दो से अधिक क्रियाएँ मिलकर एक पूर्ण क्रिया बनाती हैं (जैसे: ''वह खाना **खा चुका है**'', ''मोहन **चला गया**''), तो उन्हें क्या कहते हैं?', 'मुख्य क्रिया और रंजक क्रिया के संयोग से गठित क्रिया पद ''संयुक्त क्रिया'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27a417f8-c1cc-498d-be17-51b0eb3629b2', 'संयुक्त क्रिया (Compound Verb)', true, '6458b79c-5f48-4645-bd69-7428118f0a78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a28895e-0d8f-452a-8bba-2816b80e9cd5', 'मूल क्रिया', false, '6458b79c-5f48-4645-bd69-7428118f0a78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c85e392-c9f0-4037-938f-6584397c53ff', 'नामधातु क्रिया', false, '6458b79c-5f48-4645-bd69-7428118f0a78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8377e9d0-7d46-4981-8532-8df4f6fa5742', 'अकर्मक क्रिया', false, '6458b79c-5f48-4645-bd69-7428118f0a78');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8408032f-597e-4553-bcab-993fe7221a8e', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'मुख्य क्रिया से पहले होने वाली क्रिया (जिसमें प्रायः ''कर'' या ''करके'' लगा होता है, जैसे: ''वह **नहाकर** विद्यालय गया'') को क्या कहते हैं?', 'समापिका क्रिया से पूर्व निष्पादित क्रिया ''पूर्वकालिक क्रिया'' कहलाती है (जैसे: पढ़कर, खेलकर, खाकर)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('782d6b70-6137-4f83-912f-6cfc03e25281', 'पूर्वकालिक क्रिया (Absolutive / Preceding Verb)', true, '8408032f-597e-4553-bcab-993fe7221a8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cbfa111-5868-48fd-a350-56ac454eb8e9', 'सहायक क्रिया', false, '8408032f-597e-4553-bcab-993fe7221a8e');
