INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f76d5519-7700-4268-94df-5bd402bb3044', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'निम्नलिखित में से स्वाभाविक रूप से ''अकर्मक क्रियाओं'' का सही समूह कौन-सा है?', 'शारीरिक स्थितियाँ एवं स्वाभाविक गतियाँ (हँसना, रोना, सोना, दौड़ना) स्वतः अकर्मक क्रियाएँ होती हैं।', NOW()) ON CONFLICT DO NOTHING;
