INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce5a73a7-96de-4228-9bf3-f0f07336b850', 'पढ़ना, लिखना, खाना, पीना, देखना, बनाना', false, 'f76d5519-7700-4268-94df-5bd402bb3044');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('278f120b-67b2-4a59-9567-14a40435deed', 'काटना, धोना, सिलना, बेचना', false, 'f76d5519-7700-4268-94df-5bd402bb3044');
