INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de6e0392-5ac0-40c1-bd84-450c03121abb', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'प्रेरणार्थक क्रिया के दो रूप (प्रथम प्रेरणार्थक और द्वितीय प्रेरणार्थक) का सही उदाहरण कौन-सा है?', 'प्रथम प्रेरणार्थक में ''-आना'' (पढ़ाना) तथा द्वितीय प्रेरणार्थक में ''-वाना'' (पढ़वाना) प्रत्यय जुड़ता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8a2a32d-2495-4c60-abf2-3670641560e5', 'मूल: पढ़ना -> प्रथम: पढ़ाना -> द्वितीय: पढ़वाना', true, 'de6e0392-5ac0-40c1-bd84-450c03121abb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87e2a7cb-0a10-4093-a011-b0f0a24cea51', 'मूल: खाना -> प्रथम: खाया -> द्वितीय: खाएगा', false, 'de6e0392-5ac0-40c1-bd84-450c03121abb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8e0a252-0d11-4ac7-8a49-1d4e4b174a1e', 'मूल: चलना -> प्रथम: चला -> द्वितीय: चल', false, 'de6e0392-5ac0-40c1-bd84-450c03121abb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5456d3f1-adff-4b25-932c-6b152951cf70', 'मूल: लिखना -> प्रथम: लिखा -> द्वितीय: लेख', false, 'de6e0392-5ac0-40c1-bd84-450c03121abb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c316d66-ddad-418d-9483-ffc107ea1257', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'वाक्य में प्रयुक्त दोनों कर्मों की सही पहचान कीजिए:
