INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ba5544b-a04c-4257-9a61-a0dced13e056', 'घड़ी = गौण कर्म ; पुत्र = मुख्य कर्म', false, '6c316d66-ddad-418d-9483-ffc107ea1257');
