INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b196d14a-9ecb-45c6-9185-06e376748344', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'संज्ञा शब्द ''लाठी'' और ''फिल्म'' से बनने वाली सही नामधातु क्रियाएँ क्रमशः क्या हैं?', 'लाठी -> लठियाना; फिल्म -> फिल्माना (नामधातु क्रियाएँ)।', NOW()) ON CONFLICT DO NOTHING;
