INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fb94187-1e7b-40ff-b619-28ed1df2ca89', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'विशेषण शब्द ''चिकना'' और ''अपना'' (सर्वनाम) से बनने वाली सही नामधातु क्रियाएँ क्या हैं?', 'चिकना (विशेषण) -> चिकनाना; अपना (सर्वनाम) -> अपनाना।', NOW()) ON CONFLICT DO NOTHING;
