INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58d29a26-c3a2-464f-b812-3249e15e97e1', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'संयुक्त क्रिया ''रोहन खेलने लगा'' में मुख्य क्रिया और रंजक (सहायक) क्रिया कौन-सी है?', '''खेलने'' मुख्य अर्थ दे रहा है, और ''लगा'' क्रिया के आरंभ होने का रंजक अर्थ जोड़ रहा है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('450b2d0d-ea73-4f19-8106-e480e3e96fc1', '''खेलने'' = मुख्य क्रिया ; ''लगा'' = रंजक/सहायक क्रिया', true, '58d29a26-c3a2-464f-b812-3249e15e97e1');
