INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f1ee0ee-6eae-4485-9dfc-06c30715e661', 'दोनों मुख्य क्रियाएँ हैं', false, '58d29a26-c3a2-464f-b812-3249e15e97e1');
