INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa9a79e9-8095-47e5-9524-a0e97b9b0d47', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'वाक्य में प्रयुक्त क्रिया का लिंग और वचन किसके अनुसार निर्धारित होता है?', 'कर्तृप्रयोग में क्रिया कर्ता के अनुसार और कर्मणिप्रयोग (जैसे ''राम ने रोटी खाई'') में कर्म के अनुसार प्रयुक्त होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e242700-fd66-40ea-af9e-a15e64571b8b', 'सामान्यतः कर्ता के लिंग-वचन के अनुसार ; किन्तु कर्मवाच्य में अथवा कर्ता के साथ ''ने'' परसर्ग होने पर कर्म के लिंग-वचन के अनुसार', true, 'fa9a79e9-8095-47e5-9524-a0e97b9b0d47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac8d8c57-9d44-4b99-a250-2850ba8985a3', 'हमेशा केवल विशेषण के अनुसार', false, 'fa9a79e9-8095-47e5-9524-a0e97b9b0d47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('744bf533-1d05-412c-8b7c-1e91bfee97e4', 'हमेशा केवल क्रियाविशेषण के अनुसार', false, 'fa9a79e9-8095-47e5-9524-a0e97b9b0d47');
