INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('781eabe9-3356-4e59-bbf9-f107a5a0f915', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'अनुकरणात्मक धातुओं (ध्वनियों के अनुकरण से बनने वाली क्रियाएँ) का सही उदाहरण कौन-सा है?', 'ध्वनि के अनुकरण पर गढ़ी गई धातुएँ अनुकरणात्मक नामधातु क्रियाएँ कहलाती हैं (खटखट -> खटखटाना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1f35e08-6d92-406d-b1de-9e85ef1885a0', 'भिनभिनाना (मक्खी), खटखटाना (दरवाजा), हिनहिनाना (घोड़ा), टिमटिमाना (तारे), फड़फड़ाना (पंख)', true, '781eabe9-3356-4e59-bbf9-f107a5a0f915');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9390ce3-6da2-4496-841c-d324e8cd8d11', 'पढ़ना और लिखना', false, '781eabe9-3356-4e59-bbf9-f107a5a0f915');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b39d0ecd-05f8-4584-8c2a-0a5486d08a1c', 'जाना और आना', false, '781eabe9-3356-4e59-bbf9-f107a5a0f915');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d2a2df3-8eff-46b8-b7b2-106e767323c1', 'रोना और हँसना', false, '781eabe9-3356-4e59-bbf9-f107a5a0f915');
