INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ca2034f-75f2-4dbf-8b47-ac7ea53892de', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'मूल धातु ''हँसना'' का प्रथम और द्वितीय प्रेरणार्थक रूप क्या होगा?', 'हँसना -> हँसाना -> हँसवाना।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87fcf2a7-055a-4274-ab9d-a8a685175546', 'हँसाना (प्रथम) और हँसवाना (द्वितीय)', true, '2ca2034f-75f2-4dbf-8b47-ac7ea53892de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18a5b821-98d8-46f7-80d1-79b3435d13a1', 'हँसा और हँसाया', false, '2ca2034f-75f2-4dbf-8b47-ac7ea53892de');
