INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e539eb39-3b6c-4802-b932-db2b939f9be6', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2abe9d1-ade9-4666-84db-8562886e916b', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'e539eb39-3b6c-4802-b932-db2b939f9be6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc8e74d0-6074-476e-b0af-64f4ac4e362d', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'e539eb39-3b6c-4802-b932-db2b939f9be6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41c9cb4c-985a-4fe1-adda-3846ed38e77d', '(A) सही है, परन्तु (R) गलत है।', false, 'e539eb39-3b6c-4802-b932-db2b939f9be6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d2ac2c2-cfd9-497f-a035-67c15c2fdd16', '(A) गलत है, परन्तु (R) सही है।', false, 'e539eb39-3b6c-4802-b932-db2b939f9be6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a40bfffd-d907-46d1-8e53-855239e69143', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'Spot the IMPOSTER in the following group of क्रिया और उनके भेदों के युग्म में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cbb1b03-a287-47fa-bcf2-a2e5f0f18f78', 'पढ़ना - सकर्मक', false, 'a40bfffd-d907-46d1-8e53-855239e69143');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb969dfd-5d44-4cf9-9086-8c06c483aa5f', 'हँसना - अकर्मक', false, 'a40bfffd-d907-46d1-8e53-855239e69143');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbac748f-7401-41f9-b804-c45be3624f94', 'लिखना - सकर्मक', false, 'a40bfffd-d907-46d1-8e53-855239e69143');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c1df124-4b72-4be3-8b67-bfcbbdf9236d', 'सोना - सकर्मक', true, 'a40bfffd-d907-46d1-8e53-855239e69143');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88cf07db-a0dc-4fcf-ae4f-27376779a23e', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'सुमेलित कीजिए (क्रिया के रूप और उनके व्याकरणिक भेद):
(क) हथियाना   -> (i) पूर्वकालिक क्रिया
(ख) पिलवाना    -> (ii) नामधातु क्रिया
(ग) खाकर      -> (iii) संयुक्त क्रिया
(घ) चल पड़ा   -> (iv) द्वितीय प्रेरणार्थक क्रिया', 'हथियाना = नामधातु; पिलवाना = द्वितीय प्रेरणार्थक; खाकर = पूर्वकालिक; चल पड़ा = संयुक्त क्रिया।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e1cd38a-5b89-4e1e-9669-22e084807011', 'क-(ii), ख-(iv), ग-(i), घ-(iii)', true, '88cf07db-a0dc-4fcf-ae4f-27376779a23e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('561f9092-56da-4118-98d3-558e41239c4a', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '88cf07db-a0dc-4fcf-ae4f-27376779a23e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d8031a0-49e8-47b5-936e-7d436cf3859f', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '88cf07db-a0dc-4fcf-ae4f-27376779a23e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d44b3951-7fac-4580-9c2a-51fd0c94d5a7', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '88cf07db-a0dc-4fcf-ae4f-27376779a23e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fa6ed1e-9a07-4789-a810-bb2157bf525e', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'सजातीय क्रिया (Cognate Verb) का सही उदाहरण कौन-सा है?', 'जब कर्म और क्रिया दोनों एक ही मूल धातु से व्युत्पन्न हों (जैसे: लड़ाई लड़ी, चाल चली), तो उसे ''सजातीय क्रिया'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33ffa7b7-3231-47e4-9a60-f1020b9d9374', 'भारत ने पाकिस्तान के विरुद्ध **शानदार लड़ाई लड़ी**। (कर्म ''लड़ाई'' और क्रिया ''लड़ी'' एक ही ''लड़'' धातु से बने हैं)', true, '1fa6ed1e-9a07-4789-a810-bb2157bf525e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68643108-29a3-48cb-9fde-ce2caff61a71', 'उसने पानी पिया।', false, '1fa6ed1e-9a07-4789-a810-bb2157bf525e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab20f594-1d87-45c7-9602-52f6544fcb7d', 'वह घर गया।', false, '1fa6ed1e-9a07-4789-a810-bb2157bf525e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9de99238-5ef4-45a4-a7e4-3fedb3f7cabf', 'बच्चा खेल रहा है।', false, '1fa6ed1e-9a07-4789-a810-bb2157bf525e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c0060cd-b382-48a7-8424-d2a30391988e', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'कृदंत क्रिया (Participle Verb) और तद्धित में क्या अंतर है?', 'धातु + प्रत्यय = कृदंत (लिखकर, पढ़ता, दौड़ा); संज्ञा/सर्वनाम + प्रत्यय = तद्धित/नामधातु।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48204407-5c51-49f0-900a-5d457acbbe24', 'धातुओं (क्रिया मूलों) में प्रत्यय जुड़ने से बनने वाले क्रिया रूप ''कृदंत'' कहलाते हैं (जैसे: लिख + ता = लिखता) ; जबकि संज्ञा/सर्वनाम/विशेषण से बनने वाले रूप ''तद्धित'' कहलाते हैं', true, '7c0060cd-b382-48a7-8424-d2a30391988e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63f12b5a-2359-4093-bf5c-6fd23bade3c0', 'कृदंत केवल अव्यय होते हैं', false, '7c0060cd-b382-48a7-8424-d2a30391988e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39888b77-00e3-48bf-bcd7-50eb9c600cac', 'तद्धित में धातु होती है', false, '7c0060cd-b382-48a7-8424-d2a30391988e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18f2f749-3199-4ff7-84cc-26ec7d4daede', 'दोनों में कोई अंतर नहीं है', false, '7c0060cd-b382-48a7-8424-d2a30391988e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a97af7de-f5c8-4846-a3bd-9b860195b04c', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''अकर्मक क्रिया'' प्रयुक्त हुई है?', '''सो रहा है'' अकर्मक क्रिया है; शेष तीनों वाक्यों में कर्म (सड़क, निबंध, खाना) उपस्थित हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4820949-0bbe-4281-a952-efd85a6e01d7', '''मजदूर दिन भर से पसीना बहाकर **सो रहा है**।''', true, 'a97af7de-f5c8-4846-a3bd-9b860195b04c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('390f4887-0924-4c10-ba78-bd8bc9f0abc5', '''मजदूर सड़क बना रहा है।''', false, 'a97af7de-f5c8-4846-a3bd-9b860195b04c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5ce4ce1-4172-4c2b-bf9d-77323e53b312', '''छात्र निबंध लिख रहा है।''', false, 'a97af7de-f5c8-4846-a3bd-9b860195b04c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e6a70ee-2149-4a43-9287-e23715fa4212', '''रसोइया खाना पका रहा है।''', false, 'a97af7de-f5c8-4846-a3bd-9b860195b04c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2331ba9-76d0-47d4-b21e-1c1e06e93987', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'तात्कालिक कृदंत क्रिया का सही उदाहरण कौन-सा है?', 'धातु + ''ते ही'' लगकर तत्क्षण दूसरी क्रिया का संपादन सूचित करने वाली क्रिया ''तात्कालिक कृदंत'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('895b6628-ea16-4510-b47f-24466723c545', '''शेर को **देखते ही** शिकारी भाग गया।'' (''देखते ही'' एक क्रिया के तुरंत बाद दूसरी क्रिया का बोध कराती है)', true, 'f2331ba9-76d0-47d4-b21e-1c1e06e93987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66e0a730-21bb-4ac9-9d35-f46695ed76e7', '''वह पढ़कर सोया।''', false, 'f2331ba9-76d0-47d4-b21e-1c1e06e93987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9547afb9-083e-44f9-9132-8961a5e94c57', '''वह गाना गाता है।''', false, 'f2331ba9-76d0-47d4-b21e-1c1e06e93987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18c9ab8a-4c48-447e-a067-ea7a432fc7fb', '''वह चला गया।''', false, 'f2331ba9-76d0-47d4-b21e-1c1e06e93987');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a033386e-80f6-44ea-9c94-060dc0ea47bf', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'वाक्य में प्रयुक्त रेखांकित पद का व्याकरणिक परिचय दीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d118f8b2-6ca0-4d80-8db8-a8761a79f709', 'प्रेरणार्थक सकर्मक क्रिया (कर्म = ''भोजन'')', true, 'a033386e-80f6-44ea-9c94-060dc0ea47bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8afcab0e-2b85-4a0c-88eb-c2988ca3eea7', 'अकर्मक क्रिया', false, 'a033386e-80f6-44ea-9c94-060dc0ea47bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7054210b-2a3f-49bf-9195-e569fb87052c', 'पूर्वकालिक क्रिया', false, 'a033386e-80f6-44ea-9c94-060dc0ea47bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66251e58-c3b7-4aa0-b118-6f0dfa29ada4', 'नामधातु क्रिया', false, 'a033386e-80f6-44ea-9c94-060dc0ea47bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49c268a4-a1b9-4cbd-af28-1cb30fce4fbe', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'अकर्मक धातुओं को सकर्मक धातुओं में बदलने का सही नियम कौन-सा है?', 'अकर्मक धातुओं में आ/वा प्रत्यय जोड़कर या आदि स्वर दीर्घ करके सकर्मक क्रिया बनाई जाती है (कटना -> काटना, गिरना -> गिराना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8f7c360-c36d-49de-a2de-f78632aea65c', 'हँसना (अकर्मक) -> हँसाना (सकर्मक) ; गिरना (अकर्मक) -> गिराना (सकर्मक) ; कटना (अकर्मक) -> काटना (सकर्मक)', true, '49c268a4-a1b9-4cbd-af28-1cb30fce4fbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56c05256-3fcf-4522-9b3d-ce4b11829f65', 'केवल ''ना'' हटाकर', false, '49c268a4-a1b9-4cbd-af28-1cb30fce4fbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf0f0a98-cbc2-4fae-ac3d-6fc9aa21722b', 'केवल विसर्ग लगाकर', false, '49c268a4-a1b9-4cbd-af28-1cb30fce4fbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cbd6659-8cf0-4821-b9ec-b86618842c7a', 'अकर्मक को कभी सकर्मक नहीं बनाया जा सकता', false, '49c268a4-a1b9-4cbd-af28-1cb30fce4fbe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9aaf8e4c-dc04-4726-8719-4bb843b9e217', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'संयुक्त क्रिया के मुख्य 11 अर्थगत भेदों में से ''आरंभबोधक'' और ''समाप्तिबोधक'' का सही युग्म कौन-सा है?', '''धातु + लगना'' = आरंभबोधक (हँसने लगा); ''धातु + चुकना'' = समाप्तिबोधक (पढ़ चुका)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08436848-1fc5-4755-b4b9-78b11f340bc1', '''वह **गाने लगा**'' (आरंभबोधक) और ''वह **खा चुका**'' (समाप्तिबोधक)', true, '9aaf8e4c-dc04-4726-8719-4bb843b9e217');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('756ba0eb-b349-4b03-8ae8-0409a359d94d', '''वह जा सकता है'' और ''वह गया''', false, '9aaf8e4c-dc04-4726-8719-4bb843b9e217');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e0eb0b6-c246-4fb0-8382-b281a9bfa9c4', '''वह खेला'' और ''वह दौड़ा''', false, '9aaf8e4c-dc04-4726-8719-4bb843b9e217');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be45f69e-0c05-409f-8d52-eda1ac051cd3', '''पढ़ना'' और ''लिखना''', false, '9aaf8e4c-dc04-4726-8719-4bb843b9e217');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b08cec77-44ae-4a03-933b-b880b9da7599', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'वाक्य को क्रिया की दृष्टि से मानक रूप में शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a316208-bbe9-460c-af91-9c7db820cdf5', '''मेरे चाचा जी आए हैं, वे कल जाएँगे।'' (आदरार्थक बहुवचन कर्ता के साथ क्रिया बहुवचन ''जाएँगे'' होगी)', true, 'b08cec77-44ae-4a03-933b-b880b9da7599');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a1d42f6-50c0-4114-bdca-1be2a6b1af30', 'मेरे चाचा जी आया है, वह जाएगा।', false, 'b08cec77-44ae-4a03-933b-b880b9da7599');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d318afa8-d8e8-4f4c-9aa0-3e25292d4e4b', 'चाचा जी आया, जाएगा कल।', false, 'b08cec77-44ae-4a03-933b-b880b9da7599');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('218cc127-8d63-41b5-9760-f325841af40f', 'मेरे चाचा आए, वह कल जाते।', false, 'b08cec77-44ae-4a03-933b-b880b9da7599');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd498571-600d-49b2-a8d3-bf7e38bb6e83', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'क्रिया का वाक्य में क्या सर्वोच्च महत्व होता है?', 'क्रिया वाक्य का अनिवार्य विधेय तत्व है, जिसके बिना वाक्य की विचार-अभिव्यक्ति असंभव है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22ecf692-c49a-44aa-9440-8bcc4523b14a', 'क्रिया वाक्य का अनिवार्य केंद्र (हृदय) होती है; बिना क्रिया के कोई भी सार्थक वाक्य पूर्ण नहीं हो सकता', true, 'cd498571-600d-49b2-a8d3-bf7e38bb6e83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7009881a-62a4-4a0f-ac32-a4c494b24e0f', 'क्रिया केवल कविता में उपयोगी है', false, 'cd498571-600d-49b2-a8d3-bf7e38bb6e83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37364ae9-1336-47e2-876b-3e66610b1c4d', 'क्रिया के बिना भी वाक्य पूरे अर्थ दे सकते हैं', false, 'cd498571-600d-49b2-a8d3-bf7e38bb6e83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b8d445b-00bb-4d50-8d81-eac583a72b28', 'क्रिया केवल काल बताती है और कुछ नहीं', false, 'cd498571-600d-49b2-a8d3-bf7e38bb6e83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4036bd02-b77d-4c46-88f1-957aae30cbd3', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'What is the thick protective blanket/envelope of air surrounding the entire Earth called?', 'The atmosphere is the multi-layered gaseous envelope retained by Earth''s gravity extending hundreds of kilometres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('996eba41-c31e-4c84-baa9-5e62e832d2d5', 'Atmosphere', true, '4036bd02-b77d-4c46-88f1-957aae30cbd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2b32f6c-933f-4445-94fe-46ebd21c92c3', 'Hydrosphere', false, '4036bd02-b77d-4c46-88f1-957aae30cbd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec6d3434-c26d-44db-b940-2d888fdac22f', 'Lithosphere', false, '4036bd02-b77d-4c46-88f1-957aae30cbd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9220e9d0-574d-4fe1-8321-c353f1171e1d', 'Biosphere', false, '4036bd02-b77d-4c46-88f1-957aae30cbd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f05df0dc-7113-4ea2-8410-ad4a24459c5e', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Air in motion (moving air) is commonly called:', 'Moving air created by atmospheric pressure gradients is termed wind (or breeze).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ed64b5a-040a-4066-b9fc-1a89c1c8fe4b', 'Wind', true, 'f05df0dc-7113-4ea2-8410-ad4a24459c5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b89e6cf2-ce26-44cc-9df7-3ff739cfb31d', 'Storm', false, 'f05df0dc-7113-4ea2-8410-ad4a24459c5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fde6121f-221b-42d1-a5b9-9f0acfac1105', 'Cyclone', false, 'f05df0dc-7113-4ea2-8410-ad4a24459c5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ff2075f-433d-4674-8014-f89140d9b610', 'Vacuum', false, 'f05df0dc-7113-4ea2-8410-ad4a24459c5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59a54618-2923-4d9b-8eb3-9558c1fc4f9e', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Which gas is the MOST ABUNDANT in atmospheric air, making up approximately 78% (nearly 4/5ths) of air volume?', 'Nitrogen comprises ~78% of the dry atmosphere, acting as an unreactive diluent that tempers rapid combustion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4350b40e-7b2c-44ba-8af2-c89a15c78d81', 'Nitrogen (N₂)', true, '59a54618-2923-4d9b-8eb3-9558c1fc4f9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c08d6da-297f-4954-8630-a5b77228da62', 'Oxygen (O₂)', false, '59a54618-2923-4d9b-8eb3-9558c1fc4f9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('361d32fe-a113-4879-bbc4-9bcc916a74e7', 'Carbon dioxide (CO₂)', false, '59a54618-2923-4d9b-8eb3-9558c1fc4f9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de52f6e5-4636-4fb9-a0b9-f353fb5b7a13', 'Argon', false, '59a54618-2923-4d9b-8eb3-9558c1fc4f9e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0988ecd-5632-410e-be57-efed1fe6651d', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Which essential gas constitutes approximately 21% (nearly 1/5th) of air volume and supports animal respiration and fire combustion?', 'Oxygen makes up ~21% of clean air, essential for cellular aerobic respiration and chemical combustion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1b1317e-eb01-4cf1-8666-c6dbec1dab53', 'Oxygen (O₂)', true, 'd0988ecd-5632-410e-be57-efed1fe6651d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5be33416-944e-4e71-9aa2-3b659de18f6d', 'Nitrogen', false, 'd0988ecd-5632-410e-be57-efed1fe6651d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('207ca980-ed06-49f4-9563-0c91cb1ddcd1', 'Carbon dioxide', false, 'd0988ecd-5632-410e-be57-efed1fe6651d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74b1bf4d-d373-4718-95cb-daec8875ab78', 'Hydrogen', false, 'd0988ecd-5632-410e-be57-efed1fe6651d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fe90581-43f7-4cfb-b2f8-3367f0465a02', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'What happens when a burning candle is covered with an inverted glass tumbler?', 'Combustion requires continuous oxygen; once the enclosed oxygen is depleted, the flame extinguishes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f51b7608-47ea-4d59-8c37-e144b895b062', 'The candle flickers and goes out after a few moments because the limited oxygen inside the glass gets consumed completely', true, '5fe90581-43f7-4cfb-b2f8-3367f0465a02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83c66c32-4cbe-4a1c-9fa8-bef9d63d6deb', 'The candle burns twice as brightly', false, '5fe90581-43f7-4cfb-b2f8-3367f0465a02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22ffa2d3-8631-41ce-a447-239c5f65f26f', 'The glass tumbler melts instantly', false, '5fe90581-43f7-4cfb-b2f8-3367f0465a02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beb1afee-a781-4a0b-86b8-4761aa98bfc5', 'The candle turns into ice', false, '5fe90581-43f7-4cfb-b2f8-3367f0465a02');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e544fb8-ad1d-47e7-9733-6f3993a9de65', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Which component of air is responsible for the formation of clouds, mist, dew, and rain in nature?', 'Atmospheric water vapour evaporates from oceans/rivers and condenses at high altitudes to form cloud droplets and rain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abea4ef6-a5d8-44d1-bc18-6862e93e02bd', 'Water Vapour (Moisture)', true, '7e544fb8-ad1d-47e7-9733-6f3993a9de65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85fae4d1-2586-4c70-b05d-e85e6afdb4d5', 'Nitrogen', false, '7e544fb8-ad1d-47e7-9733-6f3993a9de65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c26223f9-937c-4224-bcb9-a1cff02eeeac', 'Smoke', false, '7e544fb8-ad1d-47e7-9733-6f3993a9de65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a658994-855a-4039-ab1f-2a9055a936da', 'Dust particles', false, '7e544fb8-ad1d-47e7-9733-6f3993a9de65');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a71a1ec1-b7dd-47ba-afb0-bea9b6888e64', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'What gas is produced during burning of fuels and animal respiration, and used by green plants for photosynthesis?', 'Carbon dioxide (~0.04% of air) is released by respiration/combustion and absorbed by plants during photosynthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8273d0e2-bd97-4cf6-8e40-029bbcf322f1', 'Carbon Dioxide (CO₂)', true, 'a71a1ec1-b7dd-47ba-afb0-bea9b6888e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1f912bc-e34a-49cf-ba54-458a670547ad', 'Oxygen', false, 'a71a1ec1-b7dd-47ba-afb0-bea9b6888e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac554a37-ec12-4971-9c2f-a852ccf7ad70', 'Nitrogen', false, 'a71a1ec1-b7dd-47ba-afb0-bea9b6888e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('193cbcae-4a7d-41c0-9e1f-892c84dc957d', 'Ozone', false, 'a71a1ec1-b7dd-47ba-afb0-bea9b6888e64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6002ee47-85de-44ee-ae01-03355adfa24b', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Why do mountaineers climbing very high Himalayan peaks carry heavy Oxygen Cylinders on their backs?', 'Atmospheric pressure and oxygen partial pressure decline with altitude, causing hypoxia without supplementary O₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d52fb59f-5b23-433a-9522-c8cbc4dcd52d', 'Because atmospheric air becomes progressively thinner and the density/availability of oxygen drops drastically at high altitudes', true, '6002ee47-85de-44ee-ae01-03355adfa24b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5898f23-6aa9-4e83-91b1-d021df76a105', 'To protect from bears', false, '6002ee47-85de-44ee-ae01-03355adfa24b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e5b5f12-e4fc-4fef-8d82-a5e1c00ba290', 'To cook food on snow', false, '6002ee47-85de-44ee-ae01-03355adfa24b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e32b0210-13b5-4dfd-95b2-09ff77b6b9f1', 'To make the backpack heavier for balance', false, '6002ee47-85de-44ee-ae01-03355adfa24b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecb63caa-7c52-4432-8576-2463b9766e2e', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'How do fish and other aquatic animals breathe underwater?', 'Fish pass oxygenated water over vascularized gill filaments, extracting dissolved O₂ via counter-current exchange.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38311693-fc13-4e06-9767-30bd514b39bb', 'They absorb Dissolved Oxygen from water through their specialized feather-like Gills', true, 'ecb63caa-7c52-4432-8576-2463b9766e2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e57c1234-c9e4-41f7-a18b-fdf5999166cf', 'They hold their breath forever', false, 'ecb63caa-7c52-4432-8576-2463b9766e2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('950b88f1-d5bb-411e-89e2-3bb7e266c2f8', 'They breathe water vapour from clouds', false, 'ecb63caa-7c52-4432-8576-2463b9766e2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('752179fb-7200-4cc6-9ebb-5d99a5c0fd5b', 'They eat oxygen rocks', false, 'ecb63caa-7c52-4432-8576-2463b9766e2e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29d9c953-a635-4a73-baed-9f4fcb71a235', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Why do Earthworms and burrowing soil animals come out of their underground burrows to the surface only during HEAVY RAINFALL?', 'Waterlogged soils displace pore air; earthworms must surface to respire cutaneously across moist skin.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc54219d-53b5-48ea-a281-ac13e97b918d', 'Heavy rainwater fills up all air spaces and pores in the soil, forcing earthworms to the surface to breathe oxygen', true, '29d9c953-a635-4a73-baed-9f4fcb71a235');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80978360-e868-4b8e-8f35-8adafd0a07ee', 'Because they like to swim in puddles', false, '29d9c953-a635-4a73-baed-9f4fcb71a235');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cdb52e8-e0ff-44b0-bb0d-a970027e9536', 'To wash their bodies', false, '29d9c953-a635-4a73-baed-9f4fcb71a235');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c14fab40-c6c2-41e7-a2a8-819dfc7ecf27', 'Because soil becomes too hot', false, '29d9c953-a635-4a73-baed-9f4fcb71a235');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92df07ad-bc16-40bf-97b4-4cdf1fd44921', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'What is a simple rotating paper toy on a stick that spins furiously when you run with it or blow on it?', 'A firki rotates due to kinetic wind pressure against its angled vanes, demonstrating that air exerts mechanical force.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f48dbfa5-c87a-4a29-bee9-c2bf3875245a', 'Firki (Pinwheel)', true, '92df07ad-bc16-40bf-97b4-4cdf1fd44921');
