INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ad8a448-b9b0-4373-9cb1-b68a0c5915d7', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'What large mechanical structure with rotating blades harnesses wind energy to pump water, grind grain, or generate clean electricity?', 'Windmills convert atmospheric wind kinetic energy into rotational mechanical and electrical power.', NOW()) ON CONFLICT DO NOTHING;
