INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20fbe531-2d8b-4ac1-9e1a-961b50ec8f35', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'How can you prove experimentally that an apparently ''empty'' open glass bottle is actually FULL of air?', 'Trapped air exerts internal pressure blocking water entry until tilting lets air bubble out, proving air occupies volume.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6148715e-2ac1-4dc5-a2b3-b38b36c33f88', 'Invert the bottle vertically into a bucket of water; water cannot enter until you tilt the bottle slightly, allowing air bubbles to escape with a gurgling sound', true, '20fbe531-2d8b-4ac1-9e1a-961b50ec8f35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8d0cf6f-0ae5-4437-b4a2-eea4cf6f00a7', 'By looking through the glass with sunglasses', false, '20fbe531-2d8b-4ac1-9e1a-961b50ec8f35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9176e9cd-816e-40e6-b0b2-3f46c4e63c3b', 'By smelling the bottle', false, '20fbe531-2d8b-4ac1-9e1a-961b50ec8f35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab353ebb-a01a-466a-b6cd-e8d8974d9085', 'By dropping the bottle on the floor', false, '20fbe531-2d8b-4ac1-9e1a-961b50ec8f35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cf21183-ea0e-46e1-b25d-c29151f4021a', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why does a lump of dry soil produce fizzing bubbles when dropped into a glass beaker of water?', 'Capillary suction of water displaces interstitial soil air, generating effervescent bubbles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a014c240-5aa6-45db-9e73-9600d4c4f224', 'Water enters the microscopic pores of the dry soil, displacing the air trapped inside soil particles which escapes upward as visible bubbles', true, '6cf21183-ea0e-46e1-b25d-c29151f4021a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b56b5270-394b-4e39-aa31-f7c3aa5f40b5', 'Because soil is boiling hot', false, '6cf21183-ea0e-46e1-b25d-c29151f4021a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f3e22f1-f7ec-4af5-b3e4-5c638de84ad5', 'Because soil reacts with water chemically to make poison', false, '6cf21183-ea0e-46e1-b25d-c29151f4021a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28e5d9ce-d45d-4406-8cc5-603e623c256c', 'Because soil has soap in it', false, '6cf21183-ea0e-46e1-b25d-c29151f4021a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f52541b8-6c9a-462c-a9f4-5dc0971c92f5', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why do tiny water droplets appear on the outer glass surface of a tumbler containing ice-cold water?', 'Ambient water vapour cools below its dew point against cold glass, condensing into liquid droplets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e5675ba-c490-4f02-96ba-0c260a7b6006', 'Water vapour present in the surrounding air comes in contact with the cold glass surface and CONDENSES into liquid water droplets', true, 'f52541b8-6c9a-462c-a9f4-5dc0971c92f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bd5db24-b138-4941-ae05-3fc4aea45569', 'Water leaks through the solid glass wall', false, 'f52541b8-6c9a-462c-a9f4-5dc0971c92f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3479d6e5-94b4-4191-9856-086c5997e3e2', 'Ice melts through the top', false, 'f52541b8-6c9a-462c-a9f4-5dc0971c92f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c701eb2-4e36-4bfb-95c8-d26f00450039', 'The glass tumbler sweats like skin', false, 'f52541b8-6c9a-462c-a9f4-5dc0971c92f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0668b9af-32d5-4b0d-9632-dcb17070c183', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'How is the delicate balance of Oxygen and Carbon Dioxide maintained in Earth''s atmosphere?', 'Photosynthetic O₂ release by plants balances respiration and combustion CO₂ emissions across the biosphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42f5ad2d-01d7-4af8-b93f-262fbd54f5ea', 'Plants produce excess Oxygen during daytime Photosynthesis and consume Carbon Dioxide, while animals and humans inhale Oxygen and exhale Carbon Dioxide (Oxygen-Carbon Dioxide Cycle)', true, '0668b9af-32d5-4b0d-9632-dcb17070c183');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ef8ddb9-59fe-42f8-ad7e-3343434f1ab8', 'Volcanoes pump oxygen into the sky', false, '0668b9af-32d5-4b0d-9632-dcb17070c183');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ef41ee9-2c34-4e92-a2e6-c54327d52303', 'Windmills manufacture oxygen', false, '0668b9af-32d5-4b0d-9632-dcb17070c183');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e55a3838-7919-4f1e-addf-ca34760b19bf', 'Oxygen comes from the moon', false, '0668b9af-32d5-4b0d-9632-dcb17070c183');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25f7d7dd-2aa0-4cc3-b48a-3feeb1764266', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why are tall chimneys installed in factories and industrial plants?', 'High stack chimneys disperse industrial effluents into higher atmospheric winds, reducing ground-level pollution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbfb67e4-81f9-45d8-8cea-e1477e2eab07', 'To release harmful smoke, dust, and toxic fumes high up into the upper atmosphere, away from ground-level human habitats', true, '25f7d7dd-2aa0-4cc3-b48a-3feeb1764266');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99ceffa7-4d64-4b2b-8a22-1fca3d159e67', 'To catch birds', false, '25f7d7dd-2aa0-4cc3-b48a-3feeb1764266');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47ba661b-5a58-41b8-8449-3afdd164ee0f', 'To make rain fall faster', false, '25f7d7dd-2aa0-4cc3-b48a-3feeb1764266');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df773220-136c-40eb-8c0b-7d8bcdc7c2c9', 'To make the factory look taller', false, '25f7d7dd-2aa0-4cc3-b48a-3feeb1764266');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('417bc429-1e69-49eb-9606-a3db05525d22', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why do we see tiny dancing, glittering dust particles in a dark room when a narrow beam of sunlight enters through a small slit?', 'Tyndall scattering by aerosolized particulate matter illuminates suspended dust in colloidal air.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10affb4c-33ce-4315-adbe-a81bf255677f', 'The sunbeam illuminates microscopic solid Dust particles suspended in air, which scatter light (Tyndall Effect / Brownian motion)', true, '417bc429-1e69-49eb-9606-a3db05525d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db923459-74d0-45be-9306-7fa8daabceab', 'They are tiny flying insects', false, '417bc429-1e69-49eb-9606-a3db05525d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02acd765-276c-48e2-920e-ded9e2c9ba71', 'The sun rays are breaking into pieces', false, '417bc429-1e69-49eb-9606-a3db05525d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd01656d-2700-44ab-ac57-05f8291d2b8e', 'They are magic sparks', false, '417bc429-1e69-49eb-9606-a3db05525d22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('70e92b24-29e6-4042-a2a9-aec568707682', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why is it strictly recommended to breathe through the NOSE rather than through the MOUTH?', 'Nasal turbinates and mucociliary clearance humidify, warm, and filter airborne aerosols before reaching alveolar lungs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b4cbcfe-fdb4-4aeb-8ff9-c9427b0aab2b', 'Fine hairs (cilia) and sticky mucus lining inside nasal passages filter out dust particles, pollen, and microbes, preventing them from entering the lungs', true, '70e92b24-29e6-4042-a2a9-aec568707682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('355121bc-2f2f-405d-9089-f1d8beb057a4', 'Because mouth breathing makes you thirsty', false, '70e92b24-29e6-4042-a2a9-aec568707682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b4b0752-cf53-42eb-abee-5ad81bdd831b', 'Because mouth has no teeth for air', false, '70e92b24-29e6-4042-a2a9-aec568707682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a2e8a49-5277-47b0-9bec-6100dfff4f9e', 'Because nose makes air colder', false, '70e92b24-29e6-4042-a2a9-aec568707682');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9317f4d8-019f-4c6a-b36a-0c9619df068e', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'What instrument is installed on top of tall buildings to indicate the DIRECTION from which the wind is blowing?', 'A wind vane rotates freely on a vertical axis; its tail fin orients the pointer into the wind source direction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('150b88d9-d1c7-42a4-8ccd-c057813f6d56', 'Wind Vane (Weather Vane)', true, '9317f4d8-019f-4c6a-b36a-0c9619df068e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c805365f-e42f-4e3a-baca-ddd843bcc6d5', 'Anemometer', false, '9317f4d8-019f-4c6a-b36a-0c9619df068e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdcfc31d-2287-4258-a55a-a2f56e233c1a', 'Barometer', false, '9317f4d8-019f-4c6a-b36a-0c9619df068e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1408448c-d2f2-469a-9fd5-ee6a50187370', 'Hygrometer', false, '9317f4d8-019f-4c6a-b36a-0c9619df068e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22ae6b3e-2bcc-4d48-a934-c2155bdf5b1c', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'How do plant seeds (like Dandelion, Maple, and Drumstick) disperse across vast distances?', 'Anemochory: aerodynamic samaras and pappus hairs utilize wind drift for long-distance seed dispersal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e34c6afc-7cc4-4e6f-a886-b7332bfdba57', 'They possess feather-like tufts, parachutes, or wings that catch atmospheric wind currents and float across kilometres', true, '22ae6b3e-2bcc-4d48-a934-c2155bdf5b1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('490e5a08-0e5a-4c0e-912b-7b67f7758fb8', 'They swim across oceans', false, '22ae6b3e-2bcc-4d48-a934-c2155bdf5b1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07a302c7-b41d-43a5-9bcb-39bc37723cd4', 'They walk on tiny roots', false, '22ae6b3e-2bcc-4d48-a934-c2155bdf5b1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dc13634-4e61-493f-8608-395d4d2626fa', 'They explode like fireworks', false, '22ae6b3e-2bcc-4d48-a934-c2155bdf5b1c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e201e8c-5ca5-4424-a0c6-b294d0ad69d7', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'What role does air play in the transmission of SOUND from one place to another?', 'Mechanical sound waves require molecular compression and rarefaction across an elastic fluid medium like air.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('790ddfdd-585d-4671-a450-c5d062391378', 'Air provides the physical material medium through which sound pressure waves propagate; sound cannot travel through a vacuum', true, '5e201e8c-5ca5-4424-a0c6-b294d0ad69d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('319a4f49-2f51-403f-8743-2225002e9575', 'Air blocks all sounds', false, '5e201e8c-5ca5-4424-a0c6-b294d0ad69d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('112db8c8-2776-4c06-9cf8-84866d93a25c', 'Air creates sound out of light', false, '5e201e8c-5ca5-4424-a0c6-b294d0ad69d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd579139-346d-414b-baef-b60156c641ea', 'Sound only travels through metal wires', false, '5e201e8c-5ca5-4424-a0c6-b294d0ad69d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d98fc4a0-8b8a-4ced-a4bf-26a37b347697', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why does air bubble out when water is boiled in a glass pan long before it reaches 100°C?', 'Gas solubility in liquids decreases with rising temperature, driving dissolved air out of solution as bubbles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('319cc48d-ec58-49b1-94af-3d09b73adf06', 'Dissolved air in the water expands due to heating and escapes as tiny air bubbles from the pan floor', true, 'd98fc4a0-8b8a-4ced-a4bf-26a37b347697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('674dad70-1de2-4c6e-adc2-60f3a622da58', 'Because glass creates bubbles', false, 'd98fc4a0-8b8a-4ced-a4bf-26a37b347697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7f51f9e-bd34-4fa5-b2b2-1d4223b77dc4', 'Because water turns into ice', false, 'd98fc4a0-8b8a-4ced-a4bf-26a37b347697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d3b1a12-db97-4a26-bf38-e0e07a645636', 'Because heat destroys water molecules instantly', false, 'd98fc4a0-8b8a-4ced-a4bf-26a37b347697');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e570d0dd-bb66-4452-82f3-6260a98e4075', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why can sailing yachts and gliders navigate across water and skies without engines?', 'Aerodynamic lift and drag forces produced by wind airflow propel yachts and gliders.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00450aa7-3919-4141-aeda-9ee77b5e8e80', 'They harness the aerodynamic thrust and lift generated by moving air (wind) pushing against canvas sails and aerofoil wings', true, 'e570d0dd-bb66-4452-82f3-6260a98e4075');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0edda67-5c3f-417f-a19b-7202865e0144', 'They are pulled by magnetic rocks', false, 'e570d0dd-bb66-4452-82f3-6260a98e4075');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef043993-f757-49d1-891d-17b900cb6452', 'They slide on cloud ice', false, 'e570d0dd-bb66-4452-82f3-6260a98e4075');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a8d181-7098-4d89-a9fc-08cc4a326dd8', 'They float on solar rays', false, 'e570d0dd-bb66-4452-82f3-6260a98e4075');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ab7f0a3-30a3-451f-b153-f059a39a364f', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'What are the three essential components that must be present together for Combustion (burning) to occur?', 'The classical Fire Triangle requires three elements: Combustible Fuel, Oxidizer (O₂), and Heat (ignition threshold).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('972416e6-9c28-4567-ab6d-98358843cb51', 'Fuel (combustible substance), Oxygen (supporter of combustion), and Ignition Temperature (heat)', true, '0ab7f0a3-30a3-451f-b153-f059a39a364f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3a9a1e6-5ac8-4129-a7cc-6a4954055f98', 'Water, Wood, and Plastic', false, '0ab7f0a3-30a3-451f-b153-f059a39a364f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa42b6c0-9751-45c3-96a0-4f547d6a1b21', 'Nitrogen, Carbon, and Ash', false, '0ab7f0a3-30a3-451f-b153-f059a39a364f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acbe88e3-0601-4bc8-ac7c-e2d2093838cb', 'Glass, Iron, and Air', false, '0ab7f0a3-30a3-451f-b153-f059a39a364f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98d7afb7-dca0-4d99-a222-934e012521fb', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why does a traffic police officer standing at a busy intersection often wear a protective face mask?', 'Particulate masks filter toxic combustion emissions (PM2.5, NOₓ, CO) at congested traffic junctions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a0c10d4-ace8-4b08-b94f-58239ccbe209', 'To protect lungs from inhaling vehicular exhaust containing unburnt carbon soot, toxic carbon monoxide, and lead particulates', true, '98d7afb7-dca0-4d99-a222-934e012521fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45bd7aac-593c-4cc7-bf2f-f7c2a80bfb1f', 'To hide identity', false, '98d7afb7-dca0-4d99-a222-934e012521fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9e711ac-df41-4e06-89da-5fcd849fd9a0', 'To keep face warm in summer', false, '98d7afb7-dca0-4d99-a222-934e012521fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6e6c8ba-98ba-46e6-b07f-4540e7c8f6ec', 'To amplify voice', false, '98d7afb7-dca0-4d99-a222-934e012521fb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21cea99a-1311-4b1e-a0f1-2dd5b8161c16', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why is Nitrogen gas in air essential for plant life even though plants cannot absorb it directly through leaves?', 'Biological nitrogen fixation converts inert atmospheric N₂ into bioavailable ammonium and nitrate for plant amino acids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8573cc6a-2505-4e1a-ada4-ff8600d1e0ee', 'Soil bacteria (like Rhizobium) fix atmospheric nitrogen into soluble nitrates that plant roots absorb to synthesize essential proteins', true, '21cea99a-1311-4b1e-a0f1-2dd5b8161c16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad3f98c5-7d8a-43a9-8531-c49c540503a2', 'Nitrogen gives green color to leaves', false, '21cea99a-1311-4b1e-a0f1-2dd5b8161c16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c4c7062-44ae-4c74-8c22-d6223496c321', 'Nitrogen makes fruits sweet', false, '21cea99a-1311-4b1e-a0f1-2dd5b8161c16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c509dcf-ac59-45c4-a046-39d269ad2d29', 'Nitrogen turns into water inside roots', false, '21cea99a-1311-4b1e-a0f1-2dd5b8161c16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('008883fc-f2d1-4391-8638-ec9a9910305a', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why does an inflated balloon burst when left in hot scorching sunlight for a long time?', 'Charles''s Law: thermal kinetic energy increases gas volume and internal pressure (P ∝ T), rupturing the elastic membrane.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2b801d1-bb7c-4332-8c23-15d90baf5141', 'Heat energy causes the air molecules trapped inside the balloon to expand and exert higher internal pressure against the rubber until it bursts', true, '008883fc-f2d1-4391-8638-ec9a9910305a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('041b6cfe-893a-48d0-994b-76f258e7b3be', 'The rubber melts from sun rays', false, '008883fc-f2d1-4391-8638-ec9a9910305a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('624b0e2b-5254-4c01-9d95-6b4f32e4ba96', 'Sunlight sucks the air out', false, '008883fc-f2d1-4391-8638-ec9a9910305a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('237e8078-2742-4d09-9549-7447468eb797', 'The balloon turns into glass', false, '008883fc-f2d1-4391-8638-ec9a9910305a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a241181-626a-43c3-b85b-e0129c248e0e', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70027413-486d-495d-93e1-4302052c91a3', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '3a241181-626a-43c3-b85b-e0129c248e0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebbf44ac-08c1-4893-8ec3-8e45bc20d1d0', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '3a241181-626a-43c3-b85b-e0129c248e0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('668b29b2-003c-427e-8d5b-3b05e02836ca', '(A) is true, but (R) is false.', false, '3a241181-626a-43c3-b85b-e0129c248e0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56b973a5-c907-4664-a2bf-39497fa0e4d2', '(A) is false, but (R) is true.', false, '3a241181-626a-43c3-b85b-e0129c248e0e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f699564e-2260-4b67-8e77-69476c518fac', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Spot the IMPOSTER in the following group of atmospheric air properties:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9cc5ede-8286-4609-bf44-ef1a9c8d4052', 'Air occupies space', false, 'f699564e-2260-4b67-8e77-69476c518fac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d015f208-1b23-4aab-b38f-6bb8910aa257', 'Air has mass/weight', false, 'f699564e-2260-4b67-8e77-69476c518fac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82fd843c-4311-485b-bc54-d9f3a57980ce', 'Air is a pure single element', true, 'f699564e-2260-4b67-8e77-69476c518fac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2934162-6908-4b51-838b-9eb7fb7a04b4', 'Air exerts atmospheric pressure in all directions', false, 'f699564e-2260-4b67-8e77-69476c518fac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ab6c73f-7eec-4a91-9aa7-117283ae663b', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'A scientist collects 100 litres of clean, dry atmospheric air at sea level. What is the approximate volume of NITROGEN and OXYGEN present in the sample?', 'Volumetric composition of dry atmospheric air: 78.08% N₂, 20.95% O₂, 0.93% Ar, 0.04% CO₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae9f0e9f-582a-43da-a035-ce116c38bcf3', 'Nitrogen: ~78 litres ; Oxygen: ~21 litres', true, '5ab6c73f-7eec-4a91-9aa7-117283ae663b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc43dc43-c20d-468d-9fd3-fc3b29e2a90c', 'Nitrogen: 50 litres ; Oxygen: 50 litres', false, '5ab6c73f-7eec-4a91-9aa7-117283ae663b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82d2d5bf-f6f7-4372-818d-53f7caf840db', 'Nitrogen: 21 litres ; Oxygen: 78 litres', false, '5ab6c73f-7eec-4a91-9aa7-117283ae663b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb0588a7-7372-493c-a54a-5dd33f047810', 'Nitrogen: 90 litres ; Oxygen: 10 litres', false, '5ab6c73f-7eec-4a91-9aa7-117283ae663b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a51a217-a023-4131-809c-0dff192e4ce7', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Match Column I (Atmospheric Constituents) with Column II (Biological & Environmental Roles):
(a) Oxygen (21%)        -> (i) Respiration & supporter of combustion
(b) Carbon Dioxide (0.04%)-> (ii) Raw material for plant photosynthesis
(c) Nitrogen (78%)      -> (iii) Dilutes oxygen & provides protein building blocks via fixation
(d) Water Vapour        -> (iv) Drives hydrological cycle, clouds & precipitation', 'Oxygen = respiration; CO₂ = photosynthesis; Nitrogen = protein fixation; Water vapour = precipitation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c434e2cc-a34b-4b6e-8a02-bc563a96d6f7', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '6a51a217-a023-4131-809c-0dff192e4ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f738d72-282e-4cf5-8a8d-3084ce84d64a', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '6a51a217-a023-4131-809c-0dff192e4ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2edbac7-c2c2-4f58-a442-d500399cd6d4', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '6a51a217-a023-4131-809c-0dff192e4ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('839bb9f4-6d1f-4e5b-ace7-1c3fd31f6a10', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '6a51a217-a023-4131-809c-0dff192e4ce7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4fd27a8d-730d-4e2f-9e29-e27f73eb45f9', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Read the statements regarding respiration:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6401874b-4523-4bb4-861e-3f81718580c1', 'Statements 1 and 2 only', true, '4fd27a8d-730d-4e2f-9e29-e27f73eb45f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c53695e8-8d87-42f0-9115-787361938af0', 'Statements 2 and 3 only', false, '4fd27a8d-730d-4e2f-9e29-e27f73eb45f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a31ece36-e57b-44d1-aab3-daee20355669', 'Statements 1 and 3 only', false, '4fd27a8d-730d-4e2f-9e29-e27f73eb45f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6da74af-f43b-4f60-9551-1d2b16516ba7', 'All Statements 1, 2, and 3', false, '4fd27a8d-730d-4e2f-9e29-e27f73eb45f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f2cab40-16c4-442b-a600-a84fcebc741d', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Why does a suction rubber sucker stick firmly to a smooth glass or tiled wall when pressed hard?', 'Evacuating internal air creates a partial vacuum (P_inside < P_atm); external atmospheric pressure (101.3 kPa) pins the sucker.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9557026c-f51d-4fb0-bece-1b708184ed13', 'Pressing the sucker pushes out most of the air between the cup and surface; external atmospheric air pressure presses down hard on the outside, holding it tightly', true, '8f2cab40-16c4-442b-a600-a84fcebc741d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc562cd7-40c4-4501-b6e6-36d67b001427', 'Because rubber has chemical glue', false, '8f2cab40-16c4-442b-a600-a84fcebc741d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a7a7519-e373-49f4-a250-4637f173996c', 'Because the glass melts onto rubber', false, '8f2cab40-16c4-442b-a600-a84fcebc741d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17630817-b147-43e4-bacd-bdd1d57234e4', 'Because of magnetic attraction', false, '8f2cab40-16c4-442b-a600-a84fcebc741d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4783ada-a812-4157-93ea-23397e7eb71e', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'How do mangroves and marsh plants growing in waterlogged saline mud adapt to breathe in oxygen-deficient soils?', 'Negatively geotropic pneumatophores with lenticels project above tidal water, ventilating root aerenchyma tissue.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51dc88bf-6752-4ec2-bf25-b13ace1405c4', 'They produce specialized vertical aerial roots called Pneumatophores (Breathing Roots) that grow upward out of the mud to absorb air directly from the atmosphere', true, 'e4783ada-a812-4157-93ea-23397e7eb71e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5de5f00-79ca-4c83-834e-71cb1e2455d0', 'They absorb air through flowers', false, 'e4783ada-a812-4157-93ea-23397e7eb71e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('900141be-bcec-46c4-9e6a-46661febeab5', 'They stop breathing completely', false, 'e4783ada-a812-4157-93ea-23397e7eb71e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98ebce38-5f34-45e4-b603-1be1cc72ffac', 'They store oxygen in seeds', false, 'e4783ada-a812-4157-93ea-23397e7eb71e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90bd5562-dc61-436e-bb60-956affbaaaed', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Why does atmospheric pressure decrease progressively as you climb higher up a mountain?', 'Barometric equation: hydrostatic pressure equals the integrated mass of the overlying air column, decaying exponentially with altitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74601cce-6afd-4fd1-a584-4d0c0667dafe', 'Because the total vertical column and density of air molecules lying above decreases, exerting less downward gravitational weight per unit area', true, '90bd5562-dc61-436e-bb60-956affbaaaed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb42127c-80d0-4250-921d-125d06e60bb8', 'Because gravity turns off in mountains', false, '90bd5562-dc61-436e-bb60-956affbaaaed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55f15097-db06-4e03-80db-17d47a46ff41', 'Because cold air has no weight', false, '90bd5562-dc61-436e-bb60-956affbaaaed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('498c1b23-a429-465e-88e9-15c4d9703ee1', 'Because clouds absorb air pressure', false, '90bd5562-dc61-436e-bb60-956affbaaaed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b16b0f7-4cc0-4d42-a300-78ff1fcd63b1', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'What would happen to all life on Earth if the Atmosphere were completely absent?', 'The atmosphere provides respiration gases, radiative greenhouse buffering, meteor friction shield, and UV absorption.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a3a4d9a-e3f0-4ace-8daa-2d2ac0cf923b', 'All living organisms would die instantly from asphyxiation, daytime surface temperatures would soar to +120°C and plunge to -180°C at night, and lethal cosmic rays would bombard the surface', true, '9b16b0f7-4cc0-4d42-a300-78ff1fcd63b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6e654ce-c7be-4b2e-860e-acfcf1e2b8d2', 'Plants would grow twice as fast', false, '9b16b0f7-4cc0-4d42-a300-78ff1fcd63b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a32d818-8bca-4f7e-bfe7-96d0d658a7bb', 'Oceans would freeze into pure gold', false, '9b16b0f7-4cc0-4d42-a300-78ff1fcd63b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2e528c9-2e80-4c76-bf2f-43e0eb434b58', 'Earth would become lighter and float away', false, '9b16b0f7-4cc0-4d42-a300-78ff1fcd63b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fb7324b-a645-4c07-9f62-6fb42bac6a95', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Why does a glass tumbler filled completely with water, covered with a flat cardboard card, and inverted upside down NOT spill water?', 'Atmospheric pressure (~101,300 Pa) dwarfs the ~1,000 Pa downward hydrostatic column of water, holding the card in equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb6ce882-f72d-43dc-b6f9-fe95592fac4f', 'The upward atmospheric pressure exerted by outside air against the underside of the cardboard card is greater than the downward hydrostatic pressure of water', true, '9fb7324b-a645-4c07-9f62-6fb42bac6a95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16f4a3b1-096e-46ce-a5a3-68cbefb118bd', 'Because the card glues to water', false, '9fb7324b-a645-4c07-9f62-6fb42bac6a95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4011f48-da31-4939-8aac-b422d5a9f43c', 'Because water freezes instantly', false, '9fb7324b-a645-4c07-9f62-6fb42bac6a95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3833d016-c78c-45cd-b871-94191c9e3f23', 'Because gravity stops working upside down', false, '9fb7324b-a645-4c07-9f62-6fb42bac6a95');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff4ce81a-533b-4327-9c02-8563e6dba293', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'What is ''Smog'' and why is it a dangerous environmental hazard in cities during winter?', 'Thermal inversion traps particulates and photochemical/sulfurous emissions in winter fog, forming hazardous smog.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd69d319-5e92-43d2-8724-211d245a40cf', 'A toxic colloidal mixture of Smoke and Fog containing particulate soot and sulfur oxides that causes acute bronchitis, asthma, and severe visibility reduction', true, 'ff4ce81a-533b-4327-9c02-8563e6dba293');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0fa1b95-0064-46ac-b9c7-405879bdde53', 'A cloud made of pure steam', false, 'ff4ce81a-533b-4327-9c02-8563e6dba293');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da5b504a-b3c0-4bfe-9de0-38a5f8faed30', 'A harmless morning mist', false, 'ff4ce81a-533b-4327-9c02-8563e6dba293');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80aec024-c3dd-4275-91c7-5774e00d157a', 'Dust from the moon', false, 'ff4ce81a-533b-4327-9c02-8563e6dba293');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20c4d3ca-24ef-477f-a1bd-9dbfeb4e937f', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'What crucial layer in the upper stratosphere shields life on Earth from harmful solar Ultraviolet (UV) radiation?', 'Stratospheric ozone photolytically absorbs high-energy UV-B radiation (280–315 nm), preventing cellular DNA mutagenesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d39884aa-f968-40f6-a238-c11185519429', 'The Ozone Layer (O₃)', true, '20c4d3ca-24ef-477f-a1bd-9dbfeb4e937f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4164c24-412b-4ef3-bcbf-16bb3ecb314e', 'The Ionosphere', false, '20c4d3ca-24ef-477f-a1bd-9dbfeb4e937f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81631224-f7b4-4d9a-a977-4104bb3d2abe', 'The Troposphere', false, '20c4d3ca-24ef-477f-a1bd-9dbfeb4e937f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e482998d-698c-4fbb-90ba-c5484a2d3e6e', 'The Exosphere', false, '20c4d3ca-24ef-477f-a1bd-9dbfeb4e937f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e9b786b-a06b-4b9b-924f-1c8f8af0a1b7', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'A symbol or letter (such as x, y, z, m, n, a, b) that does NOT have a fixed value and can take different numerical values is called a:', 'A variable represents an unknown quantity whose value varies, denoted by English alphabetic letters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfbfe576-90e1-47c1-b662-a4fa594f7daf', 'Variable', true, '7e9b786b-a06b-4b9b-924f-1c8f8af0a1b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38116ae2-d16b-4ddc-b478-cd52d2e3e89c', 'Constant', false, '7e9b786b-a06b-4b9b-924f-1c8f8af0a1b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('606082fc-6840-4ad0-967a-14f21d4413aa', 'Fraction', false, '7e9b786b-a06b-4b9b-924f-1c8f8af0a1b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e49c4fbc-4b4e-44cb-8115-0bc154bc62a0', 'Integer', false, '7e9b786b-a06b-4b9b-924f-1c8f8af0a1b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac772a7b-8259-4af8-b7a7-499a7d6c0db3', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'A quantity that has a fixed numerical value (such as 5, -8, 12, 100) that never changes is called a:', 'A constant possesses a fixed, definite mathematical magnitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17c8ff4c-68cf-496b-bb6d-d988fe2082fe', 'Constant', true, 'ac772a7b-8259-4af8-b7a7-499a7d6c0db3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f384d751-373d-421d-b3b4-f050174ab773', 'Variable', false, 'ac772a7b-8259-4af8-b7a7-499a7d6c0db3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd0fd88b-7399-4d10-866b-feab755d755f', 'Equation', false, 'ac772a7b-8259-4af8-b7a7-499a7d6c0db3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2d8506a-dc19-4b39-a1d0-fd2e9f5257b4', 'Expression', false, 'ac772a7b-8259-4af8-b7a7-499a7d6c0db3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22b32342-6fe9-45b7-897e-bc2964e7df68', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'To form the letter ''L'' using matchsticks, 2 matchsticks are required for 1 ''L''. What is the algebraic rule for the number of matchsticks required to make ''n'' number of ''L''s?', '1 ''L'' = 2 matchsticks; n ''L''s = 2 × n = 2n matchsticks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31d0a07a-e130-4414-bf4c-86af484c860b', '2n (2 × n)', true, '22b32342-6fe9-45b7-897e-bc2964e7df68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('706d8eb2-9671-44b6-81cb-30622edcd55f', 'n + 2', false, '22b32342-6fe9-45b7-897e-bc2964e7df68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0362a419-4b30-4b0d-89fc-ce42f5868a6c', '2 + n', false, '22b32342-6fe9-45b7-897e-bc2964e7df68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e18a0438-c99d-44cf-8197-a599432cf4fd', 'n / 2', false, '22b32342-6fe9-45b7-897e-bc2964e7df68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ec8e394-4465-46a2-b0b5-52c9f01df9ee', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'To form the letter ''C'' using matchsticks, 3 matchsticks are required for each ''C''. How many matchsticks are needed to form 8 ''C''s?', 'Rule is 3n. For n = 8, matchsticks = 3 × 8 = 24.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49afcc6b-c645-4a6b-b440-0eb1f4348a0e', '24 matchsticks (Rule: 3n = 3 × 8 = 24)', true, '0ec8e394-4465-46a2-b0b5-52c9f01df9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b293944-9bbb-4b27-a922-3a8c67e09e3e', '16 matchsticks', false, '0ec8e394-4465-46a2-b0b5-52c9f01df9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e04b2969-b806-4855-b242-74449b1104ea', '11 matchsticks', false, '0ec8e394-4465-46a2-b0b5-52c9f01df9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df5bb95d-2d9c-4937-8084-ee2c7e515924', '32 matchsticks', false, '0ec8e394-4465-46a2-b0b5-52c9f01df9ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30ea1029-634e-4105-9dba-d9592a617e22', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'How is the statement ''7 added to x'' written as an algebraic expression?', '''7 added to x'' maps directly to addition: x + 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed05a817-5d49-47ee-a7a1-389958575acd', 'x + 7 (or 7 + x)', true, '30ea1029-634e-4105-9dba-d9592a617e22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06d34d82-a7cb-4154-89d7-3cd8cfd887d4', '7x', false, '30ea1029-634e-4105-9dba-d9592a617e22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1e85336-de50-418d-8081-c6fd698034d5', 'x - 7', false, '30ea1029-634e-4105-9dba-d9592a617e22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5030dbf-eeae-4dc8-8dce-ce331a200967', 'x / 7', false, '30ea1029-634e-4105-9dba-d9592a617e22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7a9cb02-04e9-455b-9fda-160fb8efc115', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'How is the statement ''y multiplied by 5 and then 3 subtracted from the result'' written algebraically?', '(y × 5) - 3 = 5y - 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('597e9796-1821-4433-99fc-250c8ef9300d', '5y - 3', true, 'd7a9cb02-04e9-455b-9fda-160fb8efc115');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d889cb06-c5ee-426e-9fb5-29823c2c1660', '5y + 3', false, 'd7a9cb02-04e9-455b-9fda-160fb8efc115');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e84c4082-45c0-494a-b926-57d6345b9d23', '3 - 5y', false, 'd7a9cb02-04e9-455b-9fda-160fb8efc115');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f73afe60-40f7-45d9-a172-16fb352bea0c', 'y/5 - 3', false, 'd7a9cb02-04e9-455b-9fda-160fb8efc115');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25839968-32b0-4725-b54b-f241bc4158a3', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'A mathematical statement with an EQUALITY sign ''='' between two expressions (such as 2x + 5 = 15) is called an:', 'An algebraic equation establishes that two mathematical expressions have identical value using the equality symbol ''=''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e029f3f8-72e4-41fe-abd2-48b87a0be1ff', 'Equation', true, '25839968-32b0-4725-b54b-f241bc4158a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c79a7998-0649-4781-a769-add72c2d27cd', 'Expression', false, '25839968-32b0-4725-b54b-f241bc4158a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1de906ae-f017-4145-a388-c051b75d3ae4', 'Inequality', false, '25839968-32b0-4725-b54b-f241bc4158a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9447747-fd96-4e25-b984-4b0ed47c6381', 'Polynomial', false, '25839968-32b0-4725-b54b-f241bc4158a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9052b50c-138a-474a-94e2-d2ea1e97f587', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'The value of a variable that satisfies an equation (makes LHS = RHS) is called the:', 'A solution is a specific numerical value of the variable for which the Left Hand Side equals the Right Hand Side.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26b7694f-2e3a-495f-b4e6-49af2e263c9a', 'Solution (or Root) of the equation', true, '9052b50c-138a-474a-94e2-d2ea1e97f587');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51c50085-4a52-48a6-9cab-a4c9abc1574e', 'Constant', false, '9052b50c-138a-474a-94e2-d2ea1e97f587');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('196c5ec3-d795-448e-b36c-d686a06d5dcf', 'Coefficient', false, '9052b50c-138a-474a-94e2-d2ea1e97f587');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1a9b809-e2a3-4516-8d5e-ce84a47d97b9', 'Term', false, '9052b50c-138a-474a-94e2-d2ea1e97f587');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16e3e95d-c3c2-4a61-a13e-805da80f2b11', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'Solve the simple linear equation: x + 6 = 15. What is the value of x?', 'x = 15 - 6 = 9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6877dd3a-f2c2-4b8b-80c2-e0bba17319c9', 'x = 9 (15 - 6 = 9)', true, '16e3e95d-c3c2-4a61-a13e-805da80f2b11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f615060f-4bc9-4ae8-89e3-32c87322fcfa', 'x = 21', false, '16e3e95d-c3c2-4a61-a13e-805da80f2b11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7aaa0296-9316-4737-9afe-056caaaff066', 'x = 90', false, '16e3e95d-c3c2-4a61-a13e-805da80f2b11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c76721d0-d9c0-4802-aa61-d3790a1ad80f', 'x = 6', false, '16e3e95d-c3c2-4a61-a13e-805da80f2b11');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb4fb8bd-0b4f-4319-864d-3f9e5432c11f', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'Solve the linear equation: 4y = 28. What is the value of y?', 'y = 28 ÷ 4 = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('757ad625-4f25-4bf9-bc35-519ef0a8be51', 'y = 7 (28 ÷ 4 = 7)', true, 'cb4fb8bd-0b4f-4319-864d-3f9e5432c11f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e9c1771-f6cd-4195-a34f-671bd6f4ca8a', 'y = 32', false, 'cb4fb8bd-0b4f-4319-864d-3f9e5432c11f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51060734-67ee-45f2-9c54-441a6a26c7f0', 'y = 24', false, 'cb4fb8bd-0b4f-4319-864d-3f9e5432c11f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51cb54ba-71b9-4540-9b88-44b20db451e1', 'y = 112', false, 'cb4fb8bd-0b4f-4319-864d-3f9e5432c11f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0a70cab-3834-4584-be45-fab4265b897e', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'If side length of an equilateral triangle is denoted by ''l'', what is its perimeter written algebraically?', 'Perimeter = 3 × side = 3l.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ea149ea-38b8-460c-aa8f-c177430bcd55', '3l (l + l + l = 3l)', true, 'b0a70cab-3834-4584-be45-fab4265b897e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ee604a8-dbfa-42dc-a251-ca286a589362', 'l³', false, 'b0a70cab-3834-4584-be45-fab4265b897e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51bebf0e-d593-4549-a107-0c520350645f', '3 + l', false, 'b0a70cab-3834-4584-be45-fab4265b897e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c62a3ee5-ec13-47f7-9d1d-9f60a4eb8218', 'l/3', false, 'b0a70cab-3834-4584-be45-fab4265b897e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('845895d8-0afc-4b31-8cbe-5cac6bd24741', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'What is the numerical coefficient of the variable in the algebraic term ''-7x''?', 'The numerical multiplying factor attached to the variable x is -7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('008f688d-c660-4461-88e2-30039aa52781', '-7', true, '845895d8-0afc-4b31-8cbe-5cac6bd24741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e57dc36-bba9-4376-a00a-5dad14533b03', '7', false, '845895d8-0afc-4b31-8cbe-5cac6bd24741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a41745cd-2fa3-470f-9491-bd386c885a96', 'x', false, '845895d8-0afc-4b31-8cbe-5cac6bd24741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c854b736-1388-45e0-9d1d-1e07b6d3d409', '-x', false, '845895d8-0afc-4b31-8cbe-5cac6bd24741');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c34c05c7-ac58-4d4a-b39f-b2441f425974', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Raju is 5 years younger than his brother Ravi. If Ravi''s present age is ''x'' years, what is Raju''s age in terms of x?', 'Younger by 5 years means subtracting 5 from Ravi''s age: x - 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d26b020-9553-4e44-a53f-cda9890202e7', '(x - 5) years', true, 'c34c05c7-ac58-4d4a-b39f-b2441f425974');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47c06331-3968-4263-8024-4f5d2ded4b06', '(x + 5) years', false, 'c34c05c7-ac58-4d4a-b39f-b2441f425974');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b020bd3d-9343-4c36-8f4d-5f5626b66f56', '5x years', false, 'c34c05c7-ac58-4d4a-b39f-b2441f425974');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('578b957a-d8a9-4d78-bc9e-9bb4eb17248d', 'x/5 years', false, 'c34c05c7-ac58-4d4a-b39f-b2441f425974');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5979d448-6778-4bd8-923f-d19d06b75179', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Sarita has ''m'' marbles. Ameena has 10 more than twice the number of marbles Sarita has. How many marbles does Ameena have?', 'Twice Sarita''s marbles = 2m; 10 more than twice = 2m + 10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('040b2e2f-aa92-4f76-83b7-ac550c01790a', '2m + 10', true, '5979d448-6778-4bd8-923f-d19d06b75179');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('555a90a6-8216-421e-8060-eead73c69940', '2(m + 10)', false, '5979d448-6778-4bd8-923f-d19d06b75179');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57fd27db-a4d2-4dc8-b92c-f792c63c9041', '10m + 2', false, '5979d448-6778-4bd8-923f-d19d06b75179');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bc9f7c5-48c3-4795-bc54-df38f96742a5', 'm/2 + 10', false, '5979d448-6778-4bd8-923f-d19d06b75179');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a10a348d-c25c-444d-9539-ad199463cc03', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Solve the linear equation: 3n + 7 = 25. What is the value of n?', '3n = 25 - 7 = 18 ⇒ n = 18 ÷ 3 = 6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('292b6504-4db5-4136-8f5a-49debdf4ec73', 'n = 6 (3n = 25 - 7 = 18 ⇒ n = 18/3 = 6)', true, 'a10a348d-c25c-444d-9539-ad199463cc03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52f43eaa-1328-44d5-9a64-73ab7a3d28e1', 'n = 8', false, 'a10a348d-c25c-444d-9539-ad199463cc03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f811203-be1f-4de6-9cdd-1707374b2f3a', 'n = 5', false, 'a10a348d-c25c-444d-9539-ad199463cc03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bc2c2eb-632b-47d3-8695-28a6cde97e46', 'n = 7', false, 'a10a348d-c25c-444d-9539-ad199463cc03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61168db7-e4c5-441d-ab05-5049d9205d2b', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Solve the equation: p/3 - 4 = 2. What is the value of p?', 'p/3 = 2 + 4 = 6 ⇒ p = 6 × 3 = 18.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a72aac5d-94ff-4ecd-a55e-32c736cca2c7', 'p = 18 (p/3 = 2 + 4 = 6 ⇒ p = 6 × 3 = 18)', true, '61168db7-e4c5-441d-ab05-5049d9205d2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e003c07-f5b6-4176-b166-167c6b3b4906', 'p = 6', false, '61168db7-e4c5-441d-ab05-5049d9205d2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdea14a4-394c-4718-8efc-5ef6fc1ed0c0', 'p = 12', false, '61168db7-e4c5-441d-ab05-5049d9205d2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb2daa2c-ae8b-4a06-a10e-78adffcd33b8', 'p = 24', false, '61168db7-e4c5-441d-ab05-5049d9205d2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e288602-6b3c-4d81-8500-4c8960f36350', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'A bus travels at a uniform speed of ''v'' km per hour. It goes from Daspur to Beespur. After the bus has travelled for 5 hours, Beespur is still 20 km away. What is the total distance between Daspur and Beespur in terms of v?', 'Distance travelled in 5 hours = Speed × Time = 5v km. Total distance = 5v + 20 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ce53de7-2638-4b4b-acc0-345326996b5f', '(5v + 20) km', true, '1e288602-6b3c-4d81-8500-4c8960f36350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30f9a629-27aa-44b8-b61c-3117c71ff391', '(5v - 20) km', false, '1e288602-6b3c-4d81-8500-4c8960f36350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88803140-737b-4129-956b-604d1c9ca3c0', '20v + 5 km', false, '1e288602-6b3c-4d81-8500-4c8960f36350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4cf5426-5113-45db-8c0d-d6dd345dd042', '5(v + 20) km', false, '1e288602-6b3c-4d81-8500-4c8960f36350');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38a70a20-b568-4c6a-9a2f-c4388ab18ea9', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'If a box contains 50 mangoes, how will you write the total number of mangoes in ''b'' boxes?', 'Number of mangoes per box × number of boxes = 50 × b = 50b.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9d60e31-7c91-493a-b128-0d302dc093e2', '50b (50 × b)', true, '38a70a20-b568-4c6a-9a2f-c4388ab18ea9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8f47e15-659d-43ee-b4d0-e916f50eb577', '50 + b', false, '38a70a20-b568-4c6a-9a2f-c4388ab18ea9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1891e884-9344-4d9c-89dc-890f9476ce20', 'b / 50', false, '38a70a20-b568-4c6a-9a2f-c4388ab18ea9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6423723f-8b19-4ef9-b473-10b92e394ab8', '50 - b', false, '38a70a20-b568-4c6a-9a2f-c4388ab18ea9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80e89d2a-536b-4e3a-8606-4c3661b12b0c', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Cadets are marching in a parade in a Republic Day parade. There are 5 cadets in a row. What is the algebraic rule which gives the total number of cadets for ''r'' rows?', 'Cadets per row × rows = 5 × r = 5r.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67997477-bd7f-4d2f-9798-758c7354819f', '5r', true, '80e89d2a-536b-4e3a-8606-4c3661b12b0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('defa006d-94b5-4fb8-a589-86fa4d63aa84', 'r + 5', false, '80e89d2a-536b-4e3a-8606-4c3661b12b0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19ac4e4b-382c-4aed-b841-836e55e4232a', 'r / 5', false, '80e89d2a-536b-4e3a-8606-4c3661b12b0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81149b9c-aef2-4e77-a8c0-b67b879d1350', '5 + r', false, '80e89d2a-536b-4e3a-8606-4c3661b12b0c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60bc4edf-8490-4964-bb35-50e71e7877f5', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Leela is Radha''s younger sister. Leela is 4 years younger than Radha. Can you write Leela''s age in terms of Radha''s age? (Take Radha''s age as ''x'' years):', 'Leela''s age = Radha''s age - 4 = x - 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8fa3fbd-3ca7-44c2-9f62-8f7a968b826c', '(x - 4) years', true, '60bc4edf-8490-4964-bb35-50e71e7877f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23afb02a-20eb-40de-8967-303dc0912744', '(x + 4) years', false, '60bc4edf-8490-4964-bb35-50e71e7877f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34b6a159-ce46-417a-aecb-021ab973ed0c', '4x years', false, '60bc4edf-8490-4964-bb35-50e71e7877f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24723682-05d7-480c-97bb-93f441e45744', 'x/4 years', false, '60bc4edf-8490-4964-bb35-50e71e7877f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ead05c8d-2cef-41ee-a10e-93f01ae3c107', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Mother has made laddoos. She gives some laddoos to guests and family members; still 5 laddoos remain. If the number of laddoos mother gave away is ''l'', how many laddoos did she make in total?', 'Total made = Laddoos given away + remaining laddoos = l + 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23bdabd9-d276-471b-944b-ee4fa8bd0a02', 'l + 5', true, 'ead05c8d-2cef-41ee-a10e-93f01ae3c107');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('391a70f0-5fad-4d5d-b39d-6f450f026835', 'l - 5', false, 'ead05c8d-2cef-41ee-a10e-93f01ae3c107');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0451ccdd-79d8-4eb4-b60d-497f590ca7ba', '5l', false, 'ead05c8d-2cef-41ee-a10e-93f01ae3c107');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b9c0137-2e36-48b4-815f-528688cc97bb', 'l / 5', false, 'ead05c8d-2cef-41ee-a10e-93f01ae3c107');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2c427f4-7066-478e-8af2-90e3100a73a5', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Which of the following mathematical expressions is a valid ALGEBRAIC EQUATION containing a variable?', 'An algebraic equation must have both a variable and an equality sign (=).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4f950f1-088a-4fbd-b271-d02f413b6efe', '2x + 7 = 19 (contains variable x and ''='' sign)', true, 'f2c427f4-7066-478e-8af2-90e3100a73a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bfd3f6e-3cc8-4fbc-85a3-d9f0a93771db', '2x + 7 > 19', false, 'f2c427f4-7066-478e-8af2-90e3100a73a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e990c6a4-8ee2-40a4-9495-df5ea17fe4bb', '5 × 3 + 2 = 17 (arithmetic equality without variable)', false, 'f2c427f4-7066-478e-8af2-90e3100a73a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d036d74-82b1-43ba-a6ae-1e1e9a11efea', '3x - 5', false, 'f2c427f4-7066-478e-8af2-90e3100a73a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d313e19-4f3b-4c98-8424-3b3c928bc753', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Find the value of the algebraic expression 3x² - 4x + 5 when x = 3:', '3(3²) - 4(3) + 5 = 3(9) - 12 + 5 = 27 - 12 + 5 = 20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1400f10-f00d-4566-a307-dfc662e505c7', '20 (3(3)² - 4(3) + 5 = 3(9) - 12 + 5 = 27 - 12 + 5 = 20)', true, '8d313e19-4f3b-4c98-8424-3b3c928bc753');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c29990f-6559-4c0c-9c60-dc5fb479a8e6', '18', false, '8d313e19-4f3b-4c98-8424-3b3c928bc753');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b883238-6ceb-4a5b-a0b8-1b0c27801f07', '24', false, '8d313e19-4f3b-4c98-8424-3b3c928bc753');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c8eecba-7893-47b7-9e0f-37aef4262b5b', '15', false, '8d313e19-4f3b-4c98-8424-3b3c928bc753');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('307f2b65-c88f-4bb7-944c-c59542995541', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Change the algebraic statement into ordinary everyday English: ''A notebook costs ₹p. A book costs ₹3p.''', '3p indicates multiplication by 3, meaning the book costs 3 times the notebook''s price.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af729452-f88a-499a-910c-dd393531ce3c', 'A book costs three times as much as a notebook', true, '307f2b65-c88f-4bb7-944c-c59542995541');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cc99cc2-0531-4be3-adf3-833287ef9c8d', 'A notebook costs three times as much as a book', false, '307f2b65-c88f-4bb7-944c-c59542995541');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae31dcd0-971d-4d84-b530-97622aa2bd4b', 'A book costs ₹3 more than a notebook', false, '307f2b65-c88f-4bb7-944c-c59542995541');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a937c179-aa4f-4626-98cb-e7081a8c9674', 'A book costs ₹3 less than a notebook', false, '307f2b65-c88f-4bb7-944c-c59542995541');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93238760-7ed6-4dfd-8087-a1cc0e4f190d', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Solve the equation using the Trial and Error method: 5x = 35. For what value of x is the equation satisfied?', 'Testing values: 5(5)=25, 5(6)=30, 5(7)=35 (Satisfied!).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9741be71-b8cb-4367-ac09-3e494a8d5d99', 'x = 7 (5 × 7 = 35)', true, '93238760-7ed6-4dfd-8087-a1cc0e4f190d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2b73489-7bc9-4062-acda-77a4a4e76c10', 'x = 5', false, '93238760-7ed6-4dfd-8087-a1cc0e4f190d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d444e2a-2c1c-4eee-a280-54dd5c03c415', 'x = 6', false, '93238760-7ed6-4dfd-8087-a1cc0e4f190d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cad48680-61f5-45f9-868e-85341b31c148', 'x = 8', false, '93238760-7ed6-4dfd-8087-a1cc0e4f190d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65bb2f4a-0c8a-4768-8d16-2211a26ffd35', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'How is the Commutative Property of Addition of two whole numbers ''a'' and ''b'' written in general algebraic notation?', 'Commutative law of addition states that order of terms does not alter the sum: a + b = b + a.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c681467-4e9c-48c4-97f9-d5156fdbaf03', 'a + b = b + a', true, '65bb2f4a-0c8a-4768-8d16-2211a26ffd35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('599cfdc8-1d1a-4eb7-a751-8120901cab98', 'a × b = b × a', false, '65bb2f4a-0c8a-4768-8d16-2211a26ffd35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6b9f5e9-5272-4d42-a2f1-36896cb52143', 'a - b = b - a', false, '65bb2f4a-0c8a-4768-8d16-2211a26ffd35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0de17e6c-3a68-47a6-86c6-f6d5526467fb', 'a + (b + c) = (a + b) + c', false, '65bb2f4a-0c8a-4768-8d16-2211a26ffd35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d90096d-27f7-408b-821e-e6dca3eba0c7', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'How is the Distributive Property of Multiplication over Addition written algebraically for three numbers a, b, and c?', 'Distributive property: a(b + c) = ab + ac.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dee5f63-1b59-4036-8a24-b41a52b952c0', 'a × (b + c) = (a × b) + (a × c)', true, '7d90096d-27f7-408b-821e-e6dca3eba0c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e9c50f-ea6d-492f-a362-0ced9a7355bb', 'a + (b × c) = (a + b) × c', false, '7d90096d-27f7-408b-821e-e6dca3eba0c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ba0d22f-9fab-449e-a685-ac99eb904d4a', 'a × b × c = a + b + c', false, '7d90096d-27f7-408b-821e-e6dca3eba0c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cb32d4c-1066-444a-87b4-8092ffc138ee', 'a / (b + c) = a/b + a/c', false, '7d90096d-27f7-408b-821e-e6dca3eba0c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('018eaa55-dd8c-4b5f-aa9e-82d830209f41', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'If the diameter of a circle is ''d'' and its radius is ''r'', what is the algebraic relation between diameter and radius?', 'Diameter is twice the radius: d = 2r.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbf6716c-07f3-419e-bc4a-f017d51a8008', 'd = 2r (or r = d/2)', true, '018eaa55-dd8c-4b5f-aa9e-82d830209f41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('390777bd-9054-4482-b695-b9b6c4f601ea', 'd = r + 2', false, '018eaa55-dd8c-4b5f-aa9e-82d830209f41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('027b761d-6b94-44ad-987c-94d03a01eb61', 'd = r²', false, '018eaa55-dd8c-4b5f-aa9e-82d830209f41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3a7f671-e36b-4f29-8740-621e00a198ad', 'd = r/2', false, '018eaa55-dd8c-4b5f-aa9e-82d830209f41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9e2286d-4ee2-488d-801b-96cadab71c80', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94bdc34e-c985-48dd-8df2-719d3a22c3cf', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'e9e2286d-4ee2-488d-801b-96cadab71c80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cedc86b2-65c1-4bb8-a4c6-adc8723be896', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'e9e2286d-4ee2-488d-801b-96cadab71c80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('117b85ec-a160-40ac-ade9-24a7c7215fe8', '(A) is true, but (R) is false.', false, 'e9e2286d-4ee2-488d-801b-96cadab71c80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b7bfda9-aeee-41d9-a0ad-c91dbd6b7127', '(A) is false, but (R) is true.', false, 'e9e2286d-4ee2-488d-801b-96cadab71c80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5780c21-0b94-43ee-96d3-5de23cb4e012', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Spot the IMPOSTER in the following algebraic expressions where x = 4:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7069a42-2bcd-4f92-a95c-3b0f1c2b6a5f', '2x + 3 = 11', false, 'e5780c21-0b94-43ee-96d3-5de23cb4e012');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b856086c-2329-4f59-8709-5ce3124a3871', '5x - 8 = 12', false, 'e5780c21-0b94-43ee-96d3-5de23cb4e012');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c643209e-6698-4bb5-97bd-e092c456b876', 'x² + 1 = 17', false, 'e5780c21-0b94-43ee-96d3-5de23cb4e012');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2cd7c26-01f1-4246-b578-9ccbff1c9a3c', '3x - 5 = 8', true, 'e5780c21-0b94-43ee-96d3-5de23cb4e012');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da74b0ef-cb6c-4a78-834d-41b4a77a9a84', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'To form a pattern of ''n'' connected squares using matchsticks in a row where the first square uses 4 sticks and each adjoining square shares 1 common vertical side, what is the exact algebraic rule for total matchsticks?', 'First square uses 4; every additional square adds 3 sticks: 4 + 3(n - 1) = 4 + 3n - 3 = 3n + 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b36fdca6-faca-49f3-95fc-e3a2402052a3', '3n + 1 (For 1 square = 4 sticks ; For 2 squares = 7 sticks ; For 3 = 10 sticks)', true, 'da74b0ef-cb6c-4a78-834d-41b4a77a9a84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e284e085-3419-46c3-bc73-8417d0a978e5', '4n', false, 'da74b0ef-cb6c-4a78-834d-41b4a77a9a84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('003d91ed-8d12-4a60-91b3-e66225a31488', '4n - 1', false, 'da74b0ef-cb6c-4a78-834d-41b4a77a9a84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('373e31e3-2d60-48a5-a620-e0706887a298', '2n + 2', false, 'da74b0ef-cb6c-4a78-834d-41b4a77a9a84');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b7bdf3c-c9fd-4b1a-88ca-589d88262111', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Match Column I (Word Statements) with Column II (Algebraic Expressions):
(a) 5 subtracted from -m      -> (i) 2y + 11
(b) 11 added to twice of y    -> (ii) -m - 5
(c) y multiplied by -8        -> (iii) y/5 + 3
(d) 3 added to one-fifth of y -> (iv) -8y', '-m - 5; 2y + 11; -8y; y/5 + 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7d11df5-0af8-44e1-923c-f69181dbedf3', 'a-(ii), b-(i), c-(iv), d-(iii)', true, '2b7bdf3c-c9fd-4b1a-88ca-589d88262111');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69990341-1316-4057-9df7-65c967f94560', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '2b7bdf3c-c9fd-4b1a-88ca-589d88262111');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ae916d3-be64-4087-891b-28956c7b2bcb', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '2b7bdf3c-c9fd-4b1a-88ca-589d88262111');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97c53194-30b1-419e-a5b3-d4a2ccdf314a', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '2b7bdf3c-c9fd-4b1a-88ca-589d88262111');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7194a15f-d4a5-4e80-a50a-fde867d156c8', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Read the statements regarding algebraic equations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b2b2c04-b64d-4d27-8510-13a2429b7b96', 'Statements 1 and 2 only', true, '7194a15f-d4a5-4e80-a50a-fde867d156c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd300348-48da-4179-b25a-9f57a20e1e75', 'Statements 2 and 3 only', false, '7194a15f-d4a5-4e80-a50a-fde867d156c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5931b214-2829-4cf5-91c5-463beeb7e67e', 'Statements 1 and 3 only', false, '7194a15f-d4a5-4e80-a50a-fde867d156c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6b2321e-0bfd-4665-9923-85ad2f538b51', 'All Statements 1, 2, and 3', false, '7194a15f-d4a5-4e80-a50a-fde867d156c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a02338c-0722-4a99-ba60-8812c26677d3', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Solve the linear equation: (2x - 3) / 5 = 3. What is the value of x?', '2x - 3 = 3 × 5 = 15 ⇒ 2x = 15 + 3 = 18 ⇒ x = 9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58f14619-602d-4687-9ed7-43c6486fe79b', 'x = 9 (2x - 3 = 15 ⇒ 2x = 18 ⇒ x = 9)', true, '9a02338c-0722-4a99-ba60-8812c26677d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d288887-fc86-4560-9f39-adc733731191', 'x = 6', false, '9a02338c-0722-4a99-ba60-8812c26677d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50329094-c5db-42e1-9d23-5e642a45787d', 'x = 12', false, '9a02338c-0722-4a99-ba60-8812c26677d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23eeae39-7e0f-4c6d-aeb3-ac464c3d1df9', 'x = 15', false, '9a02338c-0722-4a99-ba60-8812c26677d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3ca553d-85b0-4760-9861-3c235914fee9', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'The length of a rectangular hall is 4 metres less than 3 times the breadth of the hall. If the breadth is ''b'' metres, what is the length in terms of b?', '3 times breadth = 3b. 4 metres less than 3b = 3b - 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da071a28-1fa7-437c-ba8b-0abaa88554ad', '(3b - 4) metres', true, 'd3ca553d-85b0-4760-9861-3c235914fee9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1381233-f24b-4530-a8dc-148845fb780f', '(3b + 4) metres', false, 'd3ca553d-85b0-4760-9861-3c235914fee9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0b97841-9757-478e-a701-01b7c4797aea', '(4b - 3) metres', false, 'd3ca553d-85b0-4760-9861-3c235914fee9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2217edca-90dc-4d7d-a634-6b50a2fec83e', '3(b - 4) metres', false, 'd3ca553d-85b0-4760-9861-3c235914fee9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c32f2855-c727-4fe6-a0f0-9251e8c9886e', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'A rectangular box has height ''h'' cm. Its length is 5 times the height and breadth is 10 cm less than the length. Express the length and breadth in terms of the height h:', 'Length = 5 × h = 5h cm; Breadth = Length - 10 = (5h - 10) cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d3fbe6e-7f24-4509-9d24-ce9b1b389476', 'Length = 5h cm ; Breadth = (5h - 10) cm', true, 'c32f2855-c727-4fe6-a0f0-9251e8c9886e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d756494a-0cd3-4fb5-8658-283348864134', 'Length = h + 5 cm ; Breadth = h - 10 cm', false, 'c32f2855-c727-4fe6-a0f0-9251e8c9886e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c479755-2369-4a5a-9b23-770b765fca35', 'Length = 5h cm ; Breadth = 5h + 10 cm', false, 'c32f2855-c727-4fe6-a0f0-9251e8c9886e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbdcf84-0e3e-4170-bb79-bd8c464571a0', 'Length = h/5 cm ; Breadth = 5h - 10 cm', false, 'c32f2855-c727-4fe6-a0f0-9251e8c9886e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db6557a5-94f1-4665-a973-50c3920bd3aa', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'The sum of three consecutive integers is 51. If the smallest integer is denoted by ''x'', what is the algebraic equation and the value of x?', '3x + 3 = 51 ⇒ 3x = 48 ⇒ x = 16. Integers are 16, 17, 18 (16+17+18 = 51).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf789154-0b29-4a34-a3c3-88e4bbea7cf2', 'Equation: x + (x + 1) + (x + 2) = 51 ⇒ 3x + 3 = 51 ⇒ x = 16 (Integers are 16, 17, 18)', true, 'db6557a5-94f1-4665-a973-50c3920bd3aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b6ab9f0-c1ca-496c-84a0-4a1aeb81c953', 'Equation: 3x = 51 ⇒ x = 17', false, 'db6557a5-94f1-4665-a973-50c3920bd3aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc28f376-5a6c-4dde-82b0-673b8a679f9b', 'Equation: x + x + x = 51 ⇒ x = 15', false, 'db6557a5-94f1-4665-a973-50c3920bd3aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a459a18-6af5-4ac4-889d-0758f63ae40c', 'Equation: 3x - 3 = 51 ⇒ x = 18', false, 'db6557a5-94f1-4665-a973-50c3920bd3aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee6ff89f-85cf-4375-9b5d-84f90a118a0b', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'A father is 35 years older than his son. After 5 years, the father will be twice as old as his son. If the son''s present age is ''s'', which equation correctly models this situation?', 'Father''s age in 5 yrs = (s + 35) + 5 = s + 40. Son''s age in 5 yrs = s + 5. Equation: s + 40 = 2(s + 5).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb1e58a2-db0c-4cdb-8fee-c94a67209e4a', '(s + 35) + 5 = 2(s + 5) ⇒ s + 40 = 2s + 10 ⇒ s = 30', true, 'ee6ff89f-85cf-4375-9b5d-84f90a118a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22a3491b-9acb-44a5-b48a-61a585317373', 's + 35 = 2s', false, 'ee6ff89f-85cf-4375-9b5d-84f90a118a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7a00e1d-ed14-405a-94d7-6934c59032c3', 's + 5 = 2(s + 35)', false, 'ee6ff89f-85cf-4375-9b5d-84f90a118a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd3fd7eb-1f72-48c5-ae31-dec1bbd0e7b0', '35s = 2(s + 5)', false, 'ee6ff89f-85cf-4375-9b5d-84f90a118a0b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff28572c-b8c8-42cc-bec7-8642a5c184e3', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'If 3x + 2y = 24 and x = 4, find the value of y:', '12 + 2y = 24 ⇒ 2y = 12 ⇒ y = 6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bc9b58d-0393-4bdd-8983-2e8d798bcaf0', 'y = 6 (3(4) + 2y = 24 ⇒ 12 + 2y = 24 ⇒ 2y = 12 ⇒ y = 6)', true, 'ff28572c-b8c8-42cc-bec7-8642a5c184e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3558be5-99b6-4c6a-8be4-78db522bcbd7', 'y = 4', false, 'ff28572c-b8c8-42cc-bec7-8642a5c184e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0d8626f-5136-4f52-9f60-5a6caa620212', 'y = 8', false, 'ff28572c-b8c8-42cc-bec7-8642a5c184e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e0ed895-5109-4fa8-b054-92a326c84b27', 'y = 12', false, 'ff28572c-b8c8-42cc-bec7-8642a5c184e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7eed178b-ce60-453a-a4ba-4b99cd09b41a', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Why is Algebra considered the foundational universal language of higher mathematics, physics, and computer programming?', 'Algebra provides abstract symbolic modeling to formulate general rules, invariant laws, and computational algorithms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d37fb132-069d-40bc-8a4d-6367c563d025', 'It allows generalized patterns, physical laws, and complex relationships to be stated succinctly using variables rather than specific arithmetic numbers alone', true, '7eed178b-ce60-453a-a4ba-4b99cd09b41a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcc5a276-7109-4dc3-b042-ce18d3068f54', 'Because letters are easier to draw than numbers', false, '7eed178b-ce60-453a-a4ba-4b99cd09b41a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9b3e6ed-a2a7-4273-90e6-893a931ad05e', 'Because algebra eliminates the need for thinking', false, '7eed178b-ce60-453a-a4ba-4b99cd09b41a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa6e3688-6eb6-4a3a-985d-62c0b61a62c3', 'Because it only works for matchsticks', false, '7eed178b-ce60-453a-a4ba-4b99cd09b41a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79453ef2-9d1c-437d-b93e-088507cd30e2', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'In English grammar, a sentence in which the SUBJECT performs the action is in:', 'In Active Voice, the grammatical subject is the active agent/doer of the transitive verb.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('092eba1b-e7a6-4900-9979-47209e27a1f6', 'Active Voice', true, '79453ef2-9d1c-437d-b93e-088507cd30e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('404d90b1-c026-4285-8e08-79a23fd76b23', 'Passive Voice', false, '79453ef2-9d1c-437d-b93e-088507cd30e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e5c1158-f504-48bd-a961-9841e04aab39', 'Direct Speech', false, '79453ef2-9d1c-437d-b93e-088507cd30e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b4379bb-5fcb-481b-be54-5df81a337f31', 'Indirect Speech', false, '79453ef2-9d1c-437d-b93e-088507cd30e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d39f662c-b7f5-41d3-b91c-fe28f488c3cb', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'A sentence in which the SUBJECT receives the action performed by an agent (e.g. ''The mouse was chased by the cat'') is in:', 'In Passive Voice, the recipient of the action occupies the subject position followed by ''be + past participle''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25914b07-805c-45be-ba81-93471c47faa4', 'Passive Voice', true, 'd39f662c-b7f5-41d3-b91c-fe28f488c3cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91d34f03-00ff-4dde-a186-0595fdfcd6b5', 'Active Voice', false, 'd39f662c-b7f5-41d3-b91c-fe28f488c3cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70ffc0d3-9189-499c-8fec-17029c08601b', 'Interrogative Voice', false, 'd39f662c-b7f5-41d3-b91c-fe28f488c3cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b31fb71-9a09-4baa-9df8-f7567879c894', 'Imperative Voice', false, 'd39f662c-b7f5-41d3-b91c-fe28f488c3cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c72d5a0f-3e87-4794-bbd5-ada11c5a3907', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'What is the exact words of a speaker quoted within inverted quotation marks (" ") called in grammar?', 'Direct Speech quotes the speaker''s verbatim words enclosed in quotation marks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('442c1eda-ca1a-4e8c-b0f8-8d9d4460eace', 'Direct Speech', true, 'c72d5a0f-3e87-4794-bbd5-ada11c5a3907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac3f5a37-feb0-48fc-a2d9-c4cf8938219d', 'Indirect Speech (Reported Speech)', false, 'c72d5a0f-3e87-4794-bbd5-ada11c5a3907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4af20ee6-69c8-4119-bb9c-da13749f6511', 'Passive Voice', false, 'c72d5a0f-3e87-4794-bbd5-ada11c5a3907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91a5e93c-1e0c-454a-818e-dcfcfae30f63', 'Active Voice', false, 'c72d5a0f-3e87-4794-bbd5-ada11c5a3907');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('165a0ae8-ad18-4d9a-b0c4-9c8a492e921a', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'What is reporting the substance of what someone said without quoting their exact words (without quotation marks) called?', 'Indirect Speech reports spoken propositions with appropriate tense, pronoun, and adverbial shifts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54960abe-9977-4204-a7df-fd3d4326e284', 'Indirect Speech (Reported Speech)', true, '165a0ae8-ad18-4d9a-b0c4-9c8a492e921a');
