INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5cc32b09-a283-4ae3-9642-6087213ac637', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'What is a SYNONYM for the word ''Courageous''?', '''Brave'' and ''courageous'' are synonymous adjectives denoting valor in confronting adversity.', NOW()) ON CONFLICT DO NOTHING;
