INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10caec3c-8503-444e-8676-e0ba550ac02d', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'What is the ANTONYM (opposite word) of ''Ancient''?', 'The antonym of ''ancient'' (pertaining to remote antiquity) is ''modern'' (contemporary).', NOW()) ON CONFLICT DO NOTHING;
