INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b392fc29-f7e9-421b-8817-1bc93721b38a', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'What is the meaning of the common English idiom ''A piece of cake''?', '''A piece of cake'' idiomatically signifies an effortlessly simple task.', NOW()) ON CONFLICT DO NOTHING;
