INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7eb48f71-4348-40f4-8e7a-de8aee0b1f3c', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'What is the meaning of the idiom ''Once in a blue moon''?', '''Once in a blue moon'' denotes an event of extreme rarity.', NOW()) ON CONFLICT DO NOTHING;
