INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54549869-f986-4ce3-a657-abda4b56bac4', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'Choose the correct past participle form of the irregular verb ''Write'':', 'Principal parts: Write (base), Wrote (past), Written (past participle).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b35ee828-8379-4d2b-ade3-4f16c848acf8', 'Written (Write - Wrote - Written)', true, '54549869-f986-4ce3-a657-abda4b56bac4');
