INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a0e9c69-e2ef-4aff-8087-36cd9a75cd7d', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'What is a group of words consisting of a verb and a preposition/adverb that takes on a unique figurative meaning (e.g. ''give up'', ''look after'', ''break down'') called?', 'A phrasal verb combines a base verb with a preposition/adverb particle to express an idiomatic semantic unit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aff6531-e28a-4e77-892e-95531f756bd6', 'Phrasal Verb', true, '0a0e9c69-e2ef-4aff-8087-36cd9a75cd7d');
