INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ffe65ba-4d88-4b0a-a62b-67c1be224710', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'What does the phrasal verb ''To look after'' mean?', '''To look after'' means to attend to the health, well-being, or maintenance of someone/something.', NOW()) ON CONFLICT DO NOTHING;
