INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bcd8efdb-0a46-47d9-847b-0a836a914db5', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Medium', 'Convert the Active Voice sentence into Passive Voice:
