INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('125867ee-1f56-43df-be44-c4cf6e2369df', 'Active: ''He wrote a letter'' -> Passive: ''A letter was written by him''', false, 'f45a6339-704b-479d-9713-f4c885e09315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecaff279-4773-4e52-ac61-8d4fe99e117a', 'Active: ''She ate an apple'' -> Passive: ''An apple was eaten by her''', false, 'f45a6339-704b-479d-9713-f4c885e09315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a408840-9ee1-4e96-9a80-9d63a8e8735f', 'Active: ''They built a bridge'' -> Passive: ''A bridge was built by them''', false, 'f45a6339-704b-479d-9713-f4c885e09315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('374503e1-1b2c-45d7-a76a-09fe6b39bfc5', 'Active: ''He slept peacefully'' -> Passive: ''Peacefully was slept by him''', true, 'f45a6339-704b-479d-9713-f4c885e09315');
