INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4137ef9-1734-4325-998f-bbe88eabaed5', 'Speed, Anger, and Power', false, 'a3344376-e500-4d12-a9a2-e545251a0b44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2efe91a-06f2-47b2-b034-30058f451c34', 'Luck, Magic, and Fortune', false, 'a3344376-e500-4d12-a9a2-e545251a0b44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9dc98969-6178-46e3-aa41-81981e3f7e7c', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Match Column I (Phrasal Verbs) with Column II (Exact Definitions):
(a) Call off     -> (i) Extinguish a fire
(b) Put out      -> (ii) Cancel an event completely
(c) Look into    -> (iii) Tolerate / endure an unpleasant situation
(d) Put up with  -> (iv) Investigate or examine closely', 'Call off = cancel; Put out = extinguish; Look into = investigate; Put up with = tolerate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('780788e6-2162-4337-982e-799b81a6a861', 'a-(ii), b-(i), c-(iv), d-(iii)', true, '9dc98969-6178-46e3-aa41-81981e3f7e7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96b580b6-86bc-4aee-bd1e-e04a19eaf431', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '9dc98969-6178-46e3-aa41-81981e3f7e7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54e6d50e-50b8-450b-a661-26bed9fb094f', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '9dc98969-6178-46e3-aa41-81981e3f7e7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7348582-a8e2-4341-b01a-a1d1cfba6fd0', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '9dc98969-6178-46e3-aa41-81981e3f7e7c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('201e90df-d6d6-4e90-a2b2-422256ec8d3c', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Read the statements regarding English grammar:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e713fa7-8687-478b-89c7-629be8820144', 'Statements 1 and 2 only', true, '201e90df-d6d6-4e90-a2b2-422256ec8d3c');
