INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab80b1f7-d9bb-4b3a-bbee-814dd58ae85c', 'Statements 1 and 3 only', false, '201e90df-d6d6-4e90-a2b2-422256ec8d3c');
