INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f029666-0501-41b7-85ed-7329d070a863', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Transform the compound sentence into a COMPLEX sentence using an Adverb Clause of Concession:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f68926d7-fcc2-49ed-81e3-0e145b67acb5', '''Although he was very poor, he remained scrupulously honest.''', true, '4f029666-0501-41b7-85ed-7329d070a863');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e02e0ab-bfed-4244-a65e-5f783c1befa6', '''He was poor and honest.''', false, '4f029666-0501-41b7-85ed-7329d070a863');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7259a584-917d-4acf-97a6-9bbb57285ee7', '''Being poor, he was honest.''', false, '4f029666-0501-41b7-85ed-7329d070a863');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec566ebe-e661-430f-ba7b-65d34ee85c51', '''Because he was poor, he was honest.''', false, '4f029666-0501-41b7-85ed-7329d070a863');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('798cdb8d-8e71-4a21-a5c1-5f0f9308c44d', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'What is the grammatical error in the sentence: ''The flock of sheep were grazing on the hillside.''?', 'Collective noun ''flock'' takes singular grammatical agreement: ''The flock of sheep was grazing''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a1db41e-7fc9-45e5-b93a-f7d1c649d230', 'The collective noun ''flock'' is singular and requires the singular verb ''was grazing''', true, '798cdb8d-8e71-4a21-a5c1-5f0f9308c44d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('973f6d49-3233-4d06-a4cc-ea8949e5c20b', '''Flock'' should be spelled ''flook''', false, '798cdb8d-8e71-4a21-a5c1-5f0f9308c44d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd82dcb5-d333-425b-9da1-a5858926de4d', '''Sheep'' should be written as ''sheeps''', false, '798cdb8d-8e71-4a21-a5c1-5f0f9308c44d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99b6795e-6cc0-479f-af28-c2fb1ef7f536', '''Hillside'' is spelled incorrectly', false, '798cdb8d-8e71-4a21-a5c1-5f0f9308c44d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e806faed-c0b9-4527-98cd-91082c415ffa', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Identify the figure of speech in: ''The lightning danced across the dark sky.''', 'Endowing natural phenomena with human kinetic agency constitutes Personification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef5b5f18-461f-41e9-ba86-0036972a7ad6', 'Personification (attributing the human voluntary action of ''dancing'' to inanimate lightning)', true, 'e806faed-c0b9-4527-98cd-91082c415ffa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5e58366-6999-4724-a649-db40104e3408', 'Simile', false, 'e806faed-c0b9-4527-98cd-91082c415ffa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a41e9b7-2393-4a2b-8bd1-65bdfa0027ed', 'Hyperbole', false, 'e806faed-c0b9-4527-98cd-91082c415ffa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f23b8f39-fbbb-4917-b8af-1b6c9eec7fca', 'Oxymoron', false, 'e806faed-c0b9-4527-98cd-91082c415ffa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('835812e9-0f73-40f7-bc4d-dd2bcac2075e', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Convert into Indirect Speech:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22dc25e0-84a0-4d7d-b99d-bc023f15b43d', 'She exclaimed with sorrow that she had lost her grandmother''s golden ring.', true, '835812e9-0f73-40f7-bc4d-dd2bcac2075e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51654eb0-498f-4f68-8fe2-5fb2ea7248f9', 'She said alas that she lost her ring.', false, '835812e9-0f73-40f7-bc4d-dd2bcac2075e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8778abb-3944-48ce-bf63-313dc2d2a769', 'She asked why she lost her golden ring.', false, '835812e9-0f73-40f7-bc4d-dd2bcac2075e');
