INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e55cf06-899a-4aa9-9c86-aaae8869c685', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'What is the meaning of the Latin phrase ''Vice Versa'' used in English?', '''Vice versa'' indicates that the reverse of the stated proposition is equally valid.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('893346a6-bb9e-402d-b04c-ec8d5d8e5ad7', 'With the order or relation reversed (the other way around)', true, '5e55cf06-899a-4aa9-9c86-aaae8869c685');
