INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1b28438-88b3-49aa-9a6d-ee794c421f51', 'With great speed', false, '5e55cf06-899a-4aa9-9c86-aaae8869c685');
