INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b1ca880-37cd-4448-b2da-52dab601961a', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Which of the following sentences exhibits correct MODAL AUXILIARY usage to express moral obligation and duty?', '''Ought to'' expresses ethical and moral duty/obligation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2072be14-fa9e-47e8-bbd9-093bc3082834', '''We ought to respect our parents and teachers.''', true, '1b1ca880-37cd-4448-b2da-52dab601961a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90e65b3a-d234-458d-bc72-fa4296ae3f21', '''We might respect our parents.''', false, '1b1ca880-37cd-4448-b2da-52dab601961a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('738937e6-6eaa-4020-8954-70d6820f651a', '''We can to respect our parents.''', false, '1b1ca880-37cd-4448-b2da-52dab601961a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85d68a1c-7329-41e2-ae8a-1bba1408e4e5', '''We would to respect our parents.''', false, '1b1ca880-37cd-4448-b2da-52dab601961a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08fc7d0e-20ae-402d-88c4-d7253ed4500b', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'What core communicative and linguistic competency does mastery of applied grammar cultivate in young scholars?', 'Applied linguistics bridges structural grammatical precision with nuanced cognitive and empathetic literary expression.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('383b162a-f131-46ee-8ab7-fe35d8a13a73', 'Precision of thought, analytical reading comprehension, eloquent rhetorical expression, and ethical literary appreciation', true, '08fc7d0e-20ae-402d-88c4-d7253ed4500b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dc0abbf-c704-47bd-8e83-9ddbee04479a', 'Rote memorization of words without meaning', false, '08fc7d0e-20ae-402d-88c4-d7253ed4500b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d31a8353-a0cd-425a-9ee9-aed3677d642d', 'Speaking without grammar rules', false, '08fc7d0e-20ae-402d-88c4-d7253ed4500b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('109a437c-6599-43e7-ae7c-efbc473863c4', 'Writing books in code', false, '08fc7d0e-20ae-402d-88c4-d7253ed4500b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6bdf2be-3110-42b5-ae2f-7bd6a68e8d24', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'Who is celebrated as the ''Missile Man of India'' and served as the 11th President of India (2002–2007)?', 'Dr. A.P.J. Abdul Kalam led the development of India''s indigenous missile systems (Agni, Prithvi) and SLV-3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe8088f4-9516-48de-a6c4-2b910ab822e6', 'Dr. A.P.J. Abdul Kalam (Avul Pakir Jainulabdeen Abdul Kalam)', true, 'c6bdf2be-3110-42b5-ae2f-7bd6a68e8d24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f81c540-81a5-4565-9100-c7221adcb143', 'Dr. Homi J. Bhabha', false, 'c6bdf2be-3110-42b5-ae2f-7bd6a68e8d24');
