INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81f6d161-1bd8-4ce9-8748-04f2b7efaad1', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'Who was the FIRST Indian scientist to win the Nobel Prize in Physics in 1930 for discovering the scattering of light?', 'Sir C.V. Raman discovered the Raman Effect on 28 February 1928, celebrated annually as National Science Day in India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fe3bc94-0958-4ab8-a26f-21b94069bce4', 'Sir C.V. Raman (Chandrasekhara Venkata Raman)', true, '81f6d161-1bd8-4ce9-8748-04f2b7efaad1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('324c4a4f-65fa-48a7-92b5-41723b2fd123', 'Jagadish Chandra Bose', false, '81f6d161-1bd8-4ce9-8748-04f2b7efaad1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9ca287a-c27d-4632-b6a6-65873747c8ea', 'Satyendra Nath Bose', false, '81f6d161-1bd8-4ce9-8748-04f2b7efaad1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a801344-8d90-4e7b-bc67-97ade541ba93', 'Meghnad Saha', false, '81f6d161-1bd8-4ce9-8748-04f2b7efaad1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b451e5ca-3fbf-4bd0-8f5b-af47a4b43ed9', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'Why is ''National Science Day'' celebrated across India every year on 28th February?', 'The Government of India designated 28 February as National Science Day in 1986 to honor the Raman Effect discovery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d56b3413-99f9-47b5-ac36-a7582aef055e', 'To commemorate Sir C.V. Raman''s historic discovery of the ''Raman Effect'' on 28th February 1928', true, 'b451e5ca-3fbf-4bd0-8f5b-af47a4b43ed9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('178a86a2-ae5a-4034-874a-1854101faa74', 'To celebrate the launch of India''s first satellite', false, 'b451e5ca-3fbf-4bd0-8f5b-af47a4b43ed9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93abe878-4645-4d10-b4b8-0885b953c5f8', 'To mark the founding of ISRO', false, 'b451e5ca-3fbf-4bd0-8f5b-af47a4b43ed9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1121f51-40e0-4a85-a01b-99828352d3f5', 'To celebrate Dr. Kalam''s birthday', false, 'b451e5ca-3fbf-4bd0-8f5b-af47a4b43ed9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d89d6a63-b5c3-4b98-92ed-b1a3d83402e1', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'Who is reverently regarded as the ''Father of the Indian Space Programme''?', 'Dr. Vikram Sarabhai founded ISRO in 1969 and established the Thumba Equatorial Rocket Launching Station.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2552ff66-044c-4691-be39-b787b7176d39', 'Dr. Vikram Sarabhai', true, 'd89d6a63-b5c3-4b98-92ed-b1a3d83402e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6ce8ce1-d40f-4b65-bbd4-e6449a3c48cd', 'Dr. Homi Bhabha', false, 'd89d6a63-b5c3-4b98-92ed-b1a3d83402e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('820c6f3d-fa1c-4260-af73-7bbde4457e76', 'Dr. Satish Dhawan', false, 'd89d6a63-b5c3-4b98-92ed-b1a3d83402e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02295d5f-4188-4402-bcd3-322f8c8cef84', 'Dr. U.R. Rao', false, 'd89d6a63-b5c3-4b98-92ed-b1a3d83402e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f328e70-69d4-4a87-b1ef-78acfba2c386', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'What was India''s FIRST indigenous artificial satellite, launched into space on 19th April 1975, named after?', 'Aryabhata, built by ISRO and launched by a Soviet Kosmos-3M rocket in 1975, marked India''s entry into the space age.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('885f34cb-8d13-4ad9-a637-2297220601bf', 'Aryabhata (named after ancient Indian astronomer-mathematician)', true, '0f328e70-69d4-4a87-b1ef-78acfba2c386');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fe7890d-1fc8-40eb-8075-31928dd70400', 'Bhaskara I', false, '0f328e70-69d4-4a87-b1ef-78acfba2c386');
