INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f7e29bf-7b78-4eb5-bbc1-8b1e14013874', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'On 23rd August 2023, India''s Chandrayaan-3 mission made history by becoming the FIRST country in the world to successfully land a spacecraft near which region of the Moon?', 'On 23 August 2023, Chandrayaan-3''s Vikram lander touched down at 69.37°S near the lunar south pole (celebrated as National Space Day).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ff39ecb-5213-4081-9165-f0864c436785', 'Lunar South Pole (Shiv Shakti Point)', true, '3f7e29bf-7b78-4eb5-bbc1-8b1e14013874');
