INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4ba333c-46ae-430d-8df7-1868136478c1', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Easy', 'In the Pallava and southern kingdoms, what were local village assemblies called?', 'Southern rural administration operated through assemblies: Sabha (Brahmadeya landholders), Ur (peasant landowners), Nagaram (merchants).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10f32c96-3649-408c-ab03-8bcd9ac48251', 'Sabha (Brahmana landholders), Ur (non-Brahmana village assembly), and Nagaram (merchant guild)', true, 'e4ba333c-46ae-430d-8df7-1868136478c1');
