INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9892136e-2610-47d3-9c1a-c16ec55ad538', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'How did Harisena in the Allahabad Prashasti describe Samudragupta''s differentiated policy towards the TWELVE rulers of ''Dakshinapatha'' (South India)?', 'Grahana-Mokshanugraha policy: Samudragupta defeated southern rulers, accepted their submission/tribute, and reinstated them.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc38a175-ce33-4149-be55-e2518cf63118', 'They surrendered after being defeated, were magnanimously liberated by Samudragupta, and allowed to rule their kingdoms again on condition of paying regular tribute and obeisance (Dharma Vijaya)', true, '9892136e-2610-47d3-9c1a-c16ec55ad538');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a026413-5edd-439d-af87-401a46659e9d', 'They were all executed and their land was destroyed', false, '9892136e-2610-47d3-9c1a-c16ec55ad538');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11869793-757d-46b6-b48a-96502a6c17dc', 'They were taken to Pataliputra as prisoners forever', false, '9892136e-2610-47d3-9c1a-c16ec55ad538');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d216bb7b-415b-4e35-baec-aaad80479f67', 'They were made to join the Roman army', false, '9892136e-2610-47d3-9c1a-c16ec55ad538');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42fa26c4-7144-4558-a067-a37f8821f324', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'How did Samudragupta treat the rulers of ''Aryavarta'' (Northern Gangetic India)?', 'Prasabhoddharana policy: the 9 Gangetic Aryavarta rulers were overthrown and their lands annexed into direct Gupta governance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2ffc59b-b098-4ab5-ac50-ecaab4f0175c', 'Nine rulers of Aryavarta were uprooted completely and their territories were annexed directly into the Gupta Empire', true, '42fa26c4-7144-4558-a067-a37f8821f324');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('071678b4-88ac-4793-8de1-a33488524260', 'He made peace treaties with them without war', false, '42fa26c4-7144-4558-a067-a37f8821f324');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce12dc49-8187-4b22-8e5a-8c86579cd16b', 'He gave them half his gold', false, '42fa26c4-7144-4558-a067-a37f8821f324');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b21ae98-b9c3-4b79-b1dd-e92d62040b20', 'He allowed them to rule independently', false, '42fa26c4-7144-4558-a067-a37f8821f324');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f78b7218-237b-41d5-bd03-b3b83e2736b8', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'Who were the ''Samantas'' in early medieval Indian administration?', 'Samantas were feudal military vassals who maintained private retinues, remitted tribute, and revolted when central kings weakened.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d090d898-f4e8-4956-a5f3-d1d5c0cdebb4', 'Military chieftains and feudal lords who provided armed troops to the king during war, collected local revenue, and paid tribute to the monarch', true, 'f78b7218-237b-41d5-bd03-b3b83e2736b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94bb153a-cda4-401b-8997-525240d81185', 'Foreign ambassadors from China', false, 'f78b7218-237b-41d5-bd03-b3b83e2736b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac055956-69cb-4f87-bcb1-3ad6d8a23f56', 'Buddhist monks living in caves', false, 'f78b7218-237b-41d5-bd03-b3b83e2736b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53bbfdf1-23bc-44fe-92ad-202ed92ecc76', 'Peasant farmers who ploughed land', false, 'f78b7218-237b-41d5-bd03-b3b83e2736b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d79fa575-16c1-40fc-9657-872197bb58a8', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What administrative change occurred in key government posts (such as ''Maha-danda-nayaka'' / Chief Judicial Officer) during the Gupta era?', 'Gupta bureaucracy became hereditary: sons inherited ministerial and judicial offices, concentrating local bureaucratic power.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a61c4e5-646f-4f09-85cb-2b40c585b039', 'Administrative posts became increasingly HEREDITARY (e.g. Harisena was a Maha-danda-nayaka just like his father Harisena before him)', true, 'd79fa575-16c1-40fc-9657-872197bb58a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eccfa42a-1459-4c70-a785-644d0499322f', 'Officers were selected through written computer exams', false, 'd79fa575-16c1-40fc-9657-872197bb58a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eec10ede-1907-4768-bbc7-21e0ee867d65', 'Kings replaced all officers every year', false, 'd79fa575-16c1-40fc-9657-872197bb58a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('690ecd26-f61a-46da-8987-5bed2434a993', 'Officers had to be Roman citizens', false, 'd79fa575-16c1-40fc-9657-872197bb58a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('087e12f8-f8a7-4c9e-a365-498e033a73af', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What was a single official holding MULTIPLE administrative portfolios called during the Gupta period (e.g. Harisena being a Kumaramatya, Maha-danda-nayaka, and Sandhi-vigrahika)?', 'Harisena held three concurrent ranks: Kumaramatya (minister), Maha-danda-nayaka (chief justice), and Sandhi-vigrahika (minister of war and peace).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15bba179-d881-423e-81fb-650f2de6f6e7', 'Cumulation of offices (holding multiple concurrent ministerial, judicial, and diplomatic roles)', true, '087e12f8-f8a7-4c9e-a365-498e033a73af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('438e8942-0d89-4ccc-a9e1-b151487935b4', 'Military dictatorship', false, '087e12f8-f8a7-4c9e-a365-498e033a73af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('799f2d50-86e5-47bf-8114-463bee2a00cf', 'Feudal democracy', false, '087e12f8-f8a7-4c9e-a365-498e033a73af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9f0c175-b642-4373-bc97-75e01f752c50', 'Monastic governance', false, '087e12f8-f8a7-4c9e-a365-498e033a73af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52cb8087-279b-4743-ba36-17ef85bb6bfc', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What does the title ''Sandhi-vigrahika'' mean in Gupta administrative terminology?', '''Sandhi'' (treaty/alliance) + ''Vigraha'' (warfare): Sandhi-vigrahika handled foreign diplomacy and military treaties.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77dc7ca7-da58-40f1-8332-ae27250981c1', 'Minister of War and Peace (Foreign Affairs Minister)', true, '52cb8087-279b-4743-ba36-17ef85bb6bfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2477212-3c3a-4cb7-87b7-de3466e672f7', 'Chief Police Officer', false, '52cb8087-279b-4743-ba36-17ef85bb6bfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32dac97c-ef12-46d4-a6a0-7854e6291d9f', 'Treasury Collector', false, '52cb8087-279b-4743-ba36-17ef85bb6bfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe786fde-9307-402e-9bcd-a08da0b68470', 'Royal Cook', false, '52cb8087-279b-4743-ba36-17ef85bb6bfc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30077bdf-3659-47e8-a768-cc44369b49c0', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What magnificent monolithic rock-cut shrines (known as the ''Five Rathas'') and the Shore Temple were built by Pallava kings at:', 'Narasimhavarman I (Mamalla) sculpted the monolithic Pancha Pandava Rathas and structural Shore Temple at coastal Mahabalipuram.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('685d1c18-2e52-4b75-8f74-61d64069564d', 'Mahabalipuram (Mamallapuram)', true, '30077bdf-3659-47e8-a768-cc44369b49c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adf63fc0-aaef-47e0-b67f-6b7f7c328a72', 'Kanchipuram', false, '30077bdf-3659-47e8-a768-cc44369b49c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0870b77b-9b37-4618-a5f3-bb07475370bb', 'Aihole', false, '30077bdf-3659-47e8-a768-cc44369b49c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ff7bce8-27e5-47d9-9343-b9eb86ac2d50', 'Pattadakal', false, '30077bdf-3659-47e8-a768-cc44369b49c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b88d6268-da29-4a38-badc-4cdfd9df4249', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'How did the poet Banabhatta describe King Harshavardhana''s army marching through the countryside in ''Harshacharita''?', 'Banabhatta''s vivid prose depicts royal armies as colossal marching cities escorted by war elephants, music, and peasant offerings.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e7a6ab4-79fc-4ed3-9292-67da0d13138d', 'A massive traveling city with elephants carrying musicians and luggage, horses, bullock carts laden with food, while villagers rushed to offer curds, molasses, and flowers', true, 'b88d6268-da29-4a38-badc-4cdfd9df4249');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e63b20d-d3c5-4af3-9a55-86bb3bd21117', 'A tiny group of 5 soldiers walking silently in dark', false, 'b88d6268-da29-4a38-badc-4cdfd9df4249');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fc3722b-6341-457c-a1df-582c508f3b44', 'Soldiers flying in balloons', false, 'b88d6268-da29-4a38-badc-4cdfd9df4249');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c98c936f-bdb4-45bd-8e5a-24b4de71fed8', 'A fleet of ocean submarines', false, 'b88d6268-da29-4a38-badc-4cdfd9df4249');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75e40482-2a10-479f-86e5-2dd415ad8dee', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What language did the elite king and Brahmanas speak in Kalidasa''s plays (like Abhijnanashakuntalam), while ordinary women and commoners spoke Prakrit?', 'Classical Sanskrit drama used sociolinguistic diglossia: high-status males spoke refined Sanskrit while women and commoners spoke Prakrit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('490d0edb-1ef8-4f0a-9b74-55dc44959353', 'Sanskrit', true, '75e40482-2a10-479f-86e5-2dd415ad8dee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('268dfea8-473c-4921-9942-25e80cee493e', 'Tamil', false, '75e40482-2a10-479f-86e5-2dd415ad8dee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22299774-d5c3-428c-b3c6-0652ac6ab798', 'Greek', false, '75e40482-2a10-479f-86e5-2dd415ad8dee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03f4b27a-5de8-4eed-8206-6dfd2dc913e5', 'Latin', false, '75e40482-2a10-479f-86e5-2dd415ad8dee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d95436c8-b406-496d-8f8e-aae84f790673', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'How did the Chinese pilgrim Fa Xian describe the miserable condition of the ''Untouchables'' (Chandalas) in 5th-century Indian cities?', 'Fa Xian''s travelogue documented rigid caste untouchability and spatial segregation enforced on Chandalas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97f8ce2a-c79a-4ffc-8c61-7cc151ca17fd', 'They lived outside the city walls, and when entering a town or marketplace, had to strike a piece of wood to announce their presence so people could avoid touching them', true, 'd95436c8-b406-496d-8f8e-aae84f790673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92b48c4d-4aaa-44da-a0a0-643e64fedd52', 'They were made governors of cities', false, 'd95436c8-b406-496d-8f8e-aae84f790673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4456f6e1-d8b2-4234-94d6-f3e5b1385fe4', 'They lived in royal palaces', false, 'd95436c8-b406-496d-8f8e-aae84f790673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d031dc4b-3ba2-4f28-b50f-3616fa62cefd', 'They were celebrated as national heroes', false, 'd95436c8-b406-496d-8f8e-aae84f790673');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae0265a4-fbe8-47ca-933f-053d6713b975', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'Who was the great astronomer and mathematician of the Gupta era who wrote the ''Aryabhatiya'', calculated the value of π (pi), and stated that the Earth rotates on its own axis?', 'Aryabhata (born 476 CE in Pataliputra) authored the Aryabhatiya, formulating earth''s axial rotation, solar/lunar eclipse math, and π = 3.1416.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b11d6297-46f2-4faa-8cc0-79354472e77d', 'Aryabhata', true, 'ae0265a4-fbe8-47ca-933f-053d6713b975');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c516eebd-6f5f-43ed-a7ed-4877fc8cae1a', 'Varahamihira', false, 'ae0265a4-fbe8-47ca-933f-053d6713b975');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2e9d1d9-23c2-4704-8b3f-878795b50248', 'Brahmagupta', false, 'ae0265a4-fbe8-47ca-933f-053d6713b975');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c542373-c828-4aa0-89a9-4e13eb85b2bf', 'Bhaskaracharya', false, 'ae0265a4-fbe8-47ca-933f-053d6713b975');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('433f34bc-c13d-4e30-85ce-c4900c48492a', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What happened to the Chalukyas and Pallavas around the 8th century CE?', 'Dantidurga founded the Rashtrakuta empire overthrowing Chalukyas, while Imperial Cholas (Vijayalaya) annexed Pallava Kanchi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52908dd6-c60b-4ee7-9e80-a03ffe89b027', 'They were gradually replaced by new rising dynasties: the Rashtrakutas (who eclipsed the Chalukyas in the Deccan) and the Cholas (who conquered the Pallavas in Tamil country)', true, '433f34bc-c13d-4e30-85ce-c4900c48492a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('457dbbd8-26fb-4c67-ba40-3f3df59cc99e', 'They migrated to Rome', false, '433f34bc-c13d-4e30-85ce-c4900c48492a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('274e2b4f-33bc-41e7-b80f-31acdb6b2532', 'They ruled India until the 20th century', false, '433f34bc-c13d-4e30-85ce-c4900c48492a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8faf944b-f065-4295-8151-151545b86e87', 'Their cities sank into the ocean', false, '433f34bc-c13d-4e30-85ce-c4900c48492a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2727b1ad-f816-4cd7-abab-8e52680930ed', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What was the ''Sabha'' in the Pallava administrative system?', 'The Sabha governed Brahmadeya villages via specialized sub-committees (Variyams) overseeing canals, tanks, and temple charities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5de3d3d2-ea36-41ec-9874-85efe03f41ac', 'An assembly of Brahmana landowners which functioned through sub-committees looking after irrigation, agricultural operations, roads, and local temples', true, '2727b1ad-f816-4cd7-abab-8e52680930ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4be74724-fa22-4162-a96b-e3284b5388dc', 'An assembly of foreign merchants', false, '2727b1ad-f816-4cd7-abab-8e52680930ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25bf29ea-8edc-4244-86ed-84547d355259', 'A court of musicians', false, '2727b1ad-f816-4cd7-abab-8e52680930ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c682ad1-5cca-4b8f-b787-b896e0f5dcdc', 'An army unit of war elephants', false, '2727b1ad-f816-4cd7-abab-8e52680930ed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f2600cc-14fa-4ef8-839b-9aebebd5075e', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What was the ''Nagaram'' in southern kingdoms?', 'Nagaram represented mercantile corporations managing marketplaces, commercial taxes, and civic affairs in commercial hubs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94b5241d-f626-430b-b4ab-e0dd5a00cda6', 'An organization and guild council of merchants that managed urban commerce and civic administration in trading towns', true, '2f2600cc-14fa-4ef8-839b-9aebebd5075e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96a29fe7-fbc0-4a39-9e78-230b86483199', 'A village of farmers', false, '2f2600cc-14fa-4ef8-839b-9aebebd5075e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b28c361-159a-4918-9bce-d69c4aba7f45', 'A school for archery', false, '2f2600cc-14fa-4ef8-839b-9aebebd5075e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('146066fa-7371-4ed1-890d-b58144dc6d71', 'A palace treasury', false, '2f2600cc-14fa-4ef8-839b-9aebebd5075e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f761c1a-3aa0-4b74-8a2d-d6ab801d33b9', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'Why was the invention of the mathematical ''Zero'' (Shunya) and the Decimal System in India during this period a monumental gift to world civilization?', 'The Indian invention of zero and place-value decimal notation revolutionized global computational mathematics and algorithmic science.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dba8860b-23fb-4de1-8338-841129da5c43', 'It simplified mathematical calculations, enabled positional place-value arithmetic, and was adopted by Arab mathematicians who transmitted it to Europe as ''Hindu-Arabic numerals''', true, '0f761c1a-3aa0-4b74-8a2d-d6ab801d33b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3954de6d-e089-41d1-89e7-44298a542493', 'Because zero was used as a weapon in war', false, '0f761c1a-3aa0-4b74-8a2d-d6ab801d33b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9522aec7-2c08-43a0-8e82-054ccdf048bc', 'Because it stopped money from being spent', false, '0f761c1a-3aa0-4b74-8a2d-d6ab801d33b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b4fe598-31ef-41d4-ba09-a986f891075e', 'Because it was carved on all swords', false, '0f761c1a-3aa0-4b74-8a2d-d6ab801d33b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68e9c8ef-d40b-4616-af57-519f4c1ebcbe', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What medical treatise on surgery and surgical instruments was authored in ancient India by the father of plastic surgery?', 'Sushruta pioneered rhinoplasty, cataract surgery, and over 120 surgical instruments in the ''Sushruta Samhita''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bed96e39-456b-4fef-9fa2-ddfadf3b0e42', 'Sushruta Samhita (by Sushruta)', true, '68e9c8ef-d40b-4616-af57-519f4c1ebcbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fa52452-6650-42b4-8234-89ea544d04ac', 'Charaka Samhita', false, '68e9c8ef-d40b-4616-af57-519f4c1ebcbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c87c33d-6119-4479-85c4-d6f3b8a1d975', 'Aryabhatiya', false, '68e9c8ef-d40b-4616-af57-519f4c1ebcbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba5b6e49-88d3-45cb-8f22-cf885b5d56cf', 'Brihat Samhita', false, '68e9c8ef-d40b-4616-af57-519f4c1ebcbe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75025214-87d1-4fe1-b9b7-fb7cdf73d5d0', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Read the statements:
