INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c709ad3-6558-40d9-8609-3f315060b0df', 'Samudragupta - Harisena', false, 'e161c877-064c-4e27-8c74-40eab49d467f');
