INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19168d7f-97a9-4c08-91fb-77f6378a6f9a', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Match Column I (Ancient Dynasties) with Column II (Prominent Capitals / Royal Centers):
(a) Guptas     -> (i) Pataliputra and Ujjain
(b) Pushyabhuti-> (ii) Kannauj and Thanesar
(c) Chalukyas  -> (iii) Vatapi (Badami) and Aihole
(d) Pallavas   -> (iv) Kanchipuram and Mahabalipuram', 'Guptas = Pataliputra/Ujjain; Harsha = Kannauj; Chalukyas = Badami; Pallavas = Kanchipuram.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ac5685d-dcc5-4a5c-9188-b5b71443b09a', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '19168d7f-97a9-4c08-91fb-77f6378a6f9a');
