INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62f96a22-49b1-4d69-9d3b-c933b0b36756', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Read the statements regarding classical Indian science:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08c97c10-b766-4c83-bf04-75ad852ea446', 'Statements 1 and 2 only', true, '62f96a22-49b1-4d69-9d3b-c933b0b36756');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a3279b9-0626-4cbd-a172-388d0954069b', 'Statements 2 and 3 only', false, '62f96a22-49b1-4d69-9d3b-c933b0b36756');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52fe7177-5f32-4887-9954-b571c6d63519', 'Statements 1 and 3 only', false, '62f96a22-49b1-4d69-9d3b-c933b0b36756');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('395256a9-a567-4a32-9d56-4019285775ce', 'All Statements 1, 2, and 3', false, '62f96a22-49b1-4d69-9d3b-c933b0b36756');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bb02ab5-5c84-4a80-a443-5daf9f556c12', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'What dramatic story of social justice is depicted in Kalidasa''s play ''Abhijnanashakuntalam'' involving a poor Fisherman and the King''s signet ring?', 'Kalidasa''s fisherman scene critiques lower-level police bribery and class prejudice in ancient royal administration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25145bee-ba7b-4055-98f7-be227899ae34', 'A poor fisherman found the king''s lost signet ring inside a fish belly; police officers falsely accused him of theft and beat him until the king recognized the ring and rewarded the fisherman, exposing systemic judicial corruption and prejudice against the poor', true, '8bb02ab5-5c84-4a80-a443-5daf9f556c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01c5977-c0da-4e3f-b4a5-402acf26133c', 'The fisherman became king', false, '8bb02ab5-5c84-4a80-a443-5daf9f556c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b7f4790-369b-4f92-af43-e71495ac6a67', 'The king threw the ring into fire', false, '8bb02ab5-5c84-4a80-a443-5daf9f556c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9898e4c4-5d92-450d-9d40-975a3c1c95a6', 'The fish turned into gold', false, '8bb02ab5-5c84-4a80-a443-5daf9f556c12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0700bc3-98f8-4293-a356-3e81193d9dd4', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'What metallurgical feature of the 4th-century CE Iron Pillar of Delhi at Mehrauli prevents it from rusting even after 1,600 years of exposure to sun and monsoon rains?', 'Solid-state forge welding with high-phosphorus slag formed a catalytic protective misawite barrier shielding against corrosion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef488838-b8cb-4072-932f-8b44d80c3950', 'High phosphorus content in forge-welded wrought iron which formed a protective passive amorphous iron hydrogen phosphate film (''misawite'') on the metal surface', true, 'a0700bc3-98f8-4293-a356-3e81193d9dd4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf8f2c00-a032-4396-ae69-8044a4b1d053', 'It is painted with modern plastic paint', false, 'a0700bc3-98f8-4293-a356-3e81193d9dd4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb2fcf4f-421c-4cee-ae7c-49456c12eead', 'It is made of pure gold inside', false, 'a0700bc3-98f8-4293-a356-3e81193d9dd4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cbcb8b3-fe65-4fd4-a5a5-b489aeae9c41', 'It is kept inside an air-conditioned room', false, 'a0700bc3-98f8-4293-a356-3e81193d9dd4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('add7c990-02c4-40d7-bf08-5f46de8d2f0f', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Consider four prominent rulers of classical India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('583f9afd-26f8-4768-97de-328df6d74da3', 'Rulers 3 and 4 (Harshavardhana and Pulakeshin II)', true, 'add7c990-02c4-40d7-bf08-5f46de8d2f0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8706e3d5-9c8b-421c-a19d-c9012e38573b', 'Rulers 1 and 2', false, 'add7c990-02c4-40d7-bf08-5f46de8d2f0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1084f514-ab5d-4ffd-a636-a3cfe9ac42e9', 'Rulers 1 and 3', false, 'add7c990-02c4-40d7-bf08-5f46de8d2f0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49f5fa0d-1392-4722-b645-356ea42fdfd0', 'Rulers 2 and 4', false, 'add7c990-02c4-40d7-bf08-5f46de8d2f0f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1ebbc75-4af3-4c8a-a711-e9afd13c050b', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'What socio-economic power did the Assemblies (Sabhas and Urs) hold in early medieval South India?', 'Southern assemblies exercised extensive fiscal, judicial, and civic self-governance over land tenure and infrastructure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff12c709-9069-4ce2-8216-68f0dca1134b', 'They levied local agricultural taxes, maintained communal irrigation tanks, managed village dispute courts, and acted as autonomous corporate governing bodies', true, 'c1ebbc75-4af3-4c8a-a711-e9afd13c050b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0591256c-57b1-4290-a96a-8b6b47b4322a', 'They had no power and followed only royal orders', false, 'c1ebbc75-4af3-4c8a-a711-e9afd13c050b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b50a5b10-a225-4349-82d7-aa954243aeba', 'They were only allowed to sing prayers', false, 'c1ebbc75-4af3-4c8a-a711-e9afd13c050b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b83a90a6-7ae5-4cd9-8280-f71995023d2b', 'They were made of royal soldiers only', false, 'c1ebbc75-4af3-4c8a-a711-e9afd13c050b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86cb676f-1dda-4a94-8622-61aef78958e3', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'How did the genealogical lineages (Vamshavalis) recorded in Prashastis help historians reconstruct ancient Indian history?', 'Epigraphic genealogies reconstruct dynastic chronologies, matrimonial alliances (Gupta-Licchavi), and political succession.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab3e4d54-aeeb-4f4b-816b-c0afed48e432', 'They provide sequential lists of royal ancestors (father, grandfather, great-grandfather) and maternal alliances (e.g. Samudragupta''s mother Kumara Devi was a Licchavi princess), establishing chronology', true, '86cb676f-1dda-4a94-8622-61aef78958e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77418c02-60a3-40c5-aa1c-bb3bb8ca7407', 'They provide recipes for ancient food', false, '86cb676f-1dda-4a94-8622-61aef78958e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96b9e15e-cffd-4eb2-abc1-6801f9f0ede2', 'They describe stars in astronomy', false, '86cb676f-1dda-4a94-8622-61aef78958e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f3318d0-e489-4cbf-8c08-6a681666e855', 'They list animal species', false, '86cb676f-1dda-4a94-8622-61aef78958e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e233f830-bd83-4d60-82d1-a9bc5891f438', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Why did Chinese pilgrim Xuan Zang spend extensive time studying at King Harsha''s grand assemblies at Kannauj and Prayag in 643 CE?', 'Harsha convened 18-day theological assemblies at Kannauj and the grand quinquennial Mahamoksha festival at Prayag.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a92d145-1325-4b95-a0b3-5eee8dd2b5d3', 'To participate in inter-religious philosophical disputations between Buddhist scholars, Vedic Brahmanas, and Jain thinkers under Harsha''s royal patronization', true, 'e233f830-bd83-4d60-82d1-a9bc5891f438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c126028-1b69-4b91-a9ca-eb6eaec7f449', 'To purchase silk for China', false, 'e233f830-bd83-4d60-82d1-a9bc5891f438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('759b3966-04cf-4967-8a12-1ff46597fbd9', 'To recruit soldiers for the Chinese army', false, 'e233f830-bd83-4d60-82d1-a9bc5891f438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bd5adb1-f62a-434f-a2e8-1a9cd7a51130', 'To build a stone castle', false, 'e233f830-bd83-4d60-82d1-a9bc5891f438');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52669f7e-a0b4-48ae-bd3e-06a866131f5e', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'What holistic view of Indian classical civilization is established in Chapter 11 of NCERT History?', 'The chapter portrays classical India''s golden synthesis of scientific breakthroughs, soaring literature, temple architecture, and grassroots assemblies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86d25b56-2b09-4f90-9b4f-f686054f7c5c', 'A golden era of artistic, literary, scientific, and architectural brilliance flourishing alongside complex feudal political networks and vibrant local democratic village institutions', true, '52669f7e-a0b4-48ae-bd3e-06a866131f5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01e1a014-30b9-40aa-89d0-ce5ad705a4aa', 'A period of complete societal collapse', false, '52669f7e-a0b4-48ae-bd3e-06a866131f5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b488bdc-4da3-4306-a492-da360ac21ae8', 'A primitive era without science or art', false, '52669f7e-a0b4-48ae-bd3e-06a866131f5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c02328b0-88c8-43c2-95ca-525d8d568279', 'A civilization isolated from the rest of Asia', false, '52669f7e-a0b4-48ae-bd3e-06a866131f5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93321171-885e-44f7-80ad-8b4952a8b5ba', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Easy', 'क्रिया के जिस रूप से उसके संपन्न होने के समय (Time of Action) का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'क्रिया के होने या करने के समय तथा उसकी पूर्णता/अपूर्णता का बोध कराने वाले रूप को ''काल'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efdc244e-9586-49fe-a7c6-91d6c6a05e94', 'काल (Tense)', true, '93321171-885e-44f7-80ad-8b4952a8b5ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cd9c0ea-392a-4428-9e0e-dea4c81aefe7', 'कारक', false, '93321171-885e-44f7-80ad-8b4952a8b5ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93607e64-8aad-4577-9928-13936781ac85', 'वाच्य', false, '93321171-885e-44f7-80ad-8b4952a8b5ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('620666b1-1c32-467d-a138-8197d52c9285', 'समास', false, '93321171-885e-44f7-80ad-8b4952a8b5ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d80c1f45-f86d-467c-bc29-d320e418baa4', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Easy', 'हिंदी व्याकरण में काल के मुख्य रूप से कितने भेद होते हैं?', 'काल के 3 मुख्य भेद हैं: भूतकाल (बीता हुआ समय), वर्तमानकाल (चल रहा समय), और भविष्यत् काल (आने वाला समय)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d977086-d28c-431a-acea-b692afed6ab0', 'तीन भेद (1. भूतकाल - Past, 2. वर्तमानकाल - Present, 3. भविष्यत् काल - Future)', true, 'd80c1f45-f86d-467c-bc29-d320e418baa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2ddb4df-cc35-4da8-b13a-03a34e57fbb2', 'चार भेद', false, 'd80c1f45-f86d-467c-bc29-d320e418baa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10fc8bf0-8db1-4fdd-9dce-61d624938229', 'दो भेद', false, 'd80c1f45-f86d-467c-bc29-d320e418baa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bce5caf0-a99b-4afd-a1e8-992c68ca0734', 'पाँच भेद', false, 'd80c1f45-f86d-467c-bc29-d320e418baa4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bda5a51e-82ed-440f-b569-c8cdf6287030', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Easy', 'क्रिया के जिस रूप से यह पता चले कि कार्य बीते हुए समय में संपन्न हो चुका है (जैसे: ''राम ने पत्र लिखा'', ''वह कल आया था''), उसे क्या कहते हैं?', 'बीते हुए समय में क्रिया के निष्पादन को ''भूतकाल'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38672c1d-5a8a-45e2-8c15-8255341f08c6', 'भूतकाल (Past Tense)', true, 'bda5a51e-82ed-440f-b569-c8cdf6287030');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10c3582c-cef9-4e4a-a744-2792fe7b1987', 'वर्तमानकाल', false, 'bda5a51e-82ed-440f-b569-c8cdf6287030');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64a73491-9d49-46b9-8582-040da80b07bb', 'भविष्यत् काल', false, 'bda5a51e-82ed-440f-b569-c8cdf6287030');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3af0654-f4ba-489a-b80d-cbeeea44cd69', 'आज्ञाकाल', false, 'bda5a51e-82ed-440f-b569-c8cdf6287030');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a6a7c23-3177-41ce-96bb-476ec0a4a925', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Easy', 'क्रिया के जिस रूप से कार्य के वर्तमान (चल रहे) समय में होने का बोध होता है (जैसे: ''रोहन पढ़ता है'', ''वर्षा हो रही है''), उसे क्या कहते हैं?', 'वर्तमान समय में क्रिया के व्यापार का बोध ''वर्तमानकाल'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29787699-9500-4f3b-b455-1d021517e09e', 'वर्तमानकाल (Present Tense)', true, '5a6a7c23-3177-41ce-96bb-476ec0a4a925');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efcfbfa1-059c-41b3-8273-335c071b4806', 'भूतकाल', false, '5a6a7c23-3177-41ce-96bb-476ec0a4a925');
