INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0735c7d9-1c5d-4209-81f1-3a764c354566', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Medium', 'क्रिया के जिस रूप से यह पता चले कि कार्य अभी-अभी कुछ ही समय पहले समाप्त हुआ है (जैसे: ''मैंने अभी-अभी चाय पी है'', ''गाड़ी स्टेशन पर आई है''), उसे क्या कहते हैं?', 'निकटवर्ती बीते समय में अभी-अभी पूर्ण हुई क्रिया ''आसन्न भूतकाल'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e081af8-27ad-46e0-9913-88592970ca94', 'आसन्न भूतकाल (Recent Past Tense - ''आसन्न'' अर्थात् निकट/समीप)', true, '0735c7d9-1c5d-4209-81f1-3a764c354566');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a799214-e03c-4fb6-8a89-f3f8082db798', 'पूर्ण भूतकाल', false, '0735c7d9-1c5d-4209-81f1-3a764c354566');
