INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5fcae7a-0a17-4385-9538-a99e9c8170cf', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Medium', 'क्रिया के जिस रूप से यह जाना जाए कि कार्य भूतकाल में शुरू हुआ था किन्तु बोलते समय तक समाप्त नहीं हुआ था, चल रहा था (जैसे: ''वर्षा हो रही थी'', ''अध्यापक पढ़ा रहे थे''), उसे क्या कहते हैं?', '''रहा था, रही थी, रहे थे'' भूतकाल में क्रिया की निरंतरता (अपूर्ण भूत) दर्शाते हैं।', NOW()) ON CONFLICT DO NOTHING;
