INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a126c38c-c80e-4d2a-beb5-96341e092613', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Medium', 'क्रिया के जिस रूप से भूतकाल में कार्य के होने में संदेह (Doubt) प्रकट हो (जैसे: ''बस छूट गई होगी'', ''उसने खाना खा लिया होगा''), उसे क्या कहते हैं?', 'बीते समय में क्रिया की सिद्धि पर अनिश्चय/संदेह होने पर ''संदिग्ध भूतकाल'' होता है (गया होगा, पढ़ी होगी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f5db436-e932-4e0f-bc89-52257874d366', 'संदिग्ध भूतकाल (Suspicious / Probable Past)', true, 'a126c38c-c80e-4d2a-beb5-96341e092613');
