INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f27f6584-7b8a-4be6-affe-6df53009d559', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Medium', 'जहाँ भूतकाल की एक क्रिया दूसरी क्रिया के होने पर निर्भर (conditional) थी किन्तु कार्य संपन्न नहीं हो सका (जैसे: ''यदि वर्षा होती, तो फसल अच्छी होती'', ''यदि परिश्रम करते, तो सफल हो जाते''), वहाँ कौन-सा काल होता है?', 'कारण-कार्य पर आश्रित अधूरी रह गई भूतकालीन क्रिया ''हेतुहेतुमद् भूतकाल'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
