INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b9aea49-4992-4d25-a0ae-c815cb0cd062', 'गाड़ी आई होगी - सामान्य भविष्यत्', true, '2ba072de-271d-4b92-99f3-8f350c91d65c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64af92b2-f81e-42b8-9831-f5f9d6bdec21', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'सुमेलित कीजिए (वाक्य और उनके सटीक काल भेद):
(क) छात्र पढ़ रहा था        -> (i) आसन्न भूतकाल
(ख) छात्र ने पुस्तक पढ़ी है  -> (ii) अपूर्ण भूतकाल
(ग) छात्र पढ़ता होगा        -> (iii) संभाव्य भविष्यत्
(घ) कदाचित कल धूप निकले    -> (iv) संदिग्ध वर्तमानकाल', 'पढ़ रहा था = अपूर्ण भूत; पढ़ी है = आसन्न भूत; पढ़ता होगा = संदिग्ध वर्तमान; कदाचित निकले = संभाव्य भविष्यत्।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dd40ae8-8eca-4b73-86e0-e5609b7aff09', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', true, '64af92b2-f81e-42b8-9831-f5f9d6bdec21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3764838-2d12-4c02-a6e0-c6ced7471ca1', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '64af92b2-f81e-42b8-9831-f5f9d6bdec21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c90b307-7a6a-4cdb-bf3f-233f64991970', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '64af92b2-f81e-42b8-9831-f5f9d6bdec21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d008d75-5f1f-4411-bd0a-b3295a7aecab', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '64af92b2-f81e-42b8-9831-f5f9d6bdec21');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4ee5289-302c-4722-a466-3e7fd7d680e9', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'आसन्न भूतकाल और सामान्य वर्तमानकाल में संरचनात्मक भेद क्या होता है?', 'आसन्न भूत = भूतकालिक निष्पत्ति + है (खाया है); सामान्य वर्तमान = स्वभाव/आवृत्ति + है (खाता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a356c95-0677-4008-a0b8-713c1b4fa756', 'आसन्न भूतकाल में भूतकालिक क्रिया के साथ ''है/हैं'' आता है (जैसे: ''वह गया है'' = क्रिया अभी समाप्त हुई) ; जबकि सामान्य वर्तमानकाल में धातु के साथ ''ता/ती/ते + है'' आता है (जैसे: ''वह जाता है'' = नित्य आदत/व्यापार)', true, 'd4ee5289-302c-4722-a466-3e7fd7d680e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8a5ef72-13a6-49ca-9ce8-269cd758c420', 'आसन्न भूतकाल में ''था'' आता है', false, 'd4ee5289-302c-4722-a466-3e7fd7d680e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82defd9e-ac9f-4382-8c7b-02d1aadce9bf', 'सामान्य वर्तमानकाल में ''होगा'' आता है', false, 'd4ee5289-302c-4722-a466-3e7fd7d680e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dfa5691-f7ac-4ad2-b667-b0fedda1bef4', 'दोनों में कोई अंतर नहीं है', false, 'd4ee5289-302c-4722-a466-3e7fd7d680e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20361937-a200-4334-befd-c5a5413d124b', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'ऐतिहासिक सत्य या स्थायी नियम व्यक्त करने के लिए भूतकाल के स्थान पर किस काल का प्रयोग मान्य होता है?', 'सार्वभौमिक, वैज्ञानिक और भौगोलिक शाश्वत सत्यों के लिए नित्य वर्तमान (सामान्य वर्तमानकाल) प्रयुक्त होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e39dfc2f-e3ff-4d0d-8818-bb1da7f23b0d', 'सामान्य वर्तमानकाल (जैसे: ''जल 100°C पर उबलता है'', ''पृथ्वी सूर्य का चक्कर लगाती है'')', true, '20361937-a200-4334-befd-c5a5413d124b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43a157b1-8986-4c9b-8d54-3a8d546a3953', 'पूर्ण भूतकाल', false, '20361937-a200-4334-befd-c5a5413d124b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1799a6f9-a2d2-42ec-93e1-6352bb54511a', 'संभाव्य भविष्यत्', false, '20361937-a200-4334-befd-c5a5413d124b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4d737d1-89dd-43ea-ac09-726943aec0be', 'आसन्न भूतकाल', false, '20361937-a200-4334-befd-c5a5413d124b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b1a313b-b3f5-411c-87c2-4efed5e3f24d', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'वाक्य में प्रयुक्त काल का सही क्रम बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75dcdb19-acb5-4963-824f-86c9e36f6a94', 'गए थे = पूर्ण भूतकाल ; देख रहे हैं = अपूर्ण वर्तमानकाल', true, '0b1a313b-b3f5-411c-87c2-4efed5e3f24d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('804ed5ad-6a51-41f8-be0d-78429d49e55d', 'गए थे = सामान्य भूतकाल ; देख रहे हैं = सामान्य वर्तमानकाल', false, '0b1a313b-b3f5-411c-87c2-4efed5e3f24d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef265392-b504-4c9e-98f7-12e896615d1b', 'दोनों भूतकाल हैं', false, '0b1a313b-b3f5-411c-87c2-4efed5e3f24d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb1e69ff-2e0e-4b36-bdd6-bb31ec9c833f', 'दोनों वर्तमानकाल हैं', false, '0b1a313b-b3f5-411c-87c2-4efed5e3f24d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e4ab0e6-b1d3-4f22-8359-260cb1ed8148', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'समीपस्थ भविष्य (Immediate Future) को सूचित करने के लिए कभी-कभी किस काल की क्रिया का प्रयोग किया जाता है?', 'आसन्न या तत्काल घटित होने वाले भावी कार्य के लिए वर्तमानकाल (आता हूँ / आ रही है) का प्रयोग मानक है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9645a281-8cca-400e-9357-73d171cbc16a', 'वर्तमानकाल की क्रिया का (जैसे: ''मैं अभी आता हूँ'' या ''गाड़ी दस मिनट में आ रही है'')', true, '7e4ab0e6-b1d3-4f22-8359-260cb1ed8148');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aba6db18-f7db-400b-924f-85ac3e5a64ff', 'पूर्ण भूतकाल', false, '7e4ab0e6-b1d3-4f22-8359-260cb1ed8148');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66c3b11a-4e69-4e72-b88d-3d6c0ec4e00d', 'संदिग्ध भूतकाल', false, '7e4ab0e6-b1d3-4f22-8359-260cb1ed8148');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('933cb453-a6e7-4c26-a0aa-6f430cbcba9b', 'हेतुहेतुमद् भूतकाल', false, '7e4ab0e6-b1d3-4f22-8359-260cb1ed8148');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96f59f86-e25b-4524-8455-de921b28ba51', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''हेतुहेतुमद् भविष्यत् काल'' प्रयुक्त हुआ है?', 'आगामी भविष्य की कार्य-कारण पर आश्रित शर्त (मिलेगी... तो प्राप्त करेगा) ''हेतुहेतुमद् भविष्यत् काल'' है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba9869c5-9128-48e9-9d3f-dcaa6089d29f', '''यदि छात्रवृत्ती मिलेगी, तो अनुज विदेश जाकर उच्च शिक्षा प्राप्त करेगा।''', true, '96f59f86-e25b-4524-8455-de921b28ba51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f18cf7ef-c07d-4b1e-a1aa-df4a053055bc', '''यदि वर्षा होती, तो किसान खुश होते।''', false, '96f59f86-e25b-4524-8455-de921b28ba51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8b96a12-6dde-4867-8a94-2b4e80069cdf', '''शायद कल वर्षा हो।''', false, '96f59f86-e25b-4524-8455-de921b28ba51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8207f92a-9664-4a61-ad30-aeb657b92357', '''अनुज विदेश गया था।''', false, '96f59f86-e25b-4524-8455-de921b28ba51');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05912b5b-2094-404d-a3d4-a50878966501', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'वाक्य को संदिग्ध भूतकाल में शुद्ध रूप से परिवर्तित कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('070d213f-809c-4a85-854f-4c964465eb3b', 'अध्यापक ने कक्षा में व्याकरण पढ़ाया होगा। (संदिग्ध भूतकाल)', true, '05912b5b-2094-404d-a3d4-a50878966501');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2d4fe45-3b13-4d25-ab80-2ff5a99cd2a0', 'अध्यापक कक्षा में व्याकरण पढ़ाते होंगे।', false, '05912b5b-2094-404d-a3d4-a50878966501');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cde2e5ab-9ac6-473c-a978-18d5e0f05c76', 'अध्यापक ने व्याकरण पढ़ाया था।', false, '05912b5b-2094-404d-a3d4-a50878966501');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31bfb75b-b182-4c82-a565-afcbcc104cce', 'अध्यापक व्याकरण पढ़ाएँगे।', false, '05912b5b-2094-404d-a3d4-a50878966501');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2112dee-ee19-49f8-a911-bfbb1be05363', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'भूतकाल के छह भेदों में से ''सामान्य भूत'' और ''पूर्ण भूत'' में क्या मूलभूत अंतर है?', 'सामान्य भूत = अनिश्चित समाप्ति (आया); पूर्ण भूत = सुदूर अतीत में पूर्ण समाप्ति (आया था)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcd8eb3b-6c90-4275-81a6-87cdd82242f5', 'सामान्य भूत में केवल कार्य के बीते समय में होने का सामान्य बोध होता है, समय की स्पष्ट सीमा नहीं होती (जैसे: ''मोहन आया'') ; जबकि पूर्ण भूत में क्रिया बहुत पहले पूर्णतया समाप्त हो चुकी होती है और ''था/थी/थे'' जुड़ता है (जैसे: ''मोहन आया था'')', true, 'a2112dee-ee19-49f8-a911-bfbb1be05363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1cd9f16-412d-48d5-b3b8-c12ccd709317', 'सामान्य भूत में ''होगा'' आता है', false, 'a2112dee-ee19-49f8-a911-bfbb1be05363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09d30ea0-4cbd-4dc9-b682-ff7d87cdb9ed', 'पूर्ण भूत में ''रहा था'' आता है', false, 'a2112dee-ee19-49f8-a911-bfbb1be05363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40859d53-29f7-4e68-8d8a-aab4c9142b6c', 'दोनों में कोई अंतर नहीं है', false, 'a2112dee-ee19-49f8-a911-bfbb1be05363');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de5e76f4-f3fe-4f2d-8715-c31a3e56da47', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'वाक्य को काल की दृष्टि से शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8c44398-d223-41d3-9c1d-b60c221c8ed1', '''मैं कल आपके घर आया था पर आप नहीं मिले।'' (आदरार्थक सर्वनाम ''आप'' के साथ मानक भूतकाल रूप)', true, 'de5e76f4-f3fe-4f2d-8715-c31a3e56da47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6f4cab1-0168-4278-bbc7-2065abe167db', 'मैं कल आया तुम नहीं मिला।', false, 'de5e76f4-f3fe-4f2d-8715-c31a3e56da47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1514b8f3-e28a-4fa0-a72e-bdc517623090', 'मैं कल आऊँगा तुम नहीं मिलोगे।', false, 'de5e76f4-f3fe-4f2d-8715-c31a3e56da47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('507c5106-837f-4499-80ba-13e61c38ffa7', 'मैं आया था तुम मिला था।', false, 'de5e76f4-f3fe-4f2d-8715-c31a3e56da47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f017cb33-fd5f-4603-80d6-27001e012d47', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'काल और क्रिया के संबंधों के बारे में कौन-सा कथन व्याकरणिक दृष्टि से पूर्णतः सत्य है?', 'काल क्रिया का रूपांतरण है जो समय, पक्ष (Aspect) और वृत्ति (Mood) को समन्वित करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0988273d-53f8-431a-a495-cfb6ae7427a3', 'काल क्रिया का ही वह विकारी रूप है जो कार्य के संपादन समय के साथ-साथ उसकी पूर्णता, अपूर्णता, निरंतरता और संभावना का यथार्थ निर्धारण करता है', true, 'f017cb33-fd5f-4603-80d6-27001e012d47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12d15be4-d5ce-4a9f-977f-9a071807b889', 'काल का क्रिया से कोई संबंध नहीं होता', false, 'f017cb33-fd5f-4603-80d6-27001e012d47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c68ba13b-a4fd-445c-84ec-7dcf9c6f65f7', 'काल केवल संज्ञा शब्दों में होता है', false, 'f017cb33-fd5f-4603-80d6-27001e012d47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fdfb541-32fb-4ac7-90b2-ca10bf90f4cb', 'काल केवल भविष्य में बदलता है', false, 'f017cb33-fd5f-4603-80d6-27001e012d47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a51f625-bc01-494f-afdd-722849fa0491', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'A low-lying open area of land where garbage collected from a city is dumped, spread out, and covered with a layer of soil is called a:', 'A landfill is an engineered low-lying site where municipal solid waste is compacted and capped with earth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b168a82a-e13e-4ba7-83ca-f5198fb38655', 'Landfill', true, '7a51f625-bc01-494f-afdd-722849fa0491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab4ce7bc-1d1a-4520-8daf-8a70ca5f0209', 'Compost pit', false, '7a51f625-bc01-494f-afdd-722849fa0491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e29d4f55-88df-49e8-b669-639a8dae92a8', 'Incinerator', false, '7a51f625-bc01-494f-afdd-722849fa0491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('188f69d1-9757-4e7d-8843-2866b48856b0', 'Water treatment plant', false, '7a51f625-bc01-494f-afdd-722849fa0491');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ffa7b19-50c5-4c52-bd0a-f3ee1cd21c0d', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'Waste materials that can be broken down naturally and decomposed by microorganisms into harmless natural substances (such as vegetable peels, leftover food, dry leaves) are called:', 'Biodegradable organic waste undergoes natural biological decomposition by bacteria and fungi into humus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2950d6c6-0430-48fc-9184-269b42502a4e', 'Biodegradable Waste', true, '3ffa7b19-50c5-4c52-bd0a-f3ee1cd21c0d');
