INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4812fec-00c1-4dbb-aad7-dd173db4a631', 'Plastic Waste', false, '3ffa7b19-50c5-4c52-bd0a-f3ee1cd21c0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91e2f194-7735-4013-90b7-0cc98fdbfa29', 'Toxic Waste', false, '3ffa7b19-50c5-4c52-bd0a-f3ee1cd21c0d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b14ed24c-20dc-44d6-95d8-6f555139ab80', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'Waste materials that CANNOT be decomposed naturally by biological organisms and persist in the environment for centuries (such as plastic bags, glass, aluminium cans) are called:', 'Non-biodegradable synthetic polymers and metals resist microbial enzymatic degradation, accumulating as persistent pollution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60466efb-71ac-4955-a615-33d04fc1ba1d', 'Non-biodegradable Waste', true, 'b14ed24c-20dc-44d6-95d8-6f555139ab80');
