INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3feb926-b475-48c5-a715-49cf48f7458f', 'Organic Waste', false, 'b14ed24c-20dc-44d6-95d8-6f555139ab80');
