INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('450ba4f1-92b8-48bf-a382-6fa2ac42db60', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'The natural biological process of converting biodegradable kitchen and plant waste into nutrient-rich organic manure is called:', 'Composting aerobic/anaerobic decomposition converts discarded organic matter into nutrient-rich soil humus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('804b9a73-a22f-4c45-9623-5e68a53905d1', 'Composting', true, '450ba4f1-92b8-48bf-a382-6fa2ac42db60');
