INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d53a55e2-0354-47fa-add4-b9ab6a0ded2c', 'Recycling', false, '450ba4f1-92b8-48bf-a382-6fa2ac42db60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6599cbd5-a33d-47ca-8710-584d39c742db', 'Incineration', false, '450ba4f1-92b8-48bf-a382-6fa2ac42db60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5a04b0a-a240-49df-bf82-f748eb2f15fe', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'The method of preparing rich compost from organic waste using specialized ''Redworms'' (Eisenia fetida) is called:', 'Vermicomposting uses epigeic redworms (Eisenia fetida) to bio-convert organic waste into vermicast fertilizer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2194a201-5427-40bf-ad9d-69e46a542502', 'Vermicomposting', true, 'e5a04b0a-a240-49df-bf82-f748eb2f15fe');
