INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78d10518-98a6-4b16-b917-83eb997ea665', 'Incineration', false, 'e5a04b0a-a240-49df-bf82-f748eb2f15fe');
