INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('618ada02-d094-4576-8c7e-b77b01f633a5', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'What color dustbin is designated by municipalities for collecting BIODEGRADABLE wet kitchen waste, fruit peels, and animal waste?', 'Green bins collect biodegradable organic kitchen wet waste destined for community composting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('585616dc-fc10-4237-80fe-e8ace72dc4a3', 'Green Dustbin', true, '618ada02-d094-4576-8c7e-b77b01f633a5');
