INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5538904b-7423-430d-b5e7-671976b839c6', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'What color dustbin is designated by municipalities for collecting RECYCLABLE dry waste (plastics, metals, glass, paper)?', 'Blue bins collect non-biodegradable dry recyclable items like plastic bottles, glass, and metals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd38f991-80a1-4f70-bfed-fc4b930b3d39', 'Blue Dustbin', true, '5538904b-7423-430d-b5e7-671976b839c6');
