INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78529085-fc8b-4f47-9b0e-5026cbf0e56f', 'Yellow Dustbin', false, '5538904b-7423-430d-b5e7-671976b839c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e99a53a0-800b-4add-ba7d-627e60f6d1f8', 'Brown Dustbin', false, '5538904b-7423-430d-b5e7-671976b839c6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b61867c0-a093-4704-9bce-49918450d8ae', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'What specialized internal muscular organ do Redworms possess to grind their food in the absence of true teeth?', 'Redworms lack teeth; food is ground in a muscular gizzard aided by ingested mineral grit particles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38f139d9-b970-4889-adf5-493084846fcc', 'Gizzard (which uses swallowed sand/grit particles to grind food)', true, 'b61867c0-a093-4704-9bce-49918450d8ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e56ea6b-d8f7-4bd8-ac50-8a04d2210c37', 'Stomach', false, 'b61867c0-a093-4704-9bce-49918450d8ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d77825ab-25f0-489e-8e57-3064bb5a56d2', 'Beak', false, 'b61867c0-a093-4704-9bce-49918450d8ae');
