INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3c4aa23-00c7-465b-9aee-9f1764c2749a', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'What are the famous ''3 Rs'' of modern solid waste management and environmental conservation?', 'The 3Rs hierarchy prioritizes: 1. Reduce consumption, 2. Reuse items, and 3. Recycle discarded materials.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7ace6f8-7c57-4c73-8552-11c7cb92c5c0', 'Reduce, Reuse, Recycle', true, 'f3c4aa23-00c7-465b-9aee-9f1764c2749a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('604d2a86-cd55-4f23-8aac-5a9c09d89d56', 'Read, Record, Remember', false, 'f3c4aa23-00c7-465b-9aee-9f1764c2749a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4ea2122-3492-4de6-b5ef-d4f8ad02507c', 'Run, Rest, Repeat', false, 'f3c4aa23-00c7-465b-9aee-9f1764c2749a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7003ab35-f046-4e20-8d77-12d2b0b72b1b', 'Remove, Repair, Replace', false, 'f3c4aa23-00c7-465b-9aee-9f1764c2749a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac2af74a-ebe4-4b87-8217-15b1853e7998', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'Which of the following household waste items CAN be easily recycled into fresh new paper in a classroom?', 'Waste cellulose paper pulp can be soaked, meshed, strained on wire frames, and dried into recycled paper.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c3953dd-07da-474f-852c-3fbf6bea7487', 'Old newspapers, magazines, and used notebook paper', true, 'ac2af74a-ebe4-4b87-8217-15b1853e7998');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5ee5160-c63c-4ca9-8e79-18dffda481a2', 'Plastic carry bags', false, 'ac2af74a-ebe4-4b87-8217-15b1853e7998');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c510a614-0c13-4a5d-ac9b-75eeee97ea03', 'Glass bottles', false, 'ac2af74a-ebe4-4b87-8217-15b1853e7998');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e30852be-b527-4d20-88e9-776ee2975769', 'Broken ceramic cups', false, 'ac2af74a-ebe4-4b87-8217-15b1853e7998');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45229b2a-f147-4452-a04c-0924a8d1cc1c', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'Why should we NEVER burn dry fallen leaves, plastic waste, or synthetic garbage in open streets?', 'Incomplete combustion of plastics and biomass releases toxic dioxins, furans, PM2.5, and carbon monoxide.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3534991-becf-4a99-8e46-48bbe35fad9d', 'Open burning releases highly toxic smoke, cancer-causing dioxins, and particulate matter that cause severe respiratory illnesses and air pollution', true, '45229b2a-f147-4452-a04c-0924a8d1cc1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97aa5c73-73b1-432c-bb55-4e6ec4c2f1c5', 'Because ash turns into gold', false, '45229b2a-f147-4452-a04c-0924a8d1cc1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31ce96be-fdcf-45f3-b4d6-e9358e0dae0a', 'Because fire makes the ground too cold', false, '45229b2a-f147-4452-a04c-0924a8d1cc1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1a7a33e-5f3a-47c7-a774-fafd215240ec', 'Because fire destroys the sun', false, '45229b2a-f147-4452-a04c-0924a8d1cc1c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7d10eb3-39c2-4602-b3a6-c75a4c15fa1b', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'What eco-friendly shopping bag should we use instead of single-use polythene plastic bags?', 'Jute and woven cotton bags are reusable, durable, renewable, and 100% biodegradable.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0b22fbe-2da3-4319-9c87-d5ada9e4f4b3', 'Bags made of Cloth, Jute, or recycled Paper', true, 'e7d10eb3-39c2-4602-b3a6-c75a4c15fa1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4171bfde-e9ab-49f0-b488-6fe041bd1e5f', 'Thicker plastic bags', false, 'e7d10eb3-39c2-4602-b3a6-c75a4c15fa1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30ece178-ccd5-4f46-810f-3a735bc26aae', 'Aluminium foil bags', false, 'e7d10eb3-39c2-4602-b3a6-c75a4c15fa1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58212fdd-c00c-476f-91b7-31d2335ab5c8', 'Thermocol boxes', false, 'e7d10eb3-39c2-4602-b3a6-c75a4c15fa1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6de55a7c-f639-4568-973c-2bd1e706b27d', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Why is putting cooked food with salt, oil, vinegar, or meat/dairy products into a Vermicomposting pit strictly avoided?', 'Saline, acidic, and fatty animal wastes rot pathogenically and destroy the neutral pH micro-habitat of redworms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be94def9-1de5-474f-bd78-be7735108af9', 'Oils, spices, and animal meats attract harmful disease-causing bacteria, foul smell, and pests (rats, ants) that can kill the redworms', true, '6de55a7c-f639-4568-973c-2bd1e706b27d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a5154e6-241b-4b88-9b9f-960d5eabb66b', 'Because worms become too fat', false, '6de55a7c-f639-4568-973c-2bd1e706b27d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0703ef9-5c6d-4773-9f1d-efcaad883180', 'Because salt makes compost too sweet', false, '6de55a7c-f639-4568-973c-2bd1e706b27d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51a90d93-8263-4286-89c1-48bc355733dc', 'Because redworms only eat ice', false, '6de55a7c-f639-4568-973c-2bd1e706b27d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67822dbe-efc2-4f9d-a7db-12801029e115', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What ideal physical environmental conditions are required inside a vermicompost pit for redworms to thrive?', 'Redworms require 60–80% moisture, loose organic bedding, and 15–25°C ambient temperature for optimal digestion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51a680be-ec28-4071-a5df-778647ea617d', 'Moist, shaded, and well-aerated bedding (loose soil, wire mesh/sand base) with moderate temperature (neither too hot nor freezing cold)', true, '67822dbe-efc2-4f9d-a7db-12801029e115');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05d9a276-046f-41ba-86e2-d204bf29b9eb', 'Direct scorching sunlight with boiling water', false, '67822dbe-efc2-4f9d-a7db-12801029e115');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c168bff-e5eb-44bd-a80a-3c42de958763', 'Bone-dry gravel in total darkness', false, '67822dbe-efc2-4f9d-a7db-12801029e115');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36ef8bad-a247-4402-a875-537d89159e06', 'Submerged in deep standing water', false, '67822dbe-efc2-4f9d-a7db-12801029e115');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59553ac3-3701-41f7-afbe-5dda74132d12', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Why do stray cows and street animals often choke and die after scavenging from open garbage dumps?', 'Plastic bags containing food scraps are swallowed whole by ruminants, causing fatal gastrointestinal impaction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd892bc9-a5c6-4774-8074-98f356df6b97', 'They swallow discarded polythene plastic bags filled with leftover food; the indigestible plastic accumulates in their rumen stomach, blocking digestion lethally', true, '59553ac3-3701-41f7-afbe-5dda74132d12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6df62899-47c5-407e-8b55-231af4287a4b', 'Because garbage is too heavy', false, '59553ac3-3701-41f7-afbe-5dda74132d12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbe91d9-d815-49ac-aae8-f0e08e568c88', 'Because they drink rain water', false, '59553ac3-3701-41f7-afbe-5dda74132d12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('696207a8-f6e3-412f-b434-830eb93033d4', 'Because cows cannot chew food', false, '59553ac3-3701-41f7-afbe-5dda74132d12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6966bd8-86df-4dee-befe-d7a4c8893f9a', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'How does a city municipal corporation transform an old, completely filled landfill site after 20 years?', 'Decommissioned landfills (e.g. Indraprastha Millennium Park in Delhi) are converted into parks due to soil settlement and methane venting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c109898e-2209-4035-aaf7-badcb41443f3', 'It is sealed with thick clay capping and topsoil and converted into a green public recreational park or playground (no heavy buildings are built for decades)', true, 'e6966bd8-86df-4dee-befe-d7a4c8893f9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f243f4ed-2d48-451f-85c6-ec8cb4b2cfb6', 'It is turned into a deep lake', false, 'e6966bd8-86df-4dee-befe-d7a4c8893f9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abe3b840-614b-4f2a-bd9a-ebd6a3ee5d5e', 'High-rise glass skyscrapers are built immediately', false, 'e6966bd8-86df-4dee-befe-d7a4c8893f9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8008354-f1bd-4293-9114-4990bbafac76', 'It is dug up and thrown into the sea', false, 'e6966bd8-86df-4dee-befe-d7a4c8893f9a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04b59b8f-7123-4b54-a5c0-e9a4c7ddd17d', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Why are single-use plastic bags and thermocol disposable cups a major cause of urban flash floods during monsoons?', 'Non-biodegradable plastic debris physically chokes stormwater culverts and sewer conduits, triggering severe street waterlogging.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7216520-00db-4314-bb6d-0b21ad5562e6', 'Carelessly discarded plastic litter is washed into roadside drains and sewage pipes, clogging municipal drainage and causing dirty water overflow', true, '04b59b8f-7123-4b54-a5c0-e9a4c7ddd17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c81d187-5003-4277-af0b-9a0a526ff11d', 'Because plastic produces rain clouds', false, '04b59b8f-7123-4b54-a5c0-e9a4c7ddd17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55642ba7-a66f-408a-9c4c-9f226402ae68', 'Because plastic absorbs all water', false, '04b59b8f-7123-4b54-a5c0-e9a4c7ddd17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f7ea990-3d4c-443c-9662-09d2e0137098', 'Because plastic makes drains too clean', false, '04b59b8f-7123-4b54-a5c0-e9a4c7ddd17d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('289a547f-6881-4c4e-a6d4-29d70f1d29a9', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What is the primary ecological benefit of practicing ''Waste Segregation at Source'' (in every household)?', 'Source separation segregates organic feedstock for bioconversion while keeping recyclables uncontaminated.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef511e70-1cf1-42a6-bfb9-a08e77538499', 'It prevents recyclable dry materials from getting contaminated by rotting wet waste, maximizing recycling efficiency and enabling clean composting', true, '289a547f-6881-4c4e-a6d4-29d70f1d29a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40ed8736-e4a6-46c2-946d-f3b799956c7d', 'It makes garbage look beautiful', false, '289a547f-6881-4c4e-a6d4-29d70f1d29a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7df90351-711c-481c-9012-fed6f1f7e4b1', 'It reduces the weight of food', false, '289a547f-6881-4c4e-a6d4-29d70f1d29a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db63d7d1-d728-4150-8ee3-e762e3fdeaf6', 'It stops garbage from producing heat', false, '289a547f-6881-4c4e-a6d4-29d70f1d29a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('631aeaea-e94d-4e30-8e4c-0bc7c6bfc6ae', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Why is Vermicompost (vermicast) considered superior to synthetic chemical fertilizers for agricultural soil?', 'Vermicompost provides bioavailable N-P-K, humic acids, and beneficial soil mycorrhizae without chemical soil salinization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('913b1b98-1d38-45d2-a2ce-98beb9a06cfa', 'It enhances soil microbial biodiversity, improves water retention, enriches soil structure naturally without chemical leaching or soil toxicity', true, '631aeaea-e94d-4e30-8e4c-0bc7c6bfc6ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47469f93-6fca-4dd3-aa62-6b0c1af0adb4', 'It kills all earthworms in the farm', false, '631aeaea-e94d-4e30-8e4c-0bc7c6bfc6ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c25f6236-08b7-46a8-99e0-8427c8a81049', 'It makes soil completely dry', false, '631aeaea-e94d-4e30-8e4c-0bc7c6bfc6ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a339ea79-87de-4d39-925c-78e19aed20cc', 'It changes plant color to purple', false, '631aeaea-e94d-4e30-8e4c-0bc7c6bfc6ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fff8d902-99c0-43f5-a15e-9071235ded76', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'How can students easily make recycled decorative paper sheets at home or school?', 'Handmade papermaking meshes soaked recycled cellulose pulp onto deckle frames, creating textured artisan sheets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6465b5ed-e198-4a29-994e-f25f239f291b', 'Tear waste paper into shreds, soak in water to make thick pulp, spread evenly over a wire mesh frame, press out excess water, decorate with dried flower petals, and sun dry', true, 'fff8d902-99c0-43f5-a15e-9071235ded76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f76c3ffb-08c6-43b8-a801-285823ff7c28', 'Melt plastic bottles in an oven', false, 'fff8d902-99c0-43f5-a15e-9071235ded76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b82bd6ea-53f3-46fb-8f96-029748d59517', 'Burn paper and mix ash with water', false, 'fff8d902-99c0-43f5-a15e-9071235ded76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7563d37e-4281-40b8-a943-c6ee84835d31', 'Paint old wood with oil', false, 'fff8d902-99c0-43f5-a15e-9071235ded76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83c412a4-3f35-49d0-a110-79af8cd94e88', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Why should we avoid packing warm, edible cooked food items in recycled colored polythene plastic bags?', 'Non-food-grade recycled plastic carries phthalates, lead, and cadmium residues that migrate into fatty, warm foodstuffs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17ffe7a4-b59a-450e-8fb8-4130ad5b8ce1', 'Recycled plastics contain toxic heavy metal dyes and chemical plasticizers that leach into hot food, causing toxic food poisoning', true, '83c412a4-3f35-49d0-a110-79af8cd94e88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ebda829-0a7d-4ee4-8822-79f45b399ef7', 'Because recycled bags smell like strawberries', false, '83c412a4-3f35-49d0-a110-79af8cd94e88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e13a6a4b-6b48-4117-81b7-3956acbbedd3', 'Because colored bags keep food too hot', false, '83c412a4-3f35-49d0-a110-79af8cd94e88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f90f1be-0996-43ff-990b-cf00b7f705a4', 'Because food turns into plastic', false, '83c412a4-3f35-49d0-a110-79af8cd94e88');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8cdeb1f2-a69b-4028-a6e8-e5f93d9fbb1e', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What is ''Kabaadiwala'' (Scrap Dealer / Informal Recycler) in the Indian municipal waste ecosystem?', 'Informal kabadiwalas recover millions of tons of dry recyclables, achieving high diversion rates from landfills.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0061ba40-b462-4372-811e-97b3e4223310', 'Crucial grassroots recycling entrepreneurs who purchase discarded paper, cardboard, scrap metal, glass, and plastics to supply to industrial recycling factories', true, '8cdeb1f2-a69b-4028-a6e8-e5f93d9fbb1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6c3d06c-63e0-4dc0-b430-09182aefedc8', 'People who burn garbage in forests', false, '8cdeb1f2-a69b-4028-a6e8-e5f93d9fbb1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26bbc5f8-62f8-44ba-90e7-154e2ae237dc', 'Drivers of city buses', false, '8cdeb1f2-a69b-4028-a6e8-e5f93d9fbb1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18c03455-8362-4829-b4fd-9505b62b4cdd', 'Street food sellers', false, '8cdeb1f2-a69b-4028-a6e8-e5f93d9fbb1e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04c32ec6-96e7-487b-911d-deb17af5d890', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'How does nature naturally recycle dead plant and animal remains in a pristine forest?', 'Natural biogeochemical nutrient cycles operate in closed loops where biotic detritus becomes nutrient feedstock for autotrophs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43c75089-4ea8-46fd-9615-037512abc3f0', 'Decomposers (bacteria, fungi, earthworms, beetles) break down fallen leaves and carcasses into nutrient-rich humus soil, which feeds new growing trees (Zero Waste in Nature)', true, '04c32ec6-96e7-487b-911d-deb17af5d890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2fc506c-7fef-4959-bb6d-2996d75c7a56', 'Forests have trash trucks', false, '04c32ec6-96e7-487b-911d-deb17af5d890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cadd7eb9-a7bb-4a5f-ba39-c49416d83b2e', 'Rivers wash everything into outer space', false, '04c32ec6-96e7-487b-911d-deb17af5d890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd36bba3-84f5-4589-9cdc-32488201808e', 'Sunlight burns all leaves instantly', false, '04c32ec6-96e7-487b-911d-deb17af5d890');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('523bcb80-3587-40b6-b9cd-254ffbc52ade', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What happens when non-biodegradable plastics are dumped in soil?', 'Buried plastic membranes impede groundwater recharge, soil aeration, and root penetration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('428c8929-dd2e-41a2-b776-c55d2060ed6f', 'They form an impermeable underground barrier that blocks rainwater percolation into deep aquifers, degrading soil health and vegetation growth', true, '523bcb80-3587-40b6-b9cd-254ffbc52ade');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46536e1f-622c-4ae2-92b1-1ec312a8db54', 'They dissolve into fertilizer within 2 days', false, '523bcb80-3587-40b6-b9cd-254ffbc52ade');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('056aa8e1-aae3-4bb9-a8ab-8395985ab984', 'They turn into groundwater', false, '523bcb80-3587-40b6-b9cd-254ffbc52ade');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b43c545-1f96-4f6e-81e7-ae98514867a3', 'They make soil softer', false, '523bcb80-3587-40b6-b9cd-254ffbc52ade');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e4e697b-3761-4c6d-a365-fe07abe4c088', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What is a major advantage of using traditional Clay Cups (''Kulhads'') and Dried Leaf Plates (''Pattals'') during public festivals?', 'Terracotta kulhads and Sal leaf pattals provide compostable, sustainable indigenous alternatives to single-use plastics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49d8a076-ba7a-4a5f-bedd-265480201608', 'They are 100% natural and biodegradable; when discarded, they dissolve back harmlessly into fertile soil without toxic plastic pollution', true, '5e4e697b-3761-4c6d-a365-fe07abe4c088');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('591a7adf-f9ac-4d87-812c-be464d3d07d5', 'They can be used for 50 years', false, '5e4e697b-3761-4c6d-a365-fe07abe4c088');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b5f0b60-fd39-4bd0-97d5-4e3d2a1e4106', 'They are made of metal', false, '5e4e697b-3761-4c6d-a365-fe07abe4c088');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcd52fe1-92b4-4de6-9550-a23fd4749530', 'They never break', false, '5e4e697b-3761-4c6d-a365-fe07abe4c088');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a891986f-f3a4-48bb-986f-001b1238a558', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Which of the following is a direct, responsible action an individual student can take to ''REDUCE'' waste generation?', 'Source reduction eliminates disposable waste generation at the consumer level.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b8bf8ad-8b37-48e2-86d7-98325d079a4f', 'Using a durable refillable steel water bottle and reusable lunchbox instead of single-use plastic bottles and plastic foil wraps', true, 'a891986f-f3a4-48bb-986f-001b1238a558');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5556866-497d-4070-8a05-e92f30882816', 'Throwing away half-eaten food in the street', false, 'a891986f-f3a4-48bb-986f-001b1238a558');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0debc741-aad8-4c1b-ac6f-24034df528f7', 'Using 10 new plastic bags every day', false, 'a891986f-f3a4-48bb-986f-001b1238a558');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8931f3f0-77aa-427e-9048-8e21a1ae2913', 'Buying disposable pens and throwing them away after one use', false, 'a891986f-f3a4-48bb-986f-001b1238a558');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ba0dff6-99ed-4d05-b827-55d862201371', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What is ''Leachate'' generated in unscientific open garbage landfills?', 'Landfill leachate is a hazardous liquid contaminated with dissolved heavy metals, ammonia, and organic toxins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2acd8502-b391-4ced-969c-021cade59b85', 'A highly toxic, black liquid formed when rainwater percolates through rotting waste, which can seep underground and poison drinking groundwater wells', true, '9ba0dff6-99ed-4d05-b827-55d862201371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8bf8b87-a76e-497d-9943-00e90086c42d', 'Clean drinking water', false, '9ba0dff6-99ed-4d05-b827-55d862201371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b80ee18-a0d4-409e-9def-23f0df04cc0d', 'Mineral spring water', false, '9ba0dff6-99ed-4d05-b827-55d862201371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4c7de88-ddcd-4832-8a70-1abb3fd26fb5', 'Compost powder', false, '9ba0dff6-99ed-4d05-b827-55d862201371');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e064944b-22f5-4b07-9e1c-6a79bd6be952', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What civic national mission was launched on 2nd October 2014 across India to eliminate open defecation, promote scientific solid waste management, and create cleaner cities?', 'Swachh Bharat Abhiyan transformed national sanitation, municipal waste processing, and behavioral cleanliness across India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5175d6a-1b0d-4456-b657-592643389e79', 'Swachh Bharat Abhiyan (Clean India Mission)', true, 'e064944b-22f5-4b07-9e1c-6a79bd6be952');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a44a93d9-acfc-464b-bf99-de2170143bd9', 'Digital India', false, 'e064944b-22f5-4b07-9e1c-6a79bd6be952');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9c981b1-a9d4-45c6-9017-13675bdc26c9', 'Make in India', false, 'e064944b-22f5-4b07-9e1c-6a79bd6be952');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53271de0-7452-42f3-8ea8-34396d05a9b4', 'Smart Cities Mission', false, 'e064944b-22f5-4b07-9e1c-6a79bd6be952');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0324c8c-eebf-4469-9e05-53dc34641875', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64461922-fab5-4347-af40-f04f4681c7de', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'a0324c8c-eebf-4469-9e05-53dc34641875');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72d39316-91ca-4fdc-942c-adbdfe9d1fa6', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'a0324c8c-eebf-4469-9e05-53dc34641875');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1987818-421c-4437-855e-1174ff87f6ea', '(A) is true, but (R) is false.', false, 'a0324c8c-eebf-4469-9e05-53dc34641875');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d75f352-c3f2-489c-81ff-ace16fe335bb', '(A) is false, but (R) is true.', false, 'a0324c8c-eebf-4469-9e05-53dc34641875');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('449cbac3-7a3e-4697-a804-f862122d533b', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Spot the IMPOSTER in the following group of waste items categorized as 100% Biodegradable:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b206b200-c33c-4f93-8ee4-cedea8e37a77', 'Banana peel', false, '449cbac3-7a3e-4697-a804-f862122d533b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6ed25b5-2f73-433f-b471-5e3728e03607', 'Cotton cloth scrap', false, '449cbac3-7a3e-4697-a804-f862122d533b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dddb00b8-8cdc-45f0-8059-e693e5fa96b8', 'Dried fallen leaves', false, '449cbac3-7a3e-4697-a804-f862122d533b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50b954e3-6b25-40a0-907e-5f05959a960d', 'Thermocol cup', true, '449cbac3-7a3e-4697-a804-f862122d533b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67ee0209-a7d1-4c55-83b8-04703574edf8', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'A student sets up two test pits in the garden:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae2fabe4-cdc3-4459-a82a-fc7fac0c89a4', 'Contents of Pit A have rotted completely into dark, rich, earthy smelling compost humus; contents of Pit B remain completely unchanged without any decomposition', true, '67ee0209-a7d1-4c55-83b8-04703574edf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28af7d9d-216b-4d21-a941-b2865ee30304', 'Contents of Pit B disappeared while Pit A turned into glass', false, '67ee0209-a7d1-4c55-83b8-04703574edf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1466f849-ee9c-4bd8-bfa2-049aa5d7b4c6', 'Both pits turned into plastic', false, '67ee0209-a7d1-4c55-83b8-04703574edf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a117aa48-456b-41f3-b4be-e174ec96445a', 'Neither pit showed any change', false, '67ee0209-a7d1-4c55-83b8-04703574edf8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d915cc2d-690e-4cf5-8d5f-c62d5cbd4bd3', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Match Column I (Waste Materials) with Column II (Appropriate Management Disposal Method):
(a) Vegetable peels & leaves -> (i) Vermicomposting / Compost pit
(b) Scrap aluminium & glass  -> (ii) Blue bin for industrial recycling
(c) Used plastic bottle      -> (iii) Reuse as a flower pot / stationery holder
(d) Solid hospital syringes  -> (iv) High-temperature biomedical incineration', 'Organic peels = composting; Scrap metals = recycling; Bottles = reuse; Biomedical waste = incineration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed83d6dc-d46f-467d-8ac3-2dfed8ec8393', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'd915cc2d-690e-4cf5-8d5f-c62d5cbd4bd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0baf09b-fc39-4b69-9289-f60946d8ad59', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'd915cc2d-690e-4cf5-8d5f-c62d5cbd4bd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('172515b4-aec7-4819-8cac-73ab72cb9da8', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'd915cc2d-690e-4cf5-8d5f-c62d5cbd4bd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('355dbf24-893e-490d-94c5-e754675fa9e0', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'd915cc2d-690e-4cf5-8d5f-c62d5cbd4bd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b25e892-f5c4-471e-ace4-51addf14b2d3', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Read the statements regarding Vermicomposting:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f08f00d-8277-4ddd-bed2-e56c8e98e40c', 'Statements 1 and 2 only', true, '3b25e892-f5c4-471e-ace4-51addf14b2d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05ee5d1b-95f8-4a5e-bdcc-b48f13d546d3', 'Statements 2 and 3 only', false, '3b25e892-f5c4-471e-ace4-51addf14b2d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a1a68cf-950f-4c1d-9b49-c170fc98ae38', 'Statements 1 and 3 only', false, '3b25e892-f5c4-471e-ace4-51addf14b2d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f87e9c64-a3f4-4312-8f05-11771599d93d', 'All Statements 1, 2, and 3', false, '3b25e892-f5c4-471e-ace4-51addf14b2d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3fe43352-334e-45e4-9183-3981619b3eca', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Why is the concept of ''Circular Economy'' (Cradle to Cradle) considered the ultimate sustainable solution to global garbage crisis?', 'Circular economy replaces linear take-make-dispose models with regenerative closed loops maximizing resource utility.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce81ddb4-4c16-4e78-b5ca-e11cb6cc0427', 'It designs products so that all materials are endlessly reused, repaired, refurbished, and recycled in closed loops, eliminating the concept of ''waste'' entirely', true, '3fe43352-334e-45e4-9183-3981619b3eca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2637d957-ef6a-4bc3-af58-5122f2f120a8', 'It dumps all waste into the deep ocean', false, '3fe43352-334e-45e4-9183-3981619b3eca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af776ed2-c82f-45f3-bf0f-d797e5b38348', 'It burns all garbage in giant rocket engines', false, '3fe43352-334e-45e4-9183-3981619b3eca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60fd3d7e-64df-468d-9e37-9b595d05632c', 'It forces people to stop eating food', false, '3fe43352-334e-45e4-9183-3981619b3eca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88c396ac-9a32-4eb7-ac54-d975b8c60f0d', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'What is ''Bioremediation'' in modern environmental biotechnology?', 'Bioremediation utilizes microbial metabolic pathways to degrade hazardous xenobiotics into non-toxic end products.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4eeb024-f4a3-4cb8-b02c-6ce1142193d0', 'Using living microorganisms (engineered bacteria, fungi) and plants to detoxify, break down, and clean up polluted soils, oil spills, and heavy metal contaminants', true, '88c396ac-9a32-4eb7-ac54-d975b8c60f0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6429797f-d6a4-4578-92ac-4eeb2c571bf9', 'Covering garbage with plastic sheets', false, '88c396ac-9a32-4eb7-ac54-d975b8c60f0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a33ad5b2-feeb-436c-9b80-9a3a2c94e152', 'Spraying perfume over landfill sites', false, '88c396ac-9a32-4eb7-ac54-d975b8c60f0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('373a7830-8f36-4c2e-8264-e34fc57e4067', 'Burning garbage with nuclear lasers', false, '88c396ac-9a32-4eb7-ac54-d975b8c60f0d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('177c74bb-d3d3-4c68-b0d8-34742868cbe2', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'What is the phenomenon of ''Microplastics'' in global marine ecosystems?', 'UV photo-oxidation and mechanical abrasion fragment macro-plastics into persistent trophic microplastics (<5 mm).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6175d9bb-8d0c-47aa-b932-983d60cc030f', 'Microscopic plastic particles (<5 mm) formed by the weathering breakdown of discarded plastic litter, which are ingested by plankton and fish, entering the human food chain', true, '177c74bb-d3d3-4c68-b0d8-34742868cbe2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e6d2297-fd21-48d1-aa1b-2670213938c0', 'Tiny plastic toys for dolls', false, '177c74bb-d3d3-4c68-b0d8-34742868cbe2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eab12cf6-1808-4374-9805-dcfc541abdfb', 'Microscopes made of plastic', false, '177c74bb-d3d3-4c68-b0d8-34742868cbe2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64ec0708-a74f-4f6c-97bd-87690c9f707f', 'Plastics that dissolve in 1 second', false, '177c74bb-d3d3-4c68-b0d8-34742868cbe2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9918dc57-2e1b-473d-9f3d-7e26e73f72d2', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Why is ''Anaerobic Digestion'' of segregated organic waste in biogas plants doubly beneficial for rural and urban sustainability?', 'Methanogenic anaerobic digestion yields carbon-neutral biomethane fuel (CH₄) alongside nutrient-rich organic digestate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68114f39-cfe8-4123-b8cf-531c3da9d09e', 'It produces clean renewable Methane Biogas for cooking and electricity while generating high-potency organic bio-slurry fertilizer', true, '9918dc57-2e1b-473d-9f3d-7e26e73f72d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76839abe-b259-496d-b79c-4d25ee55aa39', 'It produces gold and silver', false, '9918dc57-2e1b-473d-9f3d-7e26e73f72d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09c8119d-1c98-42c0-95d1-416b5b21e5c2', 'It makes synthetic plastics', false, '9918dc57-2e1b-473d-9f3d-7e26e73f72d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ca9e78b-07e4-4461-9884-e1e1dd9edc49', 'It turns water into oil', false, '9918dc57-2e1b-473d-9f3d-7e26e73f72d2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2bf78a0-5dc1-45db-a321-ea13bac02b5e', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Consider four categories of household waste generated during a birthday party:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b247d2b5-b6b6-4bcc-8ef1-1e226f78027d', 'Items 1 and 4 only (Peels and Bread crusts)', true, 'f2bf78a0-5dc1-45db-a321-ea13bac02b5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afb565e3-1ccb-4506-a767-51b693bfabd5', 'Items 2 and 3 only', false, 'f2bf78a0-5dc1-45db-a321-ea13bac02b5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fe600d4-e5c0-4dd8-b547-8f3ec206408c', 'Items 1, 2, and 3', false, 'f2bf78a0-5dc1-45db-a321-ea13bac02b5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5616ca55-fe02-41c8-a42f-0916eff54239', 'All 4 items', false, 'f2bf78a0-5dc1-45db-a321-ea13bac02b5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69b995ab-3d85-41cd-8583-16c130060ee2', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'What is ''E-Waste'' (Electronic Waste) and why does it require specialized certified recycling rather than normal municipal dumping?', 'E-waste contains hazardous heavy metals and persistent flame retardants requiring specialized dismantling and pyrometallurgical recovery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7533dbc5-70fa-4353-8b65-44e95d6a035b', 'Discarded computers, smartphones, and circuit boards that contain toxic heavy metals (lead, mercury, cadmium) that can leach into soil and water if dumped casually', true, '69b995ab-3d85-41cd-8583-16c130060ee2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b9dbdc0-65c3-4781-aeca-86007b3f45e8', 'Old paper electricity bills', false, '69b995ab-3d85-41cd-8583-16c130060ee2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61687996-7147-41b6-8578-7a489873fc67', 'Electric wires made of pure cotton', false, '69b995ab-3d85-41cd-8583-16c130060ee2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43e297e0-cf52-46c2-90a7-f1a92405ef60', 'Lightning in the sky', false, '69b995ab-3d85-41cd-8583-16c130060ee2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42cd49e4-4cf3-4902-81be-cfffc0a84bb1', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'What fundamental environmental philosophy concludes the NCERT Class 6 Science curriculum in Chapter 12?', 'The curriculum culminates in proactive ecological citizenship, waste minimization, and harmonious circular resource stewardship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06af8f98-bcf6-48fe-8481-b4a60130c0f4', 'Every human action produces ecological consequences; sustainable living requires individual responsibility to minimize waste, segregate at source, and harmonize human lifestyle with nature''s circular ecology', true, '42cd49e4-4cf3-4902-81be-cfffc0a84bb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ad2695a-ce28-452c-b5a4-dbb5dcae3ecc', 'Throwing garbage in rivers is good for fish', false, '42cd49e4-4cf3-4902-81be-cfffc0a84bb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ff1da6d-9118-4e43-9268-bd77347459e0', 'Only governments are responsible for cleanliness', false, '42cd49e4-4cf3-4902-81be-cfffc0a84bb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8c2f15b-ab68-4bc8-a684-bc2bc82ee995', 'Using disposable plastics is the only way to live', false, '42cd49e4-4cf3-4902-81be-cfffc0a84bb1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c10c1659-06d5-46a4-99f4-57a2a6648019', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Comparing two quantities of the SAME kind and in the SAME units by division is called a:', 'A ratio is a mathematical comparison of two quantities of identical physical dimension by division (a : b = a/b).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a19bb0a9-0683-4b9e-a8b8-f0b9d19ab1ab', 'Ratio (denoted by the colon symbol '':'')', true, 'c10c1659-06d5-46a4-99f4-57a2a6648019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('778930ec-5807-4022-87f6-1727ab504844', 'Fraction', false, 'c10c1659-06d5-46a4-99f4-57a2a6648019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8177cc1-dc7d-48ca-84ca-f46165319549', 'Percentage', false, 'c10c1659-06d5-46a4-99f4-57a2a6648019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7ced5b6-5692-498b-aa1a-36c82cdfc89d', 'Equation', false, 'c10c1659-06d5-46a4-99f4-57a2a6648019');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ba3897c-d832-4b93-8f3e-4422e0c90607', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'What is the Ratio of 20 boys to 40 girls in a classroom in its simplest form?', 'Ratio = 20/40 = 1/2 = 1 : 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c064bd74-ed88-4eea-b5b5-6a82abce81d2', '1 : 2 (20/40 = 1/2)', true, '2ba3897c-d832-4b93-8f3e-4422e0c90607');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0c83f04-5501-4fbc-baf4-c7f134db758e', '2 : 1', false, '2ba3897c-d832-4b93-8f3e-4422e0c90607');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('431b9382-2d9c-461a-b430-cb0acaa7ff2d', '1 : 4', false, '2ba3897c-d832-4b93-8f3e-4422e0c90607');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ec925d5-3f6b-4d13-90a2-404c6018135b', '20 : 40', false, '2ba3897c-d832-4b93-8f3e-4422e0c90607');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('909cd7d7-c743-44c0-8024-0d02be50ba9e', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Find the ratio of 15 cm to 2 metres (remember to convert both into the SAME unit first):', '2 m = 200 cm. Ratio = 15 / 200 = (15÷5) / (200÷5) = 3/40 = 3 : 40.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b8ee926-3c60-4ef4-aa0e-1317a107c5a9', '3 : 40 (2 m = 200 cm ; Ratio = 15/200 = 3/40)', true, '909cd7d7-c743-44c0-8024-0d02be50ba9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17ac44d8-e088-46bd-99e5-fbc84d7940a6', '15 : 2', false, '909cd7d7-c743-44c0-8024-0d02be50ba9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('329072b5-c45d-4124-b88f-e06583e4980d', '3 : 20', false, '909cd7d7-c743-44c0-8024-0d02be50ba9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da83aae6-133c-4517-9a67-e59607a047cf', '15 : 200', false, '909cd7d7-c743-44c0-8024-0d02be50ba9e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02e1df07-9bc3-421e-918d-481530ac72cf', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Find the ratio of 50 paise to ₹5 in simplest form:', '₹5 = 500 paise. Ratio = 50 / 500 = 1/10 = 1 : 10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f112101a-aee1-4973-9adb-ccf8028713f7', '1 : 10 (₹5 = 500 paise ; Ratio = 50/500 = 1/10)', true, '02e1df07-9bc3-421e-918d-481530ac72cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2a8c547-fb1a-40c7-b40f-3e51e2f5bfe0', '1 : 5', false, '02e1df07-9bc3-421e-918d-481530ac72cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6660ac12-62f7-489c-9317-b7682021a1c6', '10 : 1', false, '02e1df07-9bc3-421e-918d-481530ac72cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b72b48a4-837f-4e61-aad1-6c2ec89f4205', '50 : 5', false, '02e1df07-9bc3-421e-918d-481530ac72cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('972dcb8d-7fb0-48f4-91e6-0cfacaf1d3b9', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'An equality of two ratios (e.g. a : b = c : d or a : b :: c : d) is called a:', 'A proportion states that two ratios are equal: a/b = c/d.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0347fe5-fb3a-466f-be85-349b09a95789', 'Proportion', true, '972dcb8d-7fb0-48f4-91e6-0cfacaf1d3b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13014bc9-417e-4236-98c2-19d8b749c714', 'Fraction', false, '972dcb8d-7fb0-48f4-91e6-0cfacaf1d3b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed889226-8c44-4b0f-a726-daf9dc69302a', 'Percentage', false, '972dcb8d-7fb0-48f4-91e6-0cfacaf1d3b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d22e1ae5-1903-4445-a48c-c110e1904acf', 'Linear Equation', false, '972dcb8d-7fb0-48f4-91e6-0cfacaf1d3b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb66ad24-580f-4a81-bdc3-6b9894aeabb2', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'In a proportion a : b :: c : d, what are the first and fourth terms (a and d) called, and what are the middle terms (b and c) called?', 'In a : b = c : d, outer terms (a, d) are Extremes and inner terms (b, c) are Means.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8a203de-4821-49da-af76-5112a72983d5', '''a'' and ''d'' are Extreme Terms (Extremes) ; ''b'' and ''c'' are Middle Terms (Means)', true, 'cb66ad24-580f-4a81-bdc3-6b9894aeabb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98158242-4c47-4a07-a993-93a03c2da6c8', 'All four are Means', false, 'cb66ad24-580f-4a81-bdc3-6b9894aeabb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b83c110-6caa-4343-8028-841b739813d9', 'All four are Extremes', false, 'cb66ad24-580f-4a81-bdc3-6b9894aeabb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54ca189d-60cd-4951-a7fe-87a06ff38148', '''a'' and ''b'' are Extremes', false, 'cb66ad24-580f-4a81-bdc3-6b9894aeabb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6d9d388-5af3-459c-91f6-00e34ac962f4', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'What is the fundamental property of four numbers in Proportion (a : b :: c : d)?', 'Cross-multiplication rule: a/b = c/d ⇔ a × d = b × c.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83532a19-0b73-4819-aa0f-7002b8bdfeb7', 'Product of Extremes = Product of Means (a × d = b × c)', true, 'f6d9d388-5af3-459c-91f6-00e34ac962f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49d7b00d-9939-4e7d-8b2e-695e40ac228c', 'Sum of Extremes = Sum of Means', false, 'f6d9d388-5af3-459c-91f6-00e34ac962f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3413582a-3590-406c-82c1-45cda226545d', 'Difference of Extremes = Difference of Means', false, 'f6d9d388-5af3-459c-91f6-00e34ac962f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b684cd1-821c-4496-8a9c-2c14091e4806', 'Extremes divided by Means = 0', false, 'f6d9d388-5af3-459c-91f6-00e34ac962f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7ba6b17-4798-4645-911a-b46020e79bc0', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'The method in which we first find the value of ONE unit and then find the value of the REQUIRED number of units is called the:', 'The Unitary Method calculates the per-unit cost/value first (by division) and scales up (by multiplication).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b68283d3-f5a7-4fb4-bf94-12bda6e0053e', 'Unitary Method', true, 'd7ba6b17-4798-4645-911a-b46020e79bc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faa84b0f-f6d5-45f0-8a0b-7aa36861b878', 'Trial and Error Method', false, 'd7ba6b17-4798-4645-911a-b46020e79bc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d291af88-8bc0-48b0-a4da-67c982013d5c', 'Substitution Method', false, 'd7ba6b17-4798-4645-911a-b46020e79bc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1f31604-577f-45bf-b85d-560c582a0321', 'Elimination Method', false, 'd7ba6b17-4798-4645-911a-b46020e79bc0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72fedf49-4da9-4ab6-b359-571562ea790d', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'If the cost of 6 cans of juice is ₹210, what is the cost of 4 cans of juice?', 'Cost of 1 can = 210 ÷ 6 = ₹35. Cost of 4 cans = 35 × 4 = ₹140.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50b025e4-1903-4b8d-8794-28cb437353d0', '₹140 (1 can = 210/6 = ₹35 ; 4 cans = 35 × 4 = ₹140)', true, '72fedf49-4da9-4ab6-b359-571562ea790d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efa88f2c-7439-476c-aa71-24c916975fb2', '₹120', false, '72fedf49-4da9-4ab6-b359-571562ea790d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e559de37-b109-4b1a-92de-14765259945f', '₹160', false, '72fedf49-4da9-4ab6-b359-571562ea790d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5be3e091-59af-4661-a3c1-361ad21337f7', '₹180', false, '72fedf49-4da9-4ab6-b359-571562ea790d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('605e2c44-6f3f-40c9-adf3-70795fc800e5', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Are the numbers 25, 30, 40, and 48 in Proportion?', '25/30 = 5/6; 40/48 = 5/6. Since ratios are equal (1200 = 1200), they are in proportion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbe6c8d0-10ea-4bd6-bd3a-1789c9eb261d', 'Yes (25/30 = 5/6 and 40/48 = 5/6 ; Product of extremes = 25 × 48 = 1200, Product of means = 30 × 40 = 1200)', true, '605e2c44-6f3f-40c9-adf3-70795fc800e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cecdb5d-9a26-4ec8-8c80-7576c4827388', 'No', false, '605e2c44-6f3f-40c9-adf3-70795fc800e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4be85368-6035-40a5-92bc-c887e03b1486', 'Only if multiplied by 2', false, '605e2c44-6f3f-40c9-adf3-70795fc800e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93273e4d-d295-47ff-8bb6-cd8c39126f2a', 'Cannot be determined', false, '605e2c44-6f3f-40c9-adf3-70795fc800e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56acf5d6-8abe-40d5-bc8e-1facb2d8e93b', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Find the ratio of 30 minutes to 1.5 hours in simplest form:', '1.5 hours = 1.5 × 60 = 90 minutes. Ratio = 30 / 90 = 1/3 = 1 : 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5826cfe7-7a84-4259-8743-72bf5a3d622a', '1 : 3 (1.5 hours = 90 minutes ; Ratio = 30/90 = 1/3)', true, '56acf5d6-8abe-40d5-bc8e-1facb2d8e93b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cccc7e86-b675-481d-b7c2-0a878190a6fd', '1 : 2', false, '56acf5d6-8abe-40d5-bc8e-1facb2d8e93b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edcc9754-e86f-463b-82f0-033b54de750c', '30 : 1.5', false, '56acf5d6-8abe-40d5-bc8e-1facb2d8e93b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67082289-10da-4b2c-a0c2-584a3065b1fb', '1 : 5', false, '56acf5d6-8abe-40d5-bc8e-1facb2d8e93b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf89ac90-f4b3-419f-a521-23055dcff86a', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Does a pure mathematical Ratio have any physical unit (like cm, kg, or rupees)?', 'Ratios compare like quantities; identical dimensional units in numerator and denominator cancel out.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2c211a5-ffb8-46a8-a28a-0b8d5b969df2', 'No, a ratio is a pure dimensionless number with NO units (units cancel out during division)', true, 'cf89ac90-f4b3-419f-a521-23055dcff86a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc74c084-6e1a-4404-9211-fc5931056b51', 'Yes, ratio has units of cm', false, 'cf89ac90-f4b3-419f-a521-23055dcff86a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a47bb96-73bc-4e0f-b3b2-f612d8cd2052', 'Yes, ratio has units of kg', false, 'cf89ac90-f4b3-419f-a521-23055dcff86a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b925c4a-ba79-46e8-ba6d-c2bbe0651603', 'Only if it compares time', false, 'cf89ac90-f4b3-419f-a521-23055dcff86a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04ac4f45-70ce-42f2-bed9-28ce58a5c1fe', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'In a year, Seema earns ₹1,50,000 and saves ₹50,000. Find the ratio of money that Seema saves to the money she SPENDS:', 'Expenditure = 1,50,000 - 50,000 = ₹1,00,000. Savings : Expenditure = 50,000 : 1,00,000 = 1 : 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('465b90b5-a1d6-49bd-887c-5ac81118d129', '1 : 2 (Spends = 1,50,000 - 50,000 = ₹1,00,000 ; Ratio = 50,000 / 1,00,000 = 1/2)', true, '04ac4f45-70ce-42f2-bed9-28ce58a5c1fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1794e850-d692-47f6-ad34-dc543061dfad', '1 : 3', false, '04ac4f45-70ce-42f2-bed9-28ce58a5c1fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('655ee1b9-d329-4e54-866e-a482cc5d7707', '2 : 1', false, '04ac4f45-70ce-42f2-bed9-28ce58a5c1fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('247d317f-2e7c-4d9e-99da-700595a37386', '1 : 4', false, '04ac4f45-70ce-42f2-bed9-28ce58a5c1fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61b91660-b4f0-469a-9adc-dce05b47aa16', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Divide ₹1,200 between Sheela and Sangeeta in the ratio of 3 : 2. How much money will Sheela and Sangeeta get respectively?', 'Sum of ratio parts = 3 + 2 = 5. Sheela = (3/5) × 1200 = ₹720; Sangeeta = (2/5) × 1200 = ₹480.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30f9b09e-a49a-4727-8c78-6424a2346f3f', 'Sheela: ₹720 ; Sangeeta: ₹480 (Total parts = 3 + 2 = 5 ; Sheela = 3/5 × 1200 = ₹720 ; Sangeeta = 2/5 × 1200 = ₹480)', true, '61b91660-b4f0-469a-9adc-dce05b47aa16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34bf8a80-f3ce-4559-8878-7325c0582838', 'Sheela: ₹600 ; Sangeeta: ₹600', false, '61b91660-b4f0-469a-9adc-dce05b47aa16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95bd079d-fa03-417c-a0ce-e4440d63a0cc', 'Sheela: ₹800 ; Sangeeta: ₹400', false, '61b91660-b4f0-469a-9adc-dce05b47aa16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3787314-3045-4a29-b786-746314dea292', 'Sheela: ₹900 ; Sangeeta: ₹300', false, '61b91660-b4f0-469a-9adc-dce05b47aa16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('465590aa-ee93-4b62-96de-991e36665ed0', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Find the missing value ''x'' in the proportion: 8 : 12 :: x : 18', 'Product of extremes = Product of means: 8 × 18 = 12 × x ⇒ 144 = 12x ⇒ x = 12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a1d2e8b-0674-4519-9178-b7e5c799c11c', 'x = 12 (8 × 18 = 12 × x ⇒ 144 = 12x ⇒ x = 144/12 = 12)', true, '465590aa-ee93-4b62-96de-991e36665ed0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52222297-1947-4256-ba26-cf8fc758f5f4', 'x = 10', false, '465590aa-ee93-4b62-96de-991e36665ed0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ef19b64-c3d0-445e-ae75-0db829041c49', 'x = 14', false, '465590aa-ee93-4b62-96de-991e36665ed0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f20986ad-e072-4ab9-bdd4-a291756fabdd', 'x = 16', false, '465590aa-ee93-4b62-96de-991e36665ed0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16e33a08-56a6-472c-9748-8958de9880a2', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'A motorbike travels 330 km in 5 litres of petrol. How much distance can it travel in 1.5 litres of petrol?', 'Mileage = 330 ÷ 5 = 66 km/litre. Distance for 1.5 L = 66 × 1.5 = 99 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3ffd1f5-1e6c-438e-a830-6570670c721e', '99 km (1 litre = 330/5 = 66 km ; 1.5 litres = 66 × 1.5 = 99 km)', true, '16e33a08-56a6-472c-9748-8958de9880a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89c171f1-f6d4-46c1-a0a6-896fad4e0b4f', '88 km', false, '16e33a08-56a6-472c-9748-8958de9880a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43499f09-d3dc-462d-9ae7-03cefe9e5cab', '110 km', false, '16e33a08-56a6-472c-9748-8958de9880a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e33cc29-60dc-4bf2-b138-bd79dd572bfe', '95 km', false, '16e33a08-56a6-472c-9748-8958de9880a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88fa9b30-32f5-449d-bdb6-2a9c70ae1b5c', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'If the cost of 7 metres of cloth is ₹1,470, find the cost of 5 metres of cloth:', 'Cost of 1 m = 1470 ÷ 7 = ₹210. Cost of 5 m = 210 × 5 = ₹1,050.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ace7caf-56da-4944-b25b-d563b08918f9', '₹1,050 (1 metre = 1470/7 = ₹210 ; 5 metres = 210 × 5 = ₹1,050)', true, '88fa9b30-32f5-449d-bdb6-2a9c70ae1b5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5feec6b0-8c2d-42a3-ae9d-131069dbaae0', '₹1,000', false, '88fa9b30-32f5-449d-bdb6-2a9c70ae1b5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('835d634e-f1ea-40b7-8fff-5a657ea0117e', '₹1,100', false, '88fa9b30-32f5-449d-bdb6-2a9c70ae1b5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e33468a8-d4e1-452a-89bf-3372919e29b4', '₹950', false, '88fa9b30-32f5-449d-bdb6-2a9c70ae1b5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94498396-e657-412d-b051-624b586ee615', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Cost of a dozen (12) pens is ₹180 and cost of 8 ball pens is ₹56. Find the ratio of the cost of a pen to the cost of a ball pen:', '1 pen = 180/12 = ₹15; 1 ball pen = 56/8 = ₹7. Ratio = 15 : 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e0dd3fc-c32e-4622-a52d-ec38324d92b7', '15 : 7 (1 pen = 180/12 = ₹15 ; 1 ball pen = 56/8 = ₹7 ; Ratio = 15/7 = 15 : 7)', true, '94498396-e657-412d-b051-624b586ee615');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('079c954b-2c20-48b9-bebb-25740d5930bf', '18 : 7', false, '94498396-e657-412d-b051-624b586ee615');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae9ca2f1-4f00-429b-a35e-fe75423bbedf', '15 : 8', false, '94498396-e657-412d-b051-624b586ee615');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c52e08a0-d8a5-48e9-8cc2-8940d1e0e48e', '7 : 15', false, '94498396-e657-412d-b051-624b586ee615');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8a6d979-ea60-4ef8-8bed-c84066e2f6d3', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'The length and breadth of a school rectangular ground are 75 m and 25 m respectively. Find the ratio of the BREADTH to the LENGTH of the ground:', 'Order matters: Breadth : Length = 25 : 75 = 1 : 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4009d7b-6a60-49b4-a4e0-b839a1feeb0f', '1 : 3 (Breadth/Length = 25/75 = 1/3)', true, 'e8a6d979-ea60-4ef8-8bed-c84066e2f6d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25d72078-e8ce-49d7-bdad-ed13bd778bdd', '3 : 1', false, 'e8a6d979-ea60-4ef8-8bed-c84066e2f6d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5971e80b-9813-4294-9de8-d1bb1c0c70b1', '1 : 2', false, 'e8a6d979-ea60-4ef8-8bed-c84066e2f6d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f651b9b-7d60-43fa-8f80-2419fe372ad0', '2 : 3', false, 'e8a6d979-ea60-4ef8-8bed-c84066e2f6d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24567776-52dd-4e9b-b587-5a8d22019017', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Anish made 42 runs in 6 overs and Anup made 63 runs in 7 overs. Who made MORE runs per over and by how much?', 'Anish rate = 42/6 = 7; Anup rate = 63/7 = 9. Anup scored 9 runs/over (+2 higher).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fce8e15a-5ce1-49da-b20b-5a8998bd3266', 'Anup made more runs per over (Anish = 42/6 = 7 runs/over ; Anup = 63/7 = 9 runs/over ; Anup is higher by 2 runs/over)', true, '24567776-52dd-4e9b-b587-5a8d22019017');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b67d884-a53f-40e1-8fdd-8fdbb2c67689', 'Anish made more runs per over', false, '24567776-52dd-4e9b-b587-5a8d22019017');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea981a2b-d4e9-4ad4-84de-d41b4a0bf2a8', 'Both made exactly the same runs per over', false, '24567776-52dd-4e9b-b587-5a8d22019017');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f40c311-a393-49cd-aa91-e432882419af', 'Anup is higher by 5 runs/over', false, '24567776-52dd-4e9b-b587-5a8d22019017');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc0d12bd-30b4-47b4-bb9c-abcc72398f8f', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Which of the two ratios is GREATER: 3 : 4 or 5 : 6?', 'Comparing fractions with common denominator 12: 9/12 < 10/12 ⇒ 5 : 6 > 3 : 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03eea817-8adb-450f-9ed1-64508e70f362', '5 : 6 is greater (3/4 = 9/12 = 0.75 ; 5/6 = 10/12 = 0.833 ⇒ 5/6 > 3/4)', true, 'fc0d12bd-30b4-47b4-bb9c-abcc72398f8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ff91ce3-d38b-4a0e-a1ea-4d858ab6ae23', '3 : 4 is greater', false, 'fc0d12bd-30b4-47b4-bb9c-abcc72398f8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f47d4452-dee6-4a47-a349-4f08a6bb6e52', 'Both ratios are equal', false, 'fc0d12bd-30b4-47b4-bb9c-abcc72398f8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c52e93cf-71c2-4e86-b4a2-bdb3325fb1ba', 'Cannot be compared', false, 'fc0d12bd-30b4-47b4-bb9c-abcc72398f8f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffedda81-6dc7-41a8-b136-12e693c015fd', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'A car covers 180 km in 4 hours. How much time will it take to cover 450 km at the same uniform speed?', 'Speed = 180 ÷ 4 = 45 km/h. Time = Distance ÷ Speed = 450 ÷ 45 = 10 hours.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b413d05-3b4e-42b2-b604-db8753a8f01c', '10 hours (Speed = 180/4 = 45 km/h ; Time = 450/45 = 10 hours)', true, 'ffedda81-6dc7-41a8-b136-12e693c015fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b03c1544-1721-4e9f-acd4-3db871a780ea', '8 hours', false, 'ffedda81-6dc7-41a8-b136-12e693c015fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e19b5f9-c22a-48bc-9430-3c644a7e4dc6', '12 hours', false, 'ffedda81-6dc7-41a8-b136-12e693c015fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59eeaa0b-4306-4628-bf72-8da29710039d', '9 hours', false, 'ffedda81-6dc7-41a8-b136-12e693c015fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3443018e-ab14-42cb-8d4c-06bd13dd0dd6', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Find two Equivalent Ratios for 4 : 6:', 'Dividing by 2 gives 2 : 3; multiplying by 2 gives 8 : 12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29f62091-d364-456d-a321-d7597160e447', '2 : 3 and 8 : 12', true, '3443018e-ab14-42cb-8d4c-06bd13dd0dd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65e98d41-cb58-434b-9ee2-4f09f5b100be', '1 : 2 and 3 : 4', false, '3443018e-ab14-42cb-8d4c-06bd13dd0dd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62746f15-5c9c-455d-a4cc-d5fc26433dd6', '6 : 4 and 12 : 8', false, '3443018e-ab14-42cb-8d4c-06bd13dd0dd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5aab52ea-6e21-45c7-930c-4d7eb01897e5', '4 : 12 and 6 : 18', false, '3443018e-ab14-42cb-8d4c-06bd13dd0dd6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef2140ee-38dd-46b9-9e01-f91cf6b326ee', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'If 4, x, 9 are in CONTINUED Proportion (4 : x :: x : 9), find the positive value of x:', 'In continued proportion, Mean Proportional x² = a × c ⇒ x² = 4 × 9 = 36 ⇒ x = 6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e19b71c6-6448-46ed-8db3-88888ba64f7f', 'x = 6 (x² = 4 × 9 = 36 ⇒ x = √36 = 6)', true, 'ef2140ee-38dd-46b9-9e01-f91cf6b326ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12bad2a6-27b7-4b1c-9b9e-45185a842688', 'x = 5', false, 'ef2140ee-38dd-46b9-9e01-f91cf6b326ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('767c2704-025b-4d57-b0ec-8b2123ef8c16', 'x = 7', false, 'ef2140ee-38dd-46b9-9e01-f91cf6b326ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('302c752d-d13b-4844-b299-9e0f1dcfb6c8', 'x = 8', false, 'ef2140ee-38dd-46b9-9e01-f91cf6b326ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d7affdc-da0f-4dc1-98ef-447c6320eef2', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Ekta earns ₹1,500 in 10 days. How much will she earn in 30 days?', 'Earnings/day = 1500/10 = ₹150. For 30 days = 150 × 30 = ₹4,500.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e1a39eb-5384-496e-95e3-f9f6697a382f', '₹4,500 (1 day = 1500/10 = ₹150 ; 30 days = 150 × 30 = ₹4,500)', true, '6d7affdc-da0f-4dc1-98ef-447c6320eef2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12deec3b-076f-4481-bb1e-97947d906d38', '₹3,000', false, '6d7affdc-da0f-4dc1-98ef-447c6320eef2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8edc22e4-cfbe-483d-99b1-657ea7399dd8', '₹5,000', false, '6d7affdc-da0f-4dc1-98ef-447c6320eef2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab3aaecd-428d-4312-a75b-4e6ba0c9a318', '₹4,000', false, '6d7affdc-da0f-4dc1-98ef-447c6320eef2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89f4f5ae-4f17-4aef-8d4f-ba692b402903', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'The weight of 72 books is 9 kg. What is the weight of 40 such books?', 'Weight of 1 book = 9/72 = 1/8 kg. Weight of 40 books = 40 × (1/8) = 5 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f24e5e13-e4cb-47b6-912c-91bdbfdf0825', '5 kg (1 book = 9/72 = 1/8 kg ; 40 books = 40 × 1/8 = 5 kg)', true, '89f4f5ae-4f17-4aef-8d4f-ba692b402903');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f82addd7-68f4-4855-ba35-5517d7db0d5a', '4 kg', false, '89f4f5ae-4f17-4aef-8d4f-ba692b402903');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd827cc4-f433-4af1-bd2e-f16cd79f6c4d', '6 kg', false, '89f4f5ae-4f17-4aef-8d4f-ba692b402903');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a34c986a-2cd2-4a6e-a6e6-083183f7d9da', '8 kg', false, '89f4f5ae-4f17-4aef-8d4f-ba692b402903');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a00fd8c-e908-4d6d-a76a-bb784f31c7e9', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'If it has rained 276 mm in the last 3 days, how many cm of rain will fall in one full week (7 days) assuming constant rainfall rate?', 'Daily rate = 276/3 = 92 mm/day. 7 days = 92 × 7 = 644 mm = 64.4 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe562091-1e90-4ab9-907b-de7e8c385dc5', '64.4 cm (1 day = 276/3 = 92 mm ; 7 days = 92 × 7 = 644 mm = 64.4 cm)', true, '2a00fd8c-e908-4d6d-a76a-bb784f31c7e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a6c3d82-048b-4ee6-83ef-0c6b5c9a13fd', '644 cm', false, '2a00fd8c-e908-4d6d-a76a-bb784f31c7e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c700648-c42c-4248-a01d-456549e2cde2', '6.44 cm', false, '2a00fd8c-e908-4d6d-a76a-bb784f31c7e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93cec56a-a172-427c-b3b4-1a40f4022b04', '27.6 cm', false, '2a00fd8c-e908-4d6d-a76a-bb784f31c7e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d93b0578-a284-4540-bb39-1994a71c59d1', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Fill in the blank to make the proportion true: 15 / 18 = ___ / 6', '18 ÷ 3 = 6; therefore 15 ÷ 3 = 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('680727e3-8126-4597-9311-d53e2567e366', '5 (15/18 = (15÷3)/(18÷3) = 5/6)', true, 'd93b0578-a284-4540-bb39-1994a71c59d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4ecb385-7279-42b1-82b3-049c5fa48f63', '6', false, 'd93b0578-a284-4540-bb39-1994a71c59d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c05c68d-7cdf-4e30-bced-ae90d3142815', '3', false, 'd93b0578-a284-4540-bb39-1994a71c59d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1c80803-9c40-42e9-a363-913f134489f9', '4', false, 'd93b0578-a284-4540-bb39-1994a71c59d1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('756b6930-adc5-4ce9-ac06-6c76f0e4c202', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0957a3e0-80fa-4d7b-8711-d963ec0181b9', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '756b6930-adc5-4ce9-ac06-6c76f0e4c202');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('099ea747-84d6-4497-9205-e8f696553526', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '756b6930-adc5-4ce9-ac06-6c76f0e4c202');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46af999a-d174-4d6b-b3d7-7864532a7cab', '(A) is true, but (R) is false.', false, '756b6930-adc5-4ce9-ac06-6c76f0e4c202');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46688bb2-504e-4c01-8899-8a89eb596062', '(A) is false, but (R) is true.', false, '756b6930-adc5-4ce9-ac06-6c76f0e4c202');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51983dc9-64a7-46cb-8c59-2466473a98e8', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Spot the IMPOSTER in the following pairs of ratios tested for PROPORTION:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6244cbf-c4ee-4d7e-8d1e-fbbf1da19081', '1 : 5 and 3 : 15 (Proportion)', false, '51983dc9-64a7-46cb-8c59-2466473a98e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1634349-f96b-4532-808e-eebddc3912f7', '2 : 9 and 18 : 81 (Proportion)', false, '51983dc9-64a7-46cb-8c59-2466473a98e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cb3a75e-65c3-4821-9742-ab52b12973db', '15 : 45 and 5 : 25 (Proportion)', true, '51983dc9-64a7-46cb-8c59-2466473a98e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97d975f6-2a7b-4314-b8db-6641a232e3e4', '4 : 12 and 9 : 27 (Proportion)', false, '51983dc9-64a7-46cb-8c59-2466473a98e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10274a9f-83ec-4fc6-8796-c8a92418631f', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'In a triangle, the angles are in the ratio 2 : 3 : 4. If the sum of interior angles of a triangle is always 180°, find the measure of the three angles:', '9 parts = 180° ⇒ 1 part = 20°. Angles are 2×20 = 40°, 3×20 = 60°, 4×20 = 80°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e98dc310-1d87-442f-a089-e0dd69c019c7', '40°, 60°, 80° (Total parts = 2 + 3 + 4 = 9 ; 1 part = 180/9 = 20° ; Angles = 2(20°)=40°, 3(20°)=60°, 4(20°)=80°)', true, '10274a9f-83ec-4fc6-8796-c8a92418631f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aa7800d-96e8-4a9c-82ef-f408242d99fd', '30°, 60°, 90°', false, '10274a9f-83ec-4fc6-8796-c8a92418631f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e6de253-2b91-4660-8490-066f68d8476f', '45°, 45°, 90°', false, '10274a9f-83ec-4fc6-8796-c8a92418631f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a292dd1-154d-4e83-86b3-bbaef3150309', '50°, 60°, 70°', false, '10274a9f-83ec-4fc6-8796-c8a92418631f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8cb57035-148f-42c6-8398-0c682ab62dca', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Match Column I (Quantities Compared) with Column II (Simplest Ratios):
(a) 500 mL to 2 Litres    -> (i) 1 : 4
(b) 3 days to 30 hours    -> (ii) 12 : 5
(c) 40 cm to 1.5 m        -> (iii) 4 : 15
(d) 55 paise to ₹1        -> (iv) 11 : 20', '500/2000 = 1:4; 72/30 = 12:5; 40/150 = 4:15; 55/100 = 11:20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9771b049-8be1-4578-bde0-af89f16f3e9a', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '8cb57035-148f-42c6-8398-0c682ab62dca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd4975c3-2107-4766-b2b1-435ce5eee7bd', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '8cb57035-148f-42c6-8398-0c682ab62dca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46a23d6a-7be4-478d-a94b-d9d6739c96c7', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '8cb57035-148f-42c6-8398-0c682ab62dca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e2d2250-d88e-4d25-b910-962a96b60dc7', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '8cb57035-148f-42c6-8398-0c682ab62dca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16bd9e96-31d5-4d17-b852-f85c4b97378f', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Read the statements regarding proportional reasoning:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25279e76-d0c8-4eb1-9d55-8324de9f15e0', 'Statements 1 and 2 only', true, '16bd9e96-31d5-4d17-b852-f85c4b97378f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d1bd1c4-e0b2-42ad-9020-1b98e0757d57', 'Statements 2 and 3 only', false, '16bd9e96-31d5-4d17-b852-f85c4b97378f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9208f40-efa0-4c0c-aa2d-7edc4d22fa41', 'Statements 1 and 3 only', false, '16bd9e96-31d5-4d17-b852-f85c4b97378f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4d249cc-27ce-4420-9f90-b9e18c845dbc', 'All Statements 1, 2, and 3', false, '16bd9e96-31d5-4d17-b852-f85c4b97378f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25707cac-2155-48bc-a0cf-714ec30a3c3a', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Present ages of a father and son are 42 years and 14 years respectively. Find the ratio of the age of father to the age of son when the son was 12 years old (2 years ago):', '2 years ago: Father = 40, Son = 12. Ratio = 40/12 = 10/3 = 10 : 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ee8ae30-aa3a-4583-84c5-7df69da30e51', '10 : 3 (2 years ago: Father = 40 years, Son = 12 years ; Ratio = 40/12 = 10/3 = 10 : 3)', true, '25707cac-2155-48bc-a0cf-714ec30a3c3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9c5cf4e-7265-4c06-b079-7ce34a54944f', '3 : 1', false, '25707cac-2155-48bc-a0cf-714ec30a3c3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75fd04c5-a21b-4b36-ab7e-2875bd53b6c4', '4 : 1', false, '25707cac-2155-48bc-a0cf-714ec30a3c3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb96cc59-7ccc-4fe7-8a02-df2bf31730f3', '7 : 2', false, '25707cac-2155-48bc-a0cf-714ec30a3c3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f02de4f3-4954-4db2-bb71-8a67be155f99', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'What is the ratio of father''s age to son''s age after 10 years (Father = 52, Son = 24)?', 'In 10 years: Father = 42 + 10 = 52; Son = 14 + 10 = 24. Ratio = 52/24 = 13/6 = 13 : 6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81205158-31dd-439d-b140-a1ed7991f754', '13 : 6 (52 / 24 = (52÷4) / (24÷4) = 13/6 = 13 : 6)', true, 'f02de4f3-4954-4db2-bb71-8a67be155f99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c658122-02cb-4ddb-9031-eb16cd7ab6b7', '14 : 7', false, 'f02de4f3-4954-4db2-bb71-8a67be155f99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a13bd48b-64b2-47e4-a323-6912d640e8d3', '12 : 5', false, 'f02de4f3-4954-4db2-bb71-8a67be155f99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e3c9855-fcad-4783-896f-0d8f911ecca3', '2 : 1', false, 'f02de4f3-4954-4db2-bb71-8a67be155f99');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a3b1313-25e4-4f8a-814f-a818a94916c5', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Two numbers are in the ratio 5 : 8. If their sum is 91, find the difference between the two numbers:', '13x = 91 ⇒ x = 7. Numbers = 35 and 56. Difference = 56 - 35 = 21.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28d16ef2-e274-4a90-94d6-a1a57e40e6f8', '21 (Total parts = 13 ; 1 part = 91/13 = 7 ; Numbers are 35 and 56 ; Difference = 56 - 35 = 21)', true, '8a3b1313-25e4-4f8a-814f-a818a94916c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffceaf1f-c422-4a0f-96f4-c07181a7de4a', '14', false, '8a3b1313-25e4-4f8a-814f-a818a94916c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef366cd8-e7f6-417c-baca-62000b27ea29', '28', false, '8a3b1313-25e4-4f8a-814f-a818a94916c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63a7be20-3e60-4f6b-addc-08924bffed6d', '18', false, '8a3b1313-25e4-4f8a-814f-a818a94916c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('162bb0ea-5a80-456f-a51d-9548b3d087b3', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'A map is drawn to a scale of 1 : 25,000,000 (1 cm on map = 250 km on ground). If two cities are 4.8 cm apart on the map, what is the actual distance between them on ground?', 'Actual distance = 4.8 cm × 250 km/cm = 1,200 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bde609a-4260-4280-834a-8fe8d1c4a411', '1,200 km (4.8 × 250 = 1,200 km)', true, '162bb0ea-5a80-456f-a51d-9548b3d087b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cf0c718-64be-420e-bdfa-3fb505b6b8f5', '1,000 km', false, '162bb0ea-5a80-456f-a51d-9548b3d087b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cc2f949-9287-400e-9e4d-dbc410b10f1a', '1,500 km', false, '162bb0ea-5a80-456f-a51d-9548b3d087b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a3b4d53-069d-44a4-90cd-6fde3420108a', '960 km', false, '162bb0ea-5a80-456f-a51d-9548b3d087b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de1a8adc-32dd-4c3d-971d-1b30c85d9a6f', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'If A : B = 2 : 3 and B : C = 4 : 5, find the compound ratio A : B : C:', 'Equalizing B: A:B = 8:12 and B:C = 12:15 ⇒ A : B : C = 8 : 12 : 15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cc6b370-c500-4221-907c-573a4e35ae43', '8 : 12 : 15 (Multiply A:B by 4 -> 8:12 ; Multiply B:C by 3 -> 12:15 ⇒ A:B:C = 8:12:15)', true, 'de1a8adc-32dd-4c3d-971d-1b30c85d9a6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1aadd9d-8be3-4267-b6f5-bfe0d6837a3a', '2 : 4 : 5', false, 'de1a8adc-32dd-4c3d-971d-1b30c85d9a6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77087637-a073-452c-b949-917ea0161973', '8 : 10 : 15', false, 'de1a8adc-32dd-4c3d-971d-1b30c85d9a6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90692702-f44c-40d8-a52b-4fac1d7987b8', '6 : 8 : 15', false, 'de1a8adc-32dd-4c3d-971d-1b30c85d9a6f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2e8e739-6c4f-43ce-a4ac-fae241c9a3ad', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'In an alloy of brass, copper and zinc are mixed in the ratio 7 : 3. How much zinc is present in 35 kg of this brass alloy?', 'Zinc weight = (3/10) × 35 = 10.5 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd89313c-9da9-4be1-a775-9d566dbc022e', '10.5 kg (Total parts = 10 ; Zinc = (3/10) × 35 = 10.5 kg)', true, 'f2e8e739-6c4f-43ce-a4ac-fae241c9a3ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91c0923e-f5ac-45f8-95f5-9243d7583f2b', '15 kg', false, 'f2e8e739-6c4f-43ce-a4ac-fae241c9a3ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c84faca-21d1-41d5-9025-83b53edf97f5', '12 kg', false, 'f2e8e739-6c4f-43ce-a4ac-fae241c9a3ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e44414d-fb7c-4447-8855-5b157ae9e84e', '9.5 kg', false, 'f2e8e739-6c4f-43ce-a4ac-fae241c9a3ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49d82b45-eaf9-4d5f-8136-19ef59fcf2fd', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Why does Ratio and Proportional reasoning form the cornerstone of all quantitative sciences (physics, chemistry stoichiometry, economic scaling, and engineering design)?', 'Proportional scaling underpins dimensional analysis, chemical molar stoichiometry, and scale-model engineering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86e5f444-a7a7-47dc-aa21-7083ad2bcabf', 'It allows scale-invariant proportional comparisons, rate scaling, recipe formulations, and predictive quantitative modeling across macroscopic and microscopic dimensions', true, '49d82b45-eaf9-4d5f-8136-19ef59fcf2fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8742c905-750b-489f-8e00-9aad9fc3277e', 'Because proportions replace all algebra', false, '49d82b45-eaf9-4d5f-8136-19ef59fcf2fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bd988c5-af6c-4dc5-a556-8e500cecd050', 'Because division is the only math operation', false, '49d82b45-eaf9-4d5f-8136-19ef59fcf2fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ba14f02-0821-41eb-b373-f9d5a5aa4f17', 'Because numbers without ratios have no value', false, '49d82b45-eaf9-4d5f-8136-19ef59fcf2fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('429b42c3-10b3-4fcb-8eb3-7eaea94f53cb', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is the standard, polite salutation used at the beginning of a formal letter written to a School Principal or Municipal Commissioner?', 'Formal correspondence requires dignified salutations: ''Respected Sir/Madam'' or ''Dear Sir/Madam''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2895a37a-cd20-4df5-932c-c295ff8edd65', 'Respected Sir / Madam (or Dear Sir / Madam)', true, '429b42c3-10b3-4fcb-8eb3-7eaea94f53cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa0e31bf-2094-42ab-ba29-cfee85298308', 'Hey buddy!', false, '429b42c3-10b3-4fcb-8eb3-7eaea94f53cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('785b5595-31f7-4985-a901-bee3acaa85b4', 'What''s up Principal!', false, '429b42c3-10b3-4fcb-8eb3-7eaea94f53cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c50e578-920b-41f8-9909-0dc4f626da25', 'Hi friend,', false, '429b42c3-10b3-4fcb-8eb3-7eaea94f53cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b7f864d-4115-429d-adca-164b133bbbaa', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is the standard complimentary close used at the end of a formal application letter to a teacher or authority?', 'Standard formal sign-offs include ''Yours obediently'' (to teachers) and ''Yours faithfully/sincerely'' (official).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd990093-b3ee-4e54-8f59-2c46d9789ab2', 'Yours faithfully / Yours obediently / Yours sincerely', true, '3b7f864d-4115-429d-adca-164b133bbbaa');
