INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbd59b99-9490-45af-ba8b-af38b1912e9f', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'In a formal school ''NOTICE'', which crucial element is always written at the very top in BOLD CAPITAL letters enclosed in a box?', 'Notice format mandates: Institution Header, ''NOTICE'' in caps, Date, Heading, Body (enclosed in a rectangular box).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41af8ff7-7b65-4520-8c9b-de8a338e1949', 'The Name of the School/Institution followed by the word ''NOTICE''', true, 'bbd59b99-9490-45af-ba8b-af38b1912e9f');
