INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9c4c949-079c-4141-89f1-971c60533cf4', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is a ''Paragraph'' in English composition?', 'A paragraph is a coherent structural unit unified around a single topical theme.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32bd76c0-9872-4806-b8c7-e3284343df85', 'A group of related sentences focused on developing a single central topic or idea', true, 'f9c4c949-079c-4141-89f1-971c60533cf4');
