INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c052452b-76d7-4190-9544-24bd8c9e54ed', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'Who was the little magical elf who helped Patrick with his homework in ''Who Did Patrick''s Homework?''?', 'The tiny elf was rescued from the cat, cajoling Patrick into doing all his own research and homework.', NOW()) ON CONFLICT DO NOTHING;
