INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5dec165-ea7c-4895-a715-71341e696289', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What was the magical waterfall in the forest that gave delicious, warm Sake to the dutiful woodcutter Taro while giving cold water to others called?', 'The waterfall magically manifested warm sake exclusively for dutiful, filial Taro.', NOW()) ON CONFLICT DO NOTHING;
