INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47e83128-19ac-4b7f-8323-a683db60b0aa', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What was the name of the American Space Shuttle that tragic heroine Kalpana Chawla flew on her STS-107 mission in 2003?', 'Kalpana Chawla tragically perished with 6 crew members aboard Columbia during atmospheric re-entry on 1 Feb 2003.', NOW()) ON CONFLICT DO NOTHING;
