INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e93507dc-ff42-462a-8e9e-3928780f1e71', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'Who became the wise Sarpanch of the village Panchayat in Munshi Premchand''s ''Fair Play'' and delivered justice without friendship bias?', 'Premchand portrays the sacred neutrality of the Panch seat: ''The voice of the Panch is the voice of God''.', NOW()) ON CONFLICT DO NOTHING;
