INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3844ae1e-bbf2-4bde-a78a-dfa73b2b07a0', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is the famous philosophical quote from ''Fair Play'' that captures the sacred responsibility of a judge?', 'Premchand''s central aphorism emphasizes that justice transcends personal enmity or friendship.', NOW()) ON CONFLICT DO NOTHING;
