INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfb6a94f-fc50-4bd9-97be-51275ee6620a', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is the figure of speech in which two contradictory words are placed together (such as ''deafening silence'', ''sweet sorrow'') called?', 'An Oxymoron juxtaposes seemingly contradictory semantic terms (e.g. bittersweet, open secret).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce4e4a47-14ef-463b-a8a5-53e17b7d160d', 'Oxymoron', true, 'cfb6a94f-fc50-4bd9-97be-51275ee6620a');
