INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f0f052b-7567-45e0-a575-3b1ced3c6066', 'Metaphor', false, 'cfb6a94f-fc50-4bd9-97be-51275ee6620a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('287d9a2b-6d40-482f-93d5-fac07fee8fd3', 'Alliteration', false, 'cfb6a94f-fc50-4bd9-97be-51275ee6620a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d4eb6ef-55b5-417c-88bb-61115dbc8211', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is the repetition of the same initial consonant sound in adjacent or closely connected words (such as ''Peter Piper picked a peck of pickled peppers'') called?', 'Alliteration is the poetic repetition of identical initial consonant phonemes in neighboring words.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d27ef717-2608-477f-938f-5b3e0724345a', 'Alliteration', true, '4d4eb6ef-55b5-417c-88bb-61115dbc8211');
