INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3af86f1d-d5a9-41db-ace0-c40674142626', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'What is the grammatical classification of the underlined subordinate clause in: ''We cannot begin the meeting *until the Principal arrives*.''?', '''Until the Principal arrives'' functions as an Adverbial Clause of Time answering ''when''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('571a6e23-2ddb-42c2-b4c3-a4d771a729ec', 'Adverb Clause of Time (modifying the main verb ''cannot begin'')', true, '3af86f1d-d5a9-41db-ace0-c40674142626');
