INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fe4a3bd-576f-4ad1-a466-d193c9d1013d', 'Adjective Clause', false, '3af86f1d-d5a9-41db-ace0-c40674142626');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec52765a-e3cd-4fde-a82c-8c01cb52acb2', 'Relative Clause', false, '3af86f1d-d5a9-41db-ace0-c40674142626');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7dfa0502-5694-4bc4-b024-bda13eeaa723', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'Which of the following demonstrates the correct use of PUNCTUATION in a complex direct speech quotation?', 'Interrupted direct quotation: comma inside first quotes, reporting attribution, comma, quotes around remainder.', NOW()) ON CONFLICT DO NOTHING;
