INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9c8d3ea-1c1e-43d2-98ea-9bb4987a9c14', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'Identify the figure of speech in: ''The child was as brave as a young lion in the face of danger.''', 'Explicit comparative syntax with ''as... as'' constitutes a Simile.', NOW()) ON CONFLICT DO NOTHING;
