INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2605dda-41a6-44bc-84db-7d5a7857c264', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'What is the structural role of ''Transitional Linking Words'' (such as ''Furthermore'', ''However'', ''Consequently'', ''In conclusion'') in advanced essay composition?', 'Discourse connectives establish rhetorical cohesion, logical progression, and semantic clarity across paragraphs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b53e7f0-4756-4e70-a5ed-48442833e2cd', 'They establish smooth logical coherence, signposting relationships between ideas and bridging sentences seamlessly', true, 'b2605dda-41a6-44bc-84db-7d5a7857c264');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39171792-f376-4348-9a5b-9da67ef092a0', 'They are decorative filler words that make essays longer', false, 'b2605dda-41a6-44bc-84db-7d5a7857c264');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65e79114-62f8-4c93-b959-e66c5c08be92', 'They are only used in mathematics', false, 'b2605dda-41a6-44bc-84db-7d5a7857c264');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e4dfc75-ec41-4313-a147-1e831388cdde', 'They replace punctuation marks', false, 'b2605dda-41a6-44bc-84db-7d5a7857c264');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da8782b1-1697-42fb-99a8-e10b5053a407', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'What grand humanistic vision unites the entire NCERT Class 6 English curriculum at its completion?', 'The curriculum culminates in cognitive and linguistic empowerment: integrating linguistic mastery with ethical empathy and critical truth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b35d6b63-ecbe-497e-badc-fcd24d286710', 'The empowerment of the young human mind through the mastery of language, critical inquiry, compassionate integrity, and lifelong love for reading and truth', true, 'da8782b1-1697-42fb-99a8-e10b5053a407');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5068058-c894-4337-bf8c-40c9fedc5037', 'The memorization of grammar rules without understanding', false, 'da8782b1-1697-42fb-99a8-e10b5053a407');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ab2c36f-c88a-44b9-885b-419d1d34cf34', 'The rejection of all creative poetry', false, 'da8782b1-1697-42fb-99a8-e10b5053a407');
