INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b94b5d3-61b0-4a13-88bf-dcacbdf6c494', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Easy', 'Why is ''International Day of Non-Violence'' observed globally on 2nd October every year by the United Nations?', 'In 2007, the UN General Assembly unanimously established 2 October (Gandhi Jayanti) as the International Day of Non-Violence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e44f49a1-b1c7-489d-b964-6ed8ff4818b1', 'To commemorate the birth anniversary of Mahatma Gandhi and spread the universal philosophy of Ahimsa (Non-violence) and peace', true, '6b94b5d3-61b0-4a13-88bf-dcacbdf6c494');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a670a1e-450f-4c43-9cf7-eb8e9e0b285e', 'To mark the end of World War II', false, '6b94b5d3-61b0-4a13-88bf-dcacbdf6c494');
