INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17279a8a-806b-4cb7-a6e0-14f9fe0b41a8', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Easy', 'How many Sustainable Development Goals (SDGs) were adopted unanimously by all 193 UN Member States in 2015 to achieve peace, prosperity, and ecological balance by 2030?', 'The UN 2030 Agenda establishes 17 integrated SDGs addressing poverty, clean water, climate action, and inequality.', NOW()) ON CONFLICT DO NOTHING;
