INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eee82c4e-807f-4690-ba27-e1a0ff1b9281', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'Who are the FIVE Permanent Members (P5) of the UN Security Council holding permanent Veto Power?', 'The P5 victorious Allied powers of WWII (US, UK, France, Russia, China) hold permanent veto rights under Article 27.', NOW()) ON CONFLICT DO NOTHING;
