INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('008008d9-9bf9-4e73-960f-9a9dbad39f99', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'What is the chief administrative officer of the United Nations called, who heads the UN Secretariat?', 'The Secretary-General is the principal diplomat and chief administrative officer of the UN, appointed for 5-year terms.', NOW()) ON CONFLICT DO NOTHING;
