INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02cfd649-8200-4bdb-9d8d-6dce61bf3a9e', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'Which specialized UN agency headquartered in Rome, Italy works to defeat global hunger, improve nutrition, and secure food security for all?', 'FAO leads international efforts to achieve global food security and sustainable agricultural modernization.', NOW()) ON CONFLICT DO NOTHING;
