INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4720b694-db90-4ac2-9ef3-dc80ae2de30c', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'What are the ''Blue Helmets'' of the United Nations officially known as?', 'UN Peacekeepers wear distinctive blue helmets, deployed under Chapter VII mandates to de-escalate armed conflicts (India is a top contributor).', NOW()) ON CONFLICT DO NOTHING;
