INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91430026-4436-43f9-a972-a3124ff14813', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'Who was the Indian child rights activist awarded the Nobel Peace Prize in 2014 for his ''Bachpan Bachao Andolan'' which rescued over 100,000 children from forced child labour and trafficking?', 'Kailash Satyarthi founded Bachpan Bachao Andolan and Global March Against Child Labour, winning the 2014 Nobel Peace Prize.', NOW()) ON CONFLICT DO NOTHING;
