INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef015d1b-4b56-4d6b-9dfc-e529f4e5ccc7', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'Where are the prestigious Nobel Prizes presented annually every year on 10th December (the Nobel Peace Prize in Oslo, Norway and other science/literature prizes in Stockholm, Sweden)?', 'As stipulated by Alfred Nobel''s 1895 will, the Peace Prize is awarded in Oslo, while Physics, Chemistry, Medicine, and Literature are awarded in Stockholm.', NOW()) ON CONFLICT DO NOTHING;
