INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78f47689-f947-4121-b0bc-362ef6ca89c0', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'What is the primary objective of the ''International Atomic Energy Agency'' (IAEA), headquartered in Vienna, Austria?', 'IAEA (''Atoms for Peace'') inspects nuclear facilities and verifies compliance with the Non-Proliferation Treaty (NPT).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('818f2971-5a33-4cec-aa86-658ca8484f26', 'Promoting safe, secure, and peaceful uses of nuclear energy while preventing the proliferation of nuclear weapons', true, '78f47689-f947-4121-b0bc-362ef6ca89c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e6e9f88-fa66-4c98-a931-f0b58b112f7e', 'Building nuclear bombs for all countries', false, '78f47689-f947-4121-b0bc-362ef6ca89c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('135b19a4-82eb-4ec6-8f5f-47bb2ec4f6d5', 'Stopping all physics research', false, '78f47689-f947-4121-b0bc-362ef6ca89c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d34d63fe-f297-4e4e-9b51-fd2c4a4a0047', 'Mining uranium in oceans', false, '78f47689-f947-4121-b0bc-362ef6ca89c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('356470eb-8fca-40d0-b673-c67c4de0c984', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'What is ''Earth Hour'' organized annually by the World Wide Fund for Nature (WWF) on the last Saturday of March?', 'Earth Hour is a grassroots climate mobilization where cities black out iconic monuments for 60 minutes.', NOW()) ON CONFLICT DO NOTHING;
