INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d186c34c-562e-46c1-bc29-aab8b8eea364', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'What is the ancient Sanskrit universal philosophy adopted by India for its G20 Presidency in 2023: ''Vasudhaiva Kutumbakam''?', 'From the Maha Upanishad, ''Vasudhaiva Kutumbakam'' affirms that all humanity and planetary life belong to a single interconnected cosmic family.', NOW()) ON CONFLICT DO NOTHING;
