INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c223bd94-96c6-41d5-9060-e9fd4dcc70d3', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Hard', 'Match Column I (International Organizations) with Column II (Primary Domains):
(a) UNICEF -> (i) Child survival, immunization, education & protection
(b) UNHCR  -> (ii) Protection and resettlement of displaced global refugees
(c) ILO    -> (iii) International labor standards & workers'' rights
(d) WMO    -> (iv) Global meteorology, weather & climate monitoring', 'UNICEF = children; UNHCR = refugees; ILO = labor standards; WMO = weather/climate.', NOW()) ON CONFLICT DO NOTHING;
