INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e1828e9-b44d-4823-9151-cda137b728f3', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Hard', 'What is the unique environmental conservation project in Africa known as the ''Great Green Wall''?', 'The Great Green Wall restores 100 million hectares of degraded Sahelian landscape through community agro-forestry.', NOW()) ON CONFLICT DO NOTHING;
