INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7adfca1f-bfa0-4ece-9578-24e63d480292', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Hard', 'What is the global initiative known as ''Mission LiFE'' (Lifestyle for Environment) launched by India at COP26 and UN in 2022?', 'Mission LiFE mobilizes Pro-Planet People (P3) to shift individual consumer behavior towards sustainable ecological practices.', NOW()) ON CONFLICT DO NOTHING;
