INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e0d449f-a667-4f71-a99b-d41915501659', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Hard', 'What ultimate planetary vision unites the United Nations Sustainable Development Goals and human civilization?', 'The UN SDGs envision a shared global blueprint balancing socio-economic equity with planetary ecological boundaries.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5dcddd5-431d-40a8-8418-865555023a81', 'Creating an equitable, peaceful, and regenerative world where human dignity, poverty eradication, economic prosperity, and ecological biosphere balance thrive in harmony', true, '4e0d449f-a667-4f71-a99b-d41915501659');
