INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1506b8ef-1576-44a7-92a5-b0e13cf471ef', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Easy', 'Where is the famous 1,600-year-old rustless Iron Pillar of King Chandra (Gupta period), which stands 7.2 metres high and weighs over 6 tonnes, located?', 'The Iron Pillar at Mehrauli in Delhi is an enduring metallurgical masterpiece that has withstood corrosion for 16 centuries.', NOW()) ON CONFLICT DO NOTHING;
