INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7bdbebc1-030b-48fc-a4ba-76931515063d', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'How did artists paint the vivid, luminous mural paintings inside the pitch-dark caves of Ajanta over 1500 years ago?', 'Ajanta fresco-secco murals used mineral pigments on clay/lime plaster, illuminated by reflective brass mirrors.', NOW()) ON CONFLICT DO NOTHING;
