INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd122fce-fd06-4aa4-b3c7-73bcfcb87917', 'They painted only during solar eclipses', false, '7bdbebc1-030b-48fc-a4ba-76931515063d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c01b3a5-fbcf-45ba-a609-87bc496b1f38', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What famous ancient Indian Sanskrit collection of animal fables with moral and political wisdom was authored by Pandit Vishnu Sharma?', 'Vishnu Sharma composed the Panchatantra (Mitra Bheda, Mitra Labha, etc.) to teach statecraft to prince pupils through animal allegories.', NOW()) ON CONFLICT DO NOTHING;
