INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e58bc31-2f49-46c2-9aa6-77609f1d2da4', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'Who was the ancient Indian physician known as the ''Father of Indian Medicine'' whose medical treatise ''Charaka Samhita'' laid the foundations of Ayurveda?', 'Charaka formulated tridosha balance (Vata, Pitta, Kapha), diagnosis, and pharmacology in the foundational ''Charaka Samhita''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f1fa790-7c5e-4ff9-bb1e-14d22c4c5793', 'Sage Charaka', true, '3e58bc31-2f49-46c2-9aa6-77609f1d2da4');
