INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51cf7543-1c42-46f1-adf6-a7543b16d512', 'Vagbhata', false, '3e58bc31-2f49-46c2-9aa6-77609f1d2da4');
