INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f8f7d06-73a7-4bce-a23c-ae03248fccec', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What scientific explanations did Aryabhata provide in his seminal treatise ''Aryabhatiya'' (c. 499 CE)?', 'Aryabhata pioneered heliocentric motion, axial planetary rotation, geometric calculation of eclipses, and trigonometry (jya/sine).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f42001f-a8c0-4b9e-ab3e-cd3495bee212', 'He explained that day and night are caused by the rotation of the Earth on its axis, provided mathematical rules for calculating solar/lunar eclipses, and calculated π as 3.1416', true, '7f8f7d06-73a7-4bce-a23c-ae03248fccec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d69b135-6237-47e2-890a-2c3dbb4f486a', 'He claimed Earth was flat and balanced on elephants', false, '7f8f7d06-73a7-4bce-a23c-ae03248fccec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cc8dabc-940d-42ef-8abe-0bcd3908639c', 'He stated the sun orbits the earth every hour', false, '7f8f7d06-73a7-4bce-a23c-ae03248fccec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('672af1a5-dca8-4a14-9f60-39e4e61d7cd0', 'He rejected all mathematics', false, '7f8f7d06-73a7-4bce-a23c-ae03248fccec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26eb9e41-e58c-4fe1-bd7c-52fad480e0e0', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What are the ''Puranas'' in classical Hindu sacred literature?', 'The 18 Mahapuranas democratized religious lore: recited aloud in temples so commoners and women could hear sacred wisdom.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8f7afe7-1e4b-4125-a625-a66c38438794', 'Eighteen major sacred Sanskrit texts containing stories of gods and goddesses (Vishnu, Shiva, Durga), cosmology, genealogies, written in simple verse accessible to all', true, '26eb9e41-e58c-4fe1-bd7c-52fad480e0e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b851319d-7549-48fb-8897-d5b17456fd9c', 'Military training manuals for war', false, '26eb9e41-e58c-4fe1-bd7c-52fad480e0e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('589150d4-8da3-4979-9b66-17b9e89dfcac', 'Books on Roman trade', false, '26eb9e41-e58c-4fe1-bd7c-52fad480e0e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99e66152-c11a-4c4d-86c1-a122339ad8ab', 'Poetry written in Greek', false, '26eb9e41-e58c-4fe1-bd7c-52fad480e0e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('510c7bd5-6f93-42c4-ba67-ca6c9cefa854', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'How did the invention and knowledge of Papermaking spread from China across the world?', 'Following the 751 CE Battle of Talas, Arab artisans learned papermaking in Samarkand/Baghdad, diffusing it to Europe.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7daab37b-7b60-456d-a0d2-50e85cac1b26', 'It reached Korea and Japan around 1400 years ago, was transmitted to Baghdad (Arab world) in 751 CE via the Silk Route, and traveled from there to Europe', true, '510c7bd5-6f93-42c4-ba67-ca6c9cefa854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('302fd1cf-8839-4fd9-8151-a9b7a187e100', 'It was carried by birds flying across oceans', false, '510c7bd5-6f93-42c4-ba67-ca6c9cefa854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99cf59ac-da0a-4194-bd7a-3a1036fc37fa', 'It was discovered independently in every country in the same year', false, '510c7bd5-6f93-42c4-ba67-ca6c9cefa854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d50e06bc-ee57-4e44-bf05-38c1817eb321', 'It remained secret in China until 1950', false, '510c7bd5-6f93-42c4-ba67-ca6c9cefa854');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5f7948f-6992-4121-800c-a5bf9a9c7a8b', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What is the famous sculpture of ''Descent of the Ganga'' (Arjuna''s Penance) carved on an immense open-air granite rock relief at:', 'The 27m × 9m open-air bas-relief at Mahabalipuram depicts Bhagiratha''s penance / Arjuna''s austerities with celestial nagas and elephants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baa46520-760c-4cf1-b8c5-e2717884da8c', 'Mahabalipuram (Mamallapuram, Tamil Nadu)', true, 'f5f7948f-6992-4121-800c-a5bf9a9c7a8b');
