INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e5f025b-d0cc-4a68-b7f2-322caf4022e0', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What structural architectural material was used to encase and protect the older Ashokan mud-brick Great Stupa at Sanchi around the 2nd century BCE?', 'Sunga and Satavahana patrons doubled Sanchi''s diameter with sandstone ashlar casing and sculpted four monumental Torana gateways.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b6cc9ac-f8fa-4e8c-8801-0a78d84b9b8f', 'A protective outer stone casing, stone harmika balcony, stone railings (vedika), and four elaborately carved Torana gateways', true, '5e5f025b-d0cc-4a68-b7f2-322caf4022e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('875d5b23-d6f9-4640-932c-699e99fc591f', 'Solid gold bricks', false, '5e5f025b-d0cc-4a68-b7f2-322caf4022e0');
