INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b4ac42d-954b-4d2d-9b5b-d2813115aa7c', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What famous Buddhist stupa in Andhra Pradesh on the Krishna River was renowned for its exquisite marble-like limestone narrative relief carvings?', 'The Maha-chaitya at Amaravati featured dynamic, crowded narrative limestone reliefs depicting the Buddha''s life under Satavahana rule.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0988dce-7cdc-4288-98bb-dec32e153c30', 'Amaravati Stupa', true, '3b4ac42d-954b-4d2d-9b5b-d2813115aa7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f649706-2c8b-4940-9e1e-538971905067', 'Sanchi Stupa', false, '3b4ac42d-954b-4d2d-9b5b-d2813115aa7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b0bfe7d-d4ad-4ec2-97f8-ede65b374363', 'Bharhut Stupa', false, '3b4ac42d-954b-4d2d-9b5b-d2813115aa7c');
