INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1802fa19-87fd-4957-aa4a-9ae30fe2995b', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'Who financed the construction of magnificent stupas, temples, and rock-cut viharas in ancient India?', 'Epigraphic donative records prove monument construction was crowdsourced across all social strata: guilds, monks, queens, and artisans.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('313fedec-ca46-4e8b-8c23-5dd771c82ec0', 'Royal kings, queens, wealthy guild merchants, ivory carvers, farmers, blacksmiths, and humble ordinary lay devotees (recorded in votive inscriptions)', true, '1802fa19-87fd-4957-aa4a-9ae30fe2995b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5242662-1c25-443d-8721-1fe2a0b72f31', 'Only Roman emperors', false, '1802fa19-87fd-4957-aa4a-9ae30fe2995b');
