INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('876e0fc2-3548-48dc-a75d-30f71d53b10a', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What is the famous Gupta-era rock-cut temple carved into the Udayagiri hill caves in Madhya Pradesh known for?', 'Udayagiri Cave 5 houses the iconic 5th-century monumental Varaha relief symbolizing geopolitical order restored by the Guptas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8324e90-085b-439c-a2cc-6a17c9469176', 'The colossal rock-cut bas-relief of Lord Vishnu as Varaha (Boar avatar) rescuing Prithvi (Earth)', true, '876e0fc2-3548-48dc-a75d-30f71d53b10a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be18c107-6bcb-422a-ac02-703b410897c9', 'The largest Buddha statue in the world', false, '876e0fc2-3548-48dc-a75d-30f71d53b10a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f773598c-e005-442e-b980-41bd674dc2d8', 'A library of paper books', false, '876e0fc2-3548-48dc-a75d-30f71d53b10a');
