INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54fd2c72-dc78-4363-a1b7-377e5b53ab14', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What ancient Indian treatise on statecraft, economic policy, military strategy, and royal administration was authored by Kautilya (Chanakya)?', 'Kautilya''s Arthashastra is the premier ancient Sanskrit compendium of political economy, fiscal taxation, and diplomatic espionage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11b78100-285b-425d-bc0c-08b48f7b81c9', 'Arthashastra', true, '54fd2c72-dc78-4363-a1b7-377e5b53ab14');
