INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d967dd17-1797-4ba5-9069-d4703d85cd06', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'Consider the architectural components of a classical Hindu Temple:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('807eb855-4130-47a8-8754-f7ba1a79e440', 'Enter through the Mandapa hall -> circumambulate clockwise along the Pradakshina path -> look up at the towering Shikhara -> gaze directly into the Garbhagriha sanctum for Darshan', true, 'd967dd17-1797-4ba5-9069-d4703d85cd06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f36f07a1-d202-4767-9cf9-750cb3390f47', 'Start in the Garbhagriha and end at the gate', false, 'd967dd17-1797-4ba5-9069-d4703d85cd06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad0cb4a2-79d3-471f-bba6-c6ddf4c06e82', 'Climb to the top of the Shikhara first', false, 'd967dd17-1797-4ba5-9069-d4703d85cd06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('382ea4b0-7eb6-4f8d-bc0c-15b7981673f6', 'Walk around the outer village', false, 'd967dd17-1797-4ba5-9069-d4703d85cd06');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eac7911d-00a8-4da8-a533-e85316be3392', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'Match Column I (Ancient Masterpieces) with Column II (Categories & Authors):
(a) Meghaduta          -> (i) Lyric Sanskrit poem of cloud messenger by Kalidasa
(b) Sushruta Samhita   -> (ii) Foundational surgical medical treatise
(c) Manimekalai        -> (iii) Tamil epic composed by poet Sattanar
(d) Panchatantra       -> (iv) Sanskrit animal fable collection by Vishnu Sharma', 'Meghaduta = Kalidasa; Sushruta = surgery; Manimekalai = Sattanar; Panchatantra = Vishnu Sharma.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba22ddb9-9def-4e53-bff5-25abd803fb52', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'eac7911d-00a8-4da8-a533-e85316be3392');
