INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0e4468a-2f1f-4583-bccb-0b27bd903379', 'Statements 2 and 3 only', false, '2110686a-8116-42f6-aedb-793c28c60e79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fccab11b-bc6c-4c5a-aa91-529c18991803', 'Statements 1 and 3 only', false, '2110686a-8116-42f6-aedb-793c28c60e79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07dcffa9-dd03-41ec-8119-cc39afa8c2d0', 'All Statements 1, 2, and 3', false, '2110686a-8116-42f6-aedb-793c28c60e79');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4933e10c-6da9-4685-9b37-4030b51e29c6', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'What is the profound thematic resolution in the Tamil epic ''Silappadikaram'' when Kannagi tears off her left breast and throws it at the city of Madurai?', 'Kannagi''s moral fury incinerates unjust Madurai, deifying her as the supreme goddess of chastity and justice (Pattini).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('479ba0fb-f8f7-4cd1-be61-e14ea221ffc5', 'Her cosmic grief and chaste moral power (Karpu) invoke the god of fire to burn corrupt Madurai to ashes, vindicating innocent truth over royal miscarriage of justice', true, '4933e10c-6da9-4685-9b37-4030b51e29c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3b83f6a-07b5-4f2b-bb9c-235104c085e4', 'She becomes the new queen of Madurai', false, '4933e10c-6da9-4685-9b37-4030b51e29c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08f99bcb-6079-416b-a136-1796f87855f3', 'She forgives the king with gold', false, '4933e10c-6da9-4685-9b37-4030b51e29c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3490fff-0624-40b4-be75-dc7fed5e838c', 'She sails away to Rome', false, '4933e10c-6da9-4685-9b37-4030b51e29c6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbf08236-ea8f-47c2-8e9d-727e81656181', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'Why was birch bark (''Bhurjapatra'') and processed palm leaves (''Talapatra'') used as the primary writing material in ancient India before the advent of paper?', 'Pothi manuscripts utilized inscribed cured palm leaves and birch folios bound with cords through perforations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be0df5fd-225e-4c5c-b60f-fffb8848764b', 'Dried inner bark of Himalayan Betula utilis (birch) and Palmyra palm leaves were cured, trimmed, and inscribed with iron styluses or ink, strung together through central binding holes', true, 'bbf08236-ea8f-47c2-8e9d-727e81656181');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('648b0adf-8e79-41b8-85bc-2bd44fbe2fdf', 'Because stone was too light to write on', false, 'bbf08236-ea8f-47c2-8e9d-727e81656181');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dadc2f9a-ed3b-4707-98f7-6d87428232cd', 'Because ancient Indians had no metal tools', false, 'bbf08236-ea8f-47c2-8e9d-727e81656181');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58e20f66-20e0-4850-aafd-7c85cac14161', 'Because trees produced pre-printed books', false, 'bbf08236-ea8f-47c2-8e9d-727e81656181');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf2cd7d7-282d-4b70-a78e-87fc513cd352', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'What dramatic story of an artist and king''s devotion is represented in the ''Padmapani Bodhisattva'' fresco painting in Ajanta Cave 1?', 'Ajanta''s Padmapani Bodhisattva is celebrated globally for its delicate shading, downward compassionate gaze, and spiritual grace.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8a0d6e2-a731-4c6c-8c01-2a819eb6465b', 'The Bodhisattva Avalokiteshvara holding a blue lotus in his hand, radiating infinite serene compassion, graceful tribhanga posture, and sublime spiritual transcendence', true, 'bf2cd7d7-282d-4b70-a78e-87fc513cd352');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b675b901-788c-47d9-ba3a-4424aa93a9b9', 'A general riding a war horse', false, 'bf2cd7d7-282d-4b70-a78e-87fc513cd352');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75aba04d-d24b-445a-851a-0cadc460e4cc', 'A trader counting gold coins', false, 'bf2cd7d7-282d-4b70-a78e-87fc513cd352');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c82d290d-b6cb-4afb-9f9f-3328e45ae12a', 'A hunter chasing deer', false, 'bf2cd7d7-282d-4b70-a78e-87fc513cd352');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fb7181d-ba48-4ea5-828f-49036adbb8ac', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'How did Aryabhata mathematically calculate the length of the solar year in the 5th century CE?', 'Aryabhata determined the sidereal solar year to fractional precision using astronomical epicyclic models.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4b8d17f-ff0d-471d-b14a-325a4f7dedd5', 'He calculated it as 365.25868 days, remarkably close to modern atomic astronomical calculations (365.25636 days)', true, '1fb7181d-ba48-4ea5-828f-49036adbb8ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('968ee3a2-7128-4562-8bea-12ce79cba627', 'He calculated it as exactly 300 days', false, '1fb7181d-ba48-4ea5-828f-49036adbb8ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdce200f-efef-4808-896e-2560e32ca0fd', 'He calculated it as 400 days', false, '1fb7181d-ba48-4ea5-828f-49036adbb8ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c963c6-2b8d-4657-9bf7-1222aa03d5bf', 'He stated that days have no fixed length', false, '1fb7181d-ba48-4ea5-828f-49036adbb8ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b035d53-58dd-43ba-8050-9c2938624337', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'What do the diverse architectural forms of Durga Temple at Aihole (with its apsidal curved chaitya-like end) demonstrate about 6th-century Deccan art?', 'Aihole''s Durga temple illustrates architectural experimentation: adapting the apsidal plan of Buddhist chaityas into a Hindu pillared ambulatory temple.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43dc3d5b-f2ef-4823-ad0a-edbacac2cf0c', 'It represents a brilliant experimental hybrid where Chalukyan stone masons melded Buddhist rock-cut apsidal plans with emerging Hindu structural temple sanctums', true, '5b035d53-58dd-43ba-8050-9c2938624337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2697acbf-c9b1-479b-b49a-ca11eae6eece', 'It was built by Roman architects', false, '5b035d53-58dd-43ba-8050-9c2938624337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6a16339-4018-4d4f-abde-890bffa16751', 'It was a replica of a Greek stadium', false, '5b035d53-58dd-43ba-8050-9c2938624337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3d41107-a93d-4227-8d8c-a5f16fd32992', 'It was carved out of sea ice', false, '5b035d53-58dd-43ba-8050-9c2938624337');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f6e5c63-fd98-4c53-9f0a-51a7b60810dd', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'What is the ancient Sanskrit treatise on dramatic arts, theatre performance, stage aesthetics, and the theory of Nine Rasas (emotions) authored by Sage Bharata?', 'Bharata Muni''s Natya Shastra formulated classical Indian dramaturgy, abhinaya (acting), and the foundational Rasa aesthetic theory.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d868918-eaec-472f-aa58-3e69e3f765e9', 'Natya Shastra', true, '0f6e5c63-fd98-4c53-9f0a-51a7b60810dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abec6027-7aa0-43e4-88ed-c67c3510e581', 'Kavyamimamsa', false, '0f6e5c63-fd98-4c53-9f0a-51a7b60810dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b05b02f-de31-4a32-8184-dc3562774cc1', 'Sahitya Darpana', false, '0f6e5c63-fd98-4c53-9f0a-51a7b60810dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89221c06-6bc9-44ec-ac11-c72ac049b1cf', 'Dhvanyaloka', false, '0f6e5c63-fd98-4c53-9f0a-51a7b60810dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76e99152-ad9a-4c71-8175-06cb0dda872e', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'What grand cultural synthesis completes the NCERT Class 6 Social Science History journey in Chapter 12?', 'The curriculum concludes celebrating ancient India''s enduring global legacy across architecture, metallurgy, epic poetry, and mathematics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a32c751c-c8f4-4042-a1ae-55312f04bd72', 'The realization that ancient Indian civilization bequeathed a glorious heritage of rustless metallurgy, soaring architectural stupas and temples, immortal epic literature, and revolutionary scientific and mathematical breakthroughs that enriched all humankind', true, '76e99152-ad9a-4c71-8175-06cb0dda872e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2070be6a-deda-46fd-81ab-6d3897831014', 'A belief that history is only about wars', false, '76e99152-ad9a-4c71-8175-06cb0dda872e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d2008a3-f0b3-4590-95a3-4a3359cbb691', 'The conclusion that ancient people knew nothing', false, '76e99152-ad9a-4c71-8175-06cb0dda872e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed9dac5b-39b2-4737-9930-636ac4f917d7', 'A civilization that left no lasting legacy', false, '76e99152-ad9a-4c71-8175-06cb0dda872e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b5b4788-334f-49ce-a77f-85bb1e078a24', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'वाक्य को बोलते या लिखते समय भावों को स्पष्ट करने तथा रुकने के लिए जिन विशेष चिह्नों का प्रयोग किया जाता है, उन्हें क्या कहते हैं?', 'भाषा में अर्थ की स्पष्टता और भाव प्रकटीकरण हेतु प्रयुक्त ठहराव के संकेत ''विराम चिह्न'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5c69caa-cc18-4f3a-b904-9fa0d572b822', 'विराम चिह्न (Punctuation Marks)', true, '9b5b4788-334f-49ce-a77f-85bb1e078a24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00522b4f-c0d2-48a6-a8fd-8ae7fbb1a9b4', 'कारक चिह्न', false, '9b5b4788-334f-49ce-a77f-85bb1e078a24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf5296dd-8b95-4d86-ad87-99d0fd86779d', 'प्रत्यय', false, '9b5b4788-334f-49ce-a77f-85bb1e078a24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab0a47dc-9955-47a1-b06e-0c9f31a76eb1', 'उपसर्ग', false, '9b5b4788-334f-49ce-a77f-85bb1e078a24');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed4ce4f9-ad06-4d2e-9985-066033f903ef', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'साधारण वाक्य के पूर्ण समाप्त होने पर अंत में कौन-सा विराम चिह्न लगाया जाता है?', 'वाक्य की पूर्ण समाप्ति पर ''पूर्णविराम'' (।) लगाया जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7d1bf89-2728-4167-b3bb-dbaa48c23403', 'पूर्णविराम (।)', true, 'ed4ce4f9-ad06-4d2e-9985-066033f903ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59fdef83-dbfa-4291-9b38-e19876645960', 'अल्पविराम (,)', false, 'ed4ce4f9-ad06-4d2e-9985-066033f903ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ceaadc8-1bc9-4d65-8791-88015d3a4ae3', 'प्रश्नवाचक चिह्न (?)', false, 'ed4ce4f9-ad06-4d2e-9985-066033f903ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9dadbf7-797d-418c-bf8a-3ef9761bd112', 'विस्मयादिबोधक चिह्न (!)', false, 'ed4ce4f9-ad06-4d2e-9985-066033f903ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('044a5b50-e381-4cda-b500-91d95d625aa6', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'वाक्य में बहुत थोड़े समय के लिए रुकने या समान पदों को अलग करने के लिए किस चिह्न का प्रयोग होता है?', 'अल्पकालिक ठहराव तथा पदों के पृथक्करण हेतु अल्पविराम (,) का प्रयोग होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85b29106-555a-4a98-9587-7b38918c675e', 'अल्पविराम (Comma - ,)', true, '044a5b50-e381-4cda-b500-91d95d625aa6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ef5d793-687e-49ba-bf73-6e256d38de34', 'पूर्णविराम (।)', false, '044a5b50-e381-4cda-b500-91d95d625aa6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad6b2349-4c37-4a6f-a10a-b49c631a6c85', 'योजक चिह्न (-)', false, '044a5b50-e381-4cda-b500-91d95d625aa6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a9b3335-20a9-4a6e-abb0-f2504bd10668', 'कोष्ठक ()', false, '044a5b50-e381-4cda-b500-91d95d625aa6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff5ce115-f910-457d-b3da-c06b18205e5c', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'हर्ष, शोक, विस्मय, भय, घृणा आदि तीव्र मनोभावों को प्रकट करने वाले शब्दों या वाक्यों के आगे कौन-सा चिह्न लगाया जाता है?', 'आश्चर्य, हर्ष, शोक आदि मनोभावों के लिए विस्मयादिबोधक चिह्न (!) प्रयुक्त होता है (जैसे: ''अरे! यह क्या हुआ?'')', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c741c697-c3d8-4211-84e0-ac211ac2f1ea', 'विस्मयादिबोधक चिह्न (!)', true, 'ff5ce115-f910-457d-b3da-c06b18205e5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f658bbb-b4bd-4215-8c27-5653183a054a', 'प्रश्नवाचक चिह्न (?)', false, 'ff5ce115-f910-457d-b3da-c06b18205e5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b49428dc-0003-409b-8742-c7f5248b8bd8', 'पूर्णविराम (।)', false, 'ff5ce115-f910-457d-b3da-c06b18205e5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfc29b73-ab7f-4cbb-b60f-32bb26b5cc08', 'अर्धविराम (;)', false, 'ff5ce115-f910-457d-b3da-c06b18205e5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cded8f0f-6f3c-47f7-8ee0-09f9383ce1e9', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'दो वर्णों (ध्वनियों) के अत्यंत निकट आने पर उनके परस्पर मेल से होने वाले विकार (परिवर्तन) को क्या कहते हैं?', 'दो समीपवर्ती ध्वनियों के मेल से उत्पन्न रूपात्मक परिवर्तन को ''संधि'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0963c41f-76f1-4a0d-bbf5-cdc889457823', 'संधि (Euphonic Combination)', true, 'cded8f0f-6f3c-47f7-8ee0-09f9383ce1e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ba48be8-c0cb-4394-b2ff-778d238f0d54', 'समास', false, 'cded8f0f-6f3c-47f7-8ee0-09f9383ce1e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('348b250a-2e2e-473c-9f93-19761ec7e62a', 'उपसर्ग', false, 'cded8f0f-6f3c-47f7-8ee0-09f9383ce1e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('502b0d91-588b-474f-8e71-0a5056406d9b', 'कारक', false, 'cded8f0f-6f3c-47f7-8ee0-09f9383ce1e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0dde094b-6c98-4c67-b200-06c3ab26814f', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'हिंदी व्याकरण में संधि के मुख्य रूप से कितने भेद होते हैं?', 'संधि के 3 मुख्य भेद हैं: स्वर संधि, व्यंजन संधि, और विसर्ग संधि।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6205d22-f00d-499a-9c4e-92f3fc39ad6f', 'तीन भेद (1. स्वर संधि, 2. व्यंजन संधि, 3. विसर्ग संधि)', true, '0dde094b-6c98-4c67-b200-06c3ab26814f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3481e24-8bca-4e33-9f43-fd6f19fc17c7', 'दो भेद', false, '0dde094b-6c98-4c67-b200-06c3ab26814f');
