INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61333c2b-de1c-4bd0-ac5c-33ddb7f92d1e', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'दो स्वरों के आपस में मिलने से जो विकार या परिवर्तन होता है (जैसे: ''विद्या + आलय = विद्यालय''), उसे क्या कहते हैं?', 'स्वर वर्ण के साथ स्वर वर्ण के मेल से होने वाला विकार ''स्वर संधि'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
