INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5bdb4ad5-2638-49a8-a5cf-0027494df059', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'स्वर संधि के मुख्य कितने भेद होते हैं?', 'स्वर संधि के 5 भेद हैं: 1. दीर्घ, 2. गुण, 3. वृद्धि, 4. यण, तथा 5. अयादि संधि।', NOW()) ON CONFLICT DO NOTHING;
