INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed066534-79de-4e9f-a64e-6aad59663038', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'किसी के कहे हुए कथन को ज्यों-का-त्यों उद्धृत करने के लिए किस चिह्न का प्रयोग किया जाता है?', 'वक्ता के मूल कथन को सुरक्षित रखने हेतु दोहरा उद्धरण चिह्न (" ") प्रयुक्त होता है।', NOW()) ON CONFLICT DO NOTHING;
