INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('505cc6d5-e04b-4a58-825b-ba3e864ab985', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'शब्दों के संक्षिप्त रूप (abbreviation) को लिखने के लिए (जैसे: ''डॉक्टर'' के लिए ''डॉ०'', ''पंडित'' के लिए ''पं०'') किस चिह्न का प्रयोग होता है?', 'संक्षिप्त रूप दर्शाने हेतु प्रयुक्त लघु शून्यवत प्रतीक ''लाघव चिह्न'' (०) कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
