INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51cb4715-30c4-45a2-bd48-9d8bb55a944f', 'विवरण चिह्न (:- )', false, '505cc6d5-e04b-4a58-825b-ba3e864ab985');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('118efc73-9e2b-4bac-add9-e0195a762c98', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'लिखते समय जब कोई शब्द या अंश छूट जाता है, तो उसे ऊपर लिखने के लिए किस चिह्न का प्रयोग किया जाता है?', 'छूटे हुए शब्द को सम्मिलित करने हेतु ''त्रुटिपूरक / हंसपद चिह्न'' (^) लगाया जाता है।', NOW()) ON CONFLICT DO NOTHING;
