INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9be1648b-0a8e-4460-9824-0d05febff7a5', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', '''देव + इंद्र = देवेंद्र'' और ''महा + ईश = महेश'' में कौन-सी स्वर संधि है?', 'अ/आ के साथ इ/ई के मेल से ''ए'' विकार उत्पन्न होना ''गुण स्वर संधि'' का नियम है।', NOW()) ON CONFLICT DO NOTHING;
