INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('658974de-b4d7-474e-966a-0a0fff214d51', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'अनेकार्थी शब्द ''कर'' के विभिन्न अर्थों का सही समूह कौन-सा है?', '''कर'' के अनेकार्थ हैं: हाथ (हस्त), टैक्स/शुल्क, सूर्य की किरण, तथा सूँड़।', NOW()) ON CONFLICT DO NOTHING;
