INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2870a20-3ed1-497d-9362-3e47ea16966a', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'अनेकार्थी शब्द ''अंबर'' के दो मुख्य अर्थ क्या हैं?', '''अंबर'' के दो प्रमुख अर्थ हैं: आकाश/नभ तथा वस्त्र/चीर (जैसे: पीतांबर = पीला वस्त्र)।', NOW()) ON CONFLICT DO NOTHING;
