INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cd55a4c-5aeb-46f0-8daa-66f163720e96', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'श्रुतिसम भिन्नार्थक शब्द ''अनल'' और ''अनिल'' के सही अर्थ क्रमशः क्या हैं?', '''अनल'' का अर्थ आग है और ''अनिल'' का अर्थ वायु/समीर है।', NOW()) ON CONFLICT DO NOTHING;
