INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47021952-dabe-42e8-aa1e-e8819e5d1c42', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'श्रुतिसम भिन्नार्थक शब्द ''कुल'' और ''कूल'' के सही अर्थ क्रमशः क्या हैं?', '''कुल'' (ह्रस्व उ) = वंश/समग्र; ''कूल'' (दीर्घ ऊ) = नदी का किनारा/तट।', NOW()) ON CONFLICT DO NOTHING;
