INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f81841b0-8a57-467a-8077-86be5a910c7d', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'पर्यायवाची शब्दों में ''बादल'' के सही पर्यायवाची शब्दों का समूह कौन-सा है?', 'जल देने वाले (द = देने वाला): जलद, वारिद, नीरद, मेघ, घन = बादल।', NOW()) ON CONFLICT DO NOTHING;
