INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c4b8835-4be1-4784-a6ed-5075d82b8bde', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'वाक्य में विराम चिह्नों का सही प्रयोग पहचानिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39d79cd8-231a-4d62-9931-472f16246781', 'सुभाष चंद्र बोस ने कहा था, "तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा!"', true, '4c4b8835-4be1-4784-a6ed-5075d82b8bde');
