INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3718ffb-2bd2-4998-9b4d-cc6b87635f16', 'सुभाष चंद्र बोस ने कहा था: तुम मुझे खून दो मैं तुम्हें आज़ादी दूँगा।', false, '4c4b8835-4be1-4784-a6ed-5075d82b8bde');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65d48659-6b3e-456d-9a58-18b1583e9c69', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db0c5562-453e-4151-9bc2-bca022e58d18', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '65d48659-6b3e-456d-9a58-18b1583e9c69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dea75b84-aa86-49ec-9f8d-5de06425f067', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '65d48659-6b3e-456d-9a58-18b1583e9c69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0b6718f-d828-407e-8835-07735e8866dd', '(A) सही है, परन्तु (R) गलत है।', false, '65d48659-6b3e-456d-9a58-18b1583e9c69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac5d9820-fecd-4aa5-aca0-22753a4551d7', '(A) गलत है, परन्तु (R) सही है।', false, '65d48659-6b3e-456d-9a58-18b1583e9c69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05526dd4-f357-408f-8827-e80c8b7feb38', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'Spot the IMPOSTER in the following group of संधि विच्छेद और उनके प्रकारों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2599eb94-4d07-4717-831a-9d1f847f52f6', 'हिम + आलय = हिमालय (दीर्घ संधि)', false, '05526dd4-f357-408f-8827-e80c8b7feb38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d406419a-8993-41ce-80a2-ccdef8bf6e7c', 'नर + ईश = नरेश (गुण संधि)', false, '05526dd4-f357-408f-8827-e80c8b7feb38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a5e990b-be7a-4a94-8c0e-48ebbeac56db', 'महा + ऐश्वर्य = महैश्वर्य (वृद्धि संधि)', false, '05526dd4-f357-408f-8827-e80c8b7feb38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38b00697-1660-464e-b48f-06bfadeb4434', 'सु + आगत = स्वागत (अयादि संधि)', true, '05526dd4-f357-408f-8827-e80c8b7feb38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3099e461-7d47-4a6f-b987-89170230f1f2', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'सुमेलित कीजिए (विराम चिह्न और उनके मानक प्रतीक):
