INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45a6a32b-e56a-41fe-81ef-dd3ad0f012b3', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '3099e461-7d47-4a6f-b987-89170230f1f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ac8e2e7-293b-40aa-88b9-4eb95b32d66d', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '3099e461-7d47-4a6f-b987-89170230f1f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('887e3a45-5ba5-4262-8d10-643a96e99498', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '3099e461-7d47-4a6f-b987-89170230f1f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd4ef471-9b6e-4876-85c7-b4d79b909526', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', '''पो + अन = पवन'' और ''पौ + अन = पावन'' में संधि नियमों का सूक्ष्म अंतर क्या है?', 'अयादि संधि नियम: ओ + अन = अव् (पवन); औ + अन = आव् (पावन)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eda487ce-80ea-46b9-b685-8e2bcf4ef1f3', '''पो'' (ओ) + अन में ''ओ'' का ''अव्'' होकर ''पवन'' बनता है ; जबकि ''पौ'' (औ) + अन में ''औ'' का ''आव्'' होकर ''पावन'' बनता है (अयादि संधि)', true, 'dd4ef471-9b6e-4876-85c7-b4d79b909526');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28ae59f5-e6b8-4f8f-b321-ee88eb90573f', 'दोनों में दीर्घ संधि है', false, 'dd4ef471-9b6e-4876-85c7-b4d79b909526');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4b1bf46-244b-4541-8418-058d2e1ecb5d', 'पवन में व्यंजन संधि है', false, 'dd4ef471-9b6e-4876-85c7-b4d79b909526');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4283eec7-bbbc-4243-b87c-f11d71206148', 'दोनों में कोई नियम नहीं है', false, 'dd4ef471-9b6e-4876-85c7-b4d79b909526');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('709637ec-3047-49d4-978f-df6a8d65b5cb', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'संधि और समास में क्या तात्विक (मूलभूत) अंतर होता है?', 'संधि = वर्णों/ध्वनियों का विकारमूलक संयोग; समास = पदों/शब्दों का विभक्तिरहित संक्षिप्तीकरण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f01a358-e4f0-4f81-b52e-a7436c30f3a0', 'संधि दो वर्णों/ध्वनियों का मेल होती है जिससे ध्वनि विकार होता है (जैसे: ''विद्या + आलय = विद्यालय'') ; जबकि समास दो या दो से अधिक सार्थक पदों/शब्दों का मेल होता है जिसमें कारक चिह्न लुप्त होते हैं (जैसे: ''राजा का पुत्र = राजपुत्र'')', true, '709637ec-3047-49d4-978f-df6a8d65b5cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cecf11f1-0745-406a-b30b-4d5c1714263e', 'संधि केवल संस्कृत में होती है', false, '709637ec-3047-49d4-978f-df6a8d65b5cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63465fc7-b3fb-479c-bd52-665697689e09', 'समास केवल दो शब्दों में होता है', false, '709637ec-3047-49d4-978f-df6a8d65b5cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7227b677-bbd2-4eb4-b16c-bd2bb1c8c775', 'दोनों में कोई अंतर नहीं है', false, '709637ec-3047-49d4-978f-df6a8d65b5cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0a3f070-67a3-4a96-b703-d61017b7ad8e', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'अनेकार्थी शब्द ''द्विज'' के विभिन्न अर्थों का सही समूह कौन-सा है?', 'द्वि (दो) + ज (जन्मा): ब्राह्मण (उपनयन से द्वितीय जन्म), पक्षी (अंडे से जन्म), दाँत (दूध के दाँत के बाद पुनर्जन्म), चंद्रमा।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be51f0c2-cc28-4da2-9ea8-e1dbb1b93912', 'ब्राह्मण, पक्षी, दाँत, और चंद्रमा (जिनका दो बार जन्म माना जाता है)', true, 'b0a3f070-67a3-4a96-b703-d61017b7ad8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f04727d-54ec-43c8-ab4b-d651cb1ecab9', 'हाथी, घोड़ा, ऊँट', false, 'b0a3f070-67a3-4a96-b703-d61017b7ad8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e2a4393-8f4e-4f0a-b129-9673d6914cbc', 'सोना, चाँदी, ताँबा', false, 'b0a3f070-67a3-4a96-b703-d61017b7ad8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82564125-44f0-43a0-9d34-2799e1aee9fc', 'पेड़, फल, फूल', false, 'b0a3f070-67a3-4a96-b703-d61017b7ad8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('330cc9c2-98d4-4ac9-8968-664ab6afded9', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'श्रुतिसम भिन्नार्थक शब्द ''अलि'' और ''अली'' के सही अर्थ क्रमशः क्या हैं?', '''अलि'' (ह्रस्व इ) = भ्रमर/भौंरा; ''अली'' (दीर्घ ई) = सखी/सहेली।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a860015f-83b5-46ef-8c2b-17eeb40ebd94', 'अलि (ह्रस्व) = भौंरा (भ्रमर) ; अली (दीर्घ) = सखी (सहेली)', true, '330cc9c2-98d4-4ac9-8968-664ab6afded9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c54c0da7-1889-4099-9743-a9ffd507979a', 'अलि = सखी ; अली = भौंरा', false, '330cc9c2-98d4-4ac9-8968-664ab6afded9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e824b7b-5dfc-477c-bae6-30747aadf448', 'दोनों का अर्थ आँख है', false, '330cc9c2-98d4-4ac9-8968-664ab6afded9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3a93edd-0071-461a-a3b1-19bc8fbad835', 'दोनों का अर्थ नदी है', false, '330cc9c2-98d4-4ac9-8968-664ab6afded9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dba384c0-8d02-4ff1-bbe9-54fb4bc0d354', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', '''पितृ + आज्ञा'' और ''मातृ + उपदेश'' का शुद्ध संधि रूप क्रमशः क्या होगा?', 'ऋ + आ = रा (पित्राज्ञा); ऋ + उ = रु (मात्रुपदेश) - यण संधि।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39330dd4-fd61-424e-b93a-3c0d5c4ab9f6', 'पित्राज्ञा और मात्रुपदेश (यण स्वर संधि : ऋ + असमान स्वर = र्)', true, 'dba384c0-8d02-4ff1-bbe9-54fb4bc0d354');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('880765f8-8058-4145-8955-f25578a1da68', 'पितराज्ञा और मातरोपदेश', false, 'dba384c0-8d02-4ff1-bbe9-54fb4bc0d354');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed07d5a6-baa5-40d2-b8a4-b8edbcfbfa06', 'पितृआज्ञा और मातृउपदेश', false, 'dba384c0-8d02-4ff1-bbe9-54fb4bc0d354');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fc84c45-7fbe-4a5f-bbb4-e6af8dce4086', 'पित्रीआज्ञा और मात्रोपदेश', false, 'dba384c0-8d02-4ff1-bbe9-54fb4bc0d354');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ecab2fe-631d-4244-99c0-50536c6f7bc3', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'वाक्यांश के लिए एक शब्द का सही सुमेल बताइए:
(क) उपकार को मानने वाला -> कृतज्ञ
(ख) उपकार को न मानने वाला -> कृतघ्न
(ग) जो गिना न जा सके -> अगणित (असंख्येय)
(घ) जो सबमें व्याप्त हो -> सर्वव्यापी
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3833473e-750b-47d2-9f69-5073d7c48f54', 'सभी (क, ख, ग, घ) पूर्णतः सत्य हैं', true, '3ecab2fe-631d-4244-99c0-50536c6f7bc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d542339-2ff6-4b74-8d93-2cb16538b671', 'केवल क और ख', false, '3ecab2fe-631d-4244-99c0-50536c6f7bc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64ecc126-d2d1-4699-b749-010f7e0aa69f', 'केवल ग और घ', false, '3ecab2fe-631d-4244-99c0-50536c6f7bc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6b7b318-450f-4ea2-8d80-3aacac8951f9', 'केवल क और घ', false, '3ecab2fe-631d-4244-99c0-50536c6f7bc3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6e8d867-f499-4421-bd04-d868d89f3297', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'योजक चिह्न (-) का प्रयोग किन-किन परिस्थितियों में अनिवार्य रूप से किया जाता है?', 'योजक चिह्न (-) द्वंद्व युग्मों, पुनरुक्ति, विलोमों तथा ''सा/सी'' सादृश्यवाचियों में प्रयुक्त होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('226daaf9-e555-4ae2-bbdb-d961beb239f8', 'द्वंद्व समास के पदों के बीच (माता-पिता), पुनरुक्त शब्दों के बीच (धीरे-धीरे), तुलनात्मक ''सा/सी/से'' से पूर्व (चाँद-सा मुखड़ा), और विलोम युग्मों के बीच (दिन-रात)', true, 'd6e8d867-f499-4421-bd04-d868d89f3297');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('651c7132-02ce-4de0-9786-4ec4d8c28498', 'केवल वाक्य के अंत में', false, 'd6e8d867-f499-4421-bd04-d868d89f3297');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9e1a444-b657-4686-9181-f2b25728274d', 'केवल प्रश्नों में', false, 'd6e8d867-f499-4421-bd04-d868d89f3297');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fdeaf02-c1e7-4e5e-abbc-d001bd6b43e2', 'केवल संज्ञा और क्रिया के बीच', false, 'd6e8d867-f499-4421-bd04-d868d89f3297');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38301caf-0353-4615-8fa0-db0bd4e0b2f7', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'हिंदी भाषा की समृद्धि में ''शब्द संपदा'' (Vocabulary Enrichment) का क्या सर्वोच्च महत्व है?', 'शब्द संपदा भाषा की सूक्ष्म अभिव्यंजना शक्ति, संप्रेषणीयता और वैचारिक प्रखरता का मूल आधार है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abf37d86-7b35-4db5-90ad-f846e2d09a48', 'सटीक, समृद्ध शब्द संपदा से विचार-अभिव्यक्ति अत्यंत सजीव, प्रभावशाली, लालित्यपूर्ण तथा अर्थ-गांभीर्य से परिपूर्ण बनती है', true, '38301caf-0353-4615-8fa0-db0bd4e0b2f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c6a78ed-1485-4429-b2a6-91ae961e85a8', 'शब्द संपदा से केवल शब्दकोश भारी होता है', false, '38301caf-0353-4615-8fa0-db0bd4e0b2f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae74c64b-323f-4d16-b19f-949be718fb39', 'ज्यादा शब्दों से भाषा कठिन हो जाती है', false, '38301caf-0353-4615-8fa0-db0bd4e0b2f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da2764cc-5cd2-4a12-87aa-c3380a84b77c', 'शब्द संपदा का कोई विशेष लाभ नहीं है', false, '38301caf-0353-4615-8fa0-db0bd4e0b2f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a09d6174-ff63-411e-b09b-9ea1325441d5', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'कक्षा 6 के संपूर्ण हिंदी व्याकरण पाठ्यक्रम का चरम उद्देश्य क्या है?', 'पाठ्यक्रम का लक्ष्य शुद्ध मानक भाषा ज्ञान, तार्किक व्याकरणिक दक्षता, और रचनात्मक अभिव्यक्ति का समग्र परिष्कार है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5654511e-bbb1-4f3f-b483-1f71acac4de4', 'छात्रों में मानक भाषा की शुद्ध वर्तनी, व्याकरणिक नियमों की गहरी समझ, समृद्ध संप्रेषण कौशल तथा रचनात्मक चिंतन का सर्वांगीण विकास करना', true, 'a09d6174-ff63-411e-b09b-9ea1325441d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e832b77-5289-429d-ba0c-7197abdf5c7b', 'केवल परीक्षा के लिए रटना', false, 'a09d6174-ff63-411e-b09b-9ea1325441d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42bc44cd-a5bf-41db-8b8b-35e1f9a494fe', 'बिना समझे नियम याद करना', false, 'a09d6174-ff63-411e-b09b-9ea1325441d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdec7291-15cf-400e-a6ca-48dc1b9d0f97', 'अन्य भाषाओं का त्याग करना', false, 'a09d6174-ff63-411e-b09b-9ea1325441d5');
